INSERT INTO "historical_schema"."document" ("doc_id", "uploaded_by", "entity_id", "entity_type", "title", "file_url", "content", "document_type", "uploaded_at", "updated_at", "deleted_at", "status") VALUES ('27e5cca1-1a27-4c1f-9f9a-1ec8027848d3', '687b57fe-865c-496a-83b3-f83690885dd1', 'db4b930d-5336-410a-946a-18dd42471248', 'CONTEXT', 'Chi tiết chiến dịch Hồ Chí Minh', null, 'Chiến dịch Hỗ Chí Minh (từ ngày 26 đến 30-4-1975) là chiến
dịch quyết chiến chiến lược của quân và dân Việt Nam trong cuộc
Tổng tiến công và nổi dậy Xuân 1975, đánh vào đầu não và lực
lượng quan trọng nhất của chính quyền và quân đội Sài Gòn, giải
phóng Sài Gòn - Gia Định, kết thúc thắng lợi cuộc kháng chiến
chống Mỹ, cứu nước.
 
Từ ngày 26-4-1975, quân ta hình thành thế bao vây Sài Gòn từ
5 hướng. 17 giờ ngày 26 tháng 4, Chiến dịch Hồ Chí Minh bắt đầu.
Từ 26 đến 28 tháng 4, ta đột phá tuyến phòng thủ vòng ngoài, đánh
chiếm nhiều mục tiêu quan trọng: Long Thành, Trảng Bom, Nhơn
Trạch, thị xã Bà Rịa...; cắt đứt hoàn toàn đường 4 từ Sài Gòn đi các
tỉnh miền Tây; chế áp, làm tê liệt các sân bay Biên Hòa, Tân Sơn
Nhất. Ngày 29 tháng 4, ta tiêu diệt các tập đoàn chủ yếu của địch ở
vòng ngoài và vùng ven, đánh chiếm các căn cứ Nước Trong, Long
Bình, thành Tuy Hạ, Đông Dù, thị xã Hậu Nghĩa...
 
Sáng 30 tháng 4, ta tổng công kích vào nội thành Sài Gòn, nhanh
chóng thọc sâu đánh chiếm các mục tiêu then chốt: sân bay Tân Sơn
Nhất, Bộ tổng tham mưu, Biệt khu Thủ đô, Tổng nha cảnh sát...,
L1 giờ 30 phút chiếm dinh Độc Lập, bắt toàn bộ nội các chính quyền
Sài Gòn, buộc tổng thống Dương Văn Minh tuyên bố đầu hàng vô
điều kiện. Cùng với đòn tiến công quân sự, nhân dân nội thành,
ngoại thành Sài Gòn nôi dậy giành chính quyền ở 107 điểm, giải
phóng thành phố Sài Gòn - Gia Định, giải phóng hoàn toàn miền
Nam Việt Nam.
 
A. NHẬT KÝ CHIẾN DỊCH HỒ CHÍ MINH
Ngày 8-4-1975
 
Bộ Chính trị và Quân ủy Trung ương quyết định thành lập Bộ chí
huy chiến dịch giải phóng Sài Gòn - Gia Định. Tư lệnh: Đại tướng
Văn Tiến Dũng, Chính ủy: Phạm Hùng, các Phó tư lệnh: Thượng
tướng Trần Văn Trà, Trung tướng Lê Đức Anh, Trung tướng Đinh
Đức Thiện. Ngày 12-4, bổ sung thêm Trung tướng Lê Trọng Tấn -
Phó tư lệnh, Trung tướng Lê Quang Hòa - Phó chính ủy.
 
Ngày 9 đến 20-4-1975
 
Chiến dịch Xuân Lộc, Bộ Quốc phòng chỉ đạo Bộ Tư lệnh Miền
mở chiến dịch tiến công thị xã Xuân Lộc, khu vực phòng thủ trọng
yếu trong tuyến phòng thủ cơ bản (Biên Hòa - Xuân Lộc - Bà Rịa -
Vũng Tàu), tiêu diệt lực lượng địch phòng giữ ở phía đông Sài Gòn,
tạo thuận lợi cho chiến dịch Hồ Chí Minh.
 
Lực lượng địch có Sư đoàn bộ binh 18 (Quân đoàn 3), l liên
đoàn biệt động quân, 1 trung đoàn thiết giáp, 9 tiểu đoàn bảo
an, được máy bay, pháo binh chi viện hỏa lực. Trong quá trình
chiến đấu được tăng viện Lữ đoàn dù 1, Trung đoàn bộ binh 8
(Sư đoàn 5), 1 liên đoàn biệt động quân, 1 trung đoàn thiết giáp.
 
Lực lượng ta tham chiến gồm Quân đoàn 4 (thiếu Sư đoàn 9),
Sư đoàn bộ binh 6 (Quân khu 7), l trung đoàn tăng thiết giáp,
1 trung đoàn pháo binh, cuối chiến dịch được tăng cường Trung
đoàn 95 (Sư đoàn bộ binh 325) và 1 đại đội xe tăng. Bộ tư lệnh Quân
đoàn 4, Khu ủy Khu 7 trực tiếp chỉ huy chiến dịch.
 
Mở màn chiến dịch (ngày 9 tháng 4), ta đồng loạt đột phá Xuân
Lộc và tiểu khu Long Khánh nhưng không thành công. Ở ngã
ba Dầu Giây, Sư đoàn 6 tập kích chiếm 5 chốt của địch làm chủ
đường 1A (đoạn Hưng Nghĩa - đèo Mẹ Bông Con). Sáng ngày 10
 

 
tháng ‹1. ta tiếp tục đột phá Xuân Lộc, chiếm sân bay, đánh Lữ đoàn
dù số I vừa đỏ quân xuống Tân Phong. Địch phải điều thêm ï liên
đoàn biệt động quân (Trung đoàn 8, Sư đoàn bộ binh 5) tăng viện
cho Xuân Lộc.
 
Theo dõi chặt chẽ cuộc chiến đấu trên hướng Xuân Lộc, nắm
chắc quá trình phát triển tiền công trên hướng khác, Bộ Quốc phòng
chỉ đạo Bộ Chỉ huy chiên dịch thay đôi cách đánh, chuyên đội hình
tiến công sang bao vây Xuân Lộc và đánh viện. Trong các ngày từ
15 đến 17 tháng 4, ta tập kích tiêu diệt nhiều sinh lực địch ở ngã ba
Dầu Giây, đánh lui các đợt phản kích của địch từ Biên Hòa đến. Bị
thiệt hại nặng, ngày 18 tháng 4, địch phải bỏ thị xã Xuân Lộc tháo
chạy. Trong chiến dịch này, ta đánh thiệt hại nặng Sư đoàn 18, Lữ
đoàn dù 1, loại khỏi vòng chiên đấu Trung đoàn 52 (Sư đoàn 18), uy
hiếp tuyến phòng thủ của địch ở Biên Hòa - Hồ Nai.
 
Ngày 11 đến 29-4-1975
 
Bộ Quốc phòng chỉ đạo và tổ chức các lực lượng gồm đội 4
(Trung đoàn đặc công nước 126), một số đội đặc công của Quân
khu 5 và Tỉnh đội Khánh Hòa đo Trung tá Mai Năng chỉ huy tiễn ra
Trường Sa. Ngày 14 tháng 4, bộ đội ta giải phóng đảo Song Tử Tây.
Từ ngày 25 đến 29 tháng 4, ta giải phóng các đảo Sơn Ca, Nam Yết,
Sinh Tôn, Trường Sa...
 
Ngày 14-4-1975
 
Bộ Chính trị quyết định chính thức hạ quyết tâm mớ chiến dịch
quyết chiến chiến lược, kết thúc chiến tranh. Trong Điện văn số 37/
TK gửi Bộ Chỉ huy chiến dịch giải phóng Sài Gòn - Gia Định, Bộ
Chính trị “Đồng ý Chiến dịch Sài Gòn - Gia Định lấy tên là Chiến
dịch Hồ Chí Minh.... chiến dịch tiến công hiệp đồng binh chủng quy
mô lớn có kết hợp với nỗi dậy của quần chúng, kết thúc chiến tranh.
Đó là chiến dịch quyết chiến chiến lược lịch sử”.
 

 
Ngày 15 đến 20-4-1975
 
Bộ Tư lệnh Chiến dịch Hồ Chí Minh giao nhiệm vụ cho các quân
đoàn và lực lượng vũ trang địa phương:
 
- Hướng tây bắc Sài Gòn: Quân đoàn 3 do Thiếu tướng Vũ Lăng
(Tư lệnh), Đại tá Đặng Vũ Hiệp (Chính ủy) chỉ huy, cùng 2 trung
đoàn (1 và 2 Gia Định), các đội đặc công - biệt động của Thành đội
Sài Gòn được pháo binh và lực lượng phòng không chiến dịch chỉ
viện hỏa lực đánh chiếm căn cứ Đồng Dù, tiêu diệt Sư đoàn 25 ngụy,
chiếm sân bay Tân Sơn Nhất, cùng Quân đoàn 1 đánh chiếm Bộ tông
tham mưu ngụy.
 
- Hướng bắc và đông bắc Sài Gòn: Quân đoàn 1 do Thiếu tướng
Nguyễn Hòa (Tư lệnh), Thiếu tướng Hoàng Minh Thi (Chính ủy) chỉ
huy, được tăng cường Trung đoàn 95 (Sư đoàn 325 Quân đoàn 2) và
1 trung đoàn phòng không đánh chiếm Bộ tổng tham mưu ngụy và
căn cứ Bộ tư lệnh các binh chủng của địch ở Gò Vấp.
 
- Hướng đông và đông nam Sài Gòn: Quân đoàn 4 do Thiếu
tướng Hoàng Cầm (Tư lệnh), Thiếu tướng Hoàng Thế Thiện (Chính
ủy) chỉ huy, được tăng cường Lữ đoàn bộ binh 52 (Quân khu 5)
và một số tiểu đoàn binh chủng tiêu diệt Sở chỉ huy Bộ tư lệnh
Quân đoàn 3 và Sư đoàn 18 ngụy ở Biên Hòa, sau đó thọc sâu vào
nội thành đánh chiếm dinh Độc Lập; Quân đoàn 2 do Thiếu tướng
Nguyễn Hữu An (Tư lệnh), Thiếu tướng Lê Linh (Chính ủy) chỉ huy
đánh chiếm Bà Rịa, các căn cứ Nước Trong, Long Bình, chặn đường
rút chạy của địch trên sông. Sau đó, tiến vào nội thành cùng Quân
đoàn 4 chiếm dinh Độc Lập,
 
- Hướng tây và tây nam Sài Gòn: Đoàn 232 do Trung tướng Lê
Đức Anh (Tư lệnh), Thiếu tướng Lê Văn Tưởng (Chính ủy) chỉ huy
cùng lực lượng vũ trang Quân khu 8 có nhiệm vụ cắt đường số 4,
đánh chiếm Biệt khu Thủ đô và Tổng nha cảnh sát ngụy.
 

 
Các đơn vị đặc công, biệt động và lực lượng vũ trang thành phó
Sài Gòn có nhiệm vụ đánh địch, giữ các cầu vào thành phố, dẫn
đường cho các binh đoàn thọc sâu đánh chiếm các mục tiêu, hỗ trợ
quân chúng nôi dậy phối hợp với đòn tiến công quân sự.
 
Ngày 23-4-1975
 
Bộ Quốc phòng ra Quyết định số 66/QP-QĐ giao Tổng cục Kỹ
thuật tiếp quản căn cứ Cam Ranh đề tô chức thành căn cứ liên hợp
bảo đảm kỹ thuật và hậu cần khu vực trực thuộc Tổng cục Kỹ thuật.
 
Ngày 24-4-1975
 
Bộ Quốc phòng ra Quyết định số 70/QP-QĐ thành lập Trung
đoàn ô tô vận tải cơ động 526 trực thuộc Cục Vận tải, Tông cục Hậu
cần. làm nhiệm vụ vận chuyên quân sự phục vụ chiến đấu.
 
Ngày 26 đến 30-4-1975 Chiến dịch Hồ Chí Minh
 
Lực lượng địch có Quân đoàn 3 (4 sư đoàn bộ binh 22, 25, 5
và 18), 3 liên đoàn biệt động quân, sư đoàn thủy quân lục chiến,
3 lữ dù, 1 lữ đoàn ky binh thiết giáp, 19 tiêu đoàn pháo, hơn
800 máy bay, 862 tàu hải quân, tàn quân các quân đoàn I, 2 và lực
lượng dự bị chiến lược, các đơn vị cảnh sát và phòng vệ dân sự
trên địa bàn Quân khu 3. Địch tổ chức phòng thủ Sài Gòn bằng
3 tuyến: Tuyến ngoài cách Sài Gòn 30 - 50km do Š5 sư đoàn, 2 lữ
đoàn đóng giữ. Tuyến ven đô (Hóc Môn, Câu Bông, Vĩnh Trạch...)
do biệt động quân và bảo an, dân vệ đóng giữ. Tuyến nội đô do lực
lượng cảnh sát, phòng vệ dân sự, các lực lượng bảo vệ căn cứ, các
lực lượng thuộc Biệt khu Thủ đô đảm nhiệm.
 
Lực lượng ta tham gia chiến dịch, bộ đội chủ lực có các quân
đoàn 1. 2, 3, 4, Đoàn 232 (tương đương quân đoàn) với 15 sư đoàn
bộ binh, 6 trung đoàn, 4 tiểu đoàn và một số đại đội đặc công, biệt
động. 3 lữ đoàn, trung đoàn và 8 tiêu đoàn pháo binh, các đơn vị
binh chủng khác, một bộ phận không quân, hải quân. Lực lượng
 
vũ trang địa phương có 2 trung đoàn và nhiều tiểu đoàn, đại đội bộ
binh, 6 trung đoàn đặc công, 1 lữ đoàn biệt động với 60 tổ, dân quân
tự vệ và nhân đân trong địa bàn chiến địch.
 
Cách đánh của ta là chia cắt chiến lược, bao vây chặn, điệt chủ
lực ở tuyến ngoài, tổ chức binh đoàn binh chủng hợp thành thọc
sâu tiến vào nội đô đánh chiếm các mục tiêu chiến lược then chết
là: Bộ tổng tham mưu ngụy, sân bay Tân Sơn Nhất, Bộ tư lệnh Biệt
khu Thủ đô, Bộ tư lệnh Cảnh sát quốc gia, dinh Độc Lập, trong đó
có đinh Độc Lập là hợp điểm chiến dịch, kết hợp với nổi dậy của
nhân dân giành chính quyền ở cơ sở. Hướng chủ yếu bắc và tây
bắc, tây bắc là chủ yếu nhất. Hướng hiểm yếu và quan trọng đông
và đông nam.
 
Sau các chiến dịch và đợt chiến đấu tạo thế (bắt đầu từ ngày 9-4
đến 26-4-1975), ta bao vây áp sát Sài Gòn trên năm hướng: Hướng
bắc là Quân đoàn 1, tây bắc là Quân đoàn 3, đông là Quân đoàn 4 và
Quân đoàn 2, tây nam là Đoàn 232, nam là chủ lực Quân khu 8, một
số đợn vị đặc công và biệt động đã đứng chân được ở ven đô bảo vệ
các cầu trên các trục đường giao thông cho quân ta tiến vào. 17 giờ
ngày 26 tháng 4, Chiến dịch Hồ Chí Minh bắt đầu.
 
Ở hướng đông và đông nam, từ ngày 26 đến 28 tháng 4, ta chọc
thủng tuyến phòng thủ vòng ngoài, đập tan sự chống cự của các
sư đoàn địch. Trên hướng khác, ta tiêu diệt các lực lượng địch
ngăn chặn, chiếm lĩnh các địa bàn quan trọng. Chiều ngày 28
tháng 4, Bộ tổng tham mưu quân đội Sài Gòn mắt hiệu lực chỉ huy.
Địch rối loạn về chiến lược. Ngày 29, ta tổng công kích trên toàn
mặt trận, tiêu diệt các lực lượng địch ngăn chặn chiếm tuyến ven đô.
Sáng 30, ta thọc sâu vào nội đô đánh chiếm các mục tiêu kế hoạch.
11 giờ 30 phút ngày 30-4-1975, quân ta chiếm và cắm cờ trên nóc
dinh Độc Lập, bắt toàn bộ nội các chính quyền Sài Gòn, buộc tông
thống Dương Văn Minh tuyên bố đầu hàng vô điều kiện. Cùng với
đòn tiến công quân sự, nhân dân nội thành, ngoại thành Sài Gòn
 
nổi dậy giành chính quyển ở 107 điểm. Nắm vững thời cơ chiến
lược, ngay 1 tháng 5, quân và dân Khu 8, Khu 9 tiên công và nôi dậy,
tiêu diệt và làm tan rã toàn bộ lực lượng còn lại của địch ở đồng bằng
sông Cửu Long, giải phóng hoàn toàn miền Nam Việt Nam.
 
Kết quả ta tiêu điệt và làm tan rã khoảng 250.000 tên địch, gồm
7 sư đoàn bộ binh, 5 lữ đoàn dù, ky binh thiết giáp, pháo binh,
4 sư đoàn không quân... thu 500 khâu pháo, trên 400 xe tăng, xe bọc
thép, 800 máy bay, 600 tàu chiến, 3.000 xe quân sự, 270.000 khâu
súng các loại; đập tan hệ thống chính quyền Sài Gòn từ trung ương
tới cơ sở, giải phóng thành phố Sài Gòn - Gia Định và các tỉnh Tân
An, Gò Công, Hậu Nghĩa, Tây Ninh, Bình Dương, Biên Hòa, Long
Khánh, Bà Rịa, Vũng Tàu... tạo điều kiện cho các Quân khu 8 và 9
giải phóng đồng bằng sông Cửu Long, các đảo ở vùng biển Tây Nam
Tỏ quốc, giai phóng hoàn toàn miễn Nam.
 
Chiến địch Hồ Chí Minh là một điển hình về hiệp đồng chặt chẽ
giữa các lực lượng, các binh chủng, quân chủng, sự kết hợp trên quy
mô lớn giữa tiền công quân sự và nỗi dậy của quân chúng; đòn quyết
chiến chiến lược táo bạo, kịp thời, chính xác, kết thúc chiến tranh.
Chiến dịch thể hiện sự chỉ đạo chỉ huy thống nhất của Bộ Chính
trị, Quân ủy Trung ương và Bộ Quốc phòng, đánh dấu bước trưởng
thành vượt bậc của nghệ thuật quân sự Việt Nam.
 
B. DIỄN BIẾN CỦA CHIẾN DỊCH HỒ CHÍ MINH
 
1. Trận Xuân Lộc - mở “cánh cửa sắt” cho cánh quân phía
đông tiến về giải phóng Sài Gòn
 
Cuối tháng 3 năm 1975, sau khi Đà Nẵng thất thủ, Mỹ ngụy vội
vã tổ chức tuyến phòng thủ mới, kéo dài từ Phan Rang qua Xuân
Lộc đến Tây Ninh, trong đó Xuân Lộc, một thị xã thuộc tỉnh Long
Khánh, cách Sài Gòn 60km về phía đông bắc là điểm trọng tâm,
nhằm ngăn chặn quân ta tiến theo đường số 1 và đường số 20 đánh
 
vào Biên Hòa và Sài Gòn. Tướng Mỹ Uây-oen nói với Nguyễn Văn
Thiệu và các tướng ngụy: “Phải giữ cho được Xuân Lộc, mắt Xuân
Lộc là mắt Sài Gòn”. Từ nhận định như vậy, địch đã tập trung một
lực lượng lớn phòng thủ.
 
Ở Xuân Lộc, địch bế trí lực lượng mạnh mà nòng cốt là Sư đoàn
I8 bộ binh, một đơn vị còn nguyên vẹn của Quân đoàn 3 ngụy.
Tuyển phòng ngự của sư đoàn này được xác định trên một chính
diện khá rộng, từ Túc Trưng qua Dầu Giây, thị xã Xuân Lộc đến ngã
ba Tân Phong.
 
Cùng với chiến dịch Tây Nguyên, chiến dịch Trị Thiên - Huế và
chiến dịch Đà Nẵng, ở miền Đông Nam Bộ, ta đã mở thêm được
một số vùng giải phóng lớn nói liền với các căn cứ giải phóng cũ,
tạo thế, tạo lực, chuẩn bị một bước quan trọng cho giải phóng Sài
Gòn - Gia Định.
 
Ngày 2 tháng 4, quán triệt tư tưởng chỉ đạo “thần tốc, táo bạo, bất
ngờ, chắc thắng... một mặt cần cơ động nhanh chóng, thần tốc, mặt
khác sử đụng ngay lực lượng hiện có để kịp thời hành động, không
chờ đợi tập trung đầy đủ lực lượng mới làm ăn” của Bộ Chính trị
và Quân ủy Trung ương, Bộ tư lệnh Miễn đã quyết định mở cuộc
tiến công giải phóng Xuân Lộc nhằm tiêu diệt sư đoàn 18 ở vòng
ngoài, phá âm mưu phòng ngự từ xa, phá thế phòng ngự củng có
Sài Gòn của địch, cắt giao thông, cô lập Sài Gòn, tạo thế có lợi để
mở đường tiến công Sài Gòn. Nhiệm vụ tiến công Xuân Lộc được
giao cho Quân đoàn 4, được phối thuộc Sư đoàn bộ binh 6, hai tiểu
đoàn xe tăng và hai tiêu đoàn bộ đội địa phương. Tham gia Đảng
ủy và Bộ tư lệnh chiến dịch gồm có các đồng chí trong Bộ tư lệnh
Quân đoàn 4, Tư lệnh, Chính ủy Quân khu 7. Đồng chí Hoàng Cầm
được giao trọng trách làm tư lệnh chiến dịch. đồng chí Bí thư khu ủy
Khu 7 làm chính ủy.
 
Địa bàn chiến dịch thuộc địa hình trung du, khá thuận lợi cho
bộ đội tập kết, triển khai lực lượng. Song do một số điểm cao
 

 
khống chế địch đang chiếm giữ như: núi Thị (cao 100 mét), điểm
cao 396 án ngữ ngã ba Dầu Giây và tây thị xã, núi Gió án ngữ phía
nam thị xã... nên việc đưa pháo vào gần bắn thăng chỉ viện cho bộ
binh của ta gặp nhiều khó khăn.
 
Ngày 3 tháng 4, tại sơ chỉ huy ở đông cầu La Ngà, Bộ tư lệnh
chiến dịch bàn phương án tiến công Xuân Lộc. Bộ tư lệnh chiến dịch
có đề ra hai phương án:
 
Phuuzng án 1: Tập trung hai sư đoàn tiêu diệt sư đoàn I§ ngụy,
giải phóng chỉ khu Xuân Lộc và từ ngã ba Dầu Giây đến núi Chứa
Chan: một sư đoàn bao vây chia cắt địch ở Gia Kiệm, Túc Trưng
tạo điều kiện diệt quân ứng cứu của địch, nắm thời cơ tiền công giải
phóng chi khu Gia Kiệm - Dầu Giây, lộ 20.
 
Phương án 2: Nêu tình huông không có lợi thì tập trung lực lượng
tiêu điệt địch ở bên ngoài, giải phóng hai chỉ khu Tân Phong và Gia
Kiệm, tiêu diệt quân viện của địch tiến tới tiến công dứt điêm Long
Khánh và tô chức đánh địch rút lui. Nhưng trước tình hình địch đang
hoang mang dao động, Bộ tư lệnh chiến dịch quyết định tiễn công
thị xã Xuân Lộc theo phương án Ì.
 
Bộ tư lệnh chiến dịch xác định: Sư đoàn 7 tiễn công trên hướng
chủ yếu từ phía đông thị xã, có nhiệm vụ đánh chiếm hậu cứ trung
đoàn 5 thiết giáp, chiến đoàn 43, sở chỉ huy sư đoàn 18 ngụy, tiêu
diệt toàn bộ quân địch ở đông thị xã; Sư đoàn 341 tiến công trên
hướng thứ yếu từ phía bắc thị xã, có nhiệm vụ đánh chiếm ty cảnh
sát, khu cố vấn Mỹ, dinh tỉnh trưởng và cùng Sư đoàn 7 phát triển
xuống phía nam; Sư đoàn 6 chia cắt ở đường 1, đoạn ngã ba Dầu
Giây, có nhiệm vụ tiêu diệt các chết địch từ ấp Hưng Lộc - đèo Mẹ
Bồng Con, đánh viện binh và đánh địch rút chạy. Quân đoàn tổ chức
bốn cụm pháo, hai cụm cao xạ chỉ viện và bảo vệ cho các hướng
chiến đấu. Sở chỉ huy chiến địch đặt ở bắc sông La Ngà.
 
Sáng ngày 9 tháng 4, trên các hướng, ta đồng loạt nô súng tiễn
=Ânø địch: Trân hướnø chủ vều. Trung đoàn 165 của Sư đoàn 7
 
được tăng cường tám xe tăng tiến đánh căn cử sư đoàn 18 ngụy, khi
đến cách cổng 300 mét bị địch chặn đánh quyết liệt, bắn hỏng ba xe
tăng, trung. đoàn phải chuyển hướng tiến công chiếm được một phần
hậu cứ chiến đoàn 52 ngụy.
 
Hướng thứ yếu, Trung đoàn 266 của Sư đoàn 341 nhanh chóng
đánh chiếm khu thông tin, khu có vấn Mỹ, khu cảnh sát, khu chợ,
khu bảo an, nhưng khi tiến vào đỉnh tỉnh trưởng thì bị địch ngăn
chặn quyết liệt, phải dừng lại bên ngoài sở chỉ huy tiểu khu,
 
Ở vòng ngoài, Trung đoàn 270 Sư đoàn 341, Trung đoàn 209
Sư đoàn 7 đánh bại hai tiểu đoàn và điệt bảy xe tăng của hai chiến
đoàn 43 và 48§ từ Tân Phong và núi Thị vào cứu viện, giải phóng
ấp Bảo Toàn, bắt 174 tên địch. Tiểu đoàn địa phương Bà .. tiễn
công địch ở suối Cát, bắt tù binh thu vũ khí và phát triển về Bảo
Toàn. Trên hướng chia cắt, Sư đoàn 6 tổ chức điệt năm chốt của địch
trên đường l từ Hưng Nghĩa đến đèo Mẹ Bồng Con, thu hai pháo
105mm, buộc chiến đoàn 52 ngụy phải bỏ Túc Trưng co về giữ ngã
ba Dầu Giây.
 
Như vậy, trong ngày đầu ta đã chiếm tuợo một nửa thị xã, toàn
bộ khu hành chính tiểu khu, đã đưa được ba tiểu đoàn vào bên trong
và thực hiện cắt đường 1 ở đoạn ngã ba Dầu Giây - đèo Mẹ Bồng
Con. Bộ tư lệnh chiến dịch đôn đốc các đơn vị tiếp tục thực hiện
quyết tâm.
 
Ngày 10 tháng 4, trên hướng chủ yếu, Sư đoàn 7 đưa dự bị là
Trung đoàn 141 cùng một tiểu đoàn phòng không đột phá từ hướng
bắc xuống cùng Trung đoàn 165 tiến đánh căn cứ sư đoàn 18, bị
địch ở hậu cứ chiến đoàn 52 và trung đoàn 5 thiết giáp phản kích
quyết liệt. Đến 11 giờ 30 phút, Trung đoàn 141 mở được cửa và đánh
chiếm chốt Bảo Vịnh A. Trung đoàn 209 tiến công vào thị xã tử phía
nam lên, đánh thiệt hại chiến đoàn 43 ngụy. Khi gặp tuyến phòng
thủ đã ngoại của địch ở nam sân bay, trung đoàn phải dừng lại củng
cố bàn đạp.
 

 
Trên hướng thứ yếu. Sư đoàn 341 đưa Trung đoàn 270 vào thị
xã cùng Trung đoàn 266 đánh địch phản kích và giữ các khu vực
đã chiêm. Trung đoàn 266 sử dụng hai tiểu đoàn 5 và 7 bốn lần tiến
công vào sân bay Cáp Rang nhưng không thành công. Các mũi khác
đánh vào trại Lê Lợi. hậu cứ chiến đoàn 43 cũng bị địch chặn lại.
Trên hướng chia cất, Trung đoàn 33 Sư đoàn 6 tiền công và làm chủ
chỉ khu Dầu Giây, đánh bại phản kích của tiểu đoàn 1 thuộc chiến
đoàn 52, một chỉ đội thiết giáp và một tiêu đoàn biệt động.
 
Ngày 11 tháng 4, ở thị xã Xuân Lộc, trên các hướng ta và địch
giảng co quyết liệt. Ở hướng chia cắt, Sư đoàn 6 tô chức tiền công
tiêu đoàn 1 của chiến đoàn 52, nhưng diệt không gọn.
 
Quyết tâm giữ Xuân Lộc, ngày 12 tháng 4, địch vội vã đô lữ
đoàn I dù từ Sài Gòn xuống ngã ba Tân Phong, các ngày sau đó bố
trí lại đội hình trong thị xã và điều lữ đoàn 3 thủy quân lục chiến,
chiến đoàn 318 biệt động đến Trảng Bom, chiến đoàn 322 biệt động
ở Bằu Cá, chiến đoàn 315 ở Bầu Hàn, điểm cao 122, trung đoàn 8
thuộc sư đoàn Š từ Lai Khê sang Bầu Cá. Như vậy, địch đã tập trung
ở khu vực này 50% lực lượng bộ binh, 60% pháo binh và hẳu hết xe
tăng, xe thiết giáp của quân đoàn 3 cùng lực lượng tổng dự bị tương
đương một sư đoàn. Không quân ở các sân bay Biên Hòa, Tân Sơn
Nhất được huy động trung bình 80 lần chiếc mỗi ngày đề chỉ viện
trực tiếp cho các mũi phản kích. Địch còn sử dụng cả bom CBU,
loại bom có sức hủy diệt lớn. thế giới cắm sử dụng để ngăn chặn ta
tiễn công.
 
Cuộc chiến đấu ở Xuân Lộc diễn ra hết sức quyết liệt. Qua ba
ngày chiến đấu, tuy ta đã chiếm được một số mục tiêu, diệt một bộ
phận sinh lực địch và giữ được một số bàn đạp quan trọng, nhưng ta
chưa diệt gọn được một tiểu đoàn nào của chúng, bộ đội bị thương
vong nhiều (Sư đoàn 7 thương vong 300, Sư đoàn 34] thương vong
1.200, sáu xe tăng bị địch bắn hỏng và cháy, hầu hết pháo 85mm và
 
57mm bi hỏng vì bom đan).
 
Xuất phát từ nhận định cơ bản: Xuân Lộc chỉ có giá trị khi được
nối với Biên Hòa, Bộ tư lệnh chiến dịch chủ trương lập thể trận mới,
cô lập và cắt rời Xuân Lộc ra khỏi Biên Hòa bằng cách đánh chiếm
ngã ba Dầu Giây, cắt đường số 1, chặn đánh địch tử Trảng Bom lên,
đánh chiếm Tân Phong, cắt đường số 2 đi Bà Rịa.
 
Thực hiện chủ trương trên, Bộ tư lệnh đã ra lệnh ngừng tiễn công
thị xã, mỗi sư đoàn chỉ để lại một tiểu đoàn kiềm chế nghỉ binh địch,
còn lại lui ra phía sau củng cố làm lực lượng cơ động. Sư đoàn 6 và
Trung đoàn 95B (vừa được trên tăng cường) tổ chức bao vây tiêu
diệt chiến đoàn 52, thực hiện chốt chặn chiến dịch, diệt quân địch từ
Biên Hòa, Trảng Bom lên phản kích. Trung đoàn 209 triển khai trên
dải ở phía bắc chỉ khu Tân Phong chặn đánh lữ đoàn I dù, không cho
chúng vượt qua cầu Gia Liên để phối hợp với trung đoàn 43 trong thị
xã. Ngày 13, các đơn vị của ta rút khỏi thị xã.
 
Trong khi ta chuyên thế trận, địch hí hửng tưởng rằng chúng đã
đây lài được cuộc tiền công của ta, tổng thống ngụy quyển Nguyễn
Văn Thiệu tuyên truyền rùm beng về “chiến thắng Xuân Lộc”, về
“khả năng chiến đấu của quân lực Việt Nam Cộng hòa đã được phục
hồi” và hy vọng chúng “còn đủ mạnh đẻ giữ vững chế độ”.
 
Rạng sáng ngày 15 tháng 4, pháo 130mm của chiến dịch bắn
đồn dập vào sân bay Biên Hòa, cùng lúc bằng năm trận tập kích,
Sư đoàn 6 và Trung đoàn 95B đã tiêu diệt chiến đoàn 52, diệt gọn
một tiểu đoàn pháo, một chỉ đoàn thiết giáp, giải phóng hoàn toàn
chỉ khu Gia Kiệm, ngã ba Dầu Giây, cắt đứt đường số ! đoạn Xuân
Lộc - Bầu Cá, đường 20 đoạn Túc Trưng - ngã ba Dầu Giây.
 
Trong hai ngày 16 và 17, sở chỉ huy tiền phương quân đoàn 3
ngụy ở Trảng Bom đốc thúc lữ đoàn 3 thiết giáp cùng chiến đoàn 8
của sư đoàn 5 với hơn 100 khẩu pháo ở các căn cứ Nước “họng,
Hốc Bà Thức, Long Bình, Đại An và 125 lần chiếc máy bay mỗi
ngày chỉ viện, phản kích hòng chiếm lại khu vực Dầu Giây. Sư
đoàn 6 và Trung đoàn 95B chặn đánh địch quyết liệt ở Hưng Nghĩa
 

 
và điểm cao 122, diệt gọn một tiểu đoàn, bắt hơn 100 tên, đây lùi
quân địch xuống Bàu Cá.
 
Cùng thời gian trên, sau khi giải phóng Nha Trang, Cam Ranh,
cánh quán duyên hải mà nòng cốt là Quân đoàn 2 đã đập tan tuyến
phòng thủ của địch ở Phan Rang, tiến vào giải phóng Phan Thiết,
Hàm Tân và đã tiền tới Rừng Lá.
 
Trước nguy cơ bị tiêu điệt và hơn nữa mắt Dâu Giây, Xuân Lộc
mắt giá trị phòng thủ, địch quyết định rút khỏi Xuân Lộc đê bảo toàn
lực lượng. Ngày 20, địch dùng pháo binh bắn vào các trận địa của
ta đê nghi binh cho cuộc rút lui. L7 giờ, trời mưa tầm tã, phát hiện
thấy quân địch đi lại nhiều, phán đoán chúng có thê rút khỏi thị xã
theo hướng đường số 2 vẻ Vạn Kiếp, Bà Rịa và Sở cao su Ông Quê
về Nước Trong hoặc Trảng Bom, Bộ tư lệnh chiến dịch lệnh cho các
đơn vị tiền công và truy kích địch. Sư đoàn 34] tiên đánh vào thị xã
rôi phát triển theo đường Sở cao su Ông Quế; Sư đoàn 7 đánh chiêm
nam Tân Phong, chặn đường số 2, Sư đoàn 6 tô chức chặn địch ở sở
cao su Ông Quế, các tiêu đoàn địa phương chốt chặn và truy kích
địch trên đường 2.
 
Do phát hiện và tổ chức tiến công, truy kích chậm, tô chức chốt
chặn không tốt, mặt khác do trời tối, mưa to nên ta chỉ diệt được một
bộ phận đi sau của địch, bắt sóng tên đại tá tỉnh trưởng Long Khánh.
Ngày 21 tháng 4, thị xã Xuân Lộc và toàn tỉnh Long Khánh được
giải phóng, chiến dịch tiến công Xuân Lộc kết thúc.
 
Kết quả, ta đã đánh thiệt hại nặng sư đoàn 18, lữ đoàn dù l, tiêu
diệt chiến đoàn 52 (sư đoàn 18), đánh thiệt hại trung đoàn 5 và lữ
đoàn 3 thiết giáp, diệt hàng nghìn tên, bắt 2.785 tên địch, thu 48 ô tô,
1.499 súng các loại, phá hủy 42 xe tăng, xe thiết giáp, 16 ô tô. Giải
phóng Xuân Lộc và toàn bộ tinh Long Khánh.
 
Quyết định tiến công Xuân Lộc là đúng và cần thiết, chiến dịch
tiễn cÂAno Xuân T âc thắnơ lơi đã đân tan “cánh cửa thép” cửa ngõ
 

 
phía đông Sài Gòn, làm rung chuyền cả hệ thống phòng thủ còn lại
của địch ở xung quanh Sài Gòn, làm suy sụp nhanh thêm tỉnh thần
chiến đấu của quân ngụy. Thắng lợi của chiến dịch đã tạo ra một
địa bàn tập kết thuận lợi cho các binh đoàn chủ lực tiến công vào
Sài Gòn từ hướng đông, một thế trận mới rất có lợi cho Chiến dịch
Hồ Chí Minh.
 
VỀ Quân đoàn 1 hành quân thần tốc, tiến công dịch trên
hướng Bắc Sài Gòn trong chiến dịch Hồ Chí Minh
 
Thực hiện quyết tâm chiến lược của trên, Thường vụ Đảng ủy
Quân đoàn 1 đã đề ra mệnh lệnh chiến đấu cho toàn quân đoàn: “Ð¡
xa, tiến sâu, đánh thắng trận đâu, thắng lợi giòn giã liên tục đến
thắng lợi hoàn toàn”, đây còn là mệnh lệnh từ trái tim của mỗi cán
bộ, chiến sĩ, động viên mọi người xốc tới, giành chiến thắng trong
từng trận đánh, tiến tới trận quyết chiến cuối cùng.
 
Ngày 29 tháng 4, thực hiện lời kêu gọi của Bộ Chính trị:
“Hãy nhanh chóng đánh thăng vào sào huyệt cuối cùng của địch
với khí thế hùng mạnh nhất, đập tan mọi sức đề kháng của địch,
kết hợp chặt chẽ giữa tiến công và nổi dậy giải phóng hoàn toàn
thành phố Sài Gòn - Gia Định”, Quân đoàn 1 có nhiệm vụ tiến
công trên hướng bắc Sài Gòn, phối hợp với các quân đoàn 2, 3, 4
và Đoàn 232 đồng loạt tiến công, phá vỡ tuyến phòng thủ vòng
ngoài của địch xung quanh Sài Gòn.
 
Hoảng sợ trước sức mạnh tiến công không có gì ngăn cản nỗi của
ta, đại tướng Cao Văn Viên, tổng tham mưu trưởng và nhiều tướng
tá ngụy bỏ chạy. Mỹ cấp tốc điều máy bay lên thẳng chở nốt 5.000
người Mỹ trong chiến dịch di tản mang tên “Người liều mạng” khỏi
miền Nam. Sáng ngày 30 tháng 4, đại sứ Mỹ Ma-tin trèo lên máy
bay trực thăng rời khỏi Sài Gòn.
 
Rạng sáng ngày 30 tháng 4, trên các hướng tiến công của Quân
đoàn l mang tên Binh đoàn Quyết thắng, các đơn vị đồng loạt
 
nổ súng tiền công đánh chiếm các mục tiêu quy định. Pháo 130mm,
Đ24, 122mm của Lữ đoàn pháo binh 45, Trung đoàn pháo binh 54
và 186 dồn đập bắn phá các mục tiêu trong khu vực Bộ tổng tham
mưu ngụy, quận ly Lái Thiêu, căn cứ Phú Lợi, Bến Cát, Lai Khê.
Đúng Š giờ sáng, trên các hướng chia cắt của Sư đoàn 312, Trung
đoàn 165 tiến công đánh chiếm Phú Lợi.
 
Cũng rạng sáng hôm đó, quá trình ta cơ động vào áp sát căn cứ,
đã bị địch dùng pháo binh từ Bến Than, Chánh Lưu, Bình Dương
bắn phá ngăn chặn. Lực lượng địch ở nam cầu Thơ Út và Phú Chánh
băn phá dữ dội vào đội hình cơ động của Trung đoàn 165, phá hỏng
của ta một khâu pháo 85mm; một số chiến sĩ bị thương. Càng gần
đến thất bại, như con thú dữ bị thương, bọn địch càng điên cuồng
chống trả. Bộ đội ta phải hứng chịu những đợt “mưa” đạn pháo địch.
 
Mặc dù có thêm những thương vong, nhưng với truyền thống
“Đoàn kết - anh dũng - chiến tháng”, đã từng lập công vang dội, cắm
lá cờ “Quyết chiến, quyết thắng” do Bác Hồ trao tặng, lên nóc hằm
tướng giặc Đờ Cát-xtơ-ri trong chiến dịch Điện Biên Phủ năm 1954,
cán bộ, chiến sĩ Sư đoàn 312 vẫn vững vàng tay súng, tin tưởng vào
thắng lợi, quyết vượt qua mọi ác liệt, hy sinh đẻ giành toàn thắng.
 
Đúng 5 giờ 5 phút ngày 30 tháng 4, Tư lệnh sư đoàn Nguyễn
Chuông lệnh cho Trung đoàn 165 nổ súng tiến công đánh chiếm căn
cử Phú Lợi. Các trận địa pháo của Quân đoàn, sư đoàn bắn phá đồn
dập vào căn cứ địch. Lợi dụng hỏa lực pháo binh đang kiềm chế
địch, Tiểu đoàn 6 nhanh chóng khắc phục sáu lớp hàng rào và hào
chống tăng, liên tiếp dùng bộc phá mở cửa, mở thông các hàng rào
bùng nhùng, cũi lợn còn lại ở phía trong. Địch dùng hai xe tăng M48
ra ngăn chặn hướng mở cửa, nhưng cũng bị hỏa lực ĐKZ của ta bắn
cháy. Đến 8 giờ, Tiểu đoàn 6 đã mở cửa xong, Trung đoàn trưởng
Trần Măng ra lệnh cho lực lượng xe tăng xuất kích phối hợp cùng
với bộ binh xung phong vào trung tâm căn cứ, tiêu diệt địch. Nhưng
do bị lạc đường, hai chiếc xe tăng bị sa lầy (trong tổng số sáu chiếc)
 
 508/731
 

 
nên đến chậm thời gian so với quy định. Nhận thấy trận đánh phát
triển chậm, Tư lệnh sư đoàn một mặt ra lệnh cho Trung đoàn 209
kiên quyết giữ vững chốt chặn đường 13 và đường 14, không cho
địch rút chạy; mặt khác đốc thúc các lực lượng công binh, xe tăng
khẩn trương chống lầy, mở đường đưa xe tăng tiến lên phía trước.
Quyết không để khó khăn trước mắt làm ảnh hưởng tới kết quả trận
đánh, các chiến sĩ xe tăng chủ động vòng về hướng đông bắc đẻ
tìm đường. Khi vượt qua ba lớp hàng rào đơn thì một chiếc bị sa hỗ
chống tăng, năm chiếc còn lại chạy đọc đường trong sân bay về phía
đông căn cứ, sau đó vòng xuống hướng nam theo cổng chính, hiệp
đồng cùng Tiểu đoàn 6 đánh từ hướng bắc xuống.
 
Trên hướng Tiểu đoàn 4, sau khi đưa lực lượng áp sát mục tiêu
đã nhanh chóng đánh chiếm cổng ra vào căn cứ (thay cho mờ cửa)
và phát triển chiến đấu vào trung tâm. Các loại hỏa lực bắn thẳng
của ta lần lượt phá tan các ụ súng, lô cốt, hầm ngầm của địch. Các
lực lượng tiến công áp đảo lên trên cả hai hướng, bọn địch trong căn
cứ không tô chức phản kích được. 10 giờ 5 phút ngày 30 tháng 4,
từ ba hướng bắc, đông và nam, phối hợp với bộ đội địa phương,
Trung đoàn 165 đồng loạt xung phong đánh chiếm các mục tiêu:
Khu bộ tư lệnh tiểu khu Phú Lợi, khu vực đại đội cảnh sát dã chiến
và khu gia binh. Đúng 10 giờ 30 phút, Trung đoàn 165 đã hoàn toàn
làm chủ căn cứ Phú Lợi; ta tiêu diệt 44 tên địch, bắt 510 tên (trong
đó có tên đại tá tiểu khu trưởng), thu một khẩu pháo I75mm “Vua
chiến trường”, hai khẩu pháo 155mm và ba khâu pháo 105mm), hai
khẩu cối 106,7mm cùng nhiều vũ khí, phương tiện chiến tranh khác
của địch.
 
Thừa thắng, đại đội 6 Tiểu đoàn 5 do tiểu đoàn trưởng Nguyễn
Văn Thức và chính trị viên Nguyễn Thanh Nhàn dẫn đầu, phối hợp
với lực lượng Tiểu đoàn 1 và Tiểu đoàn 2 địa phương Phú Lợi, phát
triển từ hướng đông nam tiến công đánh chiếm khu dinh tỉnh trưởng
Bình Dương. Tại đây, tên đại tá Nguyễn Văn Của - Tỉnh trưởng tỉnh
Bình Dương cùng thuôc ha buôc phải ra hànø. Ta tiến tue tiến eÂnơ
 

 
và làm chủ khu Phú Văn, căn cứ giang đoàn Bạch Đăng và trường sĩ
quan công binh ngụy.
 
Trong lúc trận chiến đấu tiến công các mục tiêu địch trong thị
xã Bình Dương còn điển ra quyết liệt, thì tại ấp Hòa Mỹ, xã Định
Hòa. huy ện Châu Thành, tỉnh Bình Dương (cách thị xã gần 3km về
phía bắc ¡. đại diện Tình ủy Bình Dương gồm: Sáu Phát, Bí thư tỉnh
ủy: Năm Thuận, Phó Bí thư; Một Hữu, Thường vụ tỉnh uy, Tỉnh đội
trường: Năm Châu, Tham mưu trưởng tỉnh đội đã tiền hành hội nghị
liên tịch. cùng đại diện Đảng ủy, Bộ tư lệnh Quân đoàn và Đang uy
Bộ tư lệnh Sư đoàn 312. Hội nghị thông nhất thành lập Uy ban quân
quản tỉnh Bình Dương do đồng chí Séu Phát làm Chính ủy, đồng chí
Nguyễn Chuông, Tư lệnh Sư đoàn 312 làm Chủ tịch; đồng chí Một
Hữu làm Phó Chủ tịch.
 
Sau hai ngày đêm chiến đấu liên tục, dũng cảm, cán bộ, chiến sĩ
Sư đoàn 312 đã hoàn thành xuất sắc nhiệm vụ đánh bao vây, chia cắt,
cô lập, tiến tới tiêu diệt và làm tan rã hoàn toàn sư đoàn 5 ngụy; phối
hợp chặt chẽ với các lực lượng vũ trang địa phương, đập tan một mắt
xích quan trọng trong tuyến “tử thủ” bắc Sài Gòn, diệt 279 tên địch,
bắt 7.740 tên, gọi hàng 3.500 tên; góp phần giải phóng hoàn toàn
tỉnh Bình Dương và góp phần làm nên chiến thắng chung của Quân
đoàn trong chiến dịch lịch sử này.
 
Trên hướng thọc sâu của Quân đoàn, ngay từ khi cuộc chiên
đấu của Sư đoàn 312 tiến công bao vây, tiêu diệt Sư đoàn 5 ngụy
đang diễn ra quyết liệt ở khu vực Phú Lợi, Lai Khê, Bình Dương
và trên đường 13, 14 thì trên hướng thọc sâu vào Sài Gòn, Bộ tư
lệnh Quân đoàn đã kịp thời chỉ đạo Sư đoàn 320B đây nhanh nhịp
độ tiến công, phối hợp với các cánh quân đánh chiếm các mục tiêu
chủ yếu của địch trong thành phó. Toàn bộ đội hình thọc sâu triển
khai tiến công theo hai hướng: Trung đoàn 27 do Trung đoàn trưởng
Nguyễn Huy Hiệu và Chính ủy trung đoàn Trịnh Văn Thư chỉ huy,
từ Tân Liyên qua Tân Ba, tiền đánh quận ly Lái Thiêu. Trung đoàn 48
 
do Trung đoàn trưởng Đoàn Trưng và Chính ủy Lê Xuân Yến chỉ
huy tiến theo đường Trại Hủi, Khánh Vân, Búng xuống Lát Thiêu.
 
Đến 3 giờ ngày 30 tháng 4, toàn bộ lực lượng chiến đấu của
Trung đoàn 27 đã tập két đầy đủ ở phía bắc Lái Thiêu, chuẩn bị tiến
công đánh chiếm quận ly.
 
4 giờ 15 phút sáng ngày 30 tháng 4, Trung đoàn trưởng Trung
đoàn 27 ra lệnh nỗ súng tiến công Lái Thiêu. Các trận địa pháo, cối
của trung đoàn đồng loạt bắn vào chỉ khu. Pháo bắn thẳng của xe
tăng, súng máy cao xạ 12,7mm hạ thấp nòng bắn chế áp các lô cốt
vòng ngoài, chỉ viện cho bộ binh xung phong mở cửa.
 
Sau gần hai giờ chiến đấu, Trung đoàn 27 đã hoàn toàn làm chủ
Lái Thiêu, mở toang cánh cửa phía bắc Sài Gòn. Mắt xích quan
trọng cuối cùng trong tuyến “tử thủ” bắc Sài Gòn của địch đã bị đập
tan, tạo điều kiện thuận lợi cho Trung đoàn 48 - lực lượng thọc sâu
chủ yếu của Sư đoàn 320B nhanh chóng tiến đánh Bộ tổng tham
mưu ngụy trong thành phố,
 
Ngay sau khi trận đánh Lái Thiêu kết thúc thắng lợi, Trung
đoàn 27 giao cho Tiểu đoàn 5 triển khai đội hình chốt giữ khu vực
đã chiếm, còn toàn bộ trung đoàn có sự phối hợp của Đại đội xe
tăng 3 tiếp tục phát triển chiến đấu về phía bắc cầu Bình Phước, tiến
vào đánh chiếm các mục tiêu: Khu binh chủng ngụy, quận ly Gò
Vấp và tiểu khu Gia Định. Vào lúc 6 giờ sáng ngày 30 tháng 4, Tiểu
đoàn 5 phải xử trí một tình huống bắt ngờ: Vì không biết ta đã làm
chủ Lái Thiêu, nên một đoàn xe của địch chạy từ Bình Dương về
Sài Gòn đã ngang nhiên tiến vào quận ly Lái Thiêu. Ngay lập tức,
Tiểu đoàn 5 nhanh chóng triển khai lực lượng chặn đánh. Tốp xe
địch đi đầu gồm 20 xe (trong đó có hai xe tăng) bị tiêu diệt ngay
trên đường 13 cũ vào Lái Thiêu, ta bắt và gọi hàng 250 tên địch.
Tốp xe địch phía sau gồm 13 xe (có một xe tăng và hai pháo tự
hành 175mm) vẫn liều chết vượt qua chặng đường 13 cũ đến Bình
Hòa (bắc Lái Thiêu) để ra đường 13 mới về Sài Gòn. Các chiến sĩ
 

 
đại đội 5 do đại đội trưởng Vương Văn Vinh chỉ huy đã dùng B40,
B41 và các loại hỏa lực bắn thăng nhanh chóng tiêu diệt đoàn xe,
diệt và bát 90 tên địch.
 
Kết quả chiến đấu tại Lái Thiêu: Trung đoàn 27 đã tiêu diệt
195 tên địch, bắt 350 tên, gọi hàng 1.740 tên, diệt và phá hủy 3l xe
quân sự (có ba xe tăng M48, hai pháo tự hành 175mm), thu sáu khâu
pháo 175mm và 105mm, hai xe tăng, năm xe thiết giáp, 23 xe ô tô
các loại, 1.900 khẩu súng và nhiêu phương tiện chiến tranh khác
của địch
 
Thừa thắng, các chiến sĩ Trung đoàn 27 tiếp tục phát triển chiến
đấu về phía cầu Bình Phước, tiến đánh khu bộ tư lệnh các binh
chúng ngụy.
 
8 giờ 30 phút sáng ngày 30 tháng 4, sau khi đánh chiếm cầu Vĩnh
Bình, Trung đoàn 27 nhanh chóng xốc lại đội hình, dùng tù binh dẫn
đường khẩn trương vượt qua cầu Bình Phước, tiến đánh khu binh
chủng ngụy.
 
Từ 9 giờ 30 đến 10 giờ ngày 30 tháng 4, các đơn vị lần lượt phát
triển tiến công đánh chiếm bộ tư lệnh thiết giáp, căn cứ 60, bộ tư
lệnh lục quân công xưởng, căn cứ pháo binh, tông kho quân nhu, căn
cứ 31 và tông y viện cộng hòa.
 
Trận đánh chiếm bộ tư lệnh thiết giáp - lực lượng mạnh nhất
trong khu bộ tư lệnh các binh chủng quân ngụy đã diễn ra rất quyết
liệt Địch ở đây đã bố trí trận địa phòng ngự dày đặc, nhiều tầng,
nhiều lớp bằng tắt cả các loại xe tăng, thiết giáp hiện đại nhất nhằm
ngăn chặn ta tiến công. Tại khu vực cổng chính bộ tư lệnh thiết
giáp, hàng chục xe tăng địch tập trung hỏa lực bắn xôi xả vào mũi
đi đầu của Trung đoàn 27. Không chùn bước trước hỏa lực của
địch, cán bộ, chiến sĩ Trung đoàn 27 vẫn kiên quyết xông lên đánh
chiếm căn cứ địch. Những chiếc xe tăng ta dẫn bộ binh tiến lên đánh
 
thẳng vào đôi hình xe tăng của chúng. Trước sức tiến công táo bạo
 

 
và dũng mãnh của ta, toàn bộ sĩ quan, binh lính địch chiếm giữ các
khu binh chủng ngụy và quận ly Gò Vắp buộc phải ra hàng, trong đó
có tên chuẩn tướng Phạm Bá Thanh - tông chỉ huy y viện cộng hòa
và trung tâm tiếp huyết quân đội ngụy, đại tá Ngọc - chỉ huy khu kho
quân nhu và trung tá Chiến - chỉ huy phó căn cứ 60.
 
Lúc 10 giờ 30 phút, thừa thắng, Trung đoàn 27 tiếp tục phát
triển tiến công đánh chiếm khu vực lục quân công xưởng và quận
ly Gò Vấp. Toàn bộ quân địch ở đây không dám chống cự, kéo
cờ trắng ra hàng (trong đó có tên chuẩn tướng Huỳnh Thu Toàn
- giám đốc điều hành lục quân công xưởng). Ta tịch thu nguyên
vẹn trung tâm công nghiệp quân sự sửa chữa xe tăng, súng pháo,
xe quân sự và trung tâm truyền tin điện tử lớn nhất của quân đội
ngụy ở miền Nam. Sau đó, một bộ phận của Tiểu đoàn 6 đi trên bảy
xe vận tải do tiểu đoàn trưởng Lê Thế Dũng phát triển vào đánh
dinh Độc Lập, bốn xe vận tải do Tiểu đoàn phó Liên phát triển
đánh sang Bộ tổng tham mưu ngụy. Đến đây, hướng tiến công của
Trung đoàn 27 đã hoàn thành xuất sắc nhiệm vụ được giao.
 
Trong lúc đó, Trung đoàn 48 từ bắc Khánh Vân tăng tốc độ hành
tiến, vượt qua Lái Thiêu, qua cầu Vĩnh Bình rồi tiến vào Sài Gòn
đánh chiếm Bộ tổng tham mưu quân đội Việt Nam cộng hòa.
 
Càng tiến sâu vào phía trung tâm thành phố, lực lượng địch
phòng thủ càng dày đặc. Khi có lực lượng thọc sâu, Trung đoàn 48
phát triển đến khu vực ấp Mai Liên (bắc cầu Bình Triệu) lại bị xe
tăng và bộ binh địch ngăn chặn quyết liệt. Tiểu đoàn trưởng Tiểu
đoàn 2 Thiều Quang Nông lệnh cho đại đội 6 tiến công địch ở ấp
Mai Liên, Đại đội 8 triển khai trận địa cối ngay trên mặt đường bắn
chặn địch ở cầu Ông Đen, không cho chúng ra ứng cứu. Đại đội 5
phối hợp với lực lượng xe tăng tiến đánh cầu Bình Triệu. Nếu cầu
hỏng, bộ đội sẽ vượt sông.
 
Trong khi Đại đội 6 đánh ấp Mai Liên, Tiểu đoàn 3 vận động tiến
công trong hành tiến cắt đường số 1 (đoạn giữa Thủ Đức - Bình Lợi),
 

 
thì đội hinh thọc sâu của Trung đoàn 48 nhanh chóng phát triển tiến
công qua cầu Ông Đen, đánh thăng vào trận địa địch phòng ngự ở
âp Bình Triệu. Xe tăng ta vừa tiến công ào ạt, quân ngụy đã phải vội
vã tăng cường thêm bàng chục xe tăng thiết giáp chốt chặn ngã tư
xa lộ Đại Hàn và lập tuyến co cụm, phòng thủ dày đặc từ nam cầu
Ông Đen đến bắc cầu Bình Triệu nhằm ngăn chặn ta qua cầu. Trung
đoàn trưởng Đoàn Trưng lệnh cho các đơn vị phải kiên quyết đánh
bại âm mưu co cụm của địch, đánh chiếm bằng được cầu Bình Triệu.
Mũi tiền công của Tiêu đoàn 2 sau khi vượt qua ngã tư đường số Ì
và đường 13, vòng bên phải theo đường số 1 đánh thốc vào cụm
quân địch phòng ngự ở phía bắc cầu Bình Triệu. Trận chiến đấu diễn
ra hết sức quyết liệt. Bộ binh, xe tăng địch dựa vào hệ thống lô cốt
bê tông. bao cát và hỏa lực xe tăng bắn dữ đội vào đội hình ta.
 
Quyết không để bọn địch làm chậm tốc độ thọc sâu vào Sài Gòn,
Trung đoàn 48 quyết định sử dụng lực lượng xe tăng thiết giáp, có
bộ bình của Tiểu đoàn 2 ngồi trên xe thọc ngang qua đội hình địch,
sau đó bộ binh xuống xe tô chức thành ba mũi tiễn công. Cả ba mũi
cùng đột phá nhanh, tiền công mạnh mẽ, đánh bật địch ra mà chiếm
cầu, mở đường tiến công vào thành phó.
 
Được hỏa lực cụm pháo binh, Quân đoàn trực tiếp chi viện, lực
lượng xe tăng thiết giáp của ta vừa tiến vừa bắn mãnh liệt vào đội
hình xe địch. Các chiến sĩ bộ binh trên cả ba mũi tiến công dùng
B40, B4I và tiểu liên bắn mãnh liệt vào xe tăng và bộ binh địch.
Địch vẫn ngoan cổ chống cự. Nhưng trước sức tiến công áp đảo
của ta, chúng nhanh chóng bị tan rã và bò chạy hết từ vị trí này đến
vị trí khác.
 
Đến 8 giờ ngày 30 tháng 4, sau khi bị ta tiêu điệt thêm hai xe tăng
và một khâu pháo tự hành 175mm, thì toàn bộ quân địch phòng ngự
ở bắc cầu Bình Triệu gồm các thiết đoàn 18, 15, 22 của lữ đoàn ky
binh 3 cùng hai tiểu đoàn lính dù, các đại đội lính biệt động và bảo
an... buộc phải hạ vũ khí đầu hàng. Trận đánh kết thúc thắng lợi,
 
ta thu được 144 xe tăng thiết giáp và chiến xa địch; một khẩu cao xạ
bốn nòng và gọi hàng 1.500 tên địch.
 
Điểm “tử thủ” cuối cùng của địch ở bắc Sài Gòn đã bị đập tan.
Tranh thủ thời cơ, Trung đoàn 48 sử dụng tám chiếc xe tăng vừa thu
được của địch, bắt lính ngụy lái dẫn đường tiến vào đánh chiếm Bộ
tổng tham mưu ngụy.
 
Bộ tông tham mưu ngụy là một trong năm mục tiêu chủ yếu của
chiến dịch; là cơ quan đầu não, trung tâm điều hành chiến tranh của
quân đội Sài Gòn. Cấu trúc của Bộ tổng tham mưu ngụy rất kiên cố.
 
Trung đoàn 48 - lực lượng thọc sâu chủ yếu của Sư đoàn 320B
nhanh chóng vượt qua cầu, qua ngã tư Phú Nhuận, tiến theo đường
Võ Tánh vào đánh chiếm Bộ tổng tham mưu ngụy. Cùng lúc đó, cụm
pháo binh Lữ đoàn 45 đặt tại Búng dồn dập bắn 47 phát đạn 130mm
vào khu vực bộ này. Một số viên đạn rơi trúng trung tâm hành quân,
phá hủy sân bay trực thăng và khu kho đạn, kho xăng dầu làm bốc
cháy dữ dội; trung tâm thông tin bị tê liệt hoàn toàn. Bọn địch ở đây
vô cùng hoảng loạn.
 
Khi tiến gần tới mục tiêu, Trung đoàn 48 cho đơn vị dừng lại trên
đường Võ Tánh để điều chỉnh đội hình tiến công. Căn cứ vào tình
hình bố phòng của địch, Trung đoàn trưởng Đoàn Trưng quyết định
triển khai đội hình thọc sâu làm ba mũi tiến công vào Bộ tổng tham
mưu ngụy.
 
3 giờ 30 phút ngày 30 tháng 4, ba mũi tiến công từ ba cổng đã
gặp nhau ở khu vực cột cờ trước sân trụ sở Bộ tổng tham mưu ngụy.
Trước sức tiến công áp đảo của ta, binh lính sĩ quan địch thuộc tiểu
đoàn biệt kích dù, tiểu đoàn bảo vệ Tổng hành dinh và các đơn vị
đặc nhiệm khác đã phải lột bỏ quân phục, vứt súng chạy tháo thân.
Ta bắt một đại tá, một đại úy và nhiều binh sĩ địch.
 
Trung đoàn trưởng Đoàn Trưng và Chính ủy trung đoàn
Lê Xuân Yến tiến vào phòng làm việc của Cao Văn Viên - tổng
 
tham mưu trưởng quân đội Sài Gòn thu hồi ấn, kiếm (có ba con
dấu của Cao Văn Viên - Tổng tham mưu trưởng và trưởng đoàn
DAO Mỹ) cùng nhiều tài liệu quan trọng khác. Tổ cắm cờ gồm
ba người: Lại Đức Lưu, Hoàng Xuân Tiến, Nguyễn Văn Đông,
do đại đội trưởng Lại Đức Lưu chỉ huy nhanh chóng vận động
lên cắm lá cờ giải phóng trên nóc nhả trụ sở Bộ tổng tham mưu
ngụy trong tiếng reo hò của cán bộ, chiến sĩ, lúc đó khoảng 10 giờ
30 phút ngày 30 tháng 4 năm 1975.
 
Sau khi đánh chiếm Bộ tổng tham mưu ngụy, Bộ tư lệnh Quân
đoàn ra lệnh cho Sư đoàn 320B dùng Trung đoàn 64 phối hợp với
đơn vị bạn đánh chiếm căn cứ Gia Long và Bộ quốc phòng Việt Nam
cộng hòa; Trung đoàn 64 tiến công đánh chiếm tiểu khu Gia Định.
Một lực lượng khác do đồng chí Lê Minh - Tham mưu trưởng sư
đoàn chỉ huy phát triển sang đỉnh Độc Lập; khi đến nơi thấy đơn vị
bạn đã chiếm giữ ở đó liền quay sang cùng lực lượng của Trung đoàn
64 chiếm giữ các mục tiêu khu vực bộ quốc phòng ngụy.
 
Đền 16 giờ ngày 30 tháng 4 năm 1975, các hướng chiến đầu của
Quân đoàn đều đã cơ bản hoàn thành nhiệm vụ được giao. Một số
đơn vị tiếp tục truy quét những tên địch ngoan cố chỗng cự, gọi hàng
bọn địch còn lắn trốn. Đồng thời, các đơn vị phối hợp chặt chẽ với
Ủy ban quân quản, chính quyền địa phương triển khai phương án
bảo vệ vùng mới giải phóng và các mục tiêu đã đánh chiếm, tổ chức
tiếp nhận sự trình diện của sĩ quan và binh lính địch; tổ chức các tổ
công tác giúp chính quyền địa phương giữ gìn trật tự trị an, ôn định
đời sống nhân dân trong vùng mới giải phóng trên khu vực đứng
chân của Quân đoàn.
 
Quân đoàn đã tiêu diệt và làm tan rã hoàn toàn sư đoàn bộ binh
5 ngụy; các thiết đoàn 1, 18, 22 và một bộ phận thiết đoàn 15; hai
tiểu đoàn bảo an 306 và 316; tiêu diệt gần một nghìn tên địch (trong
đó có tên chuẩn tướng Lê Nguyên Vỹ - tư lệnh sư đoàn 5 ngụy
buôc phải tư sát): bắt làm tù binh 13.580 tên (trong đó có 3 đại tá,
 

 
26 trung tá, 114 thiếu tá, 925 sĩ quan cấp úy). Bắn cháy và phá hủy
60 xe tăng địch, ba khẩu pháo 105mm, hai cối 81mm, bắn rơi một
máy bay trực thăng; thu 113 xe tăng, thiết giáp, 583 xe quân sự,
105 khâu pháo cối các loại, 22 tàu xuồng, chiến đấu, 12 bộ siêu tần
số, 100 máy vô tuyến điện các loại...
 
3. Quân đoàn 2 sau khi hoàn thành nhiệm vụ trong tiến
công giải phóng các tỉnh duyên hải miền Trung, tham gia
chiến dịch Hồ Chí Minh lịch sử
 
Sau khi hành quân thần tốc giải phóng các tỉnh duyên hải miễn
Trung, vào những ngày cuối tháng 4 năm 1975, lực lượng của Quân
đoàn 2 có mặt đây đủ ở nam Xuân Lộc (hướng đông nam Sài Gòn).
Cùng thời điểm này, các cánh quân khác của ta cũng rằm rộ tiến vào
bao vây chặt sào huyệt cuối cùng của chính quyền Sải Gòn trên tắt
cả các hướng.
 
Ở vùng ven và nội thành Sài Gòn đã sẵn sảng có các đơn vị đặc
công, pháo binh kết hợp với lực lượng chính trị to lớn của quân
chúng. Ở phía sau, ta cũng đang gắp rút tổ chức thêm các lực lượng
dự bị mới, sẵn sàng đối phó có hiệu quả với mọi tình huống có thể
Xảy ra.
 
Về phía địch, tại Mặt trận Sài Gòn - Gia Định, trên các hướng
bắc, tây bắc, tây nam, mỗi hướng địch bố trí khoảng một sư đoàn
tăng cường. Riêng hướng đông, lực lượng phòng thủ của chúng tăng
lên đến chín trung đoàn, lữ đoàn bộ binh, lính dù, lính thủy đánh bộ
và bốn trung đoàn thiết giáp. Ở vùng nội đô có một số đơn vị lính
dù, biệt động, thiết giáp, các lực lượng bảo vệ căn cứ, các lực lượng
thuộc “Biệt khu thủ đô” phòng giữ. Lực lượng không quân ở Sài
Gòn - Gia Định có ba sư đoàn, bó trí chủ yếu ở hai sân bay lớn là
Biên Hòa và Tân Sơn Nhất. Ở khu vực đồng bằng sông Cửu Long,
địch có ba sư đoàn bộ binh, năm trung đoàn thiết giáp, một sư đoàn
không quân. Chúng tập trung phòng giữ Tân An, Mỹ Tho đề phòng
 

 
khi không giữ nôi Sài Gòn - Gia Định sẽ theo hướng đường 4 rút về
đồng bằng sông Cửu Long có thủ.
 
Sáng 23 tháng 4 năm L975, tại sở chỉ huy Quân đoàn đặt tại ấp
Tam Hiệp, xã Xuân Hiệp, sư đoàn 325 chính thức nhận nhiệm vụ của
Bộ tư lệnh Quân đoàn 2. Ngay chiều và đêm hôm đó, Đảng ủy và
Bộ tư lệnh sư đoàn họp đánh giá lại toàn bộ tình hình và nghiên cứu
nhiệm vụ. xây dựng kế hoạch tác chiến.
 
Trong Chiến dịch Hồ Chí Minh, Sư đoàn 325 được tăng cường
xe tăng. pháo binh, cao xạ, công binh, đảm nhiệm một hướng đột
kích quan trọng trong hướng tiến công chủ yếu của Quân đoàn 2,
đồng thời cũng là hướng vu hồi của chiến địch. Trước mắt sư đoản
có nhiệm vụ tiên công tiêu diệt địch ở tả ngạn sông Đồng Nai, đánh
chiếm chỉ khu Long Thành, chỉ khu Nhơn Trạch, thành Tuy Hạ,
khóa chặt đường thủy, không cho địch ở Sài Gòn theo sông Lòng
Tàu rút chạy ra biên và mở đường đưa pháo tầm xa vào Nhơn Trạch
đánh phá sân bay Tân Sơn Nhất, khống chế đường không. Nhiệm
vụ tiếp theo của sư đoàn là tổ chức vượt sông, đánh chiếm căn cứ
hải quân Cát Lái, tiêu điệt các lực lượng địch phòng ngự ở hữu ngạn
sông Đồng Nai và đánh vào nội đô giải phóng quận 9.
 
Trục tiến công của sư đoàn vào Sài Gòn là một vùng có địa hình
rất phức tạp, bị chia cắt bởi những cánh đồng lầy lội và hệ thống
sông ngòi chẳng chịt, trong đó có hai sông lớn (sông Đồng Nai và
sông Sài Gòn) ta phải tổ chức vượt qua bằng thuyền, phà vì không
có cầu qua sông. Lực lượng địch phòng thủ ở khu vực này có một
bộ phận của lữ đoàn 468 lính thủy đánh bộ, bảy tiểu đoàn bảo an,
một số đơn vị pháo binh, xe tăng và bốn liên giang đoàn yễm trợ,
một liên giang đoàn người nhái với khoảng 2.000 quân và 241 tàu,
xuông chiến đấu (các đơn vị hải quân địch tập trung chủ yếu ở khu
vực Cát Lái). Khi bị tiến công, hải quân địch có thê cơ động tàu,
xuồng theo sông lạch, phối hợp với các lực lượng trên bộ chặn đánh
ta từng bước,
 

 
Đẻ thực hiện nhiệm vụ trên, quyết tâm của Đảng ủy và Bộ tư lệnh
Sư đoàn 325 là: Tập trung lực lượng bộ binh, xe tăng, pháo binh, cao
xạ tiến công tiêu diệt quân địch ở khu vực Long Thành - Bình Sơn,
phá vỡ tuyến phòng thủ then chốt vòng ngoài của địch trên hướng
đông nam, mở đường đưa lực lượng và binh khí kỹ thuật thọc sâu
vào đánh chiếm Nhơn Trạch, thành Tuy Hạ bịt đường thủy, khống
chế đường không theo đúng yêu cầu hiệp đồng, hoàn thành nhiệm vụ
vu hôi chiến dịch và sẵn sàng vượt sông bằng sức mạnh đánh chiếm
căn cứ hải quân Cát Lái, phát triển vào nội đô giải phóng quận 9 khi
có lệnh.
Về cách đánh, Bộ tư lệnh sư đoàn chủ trương: tập trung lực lượng
bộ binh có tăng cường hỏa lực pháo binh, cao xạ và xe tăng tạo thành
mũi đột kích mạnh, chọc thủng “tuyến phòng thủ đông - nam” ở nơi
xung yếu nhất của địch là Long Thành. Kết hợp chặt chẽ giữa đột
phá chính diện với bao vây, vu hồi, chia cắt, không cho địch rút chạy
về phía sau. Khi trận tuyến phòng thủ vòng ngoài của chúng ở Long
Thành đã tan vỡ thì nhanh chóng thọc sâu đánh chiếm các mục tiêu
tiếp theo trong hành tiến làm cho địch không kịp trở tay, loại trừ khả
năng co cụm của chúng.
 
Về sử dụng lực lượng, hai trung đoàn 101 và 46 được tăng cường
xe tăng và hỏa lực mạnh đảm nhiệm nhiệm vụ đánh chiếm khu vực
Long Thành: Trung đoàn 101 đột kích hướng chính điện theo trục
đường 10; Trung đoàn 46 luồn vào phía sau địch đánh chiếm ngã
ba Phước Thiềng cắt đường rút, không cho địch lui về phía sau co
cụm; tiếp đó thọc sâu chiếm Nhơn Trạch, thành Tuy Hạ, căn cứ Cát
Lái và quận 9 Sài Gòn. Trung đoàn 18 bao vây tiêu diệt bọn địch
ở Bình Sơn và làm lực lượng dự bị chiến địch của quân đoàn, sẵn
sàng chuyển sang tham gia tiến công địch trên hướng đột kích chủ
yếu (hướng do Sư đoàn 304 đảm nhiệm), đánh vào nội đô theo trục
đường ÏŠ và xa lộ Sài Gòn - Biên Hòa.
 

 
Trưa ngày 26 tháng 4 năm 1975, mọi công tác chuân bị đã hoàn
thành. Trên các hướng, bộ binh và xe tăng bắt đầu cơ động vào
chiếm lĩnh tuyến xuất phát xung phong.
 
17 giờ ngày 26 tháng 4 năm 1975, cuộc tiến công của quân ta
trên hướng đông và đông nam Sài Gòn bắt đầu. Lực lượng pháo binh
hùng hậu của sư đoàn, quân đoàn và các đơn vị bạn đồng loạt nô
súng trút bão lửa vào Trảng Bom, Hồ Nai, Biên Hòa, Nước Trong,
Long Thành, Đức Thạnh, Bà Rịa... Bộ đội cao xạ ngoan cường
đánh tra máy bay địch bảo vệ các trận địa pháo và toàn bộ đội hình
chiến dịch.
 
Theo đúng kế hoạch, pháo tầm xa của Quân đoàn và pháo 85mm,
105mm. 122mm của các sư đoàn dồn dập bắn 40 phút vào các cụm
phòng thủ của địch trên chính diện tiền công. Súng cối và pháo đi
cùng của các trung đoàn bộ binh cũng phát huy hỏa lực bắn 10 phút
vào các mục tiêu xung phong đầu tiên. Cùng lúc đó, lợi dụng hiệu
quả chế áp của pháo, bộ binh và xe tăng ta khẩn trương vận động vào
chiếm lĩnh bàn đạp chuẩn bị xung phong. Đợt pháo bắn chuẩn bị vừa
đứt, từ các cánh rừng cao su, các vườn cây, các sườn đổi, công sự,
chiến hào... bộ đội ta ào ạt xông lên đánh chiếm các căn cứ, các trận
địa phòng ngự của địch. Phía bên phải khu vực đột phá của Sư đoàn
325, các chiên sĩ Sư đoàn 304 nổ súng tiến công căn cứ Nước Trong;
phía bên trải, các chiến sĩ Sư đoàn 3 đánh Đức Thạnh. Bà Rịa.
 
Ngày 27 tháng 4 năm 1975, cuộc chiến đấu ở khu vực Long
Thành tiếp tục diễn ra ác liệt. Bộ đội ta quyết đánh chiếm bằng được
mục tiêu, địch cũng tăng cường lực lượng tới phản kích và huy động
phi pháo chỉ viện cho binh lính lữ đoàn 468 lính thùy đánh bộ cùng
bọn bảo an, dân vệ giữ Long Thành. Các chiến sĩ vừa lùng điệt quân
địch trong các vườn cây, các dãy nhà, góc phó vừa đánh trả máy bay
địch. Đến I6 giờ 30 phút, Sư đoàn 325 hoàn toàn làm chủ khu vực
Long Thành, diệt hơn 600 tên địch, bắt tại trận 506 tên khác, trong
đó có hai tên trung tá, hai thiếu tá, bốn đại úy, thu và phá hủy ba trận
 
địa pháo (10 khâu 105mm), cùng nhiều vũ khí, phương tiện chiến
tranh khác của địch.
 
Chiến thắng Long Thành phá vỡ một khâu quan trọng trên tuyến
phòng thủ vòng ngoài của địch ở hướng đông nam Sài Gòn. Bộ tư
lệnh Quân đoàn 2 gửi điện nhiệt liệt biểu dương, khen ngợi cán bộ,
chiến sĩ đã lập chiến công đầu và chỉ thị cho sư đoàn: Nhanh chóng
tiến đánh chỉ khu, quận ly Nhơn Trạch, mở đường đưa pháo tầm xa
vào cấu trúc trận địa, kịp thời nỗ súng đánh phá sân bay Tân Sơn
Nhất, khóa chặt đường không của địch trước giờ tổng công kích và
khẩn trương đánh bịt đường rút của địch từ Sài Gòn qua sông Lòng
Tàu ra biển, hoàn thành nhiệm vụ vu hồi chiến dịch.
 
Ngày 28 tháng 4, khí sư đoàn thọc sâu vào Nhơn Trạch thì bên
cánh phải của Quân đoàn, Sư đoàn 304 vẫn đang tiếp tục đánh Nước
Trong. Các cánh quân khác của ta trên toàn mặt trận còn đang đột
phá tuyến phòng thủ vòng ngoài, mở cửa chiến dịch trên các hướng.
Riêng Sư đoàn 325 nếu đánh được vào tới Nhơn Trạch, sẽ là mũi
nhọn đột kích đầu tiên áp sát vùng nội đô. Bọn địch chắc chắn sẽ
phản ứng dữ dội. Nhưng đây là một hướng đánh rất hiểm. Do địa
hình có nhiều khó khăn, quân địch ít chú ý phòng bị trục đường 25.
Nếu ta hành động mau lẹ, chúng sẽ không kịp trở tay. ¬ đòn bất
ngờ, thế trận phòng ngự của chúng sẽ rơi vào tình trạng rối loạn. Bộ
tư lệnh Quân đoàn đồng ý cho đơn vị chuyển sang tiến công địch
trong hành tiến.
 
Trong đêm 27, các đơn vị lần lượt tiến ra đường 25 sẵn sảng cơ
động. Trung đoàn 46 đảm nhận nhiệm vụ dẫn đầu đội hình của sư
đoàn. Đại đội 6 xe tăng (hiện còn bốn chiếc) được điều lên tăng
cường cho Trung đoàn 46. Tiếp đó là cơ quan chỉ huy và các đơn vị
binh chủng, đi cuối đội hình là Trung đoàn 101, vừa hành quân vừa
tranh thủ củng cố lực lượng. Trung đoàn 18 ở lại bảo vệ phía sau và
làm dự bị của Quân đoàn tiến đánh bên cánh phải. Để nắm chắc và
chỉ huy các lực lượng ở phía trước, Sư đoàn trường Phạm Minh Tâm
 

 
và Chính ủy Lê Văn Dương quyết định tô chức một bộ phận chỉ huy
nhẹ đi cùng sở chỉ huy Trung đoàn 46 do trung tá Nguyễn Quang
Huy. Phó Sư đoàn trưởng và thiếu tá Nguyễn Văn Rinh, Phó Tham
mưu trưởng sư đoàn phụ trách. Đông chí phó chủ nhiệm chính trị
tinh đội Biên Hòa và một số đồng chí cán bộ huyện Nhơn Trạch
cũng luôn theo sát đội hình tiền quân, giúp sư đoàn hiệp đồng với
các lực lượng tại chỗ đánh địch. Rạng sáng ngày 28 tháng 4, đội
hình tiến công của sư đoàn được tỏ chức xong và các đơn vị bắt đầu
xuất phát. Trên đoạn đường từ Long Thành vào Nhơn Trạch, Trung
đoàn 46 bộ binh dẫn đầu đội hình tiến công của sư đoàn, liên tiếp
tiêu diệt các cụm phòng thủ của địch ở Bến Sáng, Phú Hội, Long
Tân: đồng thời quét luôn hàng loạt tô chức kìm kẹp của địch ở các
thôn xã dọc đường 25.
 
Bị bắt ngờ trước đòn đột kích táo bạo của các chiến sĩ Sư đoàn
325, lực lượng địch ở đây chống cự không nỗi và tan vỡ. Trong buôi
chiều và tối hôm đó, được xe tăng và pháo binh chỉ viện, Trung đoàn
46 sử dụng chiến thuật bao vây tiễn công liên tục, sau ba đợt xung
phong quyết liệt đã chiếm gọn quận ly Nhơn Trạch, tiêu diệt và làm
tan rã toàn bộ quân địch có thủ ở đây.
 
Đội hình chiến đấu của sư đoàn vừa xuất phát, các chiến sĩ Tiểu
đoàn 3 Lữ đoàn 164 pháo binh dưới sự chỉ huy của Chủ nhiệm Chính
trị lữ đoàn Nguyễn Băng Hiến cũng được lệnh đưa pháo 130mm tiến
sát theo bộ binh. Trên đường tiến quân, bộ đội pháo binh cùng các
lực lượng hành quân phía sau của sư đoàn liên tục đánh trả các cuộc
phản kích của bộ binh và hải quân địch từ căn cứ Cát Lái theo sông
lạch tiến ra bịt đường. Ở khu vực Long Tân - Phú Hội, cuộc chiến
đấu diễn ra ác liệt nhất. Hàng chục tàu chiến địch đô quân lên rừng
đước và dồn dập nã pháo, cối vào trục đường 25. Binh lính của chúng
tỏa ra, tốp bò, tốp chạy đầy đồng. Nhiều trận giáp chiến đã diễn ra
trong cíc vườn cây, các vạt ruộng ngập nước. Đề bảo vệ pháo, giữ
vững đội hình tiến quân, cán bộ, chiến sĩ cơ quan sư đoàn và các
 
đơn vị binh chủng đều xông lên diệt địch. Các khẩu đội pháo 85,
cao xạ 37mm, súng máy l2,7mm... của các trung đoàn 84, 284
cũng nhanh chóng tìm vị trí thuận lợi tham gia đánh tàu chiến và bộ
binh địch.
 
Đêm 28 tháng 4, các khẩu đội pháo tầm xa 130mm của lữ
đoàn 164 dồn dập tiến vào Nhơn Trạch thiết bị trận địa bắn, chuẩn
bị đánh sân bay Tân Sơn Nhất và các mục tiêu trong thành phố theo
lệnh của Bộ tư lệnh Quân đoàn và Bộ chỉ huy chiến dịch, 36 khẩu
pháo lớn của Trung đoàn 84 pháo binh, đơn vị anh hùng, 24 khẩu
pháo cao xạ 37mm và 57mm của Tiểu đoàn 120 và Tiểu đoàn Tà
đơn vị anh hùng nối tiếp nhau vào Nhơn Trạch, hướng nòng ra phía
trước, sẵn sàng nhã đạn đánh phá thành Tuy Hạ, căn cứ hải quân Cát
Lái, cảng Sài Gòn, v.v... săn điệt tàu địch trên sông Lòng Tàu, sông
Đồng Nai, cắt đứt đường thủy từ Sài Gòn ra biển và sẵn sàng đánh
máy bay địch bảo vệ đội hình tiến công của sư đoàn. Bao quanh các
trận địa pháo là tầng tầng, lớp lớp các tay súng bộ binh kiên cường
của hai Trung đoàn 101 và 46 - những con người đã góp phần không
nhỏ trong chiến công đưa pháo lớn vào đặt ngay cửa ngõ Sài Gòn
trước giờ tổng công kích và đang cảnh giác sẵn sàng giáng trả các
cuộc phản công của hải, lục, không quân địch, giữ vững bàn đạp
Nhơn Trạch. Trong lịch sử kháng chiến cứu nước, đây là lần đầu
tiên ta đã đặt toàn bộ khu vực “thủ đô” của địch trong tầm khống
chế của pháo binh hạng nặng, tăng thêm thế uy hiếp mạnh mẽ quân
địch ở thời điểm quyết định. Việc tổ chức thành công cả một cụm
pháo lớn ở ngay sát nội đô trước giờ tổng công kích thẻ hiện tài thao
lược của Bộ chỉ huy chiến dịch; thể hiện quyết tâm và cố gắng vượt
bậc của chiến sĩ bộ binh, bình chủng toàn Quân đoàn, đồng thời
một lần nữa chứng tỏ ưu thế áp đảo của ta trong trận đánh giải phóng
Sài Gòn - Gia Định.
 
Sáng ngày 29 tháng 4 năm 1975, chấp hành mệnh lệnh của Bộ
chỉ huy chiến dịch, Tư lệnh Quân đoàn chỉ thị cho các trận địa pháo
 
130mm đặt ở Nhơn Trạch bắn vào sân bay Tân Sơn Nhất, mở đầu
cuộc tông công kích.
 
Đúng 4 giờ 30 phút, khẩu đội của Nguyễn Văn Biên vinh dự bắn
quả đạn đầu tiên. Tiếp đó, 303 quả đạn pháo 130mm dồn dập bắn
vào sân bay Tân Sơn Nhất trong một thời gian ngắn. Hòa cùng tiếng
pháo lệnh của Lữ đoàn 164, các trận địa pháo của sư đoàn và các
đơn vị bạn đồng loạt nỗ súng, trút bão lửa vào các khu vực mục tiêu
quy định.
 
Tiếng pháo vang rền từ trận địa Nhơn Trạch báo hiệu mở đầu
cuộc tông công kích của quân dân ta trên Mặt trận Sài Gòn - Gia
Định. Chấp hành mệnh lệnh của Bộ chỉ huy chiến dịch, các binh
đoàn thọc sâu của năm cánh quân đồng loạt vượt qua tuyến phòng
thủ vòng ngoài của địch, ào ạt đánh vào nội đô, cùng các lực lượng
tại chỗ giải phóng thành phó.
 
Trước đó, ngày 28 tháng 4, trong khi sư đoàn đang khẩn trương
hoàn thành nhiệm vụ đánh vu hỏi trên hướng Long Thành - Nhơn
Trạch thì Trung đoản 18 (lực lượng dự bị của Quân đoàn) nhận
được chỉ thị đưa một tiểu đoàn sang phối hợp với Trung đoàn 9
Sư đoàn 304 đánh chiếm khu ngã ba đường 15 - Nước Trong, mở
sẵn cửa kho binh đoàn đột kích cơ giới hóa phát triển. Sáng ngày 29,
khi bình đoàn đột kích cơ giới hóa bắt đầu xuất phát, Trung đoàn 18
được lệnh tiến tiếp ngay phía sau lực lượng thọc sâu, đánh vào giải
phóng thành phố theo trục Nước Trong - Long Bình và xa lộ Biên
Hòa - Sài Gòn. Cùng thời gian đó, sư đoàn được lệnh tổ chức đánh
chiếm thành Tuy Hạ, căn cứ Cát Lái và phát triển vào nội đô giải
phóng quận 9.
 
Lúc 16 giờ chiều ngày 29 tháng 4, Trung đoàn I0I và xe tăng
bắt đầu tiến vào cùng Trung đoàn 46 mở đợt tiến công quyết định.
Ba chiếc xe tăng T54 tiến đến cách cổng thành Tuy Hạ 500 mét
thì dừng lại đùng pháo và súng trọng liên 12,7mm kiềm chế chặt
chẽ các hỏa điểm địch. Các chiến sĩ Trung đoàn 46 một lần nữa
 
ào ạt xung phong. Tiểu đoàn 3 Trung đoàn 10] có xe tăng T54 dẫn
đầu dũng mãnh xông thăng vào công chính và nhanh chóng tỏa ra
đánh chiếm các điểm cố thủ của địch. Mục tiêu thành Tuy Hạ được
giải quyết xong vào hồi 18 giờ ngày 29. Lực lượng quân ngụy phòng
thủ khu vực này phần lớn bị tiêu diệt và bắt sống tại trận. Một bộ
phận luồn được ra công phía nam, tháo chạy về Cát Lái.
 
Chớp thời cơ quân địch trong vùng đang hết sức hoang mang,
dao động sau các đòn liên tiếp thua đậm ở Long Thành, Nhơn Trạch,
thành Tuy Hạ, sư đoàn lệnh cho Trung đoàn 101 truy kích đánh
thắng xuống Cát Lái. Tới 18 giờ 40 phút, bộ binh, xe tăng ta tới sát
khu vực mồ cầu phà phía bắc. Bọn hải quân địch ở khu vực Cát Lái
vội vã kéo tất cả tàu, thuyền sang bờ nam sông Đồng Nai, bỏ rơi
hàng trăm tên lính ngụy đang run lên vì khiếp sợ bên bờ bắc sông.
Khi bộ đội ta tràn tới, chúng nhanh chóng đầu hàng và tan rã.
 
Tối 29 tháng 4, để chuẩn bị cho cuộc vượt sông đánh vào Sài Gòn,
một bộ phận trinh sát chiến đấu của sư đoàn lập tức dùng thuyền bí
mật đỗ bộ sang bờ nam sông, nắm địch. Bộ tư lệnh sư đoàn cùng cán
bộ chỉ huy các Trung đoàn 101, 84, 46 và đơn vị xe tăng, công binh...
xuống khu vực bến phà trực tiếp nghiên cứu, xây dựng phương án
vượt sông tại chỗ. Giữa những chớp lửa sáng lóe của đạn pháo địch
bắn cầm canh sang bờ bắc, cán bộ chỉ huy các đơn vị chăm chú lắng
nghe sư đoàn trưởng chỉ thị và phòng tham mưu sư đoàn phổ biến
kế hoạch hiệp đồng tác chiến. Quyết tâm của sư đoàn là: tổ chức tiến
công vượt sông Đồng Nai bằng sức mạnh hiệp đồng binh chủng,
đánh chiếm căn cứ Cát Lái, khu vực cảng và quận 9 Sài Gòn, hoàn
thành thắng lợi nhiệm vụ cấp trên giao cho.
 
Ngay trong đêm tối, các đơn vị khân trương triển khai lực lượng
chuẩn bị vươt sông. Tảng sáng ngày 30 tháng 4, khi trận địa pháo
tầm xa 130mm đặt ở Nhơn Trạch được lệnh thôi bắn vào sân bay
Tân Sơn Nhất, thì cuộc tiến công vượt sông của sư đoàn bắt đầu.
 

 
Đề thăm dò phản ứng và nhứ các trận địa hỏa lực địch trên bờ
nam sông bị lộ cho pháo binh ta bắn hủy diệt, sư đoàn trưởng chỉ thị
cho mỏt xe lội nước (BAP) chở 10 chiến sĩ bộ bình được trang bị
mạnh, vượt lên trước đội hình. tiễn thăng sang bờ nam sông. Xe BAP
của ta vừa ra tới giữa sông thì bọn địch trong căn cứ hải quân Cát
Lái nỗ súng đánh chặn và cho ba tàu chiến xuất kích ra bịt đường.
Trận địa pháo bắn ngắm trực tiếp của Trung đoàn 84 lập tức nô súng
đánh chìm tại chỗ cả ba tàu địch. Các cụm pháo sư đoàn đặt ở Nhơn
Trạch, Tuy Hạ đồng loạt phát hỏa, trút bão lửa xuống vị trí địch trên
bờ nam sông. Các khâu đội cao xạ của ta cũng hạ nòng tham gia
đánh diệt bộ binh địch. Pháo binh ta được đài quan sát luồn sâu hiệu
chinh bắn rất chính xác. Tiếng trái pháo nô dồn dập. Từ căn cứ Cát
Lái, những đám cháy, những cột khói lớn bốc cao. Đòn tập kích hỏa
lực mạnh mẽ của pháo binh ta nhanh chóng đè bẹp lực lượng địch
trên toàn khu vực. Tuy có chuẩn bị đối phó từ chiều ngày 29, nhưng
chúng vẫn bị bất ngờ trước quy mô cuộc tiền công và cách đánh của
ta. Vì bị bắt ngờ nên binh lính ngụy hoảng hốt bỏ tàu vọt lên bở tìm
nơi ẩn nấp hoặc tháo chạy thục mạng. Bọn chỉ huy các liên giang
đoàn yêểm trợ hết sức lúng túng và không năm được binh lính thuộc
quyền. Chúng liên tiếp đánh điện cầu cứu cấp trên cho lực lượng tới
tiếp viện.
 
Vào lúc 6 giờ sáng ngày 30 tháng 4, mong đánh thông đường
tháo chạy ra biển và cứu nguy cho đồng bọn ở Cát Lái, bộ tư lệnh
hải quân địch liều lĩnh tập trung lực lượng mở cuộc phản kích. Từ
Tân Cảng, hàng đoàn tàu chiến chở đây lính ngụy theo sông Nhà Bè
hùng hô tiến ra vừa đi vừa bắn tới tắp vào những nơi chúng nghỉ ngờ
có trận địa hỏa lực của ta bố trí.
 
Mặc cho địch phản pháo ác liệt, các chiến sĩ Trung đoàn 84 và
Tiểu đoàn 120 cao xạ gan góc chờ địch vào gần mới nô súng đánh
trả. Chi trong chớp nhoáng lại thêm 5 tàu địch bị nhắn chìm tại
chỗ. Nhiều chiếc khác trúng đạn pháo bị thương. Một tàu kéo theo
 
ba xà lan chở đầy đạn bốc cháy, nỗ dữ dội. Hàng chục tàu chiến địch
liên tiếp bị bắn chìm, bắn cháy trên sông Đồng Nai làm cho bọn
hải quân ngụy vô cùng khiếp sợ. Sợ pháo binh ta săn đuổi, các tàu
địch đi ở phía sau vội vã quay đầu tháo chạy về Tân Cảng. Nhân đà
thắng lợi, cán bộ chỉ huy sư đoàn lập tức ra lệnh cho Trung đoàn 101
vượt sông. Được chính quyền cách mạng và nhân dân địa phương
đưa thuyên bè tới giúp chuyên chở lực lượng, cán bộ, chiến sĩ 101
nhanh chóng đánh sang. chiếm gọn căn cứ hải quân Cát Lái, bắt giữ
thu hồi hơn 100 tàu xuồng chiến đấu và một khối lượng rất lớn vũ
khí, phương tiện chiến tranh khác. Cùng thời gian đó, các chiến sĩ
Trung đoàn 46 nhận nhiệm vụ truy kích địch mới được tàu chiến đổ
lên bờ bắc. Trung đoàn nhanh chóng tiêu điệt và đánh tan hai tiểu
đoàn địch, bảo đảm an toàn cho lực lượng binh khí kỹ thuật tiếp tục
chuyến sang phía nam sông.
 
Cuộc tiến công vượt sông Đồng Nai bằng sức mạnh hiệp đồng
binh chủng, trận đánh lớn thứ tư của Sư đoàn 325 trong Chiến dịch
Hồ Chí Minh kết thúc thắng lợi.
 
Vào lúc căn cứ Cát Lái - điểm cố thủ cuối cùng của địch ở phía
đông - nam Sài Gòn bị đập vỡ tan tành, thì trên hướng đường xa lộ,
binh đoàn đột kích cơ giới hóa của Quân đoàn 2, sau khi đánh chiếm
căn cứ Long Bình, cầu xa lộ (Đồng Nai), đã tràn qua quận Thủ Đức
và đang tiếp tục đột phá qua điểm cố thủ cuối cùng của địch ở khu
vực cầu xa lộ (Sài Gòn), mở đường đánh vào đinh Độc Lập.
 
Chấp hành mệnh lệnh trên, ngay sau khi vừa cơ bản đập vỡ được
điểm phòng thủ của địch ở Cát Lái, Bộ tư lệnh Sư đoàn 325 trực tiếp
nắm Trung đoàn 101 cùng đơn vị xe tăng thần tốc đánh vào quận 9
và khu vực Tân Cảng. Trung đoàn 46 và Trung đoàn 84 ở lại bảo vệ
mục tiêu và khóa chặt sông Lòng Tàu không cho địch rút ra biển.
 
Đến giờ phút này, bọn địch ở Sài Gòn đã hỗn độn đến cực độ. Đại
bộ phận binh lính địch khiếp sợ trước sức tiến công vũ bão của quân
ta, chúng quảng súng tìm đường tháo chạy. Bọn quan chức ngụy
 

 
quyền cùng nháo nhác tìm phương di tản. Nhưng đường thủy, đường
không va mọi tuyến đường bộ đều đã bị khóa chặt. Con đường duy
nhất mà chúng phải chọn là đầu hàng cách mạng. Ở dinh Độc Lập.
tướng Dương Văn Minh đang chủ trì một cuộc họp các tông trưởng
ngụy đề chuẩn bị cho lễ ra mắt “tân nội các” dự định sẽ tiến hành
vào 10 giờ sáng. Nhưng khi nhận được tin các đơn vị nòng cốt bảo
vệ vòng ngoài đều bị tiêu diệt và tan rã, các quân đoàn chủ lực
của ta từ nhiều hướng đã tràn vào tới nội đô, Tống thống Việt Nam
Cộng hòa buộc phải đưa ra một bản tuyên bố muộn màng trên đài
phát thanh Sài Gòn xin “ngừng bắn... đê cùng thảo luận về bản giao
chính quyền” hòng vớt vát được chút gì trong cái thế sụp đồ không
thể tránh khỏi.
 
Không nghe bắt cứ luận điệu nào của đối phương, cán bộ, chiến
sĩ ta kiên quyết chấp hành mệnh lệnh của Bộ chỉ huy chiến dịch,
nêu cao quyết tâm tiến thằng vào sào huyệt cuối cùng của địch, bắt
chúng phải đầu hàng không điều kiện.
 
Từ 9 giờ ngảy 30 tháng 4, các chiến sĩ Trung đoàn 101 phát triển
trên hướng đông nam Sài Gòn dồn dập đánh vào chiếm gọn quận 9,
bộ tư lệnh hải quân ngụy và khu vực Tân Cảng, thu hồi và bắt giữ
hàng trăm tàu địch trên sông Sài Gòn.
 
Trên hướng đường xa lộ, các chiến sĩ Trung đoàn 18 sau khi đập
tan sự kháng cự của địch ở Trường cảnh sát quốc gia và Trường huấn
luyện Thủ Đức đã nhanh chóng đánh thẳng vào quận 1.
 
Quân đoàn giao nhiệm vụ cho Lữ đoàn 203 xe tăng, Trung đoàn
66 Sư đoàn 304 và các đơn vị bạn trong Quân đoàn thành lập “Liên
binh đoản thọc sâu” đánh chiêm dinh Độc Lập. Bộ phận liên binh
đoàn thọc sâu này đã nhanh chóng vượt cầu Sài Gòn tiến vào đỉnh
Độc Lập bắt giữ tổng thống Dương Văn Minh và toàn bộ nội các Sài
Gòn, chiếm Đài phát thanh, Tổng cục chiến tranh chính trị, khu vực
 
thirưnơ cảng và anÂn 4.
 
Đúng II giờ 30 phút ngày 30 tháng 4 năm 1975, lá cờ Mặt trận
dân tộc giải phóng miền Nam Việt Nam tung bay trên nóc định
Độc Lập.
 
4. Quân đoàn 3 tiến công trên hướng bắc, tây bắc Sài Gòn
trong Chiến dịch Hồ Chí Minh
 
Quân đoàn 3 được Bộ chỉ huy Chiến dịch Hồ Chí Minh giao
nhiệm vụ tiến công trên hướng bắc, tây bắc Sài Gòn.
 
a) Trên hướng bắc, Sư đoàn 320A tiến công cứ điểm Đồng Dù,
phá tan tuyến phòng thủ tây bắc Sài Gòn của địch
 
Sư đoàn Đồng Bằng (Sư đoàn 320A) do đồng chí Bùi Đình Hòc,
nguyên phó sư đoàn trưởng, được bổ nhiệm sư đoàn trưởng, trực
tiếp chỉ huy sư đoàn chiến đấu cùng các đồng chí Bùi Huy Bồng,
Chính ủy: Đặng Văn Trượng, Phó chính ủy và Ngô Huy Phát, Phó
sư đoàn trưởng.
 
Trên con đường hành quân vào chiến dịch này đã diễn ra một
cuộc gặp gỡ lịch sử. Đó là cuộc gặp gỡ giữa hai sư đoàn cùng sinh
ra từ một cội nguồn: Sư đoàn 320A trong đội hình Quân đoàn 3 và
Sư đoàn 320B trong đội hình Quân đoàn 1.
 
Những người lính Đồng Bằng gặp nhau tay bắt mặt mừng. Từ
mắy năm nay, kể từ khi “hòn máu xẻ đôi”, mỗi đoàn quân đánh giặc
một phương trời, nhưng vẫn hằng dõi theo bước chân hành quân của
nhau. Khi quần nhau với địch trên những điểm cao chót vót phía tây
sông Pô Kô, khi nằm trong chiến hào vây ép Đức Cơ, các chiến sĩ
320A vẫn nghe tin chiến thắng của 320B từ chiến trường Quảng Trị
vọng vào. Một lá thư thăm hỏi, một gói quà nhỏ bé đầy tình nghĩa
anh em 320B gửi vào đã động viên cổ vũ các chiến sĩ tiến lên không
ngừng, không nghỉ. Từ hai đầu chiến trường, người lính Đồng Bằng
ở hai sư đoàn vẫn luôn động viên nhắc nhở nhau: Hãy xứng đáng
với truyền thống vẻ vang của Đại đoàn Đông Bằng, của Quân đội
nhân dân Việt Nam,
 

 
Ngày L5 tháng 4 năm 1975, sư đoàn chính thức nhận nhiệm vụ
của Bộ tư lệnh Quân đoàn 3: Sư đoàn 320 được tăng cường Trung
đoàn 593, có nhiệm vụ tập trung lực lượng đánh chiếm căn cứ Đồng
Dù, mơ cửa, đánh chiếm đâu cầu của Quân đoàn; đánh chiếm khu
vực càu Bông, cầu Sáng, bảo đảm đường cơ động cho mũi đột kích
cơ giơi mạnh của Quân đoàn tiền vào đánh chiếm sân bay Tân Sơn
Nhất, Bộ tông tham mưu quân ngụy Sài Gòn. Sau đó, sẽ trở thành
đội dự bị của Quân đoàn phát triên tiền công vào nội thành Sài Gòn.
 
Sau khi nhận nhiệm vụ, Đảng ủy và Bộ tư lệnh sư đoàn họp và
quyết tâm: Kiên quyết tập trung lực lượng, phát huy sức mạnh tông
hợp của toàn sư đoàn, nỗ lực cao nhất đề hoàn thành nhiệm vụ mở
chiến dịch cho hướng tiền công của Quân đoàn, tiêu diệt căn cứ
Đồng Dù, đánh chiếm Củ Chỉ, Tân Quy và cầu Bông, cầu Sáng. Sau
đó nhanh chóng xốc lại đội hình, sẵn sàng phát triển vào Sài Gòn,
hoàn thành xuất sắc nhiệm vụ của Bộ tư lệnh Quân đoàn giao cho.
 
Mọi công tác chuẩn bị cho chiến dịch lập tức được triển khai.
Ngày 22 tháng 4, phương án tiến công căn cứ Đồng Dù và khu vực
phụ cận được Bộ tư lệnh quân đoàn phê chuẩn.
 
Các chiến sĩ Tiểu đoàn L7 công binh được lệnh khẩn trương hoàn
thành cầu phao qua sông Sài Gòn bằng những phương tiện ta thu
được cúa công binh địch trong chiến dịch Tây Nguyên.
 
Đêm 23 tháng 4, sư đoàn được lệnh vượt sông Sài Gòn, hành
quân xuống nam Bến Súc. Đến ngày 25 tháng 4, toàn bộ đội hình sư
đoàn đã qua sông Sài Gòn vào vị trí tập kết an toàn.
 
Nằm trên trục quốc lộ số I Sài Gòn đi Tây Ninh, căn cứ Đồng
Dù thực sự là cánh cửa sắt án ngữ phía tây với Bình Dương và Hậu
Nghĩa. Đồng Dù là một căn cứ phòng ngự trọng yếu trong tuyến phòng
thủ Sải Gòn, nên từ lâu, Mỹ - ngụy đã ra công vun đắp, xây dựng nó
trở thành một căn cứ xuất phát hành quân hỗn hợp quy mô lớn. Nó
 
vấn là hanz ổ của sư đoàn 25 Mỹ “Tia chớp nhiệt đới”, nơi xuất phát
 
các cuộc hành quân càn quét ra vùng Củ Chỉ, Bầu Bàng sang đến Bến
Cả, Bến Súc, Tây Ninh. Sau này, khi Mỹ buộc phải cuốn cờ, sư đoàn
“Tia chớp nhiệt đới” bàn giao cơ ngơi lại cho sư đoàn 25 ngụy, một
trong những sư đoàn chủ lực mạnh của quân lực Sài Gòn. Đề bảo đảm
an toàn cho Đồng Dù, Mỹ - ngụy đã đánh phá, hủy diệt vùng Củ Chỉ,
biến vùng này thành một vùng trắng. Đứng từ đài quan sắt của căn cứ
pháo binh sư đoàn 25 trong căn cứ Đồng Dù có thể nhìn thông suốt
hàng chục kilômét. Xung quanh căn cứ, chúng bố trí một hệ thống
hàng rào và vật chướng ngại phòng thủ rất kiên cố và phức tạp với
gần chục lớp rào kẽm gai đủ các kiểu: bãi mạ, lò xo, bùng nhùng,
mái nhà... và gài mìn bẫy dày đặc. Sau hàng rào là hai lớp tường đất
kiên cô có các lô cốt, ụ súng. Tiếp đó đến hệ thống phòng thủ nội vi,
bao gồm hàng trăm lô cốt, ụ súng và hàng ngàn mét hào giao thông
nói liền các phân khu. Bên trong căn cứ rộng 8 kilômét vuông, chia
thành từng ô bàn cờ, có đường cơ động cho xe tăng, xe bọc thép và
có cả một sân bay hạng vừa, máy bay vận tải C130 và các loại máy
bay chiến đấu có thể hạ cánh được. Hệ thống thông tin liên lạc trong
căn cứ và liên lạc với mọi nơi cần thiết được thiết kế một cách hoàn
hảo. Trung tâm viễn thông của căn cứ Đồng Dù là một trong những
trung tâm lớn và hiện đại ở miền Nam Việt Nam.
 
Về lực lượng địch, trong căn cứ thường xuyên có một đến hai
trung đoàn bộ binh đóng giữ. Ngoài ra còn một trung tâm huấn luyện
tân binh và hạ sĩ quan, các tiểu đoàn trực thuộc của sư đoàn như
công binh, pháo binh, thiết giáp, thông tin, trinh sát. Căn cứ pháo
binh trong Đồng Dù là một căn cứ lớn có đến 18 khẩu pháo các loại,
trong đó có 4 khẩu 174 “vua chiến trường”.
 
Hệ thống phòng thủ khu vực Củ Chỉ và căn cứ Đồng Dù là một
hệ thống phòng thủ chặt chẽ, chu đáo, có hỏa lực mạnh, lực lượng
đông, có các căn cứ phụ cận sẵn sàng chỉ viện và có đường cơ động
hết sức thuận lợi. Chính vì vậy mà đã bao năm, chúng kết hợp với
bọn ngụy quyền địa phương kìm kẹp nhân dân, đàn áp phong trào
cách mane ở Củ Chỉ và vùng xunø manh hắt sức tàn han đã man
 
Nhân dân Củ Chỉ, đưới sự lãnh đạo của Đảng và chính quyền
cách mạng đã bao năm chiến đấu hết sức kiên cường, bám trụ vững
vàng trên mảnh đất đầy thương tích ấy. Lực lượng vũ trang cách
mạng địa phương đã trưởng thành từ trong máu lửa, nhân dân được
giác ngộ và tôi luyện trong đấu tranh. Đó là những yếu tổ hết sức
thuận lợi đôi với cuộc chiến đâu sắp tới của sư đoàn.
 
Trong trận quyết chiến này, Bộ tư lệnh sư đoàn quyết định sử
dụng lực lượng như sau:
 
Trường hợp địch chưa tăng cường lực lượng về Đồng Dù, sư
đoàn sử dụng Trung đoàn 48 tăng cường một đại đội xe tĩng cùng
với pháo binh sư đoàn và pháo binh cấp trên tăng cường tiền công
tiêu điệt căn cứ Đồng Dù; đột phá trên hai hướng: mũi chủ yêu từ
tây bắc, mũi thứ yêu từ tây nam đánh vào. Trung đoàn 9 và một đại
đội xe tăng làm dự bị đánh phát triển và đánh quân địch vòng ngoài.
Trung đoàn 64 đánh chiếm khu vực cầu Bông, cầu Sáng và phát triển
lên quận ly Hóc Môn theo nhiệm vụ Quân đoàn giao ở giai đoạn một
của chiến dịch.
 
Trường hợp địch tăng cường lực lượng về Đồng Dù và khu vực
xung quanh, sư đoàn dùng cả hai trung đoàn bộ binh cùng với Trung
đoàn 54 pháo binh và các đơn vị tăng cường tập trung tiêu diệt bằng
được căn cứ Đồng Dù, mở đường cho sư đoàn bạn đánh vào Tân Sơn
Nhất, sau đó sẽ phát triển theo kế hoạch.
 
Tiểu đoàn 1 Trung đoàn 48, đơn vị có truyền thống mở cửa, lần
này được giao nhiệm vụ đột phá hướng chủ yếu (hướng tây bắc).
 
Theo phương. án, đầu tiên sẽ dùng bộc Má đánh đồng loạt và liên
tục để mở rào; cấp trên chưa có ý kiến gì về việc dùng mìn phá rào.
Đại đội 3, đại đội có nhiệm vụ mở cửa và đánh chiếm đầu cầu, được
lệnh khẩn trương gói buộc bộc phá. Mặt khác, tiểu đoàn vẫn đề nghị
cấp trên nghiên cứu phương án dùng mìn mở rào.
 
Mọi việc chuẩn bị đã hoàn thành. Theo hiệp đồng, pháo chiến
 
Ai^h 4ã lên mìo hắn nhá căn eœ Đồng Dù trong mấy ngày liền.
 
Đơn vị bạn đã cắt đường từ Tây Ninh xuống và từ Hậu Nghĩa sang.
Ngày 27 tháng 4, sư đoàn được tin tên chuẩn tướng Lý Tòng Bá đã
điện cho trung đoàn 50 đưa lực lượng từ ấp Khói về phòng thủ Đồng
Dù và điện cho trung đoàn 10 thiết giáp sẵn sàng cơ động.
 
Sư đoàn quyết định đánh Đồng Dù theo phương án hai: địch có
tăng cường phòng thủ.
 
17 giờ ngày 28 tháng 4, các đơn vị tham gia chiến đấu được lệnh
chuẩn bị hành quân vào chiếm lĩnh. Pháo của ta vẫn tiếp tục bắn phá.
Căn cứ Đồng Dù bốc cháy ngùn ngụt. Số phận sư đoàn 25 ngụy đã
được định đoạt.
 
3 giờ sáng ngày 29 tháng 4 năm 1975, Sở chỉ huy sư đoàn như
lắng lại, hồi hộp chờ đợi giờ nổ súng. Phó tư lệnh Quân đoàn Kim
Tuấn cũng có mặt tại sở chỉ huy sư đoàn, trực tiếp chỉ huy trận đánh.
Sư đoàn trưởng, chính ủy sư đoàn đã sẵn sàng ở vị trí chỉ huy. Phó
sư đoàn trưởng Ngô Huy Phát, theo phân công, trực tiếp đi với sở
chỉ huy Trung đoàn 48.
 
10 giờ 30 phút là giờ hiệp đồng với Sư đoàn 10 của Quân đoàn,
là giờ Sư đoàn 320 phải cơ bản làm chủ căn cứ Đồng Dù để Sư đoàn
10 vượt qua cửa mở này tiến vào tiến công Tân Sơn Nhát. Từ 5 giờ
30 đến 10 giờ 30 chỉ có năm giờ đồng hồ để dứt điểm một căn cứ
rộng 8 kilômét vuông được phòng thủ kiên cố quả là một nhiệm vụ
nặng nè. Nhưng các chiến sĩ ta quyết đánh với quyết tâm cao nhất.
Đúng giờ quy định, cùng một lúc tất cả các trận địa pháo của sư
đoàn và pháo tăng cường cho sư đoàn đồng loạt nỗ súng. Tiếng đại
bác gầm lên dữ dội theo phương án hiệp đồng với bộ binh. Kế hoạch
hỏa lực được chia làm nhiều giai đoạn theo một phương án được tính
toán rất tỉ mi.
 
Ra lệnh cho pháo bắn xong, sư đoàn trưởng tiếp tục ra lệnh
cho các hướng bộ binh cho điểm hỏa đồng loạt, bát đầu thực hành
 

 
phá rào. mở cửa và ra lệnh cho xe tăng, pháo cao xạ vào chiêm lĩnh
trận địa và tuyến xuất phát xung phong.
 
6 giơ. Trung đoàn 9 báo cáo vẻ có hiện tượng địch phản kích,
Tiểu đoàn 4 đã tiêu diệt một trung đội địch từ công tây nam tiến ra.
7 giờ, đài kỹ thuật sư đoàn báo cáo địch cho Tiểu đoàn 3 Trung đoàn
50 ở xóm Mới và một chỉ đội thiết giáp lên phản kích. Có thể bọn
này sẽ đánh vảo phía sau đội hình Trung đoàn 9 trong khi hướng đột
phá của trung đoàn chưa mở cửa xong.
 
Trong khi ấy, trên hướng chủ yếu của trận đánh, cuộc chiến đấu
đang diễn ra vô cùng quyết liệt. Đại đội 3 Tiêu đoàn I do đại đội
trưởng Tràn Nhật Tăng và chính trị viên Đào Xuân Sáng chỉ huy
đang tô chức lại hỏa lực chuân bị cho các bộc phá viên lên phá nốt
những hàng rào cuối cùng. Mìn liên kết nỗ tốt, một mảng rào rộng
gần chục mét gồm bốn lớp đã bị phá bung. Nhưng các hỏa điêm địch
đã tập trung tưới lửa lên cửa mở. Dùng máy thông tỉn vô tuyến liên
lạc trực tiếp với trung đoàn, đại đội trưởng Trần Nhật Tăng yêu cầu
trên băn chi viện lên khu vực đầu cầu. Đẻ nghị được chấp thuận. Đạn
pháo cua ta tới tấp rót lên khu vực đầu cầu. Trong khi đó các bộc phá
viên đã sẵn sàng. Trung đội trưởng trung đội bộc phá Nguyễn Hữu
Dóng dẫn bộc phá viên Nguyễn Văn Chung lên cửa mở.
 
Mặc đại liên, phóng lựu địch ken dày, Nguyễn Văn Chung, Trần
Văn Minh rồi Nguyễn Khắc Bảo không một chút do dự, ôm mìn lao
lên. Từ phía sau, chính trị viên Đào Xuân Sáng bình tĩnh chỉ huy các
tổ hỏa lực bắn yêm trợ cho Bảo. Bỗng một chùm M79 nô tóe trước
mặt. Bảo ngã vật xuống. Trong giây lát, Bảo lại bật dậy, lao lên đặt
mìn vào hàng rào rồi chạy trở lại. Trái mìn nỗ tung. Hàng rào bị xé
toang, Bảo loạng choạng, chới với rồi ngã vật ra. Quyết không để
trận đánh bị gián đoạn, chiến sĩ bộc phá số 4 Nguyễn Văn Lĩnh ôm
mìn lao lên cửa mở... Nhưng cũng như Nguyễn Khắc Bảo, Nguyễn
Văn Lĩnh đã ngã xuống sau khi hàng rào cuối cùng bị phá toang.
 
- Hãy trả thù cho các đồng chí đã hy sinh! Tắt cả tiến lên!
 
Tiếng hô của chính trị viên Sáng vang lên đõng dạc. Cả đại đội 3
ào ạt đánh lên cửa mở.
 
Thấy tình hình vô cùng nguy ngập, bọn địch trong căn cứ lồng
lên. Chúng tập trung pháo, cối, 12,8mm, đại liên, M79 tưới lửa lên
cửa mở, đồng thời điều xe tăng ra, chuẩn bị bịt cửa mở. Tiểu đoàn
trưởng Nguyễn Quang Vinh điện về báo cáo với trung đoàn trưởng
Lê Quang Bình: “Địch đang bịt cửa mở. Tình hình rất căng thẳng.
Tôi xin phép được lên trực tiếp chỉ huy đột phá. Đồng chí phó tham
mưu trưởng trung đoàn sẽ thay tôi nắm sở chỉ huy, giữ liên lạc với
trung đoàn”. Được trung đoàn trưởng chấp thuận, tiểu đoàn trưởng
Vinh bàn giao công việc cho phó tham mưu trưởng trung đoàn rồi
lao lên cửa mở.
 
Đại đội 3 bắt đầu đột phá. Trung đội trưởng trung đội thọc sâu Vũ
Văn Sơn đang tổ chức lại hỏa lực. Nhưng hễ một xạ thủ nào nhỏm
đậy định bắn là lập tức bị đại liên địch quật ngã. Ác nhất là hai khẩu
12,8mm trên hai chiếc xe tăng chôn ngầm trong bờ tường đất. Từ
vị trí có lợi, chúng có thể kiềm chế toàn bộ khu vực cửa mở. Không
thể để tình trạng này kéo dài. Sơn quan sát lại và nhận ra rằng vì taở
dưới sườn đốc bắn lên nên đường đạn ăn cao, không thể găm trúng
chiếc xe quái ác ấy được.
 
Lại một vài đồng chí nữa trúng đạn. Sơn bậm môi suy nghĩ rồi bò
lên nhặt một khâu B40 của một xạ thủ vừa bị thương. Anh nằm dán
mình xuống đất, căng mắt quan sát vị trí chiếc xe tăng địch. “Phải
đứng dậy mà bắn!” - Sơn tự nhủ thầm - “Nếu không đứng dậy bắn
thì không thể bịt mồm nó được. Nhưng, đứng dậy trong lúc hỏa lực
địch đang ken dày thế này... nguy hiểm! Nhưng... Không còn cách
nào khác. Phải đứng thăng dậy. Một khoảnh khắc thôi. Miễn là đừng
trúng đạn trước khi mình siết cò!”. Sơn nghĩ vậy rồi kiểm tra lại súng
lựa thế nằm. Một... hai... ba! Đột ngột và bắt ngờ, Vũ Văn Sơn bật dậy,
 

 
đứng sừng sững phía trước cửa mở. Có lẽ chỉ trong một giây lát. Cái
giây lát Ấy hãn thẳng địch bên trong bờ thành đất đã nhìn thấy anh.
Chúng đã băn như vãi đạn. Nhưng... Sơn đã kịp siết cò. Trái đạn B40
từ nòng súng của anh lao vút ra, như cắm thăng vào bờ thành đất, nơi
chiếc xe tăng địch đang ấn nắp. Một đụn khói đen bốc lên sau tiếng
nồ đữ dội. Bị đánh một cú bắt ngờ, địch choáng váng trong giây lát.
Chính trị viên Sáng chớp thời cơ ra lệnh cho bộ đội xung phong. Các
chiến xì đại đội 3 bật dậy. Nhưng, chi vượt được chừng hai chục mét,
họ lại bị hỏa lực địch đánh bật trở lại.
 
Tiêu đoàn trưởng Vinh báo cáo về trung đoàn xin pháo băn lần
thứ hai. Đại đội 3, sau ba đợt xung phong, vẫn chưa đánh chiếm
được khu vực đầu cầu. Hỏa lực địch vẫn còn rất mạnh và bắn rất tập
trung vào khu vực cửa mở.
 
§ giơ, trung đoàn lệnh cho đại đội xe tăng đi với hướng chủ yếu
vào tham gia đột phá. Nhưng chiếc xe tăng đi đầu vừa chồm tới cửa
mở đã bị súng chống tăng của địch từ bên trong bắn trúng. Chiếc thứ
hai bị hỏng xích ngay ngoài hàng rào. Đại đội trưởng xe tăng trực
tiếp chỉ huy chiếc thứ ba lao vào tiếp tục cùng Đại đội 3 đột phá.
 
Đợi xung phong thứ tư rồi đợt xung phong thứ năm. Đại đội 3
lọt được một bộ phận vào bên trong bờ tường đất. Địch từ hai phía
tràn ra tiếp tục bịt chặt cửa mở. Xe tăng và các bộ phận phía sau vẫn
không lọt vào được. Tiểu đoàn trưởng Nguyễn Quang Vinh báo cáo
với trung đoàn xin đưa đại đội 1 vào tiếp tục đột phá. Trong khi ấy,
Đại đội 3 do chính trị viên Sáng chỉ huy vẫn tiếp tục phát triển vào
bên trong. Đại đội 1 tiếp tục đột phá đánh chiếm rộng thêm khu vực
đầu cầu rồi đưa xe tăng lên.
 
8 giờ 30 phút, Đại đội 3 báo cáo đã phát triển đến khu vực bãi xe
của tiểu đoàn công binh nhưng đạn đã sắp hết. Thương binh nhiều.
Sức chiến đấu giảm sút. Chính trị viên Đào Xuân Sáng, trung đội
trưởng Vũ Văn Sơn đã bị thương. Tiểu đoàn trưởng Vinh liền ra lệnh
 
cho Đại đội 3 dừng tại chỗ, củng có vị trí đứng chân, đưa thương
bính ra, cho Đại đội 1 tiếp tục thọc sâu vào căn cứ và đưa nốt Đại
đội 2 vượt qua khu đầu cầu vào đánh chiếm khu vực bãi tập.
 
Trận đánh diễn ra mỗi lúc một thêm quyết liệt.
 
Ở hướng thứ yếu, Tiểu đoàn 3 Trung đoàn 48 vẫn chưa vào được
trong căn cứ.
 
Hướng Trung đoàn 9 vẫn tiếp tục đánh phản kích. Các chiến sĩ
Tiểu đoàn 16 súng máy cao xạ đã hạ nòng pháo cùng với Tiểu đoàn 5
diệt hàng trăm tên địch. Nhưng địch vẫn tiếp tục đưa lực lượng phía
sau lên, hy vọng có thể bẻ gãy hướng tiến công của ta, chỉ viện cho
đồng bọn trong căn cứ.
 
Địch trong căn cứ kháng cự quyết liệt. Tên chuẩn tướng Lý Tòng
Bá vẫn bám máy, chỉ huy. Các chiến sĩ trinh sát kỹ thuật của ta vẫn
nghe rõ tiếng hắn hò hét trên vô tuyến điện.
 
9 giờ, trinh sát kỹ thuật báo tin Lý Tòng Bá ra lệnh cho trung
đoàn 46 ở Trảng Bàng, Đồng Chùa về gấp cứu nguy cho Đồng Dù.
 
Trước tình hình ấy, Bộ tư lệnh sư đoàn ra lệnh:
 
- Kiên quyết tập trung lực lượng, đưa thêm lực lượng vào hướng
Tiểu đoàn 1 Trung đoàn 48 thọc sâu vào sở chỉ huy Sư đoàn 25 ngụy
và phát triển sang hướng Tiểu đoàn 3 Trung đoàn 48 và hướng Trung
đoàn 9, hỗ trợ cho hai hướng này phát triển.
 
- Đội dự bị của sư đoàn gồm Tiểu đoàn 2 Trung đoàn 48 và 8
chiếc xe tăng theo hướng Tiểu đoàn 1 phát triển vào đánh bung ra,
chiếm các mục tiêu bên trong, hỗ trợ cho Tiểu đoàn 1 thọc sâu vào
sở chỉ huy và hai hướng thứ yếu phát triển vào.
 
- Trung đoàn 9 xốc lại đội hình Tiểu đoàn 5, tiếp tục đột phá;
dùng Tiểu đoàn 4 và Tiểu đoàn 16 súng máy cao xạ ngăn chặn và
tiêu diệt địch từ Áp Mới phản kích xuống.
 

 
-_ Pháo binh tiếp tục băn chỉ viện cho bộ binh trên tất ca các hướng.
 
Tiêu đoàn ! tiếp tục phát triển vào tung thâm mặc dù đã bị thương
vong khá nhiều. Lúc này cán bộ chỉ huy tiêu đoàn chỉ còn tiểu đoàn
trưởng Nguyễn Văn Quang chưa bị thương. Chính trị viên Nguyễn
Văn Thư tuy bị thương vẫn không rời vị trí của mình. Vĩnh và Thư
nắm lại tình hình, quyết định cho Đại đội 1 còn sung sức tiếp tục
phát triên, đồng thời cúng có những khu vực Đại đội 3 và Đại đội 2
chiêm được, mở đường cho xe tăng lên. Nhưng, đứng trong một căn
cứ rộng mênh mông, nhà cửa san sát như một thành phó, thật khó
xác định được đâu là sở chỉ huy địch. Vinh tìm vị trí có lợi quan sát
toàn khu vực một lát rồi gọi đại đội trưởng Nguyên tới, chi về phía
trước, ra lệnh: ''*Cứ nhằm hướng có cái cột ăng-ten lớn kia mà tiến!”.
Đại đội trường Nguyên năm lại đội hình, phân chia cán bộ đại đội đi
theo từng mũi rồi cho đại đội xung phong đọc theo con đường trục
lớn vào trung tâm.
 
Vượt qua khu vực Đại đội 3 đã đánh qua, Đại đội I bắt đầu gặp
hỏa lực địch ngăn chặn. Đề tạo sức đột phá mạnh, đại đội trưởng
Nguyên chủ trương đồn các xạ thủ lên phía trước để mình trực tiếp
chí huy. Xạ thủ B40 Phạm Hữu Hợp luôn bám sát đại đội trưởng,
liên tiếp điệt các hỏa điểm địch, tạo điều kiện cho đại đội đột phá.
Qua khỏi khu vực tiêu đoàn công binh, các hỏa điểm địch từ bên kia
đường (khu sở chỉ huy sư 25) tập trung băn chặn mũi thọc sâu của
Nguyên. Một lần nữa Nguyên lại phát huy sức mạnh của đội xạ thủ.
Một mặt anh tìm cách liên lạc với phía sau, chỉ mục tiêu cho pháo
binh và xe tăng, một mặt dùng cối 60 của đại đội băn kìm chân bọn
bộ binh đề cho các xạ thủ tập trung tiêu diệt các hỏa điểm. Các xạ
thủ Tĩnh, Hợp, Lịch, Mãn nhanh chóng dập tắt các hỏa điểm địch.
Bọn bộ binh bị cối bắn rát cũng hốt hoảng tháo chạy ra hướng sân
bay. Đường vào khu vực sở chỉ huy sư đoàn 25 ngụy đã mở. Đại đội
trưởng Nguyên bật dậy, lệnh cho đơn vị xung phong chiếm sở chỉ
huy địch.
 
Các chiến sĩ xe tăng theo sát bộ binh, tiếp tục dùng pháo và
đại liên trên xe bắn áp đảo địch cho bộ binh xung phong. Xạ thủ
Phạm Hữu Hợp giương cao lá cờ truyền thống của sư đoàn, lúc này
đã ướt đẫm máu của các chiến sĩ tiểu đoàn Đống Đa kiên cường, lao
về phía trước.
 
Những tên sĩ quan, tên lính ngoan có kháng cự đẻu bị tiêu diệt.
Nguyên dẫn đầu mũi thọc sâu của đại đội 1 đã đứng trước cửa nhà
chỉ huy của tên chuẩn tướng Lý Tòng Bá.
 
- Sở chỉ huy địch đây rồi! Các đồng chí!... Phát triển sâu vào bên
trong, kiểm tra kỹ, tìm cho ra Lý Tòng Bá!
 
Ra lệnh cho các chiến sĩ xong, Nguyên hỏi hộp cầm máy báo cáo
về sở chỉ huy trung đoàn:
 
- Đại đội 1 Tiểu đoàn Đống Đa đã chiếm được sở chỉ huy sư
đoàn 25 ngụy. Tên Lý Tòng Bá và bộ tham mưu của hắn đã bỏ chạy.
Chúng tôi đang truy lùng! Xin chỉ thị.
 
Sở chỉ huy sư đoàn sôi nổi hẳn lên khi nhận được báo cáo đại
đội 1 Tiểu đoàn 1 Trung đoàn 48 đã chiếm được sở chỉ huy sư đoàn
25 ngụy, những tuyến đề kháng cơ bản đã bị đập tan, quân ta từ các
hướng đang tràn vào căn cứ tiếp tục truy quét địch.
 
Cửa mở vào Sài Gòn đã thông, được lệnh của Bộ tư lệnh Quân
đoàn, Sư đoàn 10 bộ binh bắt đầu hành tiến. Các chiến sĩ Sư
đoàn 10 cùng với pháo binh, xe tăng ào ạt hành quân qua cửa mở
Đồng Dù. Ngôi trên xe, các chiến sĩ Sư đoàn 10 nhìn thấy khói
lửa vẫn còn bốc lên ngùn ngụt trong căn cứ Đồng Dù. Tiếng súng
truy quét tàn binh địch của các chiến sĩ 320 vẫn còn rộ lên từng
chặp. Khi đi ngang qua sở chỉ huy Sư đoàn 320, sư đoàn trưởng
Sư đoàn 10 cho xe dừng lại, chạy vào chúc mừng chiến công của Sư
đoàn Đồng Bằng, sư đoàn mà đồng chí đã nhiều năm làm chiến sĩ
và từ đó trở thành người cán bộ chỉ huy cấp sư đoàn... Hai sư đoàn
trưởng chúc mừng nhau và hẹn gặp nhau tại Sài Gòn.
Chiều ngày 17 tháng 3, Trung đoàn 141 tổ chức đợt tiến công thứ
hai. Trước sức tiến công của ta, quân địch phải bỏ khu quân sự và
trận địa pháo, chạy vào các “gộp đá”. Đại đội 7 chiếm thêm hai “gộp
đá” nữa, tiến sát núi đá Ba Chồng và núi đá Ông Phật.
 
Sáng ngày 18 tháng 3, sau một đêm củng có lực lượng, nghiên
cứu thêm cách đánh, sư đoàn trưởng lệnh cho các đơn vị tiếp tục
tiến công.
 
Sau khi giải phóng Định Quán, chấp hành mệnh lệnh của
Bộ tư lệnh Miền, Sư đoàn 7 chỉ để lại một tiểu đoàn của Trung
đoàn 209, đơn vị có kinh nghiệm chốt chặn đường 13 năm 1972 ở
lại phía bắc Túc Trưng, ngăn chặn chiến đoàn 52 (sư đoàn 18 ngụy).
Ngày 24 tháng 3, toàn bộ lực lượng của Sư đoàn chia thành hai mũi
tiến lên thị xã Lâm Đồng.
 
l4 giờ ngày 27 tháng 3, đại đội I1 (Tiểu đoàn 6, Trung
đoàn 165) có 3 xe tăng dẫn đầu diệt đồn bảo an Đa Gùi (nam Đắc Oai
7km), sau đó phát triển diệt các đồn dân vệ từ Đa Gùi đến Đắc Oai
làm rung chuyên hệ thống đồn bốt địch trên đường 20, tạo điều kiện
cho Tiêu đoàn 5 tiêu diệt địch ở yêu khu Đắc Oai.
 
Đêm 27 rạng ngày 28 tháng 3, đội hình tiến công bằng cơ giới
của Sư đoàn 7 nhanh chóng phát triên lên hướng Lâm Đồng. Đi đầu
là các đội trinh sát, xe tăng, bộ binh và công binh. Tiếp theo là lựu
pháo và côi l60mm,
 
( giờ ngày 28 tháng 3, pháo I30 bắt đầu bắn vào sân bay và các
mục tiêu quân sự ở phía bắc thị xã, chi viện hỏa lực cho Sư đoàn 7
tiền công trong hành tiến. Trước sức tiến công nhanh bằng cơ giới
và hỏa lực mạnh của ta, quân địch ở các chốt dọc đường bỏ chạy vẻ
đèo Ba Cô rôi chạy về thị xã. Tỉnh trưởng Lâm Đồng điều một đại
đội pháo ra cầu Đại Lào, nhưng mới nghe tiếng gầm của xe tăng và
tiếng nô của trọng pháo ta, bọn này bỏ cả súng chạy vào rừng, kéo
pháo chạy trở về thị xã, 4 giờ 30 phút sáng ngày 28 tháng 3, cánh
quân đột phá trên đường 20 bắt được liên lạc với Trung đoàn 141 ở
mũi vu hồi. Phát hiện quân địch đang hoảng loạn và lực lượng tiến
công đã đến đủ, chỉ huy Sư đoàn 7 lệnh cho các đơn vị nỗ Súng sớm
hơn một giờ so với kế hoạch ban đầu.
 
Trời hửng sáng. Pháo ta bắn cấp tập vào các mục tiêu quân sự
trong thị xã. Bộ binh có xe tăng dẫn đầu chia thành hai mũi đột phá
và thọc sâu đánh chiếm từng mục tiêu. Lực lượng địch giữ thị xã
có gần 4.000 tên được trang bị đầy đủ, có hệ thống công sự kiên cố
nhưng không còn tỉnh thần chiến đầu, đã bị ta tiêu diệt một số, phần
lớn tan rã, bỏ chạy về Di Linh và tản mát vào rừng, thị xã Lâm Đồng
được giải phóng lúc 9 giờ ngày 28 tháng 3.
 
Ngày 3I tháng 3, Trung đoàn 165 được tăng cường 3 xe tăng,
2 khẩu pháo 105, một khẩu pháo 85 hành quân bằng cơ giới đánh
chiếm khu Di Linh, diệt và làm tan rã 3 tiểu đoàn địch. Sau đó,
Trung đoàn được lệnh dừng lại đề quay về Long Khánh. Toàn tỉnh
Lâm Đồng đã được giải phóng. Ý để của địch lập tuyến phòng thủ
 
Sài Gòn từ xa, bắt đầu từ Tây Ninh qua Lâm Đồng đến Nha Trang
bị đập tan.
 
Đường số 20 từ Lâm Đồng đến Túc Trưng hoàn toàn do ta làm
chủ. Một trong những điểm phòng thủ mạnh của địch trên hưởng
này là chi khu quân sự Định Quán bị ta đánh chiếm. Quân đoàn 4
cùng lực lượng vũ trang các địa phương đã mở thêm một hành lang
chiến lược để cơ động lực lượng và binh khí kỹ thuật vào chiến
trường trọng điểm, tạo thêm một bàn đạp tiến công Sài Gòn trên
hướng đông bắc.
 
©) Trên hướng Xuân Lộc - Biên Hòa
 
Quân đoàn 4 giao nhiệm vụ cho Sư đoàn 341 trên hai hướng
đường 20 từ cầu La Ngà đến ngã ba Dầu Giây và thị xã Xuân Lộc
(tỉnh Long Khánh) chuẩn bị mọi mặt để khi có lệnh sẽ đánh tập trung
tiêu diệt lớn.
 
Sư đoàn 341 đảm nhiệm tiến công vào phòng tuyến bảo vệ Sài
Gòn từ xa của địch. Lực lượng của chúng gồm ba sư đoàn bộ binh
18, 25, 5 và các đơn vị biệt động quân, lính thủy đánh bộ, các chi
đoàn xe tăng, thiết giáp, pháo binh. Các lực lượng này chưa bị đánh
đau, còn sung sức và ngạo mạn, chúng lại được lực lượng không
quân các sân bay Biên Hòa, Tân Sơn Nhất, Cần Thơ chí viện tối đa.
 
Căn cứ vào nhiệm vụ trên giao, sư đoàn tổ chức thành
ba bộ phận:
 
- Một bộ phận do tham mưu trưởng Vũ Thang, phó chính ủy
Phạm Thành Minh trực tiếp chỉ huy Trung đoàn 273 thay thế Trung
đoàn 1 Sư đoàn 9, hoạt động tại khu vực Dầu Tiếng - Chơn Thành -
đường 13 (tỉnh Tây Ninh).
 
- Một bộ phận do sư đoàn trưởng Trần Văn Trân, phó tham mưu
trưởng Hồ Đình Quý cùng trung đoàn trưởng các Trung đoàn 270,
266, 55 và các cơ quan đi chuẩn bị chiến trường ở hướng đường 20
- Bà Rịa - Long Khánh.
 
- Một bộ phận do chính ủy Trần Nguyên Độ, phó tư lệnh Vũ
Cao cùng chủ nhiệm chính trị, chủ nhiệm hậu cần và một sô cán bộ
cơ quan chi huy bộ đội vào vị trí tập kết và tổ chức huắn luyện cho
chiến sĩ mới.
 
Ngày 4 tháng 3 năm 1975, Trung đoàn 273 thay Trung đoàn l
Sư đoàn 9 bảo vệ thị trấn Dầu Tiếng vừa được giải phóng,
đồng thời chốt chặn, đánh địch, bảo vệ đoạn đường từ Bầu Bàng đến
Chơn Thành (trên đường 13).
 
Lực lượng địch tại đây gồm liên đoàn 32 biệt động quân ở An
Lộc, liên đoàn 31 biệt động quân ở Chơn Thành, tiêu đoàn 366 bảo
an ở xóm Rớt, tiêu đoàn 36 biệt động ở nam xóm Rớt, chiến đoàn 7
và Ñ của sư đoàn 5 cùng với chỉ đoàn xe tăng 182 ở Bầu Bàng. Sở
chỉ huy sư đoàn 5 đóng ở Lai Khê - Bến Cát. Với lực lượng đông đặc
và thế đứng chân như vậy, địch hy vọng có đủ khả năng “phong tỏa”
kiểm soát con đường, bảo vệ Sài Gòn từ phía bắc.
 
Sau khi được Sư đoàn 9 cung cấp tình hình và qua báo cáo của
bộ phận cán bộ chuẩn bị chiến trường, Trung đoàn 273 thống nhất
sử dụng lực lượng như sau: Tiểu đoàn 2 do tiểu đoàn trưởng Nguyễn
Văn Phú, chính trị viên Đặng Tổ chỉ huy, vào tiếp quản và bảo vệ
quận ly Dầu Tiếng. Lực lượng còn lại có nhiệm vụ chốt chặn, giữ
vững con đường 13 từ xóm Rớt về Bầu Bàng, bảo vệ con đường cơ
động của ta từ miền Đông sang miền Tây Nam Bộ.
 
Đêm 5 tháng 3, các đơn vị hành quân tới vị trí và suốt đêm ấy
khẩn trương xây dựng trận địa chốt.
 
Chốt chặn được 20 ngày thì nhiệm vụ của trung đoàn phát triển.
Ngày 25 tháng 3, phó tham mưu trưởng Quân đoàn 4 Lê Ngọc Bì
giao cho Trung đoàn 273: “Ngoài nhiệm vụ chốt giữ, không cho
địch từ Bầu Bàng lên và từ Chơn Thành chạy về, trung đoàn sử dụng
một lực lượng cùng với Sư đoàn 9 tham gia đánh vào chỉ khu quân
sự quận ly Chơn Thành”. Nhận được lệnh, Trung đoàn 273 sử dụng
 

 
Tiểu đoàn I đo Tiểu đoàn trưởng Chu Đức Hùng và chính trị viên
Đặng Xuân Lợi chỉ huy, làm nhiệm vụ chốt giữ, đánh địch từ Bầu
Bàng lên ứng cứu cho quận ly Chơn Thành.
 
Đại đội 11 do đại đội trưởng Hoàng Văn Ảnh và chính trị viên
Nguyễn Trọng Phú chỉ huy, tiến công tiêu diệt địch tại xóm Rớt
(nam Chơn Thành 3km).
 
Tiểu đoàn 2, đại đội 9 và đại đội 10 của Tiểu đoàn 3 đánh vào
Chơn Thành dưới sự chỉ huy của tham mưu trưởng sư đoàn Vũ
Thang và phó trung đoàn trưởng Trung đoàn 273 Nguyễn Văn Giáp.
 
Đúng 5 giờ 30 ngày 31 tháng 3, tiếng súng tiến công vào chỉ khu
quân sự quận ly Chơn Thành bắt đầu.
 
Đến tối ngày 3l tháng 3, Quân đoàn ra lệnh cho các lực lượng
chuyển sang vây ép; dùng pháo binh bắn phá liên tục vào các mục
tiêu trong chí khu, gây cho chúng nhiều tổn thất.
 
7 giờ sáng ngày 1 tháng 4, hai tiểu đoàn thuộc chiến đoàn 8
và 20 xe tăng của sư đoàn 5 địch từ Bầu Bàng lên ứng cứu cho
đồng bọn đang bị vây ép tại quận ly Chơn Thành. Chúng vừa lò
dò tới ấp Xà Mách đã lọt vào trận địa phục kích của Tiểu đoàn 1,
bị diệt gọn hai đại đội, bắt sống 103 tên, bắn cháy 5 xe tăng. Số còn
lại tháo chạy về Bầu Bàng. Âm mưu chỉ viện cho Chơn Thành của
địch bị bẻ gãy.
 
22 giờ 40 phút ngày 1 tháng 4, Bộ tư lệnh Quân đoàn 4 thông
báo: “Địch ở Chơn Thành bỏ chạy, Sư đoàn 9 đang truy kích trên
hướng ra Sông Bé”. Quân đoàn lệnh cho Trung đoàn 273 chuẩn bị
đón đánh địch từ Chơn Thành chạy về Bàu Bàng; đồng thời không
cho cánh quân địch từ Bầu Bàng lên đón đám tàn quân ở Chơn
Thành chạy về.
 
Trung đoàn 273 bố trí lại lực lượng theo phương án chiến đấu
mới. Toàn trung đoàn bí mật chuẩn bị trận địa với tư tưởng chỉ đạo:
 
