Năm vững thời cơ. vận động nhanh. hiệp đồng chặt chẽ nhanh chóng
bao vây chia cắt, tiêu diệt gọn từng bộ phận, tiền tới tiêu điệt toàn bộ
quân địch. làm chủ chiến trường.
 
2 giờ sáng ngày 2 tháng 4, các đơn vị đã chuẩn bị xong và sẵn
sàng chiến đấu.
 
4 giờ 30 phút, một tốp địch lọt vào trận địa cối 82 của Đại đội 14.
Ta nô súng, diệt một tên đại úy, bắt sống hai tên, có một thiểu úy. Tù
binh khai: tiểu đoàn 366 bảo an và một số tàn binh của tiêu đoàn 31
biệt động quân được lệnh bỏ xóm Rớt rút chạy về Bầu Bàng lúc
20 giờ ngày l tháng 4. Hiện đang hành quân phía sau. Trung đoàn
trương Hoàng Trung Trực lệnh cho các đơn vị chuân bị chiến đấu.
 
Š giờ 15 phút ngày 2 tháng 4, đại đội đi đầu của địch lọt vào trận
địa phục kích của đại đội 14. Lập tức đại đội 14 nỗ súng tiến công.
Bị đòn phủ đầu, bọn địch hốt hoảng chạy sang hướng tây bị đại đội
16 hạ nòng 12,7mm bắn quét, diệt một số lớn. Lúc này Tiểu đoàn 3
và đại đội 20 cũng bắt đầu nô súng.
 
Từ phía tây, tây nam đường 13, các đại đội 9, 14, 16, 20 đánh
sang. Phía đông đường 13, các đại đội 10, 11 đánh tới. Bọn địch bị
đòn bất ngờ, rỗi loạn đội hình, tìm đường tháo lui. Các chiến sĩ ta cắt
địch ra mà đánh. Một số tên sống sót kéo nhau chạy trở lại hướng
Chơn Thành, bị ngay tiểu đoàn 2 từ Chơn Thành chặn lại. Tiểu đoàn
366 bảo an và số tàn quân tiểu đoàn 31 biệt động quân bị tiêu diệt
hoàn toàn.
 
Cũng trong ngày 2 tháng 4, bọn địch điều tiểu đoàn 2 chiến đoàn 8
từ Bầu Bàng lên đón đảm tàn quân trên. Chúng vừa tới ấp Xà Mách,
bị Tiêu đoàn l chặn đánh, diệt tại chỗ 81 tên, bắt sống 23 tên. Tiểu
đoàn 2 địch bị xóa số. Sang ngày 3 tháng 4, Tiêu đoàn I diệt thêm
120 tên. Tiểu đoàn 3 diệt 254 tên, đại đội 2 Sông Lam diệt 86 tên.
Toàn bộ quân địch từ Chơn Thành chạy về Bâu Bàng và từ Bầu Bàng
lên Chơn Thành ứng cứu hoàn toàn bị tiêu điệt và bắt sống.
 

 
Gần một tháng làm nhiệm vụ chốt chặn, trong điều kiện ăn, ngủ
dưới hầm, vật lộn với những cơn khát cháy cổ, với muỗi rừng, với
biết bao nhiêu đợt phản kích, pháo kích ác liệt của địch, các chiến sĩ
Trung đoàn 273 đã kiên cường trụ vững, liên tục đánh địch, giữ vững
chốt. Hành lang vận chuyển từ miền Đông sang miền Tây Nam Bộ
được thông suốt, bảo đảm cho đồng bằng sông Cửu Long có đầy đủ
tiềm lực và khả năng để bước vào cuộc Tổng tiến công và nồi dậy
trong chiến dịch mùa Xuân 1975 lịch sử.
 
Sau khi hoàn thành nhiệm vụ ở hướng đường 13, Trung đoàn 273
lật cánh về tỉnh Long Khánh trong đội hình chiến đấu của sư đoàn ở
mặt trận phía đông Sài Gòn - Gia Định.
 
Ngày 26 tháng 3, Trung đoàn 270 hành quân tới Đồng Xoài thì
được lệnh của Bộ tư lệnh Quân đoàn 4 tiếp tục xuyên rừng đi tiếp
về hướng đường 20 làm lực lượng dự bị cho Sư đoàn 7 và sẵn sàng
đánh địch lắn chiếm các chỉ khu Định Quán, La Ngà, Phương Lâm
do Sư đoàn 7 vừa giải phóng.
 
Từ Đồng Xoài qua Bù Đốp xuyên rừng Mã Đà, đến sáng 18
tháng 3, toàn trung đoàn đã tới bờ sông Đồng Nai. Tại đây, đồng chí
Bùi Cát Vũ, Phó tư lệnh Quân đoàn 4 giao nhiệm vụ cụ thể: “Trung
đoàn 270 (thiếu Tiểu đoàn 6) chốt giữ đường 20 từ cua chữ C đến
Phương Lâm đồng thời cùng với trinh sát sư đoàn nghiên cứu chiến
trường, chuẩn bị cho Trung đoàn 270 đánh vào Túc Trưng và Trung
đoàn 266 đánh vào Gia Tân - Gia Kiệm”.
 
Sau khi Định Quán, La Ngà thất thủ, bọn địch ở Túc Trưng, Kiệm
Tân phải co lại. Đêm 20 tháng 3, chúng cho tiểu đoàn 2 và đại đội
trinh sát của chiến đoàn 52 nống ra lắn chiếm Núi Tràn - một điểm
cao quan trọng án ngữ phía tây cầu La Ngà, phía bắc Túc Trưng
4km, nằm sát đường 20.
 
Về phía ta, Bộ tư lệnh sư đoàn lệnh ngay cho Trung đoàn 270
khẩn trương cơ động lực lượng ra tiêu diệt địch. 4 giờ sáng ngày 3I
 
