10 TRẦN ĐÁNH NỔI TIẾNG TRONG LỊCH SỬ VIÊT NAM
 
tháng 3. tiêu đoàn 5 vượt sông Đồng Nai, áp sát chân Núi Tràn về
phía tây bắc. Hai đại đội của Tiêu đoàn 4 vượt sông La Ngà, áp sát
lộ 20 đông nam Núi Tràn.
 
Ø sơ chỉ huy trung đoàn, trung đoàn trưởng Nguyễn Thể Vân và
chính ủy Lê Nguyễn theo dõi và chỉ đạo chặt chẽ các mũi. Đây là
trận đầu Trung đoàn 270 chiến đấu đánh địch ở dã ngoại.
 
5 giờ sáng ngày 31 tháng 3, hai mũi đột kích của Tiểu đoàn 5
chọc thăng vào trung tâm điểm cao. Mũi của đại đội trưởng đại đội 6
Nguyễn Văn Tý đánh vào khu chỉ huy. Mũi của đại đội trưởng
đại đội 7 Vi Văn Bê đánh hất từ phía tây, tây bắc điểm cao. Địch,
lớp chết, lớp nhốn nháo bỏ chạy xuống chân đồi, bị đại đội 1
và đại đội 2 chặn đánh. Kết quả hai đại đội địch bị diệt gọn, hai đại
đội bị thiệt hại nặng. Cuộc hành quân lắn chiếm vùng giải phóng của
tiêu đoàn 2 ngụy bị đập tan và cũng từ đó bọn địch co cụm về Túc
Trưng, không dám mở các cuộc hành quân giải tỏa.
 
Theo đường 20 (Đà Lạt về Sài Gòn), quân ta đã áp sát đến
Túc Trưng.
 
Ngày 4 tháng 4, Thiếu tướng Hoàng Cằm, Tư lệnh Quân
đoàn 4 giao nhiệm vụ: “Sư đoàn 341 (thiếu Trung đoàn 273) cùng
với Sư đoàn 7 tiền công tiêu diệt sư đoàn 18 và toàn bộ lực lượng địa
phương của địch tại thị xã Xuân Lộc, hỗ trợ đồng bào địa phương,
cùng với địa phương tiến công và nỗi dậy, giải phóng tỉnh Long
Khánh. Hướng tiến công: bắc - tây bắc. Mục tiêu: dinh tỉnh trưởng,
các khu vực cế vấn Mỹ, trung tâm thông tin, cảnh sát, tình báo CIA,
tiểu đoàn 1, chiến đoàn 43 và 4 tiểu đoàn bảo an 340, 342, 243, 367.
Sẵn sàng đánh địch từ Núi Thị, Gia Tân lên chỉ viện cho Xuân Lộc.
Thời gian nỗ súng: đêm 8 rạng 9 tháng 4”.
 
Nhận nhiệm vụ xong, sư đoàn trưởng Trần Văn Trân cùng các
đồng chí phó tham mưu trưởng Hồ Đình Quý, trung đoàn trưởng
Trung đoàn 270 Nguyễn Thế Vân, trung đoàn trưởng Trung đoàn 266
 
Nguyễn Quang Thuật, trung đoàn trưởng Trung đoàn 55 Lê Văn Cúc
và các cán bộ cơ quan sư đoàn, trung đoàn khân trương đi trình sắt,
chuẩn bị chiến trường.
 
Vượt qua ngầm La Ngà, đoàn cán bộ trinh sát vào thăng hậu cứ
tỉnh ủy Long Khánh và thị ủy Xuân Lộc để cùng với địa phương
trao đổi chuẩn bị kế hoạch phối hợp hành động. Đồng chí Tư Lạc -
tỉnh đội trưởng Long Khánh và đồng chí Nam Thắng - bí thư thị ủy
Xuân Lộc đã báo cáo toàn bộ tình hình địch, tình hình dân và địa
hình trong khu vực tác chiến. Hội nghị đã bàn bạc kỹ về những tình
huống có thể xảy ra và thống nhất phương án tác chiến. Riêng về sử
dụng lực lượng địa phương, hội nghị nhất trí: Đại đội địa phương
do bộ chỉ huy quân sự tỉnh trực tiếp năm, có nhiệm vụ hỗ trợ cho
quản chúng nồi dậy. Chọn một số du kích làm nhiệm vụ dẫn đường
cho trinh sát sư đoàn và giúp đơn vị chuẩn bị vị trí giấu quân. Toàn
bộ tù binh, hàng binh sẽ giao cho địa phương quản lý. Sau hội nghị,
đoàn cán bộ được các tô trình sát dẫn vào tận hàng rào thị xã. Lực
lượng vũ trang địa phương cử các tổ đưa các mũi trinh sát của sư
đoàn, trung đoàn luồn qua các cứ điểm trong thị xã. Ba tổ trính
sát sư đoàn do trưởng ban trinh sát Lê Anh Thiện chỉ huy. Ba tổ
trinh sát của Trung đoàn 266 đo trưởng tiểu ban trinh sát trung đoàn
Nguyễn Bá Nức chỉ huy đã vào bám suốt mấy đêm liền trong thị xã.
Trưởng ban trinh sát Lê Anh Thiện đã vào tận nhà tên tỉnh trưởng
Nguyễn Văn Phúc.
 
Các mục tiêu tiến công, vị trí cửa mở, cấu trúc các hàng rào, các
vật chướng ngại đã được trinh sát xác định. Cùng với lực lượng trinh
sát tiềm nhập, điều tra địch ban đêm, sáu đài quan sát của sư đoàn,
bốn đài của hai trung đoàn bộ binh cùng các bộ phận trinh sát kỹ
thuật, kết hợp với khai thác tù binh, đã cơ bản nắm chắc các quy luật
hoạt động của địch cũng như lực lượng của chúng ở thị xã. Các đầu
mối cơ sở hoạt động trong lòng địch cũng cử người về căn cứ báo
cáo và nhận kế hoạch mới.
 
