10 TRẬN ĐÁNH NỔI TIẾNG TRONG I.ỊCH SỬ VIỆT NAM
 
I8 giờ ngày § tháng 4, các đơn vị được giao nhiệm vụ đánh vào
Xuân Löc xuất phát.
 
0 giè 30 phút ngày 9 tháng 4, sở chi huy sư đoàn đã nhận được
bảo cáo từ các hướng:
 
- Tiêu đoàn 5 đã áp sát bìa rừng cao su, đang tổ chức vượt
tràng trông.
 
~ Tiêu đoàn 7 đã tới Bình Lộc Sở, đang vượt đường I về lô cao
su phía đông.
 
- Tiêu đoàn 9 đã vượt qua Suối Tre.
- Các khấu đội côi, cao xạ 37, pháo 85 đang cấu trúc trận địa.
 
4 giờ sáng, các hướng báo về: Bộ đội đã áp sát hàng rào các trận
địa pháo đã chuẩn bị xong phân tử.
 
5 giờ, ở hướng tây bắc xảy ra tình huống nhân dân trong thị xã
mở công áp chiến lược đi làm nương, thấy bộ đội ta đào công sự
ngay sát hàng rào, bà con đứng lưỡng lự ở cổng ấp. Để giữ bí mật
đến giờ `*G”, chính trị viên đại đội 9 Tạ Quang Trung tới gặp, đề nghị
bà con đi làm và không một ai quay về nhà.
 
Hai chiến sĩ được lệnh đứng chặn ngang công ấp đề phòng tình
huống bắt trắc. Đồng bào vui vẻ kéo nhau ra rẫy, không một ai quay
trở lại.
 
Đúng Š giờ 40 phút ngày 9 tháng 4, giờ quyết định khai tử tiểu
khu Xuân Lộc đã điểm. Pháo chiến dịch và các trận địa pháo của
Trung đoàn 5Š đồng loạt nhả đạn. Từng đụn khói trùm lên các mục
tiêu. Quả đạn 85mm đầu tiên bắn trực tiếp, phá tung cụm ăng-ten
của khu trung tâm thông tin. Quả pháo lựu 122mm đầu tiên cũng bẻ
gây nốt cột ăng-ten trên đình Núi Thị. Sau mỗi loạt đạn nổ, tiếng các
chiến sĩ thông tin ở các đài quan sát pháo binh và các mũi tiến quân
của bộ binh lại báo cáo về sở chỉ huy sư đoàn. Pháo bắn chính xác
ngay loạt đạn đầu, trúng khu trung tâm thông tin...
 
Bọn địch trong tiểu khu Xuân Lộc gào bọn pháo binh chỉ viện.
Các trận địa pháo địch ở Núi Thị, Suối Tre, ngã ba Tân Phong băn
như vãi đạn dọc đường số 1 về phía bắc, tây bắc. Chúng định dùng
hàng rào lửa ngăn chặn bộ binh và phản pháo các trận địa của ta.
Máy bay trinh sát vẻ vè trên bầu trời. Máy bay AD6, A37, F5 điên
loạn, lồng lộn chúc đầu xuống trút bom.
 
Các trận địa cao xạ 37mm kịp thời nhả đạn, hắt ngược chúng lên.
Mặc cho bom đạn địch nổ đinh tai, nhức óc, mặc cho máy bay địch
gào thét xé rách bầu trời, các khẩu đội pháo vẫn giữ đúng phần tử rót
vào các mục tiêu trong thị xã. Sau một trận mưa pháo khủng khiếp,
phần lớn các hỏa điểm địch đã bị pháo ta phá hoại hoặc làm tê liệt.
 
Đúng 6 giờ 40 phút, hai phát pháo hiệu đỏ rực bay vụt lên bầu
trời. Các chiến sĩ bộ binh vọt đậy lao qua cửa mở, đánh thẳng vào
các căn cứ.
 
Tiểu đoàn 7 tiến công trên hướng tây bắc - hướng tiến công chủ
yếu vào mục tiêu. Tiểu đoàn 5, hướng đông bắc, Tiểu đoàn 9 kẹp
sườn bên phải Tiêu đoàn 7.
 
Ở hướng Tiểu đoàn 5 được chọn làm đơn vị mở cửa. 4 giờ sáng,
đại đội 5 đã tới vị trí sát hàng rào và dùng kéo bí mật cắt được vài
lớp. Đến giờ nổ súng, pháo binh bắn cấp tập vào các mục tiêu thì tổ
mở cửa của Nguyễn Xuân Loan, Nguyễn Văn Đấu, Trần Văn Ngọc
đã đút bộc phá ông vào đưới lớp rào. Bộc phá nể, xé tung đến hàng
rào thứ năm. Địch phát hiện ra hướng cửa mở, tập trung hỏa lực bắn
ra như mưa. Máy bay C130 xổ từng tràng liên thanh vào con đường.
dẫn tới cửa mở. Một số chiến sĩ thương vong. Bộ phận hỏa lực của
đại đội 8 lên khẩu nào đều bị thương, cửa mở gặp khó khăn, đội hình
ùn lại. Khẩu đội trưởng Nguyễn Đăng Trinh vác khẩu ĐKZ lao lên
sát hàng rào, lợi dụng mô đất cao, nhằm thẳng khẩu đại liên đầu cầu
của địch, néo cò. Hỏa điểm đầu tiên của địch bị dập tắt. Trinh diệt
luôn hai khẩu đại liên của địch ở phía Trường trung học Hòa Bình
đang bắn ra cửa mở.
 
10 TRẬN ĐÁNH NỔI TIẾNG TRONG I.ICH SỬ VIỆT NAM
 
Lợi dụng thời cơ, Nguyễn Văn Lái ôm bộc phá lao lên, giật nụ
xòe phá tung thêm hai lớp rào nữa. Địch ở gác hai của trường trung
học xa đại liên vào cửa mở. Lái hy sinh. Thêm một số đồng chí bị
thương. Đại đội trưởng Nguyễn Quốc Hoàn vừa ôm bộc phá lao lên
vừa nói: “Dù thương vong cũng quyết hoàn thành nhiệm vụ. Hãy
tra thù cho những đồng chí đã hy sinh!”. Một viên đạn AR-lŠ§ của
địch dính vào tay trái Hoàn, ống bộc phá văng sang bên. Tiểu đội
phó Nguyễn Xuân Hải nhào đến, ôm ống bộc phá đút vào hàng rào,
giật tung lớp hàng rào thứ bảy thì gặp ngay lớp rào vướng chân là
là mặt đắt,
 
Đại đội 5 quyết định mở thêm cửa thứ hai. Các xạ thủ súng ĐKZ
Định Quang Tạo, Nguyễn Văn Nhung, Nguyễn Đăng Trinh ở đại
đội 8 tập trung bắn sập những hỏa điểm lợi hại của địch từ Trường
trung học Hòa Bình, từ trong các căn nhà, cũng là lúc Nguyễn Khắc
Sơn mở xong cửa thứ nhất. Trung đội 2 do Nguyễn Xuân Loan chỉ
huy cũng mở gần xong cửa thứ hai. Còn một lớp rào thì hết bộc phá
ống. trợ lý tác chiến Tiểu đoàn 5 Lê Hồng Sơn lấy ván bắc qua hàng
rào. Tiêu đoàn 5 ào ạt tiến qua hai cửa mở như những cơn lốc, tiêu
diệt hàng loạt vị trí của hai tiêu đoàn bảo an 340, 342 bảo vệ mé
ngoải và thọc sâu vào các cứ điểm, các mục tiêu ở khu vực xung
quanh đinh tỉnh trưởng.
 
Trong lúc đó, ở hướng chủ yếu, đại đội I Tiểu đoàn 7 đã mở gần
xong cửa mở thì địch điều hỏa lực bắn vào cửa mở. Một số chiến
sĩ thương vong. Chính trị viên Tiêu đoàn 7 Nguyễn Hữu Điệt bị
thương vào tay phải. Tiểu đoàn trưởng Nguyễn Văn Huyên điều
khiển ĐKZ của đại đội 4 lên điệt ngay cụm hỏa lực mới kéo tới của
địch. Các đồng chí Trần Văn Quang, Nguyễn Viết Xuân chớp thời
cơ mở xong cả hai cửa, cũng là lúc phát pháo hiệu đỏ rực vút lên.
Tiểu đoàn 7 thành hình chữ A ào ạt công kích vào hướng bắc - đông
bắc của thị xã.
 
Đến 7 giờ 5 phút. Tiểu đoàn 7 đã đánh chiếm xong khu vực
bắc nhà thờ, tây bắc đinh tỉnh trưởng, tây bắc bến xe Văn Thành.
 
Ở hướng Tiểu đoàn 5, đại đội 5 hình thành ba mũi tiến công thân tốc,
phát triển về phía dinh tỉnh trưởng. Tiểu đoàn 9 cũng đã đánh chiếm
và làm chủ gia binh và nhà máy điện. 7 giờ 40 phút, cả ba tiêu đoàn
đã thanh toán xong các mục tiêu khu thông tin, khu có vân, khu cảnh
sát và đang hợp điểm tại khu vực dinh tỉnh trưởng.

Đến 9 giờ 30 phút, khu vực nhà tên tinh trưởng đã bị chiếm.
10 giờ, các đơn vị đã cơ bản làm chủ các mục tiêu được phân công.
 
Đến 1I giờ, địch điều tiểu đoàn 1 chiến đoàn 48 từ ngã tư Tân
Phong đến phản kích ở hướng tây bắc và điều tiểu đoàn 2 chiến đoàn
52 từ Gia Tân đánh vào bên sườn Trung đoàn 266, nhằm bịt cửa của
ta. Chúng còn điều một chỉ đội xe tăng từ ấp Tân Xuân, men theo
đường Quang Trung, chọc một mũi qua ngã tư đường Hoàng Diệu,
kết hợp với tiểu đoàn 1, chiến đoàn 48 phản kích nhằm chiếm lại các
mục tiêu tại khu vực dinh tỉnh trưởng. Mặt khác, địch dùng máy bay,
pháo binh bắn bừa bãi và dọn đường cho bộ binh tiến công, đồng
thời ngăn chặn ta phát triển xuống sân bay.
 
Trước tình hình đó, phó trung đoàn trưởng Lê Tiến Hạt hội ý
chớp nhoáng với các cán bộ tiêu đoàn và thống nhất: Kiên quyết tập
trung binh lực, hỏa lực để tiêu hao, tiêu diệt sinh lực địch, giữ vững
các mục tiêu đã chiếm. Trước mắt, phải điệt bằng được bọn địch
đang co cụm trên tháp chuông nhà thờ, trên gác ba nhà ngân hàng
Đồng Tiến và tại ngã ba đường sắt. Tổ chức hỏa lực ngăn chặn xe
tăng, đồng thời lùng sục, truy quét và củng cố các vị trí đã chiếm,
chuẩn bị đánh địch phản kích.
 
Sư đoàn trưởng lệnh cho Trung đoàn 270 tung Tiểu đoàn 4 từ
Bình Lộc Sở hiệp đồng với Tiểu đoàn 9 đánh tạt sườn quân dịch đến
phản kích. Tiểu đoàn l chiến đoàn 48 ngụy từ ngã ba Tân Phong
vừa mon men đến lô cao su sát đường số 1 ở hướng tây bắc, bị Tiểu
đoàn 9 đánh hắt trở lại. Trong thị xã, Tiểu đoàn 7 tổ chức lực lượng
gọn nhẹ, lợi dụng các dãy phố, các căn nhà nhiều tầng, tiền sát ngã
tư đường Hoàng Diệu - Quang Trung bắn cháy 4 xe tăng, tiêu diệt
 
