10 TRẬN ĐÁNH NỘI TIẾNG TRONG LỊCH SỬ VIỆT NAM
 
một sỏ bộ binh. Tiêu đoản 5 băn cháy 2 chiếc khác ở đoạn ngã tư
đường sắt. Âm mưu phan kích của địch tạm thời bị bẻ gãy. Qua một
ngày chiên đấu, ta tiêu diệt và làm tan rã một số lớn quân địch. bắt
sông 235 tên, bản cháy 7 xe tăng, làm chủ các mục tiêu được quân
đoàn phân công.
 
Bộ tư lệnh sư đoàn nhận định: Địch bị đánh bắt ngờ, đối phó lúng
túng. Nhưng ơ hướng chủ yêu của quân đoàn gặp khó khăn và không
đánh trúng các mục tiêu, nên chiến đoàn 43 địch còn tăng cường lực
lượng đê phán kích, giành lại các vị trí đã mắt.
 
Vẻ ta, Trung đoàn 266 phát triển thuận lợi, tỉnh thần chiến
đấu tốt, nhất là Tiêu đoàn 5 và Tiểu đoàn 7. Nhưng do chuẩn bị
vật chất chưa tốt, đạn hết, nên tốc độ tiến công và phát triển có
chậm. Tiêu đoàn 4 đánh vận động tương đối tốt, đã bẻ gây đợt
phản kích của Tiêu đoàn 2 chiến đoàn 52, bảo vệ tốt cạnh sườn cho
Trung đoàn 266.
 
Hộ tư lệnh sư đoàn chủ trương: Kiên quyết giữ vững những mục
tiêu đã chiếm. Nhanh chóng giải quyết thương binh, tử sĩ. Bỏ Sung
đạn. gạo, xốc lại lực lượng đê ngày mai tiếp tục tiến công, tạo điều
kiện cho hướng chủ yếu của quân đoàn đột phá.
 
Suốt đêm 9 tháng 4, các đơn vị triển khai thực hiện các chủ
trương trên.
 
Š giờ 27 phút ngày 10 tháng 4. pháo binh ta băn vào một số mục
tiêu còn lại trong thị xã. 5 giờ 47 phút, pháo binh ngừng bắn. Tiêu
đoàn 9 hình thành hai mũi tiến công vào tòa hành chính. Tiểu đoàn 5
phát triển xuống sân bay Cáp Rang. Tiểu đoàn 7 đánh vào căn cứ Lê
Lợi. nơi đồn trú của hai tiểu đoàn 343 và 367 bảo an.
 
Cũng trong đêm 9 tháng 4, địch đã củng có lại các khu vực trong
thị xã. Do đó yếu tố bất ngờ không còn nữa. Dịch đã chủ động
đối phó ngay khi lực lượng xung kích của ta áp sát hàng rào. Tiểu
đoàn 7 đã năm lần tô chức đột phá vẫn không thủng. Số thương vong
 
ngày một cao. Chính trị viên tiểu đoàn Nguyễn Hữu Điệt hy sinh.
Tiểu đoàn trưởng Nguyễn Văn Huyên tạm cho bộ đội lùi xuống dưới
chân đồi và xin sư đoàn cho pháo binh bắn cắp tập theo hiệu chỉnh
của các chiến sĩ bộ binh. Được chiến sĩ bộ binh chỉnh tầm, chỉnh
hướng, các trận địa pháo của ta đã phá tung một loạt công sự vòng
ngoải, ghìm cứng bọn địch trong các công sự. Căn cứ Lê Lợi chìm
trong lửa và khói. Lực lượng xung kích Tiểu đoàn 7 lợi dụng thời
cơ phá tung hàng rào. Pháo vừa ngừng, các mũi đột kích đã thọc sâu
vào căn cứ. Một trận đánh bằng lựu đạn, lưỡi lê diễn ra ác liệt. Đến
18 giờ, Tiểu đoàn 7 làm chủ chiến trường đánh thiệt hại nặng hai tiểu
đoàn bảo an 343 và 367.
 
Ở hướng Tiểu đoàn 9 cũng diễn ra những trận chiến đấu quyết
liệt giữa chiến sĩ ta với tiểu đoàn 2 chiến đoàn 43. Mờ sáng
ngày 10 tháng 4, được chiến đoàn xe tăng 181 chỉ viện, tiểu đoàn 2
địch mở đợt phản kích hòng đánh chiếm lại khu vực nhà thờ và tòa
hành chính. Tiểu đoàn 9 đã giành giật với địch từng ngách phó, căn
nhà, từng đoạn hào giao thông nhỏ. Cuộc chiến đầu ở đây không
còn là đội hình chiến đấu của đại đội, tiểu đoàn, mà phần lớn là tổ
chiến đấu, thậm chí là cá nhân chiến đấu. Mỗi tổ, mỗi người đều
tự ghép mình thành từng bộ phận, tự hiệp đồng với nhau, hỗ trợ
nhau chiến đấu. Chiến sĩ liên lạc đại đội 9 Phạm Văn Lái cùng phó
đại đội trưởng Đặng Xuân Dần và ba chiến sĩ Trúc, Toại, Hà hình
thành một mũi đánh vào một đoạn chiến hào của địch. Để tránh
đánh vỗ mặt, Lái xin phép phó đại đội trưởng Dàn dẫn Toại và Hà
vòng phía trái, bí mật thọc một mũi vào sau lưng địch. BỊ đánh bất
ngờ, bọn địch bỏ chạy. Lái đuổi theo. Mải đuôi giặc, Lái thọc quá
sâu vào tung thâm, trong lúc đơn vị được lệnh chuyển hướng tiến
công, Phạm Văn Lái chỉ có một mình với khẩu AK hết đạn. Lái xác
định: còn một mình cũng đánh, tìm súng địch mà đánh! Lái vớ được
khẩu AR-15 với băng đạn đầy và hai quả lựu đạn Mỹ. Anh củng; cố
công sự để chiến đấu.
 
