10 TRẬN ĐÁNH NỔI TIẾNG TRONG LỊCH SỬ VIỆT NAM
 
Hơn một ngày chiến đấu trong hoàn cảnh một mình một hướng
tiến công, độc lập chiến đấu, lấy súng địch tiêu diệt địch, bị thương
không rời vị trí, Phạm Văn Lái đã diệt 3l tên địch, hoàn thành xuất
sắc nhiệm vụ bảo vệ mục tiêu, nêu tắm gương chiến đấu kiên cường,
mưu trí, sáng tạo, táo bạo tiền công. Đêm I0 tháng 4 là một đêm đấu
phảo quyết liệt. Địch dùng hàng chục trận địa pháo với 86 khâu đủ
loại 105mm, 106,7mm, 155mm cùng hàng chục lần máy bay ném
bom phá hoặc các khu vực đã bị ta đánh chiếm trong hai ngày qua.
Chúng phản pháo vào các trận địa pháo của ta, đồng thời bắn chặn
các con đường từ hậu cứ dẫn vào thị xã. Máy bay C130 xổ từng
tràng đạn 20mm. Chúng định làm thành một hàng rào lửa ngăn chặn,
không cho ta tiếp đạn và giải quyết thương binh. Chúng định hủy
diệt toàn bộ lực lượng ta còn bám trong thị xã.
 
Các tiểu đoàn 5, 7, 9 vẫn kiên cường bám trụ, vừa củng cố
công sự, vừa chuẩn bị tư thế đánh địch phản kích trong ngày mai.
4 giờ sáng ngày II tháng 4, Bộ tư lệnh Quân đoàn 4 lệnh cho
Sư đoàn 341 tô chức một lực lượng đánh vào sở chỉ huy chiến
đoàn 43 và một lực lượng đánh xuống sân bay Cáp Rang, bắt liên
lạc với Sư đoàn 7. Chiều hôm trước, địch đã dùng trực thăng đỗ
lữ đoàn dù 1 xuống ấp Tân Phong và lực lượng này đã bao vây
Tiêu đoàn 18 Sư đoàn 7. Địch còn điều tiểu đoàn 1 chiến đoàn 48,
tiểu đoàn 1 chiến đoàn 43 và tiểu đoàn 2 chiến đoàn 52 tăng cường
giải tỏa vòng ngoài. Mờ sáng ngày 11 tháng 4, lực lượng này đã tổ
chức phản kích vào khu hành chính, dinh tỉnh trưởng và đọc theo
đường số 1 về phía tây bắc.
 
Như vậy, nhiệm vụ của sư đoàn càng nặng nề hơn. Phải vừa đánh
địch phản kích, giữ vững các mục tiêu đã đánh chiếm trong hai ngày
qua, vừa tô chức lực lượng hỗ trợ, giải vây, giải quyết khó khăn cho
đơn vị bạn.
 
Sư đoàn trưởng chỉ thị cho Trung đoàn 270 tung Tiểu đoàn 6
kết hợp với Tiểu đoàn 7 đánh xuống sân bay Cáp Rang; Tiểu đoàn 5
 
đánh vào sở chỉ huy chiến đoàn 43; Tiêu đoàn 9 giữ vừng các mục
tiêu đã chiếm; Tiểu đoàn 4 chuẩn bị đánh giải vây cho Tiểu đoàn 18
Sư đoàn 7.
 
5 giờ 30 phút ngày 1 1 tháng 4, pháo binh bắn 30 phút vào sở chỉ huy
sư đoàn 18 và chiến đoàn 43. 6 giờ, pháo binh chuyển làn, kiềm chế
các trận địa pháo địch ở Núi Thị, ngã ba Tân Phong. Tiêu đoàn 5 lợi
dụng các hè phó, các ngôi nhà nhiều tằng bị bom pháo phá sập, áp sát
và tiêu diệt được một số mục tiêu vòng ngoài của chiến đoàn 43. Địch
chống cự quyết liệt, một vài phân đội của Tiểu đoàn Š lùi lại. Trong
lúc đó, đại đội 5 vẫn tiếp tục đột kích theo hướng phân công. Trung
đội trưởng Nguyễn Phi Nhân dẫn trung đội luồn qua các bức tường
đổ, áp sát sở chỉ huy chiến đoàn 43 về hướng đông, tiêu diệt một số
hỏa điểm bên ngoài. Địch rút sâu vào trong căn cứ. Nguyễn Phi Nhân
đuổi theo, tiêu diệt một số tên. Nhưng vì các mũi khác gặp khó khăn,
không đột phá được vào mục tiêu nên mũi đột kích của Nguyễn Phi
Nhân bị lẻ loi. Anh đã hy sinh anh dũng trước sở chỉ huy của Chiến
đoàn 43. Mãi đến 11 giờ, đại đội 6 Tiểu đoàn 5 mới bắt liên lạc
được với Sư đoàn 7 và cùng với bạn tiếp tục đột phá vào sở chỉ huy
chiến đoàn 43.
 
Hướng các tiểu đoàn 6 và 7 cũng diễn ra những trận đánh giằng
co với địch. Địch mới được tăng viện, chúng sử dụng xe tăng, xe bọc
thép cùng bộ binh chống phá điên cuồng. Các đơn vị của ta đã bốn
lần đột phá vào sân bay Cáp Rang đều bị chúng đánh hắt trở lại. Tình
hình diễn biến không thuận lợi. Hai tiểu đoàn đều gặp khó khăn,
Phó sư đoàn trưởng Vũ Cao và chủ nhiệm chính trị Nguyễn Quê
xuống ngay sở chỉ huy Trung đoàn 266 đốc chiến. Đại đội 9 Tiểu
đoàn 14 được lệnh đưa pháo 85 bắn trực tiếp vào các hầm chứa máy
bay lúc bấy giờ là sở chỉ huy lữ dù 1.
 
Tiếp đó, tiểu đoàn 6 và 7 đánh chiếm sân bay Cáp Rang vào lúc
10 giờ sáng ngày I1 tháng 4. 11 giờ cùng ngày, địch dùng 48 lần
chiếc trực thăng đỏ quân tăng viện xuống ngã ba Tân Phong. Thế là
 
