1C TPRẬN ĐÁNH NỔI TIẾNG TRONG LICH SỬ VIỆT NAM
 
đ:clh đã ném xuống cái thị xã này toàn bộ sư đoàn 18, lữ ky binh 3,
chiên đoàn 8 sư đoàn 5, các liên đoàn biệt động quân của quân khu 3,
cac liên đoàn biệt động què quặt của quân khu I và 2, thiết đoàn 5 xe
tăng (60 chiếc) các tiểu đoàn pháo binh lãnh thổ và lữ đù 1. Chúng
nem vào đảy đến 9 chiến đoàn bộ binh; chúng đã huy động đến mức
cao› nhất lực lượng không quân còn lại của Biên Hòa, Tân Sơn Nhắt,
Cân Thơ - một cuộc thí quân, thí tướng của Mỹ - ngụy để kéo dài
ngàiy tận số.
 
''Chúng dùng cả bom hơi ngạt ném xuống các khu vực xung quanh
thị xã. Chúng còn huy động cả một bộ máy tuyên truyền chiến tranh
tâm lý ở Sài Gòn đến Xuân Lộc đẻ lên đây cót tinh thần cho binh
lính và chỉ huy.
 
Trước những diễn biến phức tạp của tình hình, Đại tướng Văn
Tiến Dũng, Tư lệnh Chiến dịch Hồ Chí Minh chỉ thị cho Bộ Tư lệnh
Quiân đoàn 4: “Khi địch đã dồn quân vào đề cô cứu thị xã Xuân Lộc
thì ta không cần tập trung lực lượng tiếp tục đánh thăng vào đấy
nữa, mà chuyển lực lượng đánh các đơn vị địch đến phản kích đứng
châun chưa vững ở vòng ngoài đang thiêu công sự và thiếu sự hiệp
đồmg chặt chẽ với nhau; dùng pháo tầm xa bắn phá và khống chế liên
tục ngày đêm sân bay Biên Hòa, không cho máy bay chiến đấu của
địch cất cánh” (Văn Tiến Dũng, Đại thắng mùa xuân, Nxb. Quân
đội nhân dân, H., 1976, tr205). Thực hiện ý đồ trên, Bộ tư lệnh
Quiân đoàn 4 lệnh cho sư đoàn đưa các tiểu đoàn 5, 6, 9 ra ngoài,
Tiểu đoàn 7 tiếp tục chốt các mục tiêu trong thị xã. Đến 21 giờ
ngày 12 tháng 4, quân đoàn chỉ thị cho Tiểu đoàn 7 lùi ra ngoài và
dùng Trung đoàn 270 vận động bao vây đánh địch xung quanh khu
vực: Núi Thị. Trung đoàn 266 khân trương củng cố và chuẩn bị nhận
nhiệm vụ.
 
Sau khi quân ta ra khỏi thị xã, địch liền đưa hai chiến đoàn 43 và
48 cua sư đoàn 18, lữ đoàn dù 1, thiết đoàn 5 xe tăng tràn vào chiếm
lại; dùng chiến đoàn 52 giải tỏa ngã ba Dầu Giây đo Sư đoàn 6
 
của ta đánh chiếm hôm 10 tháng 4. Chúng dùng các chiến đoàn 315
và 322 từ Trảng Bom dọc theo đường số l đánh ra Dầu Giây đẻ
nối lại đoạn đường Long Khánh đi Biên Hòa. Chúng tập trung trên
60 khẩu pháo các loại để chỉ viện.
 
Bộ tư lệnh sư đoàn lúc này đã điều Trung đoàn 270 đánh địch
xung quanh Núi Thị; Tiểu đoàn 4, Tiểu đoàn 6 đã đánh chiếm được
các điểm cao 46, 52 ở phía bắc và đang khép chặt vòng vây quanh
Núi Thị. Bộ chỉ huy nhẹ sư đoàn 18 ngụy đã chuyên đến đây sau khi
ta tiến công vào thị xã. Lúc này Bộ chỉ huy chiến dịch tăng cường
thêm Trung đoàn 95B và Sư đoàn 6 mở đợt tiến công đánh chiếm
Túc Trưng, tiêu diệt chiến đoàn 52 rồi theo trục đường 20 tiến xuống
ngã ba Dầu Giây và chốt cứng đoạn đường số 1 từ ấp Trần Hưng
Đạo đến ngã ba Dầu Giây. Sau đó, Trung đoàn 95B lại đánh lui lữ
đoàn 3 ky binh từ Biên Hòa ra ứng cứu giải tỏa đoạn đường số 1 do
Sư đoàn 6 chiếm giữ. Sáng ngày 15, Trung đoàn 266 được sư đoàn
giao nhiệm vụ thay Trung đoàn 95B và Sư đoàn 6, cơ động đánh
địch từ ấp Hưng Nghĩa, Bầu Cá ra ngã ba Dầu Giây và chốt cứng ở
khu vực đèo Mẹ Bồng Con. Tiểu đoàn 6 Trung đoàn 270 đánh chiếm
Gia Kiệm và làm chủ đoạn đường 20 từ ngã ba Dầu Giây lên Túc
Trưng. Cùng ngày, Tiểu đoàn 4 tiêu diệt sở chỉ huy chiến đoàn 43
trên điểm cao 245 và 292.
 
Thị xã Xuân Lộc hoàn toàn bị cắt lìa khỏi Sài Gòn, Biên Hòa.
Lúc này các chiến đoàn 48, 43 và tiểu khu Xuân Lộc bị ta bắn phá
liên tục. Lữ dù I bị pháo binh ta bắn chặn không nhích lên được.
Các trận địa pháo của địch bị triệt dần. Viên chuẩn tướng Lê Minh
Đảo đặt hy vọng vào các lực lượng tăng viện, nhưng quân ta với ưu
thế áp đảo đã cắt đứt nguồn hy vọng ấy của hắn. Lữ đoàn dù 1 tăng
viện bị sa lầy trong đồn điền Trần Thiện Khiêm. Các lực lượng quân
đoàn 3 của tướng Toàn rõ ràng không có hy vọng chọc thủng vòng
vây theo đường số 1.
 
Qua mắy ngày đêm chịu đựng những trận pháo bắn nặng nề nhất
chưa từng có trên cái tỉnh ly tan nát này, Lê Minh Đảo nhận thấy
 
10 TIRẬN ĐÁNH NỔI TIẾNG TRONG LỊCH SỬ VIỆT NAM
 
cuộc chiến trở nên tuyệt vọng. Hắn nhận thây hỏa lực tiến công của
đối phương thật đữ đội. Các tiền đồn xung quanh Xuân Lộc bắt đầu
đỗ sập từng cái một. Vòng vây của đối phương thu hẹp dần. Rạng
sáng ngày 19 tháng 4, Đảo nói chuyện với sở chỉ huy quân đoản 3
ngụy ở Biên Hòa bằng điện đài Y được báo cho biết tướng Toàn
khômg có ở đây, nhưng sở chỉ huy đã chỉ thị cho Đảo là “phải giữ
Xuân Lộc cảng lâu càng tốt”, không còn cái kiểu “ra lệnh phải giữ
vững bằng mọi giá”. Đến nửa buôi sáng ngày 19 thì tình hình rõ rằng
là tuyệt vọng. Xuân Lộc - biêu tượng duy nhất nói lên sự chống cự
của quân ngụy Sài Gòn trước cuộc tiền công mãnh liệt của quân ta
đã sắp sửa sụp đỏ.
 
Đến 12 giờ trưa ngày 20 tháng 4, các đài quan sát liên tục báo
về sở chỉ huy sư đoàn những hiện tượng lạ: Trong thị xã xuất hiện
nhiều đám cháy và tiếng nỗ lớn. Có những chiếc GMC tự dưng bốc
cháy. Trong lúc đó, bộ binh địch bắn hỗn loạn ra xung quanh thị
xã. Trưởng ban pháo binh sư đoàn báo cáo: pháo địch từ các hướng
quanh thị xã băn rất mạnh về phía sở cao su Gia Kiệm. Theo dõi và
đếm kỹ, có tới ba trận địa pháo khác nhau, trên 10 khẩu.
 
Từ sở chỉ huy Trung đoàn 55, tham mưu trưởng Trần Thìn điện
về một chỉ tiết: Các trận địa pháo của địch bắn lung tung, không
có bài bản gì cả, ngay một khẩu pháo cũng bắn không đồng lô,
đồng liều.
 
Qua phân tích, sở chỉ huy sư đoàn 341 đi đến kết luận: Có khả
năng địch nghỉ binh, bắn cho hết đạn pháo để tháo chạy khỏi Xuân
Lộc. Sư đoàn trưởng điện báo cáo lên quân đoàn về tình hình địch
và những nhận định sơ bộ của sư đoàn. Quân đoàn ra lệnh: “Sư
đoàn 341 khân trương triển khai truy kích theo đường số 22 về
hướng Bà Rịa - Long Thành”. Lập tức các đơn vị từ bao vây được
lệnh chuyền sang truy kích tiêu diệt địch. Trung đoàn 55 pháo binh
bắn chặn mãnh liệt vào ngã ba Tân Phong. Tiêu đoàn 9 vận động
về hướng Núi Sóc làm nhiệm vụ đón lõng. Các tiểu đoàn 4, 6, 7
 
theo đường 22 truy kích về hướng Bà Rịa. Tiểu đoàn 5 tiến công vào
thị xã, bắt liên lạc với Sư đoàn 7.
 
Sau khi điện về sở chỉ huy quân đoàn 3 ngụy ở Biên Hòa, Lê
Minh Đảo ra lệnh cho tiểu khu trưởng Xuân Lộc là Nguyễn Văn
Phúc lập một vòng phòng thủ nhỏ hơn để bảo vệ Xuân Lộc. Còn sư
đoàn 18, Đảo cho phép “bí mật rút chạy”. Đảo còn nói với ban tham
mưu của y: “Cứ để cho chúng giữ, khi chủ lực rút xong, ai biết thì
biết”. 17 giờ ngày 20 tháng 4, Đảo ra lệnh: “Tùy nghỉ di tản”. Sư
đoàn 18 và các lực lượng chủ lực quân đoàn 3 ngụy rút chạy tán loạn
theo đường 22 về Tân Phong và theo đường số 1 về Trảng Bom.
 
Trung đoàn 55 pháo binh nhanh chóng chuyên trận địa, kịp thời
cấu trúc công sự và cấp tập nã đạn pháo vào ngã ba Tân Phong. Bọn
địch đành bỏ xe, pháo, chạy vào rừng cao su về phía Bà Rịa. Tiểu
đoàn 9 chốt cứng tại ngã ba Núi Sóc và kiểm soát vùng ấp Trần
Hưng Đạo. Tiểu đoàn 7 tiêu diệt tiểu đoàn dù ở ngã ba Suối Tre. Tiểu
đoàn 4 vận động phục kích một số tàn quân, điệt nhiều tên, bắt sống
125 tên ở điểm cao 22 và ấp Suối Vạc. Các tiểu đoàn 6 và 8 truy kích
địch trong các lô cao su dọc đường 1, bắt sống trên 700 tên.
 
Các lực lượng chủ lực của quân đoàn 3 ngụy ở Mặt trận Xuân
Lộc rút chạy đã bị ta chặn đánh kịch liệt. Chúng bị tiêu hao
một số lớn, một số chạy thoát về Long Bình, trong đó có cả Lê
Minh Đảo và ban tham mưu của y. Lực lượng “phòng thủ nhỏ”
của Nguyễn Văn Phúc ở Xuân Lộc cũng chịu chung số phận.
Phúc vét toàn bộ lực lượng của hắn được khoảng 600 tên đã mắt
tinh thần để nống ra phía đông bắc. Vừa mon men rời căn cứ đã bị
sư đoàn 7 và Tiểu đoàn 5 (Sư đoàn 341) tiêu diệt và bắt gọn. Riêng
Tiểu đoàn 5 đã bắt sống 257 tên. Tên đại tá Nguyễn Văn Phúc khi bị
bắt mới biết sư đoàn 18 đã rút hết từ đêm hôm trước. Y cúi đầu, lầm
bẩm: “Tưởng đánh một trận oai hùng cho thế giới biết, ai ngờ nó đã
cao chạy xa bay. Quân chó đều!”.
 
