Ca một đạo quân hùng hậu có đủ mặt các sắc lính thiện chiến của
quân đoàn 3 và quản khu 3 ngụy đã bị đánh tơi tả. Bức “tường thép”
Xuân Lộc - phòng tuyến "bất khá xâm phạm” vòng ngoài của chế
độ Sài Gòn do tướng Mỹ Uây-en lập ra và được quân ngụy cắt công
xây đắp với sự có gắng đến mức cao nhất, đã bị phá tung. Niềm hy
vọng mỏng manh đề bảo đảm cho sự tồn tại của ngụy quyên Sài Gòn
đã bị đập vỡ.
 
Thị xã Xuân Lộc, một vùng đất bình dị mà ít người biết, nay bỗng
trở thành một cái tên được ca nước biết đến, và đối với Sư đoàn 341,
Xuân Lộc đã trở thành một địa danh lịch sử, ghi nhận chiến công
của các chiến sĩ sư đoàn. Cánh cửa phía đông Sài Gòn đã mở đề đón
các lực lượng hùng mạnh của ta vào trận quyết chiến chiến lược cuối
cùng: Tổng tiền công vào Sài Gòn - Gia Định.
 
Ø nột cánh trên hướng đông bắc, mọi công tác chuân bị cho trận
quyết chiến chiến lược đang được Bộ tư lệnh Quân đoàn 4 tô chức
triển khai. Ngày 25 tháng 4, Thiếu tướng Hoàng Cầm. Tư lệnh Quân
đoàn 4 giao nhiệm vụ; Sư đoàn 341 được tăng cường một tiểu đoàn
xe tăng (l3 chiếc), một tiêu đoàn cao xạ hỗn hợp. một đại đội pháo
105, tiến công tiêu điệt địch từ ngã ba Sông Thao đến Suối Đia.
Nếu không tiêu diệt gọn thì phải bao vây chặt, không cho địch chạy
thoát về Biên Hòa, bảo đảm đường tiến quân của quân đoàn vào giải
phóng Biên Hòa. Thời gian nỗ súng là đêm 26 rạng ngày 27 tháng 4.
 
Ngày 22 tháng 4, sau khi quân đoàn giao nhiệm vụ sơ bộ, đồng chí
Vũ Cao đã dẫn đầu đoàn cán bộ lên đường đi chuân bị chiến trường.
 
Buốồi chiều ngày 25 tháng 4, Thường vụ Đảng ủy sư đoàn họp
nghe đoàn cán bộ đi chuẩn bị chiến trường báo cáo toàn bộ tình hình
yếu khu Trảng Bom và ra nghị quyết lãnh đạo trận đánh then chốt
này. Yếu khu Trảng Bom năm trên đường số 1, cách Biên Hòa 30km
về phía đông, đông bắc. Sau khi bị thất thủ ở Xuân Lộc, quân đoàn
3 ngụy lệnh cho sư đoàn 18 (chưa kịp củng cế) ra xây dựng tuyến
phòng thủ Trảng Bom.
 

 
16 giờ ngày 25 tháng 4, Bộ tư lệnh sư đoàn giao nhiệm vụ cho
các đơn vị:
 
- Trung đoàn 270 được tăng cường 8 xe tăng, 2 pháo 85, một
cối 120, tiến công trên hướng chủ yếu bố trí phía bắc yêu khu Trảng
Bom, có nhiệm vụ tiêu diệt địch trong yếu khu, bao vây chặt địch ở
Suối Đia, ngăn chặn không cho địch từ Trảng Bom rút chạy qua Hỗ
Nai - Biên Hòa, sau đó phát triển tiêu diệt địch ở Suối Đia.
 
- Trung đoàn 273 được tăng cường 2 pháo 85, 2 cối 120, tiến
công trên hướng thứ yếu bố trí ở phía đông Trung đoàn 270, có
nhiệm vụ tiêu diệt địch phòng ngự trên đường số Ì và rừng cao su
ven đường từ yếu khu đi Bầu Cá. Sau đó phát triển tiêu diệt địch ở
Bằu Cá và ngã ba Sông Thao. Phối hợp diệt địch trong yếu khu, nếu
Trung đoàn 270 gặp khó khăn.
 
- Tiểu đoàn § được tăng cường 4 xe tăng, bế trí phía đông ấp
Hưng Nghĩa, làm nhiệm vụ hướng bao vây vu hồi. Sử dụng một
đại đội tiến công từ phía đông nam vào yếu khu Trảng Bom.
Còn lại theo trục đường số 1 từ hướng đông đánh vào, phối hợp
với Trung đoàn 273 điệt địch trong khu vực Bằu Cá và ngã ba
Sông Thao.
 
- Trung đoàn 266 (thiếu Tiểu đoàn 8) bố trí phía sau Trung đoàn
270, làm dự bị cho sư đoàn, sẵn sàng bước vào chiến đấu trong khu
vực Trảng Bom, nếu tình hình khó khăn. Sẵn sàng phát triển chiến
đấu vào Biên Hòa trong tình huống thuận lợi.
 
Sau khi pháo bắn chuẩn bị, Trung đoàn 273 và 270 cử một bộ
phận tiêu diệt cụm xe tăng và bộ binh địch bố trí ở ga Sông Mây. Sau
đó chốt chặn cầu số 3 trên đoạn đường sắt Trảng Bom đi Cây Gáo.
Riêng Trung đoàn 270 đưa Tiểu đoàn 4 vào bao vây Suối Đia, kiềm
chế trận địa pháo và tạo thời cơ tiêu diệt Suối Đia.
 
