10 TRẬN ĐÁNH NỔI TIẾNG TRONG LỊCH SỬ VIỆT NAM
 
-_ Trung đoàn $5 bố trí phía bắc khu vực tác chiến tập trung hỏa
lực vao: yếu khu, khu vực nhà cô vấn Mỹ, đồn điền Ông Quế. Sau đó
chuyên hỏa lực tập trung vào Bầu Cá - Suối Địa.
 
-_ Lực lượng cao xạ ngắm bắn trực tiếp các mục tiêu trên mặt đắt;
đưa súng 2.7mm đi sát bộ binh,
 
- Tiêu đoàn 17 công binh tăng cường cho mỗi trung đoàn bộ binh
một trung đội. Số còn lại bảo đảm cho cơ giới cơ động trên đường
sắt từ Cây Gáo vào Trảng Bom và bảo đảm cho sở chỉ huy.
 
- Tiêu đoàn 18 thông tin chuẩn bị đầy đủ các phương tiện, bảo
đam chỉ huy thông suốt trong quá trình chiến đấu.
 
Trận tiến công yêu khu Trảng Bom là trận mở đầu của cánh đông
bắc cho quân ta tiến vào giải phóng Sài Gòn theo đường số 1 và
đường xa lộ Biên Hòa. 17 giờ ngày 26 tháng 4, khi tiếng súng đầu
tiên của Chiến dịch Hồ Chí Minh nỗ ở hướng đông thì Sư đoàn 341
đã ém gọn vào vị trí tập kết an toàn.
 
Đường hành quân của ta rất bí mật, nhưng địch vẫn tăng cường
pháo kích ngăn chặn. Ở hướng bắc, chúng bắn tới 1.200 - 1.500 quả
ngay vào các trục đường lớn và đọc bờ Suối Rết. Hàng ngày, 20 đến
25 lần tốp máy bay A37, F5 ném bom vào những nơi chúng nghỉ ngờ
có lực lượng ta trú quân. Chúng còn tung thám báo, biệt kích lùng
sục xung quanh yếu khu Trảng Bom đẻ phát hiện lực lượng ta. Song
mọi cố găng của chúng đều không mang lại kết quả. Các trung đoàn
bộ binh ta vẫn bí mật áp sát mục tiêu. Các khẩu pháo vẫn được chiến
sĩ ta kéo vào chiếm lĩnh trận địa.
 
18 giờ, các đơn vị đã chuân bị xong mọi mặt và đợi lệnh nỗ súng.
Sở chỉ huy sư đoàn nằm gọn trong khu rừng tre sát bờ Suối Rết.
Tre Đồng Nai khỏi phải nói về độ cứng, độ bẻn, đứng san sát nhau
 
như thành, như lũy. Hầm sở chỉ huy đặt dưới các khóm tre mà lớp
lớp rễ tre suốt mấy đời bám đắt, khó có loại bom đạn nào khoan nỗi.
 
Dù bom pháo địch vẫn bắn phá ác liệt, ngọn đèn dầu trong sở chỉ
huy vẫn soi rõ từng nét chì, từng bình độ, từng mục tiêu trên tâm bản
đồ tác chiến.
 
I9 giờ 30 phút, phó ban thông tin Bùi Ngọc Hướng kiểm tra I0
đầu dây đều thông suốt.
 
Cùng lúc Bộ Tham mưu Quân đoàn chỉ thị: “Địch ở Trảng Bom
có khả năng rút chạy, Sư đoàn 34l nhanh chóng tô chức tiền công”.
Lúc này là 20 giờ ngày 26 tháng 4. Sau 30 phút, Bộ Tham mưu lại
hối thúc: “Sư đoàn 341 báo cáo ngay kế hoạch chiến đấu”. Trong
lúc đó sở chỉ huy sư đoàn đang tranh luận sôi nổi. Có ý kiên cho
rằng địch đang rút chạy, nêu ta không nhanh chóng tiến công thì mất
thời cơ và không hoàn thành nhiệm vụ. Một ý kiến khác cho là địch
không rút chạy, chỉ có khả năng điều chỉnh lực lượng cho phù hợp.
Nếu ta tiến công sớm sẽ mất thời cơ. Căn cứ vào các ý kiến trên, Bộ
tư lệnh kết luận: Địch sẽ không bỏ Trảng Bom vì cự ly từ Trảng Bom
vào Biên Hòa không xa, nếu chúng bỏ Trảng Bom thì Biên Hòa sẽ
bị ta uy hiếp mạnh. Hơn nữa, chỉ còn bảy, tám giờ nữa thì trời sáng,
với một lực lượng đông như vậy địch sẽ không rút hết được. Cũng
có thể chúng điều chỉnh lực lượng cho phù hợp với tuyến phòng thú
Sư đoàn trưởng báo cáo lên quân đoàn, đồng thời chỉ thị cho pháo
binh bắn chặn Suối Đỉa và các mục tiêu trọng yếu khu Trảng Bom;
sử dụng tiểu đoàn 4 cắt rừng cao su, vận động bao vây chặt bọn
địch ở Suối Đỉa. 24 giờ, pháo binh ta bắn trúng đội hình hành quân
của địch ở Suối Đia, gây cho chúng thiệt hại nặng; một số lớn chạy
tán loạn vào rừng. Tiểu đoàn 4 đang vận động tới Suối Đia đã tóm
được hai tên (có một đại úy hậu cần chiến đoàn 48). Qua khai thác,
tù binh cho biết: sau khi giải phóng Bà Rịa, trục uường L5 ta đã hoạt
động, quân đoàn 3 địch đã điều lữ đoàn 3 ky binh và lữ đoàn 468
lính thủy đánh bộ đang án ngữ Trảng Bom về giải tỏa đường 15 và
đưa lữ đoàn 258 lính thủy đảnh bộ từ Long Bình cùng với sư đoàn
18 chưa kịp vá víu ra phòng thủ từ ngã ba Sông Thao đến Hồ Nai.
 
