Như vậy là địch đang điều chính lực lượng. Vậy yếu tố bất ngờ và
thời. cơ đề tiễn công vẫn còn. Địch điều chính lực lượng lúc này càng
bộc lộ thêm những chỗ yêu và sự lúng túng của chúng trong thế bố
trí phòng ngự bị động.
 
Sư đoàn chỉ thị cho các đài quan sát tiếp tục theo dõi hoạt động
của địch, đồng thời lệnh cho các đơn vị nâng đội hình áp sát mục
