Lúc này, ở các sở chỉ huy sư đoàn, trung đoàn, ai cũng nóng ruột.
Cả một tuyến phòng thủ như Trảng Bom, Suối Đia chỉ đột phá trong
bốn giờ. ta đã làm chủ, nay chỉ tuyến Hồ Nai gần chục kilômét mả
khiông chọc được. Các mũi, các hướng khác đang áp sát Sài Gòn.
Đài Tiếng nói Việt Nam lại đưa tin: “Biên Hòa đã giải phóng”. Rõ
rảmg địch ở Biên Hòa đã bỏ chạy, thế mà ở đây, còn cách Biên Hòa
gât+ hai chục kilômét, địch vẫn đánh chặn ác liệt. Bộ đội dồn ứ cà lại
trên đoạn đường Trảng Bom, Suối Địa.
 
Sơ chỉ huy sư đoàn sôi lên. Bức điện khân của Đại tướng Vô
Nguyên Giáp, Bí thư Quân ủy Trung ương, Bộ trướng Quộc phòng
vẫn đề trên bàn. Lời trong bức điện: “Thời gian là sức mạnh, là thời
cơ. Cần suy nghĩ tảo bạo, hành động táo bạo, thần tốc hơn nữa. Dùng
sức mạnh hỏa lực, đánh diệt lớn, vỡ lớn, tan lớn” như thúc giục.
Bộ tư lệnh sư đoàn nhận định: Do phán đoán tình hình địch không
sát nên tô chức tiến công chậm. Địch chỉ dùng một lực lượng nhỏ,
kết hợp với bọn cảnh sát ác ôn ở Hỗ Nai để ngăn chặn, làm chậm
bước tiến công của ta để tạo cho Quân đoàn 3 và các lực lượng khác
chuyên sang tây sông Đồng Nai lập phòng tuyến mới.
 
Sư đoàn quyết định cử phó sư đoàn trưởng Vũ Cao và cán bộ cơ
quan lên phía trước nắm chắc tình hình và trực tiếp chỉ huy. Kiên
quyết dùng hỏa lực mạnh áp đáo để đập nát bọn địch ở Hồ Nai. Sáng
29 tháng 4, với đội hình 5 xe tăng đi trước, tiếp đến là cao xạ 37,
súng máy 12,7 rồi đến bộ binh, toàn sư đoàn tiến công hành tiến vào
Hồ. Nai. Trong lúc pháo tăng và cao xạ đập tắt các ổ đề kháng của
địch trên các tháp chuông nhà thờ, trên các ô cửa sổ thì các chiến
sĩ bộ binh dùng lựu đạn, AK đánh chiếm từng tầng trệt, từng hằm
ngâm của dãy phó.
 
Đến 10 giờ, đội hình hành tiến của sư đoàn đén ngã ba Hồ Nai
đi Biên Hòa. Tới đây xe tăng của ta chưa qua được vì gặp ngay bón
tuyến hào chống tăng. Địch lại gom góp tàn quân có cả xe tăng
để chống cự. (Sau này mới biết địch còn có 60 xe tăng, lợi dụng
tuyến hào chống tăng và hậu cứ chiến đoàn 22 để chống cự. Bọn này
không nhận được lệnh của quân đoàn 3 ngụy (trưa 29 tháng 4 đê rút
về tây sông Đồng Nai để phòng ngự từ Thủ Đức). Địch mất liên lạc
lúc này trở thành khó khăn đối với ta.
 
Chỉ huy sư đoàn quyết định để một bộ phận cầm chân địch, còn
các đơn vị cứ phát triển, đánh chiếm các mục tiêu đã phân công.
Trung đoàn 273 sau khi diệt một tiểu đoàn địch trên đường vận động
ở ga Long Lạc đã nhanh chóng tiến công vào sân bay Biên Hòa.
Trung đoàn 270 vòng lên phía bắc đường số 1 đánh chiếm Hốc Bà
Thức và phát triển qua sân bay. Trung đoàn 266 đánh chiếm sở chỉ
huy quân đoàn 3 ngụy, một bộ phận vòng qua Hồ Nai, đánh vào
Long Bình.
 
Đêm 29 tháng 4, số xe tăng địch ở ngã ba Hố Nai bị Sư
đoàn 6 tiêu diệt.
 
Sáng 30 tháng 4, Trung đoàn 266, Tiểu đoàn 5, rồi Tiểu
đoàn 3 vượt qua sông Đồng Nai. Pháo địch từ trường sĩ quan Thủ
Đức, từ trường cảnh sát quốc gia và sau nhà máy xi măng bắn đữ
đội vào đoạn Long Bình - Thủ Đức. Pháo binh ta bắn chế áp các trận
địa pháo binh địch để bảo vệ cho đội hình tiến công hành tiến của
quân ta.
 
Khoảng 6 giờ sáng, pháo binh mặt đất, pháo cao xạ của Quân
đoàn 2, Quân đoàn 4 bắn giập đầu bọn pháo binh địch. Các trận địa
pháo của chúng tê liệt dần. Cũng là lúc từng đoàn xe đủ các loại của
quân ta đã vượt qua cầu Rạch Chiếc. Đến 10 giờ, Quân đoàn 2 đámh
tan tuyến phòng thủ cuối cùng của địch, bắn cháy hơn 10 xe tăng,
thiết giáp và đang vượt qua cầu Thị Nghè. Tuyến phòng thủ Sài Gòn
đã bị đập vỡ. Các binh đoàn chủ lực của quân ta tiến vào Sải Gòn
như thác đỗ. triều dânơ.
 
