c:hiếm Biệt khu Thủ đô và Tông nha cảnh sát ngụy
 
Trong cuộc Tông tiến công và nôi đậy mùa xuân 1975, Đoàn 232
v¿à Khu & tiến công trên hướng tây nam, đánh chiếm Biệt khu thủ đô
v/à Tông nha cảnh sát ngụy và đã hoàn thành xuất sắc nhiệm vụ này.
 
Đoàn 232 được thành lập tháng 2 năm 1975 gồm hai sư đoàn bộ
banh: Sư đoản 3 do đồng chí Đỗ Quang Hưng làm Sư đoàn trưởng;
Sšư đoàn 5 do đồng chí Vũ Văn Thược làm Sư đoàn trưởng, đông chí
Nguyễn Xuân Ôn làm Chính ủy và một số đơn vị binh chủng khác
hiợp thành.
 
Trước đó, Đoàn 232 do đông chí Nguyễn Minh Châu (Năm Ngà)
liàm Tư lệnh; đồng chỉ Trần Văn Phác (Tám Trần), Chính ủy; đồng
c:hí Trần Văn Nghiêm. Phó tư lệnh.
 
Khi triển khai Chiến dịch Hồ Chí Minh, đồng chí Năm Ngà và
một bộ phận chỉ huy của Đoàn 232 được rút về Sở chỉ huy cơ bản
NMiễn cùng đồng chí Đồng Văn Cống phụ trách các cơ quan Tham
mưu, Chính trị, Hậu cần của Miền để phục vụ cho Bộ Chi huy Chiến
(địch Hồ Chí Minh. Đoàn 232 lúc này do Trung tướng Lê Đức Anh
liàm Tư lệnh, Thiếu tướng Lê Văn Tưởng làm Chính ủy.
 
Sư đoàn 3 đánh chiếm tiêu khu Hậu Nghĩa, chỉ khu Đức Huệ,
IĐức Hòa - bảo đảm hành lang lộ 10 và tuyến sông Vàm Cỏ Đông
phối hợp với Trung đoàn 25 công binh làm cầu phà để xe cơ giới
wà binh khí kỹ thuật vượt sông Vàm Cỏ Đông và Kinh Xáng; Trung
(đoàn đặc công 27 diệt yêu khu Bà Hom, An Lạc, Bình Điền, khống
qchề và cắt lộ 4, giữ cầu, đảm bảo sườn và mặt sau cho Sư đoàn 9; Sư
qđđoàn 5 không đánh Mộc Hóa mà áp sát thị xã Tân An, cắt đường 4 từ
tthị xã Tân An đến Bến Lức và phía nam Tân An, đoạn Tân An - Tân
IHiệp, giữ cầu Bến Lức, cầu Tân An. Trung đoàn pháo binh 75 yểm
trợ hỏa lực cho Sư đoàn 3 đánh chiếm tiểu khu Hậu Nghĩa, sau đó
(di chuyên sang Mỹ Hanh chỉ viên cho Sư đoàn 9 tiến về Sài Gòn.
 
Ngày 26 tháng 4 năm 1975, Sư đoàn 5 tiến công sư đoàn 22 ngụy
lần lượt tiêu diệt từng đơn vị mới được bố sung tăng cường co cụm
từ cầu Voi đến cầu Bến Lức, Sư đoàn 5 khống ché và làm chủ lộ 4 từ
Tân An lên cầu Voi; Trung đoàn 16 thì đánh chiếm khu vực cầu Bình
Điền và An Lạc; hai trung đoàn đặc công 115 và 117 phối thuộc cánh
tây nam đánh chiếm vùng Phú Lâm.
 
Cùng thời điểm này, đồng chí Sáu Nhẫn (Bùi Văn Trữ), Phó
phòng công binh Miễn đang chỉ huy cán bộ, chiến sĩ công binh két
hợp với đồng bào địa phương huy động phương tiện tại chỗ để tạo
đường dẫn vượt sỉnh lầy và làm cầu phà ứng dụng (cầu phà dã chiến)
để phương tiện cơ giới, xe tăng và pháo của Đoàn 232 vượt sông
Vàm Cỏ Đông thuộc địa phận xã An Ninh, rồi tập kết về địa bàn
xuất phát tiến công thuộc vùng Mỹ Hạnh, Đức Hòa, theo lộ 10 tiến
về Sài Gòn.
 
Ngày 27 tháng 4, mũi tiến công phía nam theo tỉnh lộ 50 từ Cần
Giuộc lên đã lập bộ phận tiền trạm tại xã Bình Đăng, quận 8 dự kiến
28 tháng 4 sẽ chiếm cầu Chữ Y và ngày 29 tháng 4 chiếm lĩnh trận
địa, đợi lệnh tiến công vào mục tiêu.
 
Đến ngày 28 tháng 4, một sự kiện gây chắn động lớn trong hàng
ngũ quân địch: Một phi đoàn 5 chiếc máy bay A37, do phi công
Nguyễn Thành Trung hướng dẫn, đã táo bạo, bất ngờ oanh kích sân
bay Tân Sơn Nhất. Cùng ngày 28 tháng 4, Trần Văn Hương sau một
tuần nhận chức tổng thống thay Nguyễn Văn Thiệu, đã bát lực, đành
phải bàn giao chiếc ghế tổng thống cho tướng Dương Văn Minh.
 
Theo mệnh lệnh của Bộ chỉ huy Chiến địch Hồ Chí Minh, đúng
0 giờ ngày 29 tháng 4 năm 1975, đồng loạt cả năm cánh quân nỗ
súng tiến công vào nội thành Sài Gòn, đũng mãnh, táo bạo tiến đến
mục tiêu đã được phân công. Ở hướng tây, Sư đoàn 9, mũi chủ lực
của cánh quân tây nam, theo kế hoạch, sau khi cơ giới, tăng và pháo
vượt qua sông Vàm Cỏ Đông đêm ngày 28 tháng 4, ngày 29 tháng 4
Sư đoàn 9 hành quân về Sài Gòn.
 
