thành phố Sài Gòn cấp tương đương sư đoàn đánh chiếm Tông nha
cảnh sát ngụy, một trong năm mục tiêu chủ yêu của chiến dịch.
 
Bộ tư lệnh Quân khu § đã giao nhiệm vụ cụ thê cho các đơn vị.
Cánh quân đánh vào Sài Gòn, chiếm Tổng nha cảnh sát được quân
khu sử đụng gồm Trung đoàn 24, Trung đoàn 88, (Miền sẽ bổ sung
thêm Trung đoàn 271), có sự phối hợp Tiểu đoàn 1 và Tiểu đoàn 2
của tỉnh Long An. Bộ chỉ huy cánh quân này gồm các đồng chí: Võ
Văn Thanh - Thiếu tướng - Khu ủy viên - Phó chính ủy quân khu
làm Chính ủy; Huỳnh Văn Mến - Đại tá - Khu ủy viên - Phó tư lệnh
quân khu làm Tư lệnh; Lê Văn Phẩm - Khu ủy viên, Bí thư Tỉnh ủy
Mỹ Tho làm Phó tư lệnh phụ trách công tác đân vận; Nguyễn Văn
Chiểu - Tỉnh đội trưởng - Thường vụ Tỉnh ủy Long An làm Phó tư
lệnh, phụ trách quân sự địa phương và một số trợ lý chủ chốt tham
mưu tác chiến, chính trị, hậu cần, thông tin liên lạc...
 
Tình hình địch đang xáo động mạnh. Một số nơi, hệ thống đồn
bốt, lực lượng phòng vệ dân sự, bộ máy kìm kẹp của địch ở xã ấp
đã tự tan rã. Thế và lực của cách mạng đang áp đảo địch ở khắp nơi.
Nhân dân náo nức chờ lệnh tổng tiến công.
 
Trung đoàn 24 đang triển khai đánh chiếm căn cứ Đồng Tâm của
sư đoàn 7, cán bộ từ trung đoàn đến tiểu đoàn đang chuẩn bị trận
địa tiến công được lệnh hành quân về nam Long An nhận nhiệm vụ
mới. Đêm 14 tháng 4, toàn trung đoàn vượt qua quốc lộ 4 về đứng
chân ở huyện Chợ Gạo sát ranh giới Long An - nơi đây mới được
giải phóng nửa tháng. Mỗi tiểu đoàn trung bình gần 300 quân, súng
đạn trang bị đầy đủ.
 
16 giờ ngày 15 tháng 4 năm 1975, có điện triệu tập Trung đoàn
trưởng và Chính ủy Trung đoàn 24 đến gặp Bộ tư lệnh tiền phương
nhận nhiệm vụ ở xã Thạnh Phú Long thuộc huyện Tân Trụ, tỉnh
Long An.
 

 
10TR.ÂM DÁNH NỔI TIẾNG TRONG LỊCH SỬ VIỆT NAM
 
Đông chí Ba Thăng - Chính ủy Bộ tư lệnh tiền phương sau
khni thông báo vẫn tất tình hình đang diễn ra rất khẩn trương,
nê¿u r5 yêu cầu nhiệm vụ: Quân khu 8 có vinh dự tô chức cánh quân
đánh tư Long An vào thăng vùng ven Sài Gòn ở quận 8 đê nhận
nhniệm vụ tiếp theo. Lực lượng gồm Trung đoản 24, Trung đoàn 88,
Tiểêu đoàn 1, Tiếu đoàn 2 Long An và Trung đoàn 271 đang đến sau.
NFhiệm vụ chung là tiễn công thần tốc mớ đường theo trục đường
5B3 (lúc đó) đến rạch Cần Giuộc vào ngày *X” (ngày 27 tháng 4
nãám 1975). Trung đoàn 24 đảm nhiệm chủ công đi đầu, tiếp sau là
Trzung đoàn 88 dự bị, sau cùng là các tiêu đoàn của tỉnh Long An.
 
Tiến công trong hành tiến là chủ yếu: tiêu điệt, bức rút, bức hàng
toaàn bộ hệ thống đồn bốt trên trục tiễn công kê cả các lực lượng giải
töøa, bảo đảm hành lang an toàn từ phía sau ra phía trước. Mục tiêu
chủ yếu của Trung đoàn 24 trước mắt là tiêu điệt đánh chiếm chỉ khu
Ciần Giuộc. Trung đoàn 88 tiêu diệt chỉ khu Tân Trụ ở phía sau (đã
nổ) súng 2 ngày đêm chưa dứt điểm).
 
Tôi 15 tháng 4, toàn trung đoàn sang đứng chân ờ nam sông Vàm
Có Tây thuộc tỉnh Long An, đây là vùng mới giải phóng được ít
ngzày. Đêm 16 tháng 4, trung đoàn vượt sông Vàm Cỏ Tây bằng tàu
chở hàng của đân, mỗi tàu 40 - 50 đồng chí sang ém quân ở vùng
địach kiêm soát và triển khai đánh ngay trận mở đầu diệt 3 đồn ở xã
Tiân Chánh.
 
3 giờ sáng ngày 17 tháng 4, Tiểu đoàn 4 được lệnh nổ Súng, sau
ba tiếng bộc phá nẻ là hỏa lực các loại nổ dồn dập trong một phút -
nhiều đám cháy và tiếng nổ của đạn, lựu đạn, sau tám phút tất cả im
tiếng súng, Tiêu đoàn 4 đã báo cáo diệt xong ba đồn. Kết quả, ta loại
khhỏi vòng chiến đấu một đại đội, hai trung đội bảo an, diệt 20 tên, số
còàn lại chạy hết; thu 5 súng AR-15, M79.
 
Nhân dân đã sơ tán trước sáng I8 tháng 4, để lại lợn, gà, nhà cửa.
Biộ đội đóng ở ngoài vườn sẵn sàng đánh địch vào giải tỏa. 8 giờ
sáing ngày 18 tháng 4: I giang đoàn chạy từ Long An đến nhưng đều
 
từ Tư lệnh quân khu tiền phương, trung đoàn trưởng, cán bộ đại đội
cùng 1 tiểu đội trinh sát và 5 tự vệ thành phải ăn cơm trước sáng.
nằm im trên mặt đất không công sự, chỉ nhờ lá dừa nước che kin.
mặc cho tàu địch gầm rú, tiếng thả neo, tiếng kêu của xích sắt chạm
vào tàu nghe rợn tai.
 
Đến 4 giờ 30 phút chiều, giang đoàn này bắt đầu rút về Cần Giuộc.
 
Mọi người thở phào nhẹ nhõm bắt đầu nấu cơm. Đồng chí Tư
Nhân (Huỳnh Văn Mến) triệu tập cán bộ tiểu đoàn và trung đoàn
trưởng đến phỏ biến nhiệm vụ. Đồng chí yêu cầu đêm nay phải hoàn
thành trinh sát các mục tiêu ở cầu Nhị Thiên Đường và cầu Chữ Y,
từ đây đến đó còn trên dưới 10km. Chậm nhất 6 giờ sáng mai
(ngày 29 tháng 4) phải có mặt ở đây, sẽ có xuồng đón về Sở chỉ huy
để báo cáo sơ bộ quyết tâm đánh hai mục tiêu này. Đoàn cán bộ được
tăng cường hai tự vệ thành. Ăn cơm xong, tự vệ thành đã đưa lên
khỏi mặt nước một xuổng giấu kỹ, chở đoàn cán bộ qua sông Cần
Giuộc lên phía bắc qua lộ 5B. Đối chiếu với bản đồ, đoàn phải đi
qua một cánh đồng lầy lội bùn, ngang đầu gối, nước mặn, hướng về
Sài Gòn rực sáng ánh điện. Một trinh sát đạp phải mìn bị thương vào
bàn chân phải ở lại.
 
Trung đoàn trưởng vừa lội bùn cùng anh em vừa dự kiến phương
án tác chiến: Tiểu đoàn 4 đánh cầu Chữ Y, Tiểu đoàn 5 đánh cầu Nhị
Thiên Đường. Đến ngang cầu Nhị Thiên Đường, Trung đoàn trưởng
cho cán bộ dừng lại xác định phương án đi trinh sát: Tiểu đoàn 4 do
Tham mưu trưởng đi cùng vào điều tra cầu Chữ Y, còn Tiểu đoàn
5 và Tiểu đoàn 6 cùng Trung đoàn trưởng điều tra cầu Nhị Thiên
Đường xem địch bố trí lực lượng ra sao? Tiến công như thế nào?...
 
Kết quả đã xác định được hai đồn quân cảnh cấp đại đội bảo vệ
bai mục tiêu cầu Chữ Y và cầu Nhị Thiên Đường, đồn cầu đúc lô cốt
bê tông cốt thép 4 góc, hàng rào kẽm gai bao bọc quân lính đều ở
trong nhà, xung quanh là đường phố, nhà dân dày đặc. Ngoài ra có
một số vọng gác từ bên ngoài. Tiểu đoàn 4 phải đi xa hơn Tiểu đoàn 5
 
đến 6km đồng lầy vẫn về kịp nơi quy định trước sáng. Xuồng đã có
chuẩn bị sáng đưa cán bộ về Sở chỉ huy tiền phương đẻ báo cáo theo
đúng quy định. Ai cũng hốc hác vì quá vất vả sau 10 đêm liền không
ngủ, đêm 28 tháng 4 là căng thẳng nhất. Các đồng chí trong Bộ tư
lệnh quân khu gồm: Ba Thắng, Tư Thân và Năm Chiều (còn đồng
chí Chín Hải đã về chỉ đạo Mỹ Tho). Tất cả đang chờ nghe báo cáo
của Trung đoàn 24. Đồng chí Đàm Hữu Vắn - Chính ủy trung đoàn
cũng đến dự.
 
Sau khi nghe Trung đoàn trưởng Trung đoàn 24 báo cáo tình
hình, địa hình và sơ bộ quyết tâm đánh hai mục tiêu cầu Chữ Y và
cầu Nhị Thiên Đường bằng hai mũi, cách sử dụng lực lượng, các
đồng chí chỉ huy quân khu trao đổi và đều nhất trí. Sau khi giao
nhiệm vụ đánh chiếm cầu Chữ Y, cầu Nhị Thiên Đường, Tổng nha
cảnh sát (Trung đoàn 88 làm dự bị) đồng chí Ba Thắng xác định:
giờ *G” ngày 30 tháng 4 và đối với Trung đoàn 24 là 5 giờ ngày 30
tháng 4 năm 1975. Đồng chí Tư Thân cũng nhắn mạnh, căn đặn
thêm trung đoàn cách đánh, chốt giữ, mục tiêu là tiến thắng vào
chiếm Tổng nha cảnh sát, sẵn sàng nhận lệnh tiếp theo.
 
Đảng ủy trung đoàn họp mở rộng quán triệt nhiệm vụ lịch
sử trên giao và cụ thể hóa nhiệm vụ của trung đoàn và từng tiểu
đoàn. Bộ đội được chuẩn bị mọi mặt rất chu đáo, ai cũng dành
một bộ quần áo đen lành nhất để mặc khi giờ “G” sắp bắt đầu.
Cán bộ, chiến sĩ đã bất chấp máy bay trinh sát bay lượn trên đầu
cùng những máy bay phản lực quần lượn để yêm trợ cho trực thăng
bốc người di tản khỏi thành phố suốt ngày và đêm 29 tháng 4
năm 1975, công khai làm mọi công tác chuẩn bị ở ven địa hình. Trên
đường 5B xe cộ đủ loại vẫn tấp nập ra vào thành phố từ Cần Giuộc
lên, từ thành phó ra.
 
Vào 17 giờ ngày 29 tháng 4, bộ đội đã ngụy trang kín ba lô
súng đạn lần lượt ra khỏi ven địa hình, hình thành hai cánh quân
tiến về phía bắc nhằm hướng cầu Chữ Y và cầu Nhị Thiên Đường.
 
3 giờ sáng, Tiểu đoàn 5 đã báo cáo chuẩn bị xong, Tiêu đoàn 4 do
phải đi xa hơn nên 4 giờ 30 phút mới báo cáo chờ lệnh nô súng. Sở
chỉ huy trung đoàn đi sau Tiểu đoàn 5. Tiểu đoàn 6 đi sau cùng trên
trục đường 5B mặc cho xe cộ ngược xuôi chạy tấp nập. Đúng 5 giờ
sáng ngày 30 tháng 4, hai tiểu đoàn 4 và 5 bắt đầu nỗ súng tiến công.
 
Tiểu đoàn 5 đã diệt được một chốt, phát triển vào đánh đồn ở cầu
Nhị Thiên Đường, bị địch chống trả mạnh phải vòng tránh qua một
số nhà chiếm tầng cao đánh xuống bằng mọi cách, đến § giờ chiếm
được cầu Nhị Thiên Đường.
 
Tiểu đoàn 4 phải đánh chiếm từng mục tiêu từ ngoài vào trong,
cũng phải vòng tránh chiếm tầng cao đánh xuống đến 8 giờ 30 phút
mới chiếm được cầu Chữ Y. Địch ở các nhà tầng dùng đại liên băn
vào cầu Chữ Y và cầu Nhị Thiên Đường. Tiểu đoàn 6 được lệnh
đánh thẳng lên cầu Chữ Y theo đại lộ Phạm Thế Hiển để hợp đồng
với Tiểu đoàn 4 chuẩn bị phát triển vào quận 1.
 
Địch chiếm các tầng cao hai bên đại lộ Phạm Thế Hiển bắn
nhự đỗ đạn xuống đường để ngăn chặn, bộ đội ta vẫn dựa vào các
nhà tiến lên cầu Chữ Y. Tiểu đoàn 5 cũng được lệnh để lại một đại
đội chốt giữ cầu Nhị Thiên Đường còn lại cùng Tiểu đoàn 6 lên
cầu Chữ Y. Đến 9 giờ 30 phút thì cả Tiểu đoàn 4, 5 và 6 đều có
mặt ở cầu Chữ Y, địch ở phía bên kia cầu và nhà tằng bắn ngăn
chặn. B40, B41 cùng đại liên của ta đã diệt một số hỏa điểm,
chiếm được hai bên cầu Chữ Y. Các đơn vị tiếp tục vận động
qua cầu Chữ Y bất chấp hỏa lực ngăn chặn, đến 10 giờ 45 phút
thì Tiểu đoàn 4 và 6 cùng Tiểu đoàn 5 đã đánh chiếm Tổng nha cảnh
sát và khu quân cảnh. Đến II giờ, ta đã chốt chặn các công ra vào,
kiểm soát toàn bộ tình hình. Khoảng 1.000 tên địch đã vứt bỏ sắc
phục giơ tay xin hàng. Phóng viên nhiếp ảnh trong và ngoài nước
kéo đến quay phim, chụp ảnh cảnh ta chiếm Tổng nha cảnh sát, lúc
này là 11 giờ trưa ngày 30 tháng 4 năm 1975.
 
7. Vai trò nôi dậy của nhân dân Sài Gòn trong Chiến dịch
Hồ Chí Minh
 
Ngày 26-4-1975, cuộc hội quân lớn nhất của quân đội ta (tính
đến thời điểm đó) để triển khai thế trận chiến dịch đã hoàn thành
và bắt đầu tổng công kích vào Sài Gòn - Gia Định. Với lòng mong
ước quê hương được giải phóng đã tích tụ từ lâu, được các đòn tấn
công như vũ bão của bộ đội chủ lực hỗ trợ, ngày 2§ và 29 tháng 4,
hàng vạn nhân dân các huyện Củ Chi, Hóc Môn, Gò Vấp, Thủ Đức,
Bình Chánh đã nỗi dậy giải phóng ấp, xã, huyện ly của mình. Chỉ sau
hai ngày, hơn 40 cuộc đấu tranh điển hình của công nhân nhà máy
nước Thủ Đức (được hàng nghìn quần chúng các xã xung quanh hỗ
trợ) đã kiên quyết bao vây một tiểu đoàn lính thủy đánh bộ có hàng
chục xe tăng, thiết giáp yêm trợ, buộc chúng phải tháo lui không phá
được nhà máy.
 
Trong ngày 29 và đêm 29 rạng sáng 30 tháng 4, trước khi Š mũi
tiễn công của các quân đoàn vào nội thành thì đã có 107 điểm
nồi dậy tại chỗ của quần chúng dưới sự lãnh đạo của Đảng bộ địa
phương (31 điểm ở ngoại thành và 76 điểm ở nội thành). Trong đó có
32 điểm nôi dậy trong ngày 29 và đêm 29 rạng ngày 30 tháng 4;
34 điểm nỗi dậy trước 9 giở 30 khi Dương Văn Minh chưa tuyên bố
đầu hàng; 41 điểm trong và sau khi Dương Văn Minh tuyên bồ đầu
hàng nhưng các quân đoàn chủ lực chưa vào đến nơi.
 
Có được sự nôi dậy mạnh mẽ trên là do nhân dân được các cơ sở
Đảng lãnh đạo đã phối hợp chặt chẽ với bộ đội đặc công, biệt động
và quân địa phương đánh chiếm các mục tiêu đã quy định: giành
được chỉnh quyền ở cơ sở; phá kìm kẹp, gỡ đồn bốt, chiếm xưởng,
chiếm kho, chiếm công sở, giữ gìn bảo vệ máy móc không đề quân
địch phá trước khi rút chạy, sau đó bàn giao lại cho chính quyền cách
mạng (như hãng Vimytex, Vinatexco, kho xăng Esso, Shell, Caltex,
nhà máy điện, nhà máy nước, những cơ sở hạ tầng kinh tế....).
 
 704/731
 
Hầu như toàn bộ những cơ sở kinh tế lớn ở nội thành đều được
nhân dân nổi dậy chiếm giữ và giao lại cho cách mạng.
 
Sáng 30-4-1975, khi các mũi đột kích thọc sâu của các binh đoàn
chủ lực đánh vào các mục tiêu chủ yếu, then chốt trong nội đô, lập
tức hơn 400 cuộc nồi dậy của hàng chục nghìn quần chúng nhân dân
từ quận 1 đến quận 11, được mạng lưới tổ chức cơ sở Đảng, Đoàn,
tổ đội võ trang công tác, dân quân tự vệ, biệt động thành phát động,
đã nổi dậy truy quét ác ôn, kêu gọi binh sĩ đầu hàng, bao vây công
Sở, giải tán phòng vệ dân sự.
 
Nhân dân thành phố đã góp phần rất lớn làm tan rã hoàn toàn
40 vạn quân từ các hướng thua trận tháo chạy đồn về Sài Gòn, và
20 vạn quân ở các nơi thuộc ngoại thành. Nhân dân đã tham gia đắc
lực vào việc gìn giữ trật tự trong thành phố với gần 4 triệu người khi
chính quyền cách mạng chưa kịp tổ chức, khi mà bắt kỳ lúc nào ở
đâu bọn người lợi dụng “đục nước, béo cò” đều có thể có cơ hội đập
phá nhà công, cướp bóc nhà tư, trả thù, trả oắn cá nhân hay tuyệt
vọng làm càn.
 
Dưới sức mạnh của nhân dân, thành phó vẫn bình yên, nguyên
vẹn sau một chiến dịch lớn, mọi sinh hoạt của người dân vẫn
bình thường, cuộc sống dần dần ổn định.
 
8.. Giải phóng và làm chủ biển, đảo của Tổ quốc trong
Tổng tiến công và nổi dậy mùa Xuân 1975
 
Trong cuộc Tổng tiến công và nỗi dậy mùa xuân năm 1975, đồng
thời với việc giải phóng các tỉnh trong đắt liền, trong kế hoạch tác
chiến chiến lược và chỉ đạo thực hiện, Bộ Chính trị và Quân ủy
Trung ương đã đề ra nhiệm vụ giải phóng các đảo trên Biển Đông
từ rất sớm.
 
Chiến dịch Trị Thiên - Huế (từ ngày 5 đến 26-3-1975) và Chiến
dịch Đà Nẵng (từ 28 đến 29-3-1975) diễn ra trên một địa bàn rộng
lớn gồm các tình ven biển miền Trung: Quảng Trị, Thừa Thiên - Huế,
 
Đà Nẵng, Quảng Nam, Quảng Ngãi. Để làm tốt nhiệm vụ hiệp đồng
tác chiến chiến dịch và thực hiện quyền làm chủ biển, đảo sau khi
chiến dịch kết thúc, trước đó (tháng 2 năm 1975), Quân chủng Hải
quân đã bố trí lực lượng tàu thuyền chiến đấu tăng cường hoạt động
tuần tiễu ở bắc vĩ tuyến 17, sẵn sàng đối phó với những hoạt động
của hải quân địch và bảo vệ tuyến vận tải biển Cửa Việt - Đông Hà.
Đặc công Hải quân hoạt động sâu phía trong Huế, đánh sập cầu An
Lỗ và đánh chìm hải thuyền địch.
 
Trong thời gian chiến dịch đang phát triển mạnh, Bộ tư lệnh Hải
quân kịp thời tăng cường lực lượng tàu vận tốc nhanh và bộ đội đặc
công tinh nhuệ từ sông Gianh vào Cửa Việt để đây mạnh khả năng
hoạt động phối hợp trên chiến trường sông biển Trị - Thiên.
 
Bị đánh bại trên mặt trận Huế, quân địch tan vỡ, bỏ chạy ra
bờ biển tìm đường vào Đà Nẵng. Một biên đội thuyền máy của
Hải quân ta được lệnh vượt qua lưới lửa của địch, thả thủy lôi tại
cửa biển Thuận An, bịt cửa biển này không cho tàu địch ra vào cảng.
Sự xuất hiện kịp thời của lực lượng Hải quân ta tại đây cùng với
các lực lượng chiến đấu trên bộ đã chặn đứng đường rút chạy của
địch. Ngày 25 tháng 3, mấy vạn tên địch gồm đủ các sắc lính đang
co cụm bên bờ biển Hội An đã bị quân và dân ta tiêu diệt hoặc bị bắt
làm tù binh.
 
Ngày 26-3-1975, trong lúc cánh quân trên bộ của ta đang hành
quân thần tốc, áp sát Đà Nẵng, hải quân ta đã dùng biên đội thuyền
máy chở một phân đội đặc công táo bạo vượt qua làn đạn bắn chặn
của địch, chọc thẳng vào bán đảo Sơn Trà phối hợp tiến công từ
hướng biên.
 
Ngày 27 và 28 tháng 3, trước sức tiến công mãnh liệt của pháo
binh và hải quân ta, lực lượng tàu thuyền chiến đấu của địch đã phải
dần xa bờ, hủy bỏ việc chuyển quân rút chạy và di tản dân như kế
hoạch chúng đã định. Tối 29 tháng 3, phân đội đặc công Hải quân
 
A4 đẤn ¬ầu Thu Tủ nhất han Ưín thời với cáa hva lrynơ trân hô
 
giải phóng Đà Nẵng, tiếp quản bán đảo Sơn Trà và chiếm căn cứ đầu
não của vùng l duyên hải của hải quân địch. Cũng trong ngày, lực
lượng đặc công đã phối hợp với các lực lượng chiến đầu khác truy
lùng quân địch, quản lý căn cứ Đà Nẵng và tham gia giữ gìn trật tự,
an ninh vùng giải phóng.
 
Ngày 2-4-1975, biên đội tuần tiểu và phá lôi đầu tiên của Hải
quân ta đến quân cảng Đà Nẵng làm nhiệm vụ cảnh giới, rà phá thủy
lôi, mở đường cho các phương tiện tàu thuyền quân sự, quốc doanh
chở bộ đội, vận chuyển hàng hóa, vũ khí từ hậu phương lớn miền
Bắc vào chiến trường. Tiếp đó, các ra-đa cơ động của hải quân ta
được điều từ miền Bắc vào để quản lý vùng biển, đảo mới được giải
phóng và chuân bị cho các trận đánh tiếp theo.
 
Ngay sau khi giải phóng Đà Nẵng, Bộ Chính trị, Quân ủy Trung
ương và Bộ Tổng Tư lệnh chỉ thị cho Khu ủy, Quân khu ủy, Bộ
Tư lệnh Quân khu 5 và Bộ Tư lệnh Quân chủng Hải quân “nghiên
cứu và chỉ đạo thực hiện gấp rút, nhằm thời cơ thuận lợi nhất đánh
chiếm các đảo do quân ngụy miền Nam chiếm đóng thuộc quần đảo
Trường Sa. Đây là nhiệm vụ rất quan trọng” (Mật điện số 990B/TK
lúc 17 giờ 30 phút ngày 4 tháng 4 năm 1975 của Đại tướng Võ
Nguyên Giáp gửi đồng chí Võ Chí Công, Chính ủy Quân khu và
đồng chí Chu Huy Mân, Tư lệnh Quân khu 5).
 
Chấp hành mệnh lệnh của Bộ Tổng tư lệnh, Bộ tư lệnh Quân
khu 5 đã chỉ đạo lực lượng vũ trang phối hợp với du kích và nhân
dân tiến công và nổi dậy ngày 30 tháng 4 giải phóng Cù Lao Chàm,
Cù Lao Ré. Từ ngày 14 tháng 4 nhân dân đảo Cù Lao Xanh nổi dậy
giải phóng đảo. Ngày 10 tháng 4, bộ đội đặc công tỉnh Khánh Hòa
và một tiểu đoàn của Trung đoàn 19, sư đoàn 968 giải phóng đảo
Hòn Tre. Và đến ngày 27 tháng 4, ta giải phóng Cù Lao Thu (Khánh
Hòa) và toàn bộ các đảo ven biển Trung Bộ.
 
Trước tình hình cuộc tiến công của ta phát triển thuận lợi, giải
phóng toàn bộ Tây Nguyên và các tỉnh đồng bằng miền Trung,
 
ngảy 9 tháng 4 năm 1975, Bộ Tổng tư lệnh ra lệnh cho Quân khu 5
và Hải quân dùng lực lượng thích hợp chớp thời cơ đánh chiếm, giải
phóng các đảo thuộc quần đảo Trường Sa, nếu để chậm, quân đội các
nước khác chiếm, tình hình trở nên rất phức tạp không chỉ trên mặt
trận quân sự, mà cả mặt trận đâu tranh chính trị và ngoại giao. Vì
vậy, tiền công địch trên Biển Đông cũng phải thần tốc, táo bạo, bất
ngờ, chắc thắng. Bộ Tổng tư lệnh dự kiến cuộc chiến đâu trên biển
có thể sẽ gay go, ác liệt, vì ở đó có hạm đội 7 Mỹ và tàu chiến các
nước đang hoạt động. Trong chiến đấu, yêu cầu cán bộ, chiến sĩ ta
phải hết sức bình tĩnh xử trí tốt các tình huống, phải dũng cảm, mưu
trí và sáng tạo, đánh đúng đối tượng... Nếu quân nước ngoài chiếm
thì kiên quyết đánh chiếm lại.
 
Sự chỉ đạo đánh chiếm lại đảo ở Biển Đông của Quân ủy, Bộ
Tổng tư lệnh kịp thời, cụ thể, phù hợp với chính sách đối nội và đối
ngoại của Đảng trong giai đoạn kết thúc chiến tranh, đã tạo thuận
lợi cho bộ đội đánh chiếm đảo không gặp trở ngại gì lớn. Hải quân
của ta chuẩn bị đánh chiếm các đảo rất kỹ. Các tàu vận tải quân sự
673,674, 675 thuộc trung đoàn đặc công hải quân 126 do trung đoàn
trưởng Mai Năng chỉ huy được ngụy trang giả tàu đánh cá, bí mật
xuất phát và tiếp cận các đảo (đồng chí Mai Năng sau này là Thiếu
tướng, Tư lệnh Binh chủng Đặc công, Anh hùng lực lượng vũ trang
nhân dân). Tàu 673 do Nguyễn Ngọc Quề đội trưởng đội I chỉ huy
dùng xuỗng và phao cao su bí mật đồ bộ lên đảo. Đúng 4 giờ 30 phút
ngày 14 tháng 4, ta nổ súng tiến công địch. Sau 30 phút chiến đầu, ta
diệt và bắt 39 tên thuộc tiểu đoàn bảo an 371 quân đội Sài Gòn, giải
phóng đảo Song Tử Tây. Chiến sĩ Lê Xuân Phát kéo cờ Mặt trận dân
tộc giải phóng miền Nam Việt Nam lên cột cờ trên đảo, xác định chủ
quyền của Tổ quốc vào lúc 5 giờ ngày 14 tháng 4 năm 1975.
 
Song Tử Tây bị mắt, hệ thống phòng thủ của địch trên quần đảo
Trường Sa bị đe dọa. Địch liền điều thêm lực lượng trong đất liền
ra tăng cường phòng ngự cho các đảo còn lại và tìm cách chiếm lại
đảo Song Tử Tây. Chúng điều các tàu HQ16, HQ402 ra phản kích,
 
 712I1731
 
nhưng thế trận tan rã, địch quay về đảo Nam Yết, trung tâm quần đảo
Trường Sa để phòng thủ.
 
Lúc này trên vùng biển Trường Sa có nhiều tàu và máy bay
lạ xuất hiện. Quân ta tiếp tục củng có lực lượng, rút kinh nghiêm
chiến đấu.
 
Đúng 4 giờ sáng ngày 21 tháng 4, lực lượng tắn công đợt 2 bắt
đầu rời cảng Đà Nẵng hành quân lên đường, chiều ngày 24 tháng
4 bộ đội đến vị trí tập kết. Đêm 24 tháng 4, tàu 673 định đổ quân
chiếm đảo Nam Yết, nhưng gặp tàu khu trục địch, yếu tố bí mật
không còn nữa, tàu ta quay về đảo Song Tử Tây chờ thời cơ.
 
Tàu 641 tiến về đảo Sơn Ca, lúc 21 giờ 30 phút thì cách đảo Sơn
Ca 2 hải lý, lần thứ nhất đổ bộ không thành công do nước chảy xiết.
Chờ đến lúc 23 giờ 30 phút nước đứng, lần đổ bộ thứ hai bắt đầu,
sau 30 phút bộ đội đã đặt chân lên đảo. Địch trên đảo có 4 lô cốt, hai
dãy nhà tôn, các chòi canh, có hàng rào thép gai bao quanh. Sáng
ngày 25 tháng 4, trận đánh bắt đầu. Địch trên đảo ngoan có chiến
đấu cầm cự, nhưng sau 2 giờ thì bị bộ đội ta tiêu điệt, quân ta hoàn
toàn làm chủ đảo Sơn Ca. Các tàu tuần dương, khu trục của địch
lượn quanh các đảo nhưng không làm gì được bèn quay lại đảo
Nam Yết.
 
10 giờ 30 phút ngày 27 tháng 4, ta giải phóng đảo Nam Yết. Ngày
28 tháng 4 ta làm chủ hoàn toàn đảo Sinh Tổn. Cũng trong ngày 28
tháng 4 ta giải phóng đảo Trường Sa và An Bang. Hồi 9 giờ síng
ngày 29 tháng 4 năm 1975, phân đội cuối cùng của Trung đoàn 126
đặc công hải quân đổ bộ lên hòn đảo cuối củng của quần đảo Trường
Sa. Toàn bộ quân địch trên các đảo bị bắt làm tù binh. Bộ đội ta đã
hoàn thành xuất sắc nhiệm vụ, được Quân ủy Trung ương khen ngợi
“Hoàn thành nhiệm vụ có ý nghĩa chiến lược”.
 
Từ ngày 27-4-1975, trong lúc các cánh quân ta tiến vào giải
phóng Bà Rịa - Vũng Tàu... Hải quân ta đã điều lực lượng tàu
 
chiến đấu vào làm chủ Cam Ranh. Ngày 29 tháng 4, phối hợp với
các cánh quân xiết chặt vòng vây quanh nội đô Sài Gòn, các tàu
chiến của Hải quân ta cắp tốc hành quân vảo vùng biển Vũng Tàu.
Ngày 30 tháng 4, khi quân và dân ta tiến hành tổng công kích và nỗi
đậy ở nội đô Sài Gòn, thì bộ đội Hải quân được triển khai trên biển
ngăn chặn, truy bắt bọn tản quả địch chạy trốn.
 
Cũng trong ngày 30 tháng 4, Bộ Chính trị và Quân ủy Trung
ương điện cho Bộ Tư lệnh và Đảng ủy Mặt trận Sài Gòn chú trọng
việc giải phóng và đưa anh em tù chính trị của ta ở Côn Đáo và Phú
Quốc trở về.
 
Ngày I tháng 5, Trung ương Cục miễn Nam và Bộ chỉ huy chiến
dịch Hồ Chí Minh giao nhiệm vụ cho Hải quân tiến ra giải phóng
Côn Đảo. Khi các lực lượng của ta còn đang hành quân trên biển thì
ớ Côn Đảo, các chiến sĩ cách mạng của ta đã nổi dậy tiêu diệt địch,
giải phóng đảo. Hải quân ta và các lực lượng chiến đấu khác đã kịp
thời chuyển sang làm nhiệm vụ truy bắt bọn tàn quân địch chạy
trốn và phối hợp với các chiến sĩ cách mạng xây dựng chính quyền
trên đảo.
 
Ø Phú Quốc, khi nghe tin chính quyền Sài Gòn đầu hàng cách
mạng, nhân dân trong huyện đảo đã kéo vẻ thị trắn phối hợp với lực
lượng vũ trang giải phóng thị trắn và hoàn toàn làm chủ huyện đáo
trong ngày 30-4-1975.
 
Ở các đảo khác thuộc vùng biên phía Nam, phối hợp với cuộc
Tổng tiến công và nỗi dậy trên đất liền, năm bắt thời cơ chính quyền
và quân đội Sài Gòn đầu hàng cách mạng, các tổ chức Đảng đã lãnh
đạo nhân dân nỏi dậy tiến công, giảnh quyển làm chủ đảo trong các
ngày 30 tháng 4 và 1-5-1975.
 
361
 
chiến đấu vào làm chủ Cam Ranh. Ngày 29 tháng 4, phối hợp với
các cánh quân xiết chặt vòng vây quanh nội đô Sài Gòn, các tàu
chiến của Hải quân ta cấp tốc hành quân vào vùng biển Vũng Tàu.
Ngày 30 tháng 4, khi quân và dân ta tiến hành tổng công kích và nôi
đậy ở nội đô Sài Gòn, thì bộ đội Hải quân được triển khai trên biển
ngăn chặn, truy bắt bọn tàn qu địch chạy trốn.
 
Cũng trong ngày 30 tháng 4, Bộ Chính trị và Quân ủy Trung
ương điện cho Bộ Tư lệnh và Đảng ủy Mặt trận Sài Gòn chú trọng
việc giải phóng và đưa anh em tù chính trị của ta ở Côn Đảo và Phú
Quốc trở về.
 
Ngày I tháng 5, Trung ương Cục miền Nam và Bộ chỉ huy chiến
dịch Hồ Chí Minh giao nhiệm vụ cho Hải quân tiến ra giải phóng
Côn Đảo. Khi các lực lượng của ta còn đang hành quân trên biển thì
ở Côn Đảo, các chiến sĩ cách mạng của ta đã nỗi dậy tiêu diệt địch,
giải phóng đảo. Hải quân ta và các lực lượng chiến đầu khác đã kịp
thời chuyển sang làm nhiệm vụ truy bắt bọn tàn quân địch chạy
trốn và phôi hợp với các chiến sĩ cách mạng xây dựng chính quyền
trên đảo.
 
Ở Phú Quốc, khi nghe tin chính quyền Sài Gòn đầu hàng cách
mạng, nhân dân trong huyện đảo đã kéo về thị trần phối hợp với lực
lượng vũ trang giải phóng thị trấn và hoàn toàn làm chủ huyện đảo
trong ngày 30-4-l 975.
 
Ở các đảo khác thuộc vùng biển phía Nam, phối hợp với cuộc
Tổng tiến công và nỏi dậy trên đất liền, nắm bắt thời cơ chính quyền
và quân đội Sài Gòn đầu hàng cách mạng, các tổ chức Đảng đã lãnh
đạo nhân dân nỗi đậy tiến công, giành quyền làm chủ đảo trong các
ngày 30 tháng 4 và 1-5-1975.
 
Ngày 30 tháng 4 năm 1975, Chiến dịch Hồ Chí Minh toàn thắng,
1guy quyền Trung ương tuyên bố đầu hàng cách mạng vô điều kiện
›ũng là lúc quân, dân ta ở miền Đông Nam Bộ, đồng bằng sông Cửu
Long tiến công và nổi dậy giải phóng hoàn toàn các tỉnh Long An,
Bình Dương, Tây Ninh, Cần Thơ, Trà Vinh, Sóc Trăng, Rạch Giá,
Bạc Liêu, đảo Phú Quốc.
 
Ngày 1 tháng 5 năm 1975, quân và dân ta tiếp tục tiến công và
nổi dậy, giải phóng các tỉnh Mỹ Tho, Gò Công, Vĩnh Long, Chương
Thiện, Cà Mau, Long Xuyên, Kiến Tường, Sa Đéc và Côn Đảo,
Châu Đốc.
 
Như vậy, đến ngày 1 tháng 5 năm 1975, toàn bộ các tỉnh, các
thành phố trên đất liền, các đảo và quần đảo ở Biển Đông trên toàn
miền Nam Việt Nam được hoàn toàn giải phóng, khẳng định chủ
quyền thiêng liêng và bắt khả xâm phạm của Tổ quốc ta.
 
Thắng lợi hoàn toàn và trọn vẹn của cuộc Tổng tiến công và nỗi
dậy mùa Xuân 1975 mà đỉnh cao là Chiến dịch Hồ Chí Minh là
thắng lợi vĩ đại nhất, có ý nghĩa lịch sử quan trọng và tầm vóc thời
đại sâu sắc. Từ nay giang sơn Việt Nam được thu về một mối, chấm
dứt vĩnh viễn sự chia cắt hai miền. Đất nước Việt Nam mở ra một
trang sử mới trong độc lập tự đo và thống nhất Tổ quốc. Năm 1975
đã thực sự là một mốc son chói lọi trong lịch sử giữ nước của dân
tộc ta.', 'TEXT', '2026-06-05 07:02:55.843255', '2026-06-18 06:41:50.517768', '2026-06-18 06:41:49.762271', 'DRAFT'), ('2fcaea74-b134-4827-9bcc-244ab5a22f0b', '687b57fe-865c-496a-83b3-f83690885dd1', 'c06a4c2e-5549-4010-9475-2b19ec6fa1ef', 'CONTEXT', 'Chi tiết chiến dịch Điện Biên Phủ', null, '## A. ĐƯỜNG TỚI ĐIỆN BIÊN PHỦ

### 1. Vài nét về Điện Biên Phủ
Điện Biên Phủ nay thuộc tỉnh Điện Biên, trước đây thuộc tỉnh Lai Châu, có một vị trí chiến lược quan trọng ở Tây Bắc Việt Nam cả Đông Dương. Nơi đây cũng là một vùng kinh tế trù phú, rừng núi bao la điệp trùng đan xen những thung lũng màu mỡ.

Từ rất lâu, vùng Điện Biên còn có tên gọi là Mường Then (Mường Trời) hoặc Mường Theng - vẫn quen gọi là Mường Thanh. Trung tâm Điện Biên là cánh đồng Mường Thanh, nằm trên trục đường từ Thượng Lào qua Lai Châu, xuống Sơn La, về Hà Nội... và từ Tây Nam Trung Quốc xuống miền Trung Việt Nam, Trung Lào. Với địa thế đó, Điện Biên đã được xem là vùng đất mà một tiếng gà gáy, người dân ba nước (Việt Nam, Lào, Trung Quốc) đều nghe. Cũng vì thế mà Điện Biên là điểm gặp, nơi hội tụ của nhiều dân tộc, tiếng nói, văn hóa tộc người, phong tục tập quán khác nhau.

Bao bọc xung quanh cánh đồng Mường Thanh là những dãy núi cao thấp khác nhau, muôn hình muôn vẻ. Phía tây và nam là dãy núi Pú Xam Xao chạy dọc biên giới Việt - Lào, với đỉnh cao nhất là 1.897 mét, tạo thành một dây trường thành thiên nhiên, một bức bình phong kỳ vĩ. Phía bắc giáp với Pú Xam Xao là dãy Tây Trang - một hệ thống núi đá vôi, có nhiều cây cối um tùm và nhiều hang động tự nhiên khá hấp dẫn. Nơi đây có cửa khẩu Tây Trang - cửa ngõ của Điện Biên và cả vùng Tây Bắc thông sang vùng Thượng Lào. Phía đông có dãy núi cao từ 1.200 đến 1.700 mét. Từ dãy núi chính này xòe ra ba nhánh ôm lấy cánh đồng Mường Thanh.

Cánh đồng Mường Thanh nằm gọn giữa ba dãy núi lớn kể trên và còn được bao bọc bởi hai mươi ngọn núi cao thấp, lớn nhỏ khác nhau. Với chiều dài gần hai mươi kilômét, rộng từ sáu đến tám kilômét, Mường Thanh là cánh đồng phi nhiêu nhất của vùng Tây Bắc Việt Nam. Bởi vậy từ lâu nhân dân vùng Tây Bắc đã có câu: “Nhất Thanh, nhì Lò, tam Than, tứ Tấc”. Nghĩa là trong bốn cánh đồng, bốn vựa lúa lớn của Tây Bắc thì Mường Thanh lớn và trù phú nhất, thứ hai là là Mường Lò - cánh đồng Nghĩa Lộ thuộc tỉnh Yên Bái, thứ ba là Mường Than - tức cánh đồng Than Uyên (Lai Châu - giáp Yên Bái), thứ tư là Mường Tấc - tức cánh đồng Phù Yên ở phía nam tỉnh Sơn La.

Cuối cánh đồng Mường Thanh - về phía nam, con sông Nậm Núa tỏa ra một nhánh sông có “tính khí" thất thường. Mùa nước cạn, sông chảy hững hờ, hiền lành. Khi mưa lũ, sông trở nên hung dữ, như ngựa tụt dây cương, nên được nhân dân đặt tên là Nậm Rốm.

Do Điện Biên ở vào vị thế quan trọng và là miền đất trù phú nên từ xa xưa vùng đất này đã là nơi quần tụ sinh sống của nhiều dân tộc anh em. Những dân tộc định cư lâu đời nhất gồm có: người Thái, người Kinh, người Mông, người Tày, người Khơ-mú, người Cổng, người Lào, người Kháng, người Xinh-mun... Nhân dân các dân tộc anh em ở đây giàu truyền thống yêu nước, lao động cần cù, yêu chuộng hòa bình, sẵn sàng chiến đấu chống lại mọi thể lực áp bức và giặc ngoại xâm, bảo vệ độc lập chủ quyền quê hương, đất nước. Họ cũng là chủ nhân của những điệu dân ca trữ tình, những điệu múa mềm mại, uyển chuyển, đậm đà bản sắc dân tộc.

Điện Biên Phủ đã bị thực dân Pháp chiếm từ năm 1888 sau khi tên thực dân khóac áo nhà thám hiểm O-guyt-xtơ Pa-vi (Auguste Pavie) đã mò đến đây. Sau đó con đường mòn Lai Châu - Điện Biên Phủ được mang tên hắn - đường Pa-vi...

Điện Biên Phủ là “hạt nhân của đạo quan binh thứ 4" của Pháp ở Bắc Đông Dương. Từ năm 1939, Điện Biên Phủ đã có một sân bay dã chiến. Trong cuộc Nhật đảo chính Pháp ngày 9-3-1945, hàng ngân quân Pháp đã qua con đường Lai Châu chạy sang Trung Hoa. Năm 1945, quân Nhật rồi quân Tường đã có mặt ở Điện Biên Phủ. Khi ta ký Hiệp định sơ bộ ngày 6-3-1946 với Pháp, Pháp đã yêu cầu được đưa hơn 800 quân trở lại vùng này để làm nhiệm vụ tiếp phòng quân Tương.

### 2. Điện Biên Phủ được cả ta và Pháp chọn làm điểm quyết chiến chiến lược
Năm 1953, cuộc kháng chiến chống thực dân Pháp xâm lược của nhân dân ta đã bước vào năm thứ tám. Tám năm đó là những năm chiến đấu cực kỳ gian khổ và anh dũng của quân đội và nhân dân ta chống lại quân đội xâm lược của đế quốc Pháp có can thiệp Mỹ giúp sức. Thắng lợi của quân và dân ta trong hè thu 1953, đặc biệt là chiến thắng tây nam Ninh Bình, tạo thêm thuận lợi để cả nước bước vào chiến cuộc Đông Xuân.

Trước đó, với thắng lợi của chiến dịch Tây Bắc mùa đông năm 1952 và chiến dịch Thượng Lào cuối xuân - đầu hè năm 1953, cục diện chiến tranh ở Việt Nam nói riêng và ở Đông Dương nói chung càng chuyển biến mạnh theo hướng có lợi cho quân và dân ta, bất lợi cho thực dân Pháp và can thiệp Mỹ. Để cứu vãn tình thế, Chính phủ Pháp tiến hành cải tổ bộ máy lãnh đạo và chỉ huy quân Pháp ở Đông Dương, may chăng có được chính sách mới, tìm cho nước Pháp một “lối thoát danh dự”. Với hy vọng đó, Hăng-ri Na-va, một viên tướng tài năng, đang giữ chức Tham mưu trưởng Bộ tư lệnh lục quân Trung Âu thuộc khối quân sự Bắc Đại Tây Dương (NATO) được điều sang giữ chức Tổng chỉ huy quân đội Pháp ở Đông Dương thay cho tướng Xa-lăng bị triệu hồi. Tướng Na-va đã thông qua Hội đồng Quốc phòng tại Pa-ri bản kế hoạch chiến lược mới của mình, được chính giới Pháp và Mỹ đánh giá rất cao, mang tên là “kế hoạch Na-va".

Cho tới những ngày cuối tháng 10, đầu tháng 11 năm 1953, Na-va và bộ chỉ huy quân đội viễn chinh Pháp ở Đông Dương còn rất chủ quan. Với một số kết quả hoạt động quân sự của phía Pháp trong mùa thu 1953, Na-va cho rằng việc triển khai kế hoạch chiến lược mới của quân Pháp đang trên đà phát triển thuận lợi và kế hoạch tác chiến thu đông của ta đã bước đầu bị phá vỡ. Vì thế, cuộc hành quân Hải Âu đánh ra vùng tự do tây nam Ninh Bình vừa chấm dứt ngày hôm trước, thì ngày hôm sau (7-11-1953) Na-va cho phát đi một bức thư gửi các sĩ quan, binh lính thuộc quyền, trong đó ông ta giải thích: “Tôi có nói với các bạn rằng tôi sẽ nắm quyền chủ động bằng những cuộc hành quân lớn và tôi sẽ phóng vào lúc và nơi mà tôi sẽ lựa chọn. Cuộc hành quân Hải Âu là đòn đầu tiên trong những đòn mà tôi có ý định đánh vào đối phương. Trong cuộc hành quân đó, chúng ta đã đạt được mục tiêu của chúng ta: lợi thời gian, chúng ta đã buộc Bộ tư lệnh Việt Minh phải xét lại kế hoạch tiến công và sẽ phải sửa đổi lại tới một ngày mà họ mong có thể hoạt động mạnh mẽ. Chúng ta đã nắm quyền chủ động và chúng ta muốn giữ vững quyền đó”. Trong cuộc họp báo ngày 7-11-1953, trung tướng Cônhi, tư lệnh quân Pháp ở Bắc Bộ, đã tuyên bố: “...Tôi xin cải chính, cuộc hành quân Hải Âu không hề nhằm mục đích chiếm đóng vĩnh viễn đất đai. Vùng Nho Quan không có lợi gì cả, ta cũng chưa có ý định chiếm Thanh Hóa. Ta đổ bộ vào duyên hải Thanh Hóa là để đánh lừa Việt Minh mà thôi. Quả nhiên chúng đã bị lừa, ta đã đạt được mục đích. Chúng ta đã thắng lợi, loại trừ được Sư đoàn 320 ra ngoài vòng chiến, giam chân Sư đoàn 304 ở Thanh Hóa, trì hoãn được cuộc tiến công Thu Đông của Việt Minh vào đồng bằng Bắc Bộ, quân đội viễn chinh Pháp đã thành công trong việc mở đầu một chiến thuật tiến công mới (theo tin báo Tia sáng, Hà Nội, ngày 9-11-1953). Phụ họa những lời tuyên bố của giới quân sự Pháp, các tờ báo xuất bản ở Pa-ri, Sài Gòn, Hà Nội trong thời gian này đều đăng trên trang đầu nhiều bài ca ngợi “thắng lợi rực rỡ" của phía Pháp trong cuộc đánh ra tây nam Ninh Bình. Tờ Paris Press (Bản tin Pa-ri) ra ngày 2-11-1953 đưa ra lời bình luận: “Tướng Na-va đã thắng hiệp đầu trong cuộc đọ sức tay đôi với tướng Giáp".

Trong không khí lạc quan như vậy, bỗng nhiên Na-va nhận được báo cáo “Đại đoàn 316 đóng quân ở phía nam Hòa Bình từ ngày 15 tháng 11 sẽ di chuyển về xứ Thái, nơi mà nó đã có sẵn một trung đoàn (trung đoàn 176). Dự kiến Đại đoàn 316 sẽ đến Tuần Giáo vào khoảng từ ngày 7 đến 11 tháng 12 năm 1953". Tin này chứng tỏ rằng hướng tấn công chủ yếu của đối phương trong chiến cuộc 1953-1954 không phải là đồng bằng Bắc Bộ như ông ta và bộ chỉ huy quân viễn chinh Pháp ở Đông Dương đã phán đoán, mà có thể lại chính là Tây Bắc. Và như thế cả Thượng Lào cùng kinh đô Luông Phra Băng đều bị uy hiếp.

Tiếp tục thực hiện chiêu bài độc lập giả hiệu, ngày 22-10-1953 chính phủ Pháp đã ký với chính quyền tay sai một hiệp ước công nhận Lào là một nước độc lập trong khối liên hiệp Pháp. Việc để mất kinh đô Luông Phra Băng và Thượng lào ngay khi ký một hiệp ước “phòng thủ chung giữa Pháp và Lào vừa được ký kết, có thể dẫn tới những hậu quả chính trị, quân sự khó lường. Suy đi nghĩ lại, cuối cùng Na-va thấy cần phải “đi trước hành động của Đại đoàn 316 bằng cách tăng cường hệ thống bố trí ở xứ Thái, che chở cho Luông Phra Băng . Để thực hiện ý đồ đó, ngày 2 tháng 11, Na-va chỉ thị cho tướng Cônhi chuẩn bị chiếm đóng Điện Biên Phủ bằng một cuộc hành binh không vận vào trước ngày 1 tháng 12 (tức là khoảng 15 ngày, trước khi Đại đoàn 316 có thể đến được vùng này.

Điện Biên Phủ là một thung lũng rộng lớn như đã trình bày ở trên, cách Hà Nội khoảng 300 kilômét đường chim bay, cách Luông Phra Băng khoảng 200 kilômét. Thung lũng này nằm gần biên giới Việt - Lào, trên một ngã ba của nhiều tuyến đường quan trọng, có sông Nậm Rốm chảy theo hướng nam - bắc đổ xuống sông Nậm Hu và có sân bay Mường Thanh được xây dựng từ năm 1889.

Theo đánh giá của Na-va và nhiều nhà quân sự Pháp thì Điện Biên Phủ “là một vị trí chiến lược quan trọng chẳng những đối với chiến trường Đông Dương mà còn đối với miền Đông Nam Á - một trục giao thông nối liền các miền biên giới Lào, Thái Lan, Myanma và Trung Quốc”. Đó là “một cái chìa khóa để bảo vệ Thượng Lào", một “bàn xoay” có thể xoay đi bốn phía Việt Nam, Lào, Myanma, Trung Quốc. Từ Điện Biên Phủ, quân Pháp “có thể bảo vệ được Lào, rồi từ đó đánh chiếm lại các vùng đã mất ở Tây Bắc trong năm 1952-1953 và tạo điều kiện thuận lợi để tiêu diệt các sư đoàn chủ lực của đối phương nếu họ đến đấy”.

Việc tướng Na-va có ý định đưa quân lên chiếm đóng Điện Biên Phủ không phải là điều gì mới lạ. Trước đây Xa-lăng đã từng rất mong muốn đưa quân lên chiếm đóng Điện Biên Phủ, nhưng chưa thực hiện được. Tướng Cônhi cũng đã đề nghị với Na-va thực hiện điều đó từ tháng 6 năm 1953. Cônhi cho rằng “muốn giành chủ động phải chiếm đóng Điện Biên Phủ”. Nhưng tới khi Na-va quyết định hành động, thì do lo sợ sẽ thiếu quân để bảo vệ “đồng bằng có ích", Cônhi và một số sĩ quan dưới quyền của ông ta đã có những ý kiến trái ngược hẳn lại.

Ngày 4-11-1953, đại tá Ba-xchi-a-ni, tham mưu trưởng lục quân Bắc Bộ, đưa ra ý kiến phản đối chủ trương chiếm đóng Điện Biên Phủ với lý do là hiện nay Thượng Lào chưa có hiện tượng gì bị uy hiếp cả. Và cho dù trong trường hợp Thượng Lào có bị uy hiếp, thì cái xứ Đông Dương này, người ta không thể chỉ ngăn chặn bước tiến của Việt Minh trên một hướng, đó là khái niệm ở châu Âu, ở đây không có giá trị gì. Đáng lẽ quân Pháp phải được sử dụng tập trung để bảo vệ miền đồng bằng đang bị đe dọa, thì lại bị tung lên một miền rừng núi cách Hà Nội 300 kilômét làm một việc không có tác dụng gì thiết thực cả; “muốn hay không muốn, Điện Biên Phủ cũng sẽ trở thành một vực thẳm nuốt các tiểu đoàn của quân viễn chinh Pháp”. Cùng với ý kiến phản đối có tính chiến lược của Ba-xchi-a-ni, các sĩ quan tác chiến, không quân, hâu cần của Bô tham mưu Bắc Rô còn đưa ra những khó khăn về chiến thuật, kỹ thuật trong việc nhày dù chiếm đóng Điện Biên Phủ và việc phải bảo đảm tiếp tế bằng đường không cho một căn cứ lớn và lại ở cách xa miền đồng bằng như vậy.

Trung tuần tháng 11 năm 1953, sự kiện Đại đoàn 316 bắt đầu chuyển quân lên miền Tây Bắc đã tạm thời chấm dứt cuộc tranh cãi giữa các tướng tá Pháp. Gạt sang một bên những ý kiến bất đồng, trong cuộc họp ngày 17 tháng 11 tại tổng hành dinh quân đội Pháp ở Hà Nội, Na-va quyết tâm giữ vững ý định thực hiện cuộc hành quân Ca-xto chiếm đóng Điện Biên Phủ. Tướng Gin, nguyên chỉ huy trưởng tập đoàn cứ điểm Nà Sản được cử làm chỉ huy trưởng cuộc hành quân và như sau này, các tướng tá Pháp đã mô tả lại thì ngay chiều hôm ấy, “tại một dinh thự biệt lập ở Hà Nội, bốn sĩ quan dù, hai phi công cùng với cô thư ký của tướng Cônhi đã cho in rô-nê-ô và soạn những mệnh lệnh về cuộc hành quân Ca-xto sẽ được tiến hành ngày 18, 19 hoặc 20 tháng 11 năm 1953, tùy theo tình hình thời tiết tốt xấu... Chính họ cũng không biết rằng họ làm việc đó để chuẩn bị cho một trong những biến cố vĩ đại làm đảo lộn phương Tây.

Sau khi đã được chuẩn bị kỹ lưỡng, ngày 20-11-1953, cuộc hành binh Ca-xto đánh chiếm Điện Biên Phủ chính thức bắt đầu. Do chỉ tập trung được 60 chiếc Đa-cô-ta vào việc chở quân, đợt đầu (từ 10 giờ 35 phút đến 10 giờ 45 phút) quân Pháp thả hai tiểu đoàn dù xuống khu vực lòng chảo Điện Biên Phủ. Chiều 20 tháng 11 và trong các ngày tiếp sau đó chúng thả tiếp bốn tiểu đoàn khác và một đại đội công binh.

Vào thời điểm địch mở cuộc hành binh Ca-xto, về phía ta có trung đoàn bộ trung đoàn 48 và tiểu đoàn 910 đang đóng quân ở Điện Biên Phủ tranh thủ củng cố, huấn luyện và chuẩn bị tiêu diệt vị trí Mường Pần nhổi hơn cùng Đại đoàn 316 tiến đánh Lai Châu. Cuộc nhảy dù của địch có gây bất ngờ cho cán bộ, chiến sĩ trung đoàn 148. Nhưng tới khi nhận biết được triệu chứng quân địch sắp nhảy dù, bộ đội ta lập tức triển khai lực lượng chiếm giữ các vị trí có lợi và liên tục đánh trả địch suốt sáu tiếng liền. Đến 16 giờ ngày 20, do thời cơ diệt địch không còn, đạn hết, để bảo toàn lực lượng, cán bộ, chiến sĩ trung đoàn 148 rút vào rừng và sau đó đã chuyển về Mường Phăng chuẩn bị cho nhiệm vụ mới.

Về phía địch, sau khi thả sáu tiểu đoàn cơ động cùng một khối lượng lớn đạn dược, lương thực và các thiết bị chiến tranh xuống Điện Biên Phủ, quân Pháp bắt tay ngay vào việc xây dựng cấu trúc trận địa và tiến hành các hoạt động tiến công để mở tuyến giao thông đường bộ nổi Điện Biên Phủ với Lai Châu và Luông Phra Băng. Ngày 25 tháng 11, theo lệnh của Na-va, Cre-vo Cơ - chỉ huy quân đội viễn chinh Pháp ở Lào sử dụng sáu tiểu đoàn mở cuộc hành binh từ Luông Phra Băng lên khu giải phóng Lào ở lưu vực sông Nậm Hu. Cùng ngày hôm đó, sân bay Mường Thanh được sửa chữa xong và chiếc Đa-cô-ta đầu tiên của quân Pháp đã hạ cánh an toàn xuống khu vực Điện Biên Phủ.

Thấy cuộc hành quân chiếm đóng Điện Biên Phủ kết thúc tương đối trót lọt, Na-va và Cônhí tin rằng quân đội Pháp ở Đông Dương đã trở lại nắm quyền chủ động tiến công và tình thế trên chiến trường đang nhanh chóng được cải thiện theo chiều hướng có lợi cho phía Pháp. Trong cuộc họp báo ngày 22-11-1953, tướng Cônhi lớn tiếng tuyên bố với các nhà báo rằng cuộc hành binh Ca-xto “không phải là một cuộc nhảy dù biệt kích như Lạng Sơn, đây là khởi đầu của một cuộc tiến công đại quy mô”. “Điện Biên Phủ là một điểm chốt. Nếu tập đoàn cứ điểm Nà Sản lắp được trên các bánh xe lăn, có lẽ tôi đã chuyển nó lên Điện Biên Phủ ngay từ khi tôi nhậm chức cách đây 5 tháng”. Trong buổi tiếp đô đốc Ca-ba-ni-ê, phái viên của chính phủ Pháp ngày 20 tháng 11, mặc dù đã được thông báo chính thức là sẽ không có 9 tiểu đoàn quân tăng viện như Na-va đã yêu cầu, nhưng khi được nghe truyền đạt câu hỏi của tổng thống ...-ri-ôn và thủ tướng La-ni-en là "trong lúc quân đội viễn chinh Pháp vừa chiến thắng, trong lúc Triều Tiên vừa ký kết đinh chiến có nên đặt vấn đề ngừng bắn không", Na-va đã trả lời rằng tốt hơn hết nên chờ kết quả của cuộc chiến mùa đông, tình hình trong mùa xuân tới có thể sáng sủa hơn. Còn đối với việc Đại đoàn 316 đang tiến lên Tây Bắc, thì chỉ cần “một con nhím loại vừa" độ sáu tiểu đoàn như vậy cũng đủ để đối phó.

Có thể thấy rằng, mặc dù bộ chỉ huy quân đội viễn chinh Pháp ở Đông Dương đã tung lực lượng cơ động ứng chiến lên vùng rừng núi Tây Bắc, cho tới lúc này cuộc hành binh chiếm đóng Điện Biên Phủ đối với phía Pháp “vẫn còn là một cuộc hành binh thứ yếu có tính chất phòng vệ chiến lược và tính chất chính trị địa phương như một sử gia phương Tây đã nhận xét. Phải tới cuối tháng 11, đầu tháng 12 năm 1953 do một chuỗi các quyết định của cả hai bên tham chiến, Điện Biên Phủ mới trở thành một thử thách quyết định mà thực ra tướng Na-va rất muốn tránh trong chiến cuộc 1953-1954.

Ngày 25-11-1953, bộ chỉ huy Pháp nhận được báo cáo của phòng nhì (quân báo) là đêm qua tướng Giáp đã ra lệnh cho các đại đoàn 308, 312, 351 tiến quân lên miền Tây Bắc (sự thật không đúng như vậy). Trước đó, Đại đoàn 304 (thiếu một trung đoàn) cũng đã rời khỏi vùng tự do Thanh Hóa. Trung đoàn 66 của Đại đoàn 304 đã tiến vào chuẩn bị phối hợp cùng Đại đoàn 325 hoạt động ở miền Trung Đông Dương. Những tin này đã buộc Na-va và các tướng lĩnh dưới quyền của ông ta phải tìm cách đối phó.

Do lo ngại về những trận đánh lớn có thể diễn ra ở vùng rừng núi Tây Bắc, tướng Cônhi đề nghị một phương án phân tán chủ lực ta bằng các cuộc hành quân tập kích chớp nhoáng đánh lên Phú Thọ, Yên Bái hoặc Thái Nguyên để giữ chủ lực của ta lại. Nhưng đề nghị đó của Cônhi không được chấp nhận vì Na-va không tin rằng đối phương lại có thể khắc phục khó khăn bảo đảm tiếp tế được cho bốn đại đoàn chủ lực tác chiến dài ngày ở xa hậu phương như vậy. Na-va vẫn yên tâm khẳng định rằng chủ lực ta lúc này thực tế vẫn chưa có khả năng đánh diệt các tập đoàn cứ điểm như kiểu Nà Sản và việc chiếm đóng Điện Biên Phủ, tổ chức xây dựng ở đó một tập đoàn cứ điểm mạnh là hoàn toàn chính xác. Còn nếu chủ lực đối phương dám liều lĩnh kéo lên đây, thì quân viễn chinh Pháp cần tương kế, tựu kế biến Điện Biên Phủ thành một pháo đài vững chắc, vừa là một cái chốt, vừa là “một cái bẫy hay một cái máy nghiền, sẵn sàng nghiền nát các sư đoàn thép của đối phương, đồng thời lại vẫn bảo vệ được nước Lào”, ngăn chặn được các cuộc tiến công lớn của chủ lực đối phương vào cái “đồng bằng có ích”. Sau khi đã cùng tướng Cônhi đáp máy bay lên Điện Biên Phủ xem xét tại chỗ và cho thẩm tra lại một cách khá kỹ càng những tin tức tình báo về các hướng tiến công của chủ lực đối phương trong đông xuân này, Na-va quyết định chấp nhận giao chiến với ta ở Điện Biên Phủ. Trong bản chỉ thị gửi Cônhi ngày 3-12-1953, Na-va giao nhiệm vụ cho bộ chỉ huy quân đội viễn chinh Pháp ở Bắc Bộ phải bảo vệ Điện Biên Phủ bằng bất cứ giá nào và đưa thêm lực lượng lên tăng cường phòng ngự, xây dựng Điện Biên Phủ thành một pháo đài bất khả xâm phạm, một cử điểm mạnh hơn cả Nà Sản. Cụ thể cần thả dù thêm ba tiểu đoàn cơ động ứng chiến, đưa lực lượng phòng giữ Điện Biên Phủ từ sáu tiểu đoàn lên chín tiểu đoàn bộ binh và khoảng ba tiểu đoàn pháo. Đối với các đơn vị đồn trú ở Lai Châu thì có thể duy trì nếu điều kiện cho . phép, hoặc có thể co về tăng cường cho Điện Biên Phủ.

Ngày 5-12-1953, các đơn vị nhảy dù xuống Điện Biên Phủ được chuyển thanh binh đoàn tác chiến Tây Bắc, gọi tắt là GONO (Groupement Opérationnel du Nord Ouest). Vài ngày sau đó, chỉ thị tăng cường thêm ba tiểu đoàn cho Điện Biên Phủ của Na-va cũng đã được thực hiện.

Khi chấp nhận giao chiến với ta ở Điện Biên Phủ, tướng Na-va vẫn không hề nghĩ rằng nó lại có thể trở thành đòn quyết định nhất của toàn bộ chiến cuộc 1953-1954. Trung thành với những tư duy chiến lược của mình được thể hiện ở bản “kế hoạch Na-va" trong một bức thư mật gửi chính phủ Pháp ngày 7-12-1953, Na-va khẳng định rằng trong chiến cuộc này, ông ta vẫn tập trung sự nỗ lực chiến lược chủ yếu vào miền Trung Việt Nam. Bằng một cuộc hành quân quy mô lớn mang tên Át-lăng, ông ta sẽ chiếm đóng vùng tự do Liên khu 5 và toàn bộ các hoạt động quân sự của phía Pháp trong sáu tháng đầu năm 1954 sẽ phải phụ thuộc vào cuộc hành quân quan trọng đó. Nếu cuộc hành quân Át-lăng thành công thì dù có bị thất bại ở nơi khác, triển vọng chung của cuộc chiến tranh đối với phía Pháp vẫn đáng được coi là tốt đẹp.

Về phía ta, trung tuần tháng 11 năm 1953, sau khi đã hạ lệnh hành quân cho Đại đoàn 316, đơn vị có vinh dự được đi tiên phong trong cuộc tiến quân lên miền Tây Bắc và nhắc nhở các đơn vị khác chuẩn bị sẵn sang cơ động, ngày 19-11-1953 tại một vùng rừng núi Thái Nguyên thuộc căn cứ địa Việt Bắc, Bộ Tổng tư lệnh quân đội nhân dân Việt Nam mở hội nghị cán bộ phổ biến nhiệm vụ quân sự và kế hoạch Đông Xuân 1953-1954. Hội nghị kéo dài trong 5 ngày từ 19 đến 23 tháng 11 năm 1953. Tham gia hội nghị có các đồng chí Võ Nguyên Giáp, Nguyễn Chí Thanh, Trần Đăng Ninh, Văn Tiến Dũng, Hoàng Văn Thái cùng đông đảo cán bộ chủ trì các cơ quan thuộc Bộ Quốc phòng - Tổng tư lệnh, cán bộ chỉ huy các chiến trưởng từ Liên khu 5 trở ra và cán bộ chỉ huy các đại đoàn chủ lực 308, 304, 312, 316, 320, 325, 351. Đại tướng Võ Nguyên Giáp chủ trì hội nghị.

Hội nghị đã nghe Đại tướng Tổng Tư lệnh thay mặt Tổng Quân ủy phổ biến Nghị quyết của Bộ Chính trị và kế hoạch tác chiến của ta trong chiến cuộc Đông Xuân. Các đại biểu về dự hội nghị tích cực tham gia thảo luận từ chủ trương, phương hướng chỉ đạo tác chiến tới nhiệm vụ và những yêu cầu cụ thể của từng hướng chiến trường. Hội nghị họp đến ngày thứ hai thì địch nhảy dù xuống Điện Biên Phủ. Ngay tối hôm ấy Tổng Quân ủy và Bộ Tổng tư lệnh đã kịp thời họp bàn để xem xét, đánh giả tình hình. Nhận định và kết luận bước đầu của Tổng Quân ủy và Bộ Tổng Tư lệnh là:

“... Địch nhảy dù xuống Điện Biên Phủ, mặc dầu ta không phán đoán được cụ thể về địa điểm và thời gian, nhưng cũng nằm trong phạm vi phán đoán trước của ta là nếu Tây Bắc bị uy hiếp thì địch sẽ tăng viện lên hướng đó. Như vậy là trước sự uy hiếp của ta, địch đã phải bị động đối phó, phân tán một bộ phận cơ động lên Điện Biên Phủ để yểm hộ cho Tây Bắc, để che chở cho Thượng Lào, để phá kế hoạch tiến công của ta.
Rồi đây tình hịch địch có thể biến hóa thế nào nữa?
Chúng có thể vừa giữ Điện Biên Phủ, vừa giữ Lai Châu, một nơi chính, một nơi phụ, có thể lấy Điện Biên Phủ làm chính.
Nếu bị ta uy hiếp, chúng có thể co về một nơi và tăng viện thêm một chừng nào; cũng chả nhất định có về nơi nào, nhưng khả năng có về Điện Biên nhiều hơn.
- Nếu bị ta uy hiếp mạnh hơn, chúng có thể tăng viện nhiều và biến thành một tập đoàn cứ điểm (trong trường hợp này chúng có thể lấy Điện Biên làm nơi thiết lập trận địa), nhưng chúng cũng có thể rút.
Hiện nay ta chưa thể quyết đoán địch sẽ đóng hay rút, sẽ đóng nột nơi hay hai nơi, sẽ đóng lâu dài hay trong thời gian ngắn, sẽ tăng viện nhiều hay ít, v.v... Một là vì ta chưa có đủ căn cứ cụ thể để phán đoán âm mưu địch, hai là vì địch cũng có nhiều khó khăn, rút thì mất đất, tăng nhiều thì phân tán quân cơ động và có thể bị tiêu diệt nên chưa nhất định đã có chủ trương dứt khoát, hoặc hiện có chủ trương nhưng khi gặp khó khăn do sự đối phó của ta gây nên cũng có thể thay đổi.
Vô luận rồi đây địch thay đổi thế nào, địch nhày dù xuống Điện Biên Phủ căn bản là có lợi cho ta. Vì thế cần phải tìm cách kéo thêm chủ lực của chúng lên Điện Biên Phủ và giữ chúng lại đó”.

Từ những nhận định và kết luận trên, Bộ Tổng tư lệnh quyết định Đại đoàn 316 vẫn gấp rút tiến lên đánh địch ở Lai Châu và điều thêm Đại đoàn 308 lên để vây địch ở Điện Biên Phủ. Ở Phú Thọ, Yên Bái, Tuyên Quang, các đại đoàn 312, 351 và cả Đại đoàn 304 (thiếu) được lệnh phải tuyệt đối giữ bí mật và sẵn sàng đánh trả địch nếu chúng liều lĩnh tiến công lên vùng căn cứ địa của ta.

Ngày 23-11-1953 Hội nghị phổ biến kế hoạch Đông Xuân kết thúc, cán bộ chỉ huy các đơn vị, các chiến trường nhanh chóng trở về tổ chức, lãnh đạo bộ đội thực hiện nhiệm vụ được cấp trên giao cho. Theo sự hướng dẫn của Tổng Quân ủy và Bộ Tổng Tư lệnh, Bộ tổng tham mưu vừa theo dõi, đôn đốc các đơn vị triển khai thực hiện kế hoạch đã được xác định, đồng thời vừa khẩn trương nghiên cứu, xây dựng phương án đánh địch ở Lai Châu và Điện Biên Phủ. Đầu tháng 12 năm 1953, khi Na-va quyết định tiếp nhận cuộc giao chiến với ta ở Điện Biên Phủ và quyết giữ Điện Biên Phủ bằng bất cứ giá nào, thì phương án tiến công Điện Biên Phủ của ta về cơ bản đã được dự thảo xong.

Ngày 6-12-1953, Bộ Chính trị họp nghe Tổng Quân ủy báo cáo quyết tâm tiến công Điện Biên Phủ.

Về tình hình địch và phương hướng chiến dịch, phương án tác chiến của Tổng Quân ủy ghi rõ: “Tuy hiện nay chưa thể khẳng định nhưng muốn bảo đảm thực hiện được quyết tâm của Trung ương là tiêu diệt địch và giải phóng vùng Lai Châu - Phong Xa Lỳ cho đến Luông Phra Băng trong Đông Xuân thì phải nhằm trường hợp địch tăng cường thành lập tập đoàn cứ điểm mà chuẩn bị.

Trong trường hợp này, trận Điện Biên Phủ sẽ là một trận công kiên lớn nhất từ trước tới nay. Vì vây, sự chuẩn bị có nhiều khó khăn, cần ráo riết tập trung lực lượng mới làm kịp, nhưng nếu kiên quyết khắc phục khó khăn, hoàn thành được chiến dịch thì thắng lợi này sẽ là một thắng lợi rất lớn”.

Về bình lực và thời gian tác chiến, phải sử dụng chín trung đoàn bộ binh và toàn bộ pháo binh, công binh, phòng không và một bộ phận pháo cao xạ, tổng số là 35.000 người. Nếu tính cả Bộ chỉ huy chiến dịch khoảng 1.850 người và 4.000 tân binh bổ sung sẽ đưa lên làm hai đợt thì quân số phải cung cấp cho hỏa tuyến sẽ tăng lên 40.850 người, chưa kể dân công.
Ở trung tuyến (từ Sơn La trở về) quân số bộ đội phải bố trí đề bảo vệ tuyến cung cấp có 1.720 người. Quân số tổng quát của chiến dịch là 42.750. Thời gian tác chiến ở Điện Biên Phủ ước độ 45 ngày, nhưng còn tùy tình hình thay đổi, cũng có thể rút ngắn hơn.

Về nhu cầu nhân lực, vật lực: số nhân công phải huy động từ trung tuyến trở lên cần khoảng chừng 14.500 người, gồm cả dân công theo đơn vị, vận tải xe đạp và khuân vác, chưa kể số dân công của Hội đồng cung cấp mặt trận.

Thời gian phục vụ mặt trận, việc huy động gạo, thực phẩm, đạn dược... cũng được tính toán cụ thể. Về tình hình đường sá và kế hoạch vận chuyển cũng được chuẩn bị chi tiết, cụ thể và chu đáo. Tổng Quân ủy kiến nghị: Muốn bảo đảm sự thực hiện quyết tâm của Trung ương là giải phóng Lai Châu - Phong Xa Lỳ, vấn đề mấu chốt hiện nay trong công tác chuẩn bị là phải bảo đảm đường sá. Cần phải tập trung khả năng và có kế hoạch cụ thể để tích cực giải quyết ngay từ bây giờ, chậm lắm là đến cuối tháng Giêng năm 1954, cần phải bảo đảm cho xe kéo pháo chạy được.

Sau khi nghe báo cáo quyết tâm của Tổng Quân ủy, Bộ Chính trị phân tích và kết luận: Về địch, Điện Biên Phủ sẽ là một tập đoàn cứ điểm mạnh, nhưng chúng cũng có cái vếu cơ bản là bị cô lân mọi việc tiếp viện, tiếp tế đều phải dựa vào đường không. Về ta, với chất lượng đã được nâng cao thêm một bước trong chỉnh huấn, chỉnh quân, với kinh nghiệm sẵn có và sự tiến bộ về trang bị kỹ thuật, quân đội ta tới đây đã có thể đánh được tập đoàn cứ điểm. Vấn đề đường sá tiếp tế cho chiến dịch đúng là một khó khăn rất lớn. Nhưng với quyết tâm của toàn Đảng, cả hậu phương đang chuyển động trong cải cách ruộng đất sẽ tập trung toàn lực chi viện cho tiền tuyến và nhất định bảo đảm cung cấp cho chiến dịch.

Bộ Chính trị quyết định mở chiến dịch Điện Biên Phủ và nhất trí thông qua phương án tác chiến của Tổng Quân ủy.

Trong khi cơ quan tham mưu chiến lược của ta đang tập trung xây dựng phương án tiến công địch thì cán bộ, chiến sĩ Đại đoàn 316 và Đại đoàn 308 vẫn đang gấp rút tiến lên thực hiện nhiệm vụ đánh địch ở Lai Châu, vây địch ở Điện Biên Phủ.

Đêm 7-12-1953, đại đoàn bộ Đại đoàn 316 và Trung đoàn 174 hành quân tới ngã ba Tuần Giáo, còn trung đoàn 98 mới hành quân tới bên kia đèo Pha Đin. Một ngày trước đó, lo sợ bị ta chia cắt lực lượng, Cônhi vội và ra lệnh cho quân lính rút toàn bộ lực lượng khỏi Lai Châu, tập trung về phòng ngự Điện Biên Phủ. Kế hoạch tháo chạy khỏi Lai Châu được Cônhi đặt tên là cuộc hành quân Pòn-luých, một bộ phận được chuyên chở bằng máy bay, số còn lại rút theo đường bộ và ngày 18-12-1953 sẽ rút xong. Việc rút quân khỏi Lai Châu tuy cũng được cả Na-va và Cônhi tính đến từ trước, nhưng do sự xuất hiện nhanh chóng của Đại đoàn 316 trên vùng rừng núi Tây Bắc, làm cho quyết định của Cônhi “được đưa ra đột ngột đến nỗi binh đoàn biệt kích hỗn hợp không vận không có đủ thời gian để tập hợp 25 đại đội phụ lực người Thái đang được bố trí rải rác trong rừng rậm. Binh đoàn này chỉ có thể báo tin cho họ qua vô tuyến điện là phải chạy về Điện Biên Phủ một cách nhanh nhất”. Và để tới đích chúng sẽ phải vượt qua đoạn đường khoảng 100 kilômét và chắc chắn là sẽ rất nguy hiểm.

Được tin địch rút, ngay trong đêm mồng 7 tháng 12, sở chỉ huy tiền phương của Bộ Tổng tư lệnh lập tức chỉ thị cho Đại đoàn 316 nhanh chóng cho một bộ phận theo đường số 41 đánh thẳng vào thị xã Lai Châu, còn đại bộ phận lực lượng phải tập trung cắt đứt cho bằng được đường Lai Châu - Điện Biên Phủ để chặn đánh, tiêu diệt bọn địch đang rút chạy bằng đường bộ. Đồng thời Bộ cũng đôn đốc Đại đoàn 308 khẩn trương tiến lên bao vây địch ở Điện Biên Phủ.

Căn cứ vào nhiệm vụ trên giao và tình hình cụ thể của đơn vị, đồng chí Lê Quảng Ba, đại đoàn trưởng và đồng chí Chu Huy Mân, chính ủy Đại đoàn 316 quyết định sử dụng Tiểu đoàn 439 dưới sự chỉ huy trực tiếp của đồng chí Phạm Quang Vinh, phó chính ủy Trung đoàn 98 tiến đánh Lai Châu. Đại đoàn bộ cùng với trung đoàn 174, Tiểu đoàn 215 và trung đoàn bộ Trung đoàn 98 tiếp tục hành quân theo đường Tuần Giáo - Điện Biên, đến Nà Tấu sẽ xuyên rừng vượt đèo Pa Thông, cắt đường Lai Châu - Điện Biên Phủ ở quãng Pu San - Mường Pồn. Còn Tiểu đoàn 938, Trung đoàn 98 tạm dừng lại làm nhiệm vụ bảo vệ Tuần Giáo đề phòng địch nhảy dù tập kích vào phía sau, phá hậu phương trực tiếp của chiến dịch. Tuy đã 20 đêm liền hành quân nhưng toàn đại đoàn vẫn náo nức bắt tay ngay vào cuộc đuổi đánh địch.

Trên đường tiến quân vào thị xã Lai Châu, đêm 9-12-1953 Tiểu đoàn 439 được sở chỉ huy tiền phương của Bộ Tổng tư lệnh dùng xe chở gạo để chở bộ đội đến Nậm Mức (cách Tuần Giáo 45 kilômét). Vì đoạn đường tiếp sau quá xấu, ô tô không thể đi được, cán bộ, chiến sĩ Tiểu đoàn 439 lại xuống xe tiếp tục hành quân bộ. Tối mồng 10, đơn vị tiến đến Pa Ham (cách thị xã Lai Châu 32 kilômét). Pa Ham có một đồn nhỏ của địch, nhưng khi nghe tin chủ lực của ta đang tiến đánh Lai Châu, địch vội vàng rút một số vị trí lẻ co cụm về đây, nên quân số trong đồn đã tăng lên tới ba đại đội.

22 giờ, tiểu đoàn 439 nổ súng tiến công Pa Ham. Sau nửa giờ cầm cự, binh lính địch bỏ đồn tháo chạy. Tiểu đoàn 439 phát triển tiếp lên đánh chiếm đèo Cơ-la-vô. Đèo này nằm cách thị xã Lai Châu 14 kilômét, địa thế rất hiểm trở. Bình thường chỉ cần một đại đội chốt giữ thì hàng trung đoàn cũng khó vượt qua được. Nhưng hoảng sợ trước thế mạnh của ta, nên khi cán bộ, chiến sĩ tiểu đoàn 439 vừa xuất hiện địch đã vội vã tháo chạy.

24 giờ ngày 11-12-1953, tiểu đoàn 439 đến sát thị xã Lai Châu. Được đồng bào địa phương hướng dẫn, bộ đội ta vượt qua cầu sắt liên tiêp đánh bật địch ra khỏi các vị trí, hoàn thành việc giải phóng thị xã Lai Châu vào chiều ngày 12 tháng 12.

Trong khi tiểu đoàn 439 tiến đánh Lai Châu thì bộ phận lực lượng chủ yếu của Đại đoàn 316 sau bốn ngày hành quân gian khổ đã từ Tuần Giảo tới đường Điện Biên Phủ - Lai Châu. Trung đoàn 174 bố trí ở khu vực Mường Muôn, Mường Pồn, đón đánh quân địch từ Lai Châu chạy về. Trung đoàn 98 tiến xuống Pu San chặn đánh bọn địch từ Điện Biên Phủ kéo ra. Tiểu đoàn 888 Trung đoàn 176, theo nhiệm vụ đã được giao từ trước, tiếp tục hoạt động bám địch ở phía Him Lam - Bản Tẩu.

Sáng ngày 12, đại đội 674 tiểu đoàn 251 dẫn đầu đội hình Trung đoàn 174 tiến xuống Mường Pồn. Phát hiện trong bản có nhiều địch từ Lai Châu chạy về đang tạm dừng ở đó, Đại đội 674 tổ chức bao vây. Bọn địch có máy bay từ Điện Biên Phủ lên bắn phá yếm hộ, ráo riết phản kích phá vây. Mặc dù lực lượng ít, lại ở vào một địa thế không có lợi phải từ dưới thấp đánh lên điểm cao, nhưng với quyết tâm chặn bằng được quân địch tạo điều kiện thuận lợi cho lực lượng tiếp sau kịp tiến lên tiêu diệt chúng, cán bộ, chiến sĩ Đại đội 674 chiến đấu dũng cảm đánh lui nhiều đợt phản kích của địch. Chiến sĩ liên lạc Bế Văn Đàn mang lệnh đên cho tiểu đội Chu Văn Pù giữa lúc cả tiểu đội chỉ còn bốn người đang phải chặn đánh một cánh quân địch đông gấp nhiều lần. Địch từ trên cao tràn xuống. Chu Văn Pù có khẩu trung liên trong tay nhưng không tìm được chỗ đặt súng để bắn ngược lên. Bế Văn Đàn lao tới nhấc hai chân súng đặt trên vai mình và giục đồng đội bắn... Người chiến sĩ dũng cảm đó hy sinh, nhưng đợt phản kích của địch đã bị chặn đứng.

Trong cả ngày 12, lực lượng địch tạm dừng ở Mường Pồn vẫn bị Đại đội 674 vây chặt. Tảng sáng ngày 13, có Đại đội 317 kịp đến tiếp sức, bộ đội ta đã hoàn toàn làm chủ Mường Pồn, loại khỏi vòng chiến đấu hai đại đội thuộc Tiểu đoàn ngụy số 301 và một đại đội vận tải, diệt tại chỗ 95 tên, bắt sống 52 tên khác, thu nhiều vũ khí và lừa ngựa.

Cũng trong những ngày này, hai tiểu đoàn địch (tiểu đoàn dù lê - dương số 1 và tiểu đoàn dù ngụy số 5) từ Điện Biên Phủ kéo ra đón cánh quân ở Lai Châu rút về đã bị tiểu đoàn 888 chặn đánh ở Bản Tấu, loại khỏi vòng chiến đấu gần một trăm tên. Trưa ngày 13, các lực lượng còn lại của hai tiểu đoàn này mò ra được tới Pu San (đông nam Mường Pồn bốn kilômét). Tại đây, sau nhiều lần tổ chức xung phong đánh chiếm điểm cao 1.168 (một điểm cao khống chế rất lợi hại đang được các chiến sĩ tiểu đoàn 215 và đại đội phòng không 677 chốt giữ) không thành công, hai tiểu đoàn dù này vội vã rời Pu San, tháo chạy trở về Điện Biên Phủ. Trong những ngày sau đó, mặc dù máy bay địch đã giội nhiều bom đạn để chặn bước tiến của các chiến sĩ Đại đoàn 316, nhưng cũng không cứu nổi các cánh quân của chúng đang bị đánh tan tác trong rừng.

Qua 12 ngày đêm liên tục chiến đấu, truy kích, bao vây, tập kích trên núi rừng Tây Bắc hiểm trở, Đại đoàn 316 đã tiêu diệt và bức hàng 24 đại đội địch, giải phóng toàn bộ khu vực Lai Châu, uy hiếp Điện Biên Phủ từ phía bắc. Thắng lợi củ chiến dịch giải phóng Lai Châu là kết quả mở đầu xuất sắc của cuộc tiến công chiến lược Đông Xuân.

Mặc dù đã bị thất bại nặng ở Lai Châu và biết rằng một số đơn vị của ta đang tiếp tục tiến lên Tây Bắc, tướng Na-va vẫn chưa thấy được mối nguy hiểm sẵn đến đối với Điện Biên Phủ Ông ta vẫn đặt nhiều kỳ vọng vào “cái bẫy”, “cái máy nghiền” sẵn sàng nghiền nát các sư đoàn thép của đối phương và quyết tâm giữ nó bằng bất cứ giá nào. Ngày 22-12-1953, một lần nữa Na-va lại quyết tâm tăng cường thêm cho Điện Biên Phủ ba tiểu đoàn bộ binh và một đại đội xe tăng nhẹ, đưa lực lượng của binh đoàn tác chiến Tây Bắc (GONO) lên 12 tiểu đoàn và bảy đại đội bộ binh lẻ, hai tiểu đoàn và ba đại đội pháo, một đại đội xe tăng nhẹ, một đại đội vận tải với tổng quân số là 12.000 người.

Sau đồng bằng Bắc Bộ, Điện Biên Phủ đã trở thành nơi tập trung binh lực thứ hai của địch trên toàn chiến trường Đông Dương. Tuy vẫn quyết tâm giữ Điện Biên Phủ đến cùng, nhưng để đề phòng những trường hợp bất trắc, Na-va đã chỉ thị cho Cônhi và Cre-vơ Cơ bí mật chuẩn bị một kế hoạch rút lui khỏi Điện Biên Phủ. Ngày 23-12-1953, binh đoàn tác chiến Tây Bắc (GONO) cho một cánh quân vượt biên giới, sang bắt liên lạc với quân của Cre-vơ Cơ ở Xốp Nao (Thượng Lào) rồi rút ngay về Điện Biên Phủ. Nhưng bốn ngày sau đó, khi Trung đoàn 36 Đại đoàn 308 đã cơ động lên chốt ở Pom Lót, hình thành thể bao vây địch ở phía nam thì tuyến giao thông đường bộ nối giữa Điện Biên Phủ và Thượng Lào cuối cùng đã bị cắt đứt.

Như vậy, từ khi “kế hoạch Na-va” hình thành đến khi Điện Biên Phủ được cả ta và quân Pháp chọn làm điểm quyết chiến chiến lược, là cả một quá trình diễn ra cuộc đấu trí, đấu lực, khi công khai, khi thầm lặng giữa hai bộ thống soái. Na-va và nhiều tướng lĩnh Pháp, Mỹ và phương Tây đã từng giải thích vì sao bộ thống soái quân viễn chinh chọn Điện Biên Phủ để xây dựng tập đoàn cứ điểm, chấp nhận giao chiến với chủ lực ta. Họ nêu nhiều nguyên nhân, nhưng như trên đã trình bày, nổi bật lên là xuất phát từ vị trí chiến lược của Điện Biên Phủ; yêu cầu chiến lược về chính trị “bảo vệ Thượng Lào”; từ “con chuột biển” đến “con nhím" khổng lồ; quyết tâm sắt đá của Na-va dù cấp dưới không đồng tình, dù Pa-ri có can ngăn... Nhưng rồi cũng đến lúc thần kinh của viên tướng này cũng dao động.

Từ cuối tháng 12 năm 1953, Na-va đã ở trong tình thế tiến thoái lưỡng nan. Mọi dự kiến đã bị đào lộn hết. Quân Pháp đành phải phó mặc cho số phận: phải đánh với phương tiện của bản thân tập đoàn cứ điểm là chủ yếu.

## B. DIỄN BIẾN CHIẾN DỊCH ĐIỆN BIÊN PHỦ (ĐIỆN BIÊN PHỦ - ĐIỂM HẸN LỊCH SỬ)
Thực hiện kế hoạch tác chiến trong Đông Xuân 1953 - 1954, ngày 15 tháng 11 năm 1953, Đại đoàn 316 hành quân lên Tây Bắc, mở cuộc tiến công giải phóng Lai Châu. Phát hiện sự di chuyển của chủ lực ta lên hướng tây bắc, ngày 20 tháng 11, Na-va vội vã mở cuộc hành binh Ca-xto, đổ sáu tiểu đoàn Âu - Phi tinh nhuệ đánh chiếm Điện Biên Phủ, một địa bàn chiến lược quan trọng để giữ vững Lai Châu và bảo vệ Thượng Lào.

Ta kiên trì kế hoạch tiến công giải phóng Lai Châu, đồng thời tăng cường Đại đoàn 308 lên vây địch ở Điện Biên Phủ.

Ngày 3 tháng 12 năm 1953, Na-va quyết định bỏ Lai Châu, co lực lượng về Điện Biên Phủ, đồng thời gấp rút tăng cường lực lượng, phương tiện chiến tranh xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh, gọi là “Binh đoàn tác chiến Tây Bắc”. Đến ngày 15 tháng 12 năm 1953, quân địch ở Điện Biên Phủ đã lên đến 12 tiểu đoàn. Chúng hy vọng Điện Biên Phủ vừa là một cái chốt, vừa là một cái bẫy sẵn sàng nghiền nát các sư đoàn thép của đối phương.

Khi Na-va chấp nhận giao chiến với ta ở Điện Biên Phủ và quyết giữ Điện Biên Phủ bằng bất cứ giá nào, thì phương án tiến công Điện Biên Phủ của ta cũng cơ bản được dự thảo xong. Đầu tháng 1 năm 1954, Bộ Chính trị họp tại bản Tin Keo, xã Điềm Mạc, huyện Định Hóa, Thái Nguyên nghe Tổng Quân ủy báo cáo và chính thức hạ quyết tâm: “Tập trung đại bộ phận chủ lực thiện chiến của ta lên mặt trận Điện Biên Phủ mở chiến dịch tiến công tiêu diệt những lực lượng tinh nhuệ nhất của địch trong tập đoàn cứ điểm mạnh nhất của chúng trên chiến trường Đông Dương này”. Tại cuộc họp, Bộ Chính trị đã cử Bộ chỉ huy Chiến dịch Điện Biên Phủ gồm: Đại tướng Tổng tư lệnh Võ Nguyên Giáp trực tiếp làm Chỉ huy trưởng kiêm Bí thư Đảng ủy mặt trận; Hoàng Văn Thái, Tham mưu trưởng; Lê Liêm, Chủ nhiệm chính trị; Đặng Kim Giang, Chủ nhiệm cung cấp.

Phó Thủ tướng Phạm Văn Đồng làm Chủ tịch Hội đồng Cung cấp mặt trận Trung ương. Tổng quân ủy phân công đồng chí Trần Đăng Ninh, phụ trách toàn bộ vấn đề đường sá, tiếp tế, cung cấp của Mặt trận Điện Biên Phủ. Các đồng chí Nguyễn Chí Thanh, Chủ nhiệm Tổng cục Chính trị và Văn Tiến Dũng, Tổng Tham mưu trưởng ở tại Tổng hành dinh chỉ đạo hậu phương và các mặt trận phối hợp trên toàn quốc.

Ngày 22-12-1953, Chủ tịch Hồ Chí Minh trao cờ Quyết chiến quyết thắng cho quân đội, động viên các đơn vị giết giặc lập công.

Nhân dân các vùng tự do, vùng Tây Bắc mới giải phóng, vùng sau lưng địch đồng bằng Bắc Bộ thực hiện quyết tâm của Trung ương Đảng và Chủ tịch Hồ Chí Minh, dồn sức người, sức của cho chiến dịch.

Ngày 5 tháng 1 năm 1954, Đại tướng Võ Nguyên Giáp cùng với sở chỉ huy tiền phương của Bộ Tổng tư lệnh lên đường ra mặt trận Điện Biên Phủ.

Điện Biên Phủ có một vị trí chiến lược rất quan trọng như phần trước đã trình bày. Xung quanh thung lũng Điện Biên Phủ là một vùng rừng núi điệp trùng bao bọc. Núi có độ cao trung bình 500m, có mỏm đột xuất cao tới 1.461m. Thung lũng Điện Biên là cánh đồng bằng phẳng, đồng ruộng khô ráo, thỉnh thoảng nổi lên những đồi cao hơn mặt ruộng tám đến 20 mét, cá biệt có điểm cao tới 250m. Trong thung lũng có sông Nậm Rốm chảy theo hướng bắc nam đổ xuống sông Nậm Hu và có sân bay Mường Thanh được xây dựng từ năm 1889.

Thời tiết Điện Biên Phủ chia làm hai mùa rõ rệt. Mùa khô từ tháng 10 đến tháng 3, mùa mưa từ tháng 4 đến tháng 9. Vào mùa khô sương mù dày đặc từ 15 giờ ngày hôm trước đến tận 9 giờ ngày hôm sau. Mùa mưa, mưa kéo dài, nhiều lũ, độ ẩm lớn nên việc cơ động trong rừng vô cùng khó khăn.

Dân số Điện Biên Phủ có hơn hai vạn người, gồm 11 dân tộc khác nhau, đời sống nhân dân trong vùng còn rất khó khăn.

Về địch, đến khi ta nổ súng tiến công, chúng đã có gần bốn tháng để xây dựng và củng cố hệ thống phòng ngự ở Điện Biên Phủ thành một tập đoàn cứ điểm mạnh nhất Đông Dương lúc bấy giờ. Lực lượng phòng ngự ở đây có 12 tiểu đoàn và bảy đại đội bộ binh, hai tiểu đoàn lựu pháo 105mm (24 khẩu), hai tiểu đoàn súng cối 120mm (20 khẩu), một đại đội trọng pháo 155mm (4 khẩu), một tiểu đoàn công binh, một đại đội xe tăng (10 chiếc), một đại đội xe vận tải (khoảng 200 xe ô tô) và một phi đội máy bay thường trực (14 chiếc). Tổng số quân lúc đầu lên tới 11.800 tên, chủ yếu là lính dù và Âu - Phi tỉnh nhuệ, đặt dưới quyền chỉ huy của đại tá Đờ Cát-xtơ-ri.

Tập đoàn cứ điểm Điện Biên Phủ có 49 cứ điểm, mỗi cứ điểm đều có hệ thống công sự, hàng rào vật cản hỏa lực để độc lập chiến đấu, đồng thời những cứ điểm gần nhau lại được tổ chức lại thành cụm cứ điểm (trung tâm đề kháng). Tập đoàn cứ điểm có tám trung tâm đề kháng (mỗi trung tâm mang tên một thiếu nữ Pháp) và được chia thành ba phân khu:
* **Phân khu trung tâm (trận địa trung tâm)** là phân khu quan trọng nhất, nằm ở ngay giữa Mường Thanh, có năm tiểu đoàn chiếm đóng, ba tiểu đoàn cơ động (tức gần 2 phần 3 lực lượng của địch ở Điện Biên Phủ). Phân khu trung tâm được tổ chức thành năm trung tâm đề kháng bao bọc lấy cơ quan chỉ huy của tập đoàn. Các trung tâm đề kháng đó là: Trung tâm đề kháng đồi D (Đô-mi-nich), phòng ngự ở hướng đông bắc, gồm các cứ điểm D1, D2, E1, D3, 203, 204, 507, 508 do tiểu đoàn 3 An-giê-ri (3/3 RTA) chiếm giữ; trung tâm đề kháng đồi A (E-li-an), phòng ngự hướng đông và đông nam, là khu vực phòng ngự then chốt của trận địa trung tâm, gồm các cứ điểm C1, C2, A1, A3, 512, 506, 511 do tiểu đoàn 1 Ma-rốc (1/4 RTM) và tiểu đoàn 2 ngụy Thái (2e BAT) chiếm giữ; trung tâm đề kháng nam sân bay Mường Thanh (Clô-đín), phòng ngự hướng tây nam gồm các cứ điểm 309, 310, 311B, 305, 322, 603, 604, 607 do Tiều đoàn 1 lê dương (1/13 DBLE) chiếm giữ; trung tâm đề kháng tây sân bay (Huy-ghét) trực tiếp bảo vệ sân bay, gồm các cứ điểm 311, 311A, 206, 209, 307, do Tiểu đoàn 1 lê dương (1/2 REI) chiếm giữ. Trung tâm đề kháng Him Lam (Bê-a-tơ-ri-xơ) là vị trí phòng ngự đột xuất ở đông bắc cách Mường Thanh 2.500 mét, gồm các cứ điểm 101A, 101B, 102 do tiêu đoàn 3 lê dương (3/13 DBLE) chiếm giữ. Khu vực phía đông của phân khu trung tâm có các điểm cao có giá trị, địch đã xây dựng thành các cứ điểm rất lợi hại, đặc biệt là các ngọn đồi A1, C1, D1, E1...
* **Phân khu bắc** gồm hai trung tâm đề kháng: Trung tâm đồi Độc Lập (Ga-bri-en) do Tiểu đoàn 5 An-giê-ri (5/7 RTA) chiếm đóng, trung tâm Bản Kéo - Căng Na (An-nơ Ma-ri) phòng ngự ở hướng bắc, gồm các cứ điểm 104A, 104B, 105, 106 do tiểu đoàn ngụy Thái số 3 (32 BAT) chiếm giữ.
* **Phân khu nam** còn có tên gọi là Hồng Cúm (1 da-ben) có nhiệm vụ ngăn chặn quân ta tiến công từ phía nam lên. Phân khu này do binh đoàn cơ động số 6 chiếm giữ. Lực lượng cụ thể gồm tiểu đoàn lê dương số 3 (3/3 REI), Tiểu đoàn An-giê-ri số 2 (2/1 RTA) một đại đội pháo 105mm và một trung đội xe tăng có ba chiếc.

Trung tâm đề kháng Him Lam (Bê-a-tơ-ri-xơ) tuy thuộc phân khu trung tâm, nhưng cùng với các trung tâm đề kháng đổi Độc Lập và Bản Kéo của phân khu bắc tạo thành trận địa phòng ngự tiền duyên án ngữ phía bắc, ngăn chặn sự tiến công của ta từ hướng bắc và đông bắc.

Pháo binh của tập đoàn cứ điểm được chia thành hai căn cứ: căn cứ Mường Thanh có một đại đội pháo 155mm (bốn khẩu), một tiểu đoàn pháo 105mm (12 khẩu) và hai đại đội cối 102mm (16 khẩu), căn cứ Hồng Cúm có một tiểu đoàn pháo 105mm.

Đại đội xe tăng có 10 xe hạng nhẹ: bảy chiếc ở trận địa trung tâm, ba chiếc ở phân khu nam.

Với lực lượng đông, hỏa lực mạnh, hệ thống công sự vật cản được xây dựng vững chắc, hoàn chỉnh và tận dụng được thể lợi của địa hình, tập đoàn cứ điểm Điện Biên Phủ thực sự là một hệ thống phòng ngự mạnh chưa từng có ở Đông Dương lúc bấy giờ. Bộ chỉ huy Pháp coi Điện Biên Phủ là một “pháo đài không thể công phá” và tin chắc “sẽ gây cho Việt Minh một thất bại nghiêm trọng ở đây.

Về phía ta lực lượng tham gia chiến dịch lúc đầu gồm các đại đoàn bộ binh: Đại đoàn 308 (có Trung đoàn 102, 88, 36), Đại đoàn 312 (có Trung đoàn 141, 209, 165), Đại đoàn 316 (có Trung đoàn 174, 98, một tiểu đoàn của Trung đoàn 176); và Trung đoàn 57 thuộc Đại đoàn 304. Hỏa lực có Đại đoàn công pháo 351 gồm: trung đoàn pháo binh 45 (có hai tiểu đoàn pháo 105mm: 4 khẩu); trung đoàn sơn pháo 675 (có năm đại đội sơn pháo 75mm: 15 khẩu); trung đoàn pháo cao xạ 367 có hai tiểu đoàn cao xạ 37mm (24 khẩu) và hai đại đội súng máy cao xạ 12,7mm (24 khẩu). Tổng số quân chủ lực của ta khoảng hơn 40 nghìn, nếu tính cả tuyến hai thì số quân lên tới 55 nghìn.

Lực lượng phục vụ chiến dịch cũng rất lớn: 628 ô tô vận tải, 21.000 xe đạp thồ, 261.500 dân công cùng nhiều tàu thuyền, lừa, ngựa...

Sau khi Chiến dịch Điện Biên Phủ được Bộ Chính trị phê chuẩn mang mật danh Chiến dịch Trần Đình, ngày 14 tháng 1 năm 1954, tại Thẩm Púa, Đảng ủy và Bộ chỉ huy chiến dịch mở hội nghị cán bộ phổ biến kế hoạch tiêu diệt tập đoàn Điện Biên Phủ theo phương châm “Đánh nhanh, giải quyết nhanh".

Ý định ban đầu của ta là “Tập trung ưu thế binh lực, hỏa lực đột phá chủ yếu từ phía tây đánh thẳng vào trung tâm Mường Thanh, đồng thời từ phía đông giáp công...", dự kiến ngày 20 tháng 1 năm 1954 sẽ nổ súng.

Trong quá trình chuẩn bị chiến dịch ta thấy địch đã ráo riết xây dụng trận địa phòng ngự vững chắc hơn, đồng thời hàng ngày sử dụng từ 50 đến 60 chuyển máy bay chở từ 150 đến 200 tấn hàng tăng cường cho việc phòng thủ Điện Biên Phủ. Mặt khác, việc làm đường và đưa pháo vào trận địa của ta gặp rất nhiều khó khăn, ta chỉ dự kiến kéo pháo trong ba đêm song thực tế phải dùng một đại đoàn bộ binh kéo pháo trong bảy đêm liền mà pháo vẫn chưa vào hết vị trí. Bộ chỉ huy chiến dịch phải lùi thời hạn nổ súng vào 16 giờ ngày 25 tháng 1 năm 1954.

Trước sự tăng cường phòng ngự của địch và những khó khăn của ta về kéo pháo, Bộ chỉ huy chiến dịch nhận thấy nếu đánh theo phương châm “đánh nhanh giải quyết nhanh thì không đảm bảo chắc thắng. Đúng 15 giờ 45 phút ngày 25 tháng 1 năm 1954 (trước thời hạn nổ súng 15 phút), Bộ chỉ huy quyết định hạ lệnh đình chỉ cuộc tiến công, kéo pháo ra, rút bộ đội, dân công về vị trí tập kết, và tiến hành mọi công tác chuẩn bị theo phương châm “Đánh chắc, tiến chắc”, dùng cách đánh vây hãm tiến công, đột phá lần lượt để tiêu diệt tập đoàn cứ điểm. Đại đoàn 308 được lệnh tiến công sang Thượng Lào nhằm giúp Bạn mở rộng vùng giải phóng và nghỉ bình thu hút địch, tạo điều kiện cho các đơn vị ở Điện Biên Phủ rút ra chuẩn bị tiếp.

Theo kế hoạch mới, việc chuẩn bị và thực hành chiến dịch chia làm ba giai đoạn:
* **Giai đoạn 1:** hoàn thành mọi công tác chuẩn bị, chủ yếu là làm đường vận chuyển, xây dựng các trận địa pháo binh thật kiên cố, bí mật, triển khai đội hình bao vây khống chế sân bay.
* **Giai đoạn 2:** tiến hành đánh bao vây nhằm tiêu diệt các trung tâm đề kháng ngoại vi, hình thành và thắt chặt trận địa bao vây tiến công địch, thu hẹp dần phạm vi chiếm đóng, tiêu hao lực lượng, khống chế sân bay.
* **Giai đoạn 3:** tổng công kích tiêu diệt toàn bộ quân địch.

Về tác chiến, giai đoạn thực hành chiến dịch dự định chia làm hai đợt.
* **Đợt 1:** Tập trung lực lượng tiến công tiêu diệt các trung tâm đề kháng Him Lam, Độc Lập và Bản Kéo, phá vỡ thế trận phòng ngự ở phía bắc và đông bắc của tập đoàn cứ điểm, chiếm địa hình có lợi, siết chặt trận địa bao vây tiến công.
* **Đợt 2:** Mở các trận tiến công tiêu diệt các cụm cứ điểm trên dây điểm cao phía đông, đồng thời ở phía bắc tiến vào chiếm lĩnh sân bay, hình thành vòng vây lừa xung quanh tập đoàn cứ điểm, thu hẹp không phận và sự tiếp viện của địch, tạo thời cơ chuyển sang tổng công kích. Sở chỉ huy chiến dịch đặt tại Mường Phăng. Thời gian nổ súng dự định vào ngày 13 tháng 3 năm 1954.

Việc chuẩn bị cho chiến dịch theo phương châm “đánh chắc, tiến chắc được tập trung triển khai từ sau Hội nghị cán bộ chiến dịch ngày 7 tháng 2 năm 1954. Công việc nặng nề nhất là chuẩn bị đường cơ động và xây dựng trận địa kiên cố cho pháo. Lần này ta chủ trương bố trí pháo phân tán trên các điểm cao thành một đường vòng cung bao lấy tập đoàn cứ điểm để có thể ngắm bắn trực tiếp các mục tiêu dưới lòng chảo. Qua nghiên cứu thực địa, ta tìm được sáu trận địa cho các đại đội lựu pháo 105mm. Cự ly từ các trận địa pháo đến trung tâm Mường Thanh khoảng từ sáu đến tám kilômét (tức nằm gọn trong trong tầm bắn có hiệu quả của pháo binh hạng nặng của ta). Pháo và đạn được đặt trong hầm khoét sâu vào triền núi và được ngụy trang kín đáo. Để đưa pháo lớn vào các trận địa đã lựa chọn ta phải mở năm tuyến đường cơ động với tổng chiều dài 63 kilômét. Đường phải đủ rộng cho xe pháo đi lại được dễ dàng và phải giữ được bí mật nghiêm ngặt. Các con đường mới đều qua các sườn núi ngọn đèo và nằm trong tầm hoạt động của phi pháo địch nên công việc hết sức khó khăn Nhiệm vụ làm đường do trung đoàn công binh 151, Đại đoàn 312 và 316 đảm nhiệm.

Cùng với việc xây dựng trận địa pháo các đại đoàn bộ binh còn tổ chức xây dựng một hệ thống công sự trận địa liền công quy mô lớn. Các sở chỉ huy, hầm thương binh, hầm nghi đều được cấu trúc kiên cố.

Công tác đảm bảo hậu cần cho chiến dịch'' được Trung ương Đảng và Chính phủ đặc biệt quan tâm. Theo tính toán, khối lượng vật chất đảm bảo cho chiến dịch đánh theo phương châm, đánh chắc, tiến chắc tăng vọt lên gấp hai, ba lần. Riêng về lương thực, tổng số gạo cần huy động không phải là trên bảy nghìn tấn như trước mà là trên 20 nghìn tấn. Trung ương Đảng và Chính phủ đã động viên toàn Đảng toàn dân tập trung toàn lực chi viện cho tiền tuyến, đảm bảo cho chiến dịch Điện Biên Phủ toàn thắng. Hệ thống đường vận chuyển cơ giới, đường thủy và đường bộ được tổ chức chặt chẽ để đảm bảo cho chiến dịch.

Tổng cục Cung cấp tiền phương được tăng cường thêm lực lượng (tổng quân số gồm 3.168 cán bộ, chiến sĩ và hơn ba mươi nghìn dân công) để tổ chức lại một bộ máy hậu cần chiến dịch gồm sở chỉ huy hậu phương, các kho, các tuyến vận tải, các đội điều trị... Ta đã tổ chức ba tuyến hậu cần chiến dịch'', mỗi tuyến đều có một ban chỉ huy riêng, không những chỉ đảm nhiệm công tác vận tải quân sự mà còn làm cả nhiệm vụ bảo đảm hậu cần, thống nhất chỉ huy các ngành hậu cần trên toàn tuyến.

Vào cuối thượng tuần tháng 3, sau một thời gian cố gắng liên tục, công tác chuẩn bị mọi mặt cho cuộc tiến công tập đoàn cứ điểm Điện Biên Phủ đã hoàn thành, thế trận chiến dịch đã triển khai xong, các đơn vị đã sẵn sàng nổ súng vào đúng ngày quy định. Trong thực tế, chiến dịch được tiến hành theo ba đợt:

**Đợt 1 (từ 13 đến 17 tháng 3 năm 1954): Tiêu diệt hai cụm cứ điểm Him Lam, Độc Lập, bức hàng cụm cứ điểm Bản Kéo.**
Nhiệm vụ của đợt tiến công thứ nhất là tiêu diệt cả ba trung tâm đề kháng Him Lam, Độc Lập và Bản Kéo, phá vỡ thế trận phòng ngự từ tây bắc sang đông bắc tập đoàn cứ điểm, đánh chiếm các vị trí vành ngoài, tạo điều kiện để ta thắt chặt vòng vây và tiến công vào khu trung tâm.

Nhiệm vụ cụ thể các đơn vị được phân công như sau: Đại đoàn 312 (thiếu trung đoàn 165) tiến công trung tâm đề kháng Him Lam; Trung đoàn 165 Đại đoàn 312 và Trung đoàn 88 Đại đoàn 308 tiến công trung tâm đề kháng Độc Lập; Trung đoàn 36 Đại đoàn 308 tiến công trung tâm đề kháng Bản Kéo; Đại đoàn 316 (thiếu Trung đoàn 176) tổ chức nghỉ bình và bí mật xây dựng trận địa tiến công ở phía đông phân khu trung tâm; Trung đoàn 57 Đại đoàn 304 tổ chức hỏa lực kiềm chế pháo binh địch phân khu Hồng Cúm; Đại đoàn công pháo 351 bắn phá hoại công sự địch trong các trung tâm đề kháng chi viện cho bộ binh tấn công, kiềm chế pháo binh địch, tập kích hỏa lực vào sân bay, sở chỉ huy, kho tàng của chúng.

Lúc đầu, ta định đồng thời đánh cả Him Lam, Độc Lập và bao vây Bản Kéo. Nhưng khi trinh sát lần cuối, phát hiện địch bố trí nhiều hỏa điểm tiền duyên ở Him Lam và Độc Lập, Bộ chỉ huy chiến dịch quyết định tập trung pháo ngắm bắn trực tiếp đánh Him Lam trước, rồi nhanh chóng cơ động pháo sang đánh Độc Lập sau.

Trung tâm để kháng Him Lam có năm điểm cao được tổ chức thành ba cứ điểm vững chắc do tiểu đoàn 3 thuộc bán lữ đoàn lê dương số 13 (3/13 DBLE) phòng giữ. Cứ điểm 1 (102) ở phía tây, gồm hai cao điểm 515 và 507, là điểm tựa chủ yếu có sở chỉ huy tiểu đoàn. Cứ điểm 2 (101A) ở đông bắc gồm hai cao điểm 517,5 và 505. Cứ điểm 3 (101B) ở phía nam là đồi trọc, thấp hơn hẳn cứ điểm 1 và 2. Ở từng cứ điểm trận địa phòng ngự được xây dựng vững chắc, có nhiều lô cốt và chiến hào, vòng ngoài có bốn đến sáu hàng rào dây thép gai và nhiều bãi mìn rộng từ 100 đến 200m.

Xác định đây là trận then chốt mở màn chiến dịch, Tư lệnh chiến dịch giao nhiệm vụ đánh Him Lam cho Đại đoàn 312 và tăng cường cho đại đoàn hai đại đội sơn pháo 75mm (6k), hai đại đội cối 120mm (8k), hai đại đội cối 82mm (8k). Trong quá trình chiến đấu, đại đoàn còn được hai đại đội lựu pháo 105mm chỉ viện trực tiếp.

Theo kế hoạch, 16 giờ pháo binh sẽ bắn chuẩn bị 15 phút, sau đó chỉ viện trực tiếp cho Đại đoàn 312 tiến công. Phát hiện ta xây dựng trận địa tiến công, khoảng 12 giờ ngày 13, địch cho một đại đội bộ binh cùng hai xe tăng từ Mường Thanh ra đánh phá. Bộ chỉ huy chiến dịch lệnh cho đại đội 806 (lựu pháo 105mm) bắn 20 quả vào trung tâm đề kháng Him Lam. 18 quả đạn của ta bắn trúng mục tiêu, tên thiếu tá Pê-giô tiểu đoàn trưởng cùng ba sĩ quan khác bị chết trong loạt đạn này, bọn địch đi lùng sục hoảng sợ bỏ chay về Mường Thanh.

Đúng 17 giờ, pháo 105mm của ta bắn cấp tập, mãnh liệt vào các trận địa pháo của địch ở 307A, 307B, chân đồi A và D, sau đó chuyển sang bắn phá hoại sân bay và cứ điểm 1, cứ điểm 3. Tranh thủ thời cơ địch bị chế áp, hỏa lực các cỡ của Đại đoàn 312 vào chiếm lĩnh trận địa, tham gia bắn phá hoại, chi viện trực tiếp cho bộ binh chiếm lĩnh trận địa xuất phát xung phong. Kết quả hỏa lực bắn chuẩn bị rất tốt, đã làm tê liệt các trận địa pháo, sân bay, phá hủy nhiều mục tiêu, công sự trận địa hỏa lực của địch, chi viện có hiệu quả cho các tiểu đoàn bộ binh hoàn thành việc chiếm lĩnh trận địa tiến công.

Từ 18 giờ 30, bộ binh ta bắt đầu mở cửa trung đoàn 141 (ba tiểu đoàn) sử dụng tiều đoàn 11 làm nhiệm vụ chủ công, tiến công trên hướng bắc tiêu diệt cứ điểm 102; Tiểu đoàn 428 làm nhiệm vụ trợ công, tiến công trên hướng đông bắc tiêu diệt cứ điểm 101A. Trung đoàn 209 sử dụng Tiểu đoàn 130 tiến công trên hướng đông nam tiêu diệt cứ điểm 101B.

Cuộc chiến đấu diễn ra hết sức ác liệt, nhất là trên hướng chủ yếu khi tiến công cứ điểm 102. Đây là cứ điểm gần nhất của trung tâm Him Lam, đại đoàn phải tung lực lượng dự bị (Tiểu đoàn 166 thuộc Trung đoàn 209) vào tham gia chiến đấu, đồng thời có một mũi của tiểu đoàn 128 đánh từ 101A sang phối hợp mới chiếm được cứ điểm cuối cùng này.

Khoang 23 giờ 30 phút, trận đánh kết thúc, trung tâm đề kháng Him Lam hoàn toàn bị tiêu diệt. Hơn 200 tên bị chết, 270 tên bị bắt sống, tiểu đoàn lê dương số 3 bị loại khỏi vòng chiến đấu.

Mất Him Lam, Bộ chỉ huy Pháp bàng hoàng và liên tục thúc giục Đờ Cát tung quân ra phản kích chiếm lại. Nhưng trong suốt ngày 14, Đờ Cát không có cơ hội làm điều đó vì phải lo chỉ huy cấp dưới củng cố lại trận địa và đối đối phó với các cuộc tập kích hỏa lực chính xác của pháo binh ta. Đặc biệt, khu vực sân bay Mường Thanh đã bị pháo binh ta khống chế chặt chẽ. Chiều ngày 14 tháng 3, địch cho tiểu đoàn dù ngụy số 5 (5e BPV) nhảy dù xuống tăng viện cho Điện Biên Phủ.

Đêm 14 tháng 3, ta mở cuộc tiến công vào trung tâm đề kháng đồi Độc Lập, một cụm cứ điểm có chiều dài khoảng 500m, rộng 200m cách trung tâm Mường Thanh 4km về phía bắc. Đây được coi là cụm cứ điêm phòng ngự kiên cố nhất của Điện Biên Phủ, trận địa phòng ngự được xây dựng vững chắc, có hệ thống công sự phụ khá mạnh, xung quanh có nhiều lớp hàng rào vật cản nhất là ở phía bắc và phía nam. Trung tâm do tiểu đoàn 5 thuộc trung đoàn An-giê-ri thứ 7 (15/7 RTA) và một đại đội ngụy Thái chiếm giữ.

Nhiệm vụ tiến công đồi Độc Lập được giao cho trung đoàn 165 Đại đoàn 312 và trung đoàn 88 Đại đoàn 308, được tăng cường hai đại đội sơn pháo 75mm cùng hai đại đội cổi 120mm vừa đánh Him Lam xong. Chỉ huy trận đánh là đồng chí Vương Thừa Vũ - Đại đoàn trưởng Đại đoàn 308.

Trung đoàn 165 đảm nhiệm hướng tiến công chủ yếu đột phá từ hướng đông nam vào, trung đoàn 88 đảm nhiệm hướng tiến công thứ yếu đột phá từ hướng đông bắc vào. Trận đánh dự định vào 16 giờ 45 phút ngày 14, nhưng do trời mưa, sơn pháo 75mm và cối 120mm từ Him Lam chưa sang kịp, đồng chỉ Chỉ huy trưởng trận đánh quyết định để lựu pháo 105mm bắn chuẩn bị vào 17 giờ theo kế hoạch, còn bộ binh chờ pháo ở Him Lam tới, chuẩn bị thật chu đáo mới nổ súng.

2 giờ sáng ngày 15, sơn pháo 75mm và cối 120mm có mặt đầy đủ và nhanh chóng bắt tay vào xây dựng trận địa bắn. Đúng 3 giờ 30 phút, đồng chỉ Chỉ huy trưởng hạ lệnh nổ súng tiến công đồi Độc Lập. Trên hướng chủ yếu, trung đoàn 165 đột phá thuận lợi. Một mũi thọc sâu đã tạo điều kiện cho trung đoàn nhanh chóng đánh sâu vào cứ điểm, diệt khu thông tin, trận địa cối, uy hiếp sở chỉ huy. Trên hướng thứ yếu, trung đoàn 88 lúc đầu mở cửa chưa đúng hướng, phải định hướng lại do đó vào chiến đấu bên trong chậm hơn. Cuộc chiến đấu bên trong khá quyết liệt, song do tinh thần chiến đấu dũng cảm và sức tiến công áp đảo, 6 giờ 30 phút ngày 15 tháng 3 ta hoàn toàn làm chủ trung tâm để kháng đồi Độc Lập, diệt 483 tên, bắt 200 tên trong đó có hai tên tiểu đoàn trưởng.

Trong lúc trận đánh đang diễn ra trên đồi Độc Lập, địch đã điều một tiểu đoàn bộ binh cùng năm xe tăng ra tăng viện. Lực lượng này bị pháo binh của ta bắn chặn, cháy một xe tăng, thương vong một số tên, chúng phải chạy về Bản Kéo.

Hai trung tâm đề kháng Him Lam và Độc Lập thất thủ, tinh thần binh lính địch ở trung tâm đề kháng Bàn Kéo suy sụp. Theo kế hoạch, trung đoàn 36 Đại đoàn 308 được giao nhiệm vụ triển khai tiến công tiêu diệt Bản Kéo. 15 giờ ngày 17 tháng 3, sau khi ta bắn 20 quả lựu pháo 105mm uy hiếp và tiến hành binh vận gọi hàng mặc dù bị bọn chỉ huy khống chế, binh lính tiểu đoàn ngụy Thái số 3 (3e BTA) đóng ở Bản Kéo đã kéo cờ trắng, chạy vào rừng đầu hàng quân ta. Trung đoàn 36 chưa cần nổ súng đã chiếm được cụm cứ điểm Bản Kéo, tiếp nhận 232 hàng binh.

Đến đây, ta kết thúc đợt một chiến dịch. Trong năm ngày với hai trận chiến đấu hiệp đồng binh chủng lớn ta đã đập tan hệ thống phòng ngự tiền tiêu của địch trên hướng bắc và đông bắc, mở thông cửa xuống vùng lòng chảo, tạo điều kiện thuận lợi để các lực lượng chiến dịch áp sát khu trung tâm. Đây là thắng lợi mở đầu rất quan trọng không chỉ về quân sự mà còn đánh mạnh vào tinh thần, tâm lý của địch, làm cho chúng vô cùng hoảng sợ, đối phó lúng túng.

**Đợt 2 (từ 30 tháng 3 đến 30 tháng 4 năm 1954): Đánh chiếm các ngọn đồi phía đông và sân bay Mường Thanh, siết chặt vòng vây, tạo thế trận cho tổng công kích.**
Sau khi ta chiếm được các cụm cứ điểm Him Lam, Độc Lập, Bản Kéo, cánh cửa phía bắc xuống lòng chảo đã mở thông. Nhưng phân khu trung tâm của địch vẫn còn bốn trung tâm đề kháng gồm trên 30 cứ điểm liên kết chặt chẽ với nhau nằm giữa cánh đồng bằng phẳng trên hai bờ sông Nậm Rốm. Địch ở đây tập trung khoảng một vạn quân có sở chỉ huy, các căn cứ hỏa lực, các đơn vị xe tăng và sân bay. Ngày 16 tháng 3, địch lại tăng viện cho Điện Biên Phủ tiểu đoàn 6 dù thuộc địa (6e BPC) cùng một khối lượng khá lớn vũ khí phương tiện chiến tranh và ra sức cùng cố trận địa phòng ngự ở phân khu trung tâm. Những vị trí có giá trị đặc biệt về chiến thuật ở phân khu trung tâm là các cứ điểm, các điểm cao phía đông (A1, C1, D1, và E). Đây là khu vực phòng ngự then chốt, hiểm yếu của địch, nếu chiếm được ta sẽ có lợi thế tràn xuống Mường Thanh tiến công vào trung tâm chỉ huy của tập đoàn cứ điểm.

Nhiệm vụ chủ yếu nhất của ta trong đợt 2 chiến dịch là đánh chiếm khu vực phòng ngự then chốt trên các điểm cao phía đông, mở cửa thọc sâu vào tập đoàn cứ điểm.

Để có thể tiếp cận mục tiêu, đánh theo phương châm “đánh chắc, tiến chắc từ sau Hội nghị cán bộ chiến dịch ngày 17 tháng 3, ta đã dồn sức xây dựng một hệ thống trận địa tiến công và bao vây quanh tập đoàn cứ điểm. Hệ thống này gồm các đường hào trục, đường hào nhánh để vận chuyển và cơ động lực lượng hệ thống trận địa tiến công và xuất phát xung phong của các trung đoàn cùng rất nhiều hầm trú ẩn, hầm chỉ huy.

Sau 10 ngày vừa lao động cật lực, vừa phải đối phó với bom đạn và đánh trả các đợt phản kích của địch, bộ đội ta đã đào được trên một trăm kilômét giao thông hào, hàng vạn công sự ụ súng, hình thành một hệ thống trận địa tiến công và bao vây liên hoàn từ đại đoàn xuống các đơn vị.

Ngày 27 tháng 3, Bộ chỉ huy chiến dịch tập trung cán bộ từ cấp trung đoàn trở lên để giao nhiệm vụ. Chủ trương chung của ta trong đợt 2 là: Tập trung tuyệt đối ưu thế binh hỏa lực tiêu diệt cùng một lúc các vị trí phía đông Điện Biên Phủ chiếm các điểm cao uy hiếp Mường Thanh, tạo điều kiện chuyển sang tổng công kích. Nhiệm vụ cụ thể của các đơn vị như sau:
* Đại đoàn 312, được phối thuộc hai đại đội sơn pháo 75mm, hai đại đội cối 120mm, một đại đội cối 82mm, có nhiệm vụ tiến công tiêu diệt các cứ điểm đồi E (102), D1 (200), D2 (201A) thuộc trung tâm đề kháng Đô-mi-nich, vị trí pháo binh địch ở 210 và quân cơ động thuộc tiểu đoàn dù ngụy số 5 hoặc bộ phận của tiểu đoàn dù ngụy số 6.
* Đại đoàn 316 (thiếu trung đoàn 176) được phối thuộc hai đại đội sơn pháo 75mm, hai đại đội súng cối 120mm, có nhiệm vụ tiến công các cứ điểm Al (310), C1 (302), C2 (304) thuộc trung tâm đề kháng E-li-an và phối hợp với Đại đoàn 308 tiêu diệt tiểu đoàn 6 dù thuộc địa.
* Đại đoàn 308, có nhiệm vụ tiêu diệt khu trung tâm phía tây gồm tiểu đoàn ngụy Thái số 2 (2e BAT), trận địa pháo binh ở phía đông trung tâm và phối hợp và Đại đoàn 316 tiêu diệt Tiểu đoàn 6 dù thuộc địa, dùng hỏa lực kiềm chế địch ở Mường Thanh và chặn viện từ Hồng Cúm lên.
* Trung đoàn 57 Đại đoàn 304, được phối thuộc tiểu đoàn 888 Đại đoàn 316, một đại đội lựu pháo 105mm, một số đơn vị hỏa lực khác có nhiệm vụ chặn viện từ Hồng Cúm lên và đánh quân nhảy dù xung quanh Hồng Cúm.
* Đại đoàn 351 sử dụng trung đoàn lựu pháo 105mm chi viện trực tiếp cho bộ binh tiến công các cứ điểm E1, D1, D2, C1, C2, A1, đồng thời kiềm chế pháo binh địch ở Mường Thanh, Hồng Cúm. Riêng trung đoàn pháo cao xạ 367 được tăng cường phải giáng cho địch những đòn bất ngờ, yểm hộ cho pháo binh, bộ binh chiến đấu cả ngày lẫn đêm.

Thời gian bắt đầu tiến công đợt 2 vào chiều ngày 30 tháng 3 năm 1954. Ngày 30, sau mấy ngày mưa, trời đã tạnh nhưng mây đen vẫn bao phủ bầu trời, máy bay địch ít hoạt động, bộ đội ta chiếm lĩnh trận địa tiến công từ sớm. 17 giờ 30 phút, pháo binh chiến dịch bắn chuẩn bị, cuộc tiến công lớn vào các cứ điểm phía đông bắt đầu.

Trên hướng đông bắc, Trung đoàn 141 sử dụng Tiểu đoàn 16 và 428 tiến công cứ điểm đồi E. Sau 1 giờ 30 phút chiến đấu. Trung đoàn đã tiêu diệt gọn tiểu đoàn An-giê-ri số 3, chiếm lĩnh đồi E. Cùng thời gian, Trung đoàn 209 cũng sử dụng hai Tiểu đoàn 166 và 154 tiêu diệt gọn một tiểu đoàn địch và chiếm lĩnh cứ điểm đồi DI. Như vậy, Đại đoàn 312 đã hoàn thành nhiệm vụ đánh chiếm đồi E, D1. Đại đoàn tiếp tục điều tiểu đoàn 130 tiến công sang D2, các đơn vị vừa chiếm được đồi E phát triển vào các ngọn đồi ở phía trong. Cuộc chiến đấu của đại đoàn kéo dài cho đến khi trời sáng.

Trên hướng đông, trung đoàn 98 Đại đoàn 316 tiến công cứ điểm C1, sau 45 phút, trung đoàn làm chủ cứ điểm, diệt và bắt sống 140 tên. Thừa thắng, trung đoàn điều tiểu đoàn 215 tiến công sang C2 nhưng không thành công. Cùng thời gian trên, Tiểu đoàn 54 trung đoàn 102 luồn vào giữa D3 và C1 để tiêu diệt Tiểu đoàn ngụy Thái số 2, nhưng do chuẩn bị không tốt, địch chống trả mạnh, bộ đội không mở được cửa, đội hình ùn tắc ở C1.

Trung đoàn 174 tiến công cứ điểm A1, một cứ điểm quan trọng nhất trong cụm điểm cao phía đông. Do đường dây điện thoại bị đứt, đại đoàn vào chiến đấu chậm hơn quy định 35 phút. Trung đoàn tổ chức đột phá hai mũi, 21 giờ 30 phút các mũi mở cửa xong, bộ binh xung phong đánh vào cứ điểm. Địch dựa vào hầm ngầm trên đỉnh đồi chống trà rất quyết liệt, cuộc chiến đấu của trung đoàn 174 hết sức ác liệt. Trung đoàn đã tung hết lực lượng dự bị, nhưng đến sáng 31 cũng chỉ chiếm được một phần cứ điểm A1.

Buổi chiều và đêm 30 tháng 3, ngoài lực lượng tiến công vào các ngọn đồi ở phía đông, Bộ chỉ huy chiến dịch còn sử dụng các Tiểu đoàn 11 Trung đoàn 141, Tiểu đoàn 115 Trung đoàn 165, Tiểu đoàn 54 làm nhiệm vụ thọc sâu, diệt trận địa pháo địch ở cứ điểm 210 và tiểu đoàn dù ngụy số 5 đóng ở vòng trong. Các Tiểu đoàn 115 và 54 đã vượt qua được khoảng trống tiếp giáp giữa các vị trí C1 và D2, E và D1 tiến vào bên trong nhưng không mở được cửa mở qua hệ thống vật cản bên trong nên không thực hiện được nhiệm vụ. Riêng mũi của tiểu đoàn 11 đánh vào được một số vị trí, gây cho địch nhiều thiệt hại. Đội dũng sĩ 243 phát triển ra tới bờ sông Nậm Rốm và gan góc trụ lại trong lòng địch suốt ngày hôm sau.

Ngày 31 tháng 3, địch tung lực lượng ra phản kích cố chiếm lại các vị trí đã mất. Ở khu vực đồi D1, đồi E, địch phản kích thất bại, buổi chiều chúng rút khỏi cả 210 và D2. Riêng ở cứ điểm A1, địch cho nhiều đại đội bộ binh có xe tăng, pháo binh không quân yểm hộ tìm mọi cách thu hẹp khu vực chiếm lĩnh của Trung đoàn 174. Về phía ta, Bộ chỉ huy chiến dịch hạ quyết tâm tăng cường trung đoàn 102 từ hướng tây chuyển sang hướng đông tiếp tục tiến công A1, đồng thời lệnh cho Đại đoàn 308 đẩy mạnh hoạt động ở phía tây và bắc Mường Thanh, buộc địch phải phân tán đối phó.

Đêm 31 tháng 3, trung đoàn 102 và một bộ phận của Trung đoàn 174 tiến công A1 lần thứ hai. Cuộc chiến đấu kéo dài đến sáng ngày 1 tháng 4, ta chiếm được 2 phần 3 vị trí. Ban ngày địch tổ chức phản kích chiếm lại phần lớn trận địa. Đêm 1 tháng 4, ta tổ chức tiến công lần ba cũng không thành công. Trận đánh ở khu vực này kéo dài đến ngày 4 tháng 4, ta chỉ chiếm được 1 phần 3 đồi A1, Bộ chỉ huy chiến dịch cho Trung đoàn 102 rút về củng cố và giao cho Trung đoàn 174 phòng ngự giữ phần đồi đã chiếm được.

Ở hướng tây bắc sân bay, đêm 1 tháng 4, Trung đoàn 36 tiến công tiêu diệt gọn cứ điểm 106, tiến vào uy hiếp sân bay. Đêm 2 tháng 4, trung đoàn lại bao vây uy hiếp cứ điểm 311. Khoảng 120 tên thuộc tiểu đoàn ngụy Thái số 3 ra hàng, ta làm chủ cứ điểm này. Cũng đêm 2 tháng 4, hai đội dũng sĩ của hai Đại đoàn 308 và 312 đột nhập vào sân bay, diệt một số địch, bắt sống 10 tù binh.

Đêm 3 tháng 4, ở phía bắc sân bay, Trung đoàn 165 tiến công cứ điểm 105. Cuộc chiến đấu kéo dài đến sáng 4 tháng 4, ta chiếm được 2 phần 3 cứ điểm, trời sáng địch tổ chức phản kích chiếm lại toàn bộ.

Ngày 4 tháng 4, Bộ chỉ huy chiến dịch quyết định tạm ngừng cuộc tiến công để củng cố lực lượng, giữ vùng trận địa và tiếp tục chuẩn bị cho đợt tiến công mới.

Sau năm ngày chiến đấu trong đợt 2 của chiến dịch, ta đã thu được những kết quả quan trọng. Ở phía đông, ta chiếm được bốn ngọn đồi hiểm yếu (E, DI, D2, C1), riêng điểm cao Al địch vẫn chiếm giữ. Ở phía tây, ta chiếm thêm được điểm cao 106 và 311. Phạm vi chiếm đóng của địch bị thu hẹp, lực lượng bị tổn thất lớn, ba tiểu đoàn thiện chiến của chúng bị tiêu diệt.

Ngày 8 tháng 4, địch tăng viện cho Điện Biên Phủ tiểu đoàn dù thứ tư. Ngày 9 tháng 4, chúng tổ chức phản kích hòng chiếm lại C1. Lực lượng phòng ngự của Trung đoàn 98 bẻ gẫy nhiều đợt xung phong của địch, nhưng do địch đông và có các cứ điểm lân cận hỗ trợ nên đến trưa ngày 10, chúng chiếm được một nửa đồi phía tây, ta chỉ giữ được nửa đồi phía đông.

Sau khi tạm ngừng đợt tiến công, Bộ chỉ huy chiến dịch tổ chức rút kinh nghiệm, đồng thời hạ quyết tâm tiếp tục thực hiện nhiệm vụ đề ra cho đợt 2, tiêu diệt thêm một bộ phận sinh lực, chiếm thêm một số vị trí có lợi, đưa trận địa tiến công và bao vây vào gần địch hơn nữa, thắt chặt thêm vòng vây, đánh chiếm sân bay, quyết tâm triệt hẳn tiếp tế và tăng viện của địch, uy hiếp chúng mạnh hơn nữa. Thực hiện chủ trương đó, ngày 10 tháng 4, Bộ chỉ huy giao nhiệm vụ cho các đơn vị như sau:
* Đại đoàn 308 bố trí ở phía tây, từ sông Nậm Rốm đến Bản Kéo, có nhiệm vụ làm trận địa tiến công các cứ điểm 206, 311A, 311B, 310, bố trí lực lượng chặn viện giữa các cứ điểm 105, 206, 208, phối hợp với Đại đoàn 312 đào giao thông hào cắt ngang sân bay ở đoạn nam cứ điểm 206.
* Đại đoàn 312 bố trí ở phía bắc, từ Bản Kéo đến đoạn đông sân bay Mường Thanh, có nhiệm vụ củng cố trận địa phòng ngự ở các cứ điểm 201, 202; xây dựng trận địa tiến công các cứ điểm 105, 203 và khu tiểu đoàn ngụy Thái số 2; phối hợp với Đại đoàn 308 đào giao thông hào cắt ngang sân bay.
* Đại đoàn 316 làm trận địa tiến công ở đông Mường Thanh, bên trái tiếp giáp với Đại đoàn 312, bên phải tiếp giáp với Đại đoàn 308, xây dựng trận địa tiến công các cứ điểm A1, C2; củng cố trận địa phòng ngự ở đồi C1, A1.
* Trung đoàn 57 Đại đoàn 304 tiếp tục hoạt động bao vây, chặn viện ở phân khu Hồng Cúm.
* Đại đoàn 351 xây dựng thêm trận địa pháo ở tây bắc Mường Thanh, đưa pháo sát vùng lòng chảo; tổ chức phòng không, hiệp đồng chặt chẽ các loại pháo chi viện cho bộ binh và kiềm chế pháo binh địch.

Từ cuối thượng tuần tháng 4 năm 1954, các đơn vị bắt tay vào xây dựng trận địa tiến công. Các khu vực đã chiếm được như đồi E, DI đã trở thành các cứ điểm phòng ngự vững chắc của ta. Ngày 16, chiến hào của Đại đoàn 312 và Đại đoàn 308 nối liền với nhau, cắt đôi sân bay Mường Thanh. Đêm 18 tháng 4, sau nhiều ngày vây lấn, trung đoàn 165 tiến công dứt điểm cứ điểm 105. Sáng 19, địch cho quân ra phản kích bị Đại đoàn 308 chặn đánh phải quay lại. Cứ điểm 105 bảo vệ phía bắc sân bay bị xóa sổ. Đêm 22, Trung đoàn 36 sau ba ngày vây lấn cũng đã tiến công chiếm gọn cứ điểm 206.

Ngày 24, địch tung tiểu đoàn dù lê dương số 2 cùng năm xe tăng, có pháo binh, không quân yểm hộ mở đợt phản kích quyết liệt hòng đánh bật ta ra khỏi 206 và khu vực sân bay. Được pháo binh chi viện đắc lực, bộ đội ta đã đánh bại nhiều đợt xung phong của địch, thực hiện trọn vẹn nhiệm vụ cắt đôi sân bay Mường Thanh, thu hẹp phạm vi chiếm đóng của địch.

Tại khu vực đồi A1, ngoài việc Trung đoàn 174 kiên cường trụ vững tại trận địa đã chiếm được, ta còn tổ chức đào một đường hầm xuyên sâu vào lòng đồi A1, dưới hầm ngầm của địch để đặt khối thuốc nổ lớn chuẩn bị tiến công A1.

Từ trung tuần tháng 4, kết hợp với vây hãm, đánh lấn, các đơn vị còn tích cực tham gia bắn tỉa, tổ chức các đôi đũng sĩ luồn sâu các tô đoạt dù... gây cho địch nhiều tổn thất về sinh lực, phương tiện, căng thẳng về tinh thần.

Cùng với hoạt động vây ép của bộ binh, pháo cao xạ và súng máy phòng không của các đại đoàn tiến sâu vào thung lũng, tạo một lưới lửa phòng không khống chế không cho địch dùng máy bay tiếp tế cho quân địch bị vây trong lòng chảo Điện Biên Phủ. Đến giữa tháng 4 ta đã hạ 50 máy bay địch, buộc chúng phải thả dù ở độ cao trên ba kilômét, do đó trên một phần ba số dù tiếp tế rơi vào trận địa của ta.

Đợt 2 chiến dịch đã kéo dài gần một tháng, các đơn vị của ta đều bị thương vong khá lớn, thời tiết lúc này bắt đầu vào mùa mưa, bộ đội ta sống dưới chiến hào gặp rất nhiều khó khăn, tư tưởng bộ đội đã xuất hiện các biểu hiện ngại hy sinh gian khổ, chấp hành mệnh lệnh không nghiêm. Trước tình hình này, Tổng quân ủy đã mở hội nghị các bí thư đại đoàn úy để kiểm điểm và mở đợt giáo dục chính trị tư tưởng, tập trung đẩy mạnh công tác bảo đảm hậu cần cải thiện một phần sinh hoạt cho bộ đội, nhằm củng cố thêm ý chí quyết chiến, quyết thắng cho cán bộ chiến sĩ các cấp.

**Đợt 3 (từ ngày 1 đến ngày 7 tháng 5 năm 1954): Đánh những điểm cao cuối cùng ở phía đông, thực hành tổng công kích, tiêu diệt toàn bộ quân địch ở Điện Biên Phủ.**
Cho đến cuối tháng 4 năm 1954, vòng vây của ta đã siết chặt, phạm vi chiếm đóng của địch mỗi bề còn lại chỉ từ 1,3 đến 1,7 kilômét, lực lượng không vượt quá 37 đại đội. Việc thả dù tiếp tế cho Điện Biên Phủ hết sức khó khăn, lương thực thực phẩm khan hiểm, binh lính địch thực sự lâm vào tình trạng bị “bóp nghẹt”.

Trong lúc bộ chỉ huy quân viễn chinh Pháp và quan thầy Mỹ của chúng đang lúng túng chưa tìm được lối thoát cho Điện Biên Phủ, thì ta quyết định tiến hành đợt tiến công thứ ba vào đầu tháng 5 năm 1954. Nhiệm vụ các đại đoàn được giao như sau:
* Đại đoàn 316 tiêu diệt C1 và giữ vững trận địa ở đó; đồng thời đánh lấn sang C2 để phối hợp với trận đánh ở A1. Nếu điều kiện thuận lợi thì phát triển tiêu diệt toàn bộ C2; tổ chức đánh chiếm những lô cốt quan trọng ở A1.
* Đại đoàn 312 tiêu diệt các cứ điểm 505 và 505A, dùng một bộ phận lực lượng bộ binh và hỏa lực chặn viện khi Đại đoàn 316 tiến công C1. Ngày 5 tháng 5, phải tiêu diệt cứ điểm 204.
* Đại đoàn 308 có nhiệm vụ diệt các cứ điểm 310, 311A, 311B.
* Trung đoàn 57 Đại đoàn 304 có nhiệm vụ kiềm chế pháo binh địch và đánh lấn vào phân khu Hồng Cúm, chuẩn bị một tiểu đoàn vận động tác chiến ở hướng Thượng Lào khi có lệnh.

Ngày 1 tháng 5 năm 1954, đợt tiến công thứ 3 bắt đầu. Ngay từ trưa, pháo các cỡ của ta bắt đầu bắn mãnh liệt khu vực trận địa địch. Trong đợt bắn phá này, hỏa tiễn 122 của ta lần đầu tiên xuất hiện làm cho binh lính địch càng thêm hoảng sợ. Cụm pháo địch ở Hồng Cúm bị tê liệt hoàn toàn, một kho đạn pháo với trên ba nghìn viên đạn bị nổ tung, một kho lương thực, thực phẩm bốc cháy. Sau đợt pháo kích kéo dài, bộ đội ta đồng loạt tổ chức tiến đánh nhiều vị trí.

Trên dãy đồi phía đông, trung đoàn 98 Đại đoàn 316 diệt gọn C1, thừa thắng, đẩy mạnh vây lấn và chuẩn bị tiêu diệt C2. Trên bờ phía đông sông Nậm Rốm, trung đoàn 209 Đại đoàn 312 tiến công các cứ điểm 505 và 505A. Đến 4 giờ sáng ngày 2 tháng 5, trung đoàn hoàn toàn làm chủ hai cứ điểm này. Ở phía tây, Trung đoàn 88 cũng diệt gọn cứ điểm 311A trong vòng 30 phút. Ở phân khu Hồng Cúm, trung đoàn 57 tăng cường vây ép, tấn công diệt nhiều sinh lực địch. Cũng ngày 2 tháng 5, Trung đoàn 36 tiến công tiêu diệt gọn tiếp cứ điểm 311B.

Thấy nguy cơ Điện Biên Phủ bị tiêu diệt, ngày 3 tháng 5, tướng Cônhi - Tư lệnh quân Pháp ở Bắc Bộ, cho phép Đờ Cát rút chạy về Thượng Lào.

Nhưng kế hoạch rút chạy chưa kịp triển khai thì ngày 6 tháng 5, quân ta lại tiếp tục tiến công.

Ở hưởng đông nam, Trung đoàn 174 sau thời gian đánh lấn để phối hợp, đúng 17 giờ ngày 6 tháng 5, cho nổ khối bộc phá gần 1.000kg đặt dưới đường hầm đào sâu vào cứ điểm địch, đồng thời bộ đội từ ba hướng đồng loạt xung phong. Trận chiến đấu diễn ra rất ác liệt. đến 4 giờ 30 phút ngày 7 tháng 5, ta làm chủ hoàn toàn A1.
Cùng thời gian này, Trung đoàn 98 tiến công C2, Trung đoàn 165 tiến công cứ điểm 506. Ở phía tây, Trung đoàn 102 tấn công cứ điểm 310.

Đến 9 giờ ngày 7 tháng 5, các đơn vị đã hoàn thành nhiệm vụ được giao và sẵn sàng chuyển sang tổng công kích.

Khoảng từ 10 giờ ngày 7 tháng 5, trong khi các đại đoàn đang xúc tiến việc chuẩn bị bảo đảm cho tổng công kích thì cơ quan quân báo phát hiện địch có dấu hiệu rối loạn và có khả năng đầu hàng. Hồi 15 giờ ngày 7 tháng 5, Bộ chỉ huy chiến dịch ra lệnh tổng công kích trước giờ quy định: “Phải đánh thẳng vào sở chỉ huy, phải đánh mạnh, bao vây chặt không cho Đờ Cát hoặc bất cứ tên địch nào chạy thoát".

Chấp hành mệnh lệnh, từ hướng đông Trung đoàn 209 tiến thẳng vào Mường Thanh. Tiếp sau là các Trung đoàn 98 và 174. Bên phía tây, Trung đoàn 36 tiến thẳng vào cứ điểm cuối cùng che chở cho sở chỉ huy của Đờ Cát. Trung đoàn 88 cũng mở đường qua sân bay tiến vào sào huyệt cuối cùng của địch. Bộ đội ta tiến tới đâu quân địch đầu hàng tới đó. 17 giờ 15, một cánh quân của Đại đoàn 312 tiến sát sở chỉ huy địch, tại cửa hầm của Đờ Cát xuất hiện cờ trắng xin hàng. Đại đội trường Tạ Quốc Luật cùng hai chiến sĩ Vinh và Nhỏ tiến vào hầm bắt sống tướng Đờ Cát cùng toàn bộ bộ tham mưu của tập đoàn cứ điểm Điện Biên Phủ. 17 giờ 30 phút ngày 7 tháng 5 năm 1954, Chiến dịch Điện Biên Phủ toàn thắng.

Trên hướng Hồng Cúm, lúc này địch vẫn chống cự. Đêm 7 tháng 5, lợi dụng đêm tối địch ở đây rút chạy về hướng Thượng Lào. Bộ chỉ huy chiến dịch đã lệnh cho Đại đoàn 304 phải tích cực truy lùng đồng thời lệnh cho Trung đoàn 102 đi gấp sang Tây Trang chặn đường rút của địch. Hồi 22 giờ ngày 7 tháng 5, Đại đoàn 304 đã bao vây và bắt gọn toàn bộ quân địch ở Hồng Cúm thoát ra.

Sau 55 ngày đêm chiến đấu liên tục, các lực lượng vũ trang nhân dân ta đã tiêu diệt toàn bộ tập đoàn cứ điểm Điện Biên Phủ. Tổng số quân địch bị diệt và bị bắt sống là 16.200 tên, gồm 17 tiểu đoàn bộ binh và lính dù, ba tiểu đoàn pháo binh, 10 đại đội ngụy vừa bổ sung và các đơn vị công binh, vận tải, xe tăng... Tổng số sĩ quan và hạ sĩ quan bị diệt và bị bắt là 1.706 tên, gồm một thiếu tướng, 16 đại tá và trung tá, 353 sĩ quan từ thiếu úy đến thiếu tá. Số máy bay bị bắn rơi và phá hủy là 62 chiếc (trong đó tại mặt trận là 57 chiếc). Ta đã thu toàn bộ vũ khí kho tàng của địch ở Điện Biên Phủ, trong đó có 28 khẩu pháo lớn, 64 xe, 5.915 súng các loại, 20.000 lít xăng dầu cùng rất nhiều đạn dược, quân trang, quân dụng khác.

Chiến dịch Điện Biên Phủ đã loại khỏi vòng chiến đấu một số lượng lớn sinh lực và phương tiện chiến tranh của địch, giải phóng vùng đất đai có ý nghĩa chiến lược. Chiến thắng Điện Biên Phủ giáng một đòn quyết định vào ý chí xâm lược của thực dân Pháp, xoay chuyển cục diện chiến tranh, tạo điều kiện thuận lợi cho đấu tranh ngoại giao của ta đi tới kết thúc thắng lợi. Chiến thắng Điện Biên Phủ đã trở thành niềm tự hào của dân tộc của nhân dân ta và phong trào giải phóng dân tộc của nhân dân thế giới lúc bấy giờ.

Chiến dịch Điện Biên Phủ là đòn quyết chiến chiến lược, là chiến dịch tiến công trận địa có quy mô lớn nhất của ta trong kháng chiến chống Pháp. Lần đầu tiên ta tập trung một lực lượng lớn chủ lực tiêu diệt chủ lực địch phòng ngự trong một tập đoàn cứ điểm mạnh nhất lúc bấy giờ.

Nghệ thuật chiến dịch trong Chiến dịch Điện Biên Phủ được biểu hiện cụ thể trong các nội dung sau:
* **Sớm hình thành thể bao vây, xây dựng trận địa tiến công và bao vây, ngày càng siết chặt từng cụm cử điểm và tập đoàn cứ điêm, chia cắt thể liên hoàn của chúng.** Quá trình chuẩn bị chiến dịch theo phương châm “đánh nhanh, giải quyết nhanh lúc đầu, là quá trình quân ta hình thành thể bao vây quân địch. Đại đoàn 308 ở phía bắc và tây bắc; Đại đoàn 312 ở phía đông bắc; hai trung đoàn của Đại đoàn 316 ở phía đông: Trung đoàn 57 ở phía nam. Đặc biệt là từ hạ tuần tháng 1, khi khi ta đổi sang phương châm “đánh chắc, tiến chắc", cho đến ngày quân ta giành toàn thắng, hệ thống chiến hào hàng trăm kilômét ngày càng ken dày và siết chặt từng phân khu, từng cụm cử điểm. Bằng hệ thống trận địa tiến công và bao vây, quân ta đã “trói chặt”, chia cắt thế liên hoàn của địch để lần lượt tiêu diệt từng bộ phận và đập tan mọi kế hoạch tháo chạy của chúng.
* **Tập trung ưu thế binh lực, hỏa lực, đánh chắc thẳng, tiêu diệt từng bộ phận sinh lực địch, từng bước uy hiếp tiến tới tiêu diệt khu vực trọng yếu nhất của địch giành thắng lợi quyết định.** Tập đoàn cứ điểm Điện Biên Phủ gồm 49 cứ điểm trải trên một diện tích khoảng 40km². Trên các điểm cao từ tây bắc sang đông bắc và đông hình thành những cụm cứ điểm ngoại vi bảo vệ cho phân khu trung tâm. Khu vực giao chiến rộng, so sánh trang bị kỹ thuật chênh lệch, kinh nghiệm đánh công kiên của ta còn hạn chế, không cho phép ta tổ chức nhiều hướng tiến công đồng thời vào phân khu trung tâm của địch. Ta đã chọn cách “đánh chắc, tiến chắc”, tập trung ưu thế binh hỏa lực'' đánh từng trận hay một số trận gối đầu liên tiếp, diệt từng cứ điểm, cụm cứ điểm ngoại vi, trước hết là trên các điểm cao khống chế phía bắc rồi phía đông, “bóc vỏ từ ngoài vào, mở đường tiến xuống cánh đồng Mường Thanh, tiếp cận và từng bước uy hiếp tiến tới tiêu diệt phân khu trung tâm, trọng điểm là sở chỉ huy tập đoàn cứ điểm.
* **Chọn cách đánh hiểm, phát huy uy lực mọi thứ vũ khí của ta, hạn chế chỗ mạnh, khoét sâu chỗ yếu của địch.** Sau thắng lợi bước đầu của ta ở đợt 2, địch vẫn còn trên một vạn quân chiếm giữ trên các điểm cao khống chế và hỏa lực phi pháo còn rất mạnh. Trước tình hình đó, ta chủ trương dùng lực lượng nhỏ, hoạt động rộng rãi dưới các hình thức đánh lấn, phá hủy từng ụ đề kháng, tiêu diệt thêm một số vị trí địch; bắn tỉa tiêu hao địch rộng rãi làm cho binh lính địch luôn ở trong trạng thái căng thẳng; đánh chiếm sân bay, thắt chặt vòng vây, thu hẹp không phận, khống chế máy bay, đoạt dù tiếp tế, hạn chế tiến tới triệt hẳn nguồn tiếp tế và tăng viện của địch.

Trên thực tế, từ trung tuần tháng 4, quân ta đã từng bước làm thay đổi cục diện chiến trường. Sân bay địch đã bị chiến hào ta cắt đôi, hai vị trí sát sân bay là 105 và 206 bị các đơn vị của ta vây lấn rồi tiêu diệt. Máy bay địch không thể lên xuống hoặc thả dù tiếp tế xuống hoặc thả dù tiếp tế xuống khu vực sân bay. Hai trận địa pháo địch ở 307A và 307B bị lựu pháo của ta loại khỏi vòng chiến đấu. Các tổ bắn tỉa được tổ chức rộng khắp và hoạt động thường xuyên đã gây nên nỗi kinh hoàng đối với binh lính địch. Pháo cao xạ của ta tiến sâu xuống cánh đồng Mường Thanh, khống chế không phận, trong khi hỏa lực pháo cối thu hẹp phạm vi thả dù, buộc máy bay địch phải thả dù ở độ cao lớn. Gần một nửa số dù của địch rơi sang phía trận địa ta hoặc rơi vào khoảng trống giữa ta và địch. Đến cuối tháng 4, quân số của địch ở Điện Biên Phủ tuy còn khoảng một vạn, nhưng chỉ có 42 phần trăm quân số đủ sức chiến đấu, tinh thần binh lính suy sụp, nguồn tiếp tế bị bóp nghẹt, vũ khí trang bị thiếu thốn nghiêm trọng.

Chọn cách đánh thích hợp, ta đã làm cho địch quân còn đông mà hóa ít, trang bị còn nhiều mà hóa yếu, tinh thần, vật chất và thế trận hoàn toàn rơi vào thế bất lợi. Chính bằng cách đánh hiểm và sáng tạo, đến cuối tháng 4, mặc dù quân ta chưa hoàn toàn làm chủ các dây điểm cao phía đông, nhưng đã uy hiếp mạnh phân khu trung tâm và chuẩn bị đầy đủ điều kiện chắc thẳng để chuyển sang đợt tiến công cuối cùng.

Chiến dịch Điện Biên Phủ thực sự là một điển hình xuất sắc, là đỉnh cao của nghệ thuật quân sự, nghệ thuật chiến dịch Việt Nam trong cuộc kháng chiến chống Pháp.

Chiến thắng Điện Biên Phủ đánh dấu sự thất bại không thể cứu vãn nổi của đội quân viễn chính Pháp, kết thúc vĩnh viễn chế độ thống trị của thực dân Pháp đã kéo dài gần một thế kỷ trên đất nước ta.

Cuộc tiến công chiến lược Đông Xuân 1953 - 1954 mà đỉnh cao là chiến dịch Điện Biên Phủ là chiến thắng to lớn nhất của quân và dân ta trong cuộc kháng chiến chống thực dân Pháp xâm lược và can thiệp Mỹ (1945-1954). Chiến thắng Điện Biên Phủ đã như một Bạch Đằng, một Chi Lăng, một Đống Đa... của dân tộc ta trong thế kỷ XX và đi vào lịch sử thế giới như một chiến công chói lọi đột phá thành trì của hệ thống nô dịch thuộc địa của chủ nghĩa đế quốc. Đại tướng Võ Nguyên Giáp cũng đã viết: “Điện Biên Phủ là điểm hẹn mà lịch sử dành cho những cuộc chiến tranh xâm lược trong thời đại ngày nay.

## C. ĐIỆN BIÊN PHỦ - MỐC VÀNG THỜI ĐẠI
Chiến thắng Đông Xuân 1953-1954 mà đỉnh cao là chiến dịch Điện Biên Phủ lịch sử đã góp phần quyết định kết thúc thắng lợi chín năm kháng chiến chống thực dân Pháp xâm lược của quân và dân ta, mở ra một kỷ nguyên mới trong lịch sử dân tộc. Chiến thắng vĩ đại Điện Biên Phủ đã làm cho ba tiếng Điện Biên Phủ trở thành biểu tượng của sức mạnh Việt Nam. Chiến thắng Điện Biên Phủ còn có ý nghĩa quốc tế lớn lao là đã góp phần làm thay đổi cục diện thế giới; đã chứng minh một chân lý của thời đại: Một dân tộc bị áp bức khi đã đoàn kết vùng dậy đấu tranh theo một đường lối đúng đắn, kiên quyết chiến đấu vì độc lập, tự do và chủ nghĩa xã hội thì có khả năng đánh thắng quân đội xâm lược của chủ nghĩa đế quốc.

Trải qua 55 ngày đêm chiến đấu liên tục, lực lượng vũ trang nhân ta đã tiêu diệt hoàn toàn tập đoàn cứ điểm Điện Biên Phủ. Đây là một tập đoàn cứ điểm mạnh nhất trong hình thức tổ chức phòng ngự cao nhất của quân đội viễn chinh Pháp ở Đông Dương lúc đó. Tại đây, quân Pháp tập trung tới hơn một vạn sáu nghìn quân, chủ yếu là lính dù và Âu Phi tinh nhuệ do thiếu tướng Đờ Cát-xtơ-ri chỉ huy. Tập đoàn cứ điểm Điện Biên Phủ có 49 cứ điểm, mỗi cứ điểm đều có công sự, hàng rào vật cản, hỏa lực độc lập chiến đấu đồng thời những cứ điểm gần nhau lại được tổ chức thành cụm cứ điểm. Tập đoàn gồm 8 trung tâm đề kháng và được chia thành 3 phân khu. Phân khu Trung tâm là quan trong nhất, nằm ngay giữa Mường Thanh, có 5 tiểu đoàn chiếm đóng, 3 tiểu đoàn cơ động. Phân khu Bắc gồm đồi Độc Lập và Bản Kéo cùng với cụm cứ điểm Him Lam (thuộc phân khu Trung tâm). Phân khu Nam là cụm cứ điểm có trận địa pháo và sân bay Hồng Cúm. Với 2 trận địa pháo bố trí ở Mường Thanh, Hồng Cúm và 2 sân bay nối liền với Hà Nội, Hải Phòng bằng một cầu hàng không, khi cần thiết được 80% lực lượng không quân ở Đông Dương chỉ viện, tập đoàn cứ điểm Điện Biên Phủ là “một tập đoàn cứ điểm đáng sợ”, “một pháo đài bất khả xâm phạm”, “một Véc-đoong ở Đông Nam Á".

Về phía ta, lực lượng tham gia chiến dịch lúc đầu gồm các đại đoàn bộ binh: 308, 312, 316 và Trung đoàn 57 (Đại đoàn 304). Hóa lực có Đại đoàn công pháo 351 gồm Trung đoàn 45 lựu pháo 105mm, Trung đoàn 675 sơn pháo và cối, Trung đoàn 151 công bình, Trung đoàn 367 cao xạ, các đơn vị thông tin, vận tải (16 đại đội), quân y... Tổng quân số hỏa tuyển khoảng bốn vạn, nếu tính cả tuyến hai là năm vạn rưỡi, và 260 nghìn dân công hỏa tuyến.

Thời gian đầu khi địch chưa tăng cường, củng cố lực lượng và hệ thống quân sự, phương châm tác chiến của ta là “Đánh nhanh, giải quyết nhanh". Ngày 26-1-1954, Đại tướng Võ Nguyên Giáp đề nghị và được Bộ Chính trị đồng ý, ta chuyển phương châm tác chiến sang “Đảnh chắc, tiền chắc", dùng cách đánh vây hãm tiến công, đột phá lần lượt để tiêu diệt tập đoàn cứ điểm. Đây là một chủ trương chính xác, kịp thời và kiên quyết, góp phần quyết định thắng lợi của Chiến dịch Điện Biên Phủ.

Việc chuyên phương châm tác chiến từ “Đánh nhanh, giải quyết nhanh" sang "Đánh chắc chiến chắc là “một quyết định khó khăn nhất trong cuộc đời chỉ huy của mình như lời của Đại tướng Võ Nguyên Giáp. Và thực tế lịch sử đã sớm khẳng định không thay đổi phương châm tác chiến thì chiến dịch không thể kết thúc thắng lợi.

Để đảm bảo cho pháo lớn lần đầu xuất trận giữ được bí mật, an toàn và phát huy hiệu lực cao nhất, bất ngờ nhất, Tham mưu trưởng chiến dịch Hoàng Văn Thái đích thân dẫn cán bộ men theo những sườn núi cao chưa có vết chân người nhưng đầy vắt, ve và ruồi vàng để tìm trận địa cho pháo. Trong những ngày kéo pháo, nhiều cán bộ chính trị chủ chốt của chiến dịch như Lê Quang Đạo, Phạm Kiệt, Phạm Ngọc Mậu... thường xuyên có mặt trên đường kéo pháo, cùng cán bộ đơn vị động viên, tổ chức bộ đội hoàn thành một kỳ công chưa từng thấy. Chưa có một chiến dịch nào trong suốt cuộc kháng chiến chống thực dân Pháp, cả Bộ trưởng Y tế (bác sĩ Vũ Đình Tụng) và Thứ trưởng (bác sĩ Tôn Thất Tùng), những thầy thuốc đánh phá ác liệt tất cả các tuyến đường giao thông dẫn đến Điện Biên Phủ. Tướng Na-va đã giao nhiệm vụ cho lực lượng không quân của Pháp phải dành ưu tiên với mọi phương tiện tối đa cho việc hỗ trợ các lực lượng tác chiến của Pháp ở Tây Bắc. Trên các đoạn đường trọng điểm như Tuần Giáo - Điện Biên Phủ, Lai Châu - Sơn La, Cò Nòi - Yên Bái, không quân địch đánh phá 24/24 giờ. Có trận không quân Pháp đã “dùng tới 39 máy bay B.26, 5 máy bay Pri-va-tơ và 21 máy bay khu trục thuộc hải quân, ném hàng trăm tấn bom trên những đoạn đường nghi ngờ. Lần đầu tiên trong các trận oanh tạc, Mỹ đã cho Pháp sử dụng loại máy bay vận tải cỡ lớn Pác-két C.119 (78 chỗ ngồi) để thả bom na-pan...".

Mặc dù gặp muôn vàn khó khăn, ác liệt do địch đảnh phá và thời tiết khắc nghiệt, nhưng từng đoàn xe ô tô, xe đạp thồ, ngựa thồ, từng đoàn thuyền lớn nhỏ của ta vẫn dũng cảm vượt bom đạn tiến lên phía trước. Hàng chục vạn anh chị em dân công, thanh niên xung phong, không quản hy sinh gian khổ vẫn ngày đêm băng rừng, trèo đèo lội suối, lấy sức mình vận chuyển lương thực, đạn dược ra mặt trận, tiếp tế cho bộ đội ta giết giặc.

Ác liệt gay go nhất vẫn là cuộc chiến đấu đối mặt với quân Pháp trong từng trận đánh. Chân lý đã được khẳng định: Thắng lợi trên chiến trường, suy cho cùng, vẫn là do những chiến binh cầm súng quyết định. Trước ngày mở màn chiến dịch, đã xuất hiện gương hy sinh chiến đấu của các anh: Hoàng Văn Nô, Tô Vĩnh Diện, Nguyễn Văn Chức... Ngay từ đợt đầu, trận đầu là gương của các anh hùng: Phan Đình Giót, Trần Can... Sang đợt 2, tiêu biểu cho tinh thần chiến đấu dũng cảm của hàng vạn chiến sĩ, là Đại đội 243 luồn sâu trong lòng địch trên các điểm cao phía đông, là các đơn vị đánh phản kích... đặc biệt là tinh thần dũng cảm hy sinh của cán bộ chiến sĩ các trung đoàn 174 và 102, giành giật với địch từng tấc đất trên đồi A1 suốt hàng tháng trời. Tại đây, trong giờ phút gay go nhất, các cán bộ trung đoàn đã thể hiện rõ bản lĩnh của người chỉ huy dũng cảm, mưu trí, dày dạn; chiến sĩ thông tin Chu Văn Mùi một mình trong vòng vây địch, vừa truyền đạt mệnh lệnh vừa chiến đấu bảo vệ thương binh...

Trước tình hình cấp dưới gặp khó khăn trong nhiệm vụ cắt sân bay địch, Đại đoàn trường Đại đoàn 308 Vương Thừa Vũ ra tận trận địa, bổ khuyết từng thiếu sót cụ thể trong việc đào trận địa vây lấn, kết quả là cuối tháng 4-1954, sân bay Mường Thanh bị tê liệt hoàn toàn. Trên hướng đông, Đại đoàn trưởng Đại đoàn 316 Lê Quảng Ba ra tận Đồi Cháy nghiên cứu vị trí A1, đề ra biện pháp tiêu diệt súng trong hầm ngầm của địch. Sau đó, ngay trước mũi súng và trong tầm lựu đạn của địch, phân đội công binh 83 đã khắc phục những khó khăn tưởng như không vượt nổi, đã bí mật kiên trì khoét từng nhúm đất rắn như đá non, đào được một đường hầm xuyên vào lòng cứ điểm A1, góp phần quyết định số phận “điểm cao cuối cùng của địch. Đại đoàn trưởng Đại đoàn 312 Lê Trọng Tấn chỉ huy các đơn vị thuộc quyền tiêu diệt các cứ điểm 505A, 505B, 506, 507, đánh chiếm Sở chỉ huy của tướng Đờ Cát ở trung tâm Mường Thanh...

Chiều 13-3-1954 chiến dịch Điện Biên Phủ mở màn, trải qua ba đợt. Đợt 1 (từ ngày 13 đến 17-3), ta đập tan thế phòng ngự vòng ngoài của địch ở phía bắc và đông bắc, mở đầu bằng trận Him Lam, tiếp đó tiêu diệt cụm cứ điểm đồi Độc Lập, bao vây, bức hàng cụm cứ điểm Bản Kéo, đánh bại nhiều đợt phản kích của địch. Đợt 2 (từ ngày 30-3 đến 30-4), sau hơn 10 ngày xây dựng trận địa tiến công và bao vây với hàng trăm kilômét hào giao thông, hàng ngàn công sự và ụ súng các loại, ta tiến công diệt các cứ điểm E, D1, D2, C1 trên dãy đồi phía đông và 106, 311 trên hướng tây bắc sân bay Mường Thanh, nhưng đánh cứ điểm Al và các cứ điểm C2, 105 không thành công, bị địch phản kích chiếm lại nửa đồi C1. Từ ngày 16-4 ta phát triển trận địa bao vây, tiến công, đánh lấn diệt các cứ điểm 105, 206, đào hào cắt đôi sân bay Mường Thanh, đánh lui nhiều đợt phản kích của địch nhằm giành lại sân bay, kết hợp bắn tỉa và đưa pháo phòng không xuống cánh đồng Mường Thanh khống chế rồi triệt hẳn tiếp tế đường không của địch. Đợt 3 (từ ngày 1 đến 7-5), ta lần lượt đánh chiếm các điểm cao còn lại ở phía đông (C1, C2 và A1), diệt một số cứ điểm ở phía tây, tăng cường vây ép phân khu Hồng Cúm, bao vây uy hiếp sở chỉ huy trung tâm, dập tắt hy vọng rút chạy của địch. 15 giờ ngày 7-5-1954, quân ta tiến hành tổng công kích vào trung tâm Mường Thanh, bắt tướng Đờ Cát-xtơ-ri và toàn bộ ban tham mưu của tập đoàn cứ điểm, buộc số địch còn lại ở phân khu trung tâm phải đầu hàng, ta truy kích và bắt gọn bộ phận địch ở Hồng Cúm định rút chạy. Lá cờ Quyết chiến quyết thắng của quân đội ta đã tung bay trên nóc hầm sở chỉ huy của tưởng Đờ Cát-xtơ-ri. Chiến dịch Điện Biên Phủ toàn thắng.

Chiến dịch Điện Biên Phủ là đòn tiến công tiêu diệt lớn nhất, điển hình nhất của quân và dân Việt Nam trong kháng chiến chống Pháp, cùng với thắng lợi trên các chiến trường khác trong Đông Xuân 1953-1954 giáng đòn quyết định vào ý chí xâm lược của thực dân Pháp, góp phần đưa hội nghị Giơ-ne-vơ về Đông Dương đến thành công (8-5 đến 21-7-1954); là sự phát triển đến đỉnh cao của nghệ thuật quân sự, nghệ thuật chiến dịch Việt Nam trong kháng chiến chống Pháp. Chủ tịch Hồ Chí Minh đã nhận xét: “Điện Biên Phủ như là một cải mốc chói lọi bằng vàng của lịch sử. Nó ghi rõ nơi chủ nghĩa thực dân lăn xuống dốc và tan rã, đồng thời phong trào giải phóng dân tộc khắp thế giới đang lên cao tới thắng lợi hoàn toàn.” (Báo Nhân Dân, số 3690, ngày 7-5-1964).', 'TEXT', '2026-06-05 05:38:51.852384', '2026-06-05 05:38:51.852364', null, 'DRAFT'), ('658423ac-0432-4090-ab2a-4e8187624156', '687b57fe-865c-496a-83b3-f83690885dd1', 'a9d5bce8-bee8-4044-b361-5f7517dfacc3', 'CONTEXT', 'Chi tiết trận Rạch Gầm - Xoài Mút', null, 'Trận Rạch Gầm - Xoài Mút, trận phục kích đường sông nổi tiếng của quân Tây Sơn vào đêm 18 rạng ngày 19 tháng 1 năm 1785 (tức đêm mùng 8 rạng ngày 9 tháng Chạp năm Giáp Thìn) trên khúc sông Tiền từ Rạch Gầm đến Xoài Mút, do Nguyễn Huệ chỉ huy, đập tan 5 vạn quân Xiêm và hàng nghìn quân bản bộ của Nguyễn Ánh trong khởi nghĩa Tây Sơn (1771-1789), chôn vùi mộng bành trướng của vương quốc Xiêm La dưới thời Cha kri cầm quyền.

Từ một thủ lĩnh chiến đấu dưới cờ của Nguyễn Nhạc, Nguyễn Huệ đã trở thành lãnh tụ kiệt xuất của phong trào Tây Sơn, chăm lo xây dựng quân đội Tây Sơn thành quân đội tinh nhuệ, thiện chiến.

Qua 21 năm chiến đấu, Nguyễn Huệ đã lập nên những kỳ tích oanh liệt: Chiến thắng Phú Yên (1775), ba lần đánh tan quân Nguyễn ở Gia Định (1777, 1782 và 1783), thắng quân Xiêm ở trận Rạch Gầm - Xoài Mút (19-1-1785); đánh đổ các tập đoàn phong kiến: chúa Nguyễn ở Đàng Trong, chúa Trịnh ở Đàng Ngoài, chấm dứt cảnh đất nước chia cắt trên 200 năm; quét sạch hơn 29 vạn quân xâm lược Mãn Thanh (1789).

Từ năm 1777 đến 1783, Nguyễn Huệ đã ba lần đánh vào Gia Định và toàn thắng.

Lần thứ nhất vào năm Đinh Dậu (1777), quân Nguyễn Huệ thắng trận liên tiếp giết được chúa Nguyễn là Phúc Thuần (Duệ Tông), chỉ có một mình Nguyễn Ánh chạy thoát ra sông Khoa (Long Xuyên).

Lần thứ hai, Nguyễn Huệ đánh vào Gia Định là tháng 3 năm Nhâm Dần (1782). Quân của Nguyễn Huệ qua đường biển tiến vào Cần Giờ, quân Chúa Nguyễn thua to. Nguyễn Ánh chạy đến Lữ Phu (Giồng Lữ) còn thuộc hạ là Đình Tường thu gom đám tàn quân khoảng 30 người cố gắng phản công đánh bại Đô đốc Tây Sơn Nguyễn Học rồi thừa thắng tiến quân đóng ở Tứ Kỳ Giang (Gia Định). Nguyễn Huệ liền lập tức mang quân đến bày trận Bối Thủy (quay lưng xuống nước kiểu Hàn Tín) để đánh, Nguyễn Ánh thua thảm hại, chạy về Hà Tiên rồi lại trốn ra đảo Phú Quốc, sai Nguyễn Hữu Thụy và Trần Xuân Trạch cùng Cai cơ Cao Phúc Trí sang Xiêm cầu viện.

Lần thứ ba là tháng 2, năm Quý Mão (1783), Nguyễn Huệ cùng Nguyễn Lữ vào đánh Gia Định từ cửa biển Cần Giờ. Quân Nguyễn đại bại, Nguyễn Ánh phải chạy về Ba Giòng (Gia Định) quân không còn tới 100 người. Nguyễn Ánh và khoảng 5 - 6 bầy tôi trung thành chạy ra đảo Côn Lôn (Cổ Long). Nguyễn Huệ lại cho quân vây đảo Côn Lôn, Nguyễn Ánh rơi vào đường cùng may mà nhờ có sóng lớn nên trốn thoát. Quân Tây Sơn của Phò mã Trương Văn Đa (con rể Nguyễn Nhạc) bị đắm thuyền, binh sĩ chết nhiều, Nguyễn Ánh may mắn thoát chết chạy về đảo Cổ Cốt. Sau khi thấy Tây Sơn rút quân, Nguyễn Ánh lại chạy về Phú Quốc, nhưng lúc này lương hết, còn cột buồm thì gãy may nhờ có thuyền gạo của một người ở Hà Tiên giúp mới qua cơn bĩ cực. Nguyễn Ánh để vợ con ở lại đảo, đem thuyền về cửa biển Ma-ni liền bị do thám của Tây Sơn phát hiện, Nguyễn Ánh phải chạy ra biển lênh đênh suốt 7 ngày đêm hết cả lương thực và nước ngọt. Cuối cùng, “số phận” chưa tận nên gặp được dòng nước ngọt mới thoát chết khát lại trở về Phú Quốc. Nguyễn Huệ và Nguyễn Lữ rút quân về Quy Nhơn.

Bị đánh liên tiếp, trong cơn cùng quẫn, Nguyễn Ánh liền nhờ giáo sĩ Bá Đa Lộc cùng Phạm Văn Nhơn đem Thế tử Cảnh lúc đó mới 4 tuổi sang cầu viện nước Pháp. Mặt khác, Nguyễn Ánh lại sai người đi cầu cứu vua Xiêm La là Cha-kri (Chất Trì).

Tháng 12 năm 1783, tướng Tây Sơn là Trương Văn Đa dẫn quân tấn công Chân Lạp, đánh Chiêu Thủy Biên vốn được Xiêm công nhận là Phụ chính. Biên phải trốn qua Xiêm cầu viện. Trương Văn Đa biết tin liền báo rằng, quân Xiêm sẽ theo đường Lào đánh Quy Nhơn nên quyết định khai chiến. Hai bên đánh nhau vài lần. Ngày 6 tháng Giêng năm 1784, tướng Trương Văn Đa rút quân khỏi Nam Vang.

Thời gian này, nước Xiêm dưới triều vua Cha kri đang thi hành chính sách bành trướng ra các nước trong khu vực, có tham vọng chiếm Chân Lạp và Gia Định để mở rộng bờ cõi. Vua Xiêm thấy Nguyễn Ánh cầu viện thì cả mừng chớp ngay cơ hội, liền cho hai cháu là Chiêu Tăng, Chiêu Sương mang 5 vạn quân cả thủy và bộ, 300 chiến thuyền tiến công nước ta vào ngày 25 tháng 7 năm 1784. Nguyễn Ánh cũng kêu gọi các cựu thần của nhà Nguyễn tập hợp binh lực. Lê Văn Duyệt, Nguyễn Văn Khiêm và dư đảng Đông Sơn của Nguyễn Văn Thành cũng lần lượt xin theo Nguyễn Vương.

Quân Xiêm đi đến đâu cướp của, giết người, hãm hiếp phụ nữ rồi thi nhau chở thóc gạo về nước khiến cho dân chúng lầm than, lòng người oán giận. Hành động bạo ngược của quân giặc khơi sâu lòng căm thù của toàn dân miền Tây và cả miền Đông Gia Định, căm thù cả Xiêm lẫn Nguyễn kẻ rước giặc về phá quê hương, và hết lòng ủng hộ tướng sĩ Tây Sơn.

Khoảng tháng 12 năm 1784, Bá Đa Lộc gặp Nguyễn Ánh ở Thổ Châu đã than rằng: “Người Xiêm lừa gạt ông, lấy cơ lập lại quyền bính cho ông nhưng thực chất là lấy danh ông để cướp bóc và bắt ông thôi". Tuy nhiên, sau 5 tháng (cuối năm Giáp Tuất 1784), sau khi đem quân vào nước ta, quân Xiêm chỉ chiếm được nửa phần đất phía tây Gia Định. Thành Mỹ Tho và nửa phần đất phía đông Gia Định, quân Tây Sơn vẫn giữ vững.

Cuối năm 1784, Tây Sơn Vương Nguyễn Nhạc cử Nguyễn Huệ đem thủy quân vào Nam tổ chức phản công, thực hiện quyết chiến chiến lược nhằm nhanh chóng quét sạch quân Xiêm - Nguyễn ra khỏi đất Gia Định.

Nguyễn Huệ dùng thuyền chiến vượt biển vào đến Gia Định khoảng đầu tháng 1 năm 1785, đóng quân và đặt sở chỉ huy tại Mỹ Tho. Tổng số quân Tây Sơn ở Gia Định - kể cả quân đồn trú của Trương Văn Đa và đoàn binh thuyền mới được tăng cường của Nguyễn Huệ - lên đến khoảng 2 vạn. Về số lượng, quân Tây Sơn chưa bằng một nửa quân Xiêm, chưa kể quân bản bộ của Nguyễn Ánh. Nhưng về trang bị vũ khí của quân đội Tây Sơn, ngoài bộ binh còn có tượng binh, kỵ binh và một đội thủy binh mạnh với nhiều loại thuyền chiến lớn nhỏ khác nhau. Đặc biệt là có nhiều đại bác các cỡ. Đó là những đại bác của quân Nguyễn bị quân Tây Sơn chiếm được trong các trận đánh, bao gồm đại bác do quân Nguyễn chế tạo và do chính quyền họ Nguyễn mua của các công ty tư bản phương Tây. Chỉ riêng trận đánh ra Quảng Nam giữa năm 1774, quân Tây Sơn đã chiếm được 45 voi chiến, 82 khẩu đại bác Hà Lan, Anh và 6 thuyền chở đầy đạn dược. Trên thuyền chiến, quân Tây Sơn thường đặt nhiều đại bác. Số đại bác này đã cho thấy quân Tây Sơn có lực lượng pháo binh khá mạnh.

Trước khi Nguyễn Huệ đem quân vào Gia Định (lần thứ tư), quân Xiêm - Nguyễn đã kiểm soát được vùng Hậu Giang và tiến tới vùng Tiền Giang. Chúng đã chiếm được Sa Đéc, Long Hồ (Vĩnh Long), Mân Thít, Ba Lai, từ hữu ngạn Tiền Giang cho đến sông Ba Lai. Cuối năm 1784, chúng chiếm được Trà Tân ở phía bắc Tiền Giang và sông Mỹ Tho (một chi lưu của sông Tiền Giang). Sau khi chia quân đóng giữ một số vị trí trọng yếu trong vùng đã chiếm được, Chiêu Tăng, Chiêu Sương cùng với Nguyễn Ánh đang tập trung quân về Trà Tân (Mỹ Tho). Chúng dự tính sẽ từ Trà Tân tiến lên Mỹ Tho, Gia Định, đánh tan quân Tây Sơn, hoàn thành việc xâm chiếm toàn bộ đất Gia Định.

Để chuẩn bị cho cuộc tiến công đầy tham vọng đó, Nguyễn Ánh đã phái cai đội Nguyễn Văn Thành đi Bát Chiên và Quang Hóa thu thập tàn quân Đông Sơn là đội quân do Đỗ Thanh Nhân lập ra trước đây để chống lại quân Tây Sơn. Như vậy là quân Nguyễn Ánh đã lén lút hoạt động ở vùng sông Vàm Cỏ Đông, Vàm Cỏ Tây, khoảng giữa Mỹ Tho và Gia Định nhằm chia cắt và uy hiếp quân Tây Sơn từ mặt sau để phối hợp với cuộc tiến công từ Trà Tân lên.

Giữa lúc quân địch đang chuẩn bị cho cuộc tiến công đánh chiếm Mỹ Tho, Gia Định thì bất ngờ thủy quân Tây Sơn do Nguyễn Huệ chỉ huy kéo vào đóng ở Mỹ Tho. Quân địch phải tạm thời hoãn cuộc tiến công để lo đối phó với Nguyễn Huệ, đề phòng quân Tây Sơn từ Mỹ Tho đánh lên.

Tại Trà Tân và vùng nam bờ sông Mỹ Tho, Tiền Giang, quân địch đã tập trung một khối lượng khá lớn gồm đại bộ phận quân Xiêm và quân bản bộ của Nguyễn Ánh. Chiêu Tăng, Chiêu Sương và Nguyễn Ánh đặt sở chỉ huy và đóng đại quân tại Trà Tân. Trà Tân ở phía bắc sông Mỹ Tho, khoảng giữa Cái Bè và Bình Chánh đông. Địa hình và vị trí vùng này khá lợi hại. Dòng sông bị chia cắt bởi những cù lao lớn như cù lao Tân Phong, cù lao Trà Luật (hay cù lao Năm Thôn) và nhiều cồn cát, bãi sa bồi. Các nhánh sông chi chít nhưng hẹp. Địa thế đó rất thuận lợi cho việc bố trí phòng thủ, phối hợp chặt মিলিটারি giữa bộ binh và thủy binh. Vùng Trà Tân ở vào đầu sông Mỹ Tho tiếp với Tiền Giang và gần chỗ phân lưu của các sông Cổ Chiên, Hàm Luông, Ba Lai đổ ra biển. Khi tiến công, quân địch có thể từ Trà Tân theo dòng sông Mỹ Tho tiến đánh Mỹ Tho. Ở phía nam Tiền Giang và sông Mỹ Tho, quân địch phân chia một bộ phận đóng giữ những vị trí quan trọng như Sa Đéc, Long Hồ (Vĩnh Long), vừa để bảo vệ sở chỉ huy, ngăn chặn quân Tây Sơn có thể từ biển theo các cửa sông Ba Lai, Hàm Luông, Cổ Chiên đánh lên, vừa sẵn sàng tiếp ứng cho đại quân ở Trà Tân.

Tiến công vào Trà Tân, một căn cứ tập trung đông quân địch và phòng bị chặt chẽ như vậy, quân Tây Sơn sẽ gặp nhiều khó khăn, bất lợi, nhất là khi quân ta ít hơn hẳn quân địch về số lượng. Hơn nữa trong tình hình cả nước lúc đó, tiền đồ phát triển của phong trào Tây Sơn đòi hỏi Nguyễn Huệ phải đánh nhanh, giải quyết nhanh. Kẻ thù nguy hiểm của Tây Sơn không phải chỉ có quân xâm lược Xiêm và bọn phong kiến phản động Nguyễn Ánh ở Gia Định mà còn có quân Trịnh ở Thuận Hóa. Tiến công vào căn cứ Trà Tân, cuộc chiến đấu chắc chắn sẽ ác liệt và kéo dài. Như vậy, quân chủ lực tinh nhuệ của Tây Sơn bị giam chân ở mặt Nam, do đó ở mặt Bắc, quân Trịnh có thể lợi dụng thời cơ đánh vào Quy Nhơn. Quân Tây Sơn sẽ rơi vào tình thế nguy hiểm, phải đồng thời đối phó với hai kẻ thù ở hai phía.

Đây là lý do quân sự và chính trị giải thích vì sao Nguyễn Huệ không mở cuộc tiến công vào Trà Tân. Nguyễn Huệ chủ trương nhử địch ra khỏi căn cứ, kéo chúng đến một địa hình có lợi cho ta và tiêu diệt gọn bằng một trận quyết chiến theo lối đánh vận động trên sông.

Những ngày đầu, Nguyễn Huệ sử dụng một binh lực nhỏ mở những trận tập kích vào một số vị trí đóng quân của địch. Lợi dụng nước thủy triều lên, Nguyễn Huệ cho những đội binh thuyền nhỏ xuất phát từ Mỹ Tho theo dòng sông đánh lên Trà Tân hoặc theo những cửa sông Ba Lai, Hàm Luông, Cổ Chiên đánh lên những vị trí của địch xung quanh Trà Tân rồi lại rút lui. Đó là những trận tập kích nhằm nghi binh thăm dò lực lượng địch và kích động thêm tinh thần chủ quan, khinh địch của quân Xiêm.

Mặt khác, Nguyễn Huệ còn biết rõ dã tâm của vua Xiêm là lợi dụng danh nghĩa cứu giúp Nguyễn Ánh để xâm lấn đất Gia Định và bọn quân lính Xiêm thì lợi dụng cuộc viễn chinh để cướp bóc của cải. Cuối năm 1784, Nguyễn Ánh đã than phiền với Bá Đa Lộc về “tình trạng hai lòng của người Xiêm”. Để khoét sâu thêm nhược điểm cơ bản của quân địch và tìm cách ly gián, tăng thêm sự hoài nghi giữa Nguyễn Ánh với quân Xiêm, Nguyễn Huệ dùng một tù binh người Chân Lạp làm sứ giả mang nhiều vàng bạc, gấm vóc đến gặp chủ tướng của quân Xiêm xin giảng hòa. Chiêu Tăng vừa nhận lễ vật để thỏa lòng tham không đáy, vừa âm mưu giả vờ giảng hòa để rồi bất ngờ tiến công quân Tây Sơn. Hắn tưởng thế là cao tay, là “tương kế tựu kế”. Chủ tướng quân Xiêm đang thỏa mãn với những “thắng lợi đã đạt được và tin tưởng vào những dự tính lớn mai sau, nhưng có ngờ đâu đang bị Nguyễn Huệ từng bước, từng bước một dẫn dắt vào cạm bẫy mà quân Tây Sơn đã giăng sẵn. Việc giảng hòa riêng với Chiêu Tăng còn có tác dụng gây thêm mối hoài nghi của Nguyễn Ánh đối với quân Xiêm. Trước thái độ ngờ vực của Nguyễn Ánh, Chiêu Tăng đã phải giãi bày, thề thốt nọ kia để làm tin.

Hơn mười ngày đã trôi qua kể từ khi Nguyễn Huệ đem quân vào Mỹ Tho. Quân Xiêm lúc đầu lo phòng thủ để sẵn sàng chống lại một cuộc phản công lớn của quân Tây Sơn. Nhưng rồi chúng thấy quân Tây Sơn chỉ mở những cuộc tập kích nhỏ và Nguyễn Huệ lại điều đình xin giảng hòa. Tại Mỹ Tho, chúng thấy quân Tây Sơn “lui lại, đem thuyền ra dần ở sông lớn để đợi xem biến chuyển ra sao". Những hành động của quân Tây Sơn càng làm cho Chiêu Tăng tin rằng Nguyễn Huệ không dám tiến công và đang chờ đợi kết quả giảng hòa. Hắn hí hửng bàn với Nguyễn Ánh: “Giặc rất tin tôi, tất không phòng bị, ta nên thừa thế mà đánh phá giặc ngay. Xin hẹn đến đêm mồng 9 tháng này (tháng Chạp năm Giáp Thìn), quốc vương đem ngự binh đi trước xông vào thuyền giặc. Tôi cùng các tướng bản bộ đem tất cả chiến thuyền lớn nhỏ tiến lên phá các thuyền chắn ngang sông của giặc thì thế nào cũng toàn thắng" (theo Mạc Thị gia phả). Chiêu Tăng đẩy quân bản bộ của Nguyễn Ánh đi trước mở đường, còn hắn sử dụng toàn bộ chiến thuyền, theo sông Mỹ Tho, mở cuộc tiến công lớn vào sở chỉ huy của Nguyễn Huệ, hòng bất ngờ đánh tan quân Tây Sơn.

Kế hoạch nhử địch ra khỏi căn cứ để tiêu diệt bằng một trận đánh vận động trên sông của Nguyễn Huệ đã thành công. Bọn tướng lĩnh Xiêm, như sử nhà Nguyễn chép: “cậy mình thắng luôn, bèn dẫn quân đến thẳng Mỹ Tho". Trong lúc đó, Nguyễn Huệ đã dày công nghiên cứu địa hình từ Trà Tân đến Mỹ Tho và quyết định chọn khúc sông Mỹ Tho từ Rạch Gầm đến Xoài Mút làm trận địa quyết chiến với quân thù.

Sông Mỹ Tho là một dòng sông lớn, phía trên tiếp nước Tiền Giang rồi đổ ra biển qua cửa Đại, cửa Tiểu và các nhánh sông Ba Lai, Hàm Luông. Đặc biệt, sông Mỹ Tho chảy qua phía trước Trà Tân và Mỹ Tho (trấn lỵ) là hai vị trí đóng quân và cũng là đại bản doanh của quân Xiêm - Nguyễn và quân Tây Sơn. Quân địch từ Trà Tân đánh lên Mỹ Tho phải hành quân theo đường sông Mỹ Tho. Đoạn sông Mỹ Tho từ Rạch Gầm đến Xoài Mút dài chừng 7 kilômét. Lòng sông ở đây lại mở rộng hơn 1 kilômét, có chỗ đến trên dưới 2 kilômét. Với đoạn sông dài và rộng lớn như vậy, quân Tây Sơn có thể dồn hàng trăm thuyền chiến của địch lại mà tiêu diệt. Hai bên bờ sông lúc đó có một số thôn xóm, nhưng thưa thớt, cây cỏ rậm rạp. Hai loại cỏ mọc nhiều ở vùng này là cỏ lác và cỏ tranh. Ven sông gần mặt nước là một dải rừng cây bần khá um tùm. Địa hình như vậy rất thuận lợi cho việc giấu quân và mai phục của bộ binh Tây Sơn.

Rạch Gầm và Xoài Mút là hai con sông nhỏ, thường gọi là rạch, nhưng giữ vị trí quan trọng trong thế trận của Nguyễn Huệ. Thủy binh Tây Sơn bố trí ở hai rạch này sẽ là hai mũi tiến công lợi hại chặn đầu và khóa đuôi toàn bộ đội hình quân địch một khi chúng đã lọt vào trận địa mai phục. Khoảng giữa Rạch Gầm và Xoài Mút, dòng sông Mỹ Tho có cù lao Thới Sơn. Đây là một bãi đất bồi, chu vi dài 5 dặm (khoảng 6km) nằm hơi chếch về phía nam sông Mỹ Tho, đối diện với cửa sông Xoài Mút. Tiếp theo cù lao Thới Sơn về phía nam là cù lao Hộ hay bãi Tôn. Bộ binh Tây Sơn bố trí trên những cù lao đó có thể dùng đại bác bắn vào sườn đội hình quân địch và sẵn sàng tiêu diệt những tên địch liều lĩnh đổ bộ lên để tìm đường tháo chạy. Những nhánh sông nằm giữa các cù lao và bờ nam là những nơi mai phục và xuất phát của đội thuyền chiến Tây Sơn lao ra chia cắt đoàn thuyền của địch thành từng mảng để tiêu diệt.

Về phía địch, sau khi đã bàn bạc phối hợp với nhau và chuẩn bị các mặt, tối 18 tháng 1 năm 1785 (ngày 8 tháng Chạp năm Giáp Thìn), quân Xiêm - Nguyễn bắt đầu rời khỏi khu căn cứ Trà Tân tiến thẳng đến Mỹ Tho. Chiêu Tăng, Chiêu Sương huy động tất cả chiến thuyền lớn nhỏ, toàn bộ lực lượng thủy binh và một bộ phận bộ binh vào cuộc tiến công này. Một bộ phận bộ binh còn lại do Sa Uyển chỉ huy vẫn đóng ở Đông Khẩn (Sa Đéc) để bảo vệ vùng đất chúng đã kiểm soát được thuộc hữu ngạn Tiền Giang. Chiêu Tăng trực tiếp chỉ huy cuộc tiến công. Quân bản bộ của Nguyễn Ánh do tổng nhung chưởng cơ Lê Văn Quân chỉ huy cũng tham gia cuộc tiến công dưới quyền điều khiển chung của chủ soái quân Xiêm là Chiêu Tăng. Số quân của Nguyễn Ánh lúc bấy giờ có khoảng ba, bốn nghìn, bị Chiêu Tăng đẩy đi trước mở đường. Nguyễn Ánh tham dự cuộc hành quân với tinh thần lo lắng, hoài nghi và tâm lý thất bại. Nguyễn Ánh cố đi sau với một số bầy tôi thân cận như hộ bộ Trần Phúc Giai, cai cơ Nguyễn Văn Bình, thái giám Lê Văn Duyệt để phòng khi lâm nguy còn kịp tháo chạy. Không những thế, Nguyễn Ánh còn phái tham tướng Mạc Tử Sinh về ngay Trấn Giang, chuẩn bị sẵn thuyền bè ở Long Hồ (Vĩnh Long) để đón mình chạy trốn khi cuộc tiến công thất bại.

Khoảng đầu canh năm ngày 19 tháng 1 năm 1785, đoàn thuyền chiến của địch lọt vào trận địa mai phục của quân Tây Sơn ở Rạch Gầm - Xoài Mút. Từ Trà Tân, chiến thuyền của địch theo sông Trà Luật (một nhánh Tiền Giang chạy theo bờ phía bắc cù lao Trà Luật) và Tiền Giang ra sông Mỹ Tho. Từ đây dòng sông mở rộng và quang đãng, đoàn thuyền địch trên 300 chiếc lớn nhỏ, xếp thành đội hình tiến nhanh về phía Mỹ Tho. Khi đoàn thuyền đã vào hết trong khúc sông được chọn làm trận địa quyết chiến, nghĩa là tiền quân địch đã đến cửa sông Xoài Mút và hậu quân đã qua cửa Rạch Gầm, Nguyễn Huệ ra lệnh công kích.

Mở đầu trận đánh, hai đội thủy binh Tây Sơn từ Rạch Gầm, Xoài Mút bất ngờ lao ra, chặn đánh hai đầu, dồn quân địch vào vòng vây đã bố trí sẵn. Đồng thời, đại bác của quân Tây Sơn từ hai bên bờ sông và trên cù lao Thới Sơn bắn xối xả vào khúc giữa đoàn thuyền địch lúc bấy giờ đang bị ùn lại. Bị chặn đầu, khóa đuôi và bị hỏa lực quân Tây Sơn áp đảo từ đầu, quân địch hết sức hốt hoảng và đội hình bị rối loạn. Ngay sau đó, những đội thuyền chiến của quân Tây Sơn từ các vị trí mai phục xông thẳng vào đội hình đang rối loạn của địch, chia nhỏ đoàn thuyền chúng ra từng mảng mà tiêu diệt. Chiến thuyền quân Tây Sơn từ Mỹ Tho cũng kịp thời đến tiếp ứng. Quân Tây Sơn, thủy bộ phối hợp với nhau, khép chặt vòng vây, hăng hái chiến đấu, tiêu diệt quân địch hết mảng này đến mảng khác. Hàng loạt thuyền chiến của địch lần lượt bị đánh đắm vì trúng đạn đại bác hoặc vì quân Tây Sơn xông lên tiêu diệt. Vô số quân địch bị giết chết tại trận: kẻ bị trúng đạn, trúng tên; kẻ thì bị gươm giáo đâm chém hay bị chết đuối giữa sông nước. Một số quân địch cố bơi vào bờ để tìm đường tháo chạy. Nhưng ở đấy, những đơn vị bộ binh Tây Sơn đã được bố trí sẵn để chờ chúng.

Toàn bộ thuyền chiến địch - trên 300 chiếc đều bị đánh đắm và phá hủy. Quân Xiêm bị thua to, bỏ chạy và chết gần hết (Đại Nam thực lục). Chiêu Tăng, Chiêu Sương cùng với một số tàn quân trốn được lên bờ bắc sông Mỹ Tho. Chúng phải liều chết đánh phá để mở đường tháo chạy lên Quang Hóa rồi qua đất Chân Lạp về Xiêm. Số tàn quân sống sót chạy theo Chiêu Tăng, Chiêu Sương có khoảng vài nghìn người. Đến tháng 3 năm 1785, bọn này mới về tới Vọng Các (Băng Cốc). Một bộ phận tàn quân địch bị thua trận ở phía sau, có lẽ thuộc hậu quân, bỏ chạy tán loạn ra các ngả. Chúng cướp được một số thuyền nhỏ của dân, theo đường thủy vượt biển về nước.

Khi các nhóm tàn quân Xiêm tháo chạy tán loạn theo các ngả đã dần dần tụ tập lại. Chiêu Tăng kiểm quân số thì thấy: “Lúc xuất quân, quân thủy, bộ tất cả gồm 5 vạn quân, nay chỉ còn hơn 1 vạn" (Mạc thị gia phả). Còn quân bản bộ của Nguyễn Ánh thì, bộ sử chính thức của triều Nguyễn, bộ Đại Nam thực lục chính biên, cũng đã ghi chép: “Lê Văn Quân và các quân cũng đều tan vỡ, bỏ chạy”. Đại bộ phận quân Nguyễn bị tiêu diệt. Viên cai cơ chỉ huy quân thủy là Nguyễn Văn Oai cùng nhiều viên tướng khác bị chết tại trận. Viên tướng tiền quân là Dũng hầu (chưa rõ tên) theo gót Chiêu Tăng trốn sang Chân Lạp. Chủ tướng quân Nguyễn là Lê Văn Quân thì quân lính tan tác mỗi người một ngả, phải vừa trốn tránh vừa thu nhặt tàn quân, đến giữa năm sau (tháng 6 năm 1786) mới đem được 600 quân sang Xiêm gặp Nguyễn Ánh. Những viên tướng khác như Nguyễn Văn Thành, Tôn Thất Huy, Tôn Thất Hội... mỗi người cũng chỉ còn được dăm chục tàn quân.

Riêng Nguyễn Ánh đã chuẩn bị cho cuộc chạy trốn trước khi bắt đầu cuộc tiến công của quân Xiêm - Nguyễn. Vừa thấy “thế giặc mãnh liệt, không thể chống nổi" (Mạc thị gia phả), Nguyễn Ánh đã vội bỏ mặc quân lính, rút chạy về phía sau. Nguyễn Ánh cùng một số tướng tá và tùy tùng hơn 10 người, theo sông Trà Luật ra Tiền Giang rồi tìm đường sang Trấn Giang. Tại Long Hồ, Mạc Tử Sinh, một viên tướng của Nguyễn Ánh, cũng chỉ còn 3 chiếc thuyền để đón Nguyễn Ánh sang Hà Tiên. Bọn tàn quân dần dần nhóm họp lại, chạy theo Nguyễn Ánh có hơn 200 người và 5 chiếc thuyền. Bọn chúng bị quân Tây Sơn truy lùng nên phải chạy ra đảo Thổ Châu, Cổ Cốt rồi lại trốn sang Xiêm. Trên đường chạy trốn, bọn chúng hết sạch cả lương thực. Nguyễn Văn Thành có lần đi ăn cướp đã bị thuyền buôn đánh lại và bị trọng thương. Nguyễn Ánh cũng phải ăn cơm ngô và có lúc mệt mỏi, kiệt sức quá phải nhờ người tùy tùng cõng chạy.

Số quân bản bộ của Nguyễn Ánh có khoảng 3 - 4 nghìn thì chỉ còn hơn 800 tên chạy thoát sang Xiêm, trong đó có 200 tên chạy trốn theo Nguyễn Ánh và 600 tên chạy theo Lê Văn Quân. Trong bức thư gửi cho giáo sĩ Li-ô sáu ngày sau trận Rạch Gầm - Xoài Mút, Nguyễn Ánh phải đau xót thừa nhận một thực tế: “Chúng tôi vừa bị thua trận, tất cả quân lính đều bị tan vỡ". Từ đấy, Nguyễn Ánh và bọn tàn quân phải sống cuộc đời lưu vong khốn khổ, nhục nhã trên đất Xiêm. Họ phải đi khai hoang, đốn củi và có khi phải đi đánh thuê cho vua Xiêm để làm kế sinh sống và nương tựa.

Trận Rạch Gầm - Xoài Mút diễn ra trên một đoạn sông Mỹ Tho vào lúc trời còn chưa sáng, ánh lửa đom đóm còn lập lòe trên những cây bần ven sông nhô ra mặt nước, như một câu ca dao đã diễn tả:
Bần gie lửa đóm sáng ngời,
Rạch Gầm soi dấu muôn đời uy linh.

Chỉ trong một ngày hôm đó (19 tháng 1 năm 1785) trận đánh đã kết thúc một cách nhanh chóng. Khoảng 3 vạn quân Tây Sơn đã giao chiến và đánh tan hơn 5 vạn quân Xiêm - Nguyễn, tiêu diệt gần 4 vạn quân Xiêm và hàng nghìn quân Nguyễn. Với chiến thắng Rạch Gầm - Xoài Mút, quân Tây Sơn đã giành được thắng lợi quyết định, quét sạch quân xâm lược ra khỏi đất Gia Định, thu hồi những vùng đất bị chiếm đóng và làm tiêu tan tham vọng của vua Xiêm đối với phần lãnh thổ cực Nam của nước ta. Chính các sử thần triều Nguyễn cũng nhận thấy: “Người Xiêm từ sau cuộc bại trận năm Giáp Thìn, miệng tuy nói khoác mà lòng thì sợ Tây Sơn như cọp" (Đại Nam thực lục). Vua Xiêm Cha kri I cũng phải thừa nhận: quân Xiêm “đại bại", bọn Chiêu Tăng, Chiêu Sương “ngu hèn, kiêu căng, hung hãn đến nỗi bại trận”, làm “bại binh, nhục quốc" (Mạc thị gia phả). Chiến thắng Rạch Gầm - Xoài Mút còn giáng một đòn đích đáng, vạch trần chân tướng phản bội của Nguyễn Ánh, đập tan lực lượng quân sự và ảnh hưởng chính trị của thế lực phong kiến phản động này.

Chiến thắng Rạch Gầm - Xoài Mút đã chứng tỏ nghệ thuật dùng binh tài giỏi của người anh hùng “áo vải” Nguyễn Huệ. Điểm nổi bật đầu tiên của chiến thuật quân sự Nguyễn Huệ là tư tưởng đánh tiêu diệt. Cuộc chiến tranh chống quân xâm lược Xiêm được tiến hành bằng hai giai đoạn: Giai đoạn rút lui bảo toàn lực lượng của đạo quân trấn giữ vùng Gia Định và giai đoạn phản công chiến lược tiêu diệt địch của đạo quân Tây Sơn do Nguyễn Huệ trực tiếp chỉ huy.

Trong giai đoạn phản công chiến lược, vấn đề đánh tiêu diệt được đặt lên hàng đầu. Sở dĩ như vậy là xuất phát từ thực tế không cho phép Nguyễn Huệ kéo dài thời gian chiến đấu. Như phần trước đã nói, kẻ thù của Tây Sơn lúc này không chỉ có quân Xiêm và quân của Nguyễn Ánh mà còn có quân Trịnh đang trấn giữ ở mặt Bắc. Kể từ năm 1775, đã mười năm ròng rã nghĩa quân Tây Sơn phải để cho quân Trịnh làm chủ Thuận Hóa và chiếm đóng từ đèo Hải Vân trở ra. Trong điều kiện đó, nghĩa quân Tây Sơn rơi vào thế không thể cùng một lúc đương đầu với cả hai tập đoàn phong kiến Trịnh và Nguyễn. Về phía chúa Trịnh, tuy rất muốn tiến xuống phía Nam, song vì đang sợ uy thế của Tây Sơn và cũng chưa có thời cơ thuận lợi. Nếu Tây Sơn kéo dài chiến tranh với quân Xiêm, quân Trịnh sẽ nhân cơ hội này, từ Thuận Hóa đánh vào Quy Nhơn, đẩy quân Tây Sơn vào tình thế cực kỳ nguy hiểm là cả hai mặt Nam, Bắc đều có giặc. Vì vậy, có nhanh chóng tiêu diệt và đánh tan được quân Xiêm ở mặt Nam, quân Tây Sơn mới bảo vệ được mặt Bắc.

Mặt khác, về so sánh lực lượng, đầu tháng 1 năm 1785 khi đại quân của Nguyễn Huệ vượt biển tiến vào Gia Định thì lực lượng quân Xiêm còn rất mạnh. Tuy về trang bị, vũ khí hai bên không hơn kém nhau nhiều, nhưng về số lượng thì quân Xiêm vẫn chiếm ưu thế. Lực lượng quân Xiêm - Nguyễn có khoảng 5 vạn, trong đó quân của Nguyễn Huệ ước tính khoảng 3 vạn. Với sự chênh lệch đó, nếu không thực hiện được một trận đánh tiêu diệt lớn thì kẻ địch sẽ có điều kiện về thời gian để tổ chức lực lượng đánh bại quân Tây Sơn. Thực tế đó đòi hỏi vị tướng cầm quân phải có quyết tâm lớn và tài giỏi trong chỉ huy đánh tiêu diệt. Hơn nữa, nếu không quyết định số phận quân địch trong thời gian ngắn, thì quân Xiêm - Nguyễn có điều kiện tập hợp bọn phản động trong nước để chống lại Tây Sơn và triển khai lực lượng chiếm đóng. Ở một số vùng chiến lược, quân Xiêm đã để người của chúng đóng giữ, như các tướng Sa Uyển đóng giữ Đồng Khẩu, Ông Cao đóng giữ ở Ba Thắc... Hoặc đối với Nguyễn Ánh, ở giai đoạn đầu đã tung một số tay chân đi các nơi tuyển mộ thêm quân để tăng cường lực lượng riêng. Chúng đã lôi kéo được hàng ngàn người theo, trong đó có quan lại cũ bị tán lạc trước đây và một số tên phản bội Tây Sơn đầu hàng giặc. Do vậy, trong giai đoạn phản công chiến lược Nguyễn Huệ xác định quyết tâm đánh tiêu diệt để đáp ứng yêu cầu chiến lược đánh nhanh thắng gọn. Điều kiện lúc này cũng có điều kiện thuận lợi cho ông thực hiện quyết tâm của mình: quân địch tuy đông nhưng sức chiến đấu đã giảm sút, nhân dân rất nhiệt tình ủng hộ nghĩa quân; bên cạnh đó sự chuẩn bị của Nguyễn Huệ đã chu đáo, quân Tây Sơn vừa tiến vào khí thế đang hăng, các tướng sĩ đều muốn dốc lòng trong trận quyết chiến với quân thù.

Để thực hiện thắng lợi trận quyết chiến chiến lược này, Nguyễn Huệ đã giải quyết một cách tốt nhất những vấn đề về chiến thuật như chọn cách đánh hiệu quả, tìm địa điểm quyết chiến thích hợp, nghệ thuật lập thế trận tiêu diệt địch... Từ cuối năm 1784, sau khi chiếm được Trà Tân và một phần đất Mỹ Tho, các tướng Xiêm chia quân giữ những vị trí quan trọng. Chúng chuẩn bị cho cuộc tiến công lên Mỹ Tho và Gia Định hòng đánh tan quân đội Tây Sơn ở đây để hoàn thành mục tiêu chiếm toàn bộ đất Gia Định. Nhưng khi biết tin đại quân của Nguyễn Huệ đã tiến vào Gia Định, quân Xiêm phải hoãn tiến công, lo phòng thủ để đề phòng một cuộc phản công lớn của quân Tây Sơn. Đại quân của giặc tạm thời hạ trại ở phía Tây Nam thị trấn Mỹ Tho từ Trà Luật đến Ba Lai, Trà Tân (kể cả cù lao Năm Thôn ngày nay). Ở đó, chiến thuyền của chúng có thể an toàn trong khúc sông giữa cù lao Năm Thôn, Tân Phong với tả ngạn sông Năm Thôn. Phần lớn quân lính và sở chỉ huy của Chiêu Tăng, Chiêu Sương và Nguyễn Ánh đóng ở Trà Tân. Lúc đó, quân Xiêm tìm cách thăm dò lực lượng và ý đồ của Nguyễn Huệ để quyết định đánh Gia Định.

Từ Quy Nhơn tiến quân vào, Nguyễn Huệ không tổ chức phòng ngự ở Gia Định mà cho quân tiến thẳng vào Mỹ Tho, đóng quân gần chỗ tập kết của địch. Thủy quân của Nguyễn Huệ vừa đến đã thực hiện một số cuộc tiến công nhỏ. Từ Mỹ Tho, theo nước triều lên, thuyền chiến Tây Sơn tiến lên khiêu chiến với giặc. Nhưng phía quân Xiêm và bọn Nguyễn Ánh vẫn “án binh bất động”. Sở dĩ như vậy vì cả hai phía đều hiểu rằng đây là bước thăm dò đối phương, tìm hiểu âm mưu, ý đồ của nhau. Quân địch chưa muốn đánh ngay vì chúng cũng gờm uy danh Nguyễn Huệ. Còn Nguyễn Huệ cũng đang đứng trước những khả năng tác chiến: có thể đem tất cả quân thủy bộ thực hành một cuộc tổng công kích vào đội hình đóng quân của giặc hoặc tiến hành tiến công địch khi chúng ra khỏi khu vực đóng quân và đánh chúng ở khu vực nào thuận lợi nhất?

Nguyễn Huệ không chọn phương thức tiến công lớn vào cụm quân giặc ở Trà Tân vì yếu tố bất ngờ lúc này không còn nữa. Nếu đánh ngay sẽ gặp nhiều khó khăn, có thể bị tổn thất nhiều và khó thắng nhanh được. Bởi vì lúc này địch đã có sự chuẩn bị và chọn vị trí đóng quân khá lợi hại. Phải “điệu hổ ly sơn”, kéo chúng ra khỏi căn cứ đóng quân và thực hiện trận quyết chiến ở một địa hình thuận lợi cho ta. Đó là ý đồ chiến thuật của Nguyễn Huệ. Trước đó, ngay từ khi mới đến Mỹ Tho, để tìm hiểu đối phương và nghi binh địch, theo lệnh của Nguyễn Huệ, một bộ phận nhỏ quân đội Tây Sơn đã thực hiện một số trận đánh với giặc. Ông còn để một bộ phận thủy quân chắn ngang sông Tiền Giang để ngăn địch, bảo đảm bí mật cho những hành động quân sự của mình. Ngoài ra ông còn thực hiện một số hoạt động “ngoại giao nghi binh” khác làm cho quân Xiêm lầm tưởng quân Tây Sơn yếu, không đủ khả năng thực hiện các cuộc phản công lớn như trước đây. Từ đó quân Xiêm càng chủ quan, ngạo mạn, khinh thường quân Tây Sơn và sớm muộn chúng sẽ mở cuộc tiến công lên Mỹ Tho.

Căn cứ vào tình hình trên, Nguyễn Huệ quyết định chọn hình thức tiến công địch đang vận động, kéo địch ra khỏi căn cứ đóng quân, đưa chúng đến một đoạn sông khác, nơi địa hình có lợi nhất cho ta để tiêu diệt toàn bộ quân địch trong một trận quyết chiến. Nguyễn Huệ đã chọn khúc sông Mỹ Tho từ Rạch Gầm đến Xoài Mút làm trận quyết chiến với giặc. Đây là một sự lựa chọn chính xác và tài giỏi của ông (như phần trước đã trình bày rõ về đoạn sông được chọn làm trận địa này). Việc xác định địa hình quyết chiến rất quan trọng, nhưng vấn đề lập thế trận, bố trí lực lượng hợp lý để đạt ý đồ chiến thuật cũng là một yêu cầu lớn của một trận tiêu diệt chiến lược. Thực tế trước khi tiến công Mỹ Tho, Nguyễn Huệ đã bí mật bố trí lực lượng, đã bày sẵn một thế trận mai phục ở Rạch Gầm - Xoài Mút để chờ quân Xiêm.

Một bộ phận thủy quân nhận nhiệm vụ nghi binh đánh nhử địch, buộc địch phải rời vị trí đóng quân, kéo chúng ra đoạn sông quyết chiến. Hai đội thủy binh tinh nhuệ giấu ở hai nhánh sông Rạch Gầm và Xoài Mút, hình thành hai gọng kìm tiến công chặn đầu, khóa đuôi, bao vây, dồn ép đội hình quân địch về đoạn sông đã được chọn làm vị trí quyết chiến. Bộ binh và đại bác bố trí ở cả hai bên bờ sông và trên cù lao Thới Sơn có nhiệm vụ phát huy hỏa lực bắn vào đội hình địch khi chúng đã lọt vào trận địa mai phục, khiến địch bất ngờ, rối loạn đội hình. Tiếp đó quân Tây Sơn sẵn sàng giáp chiến và truy kích tiêu diệt tàn quân địch. Còn lại một bộ phận thủy binh Tây Sơn vẫn đóng ở Mỹ Tho, nơi tập kết của đại quân để nghi binh và sẵn sàng tiếp ứng vào những giờ phút quyết định của trận quyết chiến. Thế trận thủy bộ liên hoàn của Nguyễn Huệ khá chặt chẽ, hoàn chỉnh và bí mật. Đó là một sáng tạo của chủ tướng Nguyễn Huệ và quân Tây Sơn trong bố trí lực lượng, lập thế trận mai phục để tiêu diệt địch.

Trận đánh diễn ra đúng như dự kiến của Nguyễn Huệ. Quân giặc xuất phát tiến công từ đêm 18 tháng 1 năm 1785. Bằng mưu trí khôn khéo, quân Tây Sơn đã từng bước dẫn dắt quân địch vào cạm bẫy. Rạng sáng 19 tháng 1, toàn bộ đội hình địch lọt vào trận địa mai phục của ta. Trận đánh đã nhanh chóng diễn ra và kết thúc thắng lợi trong ngày hôm đó. Như vậy, chỉ hơn mười ngày chuẩn bị kể từ khi tiến vào Gia Định, với số quân ít hơn nhiều so với địch, quân Tây Sơn do Nguyễn Huệ chỉ huy đã thực hiện một trận quyết chiến chiến lược hết sức oanh liệt, thắng lợi giòn giã. Trong trận này, Nguyễn Huệ đã làm chủ cả không gian và thời gian. Điều đó chứng tỏ rằng, Nguyễn Huệ đã đoán đúng âm mưu địch, biết rất rõ kế hoạch và thời gian tiến công của chúng. Nó cũng chứng tỏ tính chủ động, linh hoạt và tính kế hoạch trong hành động tác chiến của Nguyễn Huệ đã đạt đến một trình độ cao.

Trận Rạch Gầm - Xoài Mút là một trong những trận thủy chiến lớn nhất và lừng lẫy trong lịch sử chống ngoại xâm của dân tộc ta. Tham gia trận đánh có cả lực lượng bộ binh và pháo binh, song giữ vai trò chủ yếu vẫn là thủy binh quân Tây Sơn. Trước đó vào các năm 1782 và 1783, Nguyễn Huệ cũng đã thực hành hai trận thủy chiến tiêu diệt bọn Nguyễn Ánh. Đó là những trận thắng nhanh gọn, song về quy mô còn kém so với trận Rạch Gầm - Xoài Mút. Sự chỉ đạo chiến thuật của trận thủy chiến này có những đặc sắc đáng ghi nhận. Ở trận Rạch Gầm - Xoài Mút, lần đầu tiên về thủy chiến, Nguyễn Huệ đã thực hiện hợp vây toàn bộ thủy quân địch và chia cắt đội hình chúng để tiêu diệt. Đây là một điểm mới về vận dụng thủ đoạn tác chiến của Nguyễn Huệ. Trong trận đánh mang ý nghĩa một trận hội chiến lớn này, Nguyễn Huệ đã thực hiện chia cắt về mặt chiến thuật. Do hợp vây tốt nên quân Tây Sơn đã đánh địch trên cả bốn mặt, trong đó Nguyễn Huệ đã sử dụng một lực lượng lớn đánh thật mạnh vào cạnh sườn địch khiến quân Xiêm - Nguyễn vô cùng bối rối, hoảng loạn, tạo điều kiện thuận lợi để quân Tây Sơn giáp chiến tiêu diệt toàn bộ quân địch.

Ở đây, Nguyễn Huệ đã tổ chức và thực hành một trận đánh phối hợp giữa bộ binh, thủy binh và pháo binh trong một quy mô lớn, thực hiện đòn tiêu diệt chiến lược trên sông Mỹ Tho. Sự phát triển tương đối mạnh mẽ về hỏa lực pháo binh và sự xuất hiện một lực lượng lớn pháo binh trong quân đội Tây Sơn cùng với tài chỉ huy chiến đấu của Nguyễn Huệ dẫn đến sự xuất hiện hình thức tập kích bằng pháo binh vào đội hình tiến công của địch trong trận Rạch Gầm - Xoài Mút. Mạc thị gia phả ghi: “Đêm hôm ấy là mồng 9 tháng Chạp, đến trống canh năm nghe tiếng đại bác nổ liên hồi, biết ngay là đã giao chiến với giặc (chỉ quân Tây Sơn). Một lát sau, thấy quan tiểu hoàng môn cho khiêng người bị thương về...". Hỏa lực pháo binh được sử dụng ở mức cao và đã phát huy uy lực to lớn của nó, áp đảo quân địch ngay từ đầu. Dùng pháo binh bắn chuẩn bị trong một trận tiêu diệt là một điểm mới của chiến thuật Nguyễn Huệ.

Như vậy, hình thức chiến đấu hiệp đồng giữa pháo binh, thủy binh và bộ binh đã được Nguyễn Huệ thực hiện thành công. Sau đòn tập kích bằng pháo binh, thủy binh và bộ binh Tây Sơn đã nhất tề bao vây, tiến công và truy kích tiêu diệt quân địch. Cũng cần nhấn mạnh rằng, yếu tố bất ngờ về chiến lược cũng như về chiến thuật đã được thể hiện rõ trong trận Rạch Gầm - Xoài Mút. Từ khi Nguyễn Huệ tiến quân vào Mỹ Tho để thực hiện phản công chiến lược, quân Xiêm liên tục bị bất ngờ. Chúng cho rằng Nguyễn Huệ có thể tiến công ngay vào Trà Tân và đã chủ động phòng bị; nhưng quân Tây Sơn đã không đánh, những trận tập kích và những hoạt động nghi binh của Nguyễn Huệ làm cho quân Xiêm lầm tưởng rằng quân Tây Sơn yếu không dám tiến quân, đồng thời làm cho quân địch chủ quan tự mãn, tạo nên yếu tố bất ngờ cho trận quyết chiến. Nguyễn Huệ còn tạo ra yếu tố này bằng cách giấu kín lực lượng, lừa địch, dụ địch, dẫn chúng vào trận địa phục binh đã bày sẵn, rồi bất ngờ tiến công, bao vây làm cho địch không kịp trở tay, không kịp đối phó, mặc dù lực lượng quân Xiêm rất lớn.

Kết cục, từ chỗ chủ quan, coi khinh quân Tây Sơn, cho rằng “thế nào cũng toàn thắng" (lời của tướng giặc Chiêu Tăng), quân giặc đã sa vào một tình thế thật thảm bại. Bốn phần năm quân số xâm lược bị tiêu diệt, 300 chiến thuyền bị phá hủy, bị nhấn chìm hay lọt vào tay Tây Sơn. Giặc chỉ còn lại ít tàn binh chạy trốn với tinh thần hoảng loạn, rã rời. Chiêu Tăng và Chiêu Sương trong lúc nguy ngập bỏ thuyền lên bộ chạy trốn, “may được mấy tù binh Cao Miên dẫn đường theo đường bộ Quang Hóa về được tới Nam Vang"...

Cuộc kháng chiến chống Xiêm thắng lợi mà đòn quyết định là trận Rạch Gầm - Xoài Mút đã đưa phong trào Tây Sơn phát triển lên một trình độ mới. Từ đây, phong trào Tây Sơn làm chủ toàn bộ đất Đàng Trong và có điều kiện tiến ra Đàng Ngoài lật đổ nền thống trị của tập đoàn phong kiến vua Lê - chúa Trịnh, làm nhiệm vụ lập lại nền thống nhất đất nước, bảo vệ độc lập dân tộc. Cũng từ đây, phong trào Tây Sơn trở thành phong trào quật khởi của cả dân tộc, kết hợp chặt chẽ trong mục tiêu, tinh thần đấu tranh và tổ chức lực lượng, tính chất ác liệt của cuộc đấu tranh giai cấp và đấu tranh dân tộc. Đó là một nét đặc sắc tạo nên nguồn sức mạnh kỳ diệu cho phong trào Tây Sơn trong cuộc chiến đấu liên tục chống thù trong giặc ngoài, lập nên một chuỗi chiến công bất diệt trong lịch sử Việt Nam.

Trong lịch sử quân sự Việt Nam, trận Rạch Gầm - Xoài Mút, đỉnh cao của cuộc kháng chiến chống xâm lược Xiêm (1784-1785) giữ một vị trí khá đặc biệt, để lại những âm vang mà những trận đánh trước đó chưa từng có. Đây là một chiến công lẫy lừng của quân đội Tây Sơn, của nhân dân ta, chứng tỏ truyền thống bất khuất, tinh thần chiến đấu anh dũng và sáng tạo của quân dân ta thời đó dưới sự lãnh đạo thiên tài của Nguyễn Huệ, đã nâng cao và hoàn thiện một bước quan trọng nghệ thuật quân sự Việt Nam. Chiến thắng này đã nêu cao truyền thống thủy chiến lâu đời và ưu việt của quân dân ta, kế thừa và phát huy kinh nghiệm của những chiến thắng Bạch Đằng thời Ngô Quyền phá quân Nam Hán (năm 938) và thời Trần Hưng Đạo diệt quân Nguyên (năm 1288)...', 'TEXT', '2026-06-05 05:31:20.50462', '2026-06-05 05:31:20.504602', null, 'DRAFT'), ('6ed750ff-f26f-4fce-9bb9-01e62f386190', '687b57fe-865c-496a-83b3-f83690885dd1', '3870c36d-2dfe-4298-9acd-a8548feb89f8', 'CONTEXT', 'Chi tiết trận Đông Bộ Đầu', null, 'Trận Đông Bộ Đầu (ngày 29-1-1258, tức ngày 24 tháng Chạp năm Nguyên Phong thứ 7) là trận phản công chiến lược của quân đội nhà Trần, do vua Trần Thái Tông chỉ huy đánh tan đạo quân xâm lược Mông Cổ tại Đông Bộ Đầu (khu vực gần cầu Long Biên, Hà Nội ngày nay), kết thúc cuộc kháng chiến chống Nguyên - Mông lần thứ nhất (năm 1258).

Vào thế kỷ XIII, sau khi các bộ lạc được thống nhất, quốc gia Mông Cổ được thành lập, Thành Cát Tư Hãn bắt đầu mở những cuộc xâm lăng ra nước ngoài. Từ một bộ tộc ở vùng thảo nguyên châu Á, sau nửa thế kỷ chinh phạt, Mông Cổ đã trở thành một đế quốc hùng mạnh có lãnh thổ rộng lớn từ châu Á đến châu Âu. Những đạo kỵ binh Mông Cổ đã gây bao đau thương cho nhân dân nhiều nước nơi mà vó ngựa của chúng đã đi qua, nhưng tham vọng bành trướng của Mông Cổ vẫn không dừng. Sau khi chiếm được nước Đại Lý (vùng Vân Nam - Trung Quốc ngày nay), năm 1257, chúa Mông Cổ là Mông Ke (Mongka, cháu nội của Thành Cát Tư Hãn) quyết định mở cuộc tiến công tiêu diệt nước Tống (vùng Nam Trung Quốc ngày nay) giáp với biên giới nước ta. Thực hiện kế hoạch xâm lược, đích thân Mông Ke dẫn đại quân theo đường Tứ Xuyên tiến vào. Hốt Tất Liệt (Khubilai, em trai của Mông Ke, năm 1260 Hốt Tất Liệt lên ngôi vua nhà Nguyên tức Nguyên Thế Tổ) chỉ huy một cánh quân vượt qua sông Trường Giang đánh chiếm châu Ngạc (Vũ Xương, Hồ Bắc). Một cánh quân khác do Tô Ga Tra chỉ huy đánh chiếm hạ lưu sông Trường Giang. Tướng Ngột Lương Hợp Thai đang ở Đại Lý được lệnh đem quân xuống Đại Việt, từ đó đánh vào châu Ung (Nam Ninh, Quảng Tây), châu Quế (Quế Lâm, Quảng Tây) tiến lên gặp các cánh quân khác ở châu Ngạc. Cánh quân này như một mũi kiếm lao vào lưng quân Tống.

Đại Việt nằm ở phía Nam nước Tống đã trở thành vị trí hết sức quan trọng trong kế hoạch tiến xuống phía Nam của quân Mông Cổ. Chiếm được Đại Việt, chúng không chỉ có thêm một mũi vu hồi vào nước Tống, mà nơi đây còn trở thành bàn đạp; đồng thời là nơi cung cấp nhân vật lực để đế chế Mông Cổ mở các cuộc viễn chinh xuống các quốc gia Đông Nam châu Á. Họa giặc Mông Thát, nỗi kinh hoàng của nhiều dân tộc trên thế giới lúc bấy giờ bắt đầu đe dọa sự tồn vong của quốc gia Đại Việt.

Đứng trước nguy cơ đất nước bị xâm lược, nhà Trần đã tích cực phát triển kinh tế, chủ động tăng cường tiềm lực quân sự, thường xuyên theo dõi và nắm tình hình địch.

Tháng 9 năm 1257, tướng giặc là Ngột Lương Hợp Thai (Uryangkhadai) cho sứ sang nước ta yêu cầu nhà Trần cho quân Mông Cổ vào Đại Việt, lấy cớ là mượn đường để sang đánh Ung Châu, Quế Châu của Trung Quốc. Quân Mông Cổ vốn ỷ vào sức mạnh áp đảo, thường dùng đe dọa ngoại giao kết hợp với tiến công quân sự để lấy thành, cướp nước của người. Trải qua mấy chục năm đánh đông cướp tây, mỗi khi quân Mông Cổ cho sứ tới đâu, nơi ấy thường khiếp sợ, cúi đầu dâng đất xin hàng hoặc xưng thần nộp cống. Đối với Đại Việt, quân Mông Cổ cũng làm như thế. Nhưng ở Đại Việt, tình hình lại không diễn ra theo ý muốn của chúng. Dân tộc ta thời Trần hiểu rất rõ thế mạnh của giặc. Qua những hành động xâm lược của Mông Cổ trên đất Trung Quốc, diệt Tây Hạ, diệt Kim, đánh Tống, diệt Đại Lý, đô hộ Cao Ly...

Nhưng dũng khí của dân tộc ta vượt lên trên sức mạnh của giặc. Dân tộc ta thời Trần kiên quyết bảo vệ độc lập, tự do của Tổ quốc, kiên quyết chống xâm lược, không nao núng trước bất cứ một sức mạnh phi nghĩa nào. Đối với giặc Mông Cổ, triều đình nhà Trần bước đầu trừng trị ngay lối ngoại giao đe dọa của giặc. Vua Trần Thái Tông không những không cho mượn đường mà còn hạ lệnh tống giam sứ giặc không cho trở về.

Cuối năm 1257, vua Trần Thái Tông xuống chiếu điều quân lên tăng cường bổ phòng ở biên giới Tây Bắc, lệnh cho cả nước sắm sửa vũ khí, khẩn trương chuẩn bị kháng chiến. Với sự chuẩn bị tích cực, cùng với tinh thần kiên quyết chống giặc xâm lược, nhà Trần và quân dân Đại Việt đã chủ động từng bước sẵn sàng kháng chiến chống quân Mông Cổ.

Tháng 12 năm 1257, tướng Ngột Lương Hợp Thai đưa quân tập trung sát vùng biên giới nước ta hòng đe dọa quân dân nhà Trần. Sau thất bại về đe dọa ngoại giao, Ngột Lương Hợp Thai hùng hổ đưa quân vượt biên giới sang đánh Đại Việt.

Theo kế hoạch, đạo quân Mông Cổ do Ngột Lương Hợp Thai chỉ huy tiến vào Đại Việt phải thực hiện hai nhiệm vụ chiến lược: nhanh chóng đánh chiếm Đại Việt sau đó thực hiện mũi vu hồi vào phía Nam nước Tống. Từ Vân Nam tiến vào nước ta có hai con đường bộ thuận tiện cho kỵ binh Mông Cổ hành quân; một theo bờ phải và một theo bờ trái sông Thao (sông Thao là đoạn Sông Hồng từ biên giới phía Bắc nước ta đến ngã ba Bạch Hạc, Việt Trì, Phú Thọ).

Lực lượng tiên phong của quân Mông Cổ chia làm hai cánh dưới sự chỉ huy của Triệt Triệt Đô và một số tướng khác theo tả và hữu ngạn sông Thao tiến vào nước ta. Tướng A Truật (18 tuổi, con của Ngột Lương Hợp Thai) được lệnh vừa tiếp ứng cho các cánh quân tiên phong, vừa dò xét tình hình phòng thủ của quân ta. Đại quân dưới sự thống lĩnh của Ngột Lương Hợp Thai tiến tiếp sau.

Từ thực tế của tình hình chiến đấu, triều đình nhà Trần quyết định để cho giặc tiến vào nội địa nước ta, trên đường từ biên giới tới Thăng Long, quân ta sẽ đánh tiêu hao, nhân dân thì làm vườn không nhà trống, không cho địch giết người cướp của trên dọc đường chúng hành quân, và Kinh thành Thăng Long phải triệt để sơ tán.

Theo kế sách của triều đình nhà Trần, quân dân ta dưới quyền Tiết chế Trần Quốc Tuấn đã anh dũng chiến đấu, đánh chặn địch từng bước nhằm tiêu hao sinh lực, hạn chế đường tiến quân của chúng, tạo điều kiện thuận lợi cho đại binh từ Kinh đô tiến lên hướng Tây Bắc. Quân thủy quân bộ của ta được lệnh tiến lên biên giới chắc số lượng không nhiều và hẳn chưa phải là để đánh đuổi giặc ra khỏi biên giới hoặc tiêu diệt chúng tại biên giới. Đây là những đơn vị làm nhiệm vụ phối hợp với quân và dân địa phương vùng Tây Bắc tiến công tiêu hao địch, khiến chúng mệt mỏi và suy yếu dần, tạo điều kiện cho đại quân ta tập trung tiêu diệt chúng tại một địa bàn thuận lợi trong nội địa.

Ta dự kiến sẽ tiến hành trận quyết chiến ở Bình Lệ Nguyên (vùng Bình Xuyên, Vĩnh Phúc ngày nay). Đây là vùng đất có sông Cà Lồ chắn ngang đường tiến công của quân địch. Tại đây quân ta lập một phòng tuyến chặn giặc bảo vệ kinh đô. Trận địa của quân ta lập bên này sông, bố trí cả bộ binh, tượng binh và thủy binh cùng nhiều thuyền chiến đậu sát bờ sông, Vua Trần Thái Tông trực tiếp chỉ huy và tướng tiên phong là Lê Tần - một viên dũng tướng tài ba, mưu lược, có tư duy phân tích thực tiễn nhạy bén.

Ngày 17 tháng 1 năm 1258, quân Mông Cổ tới được Bình Lệ Nguyên. Để tiến qua sông, địch chia lực lượng thành ba đội. Đội tiên phong do Triệt Triệt Đô cầm đầu vượt sông trước ở phía hạ lưu; Ngột Lương Hợp Thai chỉ huy trung quân đột phá chính diện quân ta. Đội thứ ba do phò mã Hoài Đô cùng A Truật chỉ huy tiến tiếp theo đánh vào phía sau quân ta. Âm mưu của địch là nhử quân ta vượt sông giao chiến để chúng bao vây, cắt đường rút, hòng tiêu diệt hoàn toàn lực lượng quân ta, rồi tiến thẳng về Thăng Long. Nhưng thực tế chiến trận lại không theo ý muốn của địch. Khi đội quân tiên phong của Triệt Triệt Đô vừa tới bờ sông liền bị quân ta đón đánh quyết liệt, buộc Ngột Lương Hợp Thai phải đưa đại quân ra tiếp ứng. Trận chiến diễn ra rất ác liệt. Địa thế bằng phẳng tạo thuận lợi cho kỵ binh địch tung hoành. Quân giặc cậy đông quân, ào ạt tấn công ta từ nhiều phía. Quân ta không hề nao núng, bình tĩnh, dũng cảm chống trả các đợt tiến công của địch, kiên quyết giữ vững trận địa. Vua Trần Thái Tông bất chấp mưa đạn xông lên phía trước, đốc thúc tướng sĩ đánh giặc. Tướng Lê Tần cưỡi ngựa lao vào đánh giặc với sắc mặt bình thản như không. Quân địch do phát huy được sở trường và quen chinh chiến, quân ta nhiều năm chưa chiến đấu với giặc ngoài nên khó tránh khỏi lúng túng, trận địa của ta mất dần trước sức đột kích mạnh của kỵ binh thiện chiến địch.

Tình thế cuộc chiến đặt quân ta vào sự lựa chọn: tiếp tục chiến đấu hay lui quân? Có ý kiến đề nghị vua Trần Thái Tông hãy quyết chiến với kẻ thù tại đây. Từ thực tế so sánh thế trận giữa ta và địch trên chiến trường, nhận thấy tiếp tục chiến đấu sẽ khó có thể trụ nổi với giặc, tướng Lê Tần, vị tướng gan dạ luôn xông pha chiến trận đã cố khuyên vua Trần Thái Tông tạm thời rút lui bảo toàn lực lượng, chờ thời cơ có lợi để phản công: "Như nay chỉ là bệ hạ dốc túi đánh nước cuối cùng thôi. Nên lánh đi, chớ nên nhẹ dạ tin người ta" (Đại Việt sử ký toàn thư). Lời khuyên này chứng tỏ Lê Tần là viên tướng tài ba, ông đã phát hiện sở trường và thế mạnh của kẻ thù, nhận rõ được thế ta, thế địch trong hoàn cảnh bấy giờ để đưa ra kế “tạm lánh” nhằm bảo toàn lực lượng, chờ thời cơ sẽ tiến công tiêu diệt địch.

Nghe theo lời khuyên của Lê Tần, vua Trần Thái Tông quyết định cho quân lên thuyền xuôi theo dòng sông Cà Lồ. Quân địch đuổi theo bắn loạn xạ. Lê Tần đi phía sau cho quân lấy ván thuyền cản tên bắn của giặc bảo vệ cho vua cùng quân ta rút lui về Phù Lỗ để tiếp tục lập phòng tuyến chặn đánh giặc.

Quân Mông Cổ không cướp được thuyền, không chặn được quân ta rút lui, âm mưu bắt sống vua Trần, tiêu diệt lực lượng của ta không thành.

Đông Bộ Đầu là một bến thủy quân lớn ở liền sát kinh thành, trên bến có doanh trại thủy binh đóng (Đông Bộ đầu ở phía đông thành Thăng Long, khoảng từ dốc Hàng Than đến phố Hòe Nhai, quận Ba Đình, Thủ đô Hà Nội ngày nay). Khi quân Mông Cổ tới Đông Bộ Đầu thì thủy quân và thuyền chiến của ta đã rời đi từ trước, chỉ còn doanh trại trống không. Giặc đóng ở đấy. Nhưng giặc không thể vượt xa được để cướp lương ăn. Từ khi để giặc vào Thăng Long, quân ta một mặt vây chặt không để giặc lọt ra ngoài, một mặt ráo riết chuẩn bị phản công.

Binh lực của Ngột Lương Hợp Thai có khoảng 3 vạn quân, gồm kỵ binh Mông Cổ và kỵ binh người Lô Lô hay Thoán Bặc (một tộc người Vân Nam - Trung Quốc). Ngột Lương Hợp Thai cho dựng hàng ngàn lều trại lớn nhỏ bằng da thú ở bến Đông Bộ Đầu. Đại bản doanh của Ngột Lương Hợp Thai đặt ở vị trí trung tâm, giữa những lều trại của những đội quân thân binh, vòng ngoài là trại của binh lính. Cạnh các lều trại đều có tàu ngựa, yên cương luôn đóng sẵn; quân lính luôn ở tư thế sẵn sàng tham chiến. Phía ngoài của khu đóng quân còn có ba tuyến canh gác thường trực, trên các ngả đường đến bản doanh đều đặt trạm cảnh giới. Những đội kỵ binh nhỏ ngày đêm lùng sục quanh thành Thăng Long nắm tình hình, truy tìm vết tích đại binh của ta và tiến hành cướp lương thực... nhưng đều bị quân ta đánh lui.

Về phía quân ta, sau khi rút khỏi Thăng Long, triều đình nhà Trần cùng đại quân theo Sông Hồng về đóng ở bãi sông Thiên Mạc (Thiên Mạc là tên cổ của khúc Sông Hồng chảy giữa các tỉnh Hưng Yên và Hà Nam ngày nay) cách địch khoảng 30 - 35 kilômét về phía Nam. Được nhân dân hết lòng che chở, giữ bí mật, quân ta tranh thủ thời gian tập trung bổ sung lực lượng, chỉnh đốn đội ngũ, sẵn sàng chờ lệnh là xuất quân. Linh Từ quốc mẫu Trần Thị Dung, vợ Thái sư Trần Thủ Độ đã thu thập tất cả những quân khí ở trong thuyền của các gia đình đi lánh nạn để gửi ra cho quân đội. Sau một thời gian rất ngắn khẩn trương chuẩn bị, lực lượng đã hồi phục, khí thế chiến đấu của quân ta lại bừng lên. Trong khi đó, quân Mông Cổ bắt đầu khổ sở và lúng túng, sa sút tinh thần vì thiếu lương thực trong một tòa thành trống, bệnh tật phát triển và do không hợp khí hậu, sức chiến đấu giảm nhanh chóng. Quân địch cố gắng tiến hành những cuộc cướp nống ra vùng xung quanh Thăng Long nhưng ở đâu chúng cũng gặp sức chống trả mãnh liệt của nhân dân ta. Chẳng hạn như khi quân Mông Cổ tiến đến Cổ Sở (nay là xã Yên Sở), nhân dân ở đây đã đoàn kết chiến đấu, bảo vệ xóm làng, đánh cho bọn địch phải bỏ chạy tan tác.

Đối với quân ta, lần đầu tiên giao chiến với kỵ binh Mông Cổ, trước thế tiến công ào ạt, hung hăng và áp đảo của địch, vua Trần và các tướng lĩnh như Trần Thủ Độ, Lê Tần, Trần Quốc Tuấn, Trần Khánh Dư... ngày đêm suy nghĩ, phân tích những mặt mạnh, mặt yếu của địch, của ta để rút ra chiến lược, chiến thuật phù hợp và cách đánh hiệu quả nhất.

Quân Mông Cổ đóng ở Đông Bộ Đầu ngày càng gặp khó khăn do không nắm được tình hình quân ta, lương thảo ngày càng vơi cạn, tinh thần quân lính bắt đầu chán nản, dao động, còn Ngột Lương Hợp Thai chần chừ chưa quyết định tấn công. Lúng túng, cùng quẫn, quân Mông Cổ lâm vào thế bắt buộc phải án binh bất động; mà động cũng không được vì bị quân ta vây chặt; không chết trận thì chết đói. Điều kiện chủ quan và khách quan đó đã tạo nên một thời cơ tốt nhất để ta phản công tiêu diệt chúng.

Trước thời cơ đó, vua Trần Thái Tông họp bàn với các tướng lĩnh. Tướng Lê Tần, tướng Trần Khánh Dư cùng bộ chỉ huy tối cao nhiệt liệt tán thành kế hoạch “nhân cơ đánh úp giặc”. Cuộc phản công được nhanh chóng quyết định với quyết tâm cao của quân dân nhà Trần khẳng định qua lời nói của Thái sư Trần Thủ Độ với vua Trần: “Đầu tôi chưa rơi xuống đất thì bệ hạ không cần lo ngại gì cả” (Đại Việt sử ký toàn thư). Lời nói quả quyết, tràn đầy hào khí đã tạo niềm tin vững chắc, sức mạnh chiến thắng của quân ta được bộ chỉ huy quyết định cuộc phản công chiến lược bất ngờ diễn ra vào đêm 28 rạng 29 tháng 1 năm 1258.

Tham gia trận đánh quyết định này, bên cạnh vua Trần Thái Tông và Thái tử Trần Hoàng còn có nhiều vương hầu, tướng lĩnh chủ chốt như Trần Quốc Tuấn, Trần Thủ Độ, Lê Tần là những người thường xuyên có mặt tại đại bản doanh tại sông Thiên Mạc để cùng bàn bạc nghĩ kế đánh phòng và phản công. Dưới quyền tiết chế của Trần Quốc Tuấn trong trận phản công chiến lược táo bạo này có khoảng gần 4 vạn quân gồm bộ binh, thủy binh và kỵ binh.

Sau khi đã xác định kế hoạch trận đánh úp, đúng ngày đã định, hai cánh quân thủy bộ bắt đầu xuất phát nhằm thẳng kinh đô tiến quân. Cánh bộ chia làm hai mũi từ phía nam và phía tây chọc thẳng vào khu địch đóng quân; cánh thủy do vua Trần Thái Tông cùng các tướng chỉ huy đoàn binh thuyền từ Thiên Mạc theo Sông Hồng đổ bộ lên Đông Bộ Đầu, triển khai đội hình tập kích vào doanh trại quân địch ở mặt đông.

Đêm 28 tháng 1 năm 1258, tiền quân nhà Trần đã tiến sát Thăng Long và tách làm hai hướng. Khoảng 5 nghìn kỵ binh hợp thành một mũi tiến công về phía tây (mũi trái) khu đóng quân của địch. Khoảng 3 nghìn bộ binh tiếp tục tiến sát khu địch đóng quân từ mặt nam (mũi phải). Đến nửa đêm thì các mũi tiến quân của ta đã tiếp cận các tuyến canh gác của địch mà chúng vẫn không hề hay biết. Mặc dù thủy binh và đạo quân chủ lực còn ở xa, nắm lấy thời cơ có lợi, tướng tiên phong Trần Khánh Dư lập tức hạ lệnh đánh úp thẳng vào trại giặc.

Đúng như kế hoạch, bộ binh và kỵ binh của ta thần tốc lao vào khu lều trại quân Mông Cổ. Kỵ binh của ta chớp nhoáng tiêu diệt kỵ binh địch; đồng thời từng nhóm bộ binh ta tổ chức bao vây tiêu diệt ngay trong lều trại của chúng. Quân của Ngột Lương Hợp Thai hỗn loạn, bị động bất ngờ “người không kịp mặc giáp, ngựa không kịp đóng yên” chống lại một cách yếu ớt, hoảng loạn. Tuy về số lượng quân ta ít hơn quân địch (chủ lực của ta gần sáng mới tới) nhưng do chủ động, tinh thần chiến đấu cao, cách đánh tài tình, táo bạo, chọn đúng thời cơ không cho địch kịp phát huy sở trường (thời điểm người tách khỏi ngựa), quân ta chiếm hoàn toàn ưu thế.

Mặc dù dốc sức đối phó, chống trả, đến sáng Ngột Lương Hợp Thai mới biết rõ đại quân của y đã bị thiệt hại hết sức nặng nề. Trong lúc đó, sức mạnh của quân ta lại được tăng cường, chủ lực đến tiếp sức. Thấy rõ nguy cơ bị tiêu diệt, lợi dụng quân ta đang triển khai lại đội hình thì tướng giặc Ngột Lương Hợp Thai ra lệnh cho các tướng sĩ mở đường máu, rút chạy khỏi Thăng Long về hướng Bạch Hạc.

Quân giặc chạy lên ngã ba Bạch Hạc để theo đường bên phải sông Thao, chạy qua vùng Quy Hóa trở về Đại Lý. Khi quân giặc chạy tới Bạch Hạc, Sơn Vì thì Phùng Lộc Hộ lại đem quân địa phương đánh đuổi chúng, giặc lại chạy lên Quy Hóa (Phú Thọ). Chủ trại Quy Hóa là Hà Bổng (dân tộc Mường) cùng quân và dân bố trí đánh tập kích, giặc thua to. Tàn binh giặc mất hết tinh thần chiến đấu, cố chạy thoát thân ra khỏi biên giới. Khi về đến Đại Lý, đạo quân của Ngột Lương Hợp Thai chỉ còn lại khoảng 5 nghìn tên.

Khi đem tàn quân ra khỏi biên giới Đại Việt để về Đại Lý (Vân Nam - Trung Quốc), Ngột Lương Hợp Thai dừng chân tại thành Áp Xích (Côn Minh, Trung Quốc). Ngột Lương Hợp Thai (Uryangkhadai) - viên tướng bách chiến bách thắng của Đại hãn Mông Ke từng làm mưa làm gió trên các chiến trường Á, Âu đã phải thua trận nhục nhã trên đất Đại Việt. Đội quân xâm lược này tiến vào Đại Việt tuy không lớn nhưng có đến 50 viên tướng tá là thân vương, trong đó phải kể đến Abisca - con trai Thành Cát Tư Hãn. Đạo quân hùng mạnh thiện chiến và nhiều tướng tài như vậy mà chỉ chiếm được thành Thăng Long có 9 ngày.

Trận đánh của quân dân nhà Trần đã hoàn toàn thắng lợi. Khoảng 2 vạn kỵ binh địch đã phải bỏ xác trên bến Đông Bộ Đầu.

Sáng 29 tháng 1 năm 1258 (tức ngày 24 tháng Chạp năm Đinh Tỵ), vua Trần Thái Tông cùng các tướng lĩnh, binh sĩ tiến vào kinh thành vừa được giải phóng trong niềm hân hoan của nhân dân kinh đô.

Thắng lợi trong cuộc chiến chống quân xâm lược Mông Cổ lần thứ nhất (năm 1258) thể hiện ý chí kiên cường và lòng dũng cảm, mưu lược vô song của quân và dân Đại Việt dưới sự chỉ huy tài giỏi của vua Trần Thái Tông và các quần thần, trong đó có vai trò rất to lớn của Thái sư Trần Thủ Độ.

Ngày 5 tháng 2 năm 1258 (mồng 1 Tết Mậu Ngọ), tại Thăng Long, triều đình nhà Trần tổ chức lễ mừng thắng trận và phong thưởng cho tướng sĩ đã có công lao trong trận thắng vừa qua. Lê Tần được phong chức Ngự sử đại phu, tước Bảo Văn hầu, được đổi gọi là Lê Phụ Trần. Vị thủ lĩnh người dân tộc miền núi ở trại Quy Hóa là Hà Bổng cũng được phong tước hầu, Trần Khánh Dư được khen thưởng vì đã có công thừa cơ tập kích giặc. Trong số những người được khen thưởng có những người là dân thường nhưng rất kiên cường, anh dũng tiêu biểu cho khí phách anh hùng và sức mạnh chiến đấu của đông đảo nhân dân yêu nước, quyết tâm bảo vệ Tổ quốc như Phùng Lộc Hộ và bảy anh em họ Lỗ đã cùng nhân dân địa phương ngoan cường đánh địch từ khi chúng tiến công tới và khi chúng rút chạy. Riêng Phùng Lộc Hộ hy sinh trong chiến đấu, được nhà vua đặc biệt gia phong tước “Lân Hồ đô thống đại vương" và khen tặng tám chữ “Nam thiên tráng khí, Bắc khấu hàn tâm" (Trời Nam khí mạnh, giặc Bắc lòng run).

Cùng với Kinh đô Thăng Long, quân và dân cả nước ta vui mừng phấn khởi, tự hào cùng đón những ngày đầu năm chiến thắng. Cuộc kháng chiến chống quân xâm lược Mông Cổ lần thứ nhất của quân dân ta đã hoàn toàn thắng lợi mà Đông Bộ Đầu là trận có tính chất quyết định. Cuộc xâm lược Đại Việt của đế quốc Mông Cổ bước đầu thất bại, việc tạo dựng gọng kìm để tấn công vào phía Nam nước Tống cũng bị bẻ gãy.

Chiến thắng Đông Bộ Đầu năm 1258 thời Trần là thắng lợi hiển hách đầu tiên của những nước bị đế quốc Mông Cổ xâm lược. Đây cũng là thất bại đầu tiên của đế quốc Mông Cổ trong cuộc trường chinh chiếm gần 50 nước từ Á sang Âu. Quân giặc đánh đâu thắng đấy, nếu đánh một lần chưa được thì đánh liên tiếp lần khác cho tới khi giành thắng lợi. Vậy mà đối với Đại Việt sau lần thất bại này (1258), giặc Mông Nguyên phải chùn bước, mãi gần 30 năm sau chúng mới dám mở cuộc tiến công xâm lược lần thứ hai (1285). Thắng lợi đó đã khẳng định chân lý một nước nhỏ nhưng anh dũng và thông minh, biết đoàn kết các tầng lớp nhân dân, đoàn kết các dân tộc hoàn toàn có khả năng đánh bại các cuộc xâm lược của một đế quốc hùng mạnh.

*

Trận Đông Bộ Đầu năm 1258 đã kết thúc thắng lợi cuộc kháng chiến chống Nguyên - Mông lần thứ nhất, để lại nhiều kinh nghiệm đánh giặc vô cùng quý báu cho quân và dân Đại Việt. Những kinh nghiệm ấy là nền móng hình thành nên tư tưởng chiến lược “lấy nhàn chờ nhọc”, “lấy đoản binh phá trường trận"... mà Hưng Đạo Vương Trần Quốc Tuấn và triều đình nhà Trần đã tổng kết và áp dụng thành công trong các cuộc kháng chiến chống Nguyên lần thứ hai và thứ ba sau này.

Qua diễn biến của trận tập kích Đông Bộ Đầu, có thể rút ra mấy vấn đề về nghệ thuật quân sự như sau:

*   Đánh giá đúng địch ta, xác định chính xác phải rút lui và rút lui đúng thời cơ. Để tránh sức mạnh ban đầu và sở trường của địch, quân đội nhà Trần đã rút lui chiến lược khỏi Bình Lệ Nguyên, sau đó rút lui khỏi cả Kinh đô Thăng Long, làm kế hoạch bao vây đánh tan quân ta của địch bước đầu bị thất bại. Để bảo đảm an toàn cho các lực lượng rút lui, quân Trần đã triển khai các điểm chốt chặn trên các trọng điểm như Phù Lỗ, quân ta phá cầu Phù Lỗ làm cho quân Mông Cổ không truy đuổi kịp vua Trần. Đồng thời, quân ta sử dụng một bộ phận lực lượng cùng các lực lượng dân binh, thổ binh đánh nhỏ lẻ rộng khắp cả trước mặt, sau lưng, hai bên sườn địch; kết hợp với kế hoạch “thanh dã", đã gây cho địch từ tập trung phải chuyển sang phân tán đối phó và luôn bị uy hiếp căng thẳng, mệt mỏi, thiếu lương thảo... khi tới Thăng Long thì chỉ là một kinh thành trống vắng, chúng nống ra xung quanh cướp phá lương thảo nhưng lại bị đánh trả quyết liệt. Quân ta ngày đêm tổ chức tập kích, quấy rối... làm cho địch không dám đóng quân trong thành mà đóng tại bến Đông Bộ Đầu dừng lại điều chỉnh chiến lược. Về phía ta, khi tình hình thực tế chưa cho phép diệt địch triệt để, kịp thời thay đổi kế hoạch rút lui để bảo toàn lực lượng là hết sức đúng đắn và sáng suốt.
*   Rút lui bí mật, nghi binh tạo bất ngờ cao, bảo toàn lực lượng, giữ vững ý chí chiến đấu, tích cực chuẩn bị mọi mặt cho tổng phản công. Quân ta chủ động rút lui khỏi Thăng Long không những bảo toàn được lực lượng, tranh thủ được thời gian, tạo thời cơ để phản công mà còn đặt địch trước tình thế không thực hiện được chiến lược đề ra. Một trong những tình huống khó khăn và đáng lo ngại nhất của quân Mông Cổ là không biết tình hình và ý định hành động của quân ta. Quân dân Đại Việt đã chủ động tạo nên cục diện mới trên chiến trường. Đại quân và triều đình theo Sông Hồng rút về xuôi, đóng dọc khúc sông Thiên Mạc. Quân ta dùng thuyền rút theo đường sông nên kỵ binh Mông Cổ nếu truy kích sẽ gặp khó khăn. Mặt khác địch lại không rõ tình hình, ý định của quân ta nên không dám truy kích. Tại vùng Thiên Mạc, quân ta nhanh chóng củng cố, tăng cường lực lượng. Khi thời cơ đến, binh thuyền của ta có thể nhanh chóng theo Sông Hồng tiến về Thăng Long tiến hành phản công được thuận tiện.
*   Chọn thời cơ tập kích chính xác, kiên quyết, đúng mục tiêu, hướng tiến công sáng tạo. Trong cuốn “Binh thư yếu lược", đã tổng kết về thời cơ như sau: “Thời là cái đến không đầy chớp mắt, trước thì thái quá, sau thì bất cập...". Quân Mông Cổ không dám đóng trong thành Thăng Long, phải cụm lại Đông Bộ Đầu trong vòng vây của thế đánh nhỏ lẻ. Sau một cuộc hành quân chiến đấu trên quãng đường dài, sinh lực bị tiêu hao, binh lính mệt mỏi và bắt đầu mất hết tinh thần chiến đấu. Sau 9 ngày vào chiếm Kinh thành Thăng Long, quân Mông Cổ đã mất hết “nhuệ khí ban mai” của một đạo quân tiến công như lốc cuốn... Đó là thời cơ để nhà Trần phản công. Mặc dù đạo quân chủ lực do vua Trần chỉ huy còn chưa tới, ngay trong đêm nắm lấy thời cơ có lợi, tướng Trần Khánh Dư lập tức hạ lệnh tập kích (đánh úp)... lực lượng địch có khoảng 3 vạn được xác định là mục tiêu chủ yếu. Lực lượng phản công của nhà Trần chia làm 2 cánh, một cánh theo đường bộ cơ động triển khai trước, còn cánh chủ yếu theo đường thủy (Sông Hồng) đổ bộ lên đánh thẳng vào cụm quân địch. Lợi dụng đêm tối quân ta quen địa hình, cuộc phản công được vận dụng dưới hình thức một trận tập kích lớn, chia cắt người và ngựa quân địch, giành thắng lợi quyết định trong đêm.

Nghệ thuật rút lui và nghệ thuật phản công trong chiến trận Đông Bộ Đầu thể hiện đầy đủ tính tích cực, chủ động tiến công địch, thực hiện rút lui chiến lược, tiến công nhỏ lẻ rộng khắp buộc địch co cụm lại, sa vào thế bị động chống đỡ, từ mạnh chúng chuyển thành yếu... đó là thời điểm để quân ta tập kích đạt hiệu quả cao nhất. Quân ta từ yếu thành mạnh, mạnh chuyển thành thắng thông qua đòn tập kích quyết định.

Giặc Mông Cổ có ưu thế về lực lượng kỵ binh cơ động nhanh, nhưng quân ta đã không cho chúng có dịp phát huy sở trường này. Ta tạm lùi một bước để tránh giao chiến với địch khi điều kiện đánh tiêu diệt chưa chín muồi; tạo điều kiện tập trung lực lượng, chớp thời cơ có lợi để phản công, xác định hướng chiến lược chính xác, cách đánh úp ban đêm táo bạo, bất ngờ, phát huy được sức mạnh của cả dân tộc, tận dụng được yếu tố bí mật, hạn chế được sở trường của kỵ binh địch là những kinh nghiệm lớn rút ra từ chiến thắng Đông Bộ Đầu lịch sử.

Bài học từ cuộc kháng chiến chống quân Mông Cổ lần thứ nhất cho thấy quân xâm lược chỉ duy trì được khả năng chiến đấu tốt nhất trong thời gian đầu. Càng về sau vì xa hậu phương, nguồn lương thực cạn kiệt, quân sĩ không quen khí hậu, bệnh tật phát triển, sức chiến đấu giảm sút nhanh chóng. Cùng với việc theo dõi sát sao tình hình địch, nhà Trần chủ trương không quyết chiến với địch khi chúng còn đang sung mãn để bảo toàn lực lượng. Tích cực chuẩn bị, tạo thế, tạo thời cơ, đánh một đòn quyết định, làm xoay chuyển tình thế chiến tranh. Đó là một quyết định đúng đắn và táo bạo. Đây cũng là kinh nghiệm quý báu trong cuộc chiến tranh vệ quốc của quân và dân ta.

Chiến thắng chống quân xâm lược Mông Cổ mùa xuân năm Nguyên Phong thứ 7 (năm 1258) không chỉ là niềm tự hào của quân dân Đại Việt thời Trần mà mãi mãi được ghi nhớ trong tâm thức các thế hệ người Việt Nam. Trong bài thơ “Xuân nhật yết Chiêu lăng" (Ngày xuân bái yết Chiêu lăng - Lăng vua Trần Thái Tông), vua Trần Nhân Tông (cháu đích tôn của vua Trần Thái Tông), vị vua anh hùng cứu nước, người đã lãnh đạo hai cuộc kháng chiến chống Mông - Nguyên vào năm 1285 và 1288 có những câu thơ rất hào sảng như sau:

Bạch đầu quân sĩ tại
Vãng vãng thuyết Nguyên Phong.
(Người lính già đầu bạc
Kể mãi chuyện Nguyên Phong).', 'TEXT', '2026-06-05 05:21:44.215072', '2026-06-05 05:21:44.215051', null, 'DRAFT'), ('7d7310de-0668-4eb3-9bd0-2c369ce81664', '687b57fe-865c-496a-83b3-f83690885dd1', 'e811b3e5-4b69-45a0-a1cd-f9f41526b3bb', 'CONTEXT', 'Chi tiết trận Chi Lăng', null, 'Trận Chi Lăng - Xương Giang (ngày 8-10 đến 3-11-1427), trận quyết chiến chiến lược diệt quân Minh (Trung Quốc) trên địa bàn từ Chi Lăng đến Xương Giang (113 kilômét) do nghĩa quân Lam Sơn tiến hành, kết thúc cuộc khởi nghĩa Lam Sơn và chiến tranh giải phóng chống Minh (1418-1427).

Trong lịch sử chống ngoại xâm oanh liệt của dân tộc ta, khởi nghĩa Lam Sơn do Lê Lợi lãnh đạo chống ách đô hộ của nhà Minh là một trong những cuộc chiến tranh giành độc lập anh dũng, hiển hách nhất của nhân dân ta. Sau hội thề Lũng Nhai (1416), ngày 7 tháng 2 năm 1418 Lê Lợi dựng cờ khởi nghĩa ở vùng núi Lam Sơn (Thanh Hóa), tự xưng Bình Định Vương, truyền hịch kêu gọi nhân dân cứu nước, được anh hùng hào kiệt khắp nơi lần lượt kéo về tụ nghĩa. Trong gần 10 năm ngoan cường chiến đấu, “nếm mật nằm gai" (1418-1427) nghĩa quân Lam Sơn đã để lại những sự kiện lịch sử chống ngoại xâm huy hoàng, tô thắm thêm truyền thống anh hùng và chủ nghĩa yêu nước của dân tộc ta. Trong những chiến công có ý nghĩa quyết định, kết thúc thắng lợi cuộc chiến tranh giải phóng ở thế kỷ XV phải nói đến là trận Chi Lăng - Xương Giang.

Từ cuối năm 1426, các cuộc tiến công của nghĩa quân Lam Sơn đã đẩy quân xâm lược nhà Minh vào tình trạng nguy ngập, chuyển hẳn sang thế phòng ngự bị động, chúng phải dồn sức vào việc củng cố các thành lũy, cố thủ trước vòng vây ngày càng xiết chặt của nghĩa quân. Đông Quan, căn cứ lớn nhất của quân Minh luôn bị quân ta bám sát; các cứ điểm ngoại vi lần lượt bị nghĩa quân triệt hạ khiến chúng không thể ra khỏi nội thành. Mặc dù “chí cùng lực tận” nhưng bọn tướng tá nhà Minh không chịu từ bỏ dã tâm chiếm đóng nước ta. Chủ tướng giặc là Thành Sơn hầu Vương Thông chủ động đưa thư xin được giảng hòa mong sớm được toàn quân trở về nước nhưng thực chất muốn có thêm thời gian thực thi mưu đồ cầu viện, tiếp tục chiến tranh. Chúng bí mật sai người mang thư bọc sáp đi lối tắt về xin viện binh.

Tin thất trận ở nước ta liên tiếp được truyền về triều đình nhà Minh. Mặc dù tình hình chính quốc không được yên ổn, Minh Tuyên Tông mới lên ngôi, đang phải đương đầu với nhiều khó khăn trong công việc nội trị nhưng triều đình nhà Minh vẫn quyết định điều tướng, tăng quân với hy vọng xoay chuyển lại cục diện chiến tranh và giữ nền đô hộ ở Giao Châu.

Cuối năm Bính Ngọ (tháng 1 năm 1427), nhà Minh điều động 15 vạn quân, 3 vạn ngựa chia làm hai đường sang cứu nguy cho Vương Thông ở thành Đông Quan:

* **Đạo quân thứ nhất** do An Viễn hầu Liễu Thăng giữ chức Tổng binh, mang ấn Chinh lỗ tướng quân chỉ huy 10 vạn quân, 2 vạn ngựa theo đường Quảng Tây tiến sang. Dưới trướng Liễu Thăng còn có Bảo Định bá Lương Minh giữ chức Phó tổng binh và Đô đốc Thôi Tụ. Đội quân này được huy động ở các Hộ vệ Vũ Xương, Thành Đô; Lưu vệ Trung Đô; các Đô ty Hồ Quảng, Chiết Giang, Hà Nam, Sơn Đông, Phúc Kiến, Giang Tây, Vân Nam, Tứ Xuyên và các hành Đô ty Tứ Xuyên. Binh bộ thượng thư Lý Khánh, Công bộ thượng thư Hoàng Phúc được điều động theo cánh quân này làm Tham tán quân sự.
* **Đạo quân thứ hai** do Kiềm quốc công Mộc Thạnh giữ chức Tổng binh mang ấn Chính nam tướng quân chỉ huy 5 vạn quân và 1 vạn ngựa từ Vân Nam tiến sang. Phụ tá cho Mộc Thạnh có các tướng Hưng An bá Từ Hanh giữ chức Tả phó tổng binh, Tân Ninh bá Đàm Trung giữ chức Hữu phó tổng binh.

Đây là lần viện binh lớn nhất của nhà Minh kể từ khi chúng xâm lược nước ta. Với một lực lượng đông đảo, dưới sự chỉ huy của những viên tướng dày dạn trận mạc, quân Minh tin sẽ giành được thắng lợi quân sự quyết định để tiếp tục thi hành chính sách cai trị, đô hộ của chúng.

Kế hoạch viện binh của nhà Minh đặt nghĩa quân Lam Sơn trước tình thế hết sức khó khăn, cùng một lúc phải đối phó với kẻ thù từ hai phía: quân tiếp viện và quân của Vương Thông đang ở thành Đông Quan và một số thành khác trong đất nước ta. Mặc dù lúc này lực lượng nghĩa quân đã mạnh hơn trước, đang ở thể bao vây kẻ địch nhưng chưa đủ sức tiêu diệt hẳn chúng, giờ đây lại phải đối phó thêm với hơn 15 vạn quân từ biên giới kéo sang, cán cân lực lượng không có lợi cho ta. Tình thế hết sức khẩn trương, kẻ thù đông và mạnh, sức ta có hạn. Đánh như thế nào? Đó là vấn đề lớn đặt ra đối với Bộ chỉ huy nghĩa quân. Không ít những kiến nghị đề xuất nhằm giải quyết câu hỏi: Đánh thành trước hay diệt viện trước?... một vấn đề có ý nghĩa chiến lược đối với sự nghiệp giải phóng dân tộc của nghĩa quân Lam Sơn. Có ý kiến cho rằng cần phải đánh gấp thành để tuyệt đường nội ứng của kẻ địch rồi dốc sức ra đánh viện binh. Lê Lợi với vai trò là tổng chỉ huy, lãnh tụ tối cao của cuộc khởi nghĩa đã quyết định “vây thành diệt viện" trên cơ sở phân tích tình hình chính xác và khoa học: “Đánh thành là hạ sách. Ta đánh thành bền vững hàng năm hàng tháng không hạ được, khi ấy quân ta sức mỏi chí nhụt, nếu viện binh giặc lại đến thì trước mặt, sau lưng đều bị tấn công, đó là con đường nguy hiểm, chi bằng nuôi sức quân, mài giũa tinh thần sắc bén để đợi viện binh của giặc. Viện binh giặc bị phá thì thành giặc nhất định phải hàng. Như thế là nhất cử lưỡng tiện, là mưu chước vẹn toàn" (Đại Việt sử ký toàn thư, Tập 2, Nxb. Khoa học Xã hội, H., 1998, tr.275).

Như vậy, nghĩa quân kiên quyết tiếp tục vây hãm giặc ở Đông Quan và các thành khác, đồng thời tập trung một lực lượng cần thiết chặn đánh viện binh. Chủ trương vây thành diệt viện được sự đồng lòng của tướng sĩ, thể hiện sự nhạy bén trong nghệ thuật chỉ đạo chiến tranh của những người lãnh đạo nghĩa quân Lam Sơn.

Viện binh của giặc chia làm hai đạo tiến sang theo hai đường khác nhau. Nếu cùng lúc tiến đánh cả hai, lực lượng nghĩa quân sẽ bị phân tán, do vậy Bộ chỉ huy nghĩa quân chủ trương sẽ tập trung binh lực đánh địch trên một hướng và dùng một phần lực lượng kiềm chế địch trên một hướng khác sau đó sẽ đánh tiêu diệt. Đạo quân Mộc Thạnh có 5 vạn. Đạo quân Liễu Thăng có hơn 10 vạn. Đánh quân Mộc Thạnh có phần dễ hơn nhưng nếu tập trung binh lực để đánh đạo quân ấy thì không đủ quân để kiềm chế đạo quân của Liễu Thăng, quân Liễu Thăng đông và mạnh dễ tiến vào Đông Quan bởi đường tiến quân từ Pha Lũy đến Đông Quan ngắn và dễ đi hơn đường từ Lê Hoa về Đông Quan. Nghĩa quân quyết định tập trung lực lượng tiêu diệt đạo quân Liễu Thăng trước và kiềm chế đạo quân Mộc Thạnh tại Lê Hoa. Các lãnh tụ nghĩa quân cũng nắm được tâm lý của Mộc Thạnh là một viên tướng già, có kinh nghiệm, đạo quân của y có nhiệm vụ phối hợp với đạo quân của Liễu Thăng nên Mộc Thạnh hành quân thận trọng, sẽ không vượt qua biên giới trước đạo quân chủ lực. “Mộc Thạnh tuổi đã già, từng trải việc đời đã nhiều... nhất định còn đợi xem quân Liễu Thăng thành bại ra sao chứ không nhẹ dạ tiến quân” (Đại Việt sử ký toàn thư, Sđd, tr.277). Ngay từ tháng 5 năm 1427 Lê Lợi đã cho tướng Trần Ban đem quân lên tu sửa cửa ải Lê Hoa, điều này chứng tỏ các lãnh tụ Lam Sơn đã có dự tính sẽ dùng công sự kiên cố và tận dụng địa hình hiểm trở vùng biên giới để chặn giữ một phần viện binh tại đây. Việc kiềm giữ đạo quân Mộc Thạnh không cho đạo quân này phối hợp với đạo quân của Liễu Thăng được giao cho các tướng Phạm Văn Xảo, Trịnh Khả, Nguyễn Chích, Lê Khuyển với nhiệm vụ “Đặt mai phục chờ đợi, chớ vội giao chiến” (Đại Việt sử ký toàn thư).

Đạo quân của Liễu Thăng được nghĩa quân Lam Sơn xác định là mục tiêu tiến công chiến lược trong kế hoạch đánh quân tiếp viện nhà Minh, đồng thời quyết tâm bẻ gãy đạo quân này khi chúng vừa đặt chân lên đất nước ta. Đây là một đạo quân binh hùng, tướng mạnh, phải đánh thế nào cho chắc thắng? Vấn đề này được Bộ chỉ huy Lam Sơn cân nhắc, tính toán cụ thể và đề ra một phương án tác chiến tận dụng tối đa điều kiện địa hình, tăng cường sức mạnh của ta, đánh thật mạnh ngay từ đầu không cho quân địch kịp trở tay. Ải Chi Lăng được chọn làm trận quyết chiến với phương châm: ta đặt phục binh ở nơi hiểm địa này để đập gãy đội quân tiên phong của địch. Các tướng Lê Sát, Lưu Nhân Chú, Lê Linh, Đinh Liệt, Lê Thụ được lệnh đem 10.000 quân tinh nhuệ và 5 voi chiến lên mai phục ở ải Chi Lăng, sau đó lại thêm 30.000 quân dưới sự chỉ huy của Lê Lý và Lê Văn An lên tiếp ứng. Hai cánh quân này có nhiệm vụ tiêu diệt một phần đạo quân chủ lực của Liễu Thăng.

Chi Lăng (nay thuộc xã Chi Lăng, huyện Chi Lăng, tỉnh Lạng Sơn) là cửa ải hiểm trở nhất nằm trên con đường từ Pha Lũy đến Đông Quan, cách Đông Quan 106km. Là một thung lũng nhỏ hình bầu dục, Chi Lăng có chiều dài khoảng 4km theo đường bắc nam, chỗ rộng nhất khoảng hơn 1km. Phía tây là dãy núi đá vôi dựng đứng (nay gọi là dãy núi Cai Kinh) có dòng sông Thương chảy sát chân núi dọc theo thung lũng. Phía đông là dãy núi Thái Hòa và Bảo Đài gồm nhiều ngọn núi trùng điệp. Trong lòng ải Chi Lăng có 5 ngọn núi nhỏ: Hàm Quỷ, Nà Nông, Nà Sản, Kỳ Lân, Mã Yên. Hai đầu bắc nam của thung lũng, mạch núi khép lại tạo thành hai cửa ải. Cửa ải phía bắc ở khoảng giữa núi Cai Kinh và núi Hàm Quỷ. Cửa ải phía nam ở khoảng giữa núi Cai Kinh và núi Bảo Đài còn gọi là ngõ Thề. Hai cửa ải này tạo nên thế hiểm của Chi Lăng. Chính quân Minh cũng phải thừa nhận đây là “nơi hiểm yếu đại quân ra vào”. Chi Lăng đã từng được chọn là điểm tiêu diệt kẻ thù xâm lược phương Bắc dưới thời Tiền Lê và thời nhà Trần. Thế kỷ XV, một lần nữa Chi Lăng lại được Bộ chỉ huy nghĩa quân Lam Sơn chọn làm nơi quyết chiến đầu tiên với đạo viện binh nhà Minh nhằm “bẻ mũi tiên phong của chúng”.

Như trên đã nói, hơn 1 vạn nghĩa quân tinh nhuệ cùng 100 ngựa, 5 voi chiến dưới sự chỉ huy của các tướng Lê Sát, Lưu Nhân Chú, Lê Linh, Đinh Liệt được lệnh đến Chi Lăng mai phục chờ giặc. Lực lượng nghĩa quân được bố trí từ cửa Hàm Quỷ đến ngõ Thề và cả phía trước con đường dẫn vào cửa ải. Quân ta giấu mình trong các ngọn núi, hang đá, lũy đất, quan sát cuộc hành binh của giặc, chờ thời cơ bẻ gãy mũi nhọn của đạo viện binh. Trên con đường từ ải Pha Lũy đến Chi Lăng, cứ cách quãng nghĩa quân lại dựng rào đắp lũy tạo thành những phòng tuyến cản đường tiến quân của quân xâm lược. Cửa ải Pha Lũy (Hữu Nghị Quan ngày nay) đang được đạo quân của tướng Trần Lựu và Lê Bôi trấn giữ. Khi viện binh nhà Minh kéo sang, đạo quân này được lệnh giặc đến thì “ra đánh nhưng giả cách không thắng”. Trần Lựu và đạo quân của ông phải chặn đánh giặc để vừa bảo vệ được mình vừa tiêu diệt một phần sinh lực của chúng nhưng quan trọng hơn cả là phải nhử được địch đi vào ải Chi Lăng, nơi đại quân ta đang mai phục.

Ngày 8 tháng 10 năm 1427, đạo viện binh của Liễu Thăng hùng hổ tiến vào nước ta qua cửa ải Pha Lũy. Theo kế hoạch đã định, quân của tướng Trần Lựu ra giao chiến vừa đánh vừa “thua” để nhử địch và kích động thêm tính chủ quan, khinh địch của Liễu Thăng, đồng thời từng bước dẫn dắt chúng tiến về phía Chi Lăng. Từ Pha Lũy, Trần Lựu cho quân lui về giữ Khâu Ôn (ở thành phố Lạng Sơn bây giờ). Quân giặc ồ ạt đuổi theo, nhanh chóng đánh chiếm được thành Khâu Ôn và tiếp tục tiến về Ải Lưu (ở địa đầu huyện Chi Lăng, tỉnh Lạng Sơn ngày nay).

Trên đường hành binh tiến vào nước ta, Liễu Thăng nhận được thư của Lê Lợi “xin” y hãy lui quân về biên giới để xem xét tình hình. Trong Thư gửi Liễu Thăng có đoạn viết: “Các ông là tướng lão luyện của thiên triều vâng mệnh đem quân ra cõi ngoài, công việc ngoài đô thành, mình tự chuyên là được rồi. Sao không xét rõ thời nghi, tùy tiện sắp việc, lui quân ra ngoài bờ cõi, sai một viên sứ giả mang một lá thư đến, xem hư thực rồi sau đó đem công việc nên làm ở trên đây xin mệnh lệnh của triều đình, may được chuẩn y, thì bọn các ông không phải khó nhọc lòng sức mà hưởng thành công. Nếu đình nghị không bằng lòng thì lúc đó tiến quân cũng chưa muộn gì. Nay, các ông không nghĩ đến việc ấy, đem quân cô độc đi sâu vào đất người cầu may nên được công việc. Tôi không cho việc làm ấy của các ông là phải. Vả lại, con ong cái bọ còn có nọc độc, huống chi người trong một nước, tôi há lại không có người nào là người có mưu kế dũng lược hay sao? Các ông chớ cho nước tôi là ít người mà coi thường. Đến lúc ấy thì lòng thành của nước tôi thờ nước lớn thực có phần thiếu, mà các ông hối lại sẽ không kịp nữa" (Nguyễn Trãi, Toàn tập, phần Quân trung từ mệnh tập, Nxb. Khoa học Xã hội, H., 1969, tr. 169).

Vốn là một viên tướng thăng quan tiến chức nhanh, đã tham gia trong đạo quân xâm lược nước ta của Trương Phụ (1406-1407) đánh bại cuộc kháng chiến của nhà Hồ nên Liễu Thăng rất kiêu ngạo và hiếu chiến. Giờ đây cầm đầu đạo quân lớn tiến vào nước ta không gặp sự kháng cự đáng kể nên Liễu Thăng càng tỏ ý coi thường quân ta, thư của nghĩa quân Lam Sơn gửi đến hắn không thèm để ý cứ nhất quyết tiến nhanh về cửa ải Chi Lăng. Trước thế hiểm của địa hình và hành động bất cẩn của Liễu Thăng các tướng giặc cùng đi lo ngại, thượng thư Lý Khánh đang ốm cũng cố gượng dậy khuyên Liễu Thăng nên cẩn thận, không được vội vàng. Đô sự Phan Nhân nhắc lại những thất bại của Vương Thông ở Cần Trạm, Ninh Kiều để Liễu Thăng đề phòng phục binh. Tất cả những lời khuyên can đều vô nghĩa đối với viên tướng ngạo mạn này. Liễu Thăng tiếp tục chỉ huy, đốc thúc quân sĩ tiến nhanh về phía trước.

Sau khi để quân giặc vượt qua Ải Lưu, đạo quân của nghĩa quân Lam Sơn do Trần Lựu chỉ huy rút về Chi Lăng phối hợp với lực lượng mai phục chuẩn bị chiến đấu. Từ Ải Lưu tới Chi Lăng quân ta cho dựng rào lũy vừa để nghi binh vừa để tạo chướng ngại vật khiến quân giặc hành binh khó khăn hơn. Khi quân Liễu Thăng chỉ cách Chi Lăng vài dặm. Trần Lựu cùng nghĩa quân từ Chi Lăng tiến ra nghênh đánh, vừa đánh vừa lui nhằm nhử chúng đi vào Chi Lăng không cho đi sang đường khác. Từ khi vượt biên giới vào nước ta, chỉ gặp sự kháng cự yếu ớt “vừa đánh vừa chạy” của đội quân Trần Lựu nên Liễu Thăng càng chủ quan, mất cảnh giác và lầm tưởng lực lượng ta mỏng, không sợ bị mai phục. Thấy quân ta lại thua chạy, Liễu Thăng thừa thắng cùng một vạn quân tiên phong đi trước mở đường tiến vào Chi Lăng.

Ngày 10 tháng 10 năm 1427 (tức ngày 20 tháng 9 năm Đinh Mùi), Liễu Thăng cùng quân tiên phong của hắn vào tới Chi Lăng, không thấy quân ta kháng cự, Liễu Thăng càng phấn khích, như thể làm gương cho tướng sĩ, chủ tướng của đạo quân 10 vạn này vội cùng hơn 100 kỵ binh băng lên phía trước, còn 1 vạn tiền quân tiến theo sau. Đội kỵ binh của Liễu Thăng vượt qua cửa ải phía bắc, tiến đến chân núi Mã Yên. Mã Yên là hòn núi đá cao khoảng 40 mét so với mặt đất, chu vi 300 mét, nằm ở phía nam cánh đồng Chi Lăng. Quanh chân núi là cánh đồng lầy lội, muốn đi tiếp phải qua cầu. Liễu Thăng định vượt qua cầu nhưng cầu hỏng (có thể là do quân ta bố trí trước). Đội kỵ binh của giặc tiến thoái lưỡng nan trước cánh đồng lầy, chúng đã hoàn toàn lọt vào trận địa mai phục của ta.

Đúng lúc này phục binh của ta từ bốn phía xông ra đánh tới tấp. Voi chiến xông thẳng vào đội hình quân địch khiến chúng rối loạn, nghĩa quân ào ạt xông lên dùng gươm, lao, mũi tên phóng tới tấp vào quân giặc, dồn chúng xuống cánh đồng lầy. Đội kỵ binh của giặc đang hung hăng tiến quân mở đường giờ đây mất sức chiến đấu hoàn toàn. Tổng binh Liễu Thăng cố tìm cách thoát thân nhưng không kịp. Y bị trúng lao tử trận ngay tại sườn núi Mã Yên. Toàn bộ đội kỵ binh gồm hơn 100 tên bị tiêu diệt.

Khi đội kỵ binh tiên phong giặc bị sa lầy ở Mã Yên, cũng là lúc đạo tiền quân địch lọt vào trận địa phục kích của ta. Từ các vị trí mai phục trong lòng ải Chi Lăng và hai bên sườn núi, quân ta nhất loạt xông ra, tên thuốc độc, đạn đá, phi tiêu, mũi lao tới tấp phóng vào quân giặc. Bị đánh bất ngờ, lại mất chủ tướng, đạo quân địch hoang mang, rối loạn. Quân ta dũng mãnh xông tới, chia cắt quân giặc ra từng mảng để tiêu diệt. Dân binh địa phương hiệp đồng và tích cực sát cánh cùng quân chủ lực chặn đánh giặc khiến chúng càng thêm hoảng hốt. Đặc biệt, Đội tuần đinh tuần tráng của Lý Huề ở Đồng Mỏ đã đánh giặc rất dũng cảm và lập nhiều chiến công. Trận đánh diễn ra dữ dội cho đến chiều tối. Quân dân ta đã hoàn thành xuất sắc nhiệm vụ “bẻ gãy mũi nhọn" của đạo viện binh chủ lực nhà Minh, tiêu diệt hơn 1 vạn tên, thu và tiêu hủy nhiều khí giới của địch, đặc biệt ta còn thu được những sắc thư, phù tín, ấn chương, cờ hiệu, sổ quân của chính tổng binh Liễu Thăng và bắt một số tướng Minh.

Chi Lăng, một chiến công chói lọi của nghĩa quân Lam Sơn, tại đây quân ta đã giết chết tổng binh Liễu Thăng và đập tan bộ phận tiên phong của đạo viện binh chủ lực của nhà Minh. Đây là chiến thắng mở đầu quan trọng, tạo đà mạnh mẽ cho hàng loạt thắng lợi tiếp sau theo kế hoạch chủ động của Bộ chỉ huy nghĩa quân. Chiến thắng Chi Lăng còn là đòn chí mạng đối với quân tiếp viện nhà Minh: chủ tướng bị giết tại trận, một phần sinh lực tinh nhuệ bị tiêu diệt khiến cho kế hoạch tác chiến của chúng bị đảo lộn và gây một tình trạng rối loạn, hoang mang cao độ trong hàng ngũ quân địch, tinh thần và thế tiến công của đạo viện binh bị giảm sút đáng kể.

Với chiến thắng Chi Lăng, quân đội Lam Sơn dưới sự chỉ huy của các tướng Lê Sát, Lê Linh, Lưu Nhân Chú, Đinh Liệt, Trần Lựu... đã hoàn thành xuất sắc nhiệm vụ đập gãy đạo tiên phong của quân tiếp viện nhà Minh. Chiến công này là hình ảnh tiêu biểu của tinh thần quả cảm và nghệ thuật quân sự điêu luyện của nghĩa quân Lam Sơn.

Sau khi Liễu Thăng bị giết, phó tổng binh là Bảo Định bá Lương Minh lên thay, cầm quyền chủ soái. Nguyễn Trãi lại viết thư cho Lương Minh, vạch rõ thế thất bại không tránh khỏi của quân địch: “Nay các ông đem quân đi sâu vào cõi đất người chính là bị hãm vào thế trong miệng cọp, muốn tiến không được, muốn lui không hay. Còn ta thì nhân thế chẻ tre, sau khi chẻ được mấy đốt, cứ lọng lưỡi dao mà chẻ đi, thực không khó gì”. Từ đó Nguyễn Trãi khuyên Lương Minh: “Xin các ông lui ngay quân ra ngoài bờ cõi, ta tự dẹp mở lối về, cho các ông được thung dung đem quân về... Như thế thì các ông có thể ngồi hưởng thành công mà Nam, Bắc từ nay vô sự, há chẳng hay ư? Nếu có thể thôi được mà không thôi, là do các ông không biết dập tắt lửa đi để cho nó tự cháy lên, không phải là tội của ta vậy” (Nguyễn Trãi, Toàn tập, Sđd, tr.170 - 171). Nhưng còn 9 vạn quân trong tay, Lương Minh cùng binh bộ thượng thư Lý Khánh, đô đốc Thôi Tụ vẫn còn ngoan cố, tiếp tục thực hiện mưu đồ xâm lược. Lương Minh cố gắng chấn chỉnh lại đội ngũ và ra lệnh tiến quân.

Phía dưới Chi Lăng, các tướng Lam Sơn là Nguyễn Đình Lý, Lê Văn An đã đem 3 vạn quân lên bày sẵn một trận địa mai phục thứ hai tại Cần Trạm (huyện Lạng Giang, tỉnh Bắc Giang ngày nay) để đợi giặc. Một vạn quân của Lê Sát, Lưu Nhân Chú, sau chiến thắng Chi Lăng, vẫn bám sát quân địch, sẵn sàng công kích vào phía sau lưng chúng.

Cần Trạm (Lạng Giang, Bắc Giang) ở vào cuối dãy núi Bảo Đài, nơi tiếp giáp giữa vùng thượng lưu và trung du. Đây là một dịch trạm trên con đường Đông Quan - Pha Lũy. Sau khi chiếm nước ta, quân Minh lập nên ở đây một đồn trại để bảo vệ dịch trạm và án ngữ con đường giao thông huyết mạch nối liền với Trung Quốc. Di tích thành Cần Trạm hiện nay vẫn còn.

Ngày 15 tháng 10 năm 1427 (25 tháng 9 năm Đinh Mùi) quân Minh lọt vào trận địa mai phục ở Cần Trạm. Ba vạn phục binh của ta do các tướng Nguyễn Đình Lý, Lê Văn An chỉ huy, từ nhiều ngả xông lên đánh tạt ngang vào đội hình hành quân của địch. Cùng lúc đó, hơn một vạn quân của Lê Sát, Lưu Nhân Chú... đánh mạnh vào hậu quân địch.

Trận đánh xảy ra trên một quãng đường dài khoảng 5km, dấu vết còn bảo tồn đến nay là những tên đất như Bãi Chiến ở đông bắc thành Cẩn Trạm, Nghè Trận ở gần Kép... Phó tổng binh, Bảo Định bá Lương Minh mới lên nắm quyền chỉ huy được 5 ngày, lại bị trúng lao chết ngay tại trận. Khoảng hơn một vạn quân địch bị tiêu diệt. Quân ta thu được rất nhiều lương thực, vũ khí...

Sau trận Cần Trạm, quân ta chủ động thu quân và nhanh chóng vận động theo đường tắt về phía Nam để tiếp tục trận địa mai phục, tổ chức những trận đánh mới.

Quân địch bị bồi thêm một đòn thất bại nặng nề. Lực lượng bị tiêu diệt chưa thật nhiều nhưng thế của địch bắt đầu suy sụp, chuyển sang chống đỡ một cách bị động. Đô đốc Thôi Tụ giữ chức hữu tham tướng, lên nắm quyền chỉ huy. Thôi Tụ cùng với thượng thư bộ binh Lý Khánh và thượng thư bộ công Hoàng Phúc, thu thập quân lính, cố gượng tiến về thành Xương Giang mà chúng tưởng đang ở trong tay quân Minh.

Phía nam Cần Trạm là địa hình trung du, đồi núi thoai thoải và thưa dần. Đường hành quân của địch xuyên qua các thung lũng hẹp và dài, hai bên là đồi thấp và rừng thưa. Quân ta lợi dụng địa thế và đội hình hành quân kéo dài của 7 - 8 vạn quân địch, tổ chức những trận đánh vào cạnh sườn, nhất là vào đội quân lương đi sau của địch. Đó là lối đánh “dùng kỳ binh chặn đường, cắt ngang lương đạo" (Bình Ngô đại cáo).

Ngày 18 tháng 10 năm 1427 (28 tháng 9 năm Đinh Mùi), quân ta đánh một trận lớn ở Phố Cát (gần Phố Tráng, Lạng Giang, Bắc Giang). Đồi Mả Ngô còn như lưu lại dấu tích của trận đánh này.

Những trận đánh liên tiếp như vậy làm cho quân địch bị tiêu diệt thêm khoảng một vạn quân, mất thêm nhiều quân lương, vũ khí. Quân ta “bắt được lừa, ngựa, trâu, quân nhu, khí giới không biết bao nhiêu mà kể” (Đại Việt sử ký toàn thư).

Sau trận Phố Cát, thượng thư bộ binh giữ chức tham tán quân vụ là Lý Khánh, phần vì ốm nặng, phần vì lo sợ và tuyệt vọng đã “kế cùng phải thắt cổ”, lại thêm một chủ tướng nữa của giặc bị chết.

Chỉ sau 10 ngày (từ ngày 8 đến 18 tháng 10 năm 1427) đặt chân lên đất nước ta, đạo viện binh chủ yếu của nhà Minh đã bị những tổn thất hết sức nặng nề. Nguyễn Trãi đã mô tả thế trận và những thắng lợi của ta trong Bình Ngô đại cáo như sau:

> "Ta đã chọn phục binh giữ hiểm, đập gãy tiên phong,
> Sau lại dùng kỳ binh chặn đường, cắt ngang lương đạo,
> Ngày mười tám, Liễu Thăng bị đánh, Chi Lăng trúng kế.
> Ngày hai mươi, Liễu Thăng bị bại, Mã Yên phơi thây,
> Ngày hai mươi lăm, bá tước Lương Minh trận hãm phải bỏ mình,
> Ngày hai mươi tám, thượng thư Lý Khánh kế cùng phải thắt cổ".

Quân địch đã bị tiêu diệt khoảng 3 vạn quân, các tướng chủ chốt lần lượt bị chết. Số quân còn khoảng 7 vạn, nhưng thế và lực đã hoàn toàn suy sụp. Từ tướng đến quân đều hoang mang, tuyệt vọng.

Tuy vậy, với số quân còn lại khoảng hơn 7 vạn đó, bọn tướng tá nhà Minh vẫn gắng tiếp tục kéo quân tiến sâu vào nội địa nước ta. Đô đốc Thôi Tụ, thượng thư Hoàng Phúc, hai tướng lĩnh cao cấp nhất còn lại của đạo quân này cùng toàn quân tập trung sức lực đánh mở đường cố tiến quân xuống Xương Giang (ở thành phố Bắc Giang ngày nay) hy vọng có thể phối hợp với quân thành Xương Giang, một cứ điểm quân sự mạnh và quan trọng của chúng nằm trên đường tiến quân về Đông Quan, xoay chuyển lại tình thế, lập lại nền đô hộ ở nước ta. Quân giặc không ngờ rằng, từ cuối tháng 9 năm 1427 thành Xương Giang đã bị nghĩa quân Lam Sơn đánh chiếm và giờ đây đã trở thành một pháo đài kiên cố của quân ta chặn ngang đường tiến quân của chúng và chia cắt hoàn toàn, tách biệt hẳn đạo quân viện binh của địch với Đông Quan. Tại đây một thế trận bao vây của nghĩa quân đã được chuẩn bị sẵn chờ giặc.

Thoát chết ở Cần Trạm, Phố Cát, cố gắng hết sức bọn Thôi Tụ, Hoàng Phúc cùng đạo quân mới tới được gần Xương Giang nhưng lại được tin thành đã thuộc về nghĩa quân Lam Sơn. Nguy khốn lại càng nguy khốn, tiến thoái lưỡng nan, quân giặc lúng túng và hoang mang. Nếu tiến tiếp sẽ bị quân ta chặn đánh phía trước. Lui quân cũng không xong với các đạo quân của các tướng Lê Sát, Lê Văn An, Lê Lý (Nguyễn Đình Lý)... vẫn bám sát đằng sau. Thoát khỏi vòng vây thật khó khăn. Cuối cùng bọn Thôi Tụ, Hoàng Phúc “không còn mưu kế gì khác đành phải đắp lũy ngoài đồng để tự vệ” (Đại Việt sử ký toàn thư, Tập 2, Nxb. Khoa học Xã hội, H., 1998, tr.276). Chúng cho quân lui về đóng trên cánh đồng Xương Giang, cách thành 3 kilômét về phía Bắc với hy vọng đồng bọn ở Đông Quan, Chí Linh và đạo quân Mộc Thạnh sẽ tới ứng cứu.

Nơi quân Minh đóng quân là một vùng đồng ruộng, xung quanh được bao bọc bởi các dãy đồi thấp và dòng sông Thương (đoạn sông Thương này còn có tên là sông Xương Giang). Đóng quân giữa một vùng đồng bằng trống trải, khó lợi dụng địa hình để tổ chức phòng vệ cầm cự, quân Minh phải đuổi dân, phá làng mạc, chặt cây cối dựng rào, đắp lũy, đào công sự để tạm thời phòng vệ và lo đối phó với những cuộc tiến công sắp tới của quân ta. Tuy bị truy kích liên tiếp trên đường tiến quân và không vào được thành Xương Giang nhưng trong tay vẫn còn một lực lượng đáng kể nên bọn Thôi Tụ, Hoàng Phúc vẫn kiên quyết cố thủ chống lại nghĩa quân Lam Sơn và hy vọng thoát khỏi vòng vây.

Về phía nghĩa quân Lam Sơn, sau những chiến thắng liên tiếp ở Chi Lăng, Cần Trạm, Phố Cát giờ đây đã buộc đạo viện binh chủ lực của nhà Minh phải giam chân tại vùng Xương Giang đã cổ vũ mạnh mẽ tinh thần chiến đấu của nghĩa binh. Khí thế của nghĩa quân lên rất cao, muốn tiến đánh ngay quân địch. Bộ chỉ huy nghĩa quân nhận thấy lực lượng địch vẫn còn đông nên quyết định chưa vội tiến công tiêu diệt ngay mà tiếp tục điều thêm quân thủy bộ tới Xương Giang tiến hành vây hãm và dụ hàng nhằm làm cho đạo quân này ngày càng suy yếu về lực lượng, khốn quẫn về lương ăn, dành thời gian và lực lượng thực hiện kế hoạch tiêu diệt đạo viện binh thứ hai do Mộc Thạnh chỉ huy tiến sang theo đường Vân Nam, không cho chúng tiến sâu vào lãnh thổ nước ta. Các đạo quân ở chiến trường Xương Giang được lệnh khép chặt vòng vây không cho quân địch trốn thoát. Toàn bộ đạo quân của Thôi Tụ, Hoàng Phúc nằm trong thế trận bao vây của nghĩa quân. Quân thủy bộ của ta án ngữ mọi phía. Quân ta “lập hàng rào ở bên tả sông Xương Giang" (Đại Việt sử ký toàn thư, Sđd, tr.276). Một bộ phận quân thủy phối hợp với quân bộ án ngữ phía tây. Mặt khác hai đạo quân của Lê Sát, Lưu Nhân Chú và Lê Lý, Lê Văn An sau trận Phố Cát tiến xuống trấn giữ. Phía nam, thành Xương Giang đã thuộc về quân ta và thành Thị Cầu, cách thành Xương Giang 20 kilômét do đạo quân của Trần Lựu án ngữ. Thế bao vây nhiều lớp như vậy đã bịt kín đường về Đông Quan. Nghĩa quân Lam Sơn còn khóa chặt đường về Quảng Tây và làm chủ con đường đến thành Chí Linh. Nằm trong vòng vây khép kín, vững chắc và dày đặc của quân thủy bộ ta, quân địch dù đông cũng khó thoát.

Tuy vậy, để đề phòng sự liều lĩnh phá vây của kẻ địch trong thế khốn cùng, đồng thời nhằm tránh một cuộc giao chiến lớn, tiêu hao sinh lực của cả hai bên, thay mặt Bộ chỉ huy nghĩa quân, Nguyễn Trãi nhiều lần viết thư khuyên Thôi Tụ, Hoàng Phúc nên hòa giải lui quân. Vừa khuyên giải, đồng thời Nguyễn Trãi cũng cảnh báo quân giặc: “Nếu các ông còn dùng dằng lâu ngày, chứa lòng nghi ngờ, làm hỏng mưu kế; tôi sợ rằng các ông sẽ chết uổng vùi xương trong bụng cá ở Xương Giang (sông Thương) sống có ích gì đâu..." (Nguyễn Trãi, Toàn tập, Nxb. Khoa học Xã hội, H., 1976, tr. 164).

Nghĩa quân Lam Sơn kiên trì dụ hàng, nhưng ỷ thế quân đông, bọn giặc vẫn rất ngoan cố, không tiến, không lui, chẳng cầu hòa. Chúng hy vọng kéo dài thời gian cầm cự chờ đồng bọn ở Đông Quan lên ứng cứu hoặc đạo quân Mộc Thạnh tiến sang tiếp sức. Đã có lần, chúng “giả xin hòa nhưng ngầm muốn chạy vào Chí Linh" (Đại Việt sử ký toàn thư, Sđd, tr.44). Xin hòa của giặc không phải là để được về nước mà chúng muốn kéo vào thành Chí Linh (một thành ở gần thành Xương Giang) để tập trung lực lượng, tiếp tục chiến tranh. Để đập tan mưu đồ của Thôi Tụ, Hoàng Phúc, quân ta xiết chặt vòng vây hơn nữa và gấp rút hạ thành Chí Linh.

Sau một thời gian bị vây hãm, bọn địch đã lâm vào thế cùng sức hết, không còn lương thực để ăn, ốm đau bệnh tật khiến quân số bị tiêu hao đáng kể. Một lần nữa Nguyễn Trãi viết thư dụ giặc đầu hàng và chỉ cho chúng đừng hy vọng gì ở sự cứu viện từ Đông Quan và đạo quân Mộc Thạnh. Nghĩa quân cũng đưa ra thời hạn rút quân cho giặc là 3 ngày. Mặc dù con đường sống đã được mở nhưng bọn giặc vẫn ngoan cố không chịu trả lời. Thời điểm tiêu diệt kẻ thù đã đến. Các tướng Lê Khôi, Nguyễn Xí, Phạm Vấn, Trương Lôi được lệnh đem ba nghìn quân thiết đột và 4 voi chiến lên tăng cường cho Xương Giang.

Ngày 3 tháng 11 năm 1427 (tức ngày 15 tháng 10 năm Đinh Mùi), các đạo nghĩa quân Lam Sơn ở Xương Giang được lệnh đồng loạt tiến công. Từ bốn phía, mấy vạn quân gồm bộ binh, kỵ binh, tượng binh ồ ạt xông vào trận địa. Các mũi tiến công nhất loạt đánh quyết liệt vào các hệ thống phòng ngự và đột phá vào khu trung tâm của giặc. Quân ta vừa tiến đánh vừa kêu gọi quân địch đầu hàng khiến đội ngũ của chúng rối loạn, binh tướng mất hết tinh thần chiến đấu, không thể chống cự nổi.

> "Một tiếng trống, sạch sanh kình ngạc,
> Hai tiếng trống, tan tác chim muông.
> Tan tổ kiến xoi, bảm nơi đê vỡ,
> Nổi gió mạnh, trút sạch lá khô".
> (Bình Ngô đại cáo)

Số phận của quân địch được định đoạt nhanh chóng:

> "Đô đốc Thôi Tụ, quỳ gối chịu tội,
> Thượng thư Hoàng Phúc trói tay nộp mình".

Sau vài giờ chiến đấu quyết liệt, toàn bộ quân giặc ở Xương Giang bị tiêu diệt. Hơn 5 vạn tên địch bị giết tại trận, chủ tướng Thôi Tụ, Hoàng Phúc và toàn bộ tướng chỉ huy lớn nhỏ hơn 300 tên cùng hơn một vạn quân bị bắt sống, một số ít quân giặc chạy trốn khỏi trận địa nhưng sau đó vài ngày cũng bị dân ta bắt được không sót tên nào. Trong số hơn 7 vạn tên giặc, chỉ duy nhất có tên chủ sự Phan Nguyên Đại trốn thoát về nước. Nghĩa quân thu toàn bộ chiến lợi phẩm bao gồm ngựa, chiến khí, vàng bạc, là lụa, đoạn vóc “từng đống, từng hòm chứa chất như núi, không thể kể xiết" (Nguyễn Trãi, Toàn tập, phần Lam Sơn thực lục, Sđd, tr.54).

Xương Giang là trận đánh lớn cuối cùng tiêu diệt nhiều sinh lực địch nhất của nghĩa quân Lam Sơn trong hơn 10 năm tiến hành chiến tranh. Cùng với Chi Lăng, Cần Trạm, Phố Cát, chiến thắng Xương Giang đã tiêu diệt toàn bộ đạo viện binh chủ lực của nhà Minh. Với thắng lợi này, quân dân ta đã làm tiêu tan mọi cố gắng của quân xâm lược nhà Minh nhằm duy trì ách cai trị đối với nhân dân ta. Đạo quân lớn nhất của đoàn quân cứu viện bị tiêu diệt hoàn toàn, hy vọng của Vương Thông và số quân địch còn lại trên đất nước ta bị tiêu tan, tinh thần chiến đấu của chúng bị suy sụp. Đây là chiến thắng oanh liệt mở ra thời kỳ giành thắng lợi hoàn toàn cuộc chiến tranh giải phóng dân tộc của quân dân ta ở thế kỷ XV.

Chiến thắng Chi Lăng - Xương Giang là kết quả của tinh thần liên tục tiến công kẻ thù của nghĩa quân Lam Sơn. Kể từ khi đạo viện binh của Liễu Thăng xâm phạm bờ cõi nước ta (8-10-1427) chúng liên tục bị đánh tới tấp: khi trước mặt, lúc sau lưng, khi bị đánh cạnh sườn, lúc bị truy kích bao vây khiến quân địch tan tác “như lá rụng trong cơn gió mạnh”. Thoát chết ở Chi Lăng, Cần Trạm, Phố Cát, số quân địch còn lại về đến Xương Giang với hy vọng hội quân nhưng không ngờ lại rơi vào vòng vây ngày càng khép chặt và phải lâm vào tình trạng khốn quẫn: đói khát, rét mướt, tinh thần thể lực sa sút. Cuộc tiến công không ngừng của nghĩa quân Lam Sơn khiến kẻ địch luôn bị tiêu hao về lực lượng, không có thời gian phục hồi; căng thẳng về tinh thần, chúng luôn trong trạng thái lo sợ, hoảng hốt. Do bị nghĩa quân Lam Sơn tiến công liên tục, đã đẩy số quân còn lại của đạo viện binh giặc khi về đến Xương Giang đã quá mệt mỏi. Khi buộc phải đóng quân trên cánh đồng Xương Giang, một địa hình trống trải, càng làm cho quân Minh hoang mang rệu rã, không còn tinh thần chiến đấu, do đó nhanh chóng tan rã trước cuộc tổng công kích của quân ta.

Về đạo viện binh thứ hai của quân Minh do Kiềm Quốc công Mộc Thạnh giữ chức Tổng binh mang ấn Chinh nam tướng quân chỉ huy 5 vạn quân và 1 vạn ngựa từ Vân Nam tiến sang, trong lúc đạo viện binh thứ nhất từ Quảng Tây tiến xuống đang bị nghĩa quân Lam Sơn đánh tơi bời ở Chi Lăng, Cần Trạm, Phố Cát và bị vây hãm ở Xương Giang, thì đạo viện binh thứ hai này vẫn án binh bất động ở gần biên giới. Vốn là một tướng xâm lược lão luyện nên Mộc Thạnh rất thận trọng, không vội tiến xuống mà cho đóng quân lại nghe tin tức của Liễu Thăng.

Tại ải Lê Hoa, quân ta do các tướng Phạm Văn Xảo, Trịnh Khả, Nguyễn Chích, Lê Trung chỉ huy, chiếm lĩnh những nơi trọng yếu, bố trí mai phục để làm nhiệm vụ ngăn chặn địch và sẵn sàng tiến công khi thời cơ đến. Biết rõ thái độ dè dặt của Mộc Thạnh, Nguyễn Trãi gửi thư vạch rõ những thất bại, tổn hại nặng nề của quân Minh ở nước ta và dùng lời lẽ ôn tồn khuyên Mộc Thạnh xin triều đình bãi binh.

Sau khi đã giam chặt số quân của Thôi Tụ, Hoàng Phúc ở Xương Giang, Bộ chỉ huy nghĩa quân Lam Sơn chủ trương phải kịp thời tổ chức tiến công đánh tan đạo quân Mộc Thạnh.

Lê Lợi sai một tên chỉ huy, ba tên thiên hộ bắt được trong đạo quân Liễu Thăng, mang sắc thư, ấn tín của Liễu Thăng cùng một bức thư của Nguyễn Trãi, chuyển cho Mộc Thạnh. Trong thư, Nguyễn Trãi chủ yếu báo tin cho Mộc Thạnh biết sự thất bại thảm hại của Liễu Thăng vì “mạo hiểm tiến quân vào sâu, chuyên việc chém giết, định diệt hết không để sót người nào” nên “bị chết tại trận tiền, không biết lẫn lộn vào đâu” và “Bảo Định bá, Thôi đô đốc, Lý thượng thư cũng nối nhau chết nốt” (Nguyễn Trãi, Toàn tập), (thực ra lúc đó đô đốc Thôi Tụ chưa bị chết).

Đòn tiến công “đánh vào lòng người” đã có tác dụng lớn. Đọc thư, lại tận mắt nhìn thấy những chứng tích thất bại của Liễu Thăng, tướng Mộc Thạnh vô cùng khiếp sợ. Đang đêm, Mộc Thạnh vội vàng đem quân tháo chạy. Quân ta đã chuẩn bị sẵn sàng lập tức tung quân ra đuổi đánh. Mộc Thạnh dù tháo chạy, nhưng cũng phải bị đánh cho tan nát thì mới đè bẹp được ý chí xâm lược của quân thù.

Quân ta thắng lớn ở Lãnh Câu và Đan Xá (Hà Giang), giết chết hơn 1 vạn, bắt sống hơn 1.000 quân địch và thu được hơn 1.000 ngựa cùng rất nhiều vũ khí, lương thực và của cải.

Nguyễn Trãi đã mô tả chiến thắng này trong Bình Ngô đại cáo:

> "Bị quân ta chẹn ở Lê Hoa,
> quân Vân Nam kinh sợ mà trước đã vỡ mật.
> Nghe quân Thăng thua ở Cần Trạm,
> quân Mộc Thạnh xéo lên nhau chạy để thoát thân.
> Lãnh Câu máu chảy thắm dòng, nước sông ấm ức.
> Đan Xả thây chồng thành núi, cỏ nội thẫm hồng".

Trong khoảng không đầy một tháng, từ ngày 8 tháng 10 đến ngày 3 tháng 11 năm 1427, toàn bộ hai đạo viện binh của Liễu Thăng, Mộc Thạnh đã bị tiêu diệt và đánh tan.

Nhằm khủng bố tinh thần quân Minh đang cố thủ ở thành Đông Quan, Lê Lợi sai Thông sự Đặng Hiếu Lộc dẫn các tướng giặc bị nghĩa quân bắt là Thôi Tụ, Hoàng Phúc cùng ấn tín của Liễu Thăng đến báo cho Vương Thông biết. Vương Thông vô cùng hoang mang lo sợ và biết không còn hy vọng gì ở quân cứu viện. Thế đã cùng, lực đã kiệt, lại đang bị bao vây khốn đốn, Vương Thông xin giảng hòa và đã được Lê Lợi chấp thuận. Tuy nhiên, Vương Thông một mặt phái sứ giả đi cầu hòa, mặt khác tập trung toàn bộ lực lượng còn lại trong thành Đông Quan mở một cuộc tập kích lớn hòng xoay chuyển tình thế. Nhưng khi Vương Thông mang quân ra khỏi thành liền bị phục binh của nghĩa quân đánh cho tan tác. Vương Thông ngã ngựa suýt bị bắt sống, từ đó không dám ra khỏi thành.

Tháng 12 năm 1427, Lê Lợi phái tướng Nguyễn Lôi đem thư dụ hàng được binh tướng hai thành Tây Đô và Cổ Lộng. Cùng với việc tăng cường lực lượng vây hãm thành Đông Quan, Lê Lợi giao cho Nguyễn Trãi soạn thảo thư từ khuyên nhủ Vương Thông đầu hàng. Để tỏ ra thiện chí muốn giảng hòa, Lê Lợi cho con là Quận vương Tư Tề đi cùng với Lưu Nhân Chú vào thành Đông Quan làm con tin. Vương Thông cũng cho các tướng là Sơn Thọ, Mã Kỳ đến ở dinh Bồ Đề.

Ngày 10 tháng 12 năm 1427 (22 tháng 11 năm Đinh Mùi), Lê Lợi dẫn các tướng lĩnh đến cùng với Vương Thông và các tướng Minh:

> "Lũ tổng binh Vương Thông, tham chinh Mã Anh, được
> cấp cho mấy nghìn ngựa, đã về nước còn ngực đập chân run.
> Chúng sợ chết thèm sống mà thực muốn cầu hòa,
> Ta lấy toàn quân làm cốt cho dân được yên nghỉ.
> Chẳng những mưu kế kỳ diệu.
> Cũng là chưa thấy xưa nay".
> (Bình Ngô đại cáo)

Sau 20 năm sống rên xiết dưới ách thống trị tàn bạo của quân Minh, đến đây đất nước ta đã sạch bóng quân xâm lược. Nguyễn Trãi đã thay mặt Lê Lợi soạn thảo văn bản Bình Ngô đại cáo, ban bố khắp trong nước khẳng định nền độc lập của quốc gia Đại Việt.

---

Trận Chi Lăng - Xương Giang đã để lại những kinh nghiệm quý báu về nghệ thuật quân sự:

**Thứ nhất,** đó là tinh thần tích cực giành thế chủ động về chiến lược và chiến thuật của Bộ chỉ huy nghĩa quân Lam Sơn. Sự khốn đốn có nguy cơ bị tiêu diệt của số quân đang có mặt trên đất nước ta buộc nhà Minh phải đưa quân sang cứu viện. Kế hoạch viện binh của giặc đặt nghĩa quân Lam Sơn trước một tình thế mới: đánh thành trước hay diệt viện trước. Sau khi cân nhắc kỹ lưỡng, Bộ chỉ huy nghĩa quân đã kiên quyết, kịp thời thay đổi chỉ đạo chiến lược; không đánh thành (mặc dù ta đang có nhiều ưu thế) mà tập trung “vây thành diệt viện”. Viện binh là niềm hy vọng của quân giặc trong thành, nếu quân tiếp viện bị tiêu diệt thì giặc trong thành thế tất phải ra hàng, như các lãnh tụ nghĩa quân đã nhận định. Như vậy làm một mà được hai. Từ đó nghĩa quân tích cực chủ động chuẩn bị đánh viện binh ngay từ khi chúng mới vào biên giới. Việc chọn hướng, bố trí lực lượng, định đối tượng tác chiến cũng được giải quyết ngay từ khi viện binh địch chưa tới nơi. Với một lực lượng nghĩa quân có hạn vừa phải tiến hành vây hãm số quân Minh trong 4 thành, nếu cùng lúc đánh cả hai đạo viện binh thì lực lượng của ta sẽ rất mỏng, nên ngay từ đầu Bộ chỉ huy nghĩa quân đã vạch ra kế hoạch tác chiến vừa kiềm chế, chia cắt quân địch, vừa tập trung lực lượng đánh vào một hướng chủ yếu để tiêu hao sinh lực địch. Nghĩa quân đã tập trung binh lực tiến công tiêu diệt đạo viện binh chủ lực do Liễu Thăng cầm đầu. Đây là một đội quân đông, có nhiều tướng giỏi giữ vai trò chủ yếu trong đội hình chiến lược của địch. Nếu đạo quân này bị tiêu diệt sẽ làm rung chuyển và sụp đổ toàn bộ thế trận của địch. Đối với đạo quân của Mộc Thạnh, chỉ dành một lực lượng vừa phải để ngăn chặn không cho chúng tiến vào Đông Quan liên lạc với Vương Thông, đồng thời vẫn dành một bộ phận vây hãm các thành không cho chúng thoát ra ngoài. Địa bàn tác chiến chính được lựa chọn là vùng rừng núi Lạng Sơn, Lạng Giang trên con đường mà viện binh địch sẽ đi qua, trong đó ải Chi Lăng là nơi quân ta mai phục dàn sẵn thế trận đợi giặc. Đây là địa bàn hiểm trở nằm sâu trong biên giới, có nhiều điểu kiện thuận lợi để quân ta mai phục chặn đánh địch. Kế hoạch tác chiến cũng được vạch ra cụ thể: ta không đem đại quân chủ lực ra quyết chiến với địch ngay khi chúng vừa vào biên giới, mở đầu chỉ là những trận đánh nhử địch của đạo quân do tướng Trần Lựu chỉ huy với kế hoạch vừa đánh vừa lui khiến quân địch vừa phải hành quân vừa tác chiến trên chặng đường rừng núi hơn trăm dặm. Khi đến Chi Lăng sức chiến đấu của chúng không còn được như lúc ban đầu, tới lúc đó ta đem quân “nhân” đánh quân “mệt nhọc”, chia cắt đội hình khiến chúng đông quân mà không mạnh, phải bị động đối phó với ta, đánh theo lối đánh của ta. Kỵ binh, một thế mạnh của giặc không phát huy được sở trường... Việc giành và giữ được quyền chủ động linh hoạt trong chỉ đạo chiến lược cũng như chiến thuật của Bộ chỉ huy nghĩa quân Lam Sơn là điều kiện tiên quyết làm nên chiến thắng.

**Thứ hai,** Chi Lăng là một trong những trận đánh tiêu biểu của nghệ thuật nghi binh. Trong chiến đấu nếu nghi binh giỏi có thể biến ít thành nhiều, tạo được những nhân tố bất ngờ khiến quân địch không biết được lực lượng của ta, không phán đoán được kế hoạch tác chiến của ta, khiến chúng hoang mang bị động đối phó với ta, tạo thời cơ và điều kiện cho ta tiêu diệt chúng. Trong quá trình tiến hành khởi nghĩa, xuất phát từ tương quan lực lượng địch mạnh, ta yếu, nghĩa quân Lam Sơn rất coi trọng hoạt động nghi binh và nhiều lần giành được thắng lợi. Nghệ thuật nghi binh lừa địch ở trận Chi Lăng nhằm đạt được mục đích phải kéo địch đi theo con đường ta đã chọn, buộc chúng phải đi qua ải Chi Lăng, nơi quân ta đã tổ chức trận địa mai phục. Đội quân của tướng Trần Lựu - người giỏi “trá bại dụ địch” - đã hoàn thành xuất sắc nhiệm vụ nhử địch, vừa bảo vệ được mình vừa đánh lừa được địch, kéo chúng vào địa bàn tác chiến của ta. Mưu kế lừa địch trên chặng đường 60 kilômét độc đạo hiểm trở của đạo quân Trần Lựu khiến quân địch vừa tức giận vừa mệt mỏi, lại thêm kích thích tính chủ quan, hiếu thắng của chúng. Cùng với hoạt động của đội quân Trần Lựu, Bộ chỉ huy nghĩa quân còn viết thư gửi cho Liễu Thăng, xin y hãy ngừng tiến quân với mục đích làm cho viên tổng binh này thêm khinh suất. Đúng như dự đoán của ta, Liễu Thăng không thèm đọc thư, y còn bỏ ngoài tai những lời can gián của những tướng lĩnh có kinh nghiệm, cứ nhất mực gấp gáp tiến quân đuổi theo những toán quân nhỏ lẻ của ta. Kết cục đạo tiền quân do y chỉ huy đã tách khỏi đội hình, sa vào vòng vây của quân ta, không còn cách thoát thân. Chính vì giỏi nghi binh, nghĩa quân Lam Sơn không những lừa được địch mà còn tạo ra những nhân tố bất ngờ khiến quân địch không thể đoán trước được hành động của quân ta. Với một lực lượng đông và mạnh, quân tiếp viện nhà Minh ồ ạt kéo vào biên giới nước ta. Do tính hiếu thắng, khi gặp đạo quân của Trần Lựu vừa đánh vừa chạy, chúng lại càng chủ quan “cho người nước ta nhút nhát, từ lâu vẫn sợ oai giặc nghe có đại quân đến tất phải sợ hãi”. Chúng có biết đâu rằng, đại quân ta đang chờ tiêu diệt chúng ở Chi Lăng.

**Thứ ba,** chiến thắng Chi Lăng là kết quả của nghệ thuật tạo lập thế trận, phát huy sức mạnh tổng hợp của nghĩa quân Lam Sơn. Xét về tương quan lực lượng, đạo quân của Liễu Thăng đông và mạnh hơn hẳn so với lực lượng của ta đưa ra biên giới chống lại chúng, nhưng trong trận Chi Lăng nghĩa quân đã phát huy được sức mạnh của quân chủ lực kết hợp với lực lượng dân binh địa phương. Sức mạnh của các lực lượng đó lại nhân lên khi nghĩa quân đã tận dụng địa hình sông núi hiểm trở để tạo lập thế trận khiến ưu thế của quân ta hơn hẳn quân địch. Lê Lợi, người đứng đầu Bộ chỉ huy nghĩa quân Lam Sơn đã từng kết luận: “Quân địch đông, quân ta ít, đem ít đánh đông, chỉ ở những nơi hiểm yếu là có thể lập được công”. Bộ chỉ huy Lam Sơn đã nghiên cứu, đánh giá lựa chọn Chi Lăng là một điểm quyết chiến bởi đây là địa hình “thiên thời địa lợi” như sử sách mô tả: “Khâu Ôn, Pha Lũy, Cần Trạm núi giăng khít, địa hình hiểm trở, tiện giấu quân mai phục, đánh úp”. Chi Lăng là ải hiểm trở nhất nằm trên con đường độc đạo từ Pha Lũy đến Đông Quan. Với núi cao tạo thành lũy chắn bốn phía, có những ngọn núi nhỏ bên trong, Chi Lăng rất thuận lợi cho quân ta giấu quân, nhưng địa hình ấy lại rất bất lợi cho giặc do tầm quan sát và cơ động bị hạn chế. Tận dụng địa thế, quân Lam Sơn đã bí mật bất ngờ triển khai lực lượng, lập thế trận. Trần Lựu, Lê Bôi giữ ải Pha Lũy, đánh như địch; Lê Sát, Lưu Nhân Chú, Đinh Liệt mai phục ở ải Chi Lăng; Lê Lý, Lê Văn An mai phục ở Cần Trạm. Quân chủ lực Lam Sơn dưới sự chỉ huy của các tướng dày dạn kinh nghiệm trận mạc sát cánh cùng dân binh quanh vùng dựng rào đặt lũy, bố trí lực lượng trong các hẻm đá, khe núi đợi giặc. Đây là một thế trận bí mật, vững chắc và hiểm hóc, buộc quân Minh một khi đã sa vào thì vô cùng bất lợi vì đường hẹp, hai bên núi rừng hiểm trở lại có lực lượng đối phương phục binh chờ sẵn. Quân ta vừa lập xong thế trận cũng là lúc quân Minh tiến vào ải Pha Lũy, tiếp đến là Khâu Ôn. Theo kế hoạch quân ta vừa chặn đánh vừa rút lui, làm cho quân Minh càng thêm kiêu căng khinh địch. Lê Lợi, Nguyễn Trãi lại “đánh vào lòng người", gửi thư cho Liễu Thăng, khiến tướng giặc càng thêm chủ quan, thúc quân tiến nhanh vào Chi Lăng, lao vào “tử địa”, mặc cho Lý Khánh can ngăn hết sức. Giặc bị trúng kế của ta, rơi vào thế trận “phục binh giữ hiểm, đập nát quân tiên phong”. Lần lượt, Liễu Thăng cùng Lương Minh và nhiều quân tướng khác phải tử trận. Do biết tận dụng thế thiên hiểm của địa hình Chi Lăng tạo lập thế trận nên chiến thuật phục binh ở đây của nghĩa quân Lam Sơn được phát huy cao độ và đạt hiệu suất cao. Đó là nghệ thuật tạo lập thế trận xuất sắc.

**Thứ tư,** chiến thắng Chi Lăng - Xương Giang thể hiện nghệ thuật điều động địch của nghĩa quân Lam Sơn, buộc chúng phải hành động theo ý định của ta, tạo điều kiện để ta tiêu diệt chúng từng bộ phận đến tiêu diệt hoàn toàn. Trong điều kiện thế giặc vẫn đang còn mạnh, muốn giành thắng lợi phải nắm bắt được ý đồ và bám sát những hành động của chúng, từ đó chủ động bày binh bố trận, sử dụng lực lượng hợp lý, tìm cách dụ nhử và từng bước dẫn dắt chúng hành động theo ý định của ta, đưa chúng vào trận địa đã chuẩn bị sẵn để tiêu diệt chúng. Trận Xương Giang là một thành công của nghĩa quân Lam Sơn về nghệ thuật điều địch. Để dồn địch về “cái túi" Xương Giang, nghĩa quân đã chủ động tạo lập một thế trận liên hoàn đánh viện binh nhà Minh từ khi chúng chuẩn bị kéo quân vào nước ta. Mở đầu là trận đánh chiếm thành Xương Giang, xóa bỏ một căn cứ quan trọng trên đường tiến quân của chúng. Tiếp theo là hành động nhử địch khéo léo của đạo quân Trần Lựu như phần trước đã nói và lời lẽ nhún nhường của Lê Lợi, Nguyễn Trãi trong những thư gửi cho Liễu Thăng để kích thích thêm tính chủ quan khinh địch của chúng, khiến chủ tướng địch phải bỏ mạng ở Chi Lăng. Sau đó các tướng lĩnh Lam Sơn lại khôn khéo vừa truy kích vừa dắt quân địch vào các trận địa dàn sẵn ở Phố Cát, Cần Trạm rồi đến Xương Giang. Tại Xương Giang quân địch đã sa vào vòng vây của ta và đã bị tiêu diệt hoàn toàn.

**Thứ năm,** Xương Giang còn là trận đánh tiêu biểu của nghệ thuật đánh tiêu diệt của nghĩa quân Lam Sơn. Trong chiến tranh, muốn chiến thắng kẻ thù phải tiêu diệt được lực lượng cơ bản và đập tan ý chí xâm lược của chúng. Muốn vậy phải có sức mạnh hơn hẳn kẻ thù. Sức mạnh đó được tạo bởi thế và lực. Trên mặt trận Xương Giang, vào thời điểm tháng 11 năm 1427, xét về số quân chủ lực, ta không hơn quân Minh, nhưng ngoài lực lượng tinh binh ta còn có thêm hàng chục vạn dân binh làng xã. Quân ta ở thế hoàn toàn chủ động, tinh thần quyết chiến rất cao. Về phía địch, đạo viện binh chủ lực đã mất chủ tướng và bị tiêu diệt một phần, số còn lại trải qua hơn một tháng tham chiến, liên tục bị truy kích khiến chúng quá mệt mỏi; về tới Xương Giang thì thành đã mất không còn chỗ dựa, phải phơi mình trên địa hình trống trải, ở trong vòng vây bốn mặt của ta khiến chúng càng hoang mang, sức chiến đấu suy giảm. Thế và lực của ta lúc này hơn hẳn chúng, nhưng để đánh thắng kẻ thù cần phải có cách đánh có hiệu quả cao. Thực hiện quyết tâm tiêu diệt hoàn toàn quân cứu viện nhà Minh trên cánh đồng Xương Giang, nghĩa quân Lam Sơn đã sử dụng hình thức chiến thuật bao vây kết hợp với tiến công. Mặc dù trước đó quân ta đã tiêu diệt được một bộ phận sinh lực địch ở Chi Lăng, Cần Trạm, Phố Cát và dồn chúng về Xương Giang, nhưng trước thế giặc vẫn đang còn mạnh, Bộ chỉ huy Lam Sơn không đánh ngay mà quyết định tiến hành bao vây giam chân địch trên địa hình bất lợi cho chúng (ở giữa cánh đồng trống trải), đẩy chúng vào thế tiến không được, lui cũng không xong vì đường tiến quân về Đông Quan bị chặn đứng, đường rút về Quảng Tây cũng bị bịt kín. Quân Minh liều chết cố thủ hy vọng sự ứng cứu của đồng bọn ở thành Chí Linh, nhưng thành Chí Linh cũng đã bị hạ khiến Xương Giang càng bị cô lập. Địch càng xảo trá, vòng vây của quân ta càng xiết chặt. Khi quân địch lâm vào tình cảnh lương thực hết cả, binh lính chết đói, bệnh tật... Bộ chỉ huy Lam Sơn ra lệnh cho các cánh quân trên chiến trường Xương Giang đồng loạt tiến công. Bằng cuộc tổng công kích mãnh liệt, quân ta nhanh chóng giành thắng lợi hoàn toàn. Toàn bộ quân giặc ở Xương Giang đã bị tiêu diệt hoặc bị bắt sống. Kế hoạch tăng viện của nhà Minh bị phá sản, hy vọng của Vương Thông bị dập tắt, y không còn con đường nào khác đành xin giảng hòa, thực chất là đầu hàng, cuối tháng 12 năm 1427 chúng phải rút quân về nước. Ý chí xâm lược nước ta của triều đình nhà Minh cũng bị tiêu tan, khiến cho suốt thời gian tồn tại sau đó, triều Minh phải giữ quan hệ bang giao bình thường với nước ta.

**Thứ sáu,** chiến thắng Xương Giang là sự kết hợp chặt chẽ giữa tiến công quân sự với công tác địch vận. Mặc dù đã giam chân đại quân của Thôi Tụ, Hoàng Phúc trong vòng vây nhiều tầng lớp nhưng Bộ chỉ huy Lam Sơn vẫn xác định: với hơn 7 vạn quân lực lượng địch không phải là nhỏ, trong thế khốn cùng, thú dữ thường quẫy mạnh. Đề phòng sự liều lĩnh của kẻ thù, cùng với việc tăng cường lực lượng xiết chặt vòng vây, nhiều lần quân ta viết thư dụ hàng quân địch, khoét sâu vào chỗ yếu, những nhược điểm căn bản của kẻ xâm lược. Bằng những lời lẽ vừa mềm mỏng, vừa cứng rắn những bức thư của Bộ chỉ huy Lam Sơn đã phân tích lẽ an nguy và chỉ ra con đường sống của bọn Thôi Tụ, Hoàng Phúc, chúng chỉ còn cách duy nhất là lui quân, nếu không sẽ bị chôn vùi tại Xương Giang. Công tác địch vận của nghĩa quân khiến quân giặc hoang mang không còn tinh thần chiến đấu. Cuộc tiến công địch bằng chính trị đã tạo điều kiện thuận lợi cho cuộc tiến công quân sự nhanh chóng giành thắng lợi. Phát huy chiến quả của thắng lợi trước nhằm uy hiếp và làm tan rã nhanh chóng tinh thần chiến đấu của địch ở các trận sau và cao hơn nữa, còn khiến cả đạo viện binh Mộc Thạnh không đánh mà tự bỏ chạy. Có thể nói, trên cơ sở tiến công bằng quân sự kết hợp với những biện pháp chính trị, binh vận, đánh địch về mọi mặt là một trong những tư tưởng chỉ đạo chiến tranh sáng tạo của nghĩa quân Lam Sơn.

Chiến thắng Chi Lăng - Xương Giang biểu thị sự nỗ lực phi thường của nghĩa quân Lam Sơn và sự kết hợp chặt chẽ giữa quân đội và nhân dân các dân tộc trong cuộc chiến tranh giải phóng. Đặc biệt nhân dân các làng quanh thành Xương Giang có công lớn giúp nghĩa quân trong khi hạ thành và bao vây tiêu diệt viện binh. Việc giúp đỡ nhiệt tình và phối hợp tác chiến có hiệu quả của nhân dân địa phương đối với nghĩa quân Lam Sơn là hình ảnh đẹp đẽ của cuộc chiến tranh nhân dân thời bấy giờ.

Chiến thắng Chi Lăng - Xương Giang là một điển hình của nghệ thuật quân sự lấy ít địch nhiều, lấy yếu đánh mạnh của nghĩa quân Lam Sơn. Chiến thắng đó thể hiện sức mạnh của trí tuệ, tinh thần và ý chí quyết thắng của dân tộc ta.

Chiến thắng Chi Lăng - Xương Giang là một võ công hiển hách trong lịch sử quân sự Việt Nam. Đây là trận quyết chiến chiến lược oanh liệt dẫn đến thắng lợi hoàn toàn cuộc chiến tranh giải phóng dân tộc đầu thế kỷ XV. Chiến thắng này như một mốc vàng lịch sử, đã góp phần chấm dứt 20 năm đô hộ tàn bạo của nhà Minh trên đất nước ta, mở ra những trang mới trong lịch sử dựng nước và giữ nước quang vinh của dân tộc. Trong nhiều thế kỷ sau đó, đất nước ta sạch bóng giặc ngoại xâm.', 'TEXT', '2026-06-05 05:23:25.890819', '2026-06-05 05:23:25.890796', null, 'DRAFT'), ('88ac76be-c128-48cd-845e-d224752878d0', '687b57fe-865c-496a-83b3-f83690885dd1', 'd99b373f-dde4-49e8-8c93-1f31d6e8b5e7', 'CONTEXT', 'Chi tiết trận Bạch Đằng 938', null, 'Trong cuộc kháng chiến chống quân xâm lược Nam Hán lần thứ hai (năm 938), trận Bạch Đằng do Ngô Quyền chỉ huy là trận quyết chiến chiến lược, là cuộc đọ sức quyết liệt giữa dân tộc ta và giặc Nam Hán. Đây là trận phục kích đường sông, có những nét rất độc đáo và có ý nghĩa to lớn trên nhiều lĩnh vực.

Kể từ khi vua Hùng dựng nước, dân tộc ta đã ghi biết bao sự tích kỳ diệu trên khắp mọi miền của đất nước, trong đó Bạch Đằng nổi lên là một trong những dòng sông ghi lại nhiều chiến công hiển hách của ông cha ta trong các cuộc chống ngoại xâm, bảo vệ nền độc lập của dân tộc.

Bạch Đằng là một dòng sông không dài lắm, khoảng hơn 20 kilômét tính từ thượng lưu nối với sông Đá Bạc đến cửa biển Nam Triệu. Phía trên, sông Bạch Đằng tiếp nước sông Đá Bạc từ sông Lục Đầu qua sông Kinh Thầy đổ xuống và các dòng nước sông Gia Đước, sông Thải, sông Giá bên hữu ngạn, sông Khoai, sông Xinh bên tả ngạn đổ về. Từ đó, dòng sông mở rộng đưa nước ra biển qua cửa Nam Triệu và các chi lưu vốn xưa là lạch thoát triều, như sông Chanh, sông Kênh (cửa sông này đã bị lấp), sông Nam (hay sông Rút). Thượng lưu và trung lưu sông Bạch Đằng chảy giữa hai huyện Thủy Nguyên (Hải Phòng) và Yên Hưng (Quảng Ninh). Cửa Nam Triệu nằm giữa đảo Cát Hải và Vũ Yên - Đình Vũ (Hải Phòng) ngày nay.

Do gần biển, nước sông Bạch Đằng lên xuống theo thủy triều. Lúc triều dâng, mặt sông mênh mông trải rộng đôi bờ đến vài kilômét. Sông khá sâu trung bình khoảng 8 - 11 mét, có chỗ sâu đến 16 mét và cửa sông giáp biển cũng sâu 13 - 14 mét. Độ chênh lệch giữa mức nước lên cao nhất và mức nước xuống thấp nhất vào kỳ nước cường khoảng 2,5 - 3,2 mét và vào kỳ nước kém khoảng 0,5 - 1 mét.

Về phương diện giao thông, sông Bạch Đằng giữ một vị trí quan trọng trong hệ thống các đường thủy vùng Đông Bắc nước ta. Đặc biệt, cửa sông Bạch Đằng là một trong những cửa biển nhìn ra vịnh Bắc Bộ và nối liền với con đường biển trọng yếu giữa nước ta và Trung Quốc. Đó là con đường ven biển từ cửa biển Bạch Đằng đến cửa biển Khâm, Liêm (Quảng Đông, Trung Quốc). Phía trong là bờ biển, phía ngoài là một loạt các đảo lớn nhỏ của vịnh Hạ Long và Bái Tử Long ngăn cách với biển cả, tạo thành một dải nước khá yên lặng rất thuận lợi cho sự đi lại của các tàu thuyền ngày xưa chạy bằng buồm và mái chèo.

Do vị trí giao thông đường thủy của nó, sông Bạch Đằng và cửa biển Bạch Đằng trước hết là một trục giao lưu kinh tế - văn hóa ở trong nước cũng như giữa trong nước và ngoài nước. Trong thời Bắc thuộc, nhiều thuyền buôn Trung Quốc từ Quảng Châu đã theo con đường ven biển qua cửa biển Bạch Đằng để buôn bán với Giao Châu.

Nhưng mặt khác, kẻ thù xâm lược, trong thời cổ đại và trung đại chủ yếu là các đế chế phong kiến phương Bắc, cũng lợi dụng sông Bạch Đằng như con đường xâm lược thuận tiện nhất về mặt đường thủy. Từ các bến cảng Khâm, Liêm (Quảng Đông), thủy quân có thể vượt qua vịnh Bắc Bộ nếu có gió thuận hoặc theo đường ven biển vào cửa Bạch Đằng rồi ngược sông Bạch Đằng lên sông Lục Đầu. Quân bộ có thể hành quân theo đường ven biển vịnh Bắc Bộ hoặc có thể từ Quảng Tây theo các đường bộ tiến sang và hội quân với quân thủy ở vùng Lục Đầu. Cửa sông Bạch Đằng là một “cửa ngõ đường biển”, có một vị trí chiến lược về quân sự đặc biệt quan trọng và xung yếu.

Năm 931, cuộc kháng chiến chống quân Nam Hán xâm lược lần thứ nhất dưới sự lãnh đạo của Dương Đình Nghệ thắng lợi. Dương Đình Nghệ tự xưng là Tiết độ sứ, tiếp tục sự nghiệp của họ Khúc, lo củng cố chính quyền tự chủ vừa giành lại được. Năm 937, Dương Đình Nghệ bị người nha tướng là Kiều Công Tiễn, hào trưởng đất Phong Châu giết hại để đoạt chức Tiết độ sứ. Hành động đó đã gây nên sự phẫn nộ của các tầng lớp quân, dân. Từ châu Ái (Thanh Hóa), Ngô Quyền là tướng và là con rể của Dương Đình Nghệ, sửa soạn tiến quân ra bắc diệt trừ tên phản bội. Trước sự căm ghét và phản kháng của nhân dân cả nước, Kiều Công Tiễn lo sợ, tự thấy thế cô lực yếu, đã đê hèn cho người sang cầu cứu nhà Nam Hán. Đây là dịp tốt để vua Nam Hán thực hiện âm mưu xâm lược nước ta một lần nữa.

Ngô Quyền (897-944) người làng Cam Lâm (nay thuộc xã Đường Lâm, thị xã Sơn Tây, Thành phố Hà Nội), là một làng quê rất giàu truyền thống yêu nước và có nhiều đóng góp cho lịch sử dân tộc trong cuộc đấu tranh lâu dài gian khổ chống giặc phương Bắc. Cha Ngô Quyền là Ngô Mân từng giữ chức Châu mục bản châu (châu Đường Lâm). Ngô Quyền sớm tỏ rõ chí khí phi thường hiếm thấy. Vốn thông minh, có thân thể cường tráng, lại thường xuyên luyện tập võ nghệ nên tiếng tăm Ngô Quyền lan rộng cả một vùng. Sách Đại Việt sử ký toàn thư mô tả Ngô Quyền “vẻ khôi ngô, mắt sáng như chớp, dáng đi như cọp, có trí dũng, sức có thể nhấc vạc, giơ cao”. Ngô Quyền đã theo Dương Đình Nghệ đánh thành Đại La, cướp chính quyền, sau đó lại đánh thắng quân xâm lược Nam Hán do Trần Bảo chỉ huy, bảo vệ được chủ quyền dân tộc. Vì có tài nên Dương Đình Nghệ giao cho Ngô Quyền cai quản đất Ái Châu và gả con gái cho.  

Trong 5 năm (934-938), Ngô Quyền đã đem lại yên vui cho đất Ái Châu, tỏ rõ là người có tài đức.

Khi được tin tên phản phúc Kiều Công Tiễn ám hại chủ tướng và cũng là bố vợ của mình là Dương Đình Nghệ, đoạt quyền Tiết độ sứ cùng với hành động nhân trắc đê hèn cầu ngoại viện của hắn, Ngô Quyền đã nhanh chóng tập hợp lực lượng từ Ái Châu kéo ra Giao Châu diệt trừ nội phản, tiếp tục sự nghiệp giữ vững nền tự chủ còn dang dở của họ Dương.  

Giữa lúc đất nước đang trong tình cảnh ngàn cân treo sợi tóc, người đứng đầu bị sát hại, quân thù đang ngấp nghé bên ngoài bờ cõi, Ngô Quyền đã trở thành niềm tin và hy vọng của toàn dân tộc, thành người thủ lĩnh có đủ tài năng và uy tín để đảm đương sứ mạng lịch sử lúc đó là huy động và lãnh đạo các lực lượng yêu nước trong toàn quốc đứng lên đánh đổ thù trong, dẹp giặc ngoài, giành nền độc lập, tự chủ, mở ra một kỷ nguyên mới lâu dài cho đất nước.  

Từng hâm mộ tài đức của Ngô Quyền, hào trưởng từ nhiều nơi đem binh về với ông. Ngoài những lực lượng quân sự đó, quần chúng nhân dân lúc nào cũng là lực lượng đông đảo nhất và nhiệt thành nhất tham gia đánh giặc bảo vệ đất nước. Tất cả các lực lượng đã nhanh chóng tập hợp dưới trướng của Ngô Quyền và Ngô Quyền lúc này đã trở thành vị thủ lĩnh tối cao với một lực lượng quân sĩ khá hùng mạnh, có mặt ở khắp các vùng từ châu Ái vào châu Hoan ra tới tận châu Giao, khiến lực lượng của Kiều Công Tiễn ở Đại La càng trở nên bị cô lập và hoàn toàn bất lợi.  

Khi đã tập hợp xong lực lượng và nhận thấy nguy cơ xâm lược của nhà Nam Hán đã đến gần, vào tháng 9 năm Mậu Tuất (10-938), Ngô Quyền cho quân tiến từ châu Ái ra Đại La khí thế như vũ bão, diệt trừ tên phản bội Kiều Công Tiễn, bêu đầu hắn trước cổng thành. Thù trong đã diệt xong, Ngô Quyền rảnh tay đối phó với giặc ngoài là quân Nam Hán.

Về phía nhà Nam Hán, được tin cầu cứu của Kiều Công Tiễn, vua Nam Hán là Lưu Cung cho đây là cơ hội đặc biệt thuận lợi, nên đã họp triều thần bàn mưu tính kế. Vấn đề mà vua Nam Hán cần đưa ra bàn định trong triều là bằng cách nào để có thể chiếm được Giao Châu nhanh gọn nhất, vì trận thất bại cách đó 7 năm (năm 931) vẫn còn là bài học nhớ đời. Sùng văn sứ là Tiêu Ích một viên quan có địa vị cao trong triều, là người am hiểu tường tận về tình hình Giao Châu lúc đó, đã bày tỏ sự khó khăn và khuyên nhủ vua Nam Hán rằng: “Hiện nay mưa dầm mấy tuần, mà đường biển thì hiểm trở xa xôi, Ngô Quyền là người kiệt hiệt chớ nên khinh xuất. Đại quân đi phải nên cẩn thận chắc chắn, dùng nhiều người hướng đạo rồi mới nên tiến" (Đại Việt sử ký toàn thư, tập I, Nxb. Khoa học Xã hội, H., 1972, trang 146). Nhưng vì cơ hội tái chiếm Giao Châu đã đến gần nên vua Nam Hán đã không thèm đếm xỉa gì tới lời bàn lợi hại đó của Tiêu Ích và một số triều thần, mà vẫn tự mình chuẩn bị một kế hoạch xuất quân sang Giao Châu để nhanh chóng thực hiện mưu đồ nung nấu từ lâu.  

Lần xuất quân lần này, vua Nam Hán đã có kinh nghiệm hơn. Nam Hán đã tận dụng thế mạnh của mình là binh thuyền và đi theo đường biển từ Quảng Đông sang. Người được vua Nam Hán Lưu Cung giao trọng trách chỉ huy đội quân đánh chiếm Giao Châu lần này chính là con trai mình, Vạn Vương Hoằng Tháo (có sách chép là Hoàng Thao, Hoành Thao). Trước khi xuất quân, vua Nam Hán đã đổi tước phong cho Hoằng Tháo từ Vạn Vương sang làm Nam Giao Vương với kỳ vọng rằng, nếu chiếm được Giao Châu sẽ lấy Giao Châu làm nơi phong thực ấp cho con. Không những thế, chính bản thân vua Nam Hán còn đích thân dẫn đầu một đạo quân ra đóng ở trấn Hải Môn (huyện Bác Bạch, Quảng Đông) sát biên giới, làm kế thanh viện, kịp thời yểm trợ cho Hoằng Tháo.  

Với kế hoạch như vậy, cộng với sự tin tưởng là đã có Kiều Công Tiễn làm nội ứng, khi quân Nam Hán tới nơi thì hai bên hợp đồng tác chiến, thực hiện kế “nội công ngoại kích”, nhanh chóng đánh chiếm đất nước ta.

Cuộc chiến tranh quy mô lớn và mang đầy tham vọng đó của nhà Nam Hán được che đậy dưới chiêu bài “cứu giúp” Kiều Công Tiễn. Quân đội Nam Hán đã dày dạn trong chiến tranh ở vùng Hoa Nam và trong cuộc đàn áp các phong trào chống đối của các “Man trại” ở vùng Quảng Đông và Quảng Tây. Từ khi lên ngôi hoàng đế, Lưu Cung càng lo củng cố và tăng cường quân đội của mình để chờ dịp bành trướng xuống phía Nam. Lực lượng mà Lưu Cung huy động tiến công nước ta lần này chủ yếu là thủy quân đã kinh qua chiến trận, có nhiều kinh nghiệm chiến đấu.  

Như vậy, Hoằng Tháo vừa được sự tiếp ứng của vua cha Lưu Cung phía sau, vừa có lực lượng nội ứng của bọn phản bội Kiều Công Tiễn ở ngay trong nước ta. Lúc đó, Kiều Công Tiễn đang cố gắng cố thủ ở thành Đại La để chờ quân cứu viện nhà Nam Hán. Việc Ngô Quyền đã nhanh chóng ra tay diệt trừ tên phản bội Kiều Công Tiễn trước khi quân Nam Hán kéo vào nước ta đã làm cho quân giặc hoàn toàn bị bất ngờ. Thành công này của Ngô Quyền đã làm thất bại ngay từ đầu âm mưu dùng nội ứng của địch, vừa tạo ra thế chủ động cho cuộc kháng chiến của quân và dân ta.  

Bấy giờ, Hoằng Tháo đã được lệnh chỉ huy đạo thủy quân tiến vào sông Bạch Đằng. Trước tình hình đó, tại thành Đại La, Ngô Quyền họp các tướng bàn rằng: “Hoằng Tháo là một đứa trẻ dại, đem quân từ xa đến, quân lính mỏi mệt, lại nghe được tin Công Tiễn đã chết, không có người làm nội ứng, đã mất vía trước rồi. Quân ta sức còn mạnh địch với quân mỏi mệt, tất phá được. Song họ có lợi ở thuyền, nếu ta không phòng bị trước thì chuyện được thua chưa thể biết được. Nếu ta sai người đem cọc lớn đóng ngầm ở cửa biển trước, vạt nhọn đầu mà bịt sắt, thuyền của họ nhân khi nước triều lên tiến vào bên trong hàng cọc, bấy giờ ta dễ bề chế ngự. Không kế gì hơn kế ấy cả" (Đại Việt sử ký toàn thư, tập I, Sđd, tr.146).  

Tướng sĩ nghe nói ai cũng vui mừng, tin rằng chắc thắng. Nhận định của Ngô Quyền chứng tỏ ông là một vị tướng biết địch biết ta. Ông đã nắm vững và phản ánh đúng tình hình địch, cho rằng quân giặc tuy đông, vũ khí, trang bị mạnh, nhất là các thuyền chiến lớn, nhưng cũng có nhiều hạn chế. Điểm yếu chí tử của chúng là tướng giặc (Lưu Hoằng Tháo) còn trẻ, chưa có nhiều kinh nghiệm trận mạc, kiêu ngạo, chủ quan khinh địch. Dưới mắt ông “Hoằng Tháo chỉ là một đứa trẻ dại” mà thôi. Quân địch từ xa đến, địa hình xa lạ, hiểm trở, còn mệt mỏi, lại mất kẻ nội ứng, tinh thần yếu kém. Trong khi đó khí thế quân ta đang mạnh, lại làm chủ địa hình và biết đánh. Đó chính là điều kiện dẫn tới sự tất thắng của quân ta, sự bại vong không thể tránh khỏi của địch. Ngô Quyền cũng chỉ ra cái lợi thế của địch chính là việc chúng có thuyền chiến mạnh, nếu ta chủ quan không phòng bị chu đáo thì kết cục thắng hay bại của cuộc kháng chiến chưa thể lường trước được.  

Nam Hán không phải là một triều đại lớn ở Trung Quốc. Quân đội Nam Hán tuy đã từng trải chiến tranh, nhưng cũng từng nếm mùi thất bại trong lần xâm lược năm 931, nay lại tổ chức một cuộc chiến tranh mới trong điều kiện đầy khó khăn. Tất nhiên, rút kinh nghiệm lần trước và để giành thắng lợi trong lần này, quân Nam Hán đã phát huy thế mạnh, sử dụng những thuyền chiến vừa to vừa chắc chắn, có trang bị đầy đủ và có khả năng chiến đấu trên sông biển. Từ hàng ngàn năm, Quảng Châu là một trung tâm thương mại lớn, có nhiều thuyền buôn trên biển. Nam Hán có thủy quân mạnh và quân đội của họ đã trải qua kinh nghiệm trận mạc. Lực lượng chiến đấu của thủy quân hầu hết là những người đã từng làm nghề đánh cá, làm muối, những thủy thủ và bọn cướp biển - những người lính đã được huấn luyện chu đáo vì mục đích chinh phục và ăn cướp. Vũ khí trang bị là bạch binh, ngoài câu liêm, móc treo, gươm giáo và áo giáp, còn có nhiều cung nỏ. Nỏ có nhiều loại, trong đó có nỏ nặng với hiệu suất chiến đấu cao và được trang bị tối đa. Quân Nam Hán rất giỏi sử dụng nỏ, sử Trung Quốc gọi họ là đội quân “Thần nỏ". Những điều đó, Ngô Quyền đều biết và ông đánh giá cao những lợi thế về thuyền và khả năng thủy chiến của giặc.  

Sử cũ không cho biết rõ lực lượng cụ thể của địch, của ta trong cuộc chiến tranh là bao nhiêu. Tuy nhiên, qua lời bình của sử gia Lê Văn Hưu về cuộc kháng chiến chống Nam Hán của sách Đại Việt sử ký toàn thư còn ghi lại: “Tiền Ngô Vương có thể lấy quân mới họp của đất Việt ta mà phá được trăm vạn quân của Lưu Hoằng Tháo, mở nước xưng vương...", thì có thể thấy được tương quan lực lượng giữa ta và địch là rất chênh lệch.

Quân đội của Ngô Quyền lúc này tuy không hùng hậu lắm về số lượng nhưng là đội quân được trưởng thành trong cuộc chiến tranh vệ quốc, có lòng yêu nước cao độ, có kỷ luật nghiêm minh, mưu trí, gan dạ và dũng cảm. Họ đã từng theo Dương Đình Nghệ và Ngô Quyền chiến đấu trong trận vây đánh thành Đại La, đuổi Thứ sử Lý Tiến, giết Thừa chỉ Trần Bảo vào năm 931 và đặc biệt họ cũng vừa cùng chủ tướng của mình tham gia trừng trị tội nghịch thần, phản chủ, phản quốc của Kiều Công Tiễn, nên khí thế ra trận của họ rất hăng hái, mãnh liệt. Quân đội của Ngô Quyền còn có quân của các tướng, các hào kiệt địa phương đến tụ hội và các đội dân binh do các làng xã tổ chức để chống giặc ngoại xâm. Tuy nhiên, về mặt vũ khí, chiến thuyền còn nhiều hạn chế so với quân Nam Hán. Trước họa xâm lăng, bên cạnh lực lượng quân đội do Ngô Quyền thống lĩnh, có những đội dân binh ở các làng xã theo tiếng gọi cứu nước đã được tổ chức đội ngũ sẵn sàng tham gia kháng chiến. Trong quá trình gấp rút chuẩn bị đánh giặc, Ngô Quyền đã đặc biệt chú trọng xây dựng lực lượng thủy quân, cho sửa chữa, đóng mới và huy động nhiều thuyền phục vụ quân đội. Có thể lúc đó quân đội của Ngô Quyền đã dùng nhiều loại thuyền, trong đó có thuyền “mông đồng” mà sử sách thường nói tới. Thuyền “mông đồng” theo Đại Việt sử ký toàn thư ghi thì, “mỗi thuyền có 25 chiến thủ, 23 tay chèo, thuyền chèo ngược xuôi nhanh như gió”, là loại thuyền hẹp và dài, có hai đáy, lớn nhỏ khác nhau, rất tiện sử dụng trong chiến đấu.  

Không có tài liệu ghi chép về vũ khí của quân đội Ngô Quyền, nhưng qua lời Tống Cảo tâu lên vua Tống về tình hình vũ khí của quân ta thời Lê Hoàn (nửa thế kỷ sau) và qua nghiên cứu khảo cổ học, chúng ta có thể đoán được quân đội của Ngô Quyền được trang bị các loại cung, nỏ, khiên mộc, lao gậy, kiếm, dao găm, giáo, kích... Ngoài ra khi chiến đấu trên thuyền quân sĩ còn sử dụng cả câu liêm, móc treo, lưới cá...  

Xét trên góc độ tiềm lực vật chất, trang bị quân sự thì có thể quân ta còn thua kém quân giặc. Song sức mạnh chiến đấu của quân đội mỗi bên tham chiến ngoài nhân tố tiềm lực vật chất - kỹ thuật, còn được tạo nên bởi các nhân tố khác như chế độ chính trị của đất nước, tinh thần chiến đấu của quân đội, tài thao lược của tướng lĩnh, những điều kiện thiên nhiên thuận lợi... hoặc theo cách nói của người xưa là các nhân tố “thiên thời, địa lợi, nhân hòa”. Nếu đem so sánh tương quan giữa địch và ta về các mặt thì quân ta mạnh hơn quân Nam Hán xâm lược. Chính vì vậy, Ngô Quyền đã khẳng định quân địch sẽ “dễ bề chế ngự” và “tất phá được”.  

Từ phân tích, đánh giá tình hình một cách chính xác tương quan lực lượng giữa ta và địch, thấy mặt mạnh của địch và mặt hạn chế của ta, đồng thời lại thấy rõ mặt yếu chí mạng của địch và mặt mạnh cơ bản của ta mà ở đây, trong cuộc chiến đấu sắp tới, những nhân tố thiên thời, địa lợi, nhân hòa và tài thao lược của tướng lĩnh lại là những nhân tố hợp thành nguyên nhân quyết định sự thành công hay thất bại của mỗi bên tham chiến, Ngô Quyền đi đến xác định mưu lược đánh bại cuộc tiến công xâm lược của địch bằng kế tổ chức một trận đánh lớn tiêu diệt đạo binh thuyền giặc ngay tại vùng cửa sông Bạch Đằng, nơi chúng tất phải đi qua để có thể tiến vào nội địa nước ta.  

Trong lời bàn với các tướng, Ngô Quyền đã đề xuất kế sách đánh thủy quân giặc là sai người đem cọc lớn vạt nhọn đầu bịt sắt đóng ngầm trước ở cửa sông và lợi dụng quy luật lên xuống của thủy triều để chế ngự thuyền giặc, không cho chúng chạy thoát. Đó chính là mưu lược phản công với quyết tâm đánh thắng giặc ngay khi chúng vừa xâm phạm đến bờ cõi nước ta, nhanh chóng giành thắng lợi quyết định cho cuộc kháng chiến bằng trận phản công, kết hợp giữa phục kích và vận động chiến nhằm tiêu diệt gọn đạo quân xâm lược ngay từ cửa ngõ Tổ quốc.

Qua mưu lược chống giặc mà Ngô Quyền đã bàn với các tướng có thể thấy được mục đích của trận đánh là nhằm tiêu diệt toàn bộ binh thuyền lớn do Hoằng Tháo chỉ huy khi chúng vượt biển tới vùng cửa sông Bạch Đằng. Đạo binh thuyền lớn của Hoằng Tháo là đạo quân xâm lược đi đầu, đạo quân chủ lực của địch. Còn đạo quân do Lưu Cung trực tiếp chỉ huy đóng ở trấn Hải Môn là đội quân tiếp sau, thê đội hai, lực lượng dự bị của địch. Nếu Hoằng Tháo tiến sang thuận lợi, hoặc chỉ bị quân ta chặn đánh tiêu hao, nhưng vẫn tiếp tục tiến sâu được vào nội địa nước ta, thì đội quân dự bị của Lưu Cung ắt sẽ tràn sang tăng cường để đè bẹp lực lượng kháng chiến. Nhưng nếu đội quân Hoằng Tháo bị ta chặn đánh tiêu diệt gọn một cách nhanh chóng thì đạo quân Lưu Cung sẽ không kịp sang tăng viện, mà chỉ còn cách duy nhất là hạ cờ rút lui để bảo toàn tính mạng. Do vậy, một khi thực hiện được mục đích trận đánh là nhanh chóng tiêu diệt gọn đạo binh thuyền Hoằng Tháo khi chúng vừa tiến vào cửa sông Bạch Đằng, làm cho Lưu Cung kinh hoàng khiếp sợ, buộc phải rút quân về, thì đã đạt được mục đích chiến lược của cuộc kháng chiến: tiêu diệt lực lượng quân địch, làm tan rã ý chí xâm lược của nhà Nam Hán, kết thúc thắng lợi cuộc chiến tranh giữ nước, bảo vệ vững chắc chủ quyền của dân tộc và sự toàn vẹn lãnh thổ của đất nước.  

Qua lời Ngô Quyền định kế chống giặc trên, có thể thấy rõ một số điểm thuộc cách đánh trong trận quyết chiến này như sau:

Về đối tượng tác chiến: toàn bộ đoàn binh thuyền lớn của địch do Hoằng Tháo chỉ huy, gồm hàng vạn quân với hàng trăm thuyền chiến cỡ lớn.

Về địa bàn tác chiến: Ngô Quyền chọn một cửa sông mà khả năng quân địch sẽ tiến vào để bố trí trận địa mai phục, đó là cửa sông Bạch Đằng, nơi có địa thế hiểm trở có thể bố trí một trận thủy chiến.

Về cách đánh: Ngô Quyền chủ trương bố trí trận địa mai phục với những cọc gỗ bịt sắt nhọn đóng ngầm dưới nước để cản phá thuyền giặc, kết hợp giữa vận động tiến công và mai phục, đợi khi nước triều lên sẽ khiêu chiến nhử địch vào trận địa cọc ngầm rồi tiến công tiêu diệt chúng khi nước triều xuống.

Về sử dụng lực lượng: Lực lượng chiến đấu sẽ có hai bộ phận: một lực lượng với những chiến thuyền nhỏ và nhẹ, cơ động nhanh có nhiệm vụ khiêu chiến, nhử địch; bộ phận chủ lực gồm phần lớn quân thủy bộ bố trí mai phục để tiến công tiêu diệt khi chúng đã lọt vào trận địa cọc ngầm.  

Quân đội chủ lực của Ngô Quyền sửa soạn chiến đấu trong sự phối hợp với các đội dân binh của các làng xã và sự tham gia phục vụ chiến đấu của nhân dân trong vùng.  

Theo thần tích, truyền thuyết dân gian và gia phả họ Dương ở làng Ràng (Dương Xá, Thiệu Hóa, Thanh Hóa), ngoài Ngô Quyền là vị chỉ huy tối cao, tham gia trận quyết chiến này còn có các tướng Ngô Xương Văn (con cả Ngô Quyền), Dương Tam Kha (con Dương Đình Nghệ, em vợ Ngô Quyền), Đỗ Cảnh Thạc (hào trưởng Đỗ Động)...  

Sau khi đánh tan bọn phản bội Kiều Công Tiễn, Ngô Quyền và bộ tham mưu tiến quân về vùng biển Đông Bắc cùng nhân dân địa phương chuẩn bị thế trận đón đánh quân Nam Hán. Vùng sông Bạch Đằng, nơi Ngô Quyền chọn làm chiến trường quyết chiến là một vùng địa lý quan trọng, là cửa ngõ phía Đông Bắc và là đường giao thông quan trọng từ biển Đông vào nội địa nước ta. Theo cửa Nam Triệu vào Bạch Đằng, địch có thể ngược mãi lên và tiến đến thành Cổ Loa hoặc thành Đại La hoàn toàn bằng đường sông. Cửa biển Bạch Đằng to rộng, rút nước từ vùng Đông Bắc Bắc Bộ đổ ra vịnh Hạ Long. Từ cửa biển ngược lên gần 20km là đến cửa sông Chanh. Phía hữu ngạn có dãy núi đá vôi Tràng Kênh với nhiều hang động, sông lạch và thung lũng hiểm trở. Trước cửa sông Bạch Đằng, về phía Bắc là những đảo nhỏ từ vịnh Hạ Long kéo tới. Thuyền từ biển vào sông, len qua vùng quần đảo này khi gặp sóng to gió mạnh vẫn bảo đảm an toàn. Hai bên bờ sông, nay là đồng ruộng và xóm làng nhưng xưa kia còn nhiều cánh rừng rậm, cây cối um tùm che lấp bờ sông thuận lợi cho quân ta che giấu, mai phục lực lượng, hạ lưu sông chịu ảnh hưởng của thủy triều khá mạnh. Lúc triều dâng, nước trải đôi bờ đến vài kilômét. Với cơ chế nhật triều, thời gian từ lúc nước triều lên cho đến lúc xuống thấp nhất chỉ trong vòng một ngày. Dấu ấn của rừng xưa còn như in trên tên sông, tên đất: sông Rừng, bến đò Rừng, xóm Rừng, giếng Rừng... sông Bạch Đằng (hay sông Rừng) rộng lớn, có sóng bạc đầu; tuy không dài lắm, chỉ khoảng vài chục kilômét, nhưng cảnh sắc thiên nhiên ở đây rất hùng vĩ, nơi có thế “thiên hiểm” như Trương Hán Siêu đã mô tả:  

Bát ngát sóng kình muôn dặm
Thướt tha đuôi trĩ một màu
Nước trời một sắc, phong cảnh ba thu
Bờ lau san sát, bến lách đìu hiu
(BẠCH ĐẰNG GIANG PHÚ)

Giữa vùng thiên nhiên sông biển đó, trên cơ sở sức mạnh đoàn kết và ý chí độc lập của cả dân tộc, Ngô Quyền khẩn trương xây dựng một thế trận mai phục lợi hại để chủ động phá giặc.

Ngô Quyền huy động quân dân vào rừng đốn gỗ, vót nhọn, bịt sắt rồi cho đóng xuống dòng sông thành hàng dài, tạo nên một bãi cọc, một bãi chướng ngại dày đặc ở hai bên cửa sông. Khi nước triều lên mênh mông thì cả bãi cọc ngập chìm, khi triều xuống thì hàng cọc nhô lên cản trở thuyền qua lại. Đại Việt sử ký toàn thư chép: “Định kế rồi, (Ngô Quyền) mới cho đóng cọc ở hai bên cửa biển”.

Để bố trí được bãi cọc trên sông Bạch Đằng, Ngô Quyền đã khéo chọn những người giỏi địa lý trực tiếp theo dõi và tìm hiểu trong dân nắm chắc quy luật (thời điểm, mức độ, tốc độ) thủy triều lên, xuống hàng ngày và vị trí thuận lợi để đóng cọc. Nhờ huy động được lực lượng quân, dân nên chỉ trong thời gian ngắn, hàng nghìn cây gỗ lim, sến đầu vạt nhọn, bịt sắt đã được bí mật cắm xuống lòng sông, thành những hàng dài chắc chắn, đầu cọc hướng chếch về phía nguồn. Khi triều rút, các hàng cọc mới phơi ra, còn lúc sáng sớm nước đang mênh mông thì thuyền lớn qua lại ven hai bờ vẫn như không. Trận địa cọc được tiến hành rất gấp rút và chỉ trong khoảng thời gian hơn một tháng là mọi việc đã hoàn thành.

Trận địa cọc ngầm là một nét độc đáo, sáng tạo của nghệ thuật thủy chiến Việt Nam mà Ngô Quyền là người khởi xướng đầu tiên. Khi chuẩn bị trận địa, Ngô Quyền không những lợi dụng địa hình thiên nhiên, mà còn lợi dụng cả chế độ thủy triều. Đây cũng là một trận đánh biết lợi dụng con nước thủy triều sớm nhất trong lịch sử quân sự nước ta, mở đầu cho truyền thống lợi dụng thủy triều nhiều trận thủy chiến sau này.  

Trận địa cọc có vị trí đặc biệt quan trọng trong toàn bộ thế trận của Ngô Quyền. Nó sẽ giúp quân ta “dễ bề chế ngự” đoàn thuyền địch, như lời Ngô Quyền đã khẳng định với tướng sĩ. Song trận địa đó sẽ mất hết tác dụng nếu đoàn thuyền giặc không bị đánh bại ở phía trong hàng cọc. Vì vậy, đồng thời với việc xây dựng trận địa cọc ngầm, Ngô Quyền đã tập trung công sức bố trí một thế trận quy mô lớn phía trong hàng cọc vùng hạ lưu và cửa biển Bạch Đằng.  

Các bộ sử cũ không ghi chép cụ thể về vấn đề này, nhưng qua kết quả khảo sát thực địa, nghiên cứu dấu tích thành lũy, di tích và phong tục thời Ngô Quyền, Ngô Xương Ngập, các truyền thuyết dân gian có liên quan và nhất là qua một số thần tích, ngọc phả sưu tầm được ở vùng cửa sông Bạch Đằng, các nhà nghiên cứu có thể hình dung được phần nào sự bố trí lực lượng của Ngô Quyền.  

Ở phía tả ngạn sông Bạch Đằng được bố trí lực lượng thủy binh thiện chiến, giàu kinh nghiệm sông nước do Dương Tam Kha chỉ huy phối hợp với đội binh thuyền địa phương do Đào Nhuận dẫn đầu. Cánh quân này phục sẵn ở các kênh rạch bên sông, lợi dụng thế dòng nước triều xuống, bất ngờ chặn đầu, tiến công thẳng vào đoàn thuyền địch, hãm chúng sa vào trận địa cọc ngầm.

Một cánh quân khác do Đỗ Cảnh Thạc và Ngô Xương Ngập chỉ huy bố trí và đánh địch từ phía hữu ngạn sông Bạch Đằng. Cánh quân này chiến đấu có sự kết hợp chặt chẽ với lực lượng dân binh địa phương, những đội dân binh của anh em Lý Minh, Lý Bảo, Lý Khả ở Hoàng Pha (xã Hoàng Động, huyện Thủy Nguyên, Hải Phòng) và của chàng trai họ Nguyễn ở Lâm Động (Thủy Nguyên). Lực lượng do Đỗ Cảnh Thạc chỉ huy gồm cả bộ binh và thủy binh, cả quân chủ lực và dân binh. Họ mai phục trong rừng cây ven sông, rạch, phối hợp với cánh quân bên tả ngạn của Dương Tam Kha, từ hai phía tiến công vào đoàn thuyền chiến của quân Nam Hán. Có thể lúc đó có một đạo thủy quân mạnh phục sẵn làm nhiệm vụ chẹn đầu, chờ khi nước xuống sẽ xuôi dòng đánh vỗ mặt đội hình tiến công của quân giặc.  

Theo thần tích Ngô Quyền ở Gia Viên, trước khi quân Nam Hán đến xâm lược, Ngô Quyền đã lập đồn bên sông Gia Viên (tức sông Cấm) để chặn giặc. Đồn Gia Viên (Hải Phòng) là trung tâm, tập trung một lực lượng lớn thủy binh và bộ binh do Ngô Quyền trực tiếp chỉ huy. Ở đồn Lương Xâm (An Hải, Hải Phòng) nay vẫn còn một số câu đối phản ánh điều đó như:  

Sư xuất vạn toàn, Hán tướng Bắc lai vô phản bái,
Danh lưu thiên cổ, Cấm giang đông hạ cựu hành doanh.  

(Quân trảy vẹn toàn, tướng Hán từ phương Bắc kéo sang không còn ngọn cờ quay lại.
Tiếng lưu muôn thuở, sông Cấm về phía đông chảy xuống, nối tiếp hành doanh).  

Quân thủy bộ, dưới sự thống lĩnh của Ngô Quyền đã bố trí mai phục sẵn ở phía trong bãi cọc, có lẽ trong khoảng hạ lưu và trung lưu sông Bạch Đằng; giấu quân trong các nhánh sông dưới rừng cây hai bên sông. Trong thế trận của Ngô Quyền, lực lượng mai phục trên sẽ giữ vai trò quyết định; trận địa cọc ngầm ở cửa sông nhằm cản phá, chặn đường tháo chạy của giặc. Sự bố trí kết hợp giữa hệ thống bãi cọc ngầm và quân mai phục chứng tỏ quyết tâm chiến lược của Ngô Quyền nhằm tiêu diệt hoàn toàn đạo quân xâm lược bằng một trận đánh quyết định. Như vậy, chiến trận Bạch Đằng diễn ra trong một cuộc đọ sức quyết định giữa ta và địch. Quân địch quyết tâm xâm chiếm nước ta. Quân ta quyết tâm đánh một trận tiêu diệt triệt để, hoàn thành sự nghiệp giải phóng dân tộc.  

Về diễn biến và hình thái cuộc chiến tranh, toàn bộ cuộc kháng chiến được thực hiện bằng một trận quyết chiến chiến lược lớn.
Tháng 12 năm Mậu Tuất (938), đoàn binh thuyền Nam Hán do Hoằng Tháo chỉ huy, hung hăng từ Quảng Đông (Trung Quốc) vượt biển xâm phạm vào lãnh thổ nước ta. Đoàn chiến thuyền thuận chiều gió đông bắc theo đường Đông Kênh qua châu Vĩnh An, theo trại Đại Bàng (đảo Kế Bào ngày nay) thuộc Ngọc Sơn, len qua các đảo nhỏ tiến vào vịnh Hạ Long. Dọc đường chúng không gặp một sự kháng cự nào, Hoằng Tháo là viên tướng trẻ tuổi hung hăng, rất chủ quan khinh địch, vội vàng thúc quân tiến thẳng vào cửa sông Bạch Đằng.  

Khi những chiếc thuyền chiến đầu tiên của quân Nam Hán vừa đến vùng cửa biển Bạch Đằng thì đội quân khiêu chiến của ta trên những chiếc thuyền nhẹ bỗng nhiên xuất hiện. Dưới quyền chỉ huy của tướng Nguyễn Tất Tố, quân ta chiến đấu rất dũng cảm, quyết liệt, vừa cố kìm chân giặc chờ nước triều lên cao, vừa để chúng không hoài nghi, giữ bí mật tuyệt đối cho trận địa mai phục. Quân Nam Hán vừa tiến vừa đánh; lợi dụng quân đông khí thế đang hăng và lúc nước triều dâng cao, chúng tăng tốc tiến sâu vào vùng cửa sông Bạch Đằng.  

Lúc nước triều đã dâng cao ngập cọc thì đội thuyền chiến của Nguyễn Tất Tố “dường như không còn sức", họ vừa đánh vừa rút, để nhử địch vào trận địa đúng lúc, đúng chỗ theo kế hoạch của chủ tướng Ngô Quyền. Thấy quân ta ít lại đang tìm cách tháo chạy, Hoằng Tháo đắc chí ra lệnh đuổi theo tiêu diệt. Càng đuổi, quân Nam Hán càng tiến sâu vào cửa sông và lọt vào trận địa mai phục của quân ta. Đại Việt sử ký toàn thư chép: “Khi nước triều dâng lên, Quyền sai người đem thuyền nhẹ ra khiêu chiến, giả cách thua để dụ địch. Hoằng Tháo quả nhiên tiến quân vào" (Sđd, tr.146).  

Khi đoàn chiến thuyền của Hoằng Tháo vượt qua vùng cửa sông Bạch Đằng thì nước triều bắt đầu xuống; đó cũng là lúc toàn bộ đội hình quân giặc lọt vào trận địa mai phục của ta. Đúng lúc đó đội quân khiêu chiến của Nguyễn Tất Tố được lệnh đánh quật trở lại và Ngô Quyền đích thân chỉ huy đại quân đổ ra từ ba phía, tiến đánh dữ dội. Trận tiến công bất ngờ, mãnh liệt của thủy quân ta từ thượng lưu đánh xuống chặn đầu, kết hợp với quân thủy bộ mai phục ở hai bên bờ sông đánh tạt ngang vào đội hình quân giặc.  

Đoàn thuyền chiến của ta nhỏ nhẹ cơ động “nhanh như gió” lại xuôi theo dòng nước lao thẳng vào đội hình thuyền chiến của giặc khiến cho chúng không kịp chống đỡ, bị rối loạn, lúng túng. Các cánh quân của các tướng Dương Tam Kha, Đỗ Cảnh Thạc, Ngô Xương Ngập, Nguyễn Tất Tố cùng các lực lượng dân binh nhất tề tiến công quân giặc. Toàn bộ đoàn binh thuyền của Hoằng Tháo nằm trọn trong vòng vây của quân ta. Quân Nam Hán bị đánh chặn quyết liệt ở phía trước, bị liên tiếp tiến công từ hai bên cạnh sườn. Lúc này, tất cả các lực lượng thủy bộ của quân ta cùng phối hợp chặt chẽ tiến công tiêu diệt các thuyền chiến của địch. Quân Nam Hán cố tìm cách chống đỡ, nhưng chúng dường như bất lực trước sức tiến công mãnh liệt của quân ta. “Hoằng Tháo không kịp chỉnh đốn binh thuyền", tổ chức chống đỡ yếu ớt và định tìm đường rút chạy ra biển, nhưng không kịp, chúng đã sa vào bãi cọc ngầm của quân ta. Sử cũ chép rằng: “Hoằng Tháo phải chống cự luôn tay, mà nước triều xuống rất nhanh, thuyền bè đều bị vướng vào cọc. Quyền đánh hăng, đại phá được Hoằng Tháo" (Việt sử lược, Nxb. Văn Sử Địa, H., 1960, tr.41); và “Khi binh thuyền của Hoằng Tháo đã vào bên trong hàng cọc rồi, nước triều rút, cọc nhô lên, Quyền mới tiến quân đánh. Chúng (quân Nam Hán) đều liều chết mà đánh, không kịp chỉnh đốn thuyền mà nước triều rút xuống mạnh, thuyền đều vướng vào cọc mà đắm, rối loạn tan vỡ, quân lính chết đuối quá nửa" (Đại Việt sử ký toàn thư, Sđd, tr. 146).  

Bị cọc chặn, bị quân đánh, thuyền địch không thể nào thoát ra biển được. Toàn bộ chiến thuyền của giặc bị đánh chìm, hầu hết quân giặc bị tiêu diệt. Đạo thủy quân xâm lược của Nam Hán đã vĩnh viễn bị nhấn chìm xuống dòng sông Bạch Đằng lịch sử. Chủ soái của giặc là Lưu Hoằng Tháo bị giết tại trận. Việt sử lược, Đại Việt sử ký toàn thư đều ghi: “Quyền thừa thắng đuổi theo đánh, bắt được Hoằng Tháo đem giết". Sách Ngũ đại sử ký của Trung Quốc cũng chép về sự kiện này: “Thuyền của Hồng Thao (tức Hoằng Tháo) bị mắc cạn nên mắc vào cọc bịt sắt, vỡ đắm gần hết, Hồng Thao tử trận" (Ngũ đại sử ký, q.65).  

Trong trận đánh, quân Nam Hán mới biết thế nào là tiến thoái lưỡng nan một cách vô cùng quẫn bách không chiều xoay xở. Trước mặt, sau lưng, bên phải, bên trái, trên bờ, dưới nước đều bị đánh tới tấp. Hầu hết thuyền lớn thuyền nhỏ đều bị cọc nhọn đâm thủng, va chạm vào nhau mà bị chìm xuống sông. Viên chủ tướng trẻ Hoằng Tháo lúc đầu hung hăng, ngạo mạn bao nhiêu thì đến đây càng bị mất tinh thần, hoảng loạn, khiếp đảm bấy nhiêu, cuối cùng bị quân của Ngô Quyền bắt và giết tại trận.

Cuộc chiến đấu cam go quyết liệt diễn ra và kết thúc chỉ trong vòng một con nước triều, nghĩa là chỉ trong vòng một ngày; thời gian chiến đấu ác liệt nhất là lúc nước triều xuống mạnh cho đến lúc nước rặc, nghĩa là chỉ trong nửa ngày. Toàn bộ đạo quân xâm lược hùng hổ, hung hăng với đoàn thuyền chiến lớn đã bị tiêu diệt ngay tại vùng cửa biển Bạch Đằng - nơi địa đầu sông nước của Tổ quốc - khi chúng chưa kịp đặt chân lên mảnh đất thiêng liêng của Tổ quốc ta, chưa kịp gây tội ác đối với nhân dân ta. Cuộc kháng chiến chống quân Nam Hán lần thứ hai này kết thúc thắng lợi nhanh, gọn trong một trận quyết chiến chiến lược. Đây cũng là một trong những cuộc chiến tranh chống xâm lược tiêu biểu nhất cho lối đánh thần tốc có hiệu quả cao của dân tộc ta.

Lúc Hoằng Tháo đang bị bao vây và bị thất bại thảm hại ở hạ lưu và cửa sông Bạch Đằng thì Lưu Cung cùng đạo quân ở trấn Hải Môn vẫn hoàn toàn không hay biết gì. Trận Bạch Đằng diễn ra nhanh chóng, triệt để đến mức vua Nam Hán đang đóng quân ở sát biên giới mà không sao tiếp ứng kịp cho con. Nghe tin thất bại quá kinh hoàng và bất ngờ, vua Nam Hán rụng rời chân tay, vô cùng thất vọng, thương khóc, đành thu nhặt tàn quân quay về nước. Sử chép: “Vua Hán thương khóc, thu nhặt quân còn sót lại mà lui. Vua Hán cho tên Cung là xấu là vì thế (Lưu Cung tức là Lưu Yễm)" (Đại Việt sử ký toàn thư, Sđd, tr.146).  

Chiến thắng Bạch Đằng đã phá tan kế hoạch xâm lược của Nam Hán. Từ đó, triều Nam Hán phải vĩnh viễn từ bỏ dã tâm xâm lược nước ta, không dám đụng đến chủ quyền lãnh thổ nước ta nữa. Sử Trung Quốc cũng thừa nhận: “Trong thời Lưu Nghiễm (tức Lưu Cung), Quyền giữ Giao Châu, Nghiễm sai Hồng Thao sang đánh, Hồng Thao tử trận, rồi bỏ không đánh nữa" (Ngũ đại sử ký, q.65).  

Điểm nổi bật trong trận Bạch Đằng là quyết tâm tiêu diệt địch, là tinh thần chủ động, kiên quyết của Ngô Quyền tiêu biểu cho quyết tâm ý chí của dân tộc. Bấy giờ đất nước ta mới giành được độc lập. Chính quyền tự chủ của họ Khúc mới xây dựng còn non trẻ và những hậu quả nặng nề của hơn 1.000 năm Bắc thuộc vẫn chưa dễ gì khắc phục được. Nhà Nam Hán tuy chỉ là một tiểu quốc ở miền đông nam Trung Quốc trong thời đại Ngũ đại thập quốc, nhưng lại là một nước mạnh đủ sức hùng cứ một phương, trấn giữ một vùng dồi dào về nguồn lợi kinh tế. Đặc biệt là về quân sự có một lực lượng thủy quân khá hùng hậu, trang bị nhiều thuyền chiến lớn chắc chắn, và một đội quân cung nỏ rất lợi hại. Vua Nam Hán lại hết sức cay cú vì đã bị Dương Đình Nghệ đánh bại trong trận xâm lược năm 930-931, nên cuối năm 938 cha con Lưu Cung quyết tâm chiếm nước ta. Cuộc kháng chiến chống Nam Hán vì thế diễn ra trong một tình thế hết sức khó khăn. Ngô Quyền với một “đội quân mới họp đất Việt" (Đại Việt sử ký toàn thư) mà phải chống lại hàng vạn quân thiện chiến của nhà Nam Hán, đó quả là một thử thách có ý nghĩa quyết định trên bước đường giành độc lập hoàn toàn của nhân dân ta.  

Thế nhưng đoàn binh thuyền Nam Hán do vua Nam Hán sai con là Hoằng Tháo làm Lãnh hải quân Tiết độ sứ, đổi phong Giao Vương, đem quân sang đánh nước ta, khi vừa tiến vào cửa sông Bạch Đằng đã bị chặn lại và bị đánh tan tành. Toàn bộ đạo quân xâm lược cùng chủ tướng đều bị nhấn chìm trong dòng nước Bạch Đằng.  

Có thể nói trận Bạch Đằng năm 938 là trận quyết chiến chiến lược lớn nhất, có ý nghĩa to lớn nhất trong lịch sử quân sự Việt Nam từ thế kỷ X về trước. Trận đánh đã kế thừa và phát huy có hiệu quả cao truyền thống thủy chiến của dân tộc ta. Cả cuộc chiến tranh chỉ giải quyết nhanh gọn bằng một trận quyết chiến, chỉ diễn ra trong vòng một ngày, bắt đầu từ lúc nước triều lên và kết thúc vào lúc nước triều xuống thấp. Đó là một trận tiêu diệt nhanh, gọn, triệt để nhất, đánh tan quân xâm lược ngay từ cửa ngõ của đất nước.  

Khi tiến hành xâm lược nước ta, trong mưu kế của quân Nam Hán, ngoài đoàn binh thuyền của Hoằng Tháo giữ vai trò chủ công và đạo quân do đích thân vua Nam Hán chỉ huy áp sát biên giới sẵn sàng tiếp ứng khi cần thiết, còn có lực lượng nội ứng của tên phản bội Kiều Công Tiễn ở La Thành. Do vậy, để phá kế hoạch phối hợp của địch, Ngô Quyền đã chủ trương trước hết phải diệt trừ lực lượng phản bội bên trong, sau đó tập trung lực lượng đánh trận thủy chiến quyết định tiêu diệt gọn đạo quân của Hoằng Tháo thật nhanh gọn, khiến vua Nam Hán không kịp trở tay, phải chấp nhận thất bại.  

Trận Bạch Đằng (năm 938) là trận phục kích đường sông kết hợp với vận động tiến công tiêu diệt địch trên sông nước. Lần đầu tiên trong lịch sử chống ngoại xâm của dân tộc, Ngô Quyền đã lợi dụng thế “thiên hiểm” của sông Bạch Đằng để bố trí trận địa phục binh, kết hợp ém binh mai phục với bãi cọc ngầm vót nhọn bịt sắt và lợi dụng nước thủy triều lên xuống để đánh giặc. Sông Bạch Đằng sâu và rộng, núi rừng san sát ven bờ, trên bãi sông và trên các kênh rạch, lau lách và cây cối um tùm, có nhiều nhánh sông và nước triều lên xuống rất mạnh. Việc xác định không gian và thời gian quyết chiến của Ngô Quyền đều nhằm triệt để lợi dụng địa hình, phát huy cao độ uy thế thủy chiến của quân dân ta trong điều kiện thiên thời, địa lợi và nhân hòa để đánh địch. Trận địa cọc ngầm đã có tác dụng to lớn; lối đánh nghi binh lừa và nhử địch vào trận địa phục binh đã được thực hiện chính xác, đúng ý định chủ tướng Ngô Quyền và bộ tham mưu của ông.  

Chiến thắng Bạch Đằng đã thể hiện trình độ tổ chức chỉ huy tài tình, khéo léo, linh hoạt, sáng tạo, kịp thời của Ngô Quyền và các tướng lĩnh. Để trận quyết chiến chiến lược kết thúc thắng lợi trong một lần thủy triều lên xuống là việc không hề đơn giản. Nếu tính toán của ta không chính xác, “lực không mạnh, thế không vững", không buộc địch phải rút chạy đúng thời điểm (thủy triều xuống) thì trận đánh không những không thắng lợi mà có thể phải chịu thất bại nặng nề, đất nước sẽ lại chịu trong cảnh nô lệ.  

Trong trận quyết chiến chiến lược này, Ngô Quyền đã khéo phán đoán, xử lý và dẫn dắt tình huống, chuyển hóa thế trận một cách linh hoạt, có lợi nhất để từng bước phá vỡ đội hình hành quân đường dài của địch, không cho chúng triển khai đội hình chiến đấu, tiêu diệt từng bộ phận, tiến lên đánh bại toàn bộ quân địch. Thắng lợi của trận chiến Bạch Đằng là kết quả nghiên cứu, nắm chắc quy luật tự nhiên, theo dõi chặt chẽ “nhất cử, nhất động” của đạo binh thuyền địch. Từ đó, tính toán nhử, dụ địch vào thế trận bày sẵn của ta để chớp thời cơ tiến công tiêu diệt chúng. Trong suốt trận đánh, Ngô Quyền luôn nắm và giữ quyền chủ động trên chiến trường, vận dụng linh hoạt các thủ đoạn tác chiến: vừa đánh, vừa lui, vận động tiến công kết hợp với cản phá bằng trận địa cọc, truy kích tiêu diệt địch tháo chạy. Với nghệ thuật phát triển cách đánh liên tục, sáng tạo theo tiến độ trận đánh nên quân địch đang từ thế chủ động đã lâm vào bị động đối phó, bất ngờ..., đẩy chúng đến chỗ tuyệt vọng, sụp đổ và bị tiêu diệt hoàn toàn.  

Trận chiến Bạch Đằng đã quy tụ và phát huy sức mạnh của cả dân tộc chống quân Nam Hán xâm lược. Sức mạnh giữ nước trong trận Bạch Đằng là sức mạnh trỗi dậy của cả dân tộc, của chiến tranh nhân dân yêu nước chống giặc ngoại xâm. Với tư duy chiến lược, Ngô Quyền thấy rõ vai trò sức mạnh của dân tộc. Chính vì vậy, ông đã nhanh chóng tập hợp được đông đảo lực lượng chiến đấu và phục vụ chiến đấu. Đặc biệt, sau khi ông đã diệt trừ tên phản bội Kiều Công Tiễn, ổn định được tình hình trong nước, nhân dân khắp nơi đồng tình ủng hộ tham gia kháng chiến, các tướng lĩnh, hào kiệt đồng lòng đứng về phía Ngô Quyền quyết tâm đánh giặc, giữ nước. Vì vậy, chỉ trong thời gian ngắn, lực lượng đã lên tới vài vạn người, nhiều tướng lĩnh tài giỏi từ các nơi đã xung phong theo ông ra trận.

Quân chủ lực của Ngô Quyền chiến đấu trong sự phối hợp với các đội dân binh và sự tham gia phục vụ chiến đấu của toàn dân. Ông còn chủ động khơi dậy tinh thần độc lập dân tộc, cố kết cộng đồng, động viên mọi tiềm lực trong dân, nhất là sức người, sức của cho trận đánh. Khi nghe tin Ngô Quyền dấy binh đánh giặc, nhân dân khắp nơi nô nức mang lương thực, thực phẩm, vũ khí, thuyền chiến tham gia và ủng hộ cuộc kháng chiến. Đặc biệt, quân và dân không quản khó khăn, vất vả, vượt qua đêm tối, mưa rét, tích cực xuyên rừng, vượt núi, chọn và chặt gỗ, vận chuyển đến trận địa đúng quy định.  

Trong lịch sử, kẻ thù của dân tộc ta chủ yếu là các thế lực phong kiến phương Bắc ở sát liền biên giới. Trong nhiều cuộc chiến tranh xâm lược, quân địch thường tiến vào nước ta theo hướng Bắc và Đông Bắc của Tổ quốc. Chúng kết hợp tiến công cả đường bộ và đường thủy, trong đó trên đường thủy quân địch thường theo hướng Vân Đồn - Bạch Đằng tiến vào nội địa nước ta. Chính vì thế, trận Bạch Đằng của Ngô Quyền năm 938 có ý nghĩa mở ra truyền thống đánh giặc trên sông nước Bạch Đằng. Nghệ thuật thủy chiến của Ngô Quyền đã để lại những bài học kinh nghiệm lớn mà tổ tiên ta trong các thế kỷ kế tiếp đã vận dụng thành công. Đó là trận Bạch Đằng năm 981 của Lê Hoàn đánh quân Tống, trận Bạch Đằng năm 1288 đánh quân Nguyên - Mông, thời nhà Trần do Hưng Đạo Vương Trần Quốc Tuấn lãnh đạo...  

Chiến thắng Bạch Đằng chứng tỏ sự trưởng thành của ý thức dân tộc Việt Nam, sự lớn mạnh của nhân dân ta về trí tuệ và khả năng đánh thắng quân thù không chỉ bằng du kích mà cả bằng chính quy, không chỉ trên bộ mà cả bằng thủy chiến. Đó là một thí dụ điển hình về mưu trí, sáng tạo, về sự tính toán chính xác trong nghệ thuật quân sự của dân tộc ta.  

Chiến thắng Bạch Đằng (năm 938) là một chiến thắng bất hủ, một võ công hiển hách trong lịch sử chống ngoại xâm của dân tộc ta, nó đánh dấu một mốc son lịch sử, một bước ngoặt vĩ đại, có ý nghĩa vạch thời đại, hoàn toàn chấm dứt nền thống trị hàng nghìn năm của phong kiến phương Bắc, mở ra một kỷ nguyên mới - độc lập tự chủ thực sự và lâu dài cho toàn dân tộc.  

Hơn ba thế kỷ sau, sử gia Lê Văn Hưu - nhà sử học Việt Nam đầu tiên đã hiểu rõ tầm cỡ và đánh giá rất chuẩn xác về những chiến công trong sự nghiệp giữ nước và dựng nước của Ngô Quyền:

“Tiền Ngô Vương có thể lấy quân mới họp của đất Việt ta mà phá được trăm vạn quân của Lưu Hoằng Tháo, mở nước xưng vương, làm cho người phương Bắc không dám lại sang nữa. Có thể bảo là một cơn giận mà yên được dân, mưu giỏi mà đánh cũng giỏi vậy. Tuy chỉ xưng vương chưa lên ngôi hoàng đế và đổi niên hiệu, mà chính thống của nước Việt ta ngõ hầu đã nối lại được" (Đại Việt sử ký toàn thư, Sđd, trang 147, 148).  

Sau Lê Văn Hưu, nhiều sử gia khác cũng hết lời ca ngợi chiến công hiển hách của Ngô Quyền trong đánh giặc giữ nước và sự nghiệp xây dựng đất nước, mở đầu kỷ nguyên độc lập tự chủ của dân tộc ta.
Sử gia Ngô Sĩ Liên cũng bàn rằng: "Lưu Cung tham đất của người ta, muốn mở rộng bờ cõi, đất chưa lấy được mà đã chết mất con và hại nhân dân" (Đại Việt sử ký toàn thư, Sđd, tr. 146).  

Nhà yêu nước Phan Bội Châu, vào đầu thế kỷ XX đã xếp Ngô Quyền là Vị tổ trung hưng của nước ta, đứng sau vị thủy tổ dựng nước đầu tiên là Hùng Vương và đứng trước vị anh hùng trung hưng thứ hai là Lê Lợi với những lời lẽ như sau: "Tất phải giặc ngoài mà đuổi đi được, quyền thống của nước bị đứt mà biết nối lại được, thì không ai hơn được Ngô Quyền" (Phan Bội Châu, Việt Nam quốc sử khảo, Nxb. Giáo dục, H. 1962, trang 22-23).

Chiến thắng Bạch Đằng (năm 938) đã thực sự đưa đất nước ta, nhân dân ta thoát khỏi hiểm họa bị diệt vong sau hàng nghìn năm bị dày xéo bởi ách đô hộ ngoại bang. Chiến công chói lọi này đã gắn liền với tên tuổi vị anh hùng dân tộc Ngô Quyền, xứng đáng là một chiến công mở màn cho mọi chiến công trong lịch sử chống ngoại xâm, đánh giặc cứu nước của dân tộc ta ở thế kỷ X.

Sau chiến thắng Bạch Đằng, đất nước ta bước vào thời kỳ xây dựng và bảo vệ Tổ quốc trên quy mô lớn. Đó là kỷ nguyên văn minh Đại Việt, của Văn hóa Thăng Long, kỷ nguyên phá Tống, bình Chiêm, đuổi Minh, một kỷ nguyên văn trị võ công rực rỡ của những triều đại Đinh, Lê, Lý, Trần và Lê Sơ. Nhà sử học Ngô Thì Sỹ thế kỷ XVIII qua Việt sử tiêu án đã đánh giá đúng: "Trận thắng trên sông Bạch Đằng là cơ sở cho việc khôi phục quốc thống. Những chiến công đời Đinh, Lê, Lý, Trần sau này còn nhờ dựa vào uy danh lẫm liệt ấy để lại. Trận Bạch Đằng là vũ công cao cả vang dội đến nghìn thu, há phải chỉ lẫy lừng ở một thời bấy giờ mà thôi đâu”.', 'TEXT', '2026-06-05 05:16:11.372337', '2026-06-06 09:58:44.588808', '2026-06-06 09:58:44.182127', 'DRAFT'), ('a1cb68e1-9149-4aee-827b-fa92e15dc1b8', '687b57fe-865c-496a-83b3-f83690885dd1', '389ffbf2-0f19-4478-96e2-9a36f17d25b3', 'CONTEXT', 'Chi tiết trận Điện Biên Phủ trên không', null, 'Năm 1972, năm thứ 18 của cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam. Năm có tầm quan trọng quyết định về chiến lược trên các mặt trận quân sự, chính trị, ngoại giao. Năm đòi hỏi quân và dân ta phải nỗ lực vượt bậc để giành thắng lợi lớn trên chiến trường, tạo thế và lực có lợi cho ta.  Sau cuộc tiến công chiến lược đầu năm 1972 của quân và dân ta trên chiến trường miền Nam Việt Nam, chiến lược “Việt Nam hóa chiến tranh” của đế quốc Mỹ có nguy cơ bị sụp đổ hoàn toàn.  Để cứu vãn tình thế, đế quốc Mỹ buộc phải “Mỹ hóa” trở lại cuộc chiến tranh ở miền Nam, đồng thời tiến hành cuộc chiến tranh phá hoại lần thứ hai đối với miền Bắc. Đế quốc Mỹ coi đó là biện pháp quyết định hòng cứu nguy cho sự sụp đổ của quân ngụy Sài Gòn - xương sống của chiến lược “Việt Nam hóa chiến tranh".  Ngày 6 tháng 4 năm 1972, máy bay và tàu chiến Mỹ mở Chiến dịch Linebacker I (Sấm rền I). Sau 10 ngày đêm ném bom đánh phá dữ dội vùng phía bắc khu phi quân sự, thành phố Vinh, Bến Thủy (Nghệ An), Thanh Hóa và nhiều nơi khác thuộc Quân khu 4, ngày 16 tháng 4 năm 1972, Mỹ cho máy bay B52 ném bom thành phố Hải Phòng. Cùng ngày, vào hồi 9 giờ 30 phút đến 10 giờ 10 phút hơn 60 lần chiếc máy bay chiến thuật của Mỹ chia thành nhiều tốp ném bom Thủ đô Hà Nội. Các lực lượng phòng không chủ lực và dân quân tự vệ bảo vệ thành phố nổ súng, đánh trả địch quyết liệt.  Trận đánh vừa kết thúc, thường vụ Thành ủy và thường trực Ủy ban Hành chính thành phố họp đột xuất quyết định sơ tán khỏi nội thành từ 25 đến 30 vạn người. Sau 4 ngày khẩn trương thực hiện, cộng với sơ tán trước, Hà Nội đã chuyển ra khỏi nội thành 26 vạn người. Đến ngày 25 tháng 4, tình hình có chiều hướng căng thẳng hơn, thành phố quyết định sơ tán thêm 10 vạn người nữa ở nội thành, đồng thời dự kiến các bước sơ tán tiếp theo: Tình hình địch đánh phá ở mức độ chưa cao, sơ tán khỏi nội thành từ 25 đến 30 vạn; tình huống địch đánh phá ác liệt, sơ tán khỏi nội thành 45 đến 50 vạn người. Chỉ để lại nội thành 10 đến 15 vạn người gồm các lực lượng chiến đấu và phục vụ chiến đấu.  Sau 4 tuần lễ đánh trả các cuộc tiến công bằng không quân và hải quân Mỹ, quân dân miền Bắc đã bắn rơi 90 máy bay, bắn cháy 20 tàu chiến, bắt sống nhiều giặc lái. Đế quốc Mỹ vẫn không thể ngăn cản được cuộc tiến công của quân và dân ta ở miền Nam, không giành được thế mạnh ở Hội nghị Paris.  Trước tình hình đó, ngày 8 và 9 tháng 5 năm 1972, tổng thống Ních-xơn triệu tập Hội đồng An ninh Quốc gia Mỹ quyết định đẩy mạnh cường độ ném bom đồng thời dùng mìn, thủy lôi phong tỏa các hải cảng miền Bắc Việt Nam nhằm cắt đứt đến mức tối đa mọi nguồn chi viện quốc tế cho cuộc kháng chiến của nhân dân ta, “làm cho Hà Nội không có được các vũ khí và đồ tiếp tế cần thiết để tiếp tục chiến tranh” (Tuyên bố của Ních-xơn. Dẫn theo Tài liệu mật Bộ Quốc phòng Mỹ, Nxb. Thông tin lý luận, H., 1986, tr.382).  Ngày 10 và 11 tháng 5 năm 1972, đế quốc Mỹ huy động hơn 100 lần chiếc máy bay ném bom đánh phá Hà Nội. Cầu Long Biên, ga Yên Viên, ga Gia Lâm, sân bay Bạch Mai là những mục tiêu chính của đợt đánh phá này. Các lực lượng phòng không và không quân bảo vệ Hà Nội đánh trả chúng quyết liệt, bắn rơi 12 máy bay. Đặc biệt trận địa súng máy cao xạ 14,5mm (ba khẩu) của tự vệ nhà máy điện Yên Phụ đã đánh một trận xuất sắc vào 12 giờ trưa ngày 10 tháng 5, bắn rơi một chiếc F4.  Từ tháng 6 đến tháng 9 năm 1972, quân dân thủ đô đã liên tục chiến đấu bắn rơi nhiều máy bay Mỹ, bắt sống nhiều giặc lái, trong đó có chiếc máy bay thứ 3.700 bị bắn rơi trên miền Bắc (ngày 27 tháng 6 năm 1972) và chiếc máy bay thứ 300 bị bắn rơi trên bầu trời Hà Nội (ngày 7 tháng 7 năm 1972).  Nhằm tạo thêm sức mạnh trước khi có thể đạt được một giải pháp chính trị có lợi ở Hội nghị Paris và tạo lợi thế cho cuộc chiến tranh cử tổng thống sắp tới, Ních-xơn quyết định tiếp tục tiến công Thủ đô Hà Nội quyết liệt hơn. Đó là con đường, là chìa khóa mà Nhà Trắng và Lầu Năm Góc đã chọn và cho rằng có thể đạt được mục đích sớm nhất.  Ngày 2 tháng 9 năm 1972, hơn 40 lần chiếc máy bay thay nhau đánh phá sân bay Nội Bài và khu vực Đông Anh. Ngày 10 tháng 9, 50 lần chiếc vào đánh phá cầu Long Biên (lần thứ tư), sân bay Gia Lâm và nhiều nơi khác. Ngày 11 tháng 9, chúng bắn tên lửa xuống phố Bà Triệu. Ngày 11 tháng 10, máy bay Mỹ tiếp tục ném bom Hà Nội phá hủy nhiều công trình kinh tế, văn hóa, giao thông vận tải, khoa học kỹ thuật, bệnh viện... Tòa nhà chính của cơ quan Tổng đại diện Pháp ở phố Trần Hưng Đạo bị trúng bom. Ông Tổng đại diện Pháp Xôxini và một số nhân viên sứ quán bị bom Mỹ giết hại.  Với cuộc bầu cử tổng thống nước Mỹ vào tháng 11 năm 1972, chiến tranh ở Việt Nam trở thành vấn đề quan trọng hàng đầu phải giải quyết nếu Ních-xơn muốn trúng cử tổng thống thêm một nhiệm kỳ nữa. Đầu tháng 10 năm 1972, phái đoàn ta ở Hội nghị Paris chủ động đưa ra bản dự thảo hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam. Trước tình thế bất lợi trên cả hai miền Nam, Bắc Việt Nam, trước sự phản đối của dư luận quốc tế và nước Mỹ, ngày 20 và 22 tháng 10 năm 1972, tổng thống Mỹ gửi thông điệp cho Thủ tướng Chính phủ ta hoan nghênh thiện chí của Việt Nam Dân chủ Cộng hòa, hứa hẹn có thể ký hiệp định chính thức vào ngày 31 tháng 10.  Tuy nhiên với bản tính tráo trở, Ních-xơn tìm mọi cách dây dưa trì hoãn việc ký hiệp định như đã hứa, đồng thời ráo riết tiến hành bước phiêu lưu mới. Ngày 26 tháng 10 năm 1972, Chính phủ ta ra tuyên bố về Tình hình cuộc đàm phán về vấn đề Việt Nam hiện nay nêu rõ lập trường chính nghĩa, thái độ thiện chí của ta, vạch trần sự tráo trở của chính quyền Mỹ, đòi Mỹ phải thực hiện nghiêm chỉnh những vấn đề đã thỏa thuận. Ngày 8 tháng 11 năm 1972, Ních-xơn trúng cử tổng thống Mỹ nhiệm kỳ hai. Ngay sau đó, Mỹ trắng trợn lật lọng, đòi phải sửa chữa lại 126 điểm trong bản dự thảo hiệp định mà trước đó đã thỏa thuận với ta. Do sự lật lọng của Mỹ, Hội nghị Paris bế tắc. Ngày 13 tháng 12 năm 1972, Hen-ri Kit-xinh-giơ, cố vấn đặc biệt của phái đoàn Mỹ tuyên bố bỏ họp vô thời hạn.  Ngày 14 tháng 12 năm 1972, với lời lẽ như một tối hậu thư, tổng thống Mỹ gửi điện cho Chính phủ ta đòi trong vòng 72 giờ tới phải trở lại bàn đàm phán ở Paris phải chấp nhận những yêu cầu của Mỹ, nếu không Mỹ sẽ ném bom trở lại. Cùng với việc gửi điện cho Chính phủ ta, Ních-xơn ra lệnh cho Bộ chỉ huy không quân chiến lược và chiến thuật thực hiện cuộc tập kích bằng máy bay chiến lược B52 vào Hà Nội, Hải Phòng. 193 máy bay chiến lược B52, gần 50 máy bay F111 cùng hơn 1.000 máy bay chiến thuật, 6 liên đội tàu sân bay và hàng chục máy bay tiếp dầu KC135... được huy động cho cuộc tập kích chiến lược mang mật danh Chiến dịch Linebacker II (Sấm rền II). Mục đích của chiến dịch Linebacker II là tàn phá Hà Nội, Hải Phòng hòng đánh sụp ý chí của nhân dân ta, phá hoại tiềm lực kinh tế quốc phòng, ngăn chặn nguồn tiếp tế của ta cho chiến trường miền Nam, giúp cho chính quyền ngụy Sài Gòn có điều kiện củng cố lực lượng, buộc Chính phủ ta phải chấp nhận các điều kiện của Mỹ.  B52 là loại máy bay ném bom chiến lược của không quân Mỹ, có thể hoạt động ban đêm, trong điều kiện thời tiết phức tạp, ném bom ở độ cao từ 9.000 đến 11.000 mét. Từ khi tham chiến ở Việt Nam (năm 1965), máy bay B52 đã nhiều lần được cải tiến, đặc biệt là hệ thống tự bảo vệ. Đến tháng 12 năm 1972, mỗi máy bay B52 đã trở thành một trung tâm tác chiến điện tử với 16 máy gây nhiễu tích cực bằng điện tử, 2 máy gây nhiễu tích cực bằng sợi kim loại (khi hoạt động có thể phủ trắng một khu vực rộng 450 kilômét vuông) và 2 quả tên lửa khi phóng ra sẽ có tín hiệu như B52 để đánh lừa ra-đa đối phương. Mỗi chiếc B52 được ví như một kho bom lưu động trên không có thể mang được 30 tấn bom. Mỗi tốp (ba chiếc) có thể rải thảm từ 80 đến 90 tấn bom trên một diện rộng, có thể thay thế cho 120 - 200 máy bay ném bom chiến thuật, hiệu quả lại cao hơn.  Với sức mạnh tàn phá to lớn của máy bay B52, đế quốc Mỹ cho rằng chỉ cần mở chiến dịch tập kích trong 3 ngày cũng đủ phá hủy Hà Nội, Hải Phòng. Sau nhiều lần xuất kích mà chưa bị trừng trị, đặc biệt là sau vụ ném bom rải thảm thành phố cảng Hải Phòng (ngày 16 tháng 4 năm 1972), giới quân sự Mỹ càng chủ quan cho rằng B52 có thể đánh bất kỳ mục tiêu nào của Bắc Việt Nam. Chúng tin rằng sử dụng loại vũ khí chiến lược này có thể đè bẹp ý chí chiến đấu của quân và dân ta, buộc ta phải khuất phục, chấp nhận các điều khoản của Mỹ, đồng thời để chứng tỏ với thế giới sức mạnh của “thần tượng không lực Hoa Kỳ”. Chúng cũng dự tính rằng hệ thống phòng không của Bắc Việt Nam sẽ không thể phát huy được hiệu quả trước đòn tiến công của B52 và tỉ lệ tổn thất của B52 là không đáng kể.  Việc đế quốc Mỹ sử dụng máy bay chiến lược B52 đánh phá Hà Nội không phải là điều bất ngờ đối với ta. Năm 1967, khi làm việc với Bộ tư lệnh Phòng không - Không quân, Chủ tịch Hồ Chí Minh đã căn dặn: “Sớm muộn rồi đế quốc Mỹ cũng sẽ đưa B52 ra đánh Hà Nội, rồi có thua nó mới chịu thua. Phải dự kiến trước tình huống càng sớm càng tốt để có thời gian mà suy ngẫm chuẩn bị" (Viện Lịch sử quân sự Việt Nam, Chiến thắng B52, Nxb. Quân đội nhân dân, H.1997, tr.44). Thực hiện lời dặn của Chủ tịch Hồ Chí Minh, chúng ta đã có bộ phận vào chiến trường nghiên cứu đánh B52 và chuẩn bị kế hoạch đánh B52 bảo vệ Thủ đô Hà Nội.  Khi cuộc chiến tranh phá hoại lần thứ hai bắt đầu, qua đối chọi liên tục với máy bay B52 trên bầu trời các tỉnh Quảng Bình, Vĩnh Linh, Nghệ An, Thanh Hóa, chúng ta đã tổng kết được nhiều kinh nghiệm bổ ích trong phòng chống và đánh trả. Đến năm 1972, việc nghiên cứu cách đánh B52 càng được chú ý. Tháng 7 năm 1972 Bộ tổng tham mưu Quân đội nhân dân Việt Nam chỉ thị cho Quân chủng Phòng không - Không quân thực hiện gấp việc tiếp tục nghiên cứu về triển khai kế hoạch đánh máy bay B52, biên soạn tài liệu huấn luyện bộ đội đánh máy bay B52 trong các tình huống phức tạp. Tháng 11 năm 1972 hội nghị chuyên đề đánh B52 của bộ đội tên lửa được tổ chức tại sở chỉ huy Sư đoàn phòng không 361 bảo vệ Hà Nội. Sau hội nghị, tài liệu “Cách đánh B52" được chính thức phát hành. Một số sân bay dã chiến được gấp rút xây dựng. Các biện pháp nghi binh, lừa địch, bố trí đội hình ra-đa để phát hiện địch kịp thời được triển khai khẩn trương. Công tác hậu cần, kỹ thuật được chuẩn bị chu đáo, đặc biệt là bổ sung đạn dược cho lực lượng cao xạ và xăng dầu cho máy bay.  Tại Hà Nội, công tác chuẩn bị chiến đấu cũng hết sức khẩn trương. Thành phố gấp rút cho sơ tán người già, trẻ em và những người không có nhiệm vụ chiến đấu, sản xuất ra khỏi nội thành với thời hạn phải hoàn thành trước ngày 4 tháng 12 năm 1972. Đến ngày 18 tháng 12 năm 1972 nội thành đã sơ tán được khoảng 20 vạn người. Các trọng điểm ở ngoại thành được sơ tán khá triệt để. Việc tu sửa, nạo vét hầm hố nhanh chóng triển khai. Công tác chuẩn bị được đặc biệt chú ý. Bộ tư lệnh Thủ đô và Hội đồng Phòng không nhân dân thành phố đã kiểm tra, chấn chỉnh lại hệ thống đài quan sát, xây dựng thêm một số cơ sở mới và sửa chữa cơ sở cũ hư hỏng. Hệ thống thông báo, báo động cũng được kiểm tra bảo đảm yêu cầu nhanh nhạy, rộng khắp. Lực lượng dân quân tự vệ được trang bị thêm nhiều súng đạn và được học tập về kỹ thuật, cách đánh. Nhiều trận địa mới được xây dựng. Các cơ quan, xí nghiệp chuẩn bị xe, máy, người sẵn sàng cơ động khắc phục hậu quả khi có lệnh. Cả Hà Nội sục sôi với hàng ngàn công việc cho trận quyết chiến sắp đến. Sự chuẩn bị chu đáo về mọi mặt tạo cơ sở vững chắc cho trận đánh B52 sắp tới.  Trước đó, ngày 27 tháng 11 năm 1972, lực lượng phòng không bảo vệ Hà Nội được phổ biến nhận định của Bộ Tổng tư lệnh: “Địch sẽ đánh phá trở lại miền Bắc với mức độ ác liệt hơn, kể cả dùng B52 đánh ồ ạt vào Hà Nội, Hải Phòng". Cùng ngày, Quân chủng Phòng không - Không quân nhận được lệnh “tập trung mọi khả năng, nhằm đúng đối tượng B52 mà tiêu diệt". Với tinh thần chủ động, khẩn trương, ngày 4 tháng 12 năm 1972, Quân chủng chính thức báo cáo lên Bộ tổng tham mưu mọi công tác chuẩn bị đánh B52 đã xong, phương án đánh B52 đã sẵn sàng.  Giữa tháng 12 năm 1972, Hội đồng Phòng không và Bộ tư lệnh Thủ đô Hà Nội tổ chức diễn tập chiến đấu khắc phục hậu quả trên phạm vi toàn thành phố. Ngoài lực lượng thường trực chiến đấu, hệ thống còi loa báo động, thông tin liên lạc, đài quan sát cũng như lực lượng khắc phục hậu quả qua diễn tập có nhiều tiến bộ. Tuyến y tế từ thành phố xuống cơ sở có thể cấp cứu 5 nghìn người một ngày, các đội cứu sập, cứu hỏa ở các tuyến được bổ sung thêm phương tiện, thiết bị. Kế hoạch sửa chữa điện, nước, chôn cất người bị nạn, vệ sinh môi trường... được các ngành chuẩn bị với khả năng cao nhất.  Tình hình ngày càng khẩn trương, ngoài Sở Giao thông vận tải thành phố, Nhà nước thành lập Ban bảo đảm giao thông vận tải khu vực do đồng chí Đỗ Mười, Phó Thủ tướng Chính phủ làm Trưởng ban. Các bến phà qua Sông Hồng ở khu vực Chương Dương, Khuyến Lương, Chèm và một số cầu phao, phà qua sông Đuống được gấp rút củng cố. Ngành giao thông vận tải đường sắt đã vận dụng thành tựu khoa học kỹ thuật lắp ráp thành công phà và cầu phao cho xe lửa. Cầu phao cho xe lửa có sức tải lớn nhưng không thuận tiện trong mùa mưa lũ, vì vậy phương tiện chủ yếu chuyển tàu hỏa qua sông là phà xe lửa. Trong thời điểm cuối tháng 11 đầu tháng 12 năm 1972, tại phía nam cảng Sông Hồng, bằng 2 chiếc phà xe lửa, đội cầu đường Hà Nội - Thái Nguyên đã vận chuyển được một khối lượng hàng hóa lớn. Trung bình một ngày đêm có 24 lượt toa tàu với hàng ngàn tấn hàng được chuyển từ bờ bắc sang bờ nam. Hàng qua sông chủ yếu là vũ khí nặng và trang bị kỹ thuật quân sự. Phà xe lửa được ghi nhận như một công trình khoa học mới của ngành giao thông vận tải đường sắt nước ta. Nó được áp dụng đúng lúc, có hiệu quả, góp phần tích cực cùng các phương tiện khác đáp ứng nhu cầu vận chuyển, phục vụ kháng chiến.  Trải qua hơn 6 tháng chiến đấu, đến tháng 12 năm 1972, lực lượng trực tiếp chiến đấu bảo vệ thủ đô có 4 trung đoàn không quân tiêm kích, 3 trung đoàn tên lửa, 6 trung đoàn pháo cao xạ, một số tàu hải quân. Dân quân tự vệ thủ đô có 4 đại đội cao xạ 100 mm (20 khẩu), 92 trận địa súng máy cao xạ 14,5mm, hơn 100 trận địa súng 12,7mm, đại liên, trung liên. Ngoài ra còn có hơn 4 vạn súng trường, tiểu liên, súng cối, ĐKZ tạo thành lưới lửa phòng không tầm thấp đồng thời sẵn sàng cơ động đánh địch đổ bộ đường không và truy lùng giặc lái Mỹ nhảy dù.  Một số tỉnh giáp với Hà Nội như Hà Bắc, Vĩnh Phú, Hà Tây, Hải Hưng, Nam Hà (địa danh hành chính thời kỳ này)... cũng đã sẵn sàng phương án tác chiến và khắc phục hậu quả, hỗ trợ cho Hà Nội. Để đảm bảo liên lạc thông suốt, kịp thời, lực lượng thông tin của Bộ tư lệnh Thủ đô và Bộ tư lệnh Thông tin kết hợp với thông tin bưu điện nối liền các mạng liên lạc điện thoại và vô tuyến điện tử Trung ương xuống thành phố và các huyện. Ngoài ra còn có xe mô tô, xe đạp và các tổ truyền đạt chạy bộ từ xã, huyện lên thành phố.  Qua gần 2 tháng tạm ngừng, ngày 17 tháng 12 năm 1972, Mỹ ném bom trở lại tỉnh Thái Bình, thả bổ sung thủy lôi và bắn tên lửa xuống cảng và thành phố Hải Phòng. Điều này càng làm rõ nhận định của ta: địch sẽ đánh phá trở lại miền Bắc, kể cả dùng máy bay ném bom Thủ đô Hà Nội. Đây cũng là thử thách cao nhất của quân dân miền Bắc, đặc biệt là quân dân Hà Nội trong cuộc chiến tranh nhân dân đánh thắng chiến tranh phá hoại của đế quốc Mỹ.  Theo dõi chặt chẽ mọi âm mưu thủ đoạn của địch, 8 giờ sáng ngày 18 tháng 12 năm 1972, Bộ Quốc phòng điện nhắc các đơn vị pháo cao xạ, tên lửa, không quân, pháo binh đẩy mạnh công tác chuẩn bị sẵn sàng chiến đấu cao, kịp thời đánh trả máy bay, tàu chiến địch.  Đêm ngày 18 tháng 12, đế quốc Mỹ huy động 90 lần chiếc máy bay chiến lược B52, 135 lần chiếc máy bay chiến thuật xuất phát từ đảo Guam và từ các căn cứ không quân ở Thái Lan lao về hướng Hà Nội. Đội hình máy bay địch kéo dài hàng chục kilômét được màn nhiễu điện tử che phủ ngược sông Mê Kông lên Tây Bắc rồi theo các dải núi bay vào Hà Nội. Đồng thời, hàng trăm lần chiếc máy bay chiến thuật cũng lao vào đánh phá Hải Phòng và một số địa phương miền Bắc.  19 giờ 10 phút, các đài ra-đa cảnh giới từ xa của ta đã phát hiện chính xác và kịp thời báo cáo về sở chỉ huy trung tâm: B52 đang bay vào Hà Nội. 19 giờ 25 phút, không quân ta cất cánh đón đánh các tốp máy bay chiến thuật Mỹ. Các đài ra-đa của các trận địa tên lửa cũng bắt đầu thu được tín hiệu của B52. Sở chỉ huy Bộ tư lệnh Thủ đô ra lệnh báo động toàn thành phố. Lập tức còi báo động từ Nhà hát lớn, Quảng trường Ba Đình, ga Hàng Cỏ và nhiều nơi khác nổi lên khẩn cấp. Trên hệ thống loa truyền thanh, Sở chỉ huy phát đi thông báo, máy bay Mỹ đã vào Hà Nội và ra lệnh cho các lực lượng chiến đấu kiên quyết đánh trả, bảo vệ thủ đô.  Từ 19 giờ 40 phút đến 20 giờ 18 phút, nhiều tốp máy bay B52 (mỗi tốp 3 chiếc) giội bom xuống các khu vực sân bay Nội Bài, Đông Anh, Yên Viên, Gia Lâm và nhiều nơi khác. Cuộc chiến đấu giữa lực lượng phòng không ta và máy bay địch diễn ra vô cùng ác liệt. Những loạt đạn tên lửa, pháo cao xạ ở phía tây và bắc thành phố bắn liên tiếp làm sáng rực bầu trời trong đêm. Tiểu đoàn 59 tên lửa do tiểu đoàn trưởng Nguyễn Thăng chỉ huy đã bắn rơi chiếc máy bay B52 đầu tiên. Chiếc máy bay bị nổ tung rơi xuống cánh đồng giữa hai xã Phù Lỗ và Đồng Xuân thuộc tỉnh Vĩnh Phú (nay là tỉnh Phú Thọ và Vĩnh Phúc). Đây là chiếc B52 đầu tiên bị bắn rơi tại chỗ trên bầu trời Hà Nội, cũng là chiếc B52 đầu tiên bị bắn tan xác tại chỗ trên chiến trường Việt Nam và Đông Dương.  Cùng lúc đó, một tiểu đoàn tên lửa khác của ta vừa phát hiện được địch, chưa kịp bắn đã bị tên lửa của chúng phóng xuống trận địa, làm một số cán bộ, chiến sĩ thương vong, khí tài bị hư hỏng. Các trung đoàn cao xạ 260, 212 bảo vệ khu vực sân bay Nội Bài, Cầu Đuống, Gia Lâm... cũng bị máy bay B52 ném bom vào trận địa. Mặc bom đạn dữ dội, ở hai xã Đồng Xuân và Phù Lỗ, nơi máy bay B52 rơi, cuộc đuổi bắt giặc lái Mỹ làm náo động cả một khu vực. Các cán bộ xã đội Đoàn Tấu, Trịnh Soi, Nguyễn Văn Lâm dẫn quân cơ động cùng nhân dân lùng sục từng bụi tre, vườn chuối. Bọn giặc lái, tên lơ lửng trên bụi tre gai, tên nằm úp mặt giữa hai luống cày, có tên chưa kịp tháo dù đã bị bắt trói. Được tận mắt nhìn thấy máy bay B52 cháy và rơi tại chỗ, quân dân thủ đô có thêm sức mạnh, càng chiến đấu bền bỉ, kiên cường.  2 giờ sáng ngày 19 tháng 12 (cách đợt một 4 giờ) máy bay B52 vào ném bom Hà Nội lần thứ hai và đến 4 giờ 30 phút là đợt ném bom thứ ba. Đợt này chúng rải thảm xuống khu vực Đài Phát thanh Tiếng nói Việt Nam ở Mễ Trì, xã Nhân Chính, nhà máy cao su Sao Vàng... Các trận địa tên lửa và pháo cao xạ liên tục đánh trả địch. Tiểu đoàn 77 tên lửa từ khu vực Chèm phóng đạn, tiêu diệt 1 máy bay B52. Xác chiếc máy bay này rơi xuống cánh đồng xã Tân Hưng, huyện Thanh Oai. Tên giặc lái bị bắt nói y đã lái chiếc máy bay B52D này cất cánh từ căn cứ Utapao lúc 2 giờ sáng. Mục tiêu ném bom là Đài Phát thanh Tiếng nói Việt Nam. Bom B52 đã phá hỏng cột ăng-ten cùng một số thiết bị, đài phải tạm ngừng hoạt động. Nhưng chỉ sau 9 phút, Đài phát thanh dự bị được đưa vào hoạt động và Tiếng nói Việt Nam phát thanh từ Hà Nội, thủ đô nước Việt Nam Dân chủ Cộng hòa lại dõng dạc công bố với cả nước và thế giới về tội ác của đế quốc Mỹ trong đêm 18 rạng ngày 19 tháng 12 năm 1972 ở Hà Nội.  Sau ngày 19 tháng 12, qua Đài Phát thanh Tiếng nói Việt Nam, Chính phủ ta cực lực lên án, tố cáo đế quốc Mỹ dùng máy bay B52 ném bom dã man Thủ đô Hà Nội, đồng thời kêu gọi quân dân cả nước kiên cường chiến đấu, bắt quân thù phải đền nợ máu. Đài Tiếng nói Việt Nam cũng thông báo lần đầu tiên trong lịch sử chống chiến tranh phá hoại - cũng là lần đầu tiên trên thế giới, quân dân Hà Nội đã bắn rơi 3 máy bay chiến lược B52 (2 chiếc rơi tại chỗ), bắt sống nhiều giặc lái.  Đêm 18 tháng 12 năm 1972, gần 1 triệu người Hà Nội gần như không ngủ. Hàng chục triệu người ở các tỉnh, thành phố khác cũng hướng về Hà Nội xúc động, lo âu. Nhưng Hà Nội vẫn đứng vững. Các cơ quan lãnh đạo Đảng, Nhà nước và quân đội vẫn làm việc ở những căn hầm trong thành phố. Ngoài việc chỉ đạo quân dân cả nước, Bộ Chính trị, Trung ương Đảng, Chính phủ và Bộ Tổng tư lệnh đặc biệt chú trọng theo sát chỉ đạo cuộc chiến đấu của thủ đô. Giữ vững thủ đô lúc này là giữ vững niềm tin cho cả nước. Sau trận đánh, Đại tướng Võ Nguyên Giáp, Bộ trưởng Quốc phòng, Tổng tư lệnh quân đội đã đến ngay một số đơn vị phòng không và khu vực Đông Anh, Yên Viên vừa bị máy bay B52 ném bom, nghiên cứu thực địa và động viên bộ đội. Cũng trong buổi sáng ngày 19 tháng 12, trong buổi giao ban cán bộ chủ chốt Bộ tổng tham mưu do Thượng tướng Văn Tiến Dũng, Tổng Tham mưu trưởng chủ trì đã đặt ra nhiều cách giải quyết cấp bách cho cuộc đánh trả của Thủ đô Hà Nội, đặc biệt với lực lượng phòng không - không quân.  Những trận bom đêm 18 tháng 12 của không quân chiến lược Mỹ vào Hà Nội gây xúc động mạnh và làm chấn động dư luận quốc tế. Chính phủ Liên Xô lên án Mỹ trắng trợn xâm phạm thủ đô của một nước có chủ quyền. Chủ tịch Hội đồng Bộ trưởng Bugaria, Phó Chủ tịch Hội đồng Bộ trưởng Ba Lan, Đảng Cộng sản Nhật Bản, Bộ Ngoại giao Trung Quốc... ra tuyên bố lên án tội ác của Mỹ, ủng hộ cuộc chiến đấu anh dũng của nhân dân ta. Nhiều nước trung lập và tư bản chủ nghĩa cũng tỏ thái độ phản đối hành động tàn bạo của Mỹ. Tổng thống Ghi-nê, Thủ tướng Đan Mạch, các Bộ Ngoại giao Ấn Độ, Pháp, Phần Lan, Thụy Điển, Hà Lan... ra tuyên bố hoặc gửi điện trực tiếp cho Tổng thống Mỹ yêu cầu lập tức chấm dứt tội ác và hoàn toàn chịu trách nhiệm trong cuộc tàn sát đẫm máu này.  Với nhân dân Việt Nam, việc Mỹ dùng máy bay B52 ném bom Thủ đô Hà Nội đã gây xúc động lớn trong tình cảm mỗi người, nhất là đồng bào và chiến sĩ đang chiến đấu ở chiến trường miền Nam. Là những người đã từng chịu nhiều thảm cảnh do máy bay B52 gây ra, đồng bào và chiến sĩ ta ở miền Nam hiểu Hà Nội đang phải chịu đựng những tổn thất to lớn. Trả thù cho người thân ở địa phương, chia lửa với Hà Nội, chiến sĩ quân giải phóng cùng đồng bào càng quyết tâm chiến đấu, đập tan các cuộc phản kích của địch, giữ vững vùng giải phóng. Thành ủy Sài Gòn - Gia Định đã thông qua quyết định mở cuộc tiến công quân sự và chính trị ở thành phố Sài Gòn theo truyền thống Hà Nội gọi, Sài Gòn trả lời.  Do có kế hoạch chuẩn bị chu đáo và sự chỉ đạo, chỉ huy chặt chẽ, ngay đêm đầu tiên Hà Nội đã đánh trả địch có hiệu quả. Chiến thắng trận đầu khẳng định Thủ đô Hà Nội nhất định sẽ được bảo vệ vững chắc. Rồng lửa Thăng Long lần đầu tiên trên thế giới đánh gục tại chỗ thần tượng pháo đài bay ngay giữa lòng Hà Nội.  Với ý đồ không cho đối phương kịp khắc phục hậu quả, những trận bom trong đêm vừa dứt, Mỹ tiếp tục cho các loại máy bay ném bom chiến thuật ồ ạt vào đánh phá ban ngày. Cùng với chiến đấu, việc khắc phục hậu quả và tổ chức sơ tán trở thành nhiệm vụ cấp bách của thành phố. Đồng chí Trần Duy Hưng, Chủ tịch Ủy ban Hành chính thành phố ra lệnh sơ tán cấp tốc người già, trẻ em và những người không có nhiệm vụ ở lại nội thành. Những người còn lại phải phân tán. Cấp tốc sửa chữa và đào thêm hầm hào. Các lực lượng khắc phục hậu quả sẵn sàng cơ động làm nhiệm vụ. Các khu phố, huyện, các ngành, đoàn thể đình chỉ những cuộc hội họp. Học sinh tạm thời nghỉ học. Phân tán, giải tỏa hàng hóa, kho tàng. Thủ tướng Chính phủ cũng chỉ thị cho các bộ, các ngành trực thuộc Trung ương chấp hành nghiêm túc các quy định của thành phố.  Đêm chiến đấu đầu tiên tuy giành được thắng lợi, nhưng lực lượng phòng không bảo vệ thủ đô gặp không ít khó khăn. Do chưa có kinh nghiệm chiến đấu liên tục với quy mô lớn, hầu hết các đơn vị hỏa lực tầm cao đã tiêu thụ quá mức cơ số đạn. Trận địa pháo 100mm của tự vệ khu phố Đống Đa bắn đến gần sáng thì hết đạn. Nhiều tiểu đoàn tên lửa cũng trong tình trạng đó. Có đơn vị đã phải phóng quả đạn tên lửa cuối cùng. Sư đoàn 361 và Quân chủng Phòng không - Không quân cấp tốc điều chỉnh đạn trong các đơn vị, đồng thời tổ chức thêm hai dây chuyền lắp ráp đạn tên lửa cho khu vực Hà Nội. Bộ Tư lệnh Thủ đô và các khu, huyện cũng khẩn trương điều động, bổ sung, thay thế người và vũ khí bị tổn thất. Bốn trận địa pháo 100mm của tự vệ được tiếp thêm đạn. Trận địa 14,5mm của dân quân xã Mễ Trì và một số nơi khác bị bom phá hủy được thay thế bằng súng máy 12,7mm.  Thực hiện âm mưu đánh quyết liệt, liên tục, đêm 19 tháng 12, máy bay B52 lại nối tiếp nhau ném bom Hà Nội và Hải Phòng. Riêng ở Hà Nội, 87 lần chiếc máy bay B52, hơn 200 lần chiếc máy bay cường kích đã ném 3 đợt bom xuống 68 điểm thuộc nội, ngoại thành. Sân bay Bạch Mai, Đài Phát thanh Tiếng nói Việt Nam ở Mễ Trì, thị trấn Yên Viên, Đông Anh, Gia Lâm, cảng Sông Hồng, Vĩnh Tuy... bị trúng bom địch. Các trận địa tên lửa, cao xạ và lưới lửa phòng không tầm thấp bảo vệ thủ đô anh dũng đánh trả địch. Hai máy bay B52 bị bắn rơi.  19 giờ ngày 20 đến rạng sáng 21, đế quốc Mỹ lại huy động 78 lần chiếc B52 và hơn 100 lần chiếc máy bay cường kích vào ném bom Hà Nội. Tên lửa và pháo cao xạ ta chặn đánh chúng trên tất cả các hướng. Từ cự ly 22 kilômét, tiểu đoàn 93 tên lửa bắn rơi tại chỗ 1 máy bay B52, chiếc máy bay này rơi xuống xã Yên Thường, huyện Gia Lâm. Bọn giặc lái sống sót nhảy dù bị quân dân tỉnh Hà Bắc (nay là Bắc Ninh và Bắc Giang) bắt sống. Mười phút sau khi chiếc máy bay B52 thứ nhất bị bắn rơi, Tiểu đoàn 77 tên lửa bắn rơi chiếc máy bay B52 thứ hai ở ngoại thành. Được chiến thắng đơn vị bạn cổ vũ, 3 tiểu đoàn tên lửa 94, 79, 78 cũng bắn rơi 2 chiếc máy bay B52. Kết hợp với hỏa lực mặt đất, máy bay ta nhiều lần xuất kích cản phá đội hình máy bay địch.  Đến 5 giờ sáng ngày 21, thành phố nổi còi báo động lần thứ 12. Mặc dù đã qua một đêm chiến đấu vô cùng ác liệt, bộ đội chủ lực và dân quân tự vệ vẫn động viên nhau kiên quyết đánh trả địch. Với kinh nghiệm dày dạn, kỹ thuật thành thạo, Tiểu đoàn 77 tên lửa do tiểu đoàn trưởng Đinh Thế Văn chỉ huy đã phóng hai quả đạn bắn rơi chiếc máy bay B52 thứ năm. Tiếp đó, tên lửa ta bắn rơi thêm một máy bay B52 và vào những phút chót của đêm chiến đấu, bằng 2 quả đạn tên lửa cuối cùng, tiểu đoàn trưởng Nguyễn Văn Phiệt đã chỉ huy Tiểu đoàn 57 bắn rơi thêm một chiếc máy bay B52.  Pháo đài bay Mỹ bị ta trừng trị đích đáng, nhưng hậu quả của những trận bom trong đêm cũng thật nặng nề. Rất nhiều nơi trong thành phố bị tàn phá, trong đó có Khu tập thể An Dương. Một vệt bom B52 đã san bằng và phá hủy nặng 15 xí nghiệp, trường học, cửa hàng, trạm xá và hàng trăm nhà trong khu vực, làm chết 171 người, bị thương 151 người. Đây là trận B52 địch đánh sâu vào nội thành và gây tổn thất lớn nhất về người kể từ đêm 18 tháng 12.  Trong trận đánh đêm 20 rạng 21 tháng 12, các lực lượng phòng không bảo vệ thủ đô đã bắn rơi 7 máy bay B52 (có 5 chiếc rơi tại chỗ) và bắt sống nhiều giặc lái, đạt hiệu suất chiến đấu cao. Đó là trận đánh hiệp đồng tốt giữa tên lửa, không quân, cao xạ với hỏa lực tầm thấp của dân quân tự vệ trên một địa bàn rộng, nhiều mục tiêu, trọng điểm. Quân dân Hà Nội đã lập chiến công lớn. Chính kẻ địch đã thú nhận chúng bị mất 6 phần trăm tổng số lượt chiếc máy bay B52 xuất kích trong đêm, một tổn thất không thể chịu đựng nổi. Trận đánh này có ý nghĩa quan trọng góp phần đẩy nhanh thất bại của không quân chiến lược Mỹ trong chiến dịch Linebacker II.  Tuy máy bay B52 có sức tàn phá lớn, nhưng ở độ cao 10 kilômét, lại bị hỏa lực ta đánh trả quyết liệt, nó không dễ dàng hủy diệt được các mục tiêu theo ý muốn của bộ chỉ huy Mỹ. Vì thế, trưa ngày 21, Mỹ sử dụng nhiều máy bay ném bom chiến thuật, ném các loại bom điều khiển từ xa vào một số khu vực quan trọng trong thành phố. Ga Hàng Cỏ, trụ sở Bộ Giao thông vận tải, Tổng Công đoàn... bị trúng bom. Ngôi nhà trung tâm ga Hàng Cỏ bị đổ sập, 16 toa xe lửa hư hỏng. Nhiều đoạn đường sắt bị phá hủy. Cũng bằng loại bom điều khiển, lúc 13 giờ, địch đã phá hủy nhà trung tâm Đài Phát thanh Tiếng nói Việt Nam. Đó là lần ném bom thứ sáu liên tiếp trong 3 ngày đêm từ 18 đến 21 tháng 12 vào Đài Phát thanh. Hàng ngàn quả bom đã trút xuống khu vực, gây thương vong cho 130 đồng bào trong vùng. Hàng trăm nhà ở, vườn cây, giếng nước, công trình công cộng bị san bằng. Cùng thời điểm trên, máy bay địch ném bom dữ dội vào Nhà máy điện Yên Phụ, 12 trong số 22 lò bị phá hỏng. Hai công nhân Đặng Đình Thọ và Vũ Xuân Hòa tình nguyện ở lại điều chỉnh dòng điện, bị bom rơi trúng buồng máy hy sinh, nêu tấm gương cao đẹp của người thợ điện thủ đô.  Đêm 21 tháng 12, số lượng máy bay B52 ném bom vào Hà Nội đã giảm xuống còn 24 lần chiếc, bằng xấp xỉ một phần ba các đêm trước. Nhưng chúng thay đổi thủ đoạn, rút ngắn thời gian bay vào khu vực hỏa lực, tăng cường máy bay yểm trợ và gây nhiễu, rút ngắn cự ly các tốp, đồng thời thu hẹp vòng lượn để thoát khỏi khu vực uy hiếp của tên lửa sau khi ném bom. Vận dụng linh hoạt phương thức tác chiến, bộ đội tên lửa đã bắn rơi thêm 3 chiếc, tiêu diệt một phần tám số máy bay B52 vào ném bom trong đêm.  Tuy vậy, ta cũng không ngăn chặn được những trận ném bom của địch. Lúc 3 giờ 45 phút ngày 22, Bệnh viện Bạch Mai bị máy bay B52 giội bom. Hàng tấn máy móc, thiết bị, thuốc men bị hư hại. 28 bác sĩ, y sĩ, y tá, nhân viên phục vụ cùng nạn nhân các trận bom trước đang nằm điều trị chết và bị thương. Bệnh viện Bạch Mai trung tâm y tế lớn nhất miền Bắc thời kỳ này, từng được nhiều nước trên thế giới đầu tư, giúp đỡ bị phá hủy nặng. Các thầy thuốc và nhân viên bệnh viện đã làm việc hết sức mình tìm cứu người bị nạn. Nguyễn Thị Cúc, nhân viên khoa da liễu bới gạch đến rớm máu tay, cứu được 12 người. Trần Thị Xiêm, dược tá dẫn đầu chi đoàn thanh niên cùng cán bộ, nhân viên xông vào các khu vực đang còn khói lửa, cứu người, cứu thuốc. Khu phố Đống Đa và thành phố cấp tốc điều tới những đội cứu sập, cứu hỏa cùng giải quyết hậu quả.  Ngoài đối tượng chính là máy bay B52, trong 12 ngày đêm cuối năm 1972, Hà Nội còn phải đối phó với lực lượng lớn máy bay chiến thuật Mỹ, đặc biệt là loại máy bay F111. Loại này thường bay rất thấp, hoạt động nhỏ, lẻ, bất ngờ, liên tục, gây tâm lý căng thẳng cho nhân dân ta.  Trước tình hình đó, Bộ tổng tham mưu đã chỉ đạo bổ sung phương án tác chiến đối với Hà Nội. Trước đây (từ đêm 18 tháng 12) hỏa lực tầm thấp trong nội thành không được bắn ban đêm, đề phòng bắn nhầm vào máy bay ta lên, xuống sân bay Gia Lâm; nay Bộ tổng tham mưu đã có kế hoạch bảo đảm an toàn cho máy bay ta, cho tất cả các loại hỏa lực trong nội thành phát huy cả ban ngày và ban đêm.  Qua theo dõi đường bay của máy bay F111, Bộ tư lệnh Thủ đô tổ chức một trận địa súng máy cao xạ 14,5mm đón lõng tại bãi cát Vân Đồn phía Bắc cảng Sông Hồng 2 kilômét. Trận địa gồm 5 khẩu đội của tự vệ 3 nhà máy tập trung lại: Gỗ Hà Nội 2 khẩu, Cơ khí Mai Động 2 khẩu, Cơ khí Lương Yên 1 khẩu. Đồng chí Hoàng Minh Giám, cán bộ Bộ tư lệnh được cử xuống trực tiếp chỉ huy trận địa. Để chỉ dẫn đường bay địch, đội thông tin kéo một đường dây điện thoại từ sở chỉ huy ra trận địa.  9 giờ đêm 22 tháng 12 năm 1972, máy bay F111 bắt đầu xuất hiện. Được trên thông báo, Lê Xuân Máy, trực tiêu đồ đánh dấu chính xác đường bay khi chúng còn cách Hà Nội 100 kilômét. Trợ lý trinh sát Lê Thống theo dõi và thông báo đường bay, hướng bay ra trận địa Vân Đồn. Càng đến gần Hà Nội, máy bay địch càng hạ thấp độ cao. Tới khoảng cách 20 kilômét, các khí tài quan sát của ta mất mục tiêu. Lúc này, theo dõi phát hiện và chủ động đánh địch hoàn toàn phụ thuộc vào kinh nghiệm, tài trí của các xạ thủ trên trận địa. Cũng giống như những đêm trước, từ phía tây bắc chiếc F111 bay theo dọc sông, qua cảng Sông Hồng đúng vào trận địa Vân Đồn, nơi các chiến sĩ tự vệ đang chờ chúng. Cả 5 khẩu đội đồng loạt nhả đạn. Chiếc F111A bốc cháy, ngoặt sang hướng tây và rơi xuống huyện Lương Sơn, tỉnh Hòa Bình. Hai tên giặc lái nhảy dù bị quân và dân địa phương bắt sống.  Trận đánh diệt máy bay F111 đầu tiên của tự vệ thủ đô được cấp trên đánh giá cao. Chủ tịch nước Tôn Đức Thắng, Đại tướng Võ Nguyên Giáp và các đồng chí lãnh đạo thành phố, Bộ tư lệnh Thủ đô đã xuống trận địa động viên, tặng quà các chiến sĩ. Từ kinh nghiệm bắn rơi máy bay F111 ở Vân Đồn, Bộ tư lệnh Thủ đô chỉ đạo các khu phố, huyện nhanh chóng tổ chức 23 trận địa tập trung. Mỗi trận địa có từ 4 đến 6 khẩu, bố trí thành cụm, đón lõng các đường bay địch. Khu vực này không đón được máy bay, anh chị em lại chuyển trận địa sang khu vực khác. Phương tiện vận chuyển cũng rất linh hoạt, phong phú, khi bằng ô tô, máy kéo, lúc bằng xe bò, xe cải tiến hoặc khiêng vác.  Khí thế chiến đấu của quân dân Hà Nội càng lên cao sau khi được Bộ Tổng tư lệnh khen ngợi nhân ngày 22 tháng 12. Trong thư khen có đoạn: “Nhiệt liệt khen ngợi bộ đội tên lửa, cao xạ, không quân, bộ đội địa phương và dân quân tự vệ, đồng bào và cán bộ thủ đô đã chiến đấu giỏi, đánh những trận tiêu diệt rất xuất sắc, liên tiếp chiến thắng oanh liệt. Trong cuộc leo thang chiến tranh mới cực kỳ nghiêm trọng này, giặc Mỹ bị quân và dân miền Bắc, quân dân thủ đô ta giáng cho những đòn quyết liệt và tổn thất nặng..." (Báo Nhân Dân ngày 23-12-1972).  Những đợt ném bom mang tính chất hủy diệt của máy bay B52 xuống Hà Nội, Hải Phòng và một số nơi khác trên miền Bắc Việt Nam khiến dư luận thế giới hết sức phẫn nộ. Nhiều cuộc mít tinh biểu tình liên tiếp diễn ra ở nhiều nước kể cả ở Mỹ. Do bị thất bại nặng nề và lấy cớ nghi lễ Noel, 24 giờ ngày 24 tháng 12 địch tạm dừng cuộc tập kích để củng cố lực lượng, ổn định tinh thần bọn giặc lái, rút kinh nghiệm, tìm thủ đoạn đánh phá mới.  Ngay sau khi đế quốc Mỹ tuyên bố ngừng đánh bom, Bộ Chính trị, Quân ủy Trung ương nhận định: địch sẽ đánh phá trở lại Hà Nội ác liệt hơn. Quân dân miền Bắc, đặc biệt là Thủ đô Hà Nội phải gấp rút chuẩn bị tốt lực lượng đánh địch trong những ngày tới. Bộ tư lệnh Phòng không - Không quân phải kịp thời tổ chức rút kinh nghiệm chiến đấu trong toàn quân chủng, tập trung lực lượng tên lửa, dành để đánh B52 ban đêm; ban ngày chỉ sử dụng không quân và pháo cao xạ đánh trả không quân chiến thuật của địch. Tuy bị tổn thất lớn về số lượng máy bay B52 và giặc lái, bị dư luận thế giới và trong nước lên án mạnh mẽ, song tập đoàn Ních-xơn vẫn ngoan cố tiếp tục chiến dịch Linebacker II với cường độ lớn hơn vào ngày 26 tháng 12 năm 1972.  Chiều ngày 26 tháng 12, gần 60 chiếc máy bay chiến thuật các loại vào ném bom dữ dội các khu vực trận địa tên lửa, nhằm tạo thuận lợi cho máy bay B52 hoạt động ban đêm. Nhưng hầu hết các đợt sục sạo ban ngày của địch đều bị hỏa lực tầm trung và tầm thấp của Hà Nội ngăn chặn. Tên lửa ta vẫn giữ được bí mật, an toàn.  Từ 22 giờ 30 phút đến 22 giờ 45 phút, 129 lần chiếc máy bay B52 ập đến ném bom dữ dội Thủ đô Hà Nội. Lần này chúng đánh phá trên cả 4 hướng tây nam, tây bắc, đông bắc và đông nam. 22 giờ 30 phút, máy bay B52 rải bom khu vực ga Văn Điển, Nhà máy Pin, kho Giáp Nhị, kho dầu Đức Giang, Đông Anh, khu trận địa tên lửa ngoại thành. 22 giờ 40 phút, chúng đánh phá Sân bay Bạch Mai, Nội Bài, khu công nghiệp và dân cư Đông Anh, Cổ Loa, Giáp Bát, cảng Sông Hồng, Thượng Đình... Tiếp đó, nhiều tốp máy bay B52 ném bom rải thảm Khâm Thiên và nhiều nơi thuộc khu phố Hai Bà Trưng. Thành phố rung chuyển.  Ba tiểu đoàn tên lửa 76, 57, 88 đã tập trung bắn rơi tại chỗ 2 chiếc. Chưa bao giờ trên bầu trời Hà Nội diễn ra trận đánh ác liệt giữa rồng Thăng Long với pháo đài bay Mỹ như lúc này. Cùng với tên lửa, 20 khẩu pháo 100mm của tự vệ cùng bắn trả địch quyết liệt. Đêm mùa đông sáng rực bởi ánh lửa của đạn pháo, đạn tên lửa, của bom và những chiếc B52 bốc cháy. Do địch cùng lúc đánh nhiều mục tiêu, chúng lại bay trong hành lang nhiễu dày đặc dài hàng chục kilômét, nên các tình huống chiến đấu diễn biến càng phức tạp. Với kinh nghiệm dày dạn, các tiểu đoàn tên lửa 59, 93, 78, 79 phân tích chính xác mục tiêu trong dải nhiễu, bắn rơi trong đêm lên 5 chiếc. Phối hợp với tên lửa và pháo cao xạ, máy bay ta xuất kích, cản phá đội hình máy bay địch. Cùng với Hà Nội, Hải Phòng và Thái Nguyên cũng bắn rơi 3 máy bay B52. Vậy là đêm 26 tháng 12, Thủ đô Hà Nội và các địa phương đã đánh một trận tiêu diệt xuất sắc, bắn rơi 8 “pháo đài bay B52", 10 máy bay cường kích chiến thuật, bắt sống nhiều giặc lái Mỹ.  5 giờ sáng ngày 27, trận đánh kết thúc. Điểm cấp cứu đầu tiên của Hà Nội là phố Khâm Thiên, khu phố (nay là quận) Đống Đa. Phố Khâm Thiên dài 1.200 mét nối liền ngã tư Ô Chợ Dừa với ngã tư đường Nam Bộ (nay là đường Lê Duẩn), một trong những phố có mật độ dân cư đông đúc nhất Hà Nội, gồm 5.968 hộ với 29.629 người (số liệu năm 1972). Vệt bom do máy bay B52 rải xuống gần hết chiều dài đường phố đã giết chết 287 người, làm bị thương 290 người. Bom san bằng, phá sập gần hai nghìn ngôi nhà, đền chùa, trường học, trạm xá, hầm hố kiên cố của tập thể, cơ quan và gia đình. Hầm nhiều nhất 8 người chết và bị thương. Có gia đình 6 người ngồi trong một hầm, không ai sống sót. Ngay sáng hôm sau, mặc dù thành phố đang trong tình trạng báo động, nhiều khách nước ngoài, cán bộ lãnh đạo Đảng, Nhà nước, quân đội, đại diện Mặt trận dân tộc giải phóng miền Nam Việt Nam, đại diện thành phố Hà Nội, các ký giả... đã đến thăm những người bị nạn ở Khâm Thiên. Nhiều đoạn đường, vỉa hè, nền nhà còn loang vết máu. Nhiều tử thi xếp dọc hè phố chờ khâm liệm và đưa đi mai táng.  Cùng với Khâm Thiên, trong đêm, máy bay B52 đã rải bom xuống hơn một trăm điểm trong thành phố. Hai phần ba trong số đó là khu dân cư, làm hơn một nghìn người chết và bị thương. Tàn sát hàng loạt dân thường để đạt tới mục tiêu chính trị là một tội ác hết sức dã man và ghê tởm của Nhà Trắng và Lầu Năm Góc. Các khu vực Yên Viên, Gia Lâm, Uy Nỗ... đã bị máy bay B52 ném bom đến lần thứ 10, thứ 12. Khu vực Yên Viên bị khoảng 5.000 quả bom; nhà ga cùng nhiều đoạn đường sắt, kho chứa hàng bị bom Mỹ đào lên lấp xuống đến mức không còn dấu tích cũ.  Cùng thời gian từ 22 giờ 30 phút đến 22 giờ 45 phút ngày 26 tháng 12, Mỹ dùng máy bay B52 đánh phá thành phố Hải Phòng và Thái Nguyên. Chúng thực hiện đánh cả ba khu vực Hà Nội, Hải Phòng, Thái Nguyên cùng lúc, đánh phá ồ ạt, liên tục, thời gian ngắn, đánh từ nhiều hướng. Đây là đợt đánh phá được Mỹ chuẩn bị kỹ, tổ chức hiệp đồng công phu với cường độ lớn. Địch tin rằng với chiến thuật mới đó chúng sẽ phân tán và gây nên sự rối loạn về chỉ huy của ta, làm cho hỏa lực phòng không, nhất là tên lửa và không quân bị tê liệt. Nhưng ngược lại, đây lại là đêm tổn thất máy bay B52 lớn nhất của không quân chiến lược Mỹ.  Trước hành động điên cuồng, hung hăng, tàn bạo của Mỹ, Thành ủy Hà Nội phát động căm thù trong toàn thành phố. Các lực lượng vũ trang, cơ quan, đoàn thể, các ngành và nhân dân đều tỏ rõ quyết tâm chiến đấu đến cùng với giặc Mỹ, trả thù cho Khâm Thiên và những nơi bị hủy diệt. Các tỉnh, thành trên miền Bắc tấp nập gửi hàng hóa, thuốc men, lương thực... đến trợ giúp. Tỉnh Hà Tây (cũ) báo về có thể tiếp nhận của Hà Nội từ hai đến ba nghìn nạn nhân sau khi mổ. Cùng vào thời gian nóng bỏng này, đồng bào Sài Gòn - Gia Định kết nghĩa với Hà Nội, thay mặt quân dân miền Nam gửi thư chia sẻ đau thương, mất mát và tỏ lòng khâm phục truyền thống kiên cường bất khuất của thủ đô.  Với những diễn biến phức tạp, dồn dập trong đêm 26, ngày 27 tháng 12, Thủ tướng Chính phủ triệu tập cuộc họp khẩn cấp với các Bí thư, Chủ tịch một số tỉnh, thành phố để giải quyết những vấn đề cấp bách về chiến đấu, phòng tránh và tập trung sức chi viện cho thủ đô. Trước mắt, Bộ Quốc phòng tăng cường phương tiện, lực lượng để cùng Hà Nội nhanh chóng khắc phục hậu quả, giải tỏa giao thông. Các tỉnh Vĩnh Phú, Hà Tây, Hải Hưng, Hà Bắc (cũ) sẵn sàng chi viện theo yêu cầu của thủ đô, sẵn sàng tiếp nhận và cứu chữa nạn nhân của thủ đô.  Đêm 27 tháng 12, từ sân bay Yên Bái, phi công Phạm Tuân lái máy bay MiG 21 vượt qua hàng rào bảo vệ của máy bay F4 tiến về hướng máy bay B52. Đến bầu trời Mộc Châu, Sơn La, anh tiếp cận được mục tiêu và bắn rơi 1 chiếc góp phần cản phá đội hình B52 đang bay xuống Hà Nội. Cũng trong đêm 27 tháng 12, do những tổn thất rất nặng từ trước, máy bay B52 vào ném bom Hà Nội giảm xuống còn 36 lần/ chiếc. Các trận địa tên lửa của ta đã đánh trả địch rất hiệu quả, 4 chiếc B52 bị bắn rơi, trong đó, một chiếc từ độ cao 10 kilômét chưa kịp cắt bom, bị trúng đạn bốc cháy rơi xuống làng Ngọc Hà, cách Quảng trường Ba Đình hơn 500 mét.  Trong lúc bầu trời và mặt đất ầm vang tiếng súng, tiếng bom, tiếng rít của đạn tên lửa, của máy bay F111, cuộc chiến đấu của các lực lượng không cầm súng cũng diễn ra hết sức căng thẳng. Các chiến sĩ ra-đa luôn phải đấu trí với những tên giặc lái già đời sử dụng kỹ thuật mới nhất chống ra-đa phát hiện để đánh phá mục tiêu. Hàng trăm chiến sĩ trinh sát phòng không bám trụ trên những đài quan sát chênh vênh không vật che đỡ, theo dõi địch báo cáo kịp thời về Sở chỉ huy. Các chiến sĩ thông tin liên lạc băng mình qua bom đạn để truyền đạt mệnh lệnh. Trong các căn hầm dã chiến, những người thầy thuốc làm việc suốt ngày đêm cấp cứu nạn nhân. Đặc biệt, Đài Tiếng nói Việt Nam, Đài Phát thanh Hà Nội làm việc liên tục ngày đêm, bảo đảm chương trình phát sóng. Các văn nghệ sĩ cũng gắn mình vào cuộc chiến đấu. Nhiều nhà văn, nhà báo của thành phố, của Trung ương, quân đội không quản hiểm nguy đến tận nơi xảy ra chiến sự ghi chép, tìm hiểu. Các phóng viên quay phim, chụp ảnh đã kịp thời thu những hình ảnh chiến đấu hào hùng của Thủ đô Hà Nội. Trong một lần báo động kéo dài, nhạc sĩ Phạm Tuyên sáng tác bài hát Hà Nội - Điện Biên Phủ ở một căn hầm giữa thành phố. Hà Nội đây, đế quốc Mỹ có nghe chăng câu trả lời của Hà Nội chúng ta? Đâu chỉ vì riêng nước non này?... Cùng nhiều tác phẩm văn hóa, nghệ thuật khác, bài hát ra đời đúng lúc đã cổ vũ mạnh mẽ ý chí chiến sĩ, đồng bào kiên quyết chiến đấu bảo vệ thủ đô.  Những cuộc tiến công ác liệt dồn dập vào Thủ đô Hà Nội vẫn không tạo được thế mạnh cho Mỹ ở Hội nghị Paris. Mỹ buộc phải xuống thang, đề nghị Chính phủ ta nối lại cuộc đàm phán. Và chiều ngày 28 tháng 12 năm 1972, phái đoàn ta do đồng chí Lê Đức Thọ làm cố vấn dẫn đầu trở lại Hội nghị Paris với lòng tự tin của một dân tộc chiến thắng. Cũng trong ngày 28, Bộ tổng tham mưu điện cho Bộ tư lệnh Phòng không - Không quân: trước tổn thất rất nặng, địch có thể kết thúc cuộc tập kích. Trên tinh thần đó, quân chủng chỉ thị gấp cho Sư đoàn phòng không Hà Nội (Sư đoàn 361) và Sư đoàn 363 (bảo vệ Hải Phòng) tập trung lực lượng lớn nhất bắn rơi nhiều máy bay B52, giành thắng lợi to lớn hơn nữa.  Đến cuối ngày 28 tháng 12, Thủ đô Hà Nội hoàn thành sơ tán bước ba, đưa ra khỏi nội thành hơn 50 vạn người. Đây là lần sơ tán có quy mô lớn nhất trong lịch sử kháng chiến chống ngoại xâm của Thủ đô Hà Nội. Tuy đã giảm tám mươi phần trăm số người, nhưng Hà Nội vẫn duy trì nếp sinh hoạt thời chiến, khẩn trương, kỷ luật, bình tĩnh, tự tin. Điều mà Nhà Trắng và Lầu Năm Góc mơ tưởng là Hà Nội sẽ tê liệt sau những trận B52 rải thảm đã không xảy ra. Một số chính khách, phóng viên người nước ngoài đến Hà Nội trong dịp này vẫn được đón tiếp chu đáo trong bầu không khí hữu nghị, bình thản.  Đêm 28 tháng 12, số máy bay B52 vào đánh phá Hà Nội chỉ còn 30 lần/ chiếc cùng với 131 lần/ chiếc máy bay chiến thuật các loại. Lực lượng tên lửa bảo vệ thành phố bắn rơi 1 chiếc. Trong lúc Hà Nội đang diễn ra cuộc chiến đấu quyết liệt, theo phương án đánh địch từ xa, sân bay Thọ Xuân (Thanh Hóa), phi công Vũ Xuân Thiều lái máy bay MiG 21 ngược lên Sơn La bắn rơi 1 chiếc máy bay B52. Nhưng do tiếp cận quá gần, máy bay của Vũ Xuân Thiều bốc cháy theo. Người con trai Hà Nội đã anh dũng hy sinh.  Sau đêm 28 tháng 12, B52 và các loại máy bay cường kích vẫn tiếp tục vào ném bom nhưng số lượng giảm hẳn so với những đêm trước. Thêm 1 chiếc máy bay B52 và 1 chiếc máy bay F4 bị quân dân Hà Nội bắn rơi.  Từ đánh nhỏ đến đánh lớn, đánh ban đêm và đánh ban ngày, đánh liên tục, dữ dội, nhưng Mỹ không đạt được mục đích mong muốn. Ngược lại, tổn thất về máy bay, nhất là B52 quá lớn, buộc Mỹ không thể kéo dài hơn nữa cuộc tập kích chiến lược vào Thủ đô Hà Nội. Đây thực sự là một đòn chiến lược có ý nghĩa quyết định làm cho đế quốc Mỹ buộc phải thay đổi kế hoạch. 7 giờ 30 phút ngày 30 tháng 12 năm 1972, tổng thống Mỹ ra lệnh ngừng ném bom miền Bắc từ vĩ tuyến 20 trở ra, Chiến dịch Linebacker II của Mỹ kết thúc trong thất bại. chính của tôi trong tuần lễ ném bom đầu tiên không phải là những đợt phản đối gay gắt ở trong nước và thế giới, điều này đã được dự tính, mà chính là thiệt hại nặng nề về B52.  Chiến thắng 12 ngày đêm cuối năm 1972 của quân dân Hà Nội và của cả miền Bắc đã làm nên trận “Điện Biên Phủ trên không" chôn vùi uy thế của không lực Hoa Kỳ. Chiến thắng này được coi là đỉnh cao nhất của quân dân Thủ đô cũng như của cả miền Bắc trong cuộc chiến tranh nhân dân hai lần chống chiến tranh phá hoại của đế quốc Mỹ. Trong 12 ngày đêm, giặc Mỹ muốn biến Hà Nội thành bãi chiến trường của cuộc đọ sức cuối cùng mà chúng tin rằng sẽ nắm chắc phần thắng. Mọi tính toán của chúng bị đảo lộn. Hà Nội đã chiến thắng. Chiến công của quân và dân Thủ đô không chỉ là tiêu diệt nhiều máy bay địch mà quan trọng hơn là chủ động phòng tránh, giảm tổn thất về người và của, nhanh chóng khắc phục hậu quả sau mỗi trận đánh phá của kẻ thù, hơn tất cả là ý chí kiên cường, sự vững vàng, bình tĩnh của người Hà Nội trước thủ đoạn xâm lược của quân xâm lược. Trong những ngày chiến đấu ác liệt, cùng với bộ đội phòng không - không quân, tất cả các tầng lớp nhân dân Thủ đô đã góp sức tạo nên chiến thắng. Hàng trăm tấm gương sáng ngời đã xuất hiện trên mọi lĩnh vực: chiến đấu, phục vụ chiến đấu, bảo vệ sản xuất, bảo vệ trật tự trị an, tính mạng và tài sản của nhân dân trong cứu thương, cấp cứu, trong đùm bọc cưu mang giúp đỡ lẫn nhau. Đó là hình ảnh các chiến sĩ công an bám trụ ngày đêm bảo đảm giao thông, là tấm gương của hai công nhân nhà máy điện Yên Phụ bám máy đến cùng bảo vệ dòng điện cho Thủ đô, đó là hàng ngàn các chiến sĩ tự vệ cùng lực lượng cứu sập, cứu hỏa quên mình dưới làn bom đạn vì nhiệm vụ; đó là những nữ dân quân, học sinh, sinh viên tình nguyện phục vụ tiếp đạn ra trận địa cho các chiến sĩ tên lửa, cao xạ...  Cùng Hà Nội làm nên chiến thắng còn có sự góp sức của quân dân các địa phương đã tổ chức chiến đấu bảo vệ Hà Nội từ xa và cưu mang giúp đỡ hàng chục vạn đồng bào Thủ đô về sơ tán. Hà Nội đã cùng quân dân miền Bắc làm nên trận “Điện Biên Phủ trên không”, một trận thắng có ý nghĩa chiến lược: đánh thắng lực lượng không quân chiến lược của Mỹ, đánh thắng kẻ thù khi chúng leo thang đến mức cao nhất. Đánh thắng B52, ta đã đập tan mọi cố gắng phản kích của Mỹ vào thời điểm quan trọng. Thắng lợi này đẩy đế quốc Mỹ lún sâu vào thế bế tắc hơn cả những lần trước đây. Không còn cách nào khác hơn, Mỹ phải trở lại bàn Hội nghị Paris, chấp nhận những nội dung đã thỏa thuận tháng 10 năm 1972 và phải ký Hiệp định Paris (27-1-1973) về chấm dứt chiến tranh lập lại hòa bình ở Việt Nam. Ngày 28 tháng 1 năm 1973, Hiệp định Paris bắt đầu có hiệu lực, chấm dứt vai trò của quân viễn chinh Mỹ trên chiến trường miền Nam Việt Nam.  Qua thắng lợi 12 ngày đêm đánh trả cuộc tập kích chiến lược của không quân Mỹ, vị trí của Việt Nam, cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam càng có thể đứng vững chắc trong lòng nhân dân thế giới. Ngoài các nước xã hội chủ nghĩa anh em coi cuộc chiến đấu chống Mỹ của nhân dân Việt Nam như cuộc chiến đấu của chính mình, rất nhiều nước trung lập, tư bản chủ nghĩa, các nước mới trỗi dậy tỏ rõ thái độ phản đối hành động dã man của đế quốc Mỹ. Dư luận tiến bộ thế giới lên án Tổng thống Mỹ thứ 37 (Ních-xơn) đã đi vào lịch sử như một Hít-le, Kẻ sát hại đàn bà và trẻ em, Sự sỉ nhục của trái đất... Cùng với quân dân cả nước, quân dân Hà Nội đã đập tan huyền thoại về B52, loại siêu pháo đài bất khả xâm phạm của Không lực Hoa Kỳ, một trong bộ ba Vũ khí chiến lược của Mỹ. Từ hồi hộp, lo lắng, nhân dân thế giới đi đến ngạc nhiên, khâm phục cuộc chiến đấu của nhân dân Việt Nam, của Thủ đô Hà Nội.  Cuộc chiến đấu chống chiến tranh phá hoại lần thứ hai của đế quốc Mỹ, mà đỉnh cao là 12 ngày đêm cuối năm 1972 trên bầu trời Hà Nội đã đi vào lịch sử Việt Nam và thế giới như một dấu son chói lọi. Cùng với cuộc chiến tranh giải phóng của nhân dân miền Nam, nó còn là đề tài cho nhiều nhà quân sự chính trị sử học trên thế giới nghiên cứu, khai thác về tính chất anh hùng Việt Nam, của Hà Nội và về sai lầm của Mỹ.  Thắng lợi của chiến tranh nhân dân chống chiến tranh phá hoại lần thứ hai của đế quốc Mỹ mà đỉnh cao là Chiến dịch mười hai ngày đêm ở Hà Nội, trước hết là thắng lợi của nghệ thuật phát huy sức mạnh tổng hợp của chiến tranh nhân dân; là thắng lợi của sự kết hợp chặt chẽ giữa lực lượng phòng không chủ lực với hệ thống phòng không dân quân tự vệ, lấy lực lượng phòng không chủ lực làm nòng cốt, đồng thời động viên đẩy mạnh hoạt động của các tổ chức, các lực lượng khác trong thành phố tham gia bảo đảm chiến đấu và phục vụ chiến đấu. Thắng lợi đánh bại máy bay B52 là thắng lợi của tên lửa phòng không, của bộ đội ra-đa có sự phối hợp hiệp đồng của ba thứ quân, của tác chiến phòng không nhân dân. Thắng lợi đó còn là sự phát huy thế mạnh của thủ đô được Bộ Chính trị, Trung ương Đảng, Chính phủ và Bộ Tổng tư lệnh trực tiếp chỉ đạo, chỉ huy, kết hợp chặt chẽ với sự lãnh đạo, chỉ đạo của thành phố trong từng chủ trương, từng tình huống cụ thể.  Cả nước vì thủ đô, thủ đô vì cả nước là mối quan hệ máu thịt, một yếu tố cực kỳ quan trọng dẫn đến thắng lợi, đặc biệt là các tỉnh bạn lân cận đã đồng tâm hiệp lực với Hà Nội đánh bại sức mạnh không thể tưởng tượng nổi của không lực Hoa Kỳ tạo nên một trận Điện Biên Phủ trên không.  “Chiến thắng Điện Biên Phủ trên không" - cũng là “Chiến thắng B52", “Chiến thắng 12 ngày đêm” đã được nhắc đến nhiều lần trên các sách, báo, các đài phát thanh, các đài truyền hình của nước ta từ cuối năm 1972 đến nay và còn vang vọng đến mai sau.', 'TEXT', '2026-06-05 05:42:39.526143', '2026-06-05 05:42:39.526124', null, 'DRAFT'), ('aba92ab1-b99b-4dd0-b619-e5b894a71f8c', '687b57fe-865c-496a-83b3-f83690885dd1', '55ae763f-2c8f-4918-bf31-b43566c3c355', 'CHARACTER', 'Tiểu sử Ngô Quyền', null, '1. Thân thế Ngô Quyền

Sử cũ đều chép Ngô Quyền xuất thân trong một dòng họ quý tộc, có thế lực ở Giao Châu. Đại Việt sử ký toàn thư chép: “Tiền Ngô vương: ở ngôi 6 năm, thọ 47 tuổi (898-944). Vua mưu tài đánh giỏi, làm nên công tái tạo, đứng đầu các vua. Họ Ngô, tên húy là Quyền, người Đường Lâm, đời đời là nhà quý tộc. Cha là [Ngô] Mân làm chức Châu mục ở bản châu”.

Đại Việt sử ký tiền biên chép: “Tiền Ngô vương: Vua họ Ngô, húy là Quyền, người Đường Lâm… Vua đời đời là quý tộc ở Đường Lâm, cha là [Ngô] Mân làm quan Mục ở châu đó. Khi vua mới sinh ra có một luồng ánh sáng lạ tỏa khắp nhà. Vua hình dạng khác thường, sau lưng có ba nốt ruồi, người xem tướng cho là khác thường, bảo rằng người này có thể làm chúa một phương, bèn đặt tên là Quyền. Khi lớn lên, vẻ người khôi ngô, mắt sáng như tia chớp, đi thong thả như dáng cọp, có chí dũng, sức có thể giơ nổi vạc…”.

Khâm định Việt sử thông giám cương mục chép: “Ngô Quyền, người xã Đường Lâm, thuộc dòng quý tộc đã lâu đời, cha là [Ngô] Mân trước làm quan Mục ngay châu nhà (tức Giao Châu - TG)…”.

Như vậy, cho thấy Ngô Quyền sinh ra trong một gia đình có truyền thống yêu nước chống quân xâm lược phương Bắc. Theo Thần tích đền Gia Viên, quận Hồng Bàng, thành phố Hải Phòng, thì ông Tổ bốn đời của Ngô Quyền là Ngô Xuân, là người đã từng chiêu mộ được hơn 100 thủ hạ theo Triệu Quang Phục, tiếp tục sự nghiệp anh hùng của Lý Nam đế chống quân Lương. Vì lập được nhiều chiến công nên ông được phong làm thổ tù và được cha truyền con nối chức tước. Cha Ngô Quyền là Ngô Mân, còn mẹ ông là bà họ Phạm, người cùng châu Đường Lâm. Ngô Quyền sinh 4 người con trai: Ngô Xương Ngập (Thiên Sách Vương), Ngô Xương Văn (Nam Tấn Vương), Ngô Nam Hưng, Ngô Càn Hưng (Thất truyền).

2. Ngô Quyền với chiến thắng trên sông Bạch Đằng năm 938
Năm Đinh Dậu (937), Kiều Công Tiễn - bộ tướng của Dương Đình Nghệ đã sát hại chủ tướng, đoạt chức Tiết độ sứ. Từ Ái Châu, Ngô Quyền  là tướng và là con rể của Dương Đình Nghệ chuẩn bị lực lượng tiến ra Bắc diệt trừ tên phản bội. Trước sự căm ghét và phản kháng của quân dân trong  nước, Kiều Công Tiễn tự thấy mình thế cô lực yếu, đã đê hèn cho người sang  cầu cứu vua Nam Hán. Đoán trước được ý đồ “nội công ngoại kích” của địch, Ngô Quyền đã nhanh chóng tập hợp lực lượng chống thù trong giặc ngoài. Tháng 10 năm 938, Ngô Quyền tiến quân bao vây thành Đại La, tiêu   diệt Kiều Công Tiễn, đập tan thế lực phản động, làm thất bại âm mưu dùng nội ứng của nhà Nam Hán. Tiếp đó, ông tập hợp mọi lực lượng dân tộc, kêu gọi động viên nhân dân cả nước, đặc biệt là dân binh các làng xã ở miền Đông Bắc tham gia đánh giặc; mặt khác, ông chủ trương lợi dụng địa hình hiểm trở của núi  rừng, sông nước ở vùng cửa sông Bạch Đằng bí mật bố trí một trận địa mai phục, với bãi cọc ngầm đóng dưới lòng sông và triển khai quân đội mai phục ở hai bên bờ sông  sẵn sàng đón đánh quân địch.

Cuối tháng 12 năm 938, đoàn binh thuyền Nam Hán do Hoằng Tháo chỉ huy từ Quảng Đông (Trung Quốc) vượt biển, qua đường Đông Kênh, châu Vĩnh An, tiến vào vùng vịnh Hạ Long. Đúng như kế hoạch, khi nước triều đang lên, Ngô Quyền cho một bộ phận thủy quân ra khiêu chiến, rồi giả vờ thua. Hoằng Tháo thúc quân đuổi theo nhưng chúng đã lọt vào trận địa phục binh mà Ngô Quyền đã bày sẵn. Khi nước thủy triều xuống, Ngô Quyền  ra lệnh cho quân thủy bộ từ các vị trí mai phục, bất thần xông ra chặn đầu, đánh tạt hai bên sườn đội hình thuyền giặc. Bị đánh bất ngờ và mạnh liệt, thủy quân Nam Hán không kịp trở tay, đội hình rối loạn, tổn thất lớn, buộc phải quay đầu tháo chạy hòng thoát ra biển, nhưng lại bị sa vào trận địa cọc ngầm. Trong thời gian ngắn, toàn bộ đoàn chiến thuyền của Nam Hán bị nhấn chìm, hầu hết quân địch bị tiêu diệt, trong đó có cả chủ tướng Lưu Hoằng Tháo.

3. Ngô Quyền xưng Vương và định đô tại Cổ Loa
Ngay sau ngày chiến thắng, Ngô Quyền kéo đại quân về đóng đô ở Loa Thành (thành Cổ Loa, huyện Đông Anh, Hà Nội) để tỏ ý tiếp tục sự nghiệp dựng nước và giữ nước đời Hùng Vương - An Dương Vương, khẳng định quyết tâm giữ vững nền độc lập dân tộc non trẻ vừa mới giành lại được. Ông quyết định bỏ chức Tiết độ sứ của phong kiến phương Bắc, tự x­ưng Vư­ơng. Sách Đại Việt sử ký toàn thư cho biết “Kỷ Hợi, năm thứ 1 (939), (…). Mùa xuân, vua bắt đầu xưng vương, lập Dương Thị làm Hoàng hậu, đặt trăm quan, chế định triều nghi phẩm phục”. Ông kiên quyết cắt đứt mọi quan hệ lệ thuộc đối với nư­ớc ngoài, xây dựng một chính quyền theo mô hình quân chủ tập trung, một vương quốc thật sự độc lập.

Ngô Quyền trị vì đất nư­ớc chưa đầy 6 năm. Năm 944, ông qua đời khi mới 47 tuổi. Sự nghiệp mở nước, xưng vương của người anh hùng còn dang dở, nhưng trên đại thể vẫn nhận ra được vương triều Ngô “là Nhà nước độc lập của một quốc gia có đầy đủ chủ quyền, xét trên ý thức tư tưởng cũng như trong hoạt động thực tế” (Phan Huy Lê, 2011, Tìm về cội nguồn, Nxb. Thế giới, tr.700).

Lê Văn Hưu (1230-1322), nhà sử học khai sáng nền sử học Đại Việt thời Trần và được tôn vinh là Thủy tổ của nền sử học Việt Nam xác nhận:“Tiền Ngô Vương có thể lấy quân mới họp của nước Việt ta mà đánh tan được trăm vạn quân của Lưu Hoằng Tháo, mở nước xưng vương, làm cho người phương Bắc không dám lại sang nữa. Có thể nói là một lần nổi giận mà yên được dân, mưu giỏi mà đánh cũng giỏi vậy. Tuy chỉ xưng vương, chưa lên ngôi đế, đổi niên hiệu, nhưng chính thống của nước Việt ta ngõ hầu đã nối lại được”. Nhà yêu nước kiệt xuất đầu thế kỷ XX Phan Bội Châu đã tôn vinh Ngô Quyền là vị “Tổ trung hưng nước ta”.', 'TEXT', '2026-06-06 09:13:02.410537', '2026-06-06 09:13:02.410465', null, 'DRAFT'), ('c5c83279-874c-458b-bf4f-41e095067d94', '687b57fe-865c-496a-83b3-f83690885dd1', '1055f5d5-7249-46c9-a5c9-84508e09a9eb', 'CONTEXT', 'Chi tiết trận Như Nguyệt', null, 'Trận Như Nguyệt (18-1 đến 28-2-1077), trận quyết chiến chiến lược diệt quân Tống xâm lược trên phòng tuyến sông Cầu (Bắc Ninh) của quân dân Đại Việt do Lý Thường Kiệt chỉ huy, kết thúc cuộc kháng chiến chống Tống lần thứ hai (1075-1077). Trận Như Nguyệt cũng là trận chiến bảo vệ Kinh đô Thăng Long mùa Xuân năm 1077.

Năm Canh Tuất (1010), vua Lý Thái Tổ (Lý Công Uẩn) quyết định dời đô từ Hoa Lư ra thành Đại La, đổi tên là thành Thăng Long, cốt để “mưu nghiệp lớn, chọn ở chỗ giữa, làm kế cho con cháu muôn vạn đời, trên kính mệnh trời, dưới theo dân..." (Chiếu dời đô). Bắt đầu từ Lý Thái Tổ, mảnh đất Thăng Long mới trở thành Kinh đô của nước ta. Và mảnh đất đó cũng trở nên linh thiêng một phần chính vì những truyền thuyết liên quan đến Lý Công Uẩn. Ông không những là vị vua khai cơ cho triều Lý, mà còn là vị vua khai sinh ra Kinh thành Thăng Long, đặt ra một kinh đô lý tưởng cho các triều đại sau này.

Năm 1054, nhà Lý đổi tên nước là Đại Việt, ra sức củng cố và phát triển chế độ trung ương tập quyền. Bộ máy nhà nước phong kiến tổ chức khá quy củ. Hệ thống tổ chức hành chính được thành lập từ trung ương đến cơ sở. Đất nước được chia thành các lộ, các trại, các phủ, các châu; ở cấp dưới là huyện, hương, giáp. Triều đình có những chính sách để “cố kết nhân tâm", tranh thủ tù trưởng miền núi, thắt chặt khối đoàn kết dân tộc, tăng cường mối quan hệ với các địa phương tạo cơ sở chính trị thuận lợi cho sự nghiệp xây dựng và bảo vệ Tổ quốc. Đối với vùng biên cương phía Bắc và Đông Bắc Tổ quốc - vùng giữ vị trí chiến lược trọng yếu, triều đình có kế hoạch phòng thủ thích hợp.

Về quân sự, kế thừa những kinh nghiệm tổ chức quân đội thời Đinh Lê, nhà Lý đã tổ chức và xây dựng lực lượng vũ trang quốc gia theo chính sách “ngụ binh ư nông" (gửi quân lính ở nông thôn). Chính sách này đã đáp ứng được yêu cầu dựng nước gắn liền với giữ nước. Ngoài quân triều đình, còn có quân địa phương do các lộ tổ chức và quản lý, chỉ huy, đồng thời đặt dưới sự thống lĩnh của triều đình. Hương binh, thổ binh được tổ chức ở làng, bản, xã. Quân đội nhà Lý được trang bị giáo, mác, kiếm bằng sắt, các loại áo giáp, cung nỏ, máy bắn đá... và được huấn luyện, thao diễn thống nhất. Các quan văn võ lần lượt đến điện giảng võ ở Thăng Long để nghe giảng binh pháp.

Như vậy, thời Lý, đất nước Đại Việt được phát triển về mọi mặt khá hoàn chỉnh. Sự phát triển đó tạo cơ sở thuận lợi cho việc ổn định và nâng cao một bước đời sống của nhân dân, tăng cường đoàn kết trong nước, nâng cao ý thức trách nhiệm bảo vệ đất nước, cho khả năng động viên trăm họ thực hiện cả nước đánh giặc khi nước nhà bị xâm lược và cuối cùng tạo cơ sở thuận lợi cho sự phát triển nghệ thuật quân sự truyền thống đã được hình thành phong phú trước đó. Đặc biệt việc dời đô ra Thăng Long đã tạo nhiều điều kiện thuận lợi cho công cuộc xây dựng và bảo vệ đất nước.

*   Về xây dựng đất nước: Kinh đô ở vào nơi trung tâm của đất nước, tiện cho việc chỉ đạo thực hiện các chính sách của triều đình, lại thuận lợi cho việc giao lưu kinh tế, văn hóa, xã hội giữa các miền đồng bằng, trung du và miền núi, các lộ phía bắc và các lộ phía nam, các vùng người Kinh và các vùng dân tộc ít người.... Nhờ đó mà thúc đẩy sự phát triển về các mặt kinh tế, chính trị, xã hội, văn hóa của Thăng Long và của cả nước. Kinh đô Thăng Long trở thành trung tâm chính trị, kinh tế, văn hóa sầm uất, phồn thịnh nhất của cả nước.
*   Về bảo vệ đất nước: Ở Thăng Long triều đình nắm tình hình các mặt thuận lợi hơn ở Hoa Lư như tình hình biên giới phía bắc, tình hình và âm mưu xâm lược của phong kiến phương Bắc, đồng thời cũng có điều kiện nắm tình hình biên giới phía nam, theo dõi sự câu kết chống Đại Việt của nhà Tống với phong kiến Chiêm Thành. Việc cơ động lực lượng theo đường biển và đường sông, đường bộ từ kinh đô đến các địa phương và ngược lại cũng thuận tiện. Khi cần thiết, việc động viên sức người, sức của để kháng chiến từ trong dân cũng được tiện lợi và nhanh chóng.

Vào giữa thế kỷ XI, nhà Tống ở Trung Quốc đang ở giai đoạn phát triển cực thịnh. Nhà Tống vốn nuôi dưỡng mưu đồ làm bá chủ cả thiên hạ, trước hết là đánh chiếm các nước ở phía nam, trọng điểm là Đại Việt. Nhằm mục đích đó triều đình Tống ra sức xây dựng quân đội nhà nghề gồm cả bộ binh, kỵ binh và thủy binh. Mặt khác, sự bóc lột phong kiến cũng phát triển. Thuế khóa hết sức nặng nề, của cải của dân chúng nước Tống bị vơ vét đến tận cùng. Trong lúc nông dân sống trong cảnh khốn cùng, “người nghèo ngày càng lưu tán, chết đói, chết đường không ai thương” thì bọn vua quan, thương gia lớn và điền chủ sống sung sướng, xa hoa. Mâu thuẫn xã hội giữa giai cấp nông dân với giai cấp phong kiến, địa chủ quan liêu ngày càng trở nên quyết liệt. Tình hình đó có ảnh hưởng đến sức chiến đấu của quân đội xâm lược nhà Tống và khả năng động viên lực lượng khi cần thiết.

Tại Đại Việt, năm 1072 vua Lý Thánh Tông băng hà, Thái tử Càn Đức mới bảy tuổi lên nối ngôi. Nhà Tống coi đây là cơ hội tốt để đem quân đánh lấy Đại Việt. Tháng 3 năm 1074, nhà Tống bắt đầu điều động binh mã, xây lập các căn cứ ở các châu Ung, Khâm, Liêm, tích trữ lương thảo, gấp rút chuẩn bị lực lượng tấn công Đại Việt, đồng thời cho quân quấy phá biên giới.

Vua Tống là Thần Tông cùng với Tể tướng Vương An Thạch quyết định xâm lược nước ta với mục đích là giải quyết mối nguy cơ về đối nội và đối ngoại, nhưng trước hết là để lấn chiếm đất đai, mở rộng phạm vi chiếm đóng của triều đình Tống. Theo nhà Tống, đánh nước ta nếu thắng, thế Tống tăng, các nước Liêu, Hạ sẽ phải kiêng nể. Do vậy, lần này chúng chuẩn bị xuất quân rất chu đáo.

Trước những hoạt động chuẩn bị xâm lược của nhà Tống, triều đình nhà Lý khẩn trương chuẩn bị kháng chiến. Triều đình sắp xếp lại chức vụ của các đại thần, cử Lý Đạo Thành chuyên lo công việc nội chính, giao cho Lý Thường Kiệt chuyên trách công việc binh bị để chống giặc. Lệnh trưng binh được ban hành trong nước. Quân đội được tăng cường huấn luyện và diễn tập.

Lý Thường Kiệt cho rằng: “Ngồi yên đợi giặc không bằng đem quân ra trước để chặn mũi nhọn của giặc" (Lý Tế Xuyên, Việt điện u linh). Chủ trương “tiên phát chế nhân” của Lý Thường Kiệt được triều đình tán thành ủng hộ. Ông quyết định mở cuộc tiến công quy mô lớn sang đất Tống, nhằm phá tan các cứ điểm xâm lược Ung, Khâm, Liêm, mà chủ yếu là thành Ung Châu rồi quay về phòng thủ đất nước, chủ động đánh địch. Trong cuộc tiến công này, Lý Thường Kiệt đã huy động hơn 10 vạn quân thủy bộ.

Ngày 27 tháng 10 năm 1075, cuộc tiến công bắt đầu. Các đạo quân của ta từ Quảng Nguyên, Quang Lang, Tô Mậu do Tôn Đản, Hoàng Kim Mãn, Thân Cảnh Phúc và các thủ lĩnh dân tộc thiểu số khác chỉ huy chia thành nhiều mũi, vượt biên ải bất ngờ tấn công vào hệ thống đồn trại quân Tống, rồi vây đánh thành Ung Châu. Ngày 30 tháng 12 năm 1075, Lý Thường Kiệt thống lĩnh 6 vạn quân, từ Vĩnh An (Móng Cái) dùng thuyền ngày đêm vượt biển tiến về Khâm Châu. Quân ta lần lượt đánh chiếm Khâm Châu, Liêm Châu, tiến về Ung Châu. Trên đường tiến binh, Lý Thường Kiệt cho phát bản Phạt Tống lộ bố văn (bài văn nói rõ lý do đánh Tống), lên án sự bóc lột hà khắc của nhà Tống, công bố mục đích cứu dân của cuộc tiến quân, xác định thái độ phân biệt quốc thổ, không phân biệt chúng dân, kêu gọi dân chúng chớ mang lòng sợ hãi. Dân Tống vui mừng, đem trâu, rượu khao quân đội nhà Lý.

Trung tuần tháng 1 năm 1076, các cánh quân ta bao vây, tiến công thành Ung Châu; ngày 1 tháng 3 năm 1076 tiêu diệt hoàn toàn quân Tống, làm chủ thành này. Sau hơn 120 ngày đêm chiến đấu, nhiệm vụ triệt phá các căn cứ xâm lược đã hoàn thành, quân ta đã tiêu diệt và bắt sống khoảng 10 vạn quân Tống. Lý Thường Kiệt lệnh lui quân về nước.

Bằng cuộc tập kích táo bạo, tiến công vào kẻ địch đang chuẩn bị xâm lược, Lý Thường Kiệt đã “chặn mũi nhọn của giặc”, đẩy kẻ thù vào thế bị động ngay từ đầu và tạo ra nhiều điều kiện có lợi cho cuộc kháng chiến chống xâm lược của dân tộc ta. Bao nhiêu căn cứ quân sự và hậu cần nhà Tống chuẩn bị bấy lâu nay đã bị phá hủy tan tành.

Biết thế nào quân Tống cũng kéo quân sang xâm lược, Lý Thường Kiệt cùng triều đình nhà Lý lo xúc tiến ngay công việc chuẩn bị chống giặc. Bằng một mạng lưới thám tử tung sang đất Tống dưới nhiều hình thức như nhà sư, lái buôn, dân chài... Lý Thường Kiệt nắm chắc tình hình địch và theo dõi từng bước hoạt động của quân Tống.

Tháng 3 năm 1076, vua Tống hạ chiếu cử Quách Quỳ là một võ tướng cao cấp đã từng giúp Phạm Trọng Yêm giữ biên thùy phía bắc chống lại nước Hạ làm chánh tướng, đem quân sang xâm lược nước ta. Triệu Tiết giữ chức viên ngoại lang bộ lại đang coi Diên Châu (Thiểm Tây) được điều về làm phó tướng. Dưới trướng Quách Quỳ và Triệu Tiết, có nhiều tướng đã quen với chiến trận ở miền bắc. Về quân số, Quách Quỳ muốn huy động một lực lượng thật lớn, càng nhiều càng tốt. Chốt lại, triều đình Tống quyết định điều 10 vạn quân chiến đấu gồm bộ binh và kỵ binh, 1 vạn ngựa và 20 vạn phu vận chuyển lương thực. Ngoài ra, nhà Tống còn tổ chức một đội thủy binh tiến sang để cùng hiệp đồng với bộ binh, kỵ binh trong hành quân và chiến đấu. Như vậy, toàn bộ quân xâm lược Tống lên đến trên 30 vạn, trong đó có 10 vạn quân chiến đấu tinh nhuệ. Vua Tống còn hạ chiếu cho Chiêm Thành và Chân Lạp đem quân cùng đánh Giao Chỉ.

Theo kế hoạch, bộ binh và kỵ binh quân Tống sẽ tập trung ở Ung Châu rồi đột nhập vào vùng biên giới đông bắc nước ta. Thủy quân của chúng sẽ từ cửa biển Khâm, Liêm vượt biển tiến vào cửa sông Bạch Đằng để phối hợp với bộ binh. Các căn cứ xâm lược ở vùng châu Ung, Khâm lại được lệnh gấp rút xây dựng. Vua Tống Thần Tông đích thân kiểm tra việc điều quân lương và mọi mặt chuẩn bị. Thần Tông còn căn dặn tướng Quách Quỳ cuộc viễn chinh này phải toàn thắng, vì “bốn phương nhìn về”, nếu không sẽ “bất tiện cho nước nhà”.

Thời bấy giờ nhà Tống là một triều đại phong kiến lớn trên thế giới, lại ở sát nước ta. Quân đội nhà Tống mấy năm chiến tranh liên miên với các tộc phía bắc và phía tây nên có kinh nghiệm tác chiến, sở trường với lối đánh trận địa, có bộ binh và kỵ binh mạnh. Ngoài các vũ khí thông thường, quân Tống còn sử dụng phổ biến máy bắn đá và tuy chưa chế tạo ra hỏa pháo nhưng đã sử dụng thuốc súng trong chiến tranh, dùng hỏa tiễn (một loại pháo thăng thiên) để đốt cháy doanh trại đối phương.

Quân dân ta khẩn trương chuẩn bị cho cuộc kháng chiến, sẵn sàng đánh địch. Đồng thời Lý Thường Kiệt thống lĩnh một đạo thủy quân tinh nhuệ đi kinh lý phía nam để tuyên cáo tin thắng trận, động viên sĩ khí quân các lộ, cũng là để báo cho Chiêm Thành biết thất bại thảm hại của nhà Tống. Vua Chiêm Thành do đó không tiến quân hội chiến theo chiếu dụ của nhà Tống.

Trong điều kiện so sánh lực lượng chênh lệch giữa ta với địch và trước cuộc tiến công ồ ạt của hàng chục vạn quân Tống, nếu ta đưa toàn bộ lực lượng ra quyết chiến với địch ngay từ đầu là hết sức bất lợi. Do vậy, Lý Thường Kiệt không chủ trương chặn địch ở biên giới. Nhưng ông cũng không chủ trương tạm thời rút lui chiến lược để cho quân địch tiến quá sâu vào lãnh thổ của nước ta. Trên cơ sở tính toán, cân nhắc kỹ thế và lực của ta và địch, đồng thời phát huy thắng lợi vừa giành được trong cuộc tiến công tự vệ trước đó, Lý Thường Kiệt đề ra một kế hoạch kháng chiến rất chủ động, tích cực nhằm hạn chế đến mức cao nhất sự tàn phá của quân xâm lược và giành thắng lợi to lớn cho đất nước.

Về phía địch, lúc này nhà Tống phải lo đối phó nhiều mặt, vua Tống vẫn còn e sợ các nước Liêu, Hạ nhận thấy Tống bận việc phương Nam sẽ gây sự ở phương Bắc nên Tống Thần Tông còn căn dặn Quách Quỳ “phải lo việc An Nam cho chóng xong”. Nhà Tống hết sức giữ bí mật cuộc Nam chinh này vì nếu không đánh nhanh thắng nhanh sẽ không kham nổi cuộc hành binh lâu dài trên đất nước ta, khi gặp khó khăn sẽ có ít khả năng tăng viện. Như vậy là quân Tống tiến hành xâm lược trong thế bị động và không thể kéo dài chiến tranh. Còn quân dân ta thì bước vào cuộc kháng chiến với tư thế chủ động, với quyết tâm bảo vệ nền độc lập dân tộc, chủ quyền quốc gia và được chiến đấu trên đất nước yêu thương của mình.

Từ những điều kiện khách quan, chủ quan trên, Lý Thường Kiệt chủ trương lập chiến tuyến ở nơi có lợi nhất để chặn bước tiến của quân Tống, bảo vệ an toàn Kinh đô Thăng Long và địa bàn cơ bản của đất nước. Sau khi đã đánh bại mọi cuộc tiến công của địch, giam hãm chúng vào tình trạng mệt mỏi, tiêu hao, khốn cùng, sẽ tiến hành phản công, thực hành quyết chiến chiến lược giành thắng lợi quyết định. Đây là một chiến lược sáng tạo, độc đáo của Lý Thường Kiệt, thể hiện tư tưởng tiến công chủ động, tích cực của ông.

Sau khi nghiên cứu rất kỹ địa hình, địa vật, Lý Thường Kiệt quyết định cho xây dựng tuyến phòng ngự quân giặc ở bờ Nam sông Như Nguyệt đi từ sườn đông dãy núi Tam Đảo đến sườn tây dãy núi Yên Tử. Sông Như Nguyệt là tên sông Cầu, đoạn chảy từ ngã ba sông Cà Lồ và sông Cầu chảy qua làng Như Nguyệt, xã Tam Giang, huyện Yên Phong, tỉnh Bắc Ninh đến Phả Lại, huyện Chí Linh, tỉnh Hải Dương. Tính toán kỹ đường đi nước bước của quân Tống, Lý Thường Kiệt cho xây dựng tuyến phòng thủ ở đây là rất hợp lý, vừa bảo vệ được Kinh thành Thăng Long, vừa bảo vệ được lăng tẩm của nhà Lý ở Đình Bảng, Từ Sơn, Bắc Ninh. Bởi đây chính là những mục tiêu quan trọng phải chiếm cho được của quân Tống khi xâm lược nước ta. Kinh thành Thăng Long và lăng tẩm của nhà Lý lại được che chở bởi con sông Cầu. Các đường tiến vào Thăng Long của quân Tống từ Ung Châu xuống đều phải qua con sông Cầu chạy dài suốt từ Cao Bằng đến Lục Đầu đổ ra biển. Vì vậy sông Cầu cùng thượng lưu của nó có vai trò rất hệ trọng đối với việc bảo vệ miền đồng bằng và Kinh đô Thăng Long. Trừ vùng thượng lưu có núi non hiểm trở ra, đoạn từ Thái Nguyên trở xuống có thể qua được, nhưng mặt sau lại có dãy Tam Đảo chắn ngang nên khúc từ Đa Phúc đến Lục Đầu nhất là đoạn từ bến đò Như Nguyệt đến chân núi Nham Biền là thuận lợi nhất, có bến, có lối, qua sông dễ dàng. Dưới sự chỉ huy của Lý Thường Kiệt, quân và dân nhà Lý đã xây dựng tại đây một hệ thống phòng thủ kiên cố chưa từng có.

Để phòng thủ phía dưới được tốt, Lý Thường Kiệt đã cho quân chủ lực làm nhiệm vụ chặn đường quân Tống từ trại Vĩnh Bình trở xuống, đặt doanh trại tại các cửa ải, vì Vĩnh Bình là tâm điểm để đi vào các vùng Quảng Nguyên, Quang Lang và Tô Mậu. Cửa khẩu đầu tiên được quân Lý đặt doanh trại là cửa ải Quyết Lý (Nhân Lý, thuộc xã Văn Thụ, Lạng Sơn) ở phía bắc châu Quang Lang và cửa khẩu thứ hai được đặt ở phía nam của châu này là cửa ải Giáp Khẩu (Chi Lăng). Con đường hành quân duy nhất từ Nam Quan xuống Thăng Long của quân Tống buộc phải đi qua hai cửa ải hiểm yếu mà hai bên toàn là núi non hiểm trở và rừng rậm này. Hai cửa ải Quyết Lý và Giáp Khẩu cùng nằm trong hệ thống phòng tuyến nhưng nó chỉ mang ý nghĩa quan trọng khi thực hiện nhiệm vụ đánh tỉa lúc quân địch đặt chân vào Đại Việt. Còn phòng tuyến quan trọng bậc nhất có tính quyết định thắng lợi của cuộc chiến là phòng tuyến phía Nam sông Cầu (Như Nguyệt).

Để ngăn cản bước tiến của quân Tống qua sông, Lý Thường Kiệt đã cho đắp đê cao như bức tường thành ở mặt Nam sông Cầu. Bên trên đóng tre làm giậu dày mấy tầng. Bức tường thành kiên cố nhân tạo chạy dài gần 100 cây số từ chân dãy núi Tam Đảo trở xuống, bao bọc che đỡ cho cả hai vùng đồng bằng rộng lớn. Có sách viết rằng, phía Nam sông Như Nguyệt, Lý Thường Kiệt cho đắp chiến lũy bằng đất dọc bờ sông. Phía ngoài lũy, mặt giáp sông, ông sai đóng cọc tre làm giậu dày mấy tầng. Dưới bãi sông còn có những hố chông ngầm, giậu tre dày, tất cả những kiến trúc tự nhiên và nhân tạo đó được tổ chức lại, kết hợp chặt chẽ với nhau, tạo thành một chiến lũy kiên cố.

Như vậy, hệ thống thành lũy, đồn ải từ sông Như Nguyệt đến biên giới phía Bắc đều được củng cố. Lực lượng dự bị chiến lược gồm hai khối: khối bộ binh bố trí giữa vùng Thiên Đức và Thăng Long, khối thủy binh bố trí ở sông Lục Đầu. Tháng 11 năm 1076, quân và dân ta đã hoàn thành việc xây dựng tuyến phòng ngự và triển khai lực lượng trên các hướng.

Quân chủ lực được điều đến để chiến đấu trên phòng tuyến sông Như Nguyệt. Lý Thường Kiệt trực tiếp chỉ huy ở đây. Ông không dàn mỏng lực lượng trên chiến tuyến kéo dài đó mà bố trí binh lực có trọng điểm vừa kiểm soát bảo vệ được toàn bộ trận địa, vừa dễ dàng cơ động để có thể nhanh chóng tập trung quân đánh bại những mũi đột phá của địch hay tổ chức phản công khi thời cơ đã đến. Trên chiến tuyến, một bộ phận bộ binh đóng thành từng trại quân ở những vị trí xung yếu mà quân địch có thể vượt sông tiến công nhằm chọc thủng chiến tuyến của ta. Trong số các trại quân đó có ba trại quan trọng bố trí ở Như Nguyệt, Thị Cầu, Phấn Động. Hai trại quân Như Nguyệt và Thị Cầu khống chế hai bến đò ngang và con đường tiến về Thăng Long. Vùng Phấn Động (xã Tam Đa, Yên Phong) ngược lên phía bắc đến Thọ Đức và xuôi xuống phía nam đến Đại Lâm (đều thuộc xã Tam Đa) xưa kia là cánh rừng rậm, không có bến đò ngang, nhưng ở đây dòng sông hẹp, giữa sông lại có ghềnh đá Can Vang (khoảng ngang thôn Thọ Đức), quân địch có thể bắc cầu vượt sông. Trại quân Phấn Động có nhiệm vụ bảo vệ đoạn phòng tuyến này, đề phòng quân địch lợi dụng địa hình có lợi để tổ chức vượt sông. Ở mỗi trại quân, ngoài bộ binh có thể có một số thủy binh phối hợp. Thuyền chiến của ta đậu ở ven sông bên phía bờ Nam. Nhưng đại bộ phận thủy binh đóng tập trung ở Vạn Xuân về phía cực đông của chiến tuyến.

Vạn Xuân là một vị trí chiến lược trọng yếu ở vào đầu mối của tất cả các đường thủy vùng Đông Bắc. Từ Vạn Xuân, thủy binh của ta có thể ngược dòng sông Lục Nam, sông Thương, sông Cầu tiến sâu vào địa bàn vùng Đông Bắc, có thể xuôi sông Bạch Đằng, sông Thái Bình ra biển, lại có thể theo sông Đuống về Thăng Long. Lực lượng thủy binh đóng ở Vạn Xuân do hai hoàng tử Hoằng Chân và Chiêu Văn chỉ huy, có trên 400 thuyền chiến và hơn hai vạn quân. Nhiệm vụ của đoàn binh thuyền này là sẵn sàng cơ động tiếp ứng cho mọi mặt trận khi cần thiết và đặc biệt là phối hợp với chủ lực bộ binh bảo vệ chiến tuyến sông Như Nguyệt và tổ chức phản công, thực hành những trận quyết chiến.

Lý Thường Kiệt trực tiếp nắm đại bộ phận bộ binh, đóng tập trung ở phủ Thiên Đức, phía sau chiến tuyến. Địa điểm đóng quân là một vị trí cơ động có thể khống chế mọi ngả đường tiến về Thăng Long và kịp thời chi viện cho các hướng trên chiến tuyến mỗi khi bị tiến công. Đại quân có nhiệm vụ sẵn sàng sử dụng binh lực tập trung tổ chức phản kích đánh bại mọi mũi tiến công của địch và giữ vai trò lực lượng chủ yếu trong cuộc phản công chiến lược sau này. Lực lượng quân chủ lực bố trí trên chiến tuyến sông Như Nguyệt, gồm cả quân bộ và quân thủy, lên đến 6 vạn quân.

Cuối năm Bính Thìn - 1076, quân xâm lược Tống vượt biên giới, tiến công vào nước ta. Sách Việt sử lược đời Trần chép: “Mùa thu, tháng 7, Tống lấy Quảng Tây tuyên phủ sứ Quách Quỳ, Triệu Cao (Triệu Tiết) làm chiêu thảo sứ, thống lĩnh 9 tướng quân tới đánh nước ta" (Việt sử lược, Nxb. Văn Sử Địa, H., 1960, trang 111). Quân Tống chia thành hai cánh nhằm mục tiêu là thành Thăng Long. Cánh chính do Quách Quỳ chỉ huy. Quân dân ta dựa vào các thành ải và địa hình hiểm trở kiên cường ngăn chặn địch ngay từ biên giới. Quân địch mạnh hơn, vượt qua được. Quân dân ta quay lại giữ các căn cứ phía sau và đánh địch trên các đường giao thông phía sau chúng.

Ngày 18 tháng 11 năm 1077, các mũi tiến công của quân Tống đến bờ bắc sông Như Nguyệt. Đúng như dự kiến của Lý Thường Kiệt, đến đây bộ binh và kỵ binh địch bị chặn đứng lại trước chướng ngại tự nhiên là dòng sông và chiến tuyến kiên cố của quân ta ở bờ nam Như Nguyệt. Đây chính là nơi và cũng là lúc quân thủy, bộ của địch cần phối hợp với nhau, tổ chức vượt sông để tiến thẳng về Thăng Long như kế hoạch hành quân của chúng đã vạch ra. Nhưng trước đó, thủy binh Tống đã bị đội thuyền binh ta, do Lý Kế Nguyên chỉ huy, chặn lại ở Vĩnh An. Quân Tống cố gắng đánh mở đường để theo sông Đông Kênh tiến vào cửa sông Bạch Đằng, nhưng 10 trận liền bị quân ta đánh bại, không thể tiến lên nổi. Tiến không được, lui không xong, vì rút lui về nước sợ bị tội, thủy binh địch đành đóng ở cửa sông Đông Kênh để chờ đợi tin tức của bộ binh. Cho đến khi có lệnh của triều đình gọi về, bọn thủy binh này mới biết chiến tranh đã thất bại và kết thúc!. Đó là một thắng lợi có ý nghĩa chiến lược của quân ta nằm trong toàn bộ kế hoạch của Lý Thường Kiệt.

Đại quân của Quách Quỳ chờ mãi không thấy tăm tích thủy binh đến để hiệp đồng vượt sông, Quách Quỳ đành phải quyết định tạm đóng quân lại ở bờ Bắc sông Như Nguyệt. Với ý đồ chuẩn bị vượt sông, tiếp tục cuộc tiến công đánh chiếm Kinh thành Thăng Long, nên địch không dàn đều lực lượng trên trận tuyến dài mà chúng đóng thành từng khối ở những vị trí xung yếu nhất là những bến đò, những con đường thuận lợi tiến về Thăng Long. Một bộ phận quan trọng quân Tống do phó tướng Triệu Tiết chỉ huy đóng ở bờ Bắc bến đò Như Nguyệt vùng thôn Mai Thượng, xã Mai Đình, huyện Hiệp Hòa, tỉnh Bắc Giang. Đại bản doanh của Quách Quỳ đóng ở phía đông, cách khu đóng quân của Triệu Tiết, Miêu Lý 60 dặm (khoảng 30 kilômét). Đó là địa điểm đối diện với Thị Cầu (Đáp Cầu, thành phố Bắc Ninh ngày nay). Đây là vị trí trọng yếu nằm trên đường thiên lý.

Như vậy, địch chia quân làm hai khối lớn cho chánh tướng và phó tướng trực tiếp chỉ huy, đóng cách nhau hơn 30 kilômét ở Bắc sông Như Nguyệt trước mặt hai bến đò lớn (bến Như Nguyệt và bến Thị Cầu) nằm trên hai trục đường quan trọng tiến về Thăng Long. Điều này chứng tỏ quân địch vẫn giữ đội hình tiến công và tạm đóng quân lại để tìm cách vượt sông Cầu, chọc thủng phòng tuyến quân ta, mở đường tiến đánh Thăng Long. Khoảng giữa hai khối quân lớn, địch còn đóng giữ một số vị trí cần thiết để có thể liên hệ, tiếp ứng cho nhau khi tổ chức vượt sông hoặc bị tiến công. Trong số các vị trí đó có địa điểm núi Tiên Lát ở thôn Hạ Lát, xã Tiên Sơn (huyện Việt Yên, tỉnh Bắc Giang) ngày nay. Khu núi Tiên Lát gồm có Núi Voi, núi Chúc, núi Lều, núi Phượng Hoàng... cao dưới 80 mét. Đứng trên núi Phượng Hoàng có thể nhìn rõ một vệt dài ở bờ Nam sông Như Nguyệt từ xã Dũng Liệt đến xã Hòa Long (đều thuộc huyện Yên Phong) và đến cả vùng Thị Cầu.

Tiến xuống bờ Bắc sông Như Nguyệt, quân Tống chỉ còn cách Thăng Long khoảng 20 kilômét (tính theo đoạn Như Nguyệt - Thăng Long). Quách Quỳ nóng lòng muốn đánh chiếm Thăng Long để thực hiện kế hoạch đánh nhanh thắng nhanh như vua Tống đã căn dặn. Việc Quách Quỳ phải tạm dừng lại đợi thủy quân vào hiệp đồng tác chiến là rất bất đắc dĩ. Sau một thời gian không thấy thủy quân, Quách Quỳ và Triệu Tiết quyết định tự tổ chức vượt sông bằng lực lượng bộ binh và kỵ binh.

Tướng Tống là Vương Tiến được lệnh bắc cầu phao qua bến Như Nguyệt để cho đội quân xung kích của Miêu Lý sang sông. Đội quân này khoảng hai nghìn tên nhờ cầu phao mà qua sông dễ dàng và sau đó chọc thủng được chiến tuyến của quân ta. Sau khi chiếm được đầu cầu, Miêu Lý chủ quan, tự mãn, không cần chờ đại quân qua sông mà phát triển tiến công đánh về hướng Thăng Long. Các vệ quân chủ lực của ta bố trí trên tuyến phòng ngự lập tức cơ động đánh trả, cắt ngang đội hình địch, không cho quân Tống sang sông. Cũng trong lúc này, một cánh quân ta, được lệnh của Lý Thường Kiệt, từ hướng Thăng Long tiến lên phản kích mạnh mẽ vào sườn cánh quân Miêu Lý. Quân Tống mới qua sông Như Nguyệt, đi được khoảng mười dặm thì bị vây đánh tứ phía một cách quyết liệt, chúng bị thương vong lớn, vội vã tháo chạy. Quân ta đuổi theo đánh gấp. Những tên sống sót cùng Miêu Lý hốt hoảng chạy về Như Nguyệt. Nhưng đến nơi thì cầu phao đã bị cắt và quân ta đã chẹn đường về của chúng. Bên kia sông, quân địch cho bè sang cứu nhưng không có kết quả. Quân địch hỗn loạn, một số nhảy xuống sông bơi được về bờ bắc. Miêu Lý dùng thuyền nhỏ chạy thoát. Hầu hết cánh quân xung kích của y bị quân ta tiêu diệt. Cuộc tiến công lần thứ nhất của quân Tống đã bị đập tan nhanh chóng.

Sau trận đó, Quách Quỳ lại huy động một lực lượng mạnh hơn và đóng bè lớn chở quân qua sông lần thứ hai. Mỗi lần bè đưa được 500 tên. Bè không có nhiều, chở quân sang lại phải quay về đón số mới. Hết lớp này đến lớp khác, quân Tống đổ sang bờ nam Như Nguyệt rồi xông lên phá bãi chướng ngại ven sông. Chúng chặt đốt những hàng rào bằng tre, nhưng hàng rào mấy tầng rất khó phá. Quân ta từ trên chiến lũy lại đánh xuống dữ dội, làm cho địch lớp trước bị tiêu diệt, lớp sang cứu viện cũng bị đánh tan.

Hai lần vượt sông, hai lần thất bại thảm hại, vì thế nên còn trong tay gần nguyên vẹn số quân 10 vạn, số phu 20 vạn mà Quách Quỳ không dám nghĩ đến tiến công nữa. Quách Quỳ quyết định dứt khoát phải chờ thủy binh và buồn rầu ra lệnh: “Ai bàn đánh sẽ chém". Chủ lực của địch là bộ binh và kỵ binh đã không thể liên hệ được với thủy binh và bị chặn đứng trước chiến tuyến sông Như Nguyệt. Quân địch tuy chiếm được khu Đông Bắc và Bắc ngạn sông Cầu nhưng đã mất thế chủ động tiến công và bị hãm trong một địa bàn rất bất lợi. Đó là vùng thượng du và trung du, dân cư thưa thớt, quân Tống không thể vơ vét cướp bóc được. Lương ăn của đạo quân xâm lược hoàn toàn trông chờ vào việc vận chuyển tiếp tế bằng đường bộ của dân phu.

Quân dân ta vòng sau lưng địch lại phát triển các hoạt động du kích quấy rối liên tục. Những đoàn phu vận chuyển lương thực của quân Tống luôn bị chặn đánh. Những đội quân thượng du của ta cùng với bà con các dân tộc thiểu số len lỏi trong rừng sâu, núi cao thường bất ngờ tiến ra đánh tỉa. Hoạt động mạnh nhất là đạo quân của phò mã Thân Cảnh Phúc, người dân tộc Tày ở vùng động Giáp. Quân địch ngày càng bị tiêu hao, mệt mỏi, hoang mang lo sợ vì những hoạt động du kích lợi hại đó.

Hai tháng đã trôi qua, quân Tống ngày càng bị tiêu hao về số lượng và đặc biệt nghiêm trọng là chúng không thể vơ vét cướp bóc của cải được. Như trên đã nói, lương ăn của đạo quân xâm lược này hoàn toàn trông chờ vào việc vận chuyển bằng đường bộ của dân phu. Viên quan chuyển vận sứ Lý Bình Nhất đã tính phải có 40 vạn phu, nhưng nhà Tống chỉ điều được 20 vạn. Do đó, một số vũ khí và tên sắt của quân lính đã phải bỏ lại, lương thực không mang được nhiều.

Quân Tống tuy thế suy, lực giảm nhưng vẫn còn một số lượng khá đông. Chúng vẫn đóng trên một trận tuyến dài khoảng 30 kilômét ở bờ bắc sông Như Nguyệt. Từ lúc chuyển sang thế tạm thời cố thủ, chúng không dám tiến công ta dù bị khiêu khích, nhưng lại có âm mưu nhử quân ta sang bờ bắc để tiêu diệt. Trong điều kiện quân địch còn đông và lo phòng thủ như vậy nên ta không thể mở cuộc tổng tiến công bao vây tiêu diệt toàn bộ quân địch. Lý Thường Kiệt chủ trương mở nhiều cuộc công kích để vừa có thể chia sẻ lực lượng vừa tiêu diệt được nhiều địch. Hai đối tượng chính mà Lý Thường Kiệt dự kiến tập trung lực lượng đánh vào là khối quân của Quách Quỳ và Triệu Tiết.

Lý Thường Kiệt cử hai hoàng tử Hoằng Chân và Chiêu Văn đem 400 chiến thuyền chở hai vạn quân từ Vạn Xuân ngược sông Như Nguyệt mở một cuộc tiến công vào doanh trại Quách Quỳ. Hai hoàng tử đã chiếm núi Nham Biền, rồi từ đó đánh thẳng vào doanh trại quân Tống. Trước sức tiến công mãnh liệt của quân ta, quân Tống phòng ngự ở vòng ngoài chống cự không nổi buộc phải rút chạy. Thừa thắng quân ta chia thành nhiều mũi đánh sâu vào mặt đông và đông nam doanh trại Quách Quỳ. Sợ quân ta thừa thắng đánh tràn vào đại bản doanh, Quách Quỳ phải điều động phần lớn lực lượng dự bị gồm 7.000 kỵ binh để ngăn chặn cuộc phản công của quân ta. Các viên tướng chủ chốt như Yên Đạt, Thế Cự, Vương Mãn, Lý Thường, Điền Chủng đều phải xuất trận để bảo vệ đại bản doanh Quách Quỳ. Do có lực lượng lớn, quân Tống tiếp tục tăng quân phản kích, quân ta buộc phải rút xuống thuyền. Ở trên bờ địch dùng cung nỏ và máy bắn đá bắn theo dữ dội làm cho một số thuyền chiến của ta bị đắm và gây thương vong lớn. Cả hai hoàng tử Hoằng Chân, Chiêu Văn và mấy nghìn quân sĩ đã anh dũng hy sinh.

Cuộc tiến công bằng thủy binh quân ta mặc dù bị tổn thất nhưng đã gây cho địch nhiều thiệt hại nặng về lực lượng cũng như đảo lộn về thế trận. Cuộc tấn công chính diện này không chỉ nhằm tiêu diệt sinh lực địch mà còn nhằm thu hút lực lượng và tập trung sự chú ý của các khối quân địch vào đây. Việc đó tạo nên thời cơ cho mũi tiến công khác, mũi tiến công chủ yếu của Lý Thường Kiệt, bất ngờ tập kích vào chỗ sơ hở của địch để giành thắng lợi quyết định.

Trong lúc chánh tướng Quách Quỳ mải lo đối phó với sự tiến công mãnh liệt của thủy binh ta, phó tướng Triệu Tiết và các tướng phụ trách các doanh trại khác cũng chăm chú theo dõi diễn biến chiến sự ở đó, thì gần như đồng thời, Lý Thường Kiệt trực tiếp chỉ huy đại quân ban đêm vượt bến đò Như Nguyệt, đánh úp doanh trại phó tướng Triệu Tiết ở xã Mai Đình đối diện với bến đò Như Nguyệt. Số quân Lý Thường Kiệt chỉ huy là 3 vạn người vượt sông trong đêm tối đánh vào sườn tây doanh trại Triệu Tiết ở thôn Mai Thượng, xã Mai Đình. Các đạo quân của ta đồng loạt phát triển tiến công đánh chiếm các quân Tống ở khu vực chùa Tiên Sát và Ải Quan. Cùng lúc đó, một cánh quân của ta phòng ngự ở biên giới, khi địch tràn qua đã tổ chức dàn thế trận từ Bắc Sơn theo hướng Hiệp Hòa cũng đánh vào sau lưng cụm quân Triệu Tiết. Thế trận cụm quân Triệu Tiết bị vỡ, hơn 2 vạn tên bị diệt. Sách Việt sử lược thời Trần chép: “Lý Thường Kiệt biết rằng quân Tống sức lực đã khốn, đang đêm sang sông đánh úp, đại phá được. Quân Tống 10 phần chết 5, 6" (Việt sử lược, Sđd, tr.111). Triệu Tiết phải lên ngựa cùng với đội thân quân mở đường chạy sang trại quân Quách Quỳ. Các cánh quân chủ lực của ta hợp lại như hai gọng kìm từ mặt tây và đông doanh trại Quách Quỳ, xiết chặt lấy chúng.

Sử sách ghi chép quá sơ sài về diễn biến của trận tập kích này. Đại Việt sử ký toàn thư ghi: “Một đêm quân sĩ chợt nghe ở trong đền Trương tướng quân có tiếng ngâm to rằng:

Nam quốc sơn hà Nam đế cư,
Tiệt nhiên định phận tại thiên thư.
Như hà nghịch lỗ lai xâm phạm?
Nhữ đẳng hành khan thủ bại hư.

Dịch:
Sông núi nước Nam vua Nam ở,
Cõi bờ ngăn cách tự sách trời.
Cớ chi quân giặc sang xâm lấn?
Thất bại bay xem sẽ đến nơi.

Rồi sau quả nhiên như thế. (Đại Việt sử ký toàn thư, Nxb. Khoa học Xã hội, H., 1972, tr.238).

Đây chính là bài thơ thần khích lệ tinh thần yêu nước thành sức mạnh chiến đấu trực tiếp diệt quân thù. Bài thơ là một lời khẳng định hùng hồn cho một chân lý của tạo hóa là: Nước Nam do người Nam làm chủ, đó là chủ quyền thiêng liêng bất khả xâm phạm, bất chấp đó là ai, nếu đi ngược lại chân lý của tạo hóa là xâm lược lãnh thổ nước Nam thì chắc chắn sẽ chuốc lấy thất bại. Nhân dân địa phương vẫn truyền tụng nhiều chi tiết và chỉ rõ những di tích ghi lại chiến công oanh liệt này, khu vực doanh trại địch biến thành bãi chiến trường. Hàng vạn xác giặc nằm ngổn ngang khắp cánh đồng, gò đất. Nhân dân địa phương gọi là cánh đồng Xác, gò Xác.

Thất bại này của quân Tống thật quá nặng nề. Chỉ trong một đêm, toàn bộ doanh trại gồm 3, 4 vạn quân bị đánh tan tành, binh sĩ thương vong gần hết. Thắng lợi của cuộc tập kích xuất phát từ bến Như Nguyệt này cộng với những thiệt hại mà quân ta đã gây ra cho địch ở khối quân Quách Quỳ làm cho thế phòng ngự của quân Tống ở bờ Bắc sông Như Nguyệt bị rung chuyển hoàn toàn.

Trong lúc quân Tống có nguy cơ bị tiêu diệt toàn bộ, Lý Thường Kiệt cử “biện sĩ” tới bản doanh của Quách Quỳ nói rằng hạ chiếu rút đại binh về, thì sẽ lập tức sai sứ sang tạ tội và triều cống. Trong tình thế nguy khốn Quách Quỳ đã thốt lên: “Ta không đạp đổ sào huyệt giặc bắt được Càn Đức để bảo mệnh triều đình, đó là bởi trời! Thôi ta đành liều một thân, chịu tội với triều đình, để mong cứu hơn 10 vạn nhân mạng “ (La Sơn Yên Hồ, Hoàng Xuân Hãn, Tập 2, Nxb. Giáo dục, 1998, tr.432).

Khi triều đình Tống nhận được tin, Tống Thần Tông giận lắm, định điều thêm viện binh để cố qua sông, nhưng nhiều quần thần can ngăn rằng chiến tranh sẽ kéo dài, hao người tốn của, Tống Thần Tông nuốt hận phải nghe theo. Quách Quỳ định ngày rút quân, nhưng không dám công khai vì viên chủ tướng này vẫn nơm nớp lo sợ quân Lý đuổi theo, đành bí mật thực hiện kế hoạch của mình. Đang đêm, vào đầu tháng 2 năm Đinh Tỵ (3-1077), Quách Quỳ lệnh cho quân sĩ lập tức rút quân. Vẫn chưa hết khiếp đảm vì những trận tập kích vừa qua, quân sĩ Tống nghe lệnh rút lui đã tranh nhau tháo chạy trong cảnh hỗn loạn.

Trong tình thế rút lui của quân Tống như vậy, việc truy kích tiêu diệt chúng không có gì khó khăn, nhưng Lý Thường Kiệt đang muốn mau chóng đem lại hòa bình cho đất nước và không muốn bội ước nên đã để cho quân Tống rút lui một cách yên ổn. Nhưng về đất đai thì khi quân Tống rút lui đến đâu, Lý Thường Kiệt đã cho quân tiến theo chiếm lại đến đó. Quân dân nhà Lý thu hồi ngay được các châu Quang Lang, Môn, Tô Mậu và Tư Lang một cách nhanh chóng. Còn châu Quảng Nguyên (Cao Bằng) thì hai năm sau (1079) nhà Tống phải trao trả nốt cho Đại Việt.

Từ trận đột kích Ung Châu đến trận tập kích Như Nguyệt (Mai Thượng) 30 vạn lính và phu của nhà Tống bị tiêu diệt. Trong lần xuất chinh năm 1076-1077 thì 10 vạn quân ra đi, khi về đến nước Tống (4-1177) chỉ còn hơn 2 vạn (23.400), 8 vạn trong số 20 vạn phu đã bỏ mạng, ngựa 1 vạn chỉ còn 3.174 con. Toàn bộ chi phí chiến tranh được người Tống tính ra là 5.190.000 lạng vàng.

Chiến thắng Như Nguyệt năm 1077 là thắng lợi oanh liệt của trận quyết chiến chiến lược có ý nghĩa kết thúc chiến tranh. Cuộc kháng chiến chống Tống xâm lược của quân dân Đại Việt đời Lý đã thu được thắng lợi hoàn toàn. Kinh đô Thăng Long được bảo vệ nguyên vẹn, bất khả xâm phạm.

Sau chiến thắng, để cho nhà Đại Tống đỡ mất mặt, để khôi phục hòa bình lâu dài giữa hai nước, triều đình Lý cử phái đoàn sứ giả Đại Việt lên đường sang kinh đô Tống. Từ Kinh đô Thăng Long, sứ thần ta mang theo quốc thư và cống phẩm của Lý Nhân Tông gửi Tống Thần Tông. Với lời lẽ thương thuyết kiên quyết và mềm dẻo của sứ thần nước ta, lại “có cái oai thắng trận, người trung châu phải sợ” (theo sử thần Ngô Sĩ Liên), triều đình Tống phải chấp nhận điều kiện là bên ta thả 1.000 tù binh, bên Tống trả lại cho ta châu Quảng Nguyên. Triều đình Tống phải chính thức công nhận Đại Việt là một quốc gia độc lập “An Nam quốc”. Quan hệ giữa hai nước Việt - Tống trở lại bình thường.

Ý đồ đánh chiếm Đại Việt mà nhà Tống đã theo đuổi gần một thế kỷ đến đây bị đánh bại. Nhà Tống còn trị vì ở Trung Quốc hơn 200 năm nữa (1077 - 1257), nhưng không dám tiếp tục gây chiến với ta. Kinh đô Thăng Long từ khi định đô được an toàn trong gần 250 năm (1010 - 1257).

Từ thực tiễn cuộc kháng chiến chống quân Tống xâm lược thời Lý, đặc biệt là qua chiến thắng Như Nguyệt năm 1077, ta có thể rút ra đôi điều về nghệ thuật quân sự:

*   Tư tưởng tích cực chủ động phòng ngự và tiến công quân địch là nét đặc sắc của nghệ thuật quân sự nhà Lý. Trong quá trình chiến tranh, ta đã vận dụng cả phương thức tác chiến tiến công và phương thức tác chiến phòng ngự. Lý Thường Kiệt đã kết hợp khéo léo giữa hai phương thức đó hỗ trợ lẫn nhau nhằm mục đích tiêu diệt địch, giành thắng lợi triệt để. Quân ta phòng ngự trên chiến tuyến Như Nguyệt không phải vì yếu và bị động mà đó là trận tuyến phòng ngự hoàn toàn chủ động, tích cực, nhằm mục đích chặn đứng quân Tống, làm thất bại kế hoạch tiến công của địch, từng bước làm suy yếu và đẩy đạo quân Quách Quỳ, Triệu Tiết vào thế bất lợi để quân ta chuyển sang tiến công tiêu diệt chúng. Phòng ngự ở hướng chủ yếu là chiến tuyến Như Nguyệt, tiến công hướng thứ yếu ở sông Đông Kênh. Trước mặt địch thì phòng ngự đánh trả chúng quyết liệt, đập tan những cuộc tiến công của chúng, kiên quyết phản kích khi chúng lọt vào trận địa phòng ngự, sau lưng địch thì tiến công liên tục dùng mọi lực lượng bằng mọi thủ đoạn, tập kích, phục kích, quấy rối... Khi mục đích phòng ngự đã đạt được nhanh chóng chuyển sang tiến công tập kích giành thắng lợi quyết định.
*   Lý Thường Kiệt không những đã xây dựng cho quân dân nhà Lý có tinh thần hăng hái chống giặc cứu nước rất cao mà còn xác định một phương thức đánh địch tài giỏi và sáng tạo. Qua diễn biến trận chiến Như Nguyệt năm 1077, một trong những vấn đề nổi bật về nghệ thuật chỉ đạo chiến tranh của Lý Thường Kiệt là vấn đề xác định cách đánh. Sau khi giành thắng lợi trên chiến trường Ung - Khâm - Liêm, Lý Thường Kiệt chủ trương sử dụng một phần lực lượng để tổ chức phòng ngự trên sông Như Nguyệt. Sử dụng phương thức tác chiến phòng ngự, quân ta đã tiêu diệt, tiêu hao được nhiều quân Tống trong quá trình chúng tiến công sang ta, làm cho địch bị tổn thất về lực lượng chiến lược hết sức nặng nề. Đồng thời ta cũng nhanh chóng phá tan được kế hoạch tiến công chiến lược tốc quyết của Quách Quỳ. Với hình thức tác chiến phòng ngự, quân ta đã làm cho quân Tống mất khả năng tiến công, hoàn toàn lâm vào thế bị động, buộc phải chuyển sang cầm cự cố thủ với ta. Trước tình thế đó, Lý Thường Kiệt đã lập tức tung toàn lực tiến công chiến lược để tiêu diệt toàn bộ đạo quân viễn chinh xâm lược Tống. Đòn tiến công này đã nhanh chóng giành thắng lợi, thực hiện trận then chốt quyết định, kết thúc chiến tranh một cách toàn thắng.
*   Trong chỉ đạo tác chiến, Lý Thường Kiệt còn sử dụng và kết hợp chặt chẽ giữa phương thức tập trung đánh lớn của quân chủ lực với phân tán đánh nhỏ của quân địa phương cùng dân binh, kết hợp giữa tác chiến trận địa với tác chiến cơ động; giữa tiến công với phòng ngự để đánh địch. Phép dụng binh mưu lược trên đây của Lý Thường Kiệt đã tạo ra cho quân ta một thế chủ động hoàn chỉnh, vững mạnh và vô cùng lợi hại. Thực tế sự kiện lịch sử xảy ra trong trận Như Nguyệt chứng tỏ phép dụng binh mưu lược của Lý Thường Kiệt vượt xa trình độ và năng lực hoạt động thực tiễn về quân sự của bọn tướng lĩnh nhà Tống. Quách Quỳ, Triệu Tiết, Tô Giám và Dương Tùng Tiên đều là những tướng giỏi được vua Tống tin dùng, song trước nghệ thuật chỉ huy quân sự kiệt xuất của Lý Thường Kiệt, chúng biến thành những kẻ cầm quân bất tài. Đó là một trong những nhân tố dẫn đến sự thất bại thảm hại của quân Tống trong chiến tranh.
*   Nghệ thuật tạo và nắm thời cơ, hành động kịp thời được thực hiện thành công trong trận tiến công bắc sông Như Nguyệt. Sau khi kết thúc trận chiến phòng ngự thắng lợi, Lý Thường Kiệt đã sử dụng tổng lực mở trận phản công lớn để tiêu diệt toàn bộ lực lượng địch ở bờ Bắc sông Như Nguyệt. Quân ta đã giành được thắng lợi rất lớn, tiêu diệt cụm quân Triệu Tiết, đánh vỡ hệ thống phòng ngự tuyến ngoài, phía đông của cụm quân Quách Quỳ. Phát huy thắng lợi ban đầu, nắm lấy thời cơ thuận lợi này, Lý Thường Kiệt đã ra lệnh cho cả hai đạo quân chính, kỳ nhanh chóng tiến công hợp vây cụm quân Quách Quỳ. Tình hình đó dẫn tới khả năng Quách Quỳ không dám liều mạng tử chiến trong thế không có chiến thành phòng ngự vững chắc mà khả năng Quách Quỳ sẽ tổ chức phá vây, tháo chạy về nước. Do tạo ra được thời cơ như vậy, Lý Thường Kiệt đã mở lối thoát cho quân Tống, chủ động “giảng hòa” để kết thúc chiến tranh, buộc chúng phải rút quân về nước. Quân Tống rời khỏi trận địa, rút chạy trong hoảng loạn, tinh thần suy sụp.... Quân Tống rút lui đến đâu, quân ta tiến theo thu hồi đất đai đến đó.
*   Ngoài việc sử dụng phương thức đánh địch một cách sáng tạo và chính xác, Lý Thường Kiệt còn rất giỏi trong việc sử dụng nhân tố bất ngờ để đánh địch. Ông đã chỉ huy đại quân tiến công cụm quân Triệu Tiết, tạo được thế đánh hết sức bất ngờ, tiêu diệt cụm quân Triệu Tiết, rồi thừa thắng chuyển sang tiến công cụm quân chủ yếu của Quách Quỳ, dồn quân Tống vào thế cùng lực kiệt, buộc phải giảng hòa, xin rút quân về nước. Nhân tố bất ngờ trong chiến tranh đã được Lý Thường Kiệt biến thành một sức mạnh quân sự rất lớn, khó có thể định trước. Đây là một nội dung nói lên nghệ thuật dụng binh mưu lược thiên tài của Lý Thường Kiệt và cũng là một bài học lịch sử vô cùng quý báu về quân sự của dân tộc ta.

Trận Như Nguyệt năm 1077 đã để lại bài học lớn về quân sự trong cuộc chiến tranh bảo vệ Tổ quốc. Bằng chiến tuyến sông Như Nguyệt, dưới sự chỉ huy tài giỏi của Lý Thường Kiệt, quân và dân ta đã chặn đứng và đập tan mọi cuộc tiến công của quân địch và làm thất bại chiến lược đánh nhanh thắng nhanh của nhà Tống và kẻ thù bị giam hãm trong một địa bàn bất lợi. Khi quân địch đã bị động, mệt mỏi, suy yếu, Lý Thường Kiệt sáng suốt nắm lấy thời cơ giành quyền chủ động mở cuộc phản công nhanh chóng đánh tan quân địch. Đây là cuộc tập kích quy mô lớn, phối hợp chặt chẽ giữa quân thủy và quân bộ. Đặc biệt cuộc kháng chiến đó thể hiện nổi bật tư tưởng chủ đạo là chủ động tiến công, dù có lúc ta ở thế phòng ngự gay go phức tạp.

Chiến tuyến sông Như Nguyệt là một công trình lớn của quân dân ta ở thế kỷ XI, được xây dựng một cách hợp lý, khoa học. Đặc điểm nổi bật của thế trận này là bố trí trên diện rộng, có chiều sâu, có trọng điểm, phối hợp chặt chẽ giữa quân chủ lực với quân địa phương nhằm đánh địch cả phía trước và sau lưng. Trong lịch sử chống ngoại xâm của dân tộc ta, Lý Thường Kiệt là người duy nhất thực hiện thắng lợi phòng ngự có quy mô lớn theo kiểu chiến tuyến kết hợp với nhân công.

Từ hành động tiến công sang đất địch, phá bàn đạp tiến công của chúng, tranh thủ thời gian thực hành chuẩn bị ở trong nước, làm cho địch suy yếu phải chuẩn bị lại, để ta có điều kiện xây dựng phòng tuyến, đến hành động phòng ngự kiểu chiến tuyến theo sông nhằm chặn đứng quân địch, phát huy thế mạnh của ta, khoét sâu chỗ yếu của địch, đánh địch bằng cả chặn trước đánh sau, buộc quân địch phải chuyển từ tiến công sang phòng ngự, tạo điều kiện và thời cơ để quân ta thực hành phản công và giành thắng lợi.

Khi rút quân về lập tuyến phòng ngự trên sông Như Nguyệt, Lý Thường Kiệt đã lập một thế trận phòng ngự rất tốt: Dựa vào bờ nam sông để đắp lũy, dùng dòng sông làm vật chướng ngại thiên nhiên lợi hại, có lực lượng mạnh chặn địch trực tiếp ở bờ nam sông, có lực lượng của quân và dân tại chỗ phía bắc sông Như Nguyệt dựa vào địa hình hiểm trở của đất nước để chặn địch từ xa, suốt từ biên giới phía Bắc, lại có lực lượng dự bị cơ động bố trí ở phía sau, bộ binh trên hướng Thăng Long, thủy binh trên hướng Lục Đầu. Thế trận phòng ngự đó phát huy được sức mạnh của quân và dân, khai thác thế lợi của địa hình, thời tiết nước ta, tăng cường khả năng tiến công trong phòng ngự của quân và dân ta. Với quan điểm quân sự ngày nay, đó là một thế trận rất hiện đại mang đặc tính của nghệ thuật chiến tranh nhân dân Việt Nam. Đó là cách hay nhất để bảo vệ Kinh đô Thăng Long từ xa. Triệt phá các căn cứ quân sự của quân Tống ở Ung, Khâm, Liêm, đánh địch suốt từ biên giới phía Bắc đến sông Như Nguyệt rồi chặn đứng trên sông Như Nguyệt bằng cố gắng phối hợp của các lực lượng trên toàn bộ thế trận phòng ngự. Cuối cùng là phản công chiến lược mạnh mẽ, gây tổn thất lớn cho địch, đưa chúng vào thế cùng và buộc chúng phải lui quân, ta thu hồi lãnh thổ trọn vẹn.

Vừa đánh vừa đàm buộc địch phải chịu thua. Đánh thắng lại đàm để buộc địch phải công nhận độc lập chủ quyền nước ta, lập lại quan hệ hòa bình lâu dài giữa hai nước mà không mất thể diện của nước lớn. Vừa chuẩn bị đánh quân Tống xâm lược, vừa thuyết phục vua Chiêm Thành không đưa quân hội chiến theo chiếu dụ nhà Tống. Đó là những nét rất đặc sắc của nghệ thuật quân sự thời Lý.', 'TEXT', '2026-06-05 05:17:47.214003', '2026-06-05 05:17:47.21398', null, 'DRAFT'), ('d7db973a-5191-45e3-bf1c-6cab05d8ad89', '687b57fe-865c-496a-83b3-f83690885dd1', 'f1a45c4c-69b9-47e5-907c-ae2236a79f69', 'CONTEXT', 'Chi tiết trận Ngọc Hồi - Đống Đa', null, 'Chiến thắng Ngọc Hồi - Đống Đa năm 1789 là một trong những chiến công hiển hách bậc nhất trong lịch sử chống ngoại xâm của dân tộc ta. Chỉ trong khoảng thời gian rất ngắn, đặc biệt trong 5 ngày đêm đầu tiên của mùa Xuân Kỷ Dậu, từ đêm 30 Tết đến trưa ngày mồng 5 Tết (tức là từ 25 đến 30-1-1789), bằng một trận quyết chiến chiến lược, quân và dân ta dưới sự lãnh đạo kiệt xuất của người anh hùng áo vải Quang Trung - Nguyễn Huệ đã quét sạch 29 vạn quân xâm lược Mãn Thanh ra khỏi bờ cõi, giữ vững nền độc lập dân tộc.

Trong những năm 80 của thế kỷ XVIII, sau khi đánh đổ ách thống trị của các thế lực phong kiến Nguyễn ở Đàng Trong và đánh bại cuộc xâm lược của quân Xiêm ở phương Nam, phong trào Tây Sơn phải gánh vác nhiệm vụ lịch sử trọng đại là đánh đổ tập đoàn phong kiến Lê - Trịnh ở phía Bắc, tiếp đó là đánh đuổi quân xâm lược Mãn Thanh.

Sau cuộc tiến quân lần thứ hai ra Bắc Hà để trừng trị Vũ Văn Nhậm do phản bội, và tổ chức lại bộ máy chính quyền mới, bố trí lực lượng trấn giữ Thăng Long, từ tháng 6 năm 1788, Nguyễn Huệ trở lại Phú Xuân. Lúc này lực lượng Tây Sơn trấn giữ Bắc Hà khoảng 1 vạn quân.

Để khôi phục lại Lê Chiêu Thống, tháng 7 năm Mậu Thân (1788), Hoàng Thái hậu nhà Lê sang nhà Thanh xin cầu viện.

Vua Càn Long nhà Thanh theo lời tâu của Tổng đốc Tôn Sĩ Nghị liền điều động binh sĩ 4 tỉnh Quảng Đông, Quảng Tây, Vân Nam, Quý Châu hẹn ngày sang cứu viện.

Ngày 22 tháng 11 năm Mậu Thân (1788), quân xâm lược nhà Thanh gồm 29 vạn quân chia làm bốn đạo ạt tiến vào nước ta. Đạo thứ nhất là quân chủ lực do Tổng đốc Lưỡng Quảng Tôn Sĩ Nghị chỉ huy đi qua Lạng Sơn vào cửa ải trấn Nam Quan. Trấn thủ Lạng Sơn là Đô đốc Nguyễn Văn Diệm lui quân. Ngô Văn Sở cử Đô đốc Phan Văn Lân dàn binh bày trận ở sông Nguyệt Đức. Nhưng quân của Lân vừa qua sông đã bị chết cóng vì lạnh và hoảng sợ trước thế mạnh của giặc nên bỏ chạy hết. Đạo quân của Tôn Sĩ Nghị vào đến địa phận nước ta mà không gặp phải một trở ngại nào.

Đạo quân thứ hai do tri phủ Điền Châu Sầm Nghi Đống chỉ huy qua Cao Bằng tiến xuống. Đạo quân thứ ba do Đề đốc Ô Đại Kinh tiến sang qua đường Tuyên Quang. Đạo thứ tư theo hướng Quảng Ninh tiến vào đóng ở Hải Dương.

Đợt tiến quân của quân Thanh không gặp một trở ngại nào là vì kế hoãn binh của Ngô Thì Nhậm đồng loạt cho rút quân. Ngô Thì Nhậm là một mưu thần rất sắc sảo của Nguyễn Huệ. Thấy quân giặc đông, Ngô Thì Nhậm chủ trương không đánh, chủ động rút lui để bảo toàn lực lượng, đồng thời nuôi chí khí kiêu binh và tư tưởng chủ quan của quân Thanh. Tướng Ngô Văn Sở lại muốn dốc quân đánh giặc ngay từ khi chúng mới bước chân đến. Thấy vậy, Ngô Thì Nhậm liền nói: “Nay ta chủ động rút lui, không bị mất một mũi tên nào, đó là kế lùi một bước mà tiến hai bước, đợi khi chúng chủ quan, sơ hở, ta sẽ tiến công đánh cho chúng không còn mảnh giáp mà về, đó mới là kế hay". Ngô Văn Sở nghe xong liền cho rút toàn bộ quân về Thăng Long, tổ chức một cuộc chuyển binh lớn trên Sông Hồng, rồi cho thủy binh lui về đóng giữ ở Biện Sơn, Thanh Hóa, bộ binh thì lui về giữ ở núi Tam Điệp, Ninh Bình, như thế là cả thủy và bộ liên kết thành một phòng tuyến vững chắc. Ngô Văn Sở liền đưa tin cấp báo về thành Phú Xuân cho Nguyễn Huệ. Nhận được tin, Nguyễn Huệ rất bình tĩnh bảo với ba quân: “Chó Ngô là cái thá gì. Chúng đến đây chỉ để tự đi đến chỗ chết. Việc gì phải cuống quýt làm vậy?". *(Chú thích: Nguyễn Thu, Lê quý kỷ sự, Nxb. Khoa học Xã hội, 1974, tr.120).*

Sau khi nghe tin Tôn Sĩ Nghị đem quân vào chiếm nước ta, các tướng đã bàn với Nguyễn Huệ rằng: “Chúa công vừa có hiềm khích với vua Thái Đức (Nguyễn Nhạc), dân chưa vững lòng tin cậy, nay nghe quân Thanh đến đánh như vũ bão tất sinh nghi ngại. Chỉ bằng trước hãy chính danh hiệu ra ơn đại xá để yên lòng những kẻ phản trắc bên trong, sau để quang minh chính đại mà mang quân chống giặc bên ngoài".

Nghe theo lời khuyên của các tướng, ngày 25 tháng 11 năm Mậu Thân (22-12-1788), Nguyễn Huệ mặc áo long cổn, đội mũ bình thiên tự tay vẽ kiểu, dẫn văn, võ bá quan làm lễ tế trời đất ở Bân Sơn, xưng làm hoàng đế, đổi niên hiệu Thái Đức năm thứ 11 thành niên hiệu Quang Trung năm thứ nhất (1788) để quang minh chính đại ra Bắc dẹp giặc.

Ngay ngày hôm ấy, Hoàng đế Quang Trung dốc toàn bộ quân ở thành Phú Xuân thẳng tiến ra Bắc.

Khi đi qua Nghệ An, Hoàng đế Quang Trung cho quân dừng lại hơn 10 ngày để tuyển thêm binh sĩ và thăm dò ý kiến của La Sơn phu tử Nguyễn Thiếp. Hàng vạn người hăng hái tham gia quân ngũ. Tổng số quân lên đến 10 vạn, chia làm 5 doanh. Một cuộc duyệt binh lớn đã được tổ chức tại dinh trấn Nghệ An.

Tại Thanh Hóa, nghĩa quân Tây Sơn được tiếp tục bổ sung thêm nhiều đinh tráng tự nguyện tòng quân diệt giặc, cứu nước. Những người lính Tây Sơn mới tuyển được phiên chế trong những đạo “Trung quân”, đặt ngay dưới quyền chỉ huy trực tiếp của Quang Trung - Nguyễn Huệ. Với cách phiên chế đó, những người lính cũ lính mới không khác gì nhau về chính sách đãi ngộ cũng như về trách nhiệm. Do đó, họ dễ dàng đoàn kết, trao đổi để nâng cao tinh thần chiến đấu và kỹ thuật, chiến thuật, đáp ứng yêu cầu của cuộc chiến đấu mới.

Vua Quang Trung lại cho người mang ra trước trao cho Tôn Sĩ Nghị thư giả vờ xin hàng lời lẽ trong thư rất nhã nhặn, khiêm tốn.

Về phần Tôn Sĩ Nghị thì từ lúc qua cửa ải, thấy không một ai dám đánh nên vênh váo tự cho mình là giỏi. Tôn Sĩ Nghị tuyên sắc thư của vua Càn Long phong Lê Chiêu Thống làm An Nam Quốc Vương, ban cho ấn vàng. Nay nhận được thư nhận tội của Nguyễn Huệ lại càng chủ quan, khinh suất, sai viết hịch bảo Nguyễn Huệ phải rút quân về Thuận Hóa chờ ngày xét hỏi, không được làm càn chuốc lấy tội.

Thấy Tôn Sĩ Nghị mắc mưu lơ là phòng thủ, vua Quang Trung cả cười thúc quân ngày đêm thần tốc ra Thăng Long. Trên đường đi, vua Quang Trung - Nguyễn Huệ làm lễ “Thệ sư” (một hình thức động viên quân sĩ) ở Thọ Hạc (Thanh Hóa). Vua Quang Trung ngồi trên đầu voi ra lệnh rằng: “Trong các quân của ta, ai muốn đánh thì phải vì ta mà giết hết lũ chó Ngô. Các ngươi hãy xem ta chỉ trong một trận sẽ giết được mấy vạn giặc cho coi. Các người hãy chờ xem. Không phải ta nói khoác đâu”.

Tiếp đó, vua Quang Trung đã đọc bài hiểu dụ tướng sĩ với những lời tuyên bố đanh thép biểu thị cao độ ý chí độc lập tự chủ và quyết tâm tiêu diệt quân xâm lược:

> Đánh cho để dài tóc,
> Đánh cho để đen răng,
> Đánh cho nó chích luân bất phản,
> Đánh cho nó phiến giáp bất hoàn,
> Đánh cho sử tri Nam quốc anh hùng chi hữu chủ.

Vua Quang Trung vừa dứt lời, tiếng dạ của chư quân tướng sĩ vang lên như sấm rung động cả núi rừng.

Khi đến trấn Sơn Nam, vua Quang Trung lại viết một bức thư khác gửi cho tướng giặc Tôn Sĩ Nghị, nhưng trong thư lần này, Quang Trung không tiếc lời mắng Tôn Sĩ Nghị là kẻ cướp nước và gọi Sĩ Nghị là Tôn điên. Sĩ Nghị đọc thư xong thì tức tối sai Đề đốc Hứa Thế Hanh đem quân Tứ Dực đi trước đóng giữ các nơi hiểm yếu để bảo vệ thành Thăng Long.

Bốn đạo quân của quân Thanh đóng ở bốn vị trí Tây Long, Đống Đa, Hải Dương, Sơn Tây. Như vậy Thăng Long là khu vực tập trung binh lực, trung tâm phòng thủ của địch. Đại bản doanh của Tôn Sỹ Nghị đóng ở cung Tây Long có đạo quân chủ lực bảo vệ. Ở Đống Đa có đạo quân của Sầm Nghi Đống trấn giữ. Hai đạo quân Thanh đóng ở Sơn Tây và Hải Dương có nhiệm vụ bảo vệ phía tây bắc và phía đông nam của Kinh thành Thăng Long. Đó là một hệ thống phòng thủ có chiều sâu, có trọng điểm nhưng phải bố trí trên tuyến dài nên dễ bị quân ta đánh chia cắt hoặc vu hồi. Mục đích của Tôn Sỹ Nghị là buộc quân Tây Sơn phải giao chiến từ xa Thăng Long.

Dựa trên sự bố trí của địch như vậy, Quang Trung quyết định chia đại quân Tây Sơn thành năm đạo quân cùng đánh vào khu vực Thăng Long:

* Đạo chủ lực do Quang Trung trực tiếp chỉ huy đánh thẳng vào hệ thống phòng ngự chủ yếu của địch ở phía Nam Thăng Long.
* Đạo quân thứ hai do Đô đốc Bảo chỉ huy tiến ra Đại Áng (Thường Tín) có nhiệm vụ yểm trợ và phối hợp với đạo quân chủ lực.
* Đạo thứ ba do Đô đốc Long chỉ huy bất ngờ tiêu diệt đồn Đống Đa rồi thọc sâu vào cung Tây Long nơi địch không ngờ tới và hiểm yếu nhất.
* Đạo quân thứ tư do Đô đốc Tuyết chỉ huy vượt biển đánh vào Hải Dương.
* Đạo quân thứ năm do Đô đốc Lộc chỉ huy là mũi bao vây chiến lược chặn đường rút lui của quân Thanh từ Thăng Long về Quảng Tây và sẵn sàng đánh chặn quân tiếp viện từ Quảng Tây sang bằng đường biển.

Với năm đạo quân được bố trí như trên, Quang Trung hình thành một thế trận gồm nhiều tầng nhiều lớp, kết hợp chặt chẽ giữa tiến công chính diện với thọc sâu, bao vây vu hồi.

Từ thế trận đó, Quang Trung đã chọn những đồn quan trọng trong hệ thống phòng ngự của Tôn Sỹ Nghị như Hà Hồi, Ngọc Hồi và Đống Đa, tập trung lực lượng đánh vào các điểm đó. Khi cuộc chiến bắt đầu, theo kế hoạch tác chiến của Quang Trung đã hình thành rõ rệt thế trận bao vây rộng lớn toàn khu vực Thăng Long, cũng như các đường rút lui của địch đều có quân Tây Sơn phục kích, bủa vây. Một cánh do Đô đốc Long chỉ huy từ làng Nhân Mục tập kích đồn Khương Thượng và phía tây Thăng Long. Cánh Đô đốc Bảo tiến đánh các đồn phía nam Thăng Long. Trung quân do đích thân Quang Trung chỉ huy, phối hợp với Đô đốc Bảo đánh diệt các đồn phía nam Thăng Long. Cánh Đô đốc Tuyết và Đô đốc Lộc theo đường biển ra Bắc, chặn đường rút lui của địch ở phía bắc sông Nhị Hà và huyện Phượng Nhãn.

Vào đêm giao thừa đón chào năm mới - năm Kỷ Dậu (1789), tại cung Tây Long bên bờ sông Nhị, Tôn Sĩ Nghị cùng bọn tướng soái quân Thanh đang mở yến tiệc hát xướng để đón xuân và mừng “chiến thắng”. Trước đó, Lê Chiêu Thống cũng đã dâng lên “quan đại soái của thiên triều” lễ vật nhiều gấp đôi lễ thết sứ thần sang phong vương. Khắp các doanh trại, đồn lũy, quân địch đều chúi đầu vào chè chén hay cờ bạc say sưa. Chính vào lúc đó - giữa đêm 30 Tết - đạo quân chủ lực của Quang Trung vượt sông Gián, mở màn cuộc đại phá quân Thanh. Tiền quân Tây Sơn bất ngờ tiến công tiêu diệt đồn tiền tiêu của địch ở Gián Khẩu. Đồn này do một đội quân Lê Chiêu Thống đóng giữ. Quân địch hoảng sợ, tan vỡ và bỏ chạy ngay từ đầu. Quân Tây Sơn thừa thắng tiến lên, nhanh chóng tiêu diệt luôn các đồn quân Thanh ở bờ bắc sông Nguyệt Quyết và Nhật Tảo. Những toán quân Thanh do thám “từ đằng xa trông thấy bóng cũng chạy nốt". Quang Trung ra lệnh truy kích ráo riết. Quân Tây Sơn đuổi đến Phú Xuyên (Hà Nội) thì bắt gọn được toàn bộ tàn quân và bọn lính do thám của địch, không để tên nào trốn thoát.

Quân Tây Sơn đã tiến đến Phú Xuyên (cách Thăng Long trên 30 kilômét), phá tung gần hai phần ba tuyến phòng thủ của địch mà quân Thanh từ đồn Hà Hồi trơ ra vẫn không biết gì hết. Bằng lối đánh bất ngờ, tiêu diệt gọn, truy kích triệt để, Quang Trung đã phong tỏa tin tức, giấu kín được cuộc tiến công của mình để tiếp tục phát huy thời cơ, tận dụng yếu tố bất ngờ.

Nửa đêm ngày mồng 3 Tết Kỷ Dậu (tức ngày 28 tháng 1 năm 1789), quân Tây Sơn bí mật bao vây đồn Hà Hồi (Thường Tín). Đây là một đồn quan trọng của quân Thanh cách Thăng Long khoảng 20 kilômét.

Theo kế hoạch của Quang Trung, quân Tây Sơn sau khi vây chặt đồn trại của địch rồi bắc loa gọi hàng. Khắp bốn mặt đồn, “tiếng quân lính luân phiên nhau dạ ran để hưởng ứng, nghe như có hơn vài vạn người". Quang Trung chỉ sử dụng một bộ phận của đạo quân chủ lực, nhưng bằng hành động bí mật, bất ngờ, kết hợp bao vây uy hiếp dữ dội với biện pháp gọi hàng, làm cho quân địch “ai nấy rụng rời, sợ hãi, liền xin ra hàng". Chỉ trong chốc lát, quân Tây Sơn đã diệt gọn một đồn quan trọng của địch, thu được rất nhiều vũ khí, lương thực.

Quân Tây Sơn tạm đóng quân ở phía nam Hà Hồi, trên một khu đất cao ráo, rộng rãi gồm cánh đồng Cung và những cánh đồng xung quanh. Đây là vị trí tập kết của đạo quân chủ lực trước khi bước vào trận quyết chiến tiêu diệt đồn Ngọc Hồi.

Sau khi đồn Hà Hồi bị tiêu diệt, sáng ngày mồng 4 Tết (ngày 29 tháng 1 năm 1789), Tôn Sĩ Nghị nhận được tin cáo cấp của đồn Ngọc Hồi: “Quan quân ở đồn Hà Hồi đều bị quân Tây Sơn đánh úp bắt hết cả. Ở đấy cách đồn Ngọc Hồi không xa, sớm chiều thế nào cũng bị đánh tới". Tin sét đánh đó làm cho quân Thanh vô cùng hoảng hốt. Chúng nói với nhau: “Thật là tướng ở trên trời xuống, quân ở dưới đất chui lên”. Bản thân Tôn Sĩ Nghị tuy có phòng bị trước, nhưng cũng hết sức kinh ngạc trước lối đánh thần tốc của quân Tây Sơn. Khi được tin cấp báo, hắn “rút kiếm chém xuống đất nói rằng: Sao mà thần đến thế!".

Tôn Sĩ Nghị cố trấn tĩnh để tìm cách đối phó. Trước hết, hắn ra lệnh lập tức tăng viện cho đồn Ngọc Hồi. Lãnh binh Quảng Tây là Thang Hùng Nghiệp và viên hàng tướng Tây Sơn là Phan Khải Đức được lệnh đem một đội quân “cần vương" của Lê Chiêu Thống xuống tăng cường lực lượng cho đồn Ngọc Hồi. Tôn Sĩ Nghị còn đặc biệt phái 20 kỵ binh trong đội hầu cận của hắn theo Thang Hùng Nghiệp xuống Ngọc Hồi với nhiệm vụ “trong khoảng chốc lát, phải tiếp tục báo tin về ngay”.

Tối ngày mồng 3, sáng mồng 4 Tết, đạo quân chủ lực của Quang Trung đã tập kết đầy đủ tại cánh đồng Cung ở phía nam Hà Hồi. Cũng vào khoảng thời gian đó, theo kế hoạch hiệp đồng đã vạch ra ở Tam Điệp, đạo quân của đại đô đốc Bảo cũng tập kết tại Đại Áng (xã Thanh Hưng, Thường Tín) ở phía tây - nam Ngọc Hồi.

Đạo quân của đại đô đốc Bảo đi theo con đường núi ra Vân Đình (Ứng Hòa), rồi theo con đường ngày nay là quốc lộ 22 ra ngã tư Vác (Thanh Oai) và từ đó, đi theo con đường qua các làng Canh Hoạch, Tri Lễ, Úc Lý, Dư Dụ (đều thuộc Thanh Oai), rồi qua cầu Sấu trên sông Nhuệ đến Đại Áng. Con đường này không cách xa con đường thiên lý (con đường hành quân của đạo quân chủ lực) bao nhiêu. Trục vận động và địa điểm tập kết thể hiện rõ ý định của Quang Trung sử dụng đạo quân của đại đô đốc Bảo như một lực lượng tiếp ứng cho đạo quân chủ lực trên hướng tiến công chủ yếu. Quang Trung quyết định sử dụng đạo quân của đại đô đốc Bảo vào trận công phá và tiêu diệt đồn Ngọc Hồi. Sự phối hợp hai đạo quân - đạo quân chủ lực và đạo quân tiếp ứng - đã cho phép Quang Trung tạo nên một ưu thế binh lực tương đối so với quân địch. Tuy vậy, trước mặt quân Tây Sơn là một đồn lũy phòng thủ kiên cố có công sự bảo vệ, có binh lực tập trung, hỏa lực mạnh. Căn cứ vào sự bố trí lực lượng và diễn biến của trận đánh thì kế hoạch công phá đồn Ngọc Hồi như sau:

* Đại bộ phận đạo quân chủ lực do Quang Trung đích thân chỉ huy sẽ mở cuộc tiến công chính diện và mãnh liệt vào mặt nam đồn Ngọc Hồi. Toàn bộ lực lượng tượng binh, đại bộ phận bộ binh, kỵ binh và hỏa pháo được tập trung vào mũi tiến công quyết liệt này.
* Số quân địch từ Ngọc Hồi chạy về Thăng Long phải đi theo hoặc con đường thiên lý qua đồn Lưu Phái, Văn Điển, hoặc đường đê sông Nhị, hoặc “đường cái cao" theo bờ sông Tô Lịch qua Quỳnh Đô lên Văn Điển. Chúng có thể tháo chạy theo một trong ba con đường đó mà thuận lợi nhất là con đường thiên lý, cũng có thể tháo chạy tán loạn theo cả ba con đường. Quang Trung quyết định chọn đầm Mực - một cái đầm lớn, lầy lội ở làng Quỳnh Đô - làm trận địa tiêu diệt bọn quân địch tháo chạy.
* Đạo quân của đại đô đốc Bảo từ Đại Áng được lệnh bí mật tiến lên, sẵn sàng chi viện cho đạo quân chủ lực nếu việc công phá đồn Ngọc Hồi gặp khó khăn, nhưng nhiệm vụ chủ yếu là bày sẵn một thế trận bao vây, tiêu diệt toàn bộ tàn quân địch ở đầm Mực (làng Quỳnh Đô).

Quang Trung quyết định cuộc tiến công đồn Ngọc Hồi sẽ bắt đầu vào mờ sáng ngày mồng 5 tháng Giêng (ngày 30 tháng 1 năm 1789) cùng một lúc với cuộc tiến công của đạo quân đô đốc Long vào đồn Đống Đa.

Cả ngày mồng 4, Quang Trung tiếp tục công việc chuẩn bị chu đáo cho trận quyết chiến và tổ chức hiệp đồng chặt chẽ với đạo quân của đại đô đốc Bảo. Cũng trong ngày hôm đó, Quang Trung chỉ dùng những toán nhỏ đánh khiêu khích vùng ngoại vi Ngọc Hồi, gây tâm lý căng thẳng cho quân Thanh và tạo yếu tố bất ngờ cho cánh quân Đô đốc Long trên hướng thứ yếu đánh đồn Đống Đa.

Ngày mồng 5 Tết Kỷ Dậu (ngày 30 tháng 1 năm 1789), lúc trời còn chưa sáng, bất thình lình quân Tây Sơn tiến công mãnh liệt vào mặt nam đồn Ngọc Hồi.

Quân Tây Sơn tràn qua đồn Bình Vọng, một đồn tiền tiêu của địch, xông thẳng đến đồn Ngọc Hồi.

Vua Quang Trung cưỡi voi chỉ huy chủ lực quân tiến vào đồn Ngọc Hồi. Để biểu lộ sự quyết tâm đánh tan kẻ thù trước toàn quân, Quang Trung đã chít khăn vàng lên đầu. Quân sĩ cũng chít khăn đỏ lên đầu để hưởng ứng.

Cuộc tiến công bắt đầu. Quang Trung tung đội tượng binh gồm hơn 100 voi chiến tiến lên trước. Đây là một binh chủng xung phong, đột phá rất lợi hại. Một con voi chiến lúc đó có thể chở được 13 - 14 người kể cả quản tượng. Ngoài cung nỏ, giáo, lao, tượng binh Tây Sơn còn được trang bị thêm nhiều thứ hỏa khí như súng tay, hỏa hổ và đặc biệt đặt cả đại bác trên mình voi. Trước khi sang xâm lược nước ta, Tôn Sĩ Nghị đã nghe nói về binh chủng này và đã nghiên cứu cách đề phòng, chống đỡ. Phía ngoài đồn Ngọc Hồi, quân địch bố trí một bãi chướng ngại dày đặc, trong đó có chông sắt và địa lôi, nhằm ngăn cản tượng binh của ta từ xa, không cho tiến sát vào chiến lũy.

Nhưng trước cả một đội tượng binh lớn mạnh với hơn 100 voi chiến đang hùng hổ xông đến, trông từ xa như “quả núi di động", quân Thanh vẫn không khỏi hoảng sợ. Đề đốc Hứa Thế Hanh phải vội vàng trấn an tinh thần quân lính và lập tức ra lệnh cho đội kỵ binh thiện chiến - binh chủng tinh nhuệ nhất của quân Thanh - lao ra khỏi cửa lũy nghênh chiến. Nhưng vừa trông thấy đoàn voi chiến của quân Tây Sơn, ngựa quân Thanh đã “sợ hãi, hí lên, tế chạy, lồng lộn quay về, chà đạp lẫn nhau”. Chưa đánh, đội kỵ binh thiện chiến của địch đã rối loạn cả đội hình.

Quân Tây Sơn thừa thắng thúc voi đuổi theo. Quân địch càng hoảng sợ, tất cả rút lui vào trong lũy cố thủ. Chúng dựa vào hệ thống chiến lũy, từ trên cao bắn đại bác và cung nỏ ra rất dữ dội để cản đường tiến của đoàn quân voi Tây Sơn.

Nhưng, trước hỏa lực của địch, “súng và tên bắn ra như mưa", thế trận và đội ngũ quân Tây Sơn vẫn vững vàng.

Theo lệnh của Quang Trung, đội voi chiến lập tức chia ra làm hai cánh đánh vòng về hai phía tả và hữu để mở đường cho đội xung kích lao lên. Đây là một đội quân cảm tử gồm 600 người, chia làm 20 toán. Mỗi toán gồm 10 chiến sĩ giắt dao ngắn bên hông, khiêng một tấm mộc lớn bằng gỗ phía ngoài quấn rơm ướt và 20 chiến sĩ cầm vũ khí tiến theo sau. Hai mươi toán quân cảm tử dàn ngang thành thế trận chữ “nhất”, phía trước là 20 tấm mộc kết liền với nhau như một bức tường thành di động, xông thẳng vào trận địa của địch. Những tấm mộc bọc rơm ướt có tác dụng chống đỡ đại bác và cung tên của địch từ trong chiến lũy bắn ra, che chở cho đội quân xung kích tiến lên.

Quân chủ lực Tây Sơn dưới sự đốc chiến trực tiếp của Quang Trung, lập tức xung phong vào đồn lũy của địch. Bộ binh, kỵ binh, tượng binh của ta ào ạt xông vào cửa lũy đã mở. Thế xung trận của quân Tây Sơn mạnh như triều dâng bão cuốn.

Từ hai bên sườn đồn Ngọc Hồi, đội tượng binh cũng đồng thời đánh ập vào. Quân ta lùa voi, xông pha tên đạn, nhổ rào lũy tiến vào. Từ trên mình voi, quân ta dùng đại bác và hỏa hổ đốt phá đồn lũy, doanh trại địch và thiêu cháy quân địch.

Quân Thanh vốn đã khiếp sợ những con voi chiến hùng hổ của Tây Sơn, nay lại càng khiếp sợ hỏa lực lợi hại của binh chủng này. Đó là hỏa hổ, một thứ vũ khí nổi tiếng của quân Tây Sơn.

Đồn Ngọc Hồi, cứ điểm phòng ngự kiên cố nhất của quân Thanh bị phá vỡ. Một bộ phận quan trọng quân địch bị giết chết tại trận. Trong bộ chỉ huy của địch, đề đốc Hứa Thế Hanh, phó tướng của Tôn Sĩ Nghị và là tướng chỉ huy toàn bộ mặt trận phía nam Thăng Long và tổng binh Thượng Duy Thăng là tướng chỉ huy quân tả dực của Tôn Sĩ Nghị bị bỏ mạng tại đây.

Tuy nhiên, số quân Thanh thoát chết ở đồn Ngọc Hồi vẫn còn khá nhiều, khoảng vài vạn tên. Bọn tàn quân này theo tổng binh Trương Triều Long tìm đường tháo chạy về Thăng Long.

Đạo quân của đại đô đốc Bảo đã chăng sẵn một mẻ lưới bủa vây và tiêu diệt toàn bộ tàn quân địch ở đầm Mực.

Quân địch bị dồn vào bước đường cùng. Chúng còn khoảng vài vạn quân nhưng chỉ là một khối người rã rời, kiệt sức về thể xác và kinh hoảng đến tuyệt vọng về tinh thần. Từ ba mặt, quân Tây Sơn khép chặt vòng vây, dồn ép chúng vào khu đầm Mực lầy lội, um tùm mà tiêu diệt. Quân Thanh “hết hồn hết vía, vội trốn xuống đầm Mực làng Quỳnh Đô" và “quân Tây Sơn lùa voi cho giày đạp, chết đến hàng vạn người". Toàn bộ bọn tàn quân địch ở đồn Ngọc Hồi đều bị tiêu diệt, trong đó có cả tổng binh Trương Triều Long. Một số tên lẩn trốn vào các làng xóm chung quanh cũng bị nhân dân giết chết hoặc bắt nộp cho quân Tây Sơn.

Chỉ trong sáng ngày mồng 5 tháng Giêng Tết Kỷ Dậu, quân Tây Sơn đã phá tan đồn Ngọc Hồi tiêu diệt toàn bộ quân địch khoảng 3 vạn tên ở Ngọc Hồi và đầm Mực. Đây là một cứ điểm then chốt nhất của quân địch đã bị tiêu diệt, đập nát hệ thống phòng thủ của chúng ở phía nam Thăng Long, mở toang cửa ngõ tiến vào giải phóng kinh thành, uy hiếp đại bản doanh của Tôn Sĩ Nghị ở cung Tây Long.

Đạo quân chủ lực của Quang Trung và đạo quân của Đô đốc Bảo đã hoàn thành xuất sắc nhiệm vụ nặng nề trên hướng tiến công chủ yếu này. Đây là trận quyết chiến chiến lược thể hiện quyết tâm đánh tiêu diệt và nghệ thuật tổ chức lực lượng, nhất là dùng voi chiến công đồn của Quang Trung - Nguyễn Huệ. Trận Ngọc Hồi xứng đáng giữ vị trí quyết định trong toàn bộ cuộc tổng tiến công chống quân xâm lược Mãn Thanh cuối thế kỷ XVIII ở nước ta.

Cũng vào rạng sáng ngày mồng 5 tháng Giêng (30-1-1789), khi đạo quân chủ lực tiến đánh đồn Ngọc Hồi thì trên hướng tiến công phối hợp, đạo quân của đô đốc Long (có tài liệu nói là Đặng Tiến Đông) cũng đồng thời mở cuộc tiến công hết sức bất ngờ vào đồn Đống Đa (về danh tướng chỉ huy trực tiếp trận Đống Đa, hiện nay có những chủ kiến khác nhau: Hoàng Lê nhất thống chí ghi là Đô đốc Long, Đại Nam chính biên liệt truyện lại ghi là Đô đốc Mưu).

Đồn Đống Đa tuy không kiên cố như đồn Ngọc Hồi, nhưng cũng giữ một vị trí quan trọng trong hệ thống phòng thủ Thăng Long của Tôn Sĩ Nghị.

Quân Thanh lập đồn trại ở Đống Đa là để khống chế con đường cái từ Tam Điệp ra phía tây - nam Thăng Long, đề phòng cuộc tiến công của quân Tây Sơn theo hướng này và bảo vệ trực tiếp cửa ô Thịnh Quang, một cửa ngõ phía tây - nam thành Thăng Long.

Đóng giữ đồn Đống Đa là đạo quân Điền Châu, Triều Châu do Sầm Nghi Đống chỉ huy. Đặc điểm của đạo quân này là số lượng khá đông - ước đoán khoảng vài vạn quân - nhưng chất lượng không đều và khá ô hợp. Đồn Đống Đa là hướng tiến công mà Tôn Sỹ Nghị chủ quan cho là khó có thể xảy ra vì con đường “thượng đạo” hiểm trở khó cơ động và triển khai lực lượng lớn các binh chủng. Để đánh đồn Đống Đa, đạo quân Tây Sơn của đô đốc Long phải hành quân bí mật, đi theo một con đường núi đã bế tắc, phải mở lấy đường mà đi và khắc phục nhiều trở ngại của núi rừng. Nhiệm vụ đó đòi hỏi tướng chỉ huy không những phải giàu nghị lực, có tài tổ chức, mà còn phải am hiểu cặn kẽ địa hình và đường đi lối lại trong vùng. Đạo quân của đô đốc Long không nhiều lắm - chỉ khoảng một vạn quân - nhưng theo kế hoạch phối hợp của Quang Trung, phải bất ngờ đánh úp, tiêu diệt đồn Đống Đa thật nhanh, gọn. Muốn hoàn thành thắng lợi nhiệm vụ đó, quân đội Tây Sơn cần được sự tham gia, hỗ trợ trực tiếp của nhân dân xung quanh đồn địch.

Đạo quân của đô đốc Long gồm kỵ binh và tượng binh, tuy không nhiều nhưng có sức cơ động nhanh và đột phá mạnh. Quân đội cũng được trang bị nhiều hỏa hổ và đại bác đặt trên mình voi chiến. Cuộc tiến công bắt đầu vào khoảng cuối canh tư (khoảng 3 giờ sáng).

Bằng khí thế áp đảo quân thù, quân Tây Sơn với đội hình đã bày sẵn, xông thẳng vào đồn trại của địch. Quân ta đốt phá các doanh trại phía ngoài rồi nhanh chóng đánh thọc vào sở chỉ huy của địch. Sầm Nghi Đống cố đốc thúc quân lính chống cự nhưng không sao đương nổi sức tiến công mãnh liệt của quân Tây Sơn. Chỉ trong chốc lát, số quân Thanh bị chết và bị thương đã lên đến 5.000 người. Sầm Nghi Đống phải bỏ các doanh trại bên ngoài, rút về bảo vệ sở chỉ huy trên Loa Sơn để chờ quân cứu viện.

Cùng lúc đó, xung quanh đồn trại của địch đột nhiên xuất hiện một hàng rào lửa dày đặc. Đó là “trận rồng lửa” (hỏa long trận) của nhân dân địa phương góp sức cùng với quân đội Tây Sơn diệt giặc. Nhân dân 9 xã ở ngoại thành Thăng Long đã hăng hái dùng rơm rạ, cỏ khô bện thành những con cúi, tẩm dầu, nhựa trám và nhựa thông, nối lại thành những “con rồng”. Khi nghĩa quân nổ súng, nhân dân đốt cháy những con rồng rơm tạo thành bức tường lửa vây kín đồn trại giặc.

Quân địch đang choáng váng vì đòn tiến công bất ngờ của quân Tây Sơn lại càng khiếp đảm trước lưới lửa bao vây trùng điệp của nhân dân. Trong đêm tối, chúng chỉ còn trông thấy bốn bề lửa cháy rực trời, tiếng reo hò dậy đất. Đồn trại của địch tan vỡ nhanh chóng. Quân địch đang lúc đêm tối, tự xéo lên nhau mà chạy. Các mũi tiến công của quân Tây Sơn lao vào chém giết như vào chỗ không người.

Từ trên sở chỉ huy, Sầm Nghi Đống thấy rõ đã lâm vào cảnh thế cùng lực kiệt: chống đỡ không nổi, quân cứu viện không có, phá vây không được. Hắn tuyệt vọng, thắt cổ tự vẫn ngay tại sở chỉ huy. Đội thân binh trung thành của hắn cũng tự sát theo chủ tướng đến vài trăm tên.

Đồn Đống Đa bị tiêu diệt chỉ sau mấy giờ chiến đấu. Đại bộ phận quân địch bị tiêu diệt tại trận. Một số tên chạy thoát ra ngoài cũng bị quân ta đuổi theo chém và bắt được đến quá nửa. Quân Tây Sơn thừa thắng tiêu diệt luôn các đồn Yên Quyết, Nam Đồng rồi nhanh chóng tràn vào cửa ô tây - nam thành Thăng Long.

Sau trận đánh, hàng vạn xác giặc nằm ngổn ngang khắp chiến trường từ trại Khương Thượng, Thịnh Quang đến trại Nam Đồng. Khi thu dọn chiến trường, quân dân ta đã nhặt xác giặc, xếp thành từng đống rồi đắp đất lên thành những gò đống lớn. Đó là lối chôn cất cổ truyền của nhiều nước phương Đông vừa có ý nghĩa biểu dương chiến công, để lại một di tích chiến thắng cho muôn đời con cháu, vừa nhằm cảnh cáo kẻ thù. Những đống xác giặc đó gọi là Kình nghê kinh quán, có nghĩa là gò đống lớn vùi xác quân giặc hung dữ ví như loài cá kình, cá nghê ngoài biển cả (là loại cá to hay đuổi bắt loại cá nhỏ mà ăn). Mười hai gò đống như vậy đã xuất hiện trên trận địa như những chiến tích bất diệt của dân tộc. Trong bài Loa Sơn điếu cổ, nhà thơ đương thời Ngô Ngọc Du ca ngợi võ công oanh liệt của quân và dân ta gắn liền với những chiến tích đó:

> Thành nam thập nhị Kình nghê quán,
> Chiếu diệu anh hùng đại võ công.
> *(Phía nam thành, mười hai gò xác giặc,*
> *Rạng rỡ công lớn của anh hùng).*

Tuy vậy, mười hai gò lớn vẫn chưa vùi hết xác quân xâm lược, rải rác trên các cánh đồng vẫn còn có nhiều xác giặc chôn ở đó. Rất nhiều năm sau này (năm 1851), người dân khi đào đất để đắp đường, lập chợ đã tìm thấy nhiều xương cốt bèn thu nhặt đem chôn thành một hố, đắp thành gò thứ 13.

Trải qua năm tháng, trên các gò đống đó, cây cối mọc um tùm, nhiều nhất là cây đa. Với tên đất sẵn có, nhân dân thường gọi những gò đống đó là “gò Đống Đa" và cùng có những gò đống đó là “xứ Đống Đa".

Như trên đã nói, theo kế hoạch của Quang Trung, trong khi đạo quân chủ lực công phá đồn Ngọc Hồi, thì đạo quân của Đô đốc Long bất ngờ tập kích tiêu diệt đồn Đống Đa, rồi nhanh chóng thọc sâu vào thành Thăng Long, uy hiếp đại bản doanh của Tôn Sĩ Nghị. Do đó, mờ sáng ngày mồng 5, lúc đồn Đống Đa sắp bị tiêu diệt, đô đốc Long đã hết sức khẩn trương, mau lẹ, đem đội kỵ binh tiên phong của mình đánh thọc vào Thăng Long. Như một mũi dao nhọn, đội kỵ binh Tây Sơn lao thẳng về phía cung Tây Long. Đấy là hành động bất ngờ, táo bạo mà Tôn Sĩ Nghị không thể nào lường trước được. Những tin tức khủng khiếp của mặt trận phía nam và phía tây - nam đồng thời đến với Tôn Sĩ Nghị như những đòn trời giáng. Cả một đạo quân chủ lực còn nguyên vẹn trong tay, nhưng viên chủ soái của quân Thanh hoảng hốt, không còn biết xoay xở, đối phó thế nào.

Như trong bản tâu gửi về triều đình nhà Thanh, Tôn Sĩ Nghị cảm thấy “quân giặc nhiều quá" và quân Thanh đã bị “vây kín bốn mặt". Hắn “sợ mất mật” và “ngựa không kịp đóng yên, người không kịp mặc giáp, dẫn bọn lính kỵ mã của mình chuồn trước qua cầu phao, rồi nhằm hướng Bắc mà chạy”. Viên thiên tổng Tiết Trung phải dắt cương ngựa cho Tôn Sĩ Nghị chạy trốn và phó tướng Khánh Thành đi theo hộ tống.

Chủ tướng bỏ chạy, “quân sĩ các doanh nghe tin đều hoảng hồn, tan tác bỏ chạy, tranh nhau qua cầu sang sông, xô đẩy nhau rơi xuống mà chết rất nhiều". Tình hình hỗn loạn đến mức độ, tổng binh Lý Hóa Long chạy đến giữa cầu phao cũng bị quân lính đẩy ngã nhào xuống sông.

Qua khỏi cầu phao sang bờ bắc sông Nhị, Tôn Sĩ Nghị lại sợ quân Tây Sơn lợi dụng cầu phao đuổi theo. Chỉ lo bảo toàn tính mạng của bản thân, viên bại tướng đó không ngần ngại ra lệnh cắt đứt cầu phao để chẹn phía sau.

Hành động ích kỷ và tàn nhẫn của Tôn Sĩ Nghị đã làm cho hàng vạn quân Thanh bị dòng nước sông Nhị cuốn trôi. “Cầu gãy, người bị chết vô kể" và “nước sông Nhị vì thế mà tắc nghẽn không chảy được”. Số quân Thanh không kịp qua cầu phao cũng tìm mọi cách liều lĩnh vượt sông. Có bọn cướp được một số thuyền buôn và thuyền đánh cá đang đỗ bên bờ sông nhưng rồi chúng tranh nhau xuống thuyền đông quá nên hầu hết cũng bị đắm. Có bọn thì buộc giáo, mác, khiên, mộc lại thành từng bó để làm bè vượt sông. Vừa lúc đó, quân Tây Sơn ập tới. Số phận quân Thanh chưa kịp qua sông đã được định đoạt: nếu không vùi xác theo dòng sông Nhị thì cũng bị chém giết hoặc bắt làm tù binh. Một số tàn quân trốn tránh vào các xóm làng thì sau đó, trong vòng 10 ngày, đều phải ra đầu thú.

Số phận đám quân Thanh đóng ở bờ bắc sông Nhị cùng với số tàn quân vượt qua cầu phao chạy trốn theo Tôn Sĩ Nghị cũng không may mắn hơn bao nhiêu. Bọn chúng bị quân Tây Sơn truy kích phía sau và đến Phượng Nhãn lại bất ngờ bị đạo quân của đô đốc Lộc chặn đánh. Tôn Sĩ Nghị và bọn tàn quân không dám chạy theo đường cái. Chúng phải luồn rừng, lội suối, leo núi, đường đi quanh co rẽ ngang rẽ dọc... luôn luôn lạc lối, không tìm được nẻo đi và đêm ngày đi gấp, không dám nghỉ ngơi. Tôn Sĩ Nghị phải vất bỏ tất cả mọi thứ mang theo kể cả sắc thư, kỳ bài, quân ấn chủ soái do vua Thanh ban cho, để lo chạy thoát thân.

Đạo quân Thanh đóng ở Hải Dương cũng bị đánh tan. Riêng đạo quân Vân Nam do đề đốc Ô Đại Kinh chỉ huy, ngày 21 tháng Chạp năm Mậu Thân (ngày 16 tháng 1 năm 1789) đến Tuyên Quang và những ngày cuối năm đó mới đến Sơn Tây. Vừa đóng quân được mấy ngày thì được tin Tôn Sĩ Nghị bại trận, cả đạo quân này hốt hoảng tháo chạy về nước. Không bị tiến công nhưng đạo quân Ô Đại Kinh cũng bị tan vỡ và rút chạy trong cảnh hỗn loạn. Qua vùng Tuyên Quang, chúng lại bị một đội dân binh dân tộc Tày do Ma Doãn Dào chỉ huy chặn đánh. Chúng càng hoảng sợ, chen lấn xô đẩy nhau giành đường về nước và một bộ phận khá đông tán loạn vào núi rừng. Một toán quân do Phùng Chấn Tiên cầm đầu bị lạc đường chạy sang Quảng Tây. Theo lời tâu của tổng đốc Vân Quý là Phú Cương thì trong đạo quân Ô Đại Kinh có một số không thấy trở về, trong đó có một viên vũ cử (cử nhân võ), một viên ngoại ủy (võ quan cấp dưới) và mấy chục tên lính.

Thắng lợi của cuộc kháng chiến thật là rực rỡ, chói lọi. Toàn bộ quân xâm lược Mãn Thanh khoảng 29 vạn quân cùng với vài vạn quân của bù nhìn Lê Chiêu Thống đã bị đánh tan tành, bị tiêu diệt đại bộ phận và bị quét sạch ra khỏi bờ cõi. Sáng mồng 5, đang ở trong cung điện, được tin quân Thanh bại trận, Tôn Sĩ Nghị rút chạy, Lê Chiêu Thống vội vàng bám gót chạy theo. Nhưng ra đến bờ sông thì cầu phao đã bị cắt, hắn hoảng sợ theo bờ sông chạy lên Nghi Tàm, cướp được chiếc thuyền đánh cá chèo qua sông. Hắn tìm đường chạy lên ải Nam Quan mới gặp Tôn Sĩ Nghị để bắt đầu cuộc sống lưu vong nhục nhã nơi đất khách quê người.

Trưa ngày mồng 5 Tết Kỷ Dậu (30-1-1789), vua Quang Trung ngồi trên lưng voi, chiến bào màu đỏ của nhà vua xạm đen khói súng, đi đầu đại quân tiến vào Thăng Long giữa cảnh mừng vui khôn xiết của nhân dân. Không khí hân hoan chào đón đoàn quân giải phóng được nhà thơ đương thời Ngô Ngọc Du tả lại như sau:

> Mây tạnh mù tan trời lại sáng
> Đầy thành già trẻ mặt như hoa
> Chung vai sát cánh cùng nhau nói
> Cố đô vẫn thuộc núi sông ta.

Cuộc kháng chiến chống quân Thanh xâm lược đã giành được thắng lợi hoàn toàn. Toàn bộ 29 vạn quân xâm lược Mãn Thanh cùng với vài vạn quân của bọn bù nhìn Lê Chiêu Thống đã bị đánh tan tành, bị tiêu diệt đại bộ phận và bị quét sạch ra khỏi bờ cõi. Trong bốn đạo quân Thanh thì ba đạo, trong đó có đạo quân chủ lực của Tôn Sĩ Nghị bị tiêu diệt gần hết và một đạo quân không đánh mà cũng tan tác. Hàng loạt tướng lĩnh cao cấp của địch bị bỏ mạng.

Trong lịch sử hàng nghìn năm dựng nước và giữ nước, dân tộc ta đã tiến hành nhiều cuộc kháng chiến, đánh bại mọi kẻ thù xâm lược, nhưng đến cuối thế kỷ XVIII, chưa có lần nào khi phải đương đầu với hàng chục vạn quân xâm lược mà đánh thắng oanh liệt, vang dội trong một thời gian ngắn như thế. Điều đó càng có ý nghĩa lớn lao khi cuộc kháng chiến chống quân Thanh diễn ra vào lúc chế độ phong kiến suy tàn, kẻ thù có sẵn chỗ dựa bên trong là bọn phong kiến phản động, và quân xâm lược đã chiếm kinh thành cùng nhiều vùng rộng lớn xung quanh.

Chiến thắng Ngọc Hồi - Đống Đa giữ vai trò là những trận quyết chiến chiến lược có ý nghĩa quyết định, kết thúc thắng lợi cuộc kháng chiến chống quân Thanh xâm lược. Nhìn riêng về từng hướng tiến công thì trận Ngọc Hồi là trận quyết chiến trên hướng tiến công chủ yếu và trận Đống Đa là trận quyết chiến trên hướng tiến công thứ yếu.

Trận Ngọc Hồi là trận tiến công chính diện nhằm tiêu diệt cứ điểm kiên cố nhất của địch, đập nát vị trí then chốt trong hệ thống phòng thủ cứng rắn phía trước, đồng thời thu hút chủ lực địch. Còn trận Đống Đa là trận vu hồi, thọc sâu hết sức bất ngờ, đánh thẳng vào một cửa ngõ thành Thăng Long và cũng là chỗ sơ hở, chỗ yếu của địch để trực tiếp uy hiếp bộ chỉ huy đầu não của địch. Sự phối hợp chặt chẽ của hai trận này làm cho quân Thanh bị chia cắt, cô lập không thể ứng cứu được cho nhau và đặc biệt làm cho Tôn Sĩ Nghị cùng với đạo quân chủ lực, cơ động to lớn của địch lâm vào tình thế bất ngờ, bị động, không kịp trở tay đối phó và cuối cùng bị tê liệt, tan rã và tháo chạy tán loạn.

Thật hiếm có một chiến công chống ngoại xâm, trong hoàn cảnh phức tạp của đất nước, trong so sánh lực lượng rất chênh lệch về quân số giữa ta và địch, mà lại giành được thắng lợi oanh liệt, thần tốc như cuộc đại phá quân Thanh.

Với cách đánh táo bạo, mãnh liệt, đánh nhanh, đánh hiểm, đánh thẳng vào sào huyệt trung tâm, chọc những mũi dao nhọn vào tim địch, diệt ngay được bộ chỉ huy cùng tập đoàn chiến lược chủ yếu của địch. Nguyễn Huệ thường chỉ bằng một trận quyết chiến đã giải quyết xong một cuộc chiến tranh. Đây là tài năng hiếm có của ông và cũng là điều ít thấy trong lịch sử chiến tranh của dân tộc ta. Những trận quyết chiến diệt quân Xiêm - Nguyễn, đánh tan quân Trịnh và đại phá quân Thanh là những trận nổi tiếng trong lịch sử, đã đưa Nguyễn Huệ trở thành người anh hùng, nhà quân sự kiệt xuất của dân tộc ta.

Chiến thắng Ngọc Hồi - Đống Đa đã biểu hiện một cách rất rõ tài năng quân sự kiệt xuất của Hoàng đế Quang Trung - Nguyễn Huệ, ý chí quyết chiến quyết thắng và bản lĩnh chiến đấu kiên cường của quân đội Tây Sơn.

Chiến thắng này là chiến thắng của lòng quyết tâm và ý chí “Đánh cho sử tri Nam quốc anh hùng chi hữu chủ" được nhân dân hết lòng ủng hộ và giúp đỡ mạnh mẽ. Trên đường hành quân chiến đấu của quân Tây Sơn, nhân dân đã hăng hái cho con em mình gia nhập nghĩa quân, tiếp tế lương thực, thực phẩm, giúp đỡ các phương tiện vượt sông... Nhân dân các làng xã quanh kinh thành Thăng Long đã giúp quân Tây Sơn bí mật giấu quân ém sát đồn giặc, góp ván gỗ làm mộc công phá đồn Ngọc Hồi, đã phối hợp làm “trận rồng lửa” trong trận diệt đồn Đống Đa...

Ngọc Hồi - Đống Đa là một thiên anh hùng ca, một chiến công lừng lẫy, một sự nghiệp vĩ đại của Quang Trung - Nguyễn Huệ và của dân tộc ta, là một cống hiến lớn lao cho nền khoa học và nghệ thuật quân sự Việt Nam.', 'TEXT', '2026-06-05 05:34:48.895292', '2026-06-05 05:34:48.895274', null, 'DRAFT'), ('f686c1f3-9431-4655-b59b-7d3270366290', '687b57fe-865c-496a-83b3-f83690885dd1', 'de09e246-703a-4f00-bd33-9a1fb4dbd5e5', 'CONTEXT', 'Chi tiết trận Bạch Đằng 1288', null, 'Trận Bạch Đằng ngày 9-4-1288 là trận phục kích đường sông của quân đội nhà Trần (Đại Việt), do Trần Quốc Tuấn chỉ huy diệt quân Nguyên - Mông rút chạy, kết thúc cuộc kháng chiến chống Nguyên - Mông lần thứ ba (1287-1288).

Trong vòng 30 năm (1258 - 1288), đế quốc Mông - Nguyên đã liên tiếp ba lần tiến công xâm lược Đại Việt.

Lần thứ nhất, năm 1258, hơn 3 vạn kỵ binh Mông Cổ dưới quyền chỉ huy của tướng Ngột Lương Hợp Thai (Uriangkhadai) tiến vào Đại Việt. Trước thế mạnh của giặc, quân ta buộc phải rút lui khỏi Kinh thành Thăng Long về vùng sông Thiên Mạc (Hưng Yên). Quân xâm lược chiếm được một kinh thành trống rỗng, không có lương ăn. Ngày 29 tháng 1 năm 1258, quân đội nhà Trần mở cuộc phản công. Bằng trận tập kích chiến lược Đông Bộ Đầu, quân Mông Cổ bị thất bại nặng nề, đám tàn quân chạy một mạch về Vân Nam (Trung Quốc). Thắng lợi của cuộc kháng chiến chống quân Mông Cổ lần thứ nhất vào năm Nguyên Phong thứ 7 (1258) đã giữ vững được nền độc lập và chủ quyền của quốc gia Đại Việt. Đất nước hòa bình trong hơn một phần tư thế kỷ (1258 - 1284). Nhưng nguy cơ ngoại xâm mới chỉ được đẩy lùi chứ chưa phải đã hết. Đế quốc Mông Cổ đang trên đà phát triển và chưa chịu từ bỏ ý đồ xâm lược các nước phía Đông và Đông Nam Á. Vì vậy, đây là thời kỳ đấu tranh ngoại giao vừa quyết liệt vừa khôn khéo của vua tôi nhà Trần với các đoàn sứ thần Mông Cổ. Năm 1258, vừa mới chạy thoát thân về đến Vân Nam, Ngột Lương Hợp Thai đã sai sứ sang dụ vua Trần sang chầu vua Mông Cổ. Hành động ngang ngược đó liền bị nhà Trần đán lại đích đáng. Vua Trần Thái Tông sai trói sứ giả của giặc lại rồi đuổi về.

Năm 1260, sau khi chúa Mông Cổ là Mông Ke chết, Hốt Tất Liệt tự xưng làm Đại Hãn. Cuộc tranh giành quyền lực trong nội bộ đế quốc Mông Cổ khiến chúng phải tạm ngừng cuộc tấn công Nam Tổng và nới lỏng hơn trong quan hệ với Đại Việt. Khi lên ngôi Hãn năm 1271, Hốt Tất Liệt đổi quốc hiệu là Nguyên, thống trị cả vùng đất Trung Quốc, tăng cường dùng sức mạnh ngoại giao hòng khuất phục triều Trần. Trong vòng hai mươi năm liền, nhà Nguyên đã liên tiếp phái nhiều đoàn sứ giả sang Đại Việt dụ dỗ, yêu sách, đe dọa ngày cảng trắng trợn, hống hách, ngang ngược đối với vương triều Trần...

Lùn thứ hai, năm 1285, vua Nguyên là Hốt Tất Liệt (Khubilai) huy động 50 vạn quân do con trai là Thoát Hoan chỉ huy, tiến công Đại Việt. Quân dân ta dưới sự lãnh đạo của hai vua Trần (Thượng hoàng Trần Thánh Tông và vua Trần Nhân Tông) mà trực tiếp là Quốc công Tiết chế Trần Quốc Tuấn đã anh dũng chiến đấu ngăn chặn các mũi tiến công của quân giặc. Trước đó, triều đình nhà Trần đã mở hội nghị Bình Than và Diên Hồng nêu cao quyết tâm đánh giặc cứu nước. Hưng Đạo Vương Trần Quốc Tuấn đã ra Hịch tướng sĩ. Bai hịch đã có tác dụng khích lệ, cổ vũ lòng yêu nước và thúc giục các trớng sĩ hăng hái luyện tập binh mã để giết giặc lập công. Quân và dến Đại Việt dưới quyền tổng chỉ huy của Trần Quốc Tuấn và các tướng Trần Quang Khải, Trần Nhật Duật đã chặn giặc từng bước ở các cửa ải biên giới, ở Sông Hồng, ở Nghệ An và Thanh Hóa. Nhưng cũng như lần trước, triều đình và quân đội nhà Trần phải tạm rút lui khỏi kinh thành về Thiên Trường, Trường Yên (thuộc Nam Định và Ninh Bình) rồi vào Thanh Hóa. Cả nước thực hiện cuộc chiến tranh toàn dân, thực hiện vườn không nhà trống, triệt nguồn lương thảo của giặc và liên tục tiến hành đánh nhỏ, phục kích và tập kích, đánh tiêu hao quân xâm lược. Tháng 5 năm 1285, khi quân giặc đã mệt mỏi sức lực suy yếu, sa vào thế bị động, quân ta mở cuộc phản công chiến lược bằng một loạt các trận đánh lớn như: A Lỗ (Thái Bình), Tây Kết, Hàm Tử (Hưng Yên), Chương Dương (Hà Nội), tiêu diệt nhiều sinh lực địch, rồi thừa thắng bao vây và tiến công mạnh quân địch ở Thăng Long. Bị thất bại liên tiếp, Thoát Hoan và các tưởng giặc tìm đường tháo chạy về nước. Nhưng chúng bị chặn đánh ở Sông Cầu và bị thua to ở Vạn Kiếp (Hải Dương). Đạo quân Toa Đô cũng bị đánh tan ở Tây Kết. Toa Đô bị chém đầu tại trận. Cuối tháng 6 năm 1285, toàn bộ quân xâm lược bị quét sạch khỏi bờ cõi nước ta.

Lần thứ ba, vào cuối năm 1287, đầu năm 1288, vua Nguyên là Hốt Tất Liệt dốc toàn bộ lực lượng quyết tâm đánh chiếm Đại Việt. Hai lần xâm lược, hai lần thất bại thảm hại. Hốt Tất Liệt vô cùng tức tối, tổ chức cho được cuộc xâm lược lần thứ ba. Hắn bãi bỏ kế hoạch đánh Nhật Bản đã được chuẩn bị từ trước và dồn sức lực cho cuộc viễn chinh này. Khác với hai lần trước, lần này ngoài bộ binh và kỵ binh, nhà Nguyên còn huy động một lực lượng thủy binh hùng mạnh và mang theo lương thực đầy đủ. Tổng số quân Nguyên khoảng 50 vạn do Trấn Nam vương Thoát Hoan thống lĩnh, chia thành ba đạo tiến vào Đại Việt:
- Đạo quân do Thoát Hoan chỉ huy chiếm phần lớn quân số, tiến từ Quảng Tây theo đường Lạng Sơn tiến vào.
- Đạo quân do Ái Lỗ (Aruc) chỉ huy từ Vân Nam theo Sông Hồng tiến xuống.
- Đạo quân thủy do Ô Mã Nhi và Phàn Tiếp chỉ huy với khoảng 600 chiến thuyền từ Khâm Châu (Quảng Đông, Trung Quốc) theo sông Bạch Đằng tiến vào rồi hội quân ở Vạn Kiếp (Chí Linh, Hải Dương).
Ngoài ra còn có đội thuyền vận tải do Trương Văn Hổ cầm đầu chở hơn 70 vạn hộc lương theo sau. Các tướng giặc chỉ huy cuộc viễn chinh lần thứ ba đều là những tên thiện chiến, hầu hết đều rất quen thuộc với chiến trường Đại Việt. Thoát Hoan giữ chức Tiết chế tổng chỉ huy là kẻ cầm đầu cuộc xâm lược lần trước.

Quân dân Đại Việt bước vào cuộc kháng chiến lần thứ ba hết sức chủ động vì lúc đó nước ta đã chuẩn bị đầy đủ các mặt kinh tế, chính trị, quốc phòng. Toàn quân, toàn dân Đại Việt đã sẵn sàng chiến đấu chống quân xâm lược. Từ khi được tin quân Nguyên chuẩn bị xâm lược thì việc huấn luyện, diễn tập của quân đội được đẩy mạnh và tăng cường. Vua Trần Nhân Tông đã lệnh cho các vương hầu, tôn thất mộ thêm binh lính, chấn chỉnh lực lượng. Chiến thuyền, khí giới được gấp rút chế tạo, tu sửa. Hưng Đạo Vương Trần Quốc Tuấn lại được cử làm Quốc công Tiết chế thống lĩnh quân đội kháng chiến. Các vương hầu đem quân đóng ở các nơi hiểm yếu, sẵn sàng chống giặc. Vua Trần hỏi Hưng Đạo Vương Trần Quốc Tuấn: “Thế giặc năm nay thế nào?”. Quốc Tuấn trả lời: “Nước ta thái bình lâu ngày, dân không biết việc binh, cho nên năm trước quân Nguyên xâm lấn, hoặc có người đầu hàng trốn tránh. Nhờ được uy linh của tổ tông và thần võ của bệ hạ đã quét sạch được rợ Hồ. Nay nếu nó lại sang thì quân ta đã quen việc đánh dẹp mà quân họ thì ngại về đi xa vả lại họ đã cạch về sự thất bại của Hằng và Quán, không có lòng chiến đấu nữa. Cứ ý thần xem thì tất đánh tan được (Đại Việt sử ký toàn thư, Tập II, Nxb. Khoa học Xã hội, H., 1971, tr.63 - 64. Hằng và Quán là tướng Nguyên bị quân ta bắn chết khi bảo vệ Thoát Hoan chạy về nước, trong cuộc kháng chiến chống Mông - Nguyên lần thứ hai).

Trong trận chiến lần này, Hưng Đạo Vương Trần Quốc Tuấn rất chú trọng đến vùng biển Đông Bắc. Đó là đường tiến của thủy quân và đoàn thuyền tải lương của quân Nguyên. Nhân Huệ Vương Trần Khánh Dư được phong làm phó tướng, phụ trách mọi việc ở vùng biển này, đóng quân ở Vân Đồn; Phán thủ Thượng bộ Nhân Đức hầu Trần Toàn lãnh nhiệm vụ ngăn chặn thủy quân giặc. Quân đội nhà Trần với tinh thần “Sát thát” đã ra sức rèn luyện để có tinh thần và kỹ thuật chiến đấu cao. Tướng sĩ đã từng trải chiến trận, thông hiểu binh pháp. Quân đội được xây dựng theo phương thức “cốt tinh nhuệ”, trở thành chỗ dựa tin cậy của vương triều.

Cuối tháng 12 năm 1287, quân xâm lược vượt biên giới tiến công Đại Việt. Theo kế hoạch của Quốc công Tiết chế, quân ta chủ động rút lui, không quyết chiến buổi đầu với giặc, nhằm bảo toàn lực lượng, từng bước đánh kìm chân địch và dẫn dắt quân thù vào thế trận của ta, tạo thời cơ phản công tiêu diệt. Trong khi đó các cánh quân bộ binh, kỵ binh của Thoát Hoan và Ái Lỗ ào ạt tiến vào Đại Việt thì đạo thủy quân của chúng cũng lên đường. Trên hướng đường thủy, quân ta do phó tướng Trần Khánh Dư chỉ huy không thể ngăn chặn được bước tiến của đạo thủy quân do Ô Mã Nhi và Phàn Tiếp cầm đầu. Tuy nhiên, thủy quân của ta đã giành được một thắng lợi có ý nghĩa lớn, đó là chiến thắng Vân Đồn - Cửa Lục, hoàn thành nhiệm vụ tiêu diệt toàn bộ đoàn thuyền lương của Trương Văn Hổ. Quân Trần thu được lương thực, khí giới của giặc rất nhiều không kể xiết. Còn tên chỉ huy đoàn thuyền tải lương của quân Nguyên là Trương Văn Hổ vội vã lấy thuyền nhẹ chạy trốn ra Quỳnh Châu (đảo Hải Nam, Trung Quốc).

Về phía quân Nguyên, sau khi hội quân ở Vạn Kiếp, Thoát Hoan đã cố xây dựng ở vùng này thành một căn cứ quân sự lớn cho cả quân bộ lẫn quân thủy. Đến ngày 27 tháng 1 năm 1288, Thoát Hoan bắt đầu chia quân tiến về Thăng Long. Quân dân nhà Trần đã đặt phục binh đánh giặc rồi lại rút lui. Thoát Hoan lại chiếm được Kinh thành Thăng Long. Từ Thăng Long, chủ tướng Thoát Hoan huy động một lực lượng thủy quân lớn có sự hỗ trợ của bộ binh đuổi theo quân đội nhà Trần hòng bắt sống vua Trần và triều đình. Tướng giặc Ô Mã Nhi đe dọa vua Trần: “Ngươi chạy lên trời, ta theo lên trời; ngươi chạy xuống đất ta theo xuống đất; ngươi trốn lên núi ta theo lên núi; ngươi lặn xuống nước ta theo xuống nước (Từ Minh Thiên, Thiên Nam hành ki, bản thuyết phu (tài liệu Trung Quốc) tr.12). Thế nhưng đồ của quân Nguyên không thực hiện được, chúng không sao bắt được những người lãnh đạo chủ chốt của triều đình nhà Trần. Quân giặc tức tối thẳng tay tàn sát nhân dân. Tướng giặc Ô Mã Nhi đã cho quân sục vào phủ Long Hưng (Tiên Hưng, Thái Bình), nơi có lăng mộ của họ Trần, cho khai quật lăng Trần Thái Tông để trả thù lần thất bại trước của hắn. Bấy giờ vua Trần và triều đình đã theo cửa Thiên Trường (Giao Thủy) ra biển. Quân giặc còn triệt hạ điền trang thái ấp, tàn phá nhiều làng mạc, gây ra trăm ngàn tội ác với nhân dân ta. Một dải đồng bằng từ Thăng Long đến các lộ Hồng, Khoái tiêu điều xơ xác. Tuy nhiên đi đến đâu, chúng cũng gặp vườn không nhà trống và bị quân dân địa phương chống lại quyết liệt. Chúng cũng không thể cướp được lương thực vi nhân dân đã mang hết thóc, gạo cất giấu đi nơi khác.

Ngày 6 tháng 2 năm 1288, không đuổi kịp được vua Trần, Thoát Hoan đành cho quân trở lại Thăng Long. Việc thiếu lương thực đã trở thành nguy cơ nghiêm trọng đối với đạo quân khổng lồ của nhà Nguyên. Đã gần hai tháng đóng quân ở Thăng Long, mấy chục vạn quân Nguyên lâm vào tình trạng nguy khốn. Quân Nguyên tuy chiếm được một vùng rộng lớn, nhưng ý đồ đánh nhanh thắng nhanh, tiêu diệt quân chủ lực và bộ máy lãnh đạo kháng chiến của nhà Trần không thực hiện được. Bấy giờ quân ta tiến công ở nhiều nơi, quân Nguyên ốm yếu và thiếu lương ăn, tinh thần chiến đấu sa sút, rệu rã. Thoát Hoan đã thấy chán nản, muốn rút quân về. Bọn tướng Nguyên bàn với Thoát Hoan: "Ở Giao Chỉ không có thành trì để giữ, không có lương thực để ăn, mà thuyền lương của Trương Văn Hổ không đến. Vả lại, khí trời nóng nực, lương hết, quân mệt, không lấy gì để chống giữ lâu được, làm hổ thẹn cho triều đình, chỉ bằng nên toàn quân rút về thì hơn" (Nguyên sử, quyển 209, An Nam truyện). Thoát Hoan cũng thừa nhận: “Ở đây nóng nực ẩm thấp, lương hết quân mệt và đồng ý rút quân về. Lúc đó lực lượng của quân Nguyên tuy còn rất đông, do bị quân ta tiến công mãnh liệt, chúng sa vào một cuộc chiến tranh toàn dân, ngày càng tiến gần đến nguy cơ bị tiêu diệt. Thoát Hoan chấp nhận rút quân, nhưng rút bằng cách nào là cả một vấn đề mà các tướng Nguyên phải bàn bạc. Kẻ thì đề nghị hủy thuyền đi bộ, kẻ khác muốn đi cả bộ lẫn thuyền. Tập trung mấy chục vạn quân rút theo đường bộ thì quá chậm chạp, thật khó mà an toàn tính mạng. Bài học “Hằng, Quán” cũng như vết nhục và nỗi sợ “chui vào ống đồng” trước đây vẫn ám ảnh viên chủ tướng. Cũng cần nói thêm rằng, trong cuộc xâm lược Đại Việt lần trước, Thoát Hoan đã thất bại thảm hại. Đại Việt sử ký toàn thư chép: “Tháng 6-1285, Lý Hằng đem quân hộ vệ Thoát Hoan chạy về Tư Minh. Quân ta lấy tên thuốc bắn trúng vào đầu gối bên trái của Hằng, Hằng chết, tỳ tướng là Lý Quán thu nhặt 5 vạn quân còn lại lấy đồ đồng giấu Thoát Hoan vào trong để trốn về Bắc. Đến Tư Minh, Hưng Võ Vương đuổi theo, lấy tên thuốc bắn trúng Lý Quán, Quán chết. Quan Nguyên cả vỡ" (Đại Việt sử ký toàn thư, Tập II, Sđd, tr.61 - 62).

Cuối cùng, Thoát Hoan quyết định lần này chia quân làm hai đường thủy bộ rút về nước. Kế hoạch rút lui của giặc như sau:
- Quân bộ do Thoát Hoan chỉ huy, có A Bát Xích (Abatri) dẫn kỵ binh đi trước mở đường rút theo đường Lạng Sơn.
- Quân thùy do Ô Mã Nhi, Phàn Tiếp chỉ huy rút về theo đường sông Bạch Đằng ra biển.
Cùng rút với đạo quân thùy còn có thân vương Tích Lệ Cơ và viên quan vạn hộ thủy quân Trương Ngọc. Để bảo vệ cho đoàn thủy binh rút lui có đội kỵ binh dọc theo sông hộ tống.

Về phía ta, Hưng Đạo Vương Trần Quốc Tuấn cùng hai vua Trần (Trần Thánh Tông và Trần Nhân Tông) luôn theo dõi chặt chẽ mọi âm mưu và hành động của giặc. Trần Quốc Tuấn biết chắc rằng, Thoát Hoan không còn cách gì hơn là tháo chạy. Vì thế, trên khắp các ngả đường mà quân Nguyên có thể chạy qua, quân đội Đại Việt đã được lệnh bố trí lực lượng để chặn đánh. Một cạm bẫy lớn đã được giăng ra, đặc biệt trên hướng đường thủy ở Bạch Đằng, sẵn sàng đánh đòn quyết định tiêu diệt giặc Nguyên. Tử các nguồn tin thu thập ở Thăng Long và Vạn Kiếp, quân ta đã nắm chắc được lực lượng và kế hoạch rút lui của quân Nguyên. Kế hoạch rút chạy của Thoát Hoan không nằm ngoài dự đoán từ trước của Quốc công Tiết chế Trần Quốc Tuấn. Quân và dân ta được huy động chuẩn bị cho một trận đánh quyết định. Không có tài liệu nào ghi chép cụ thể số lượng quân dân ta tham chiến trong trận Bạch Đằng. Nhưng do vị trí và ý nghĩa chiến lược của trận quyết chiến này, chắc chắn Trần Quốc Tuấn đã tập trung về đây một bộ phận quan trọng quân chủ lực của triều đình kết hợp với quân của các vương hầu và dân binh. Trong lực lượng chủ lực được huy động vào trận Bạch Đằng, có phần lớn thủy bình và những lực lượng bộ binh tinh nhuệ của nhà Trần như đạo quân của Hưng Đạo Vương Trần Quốc Tuấn, đạo quân của hai vua Trần, đạo quân Thánh dực nghĩa dũng do tướng Nguyễn Khoái chỉ huy, đạo quân Hữu vệ thánh dực do Phạm Ngũ Lão chỉ huy, đạo quân của các con Trần Quốc Tuấn (như Hưng Trí Vương Hiến), quân của Trần Quốc Bảo... Đáng chú ý trong trận Bạch Đằng, cùng tham gia chuẩn bị và trực tiếp chiến đấu với quân đội chủ lực còn có nhiều đội dân binh và sự đóng góp hết sức to lớn của nhân dân vùng ven biển Hạ Hồng (Hải Phòng, Hải Dương, Quảng Ninh), trong đó có đông đảo nhân dân hai xã bên bờ sông Bạch Đằng. Sử sách không ghi chép nhiều về sự tham gia của dân binh, nhưng tên tuổi của nhiều anh hùng địa phương và sự tích cứu nước của quần chúng nhân dân vẫn còn được lưu truyền trong dân gian với một số di tích đền miếu, bia tượng, địa danh... Những di tích và câu chuyện dân gian đó thường gắn liền với vai trò tổ chức, lãnh đạo và hình ảnh của vị anh hùng dân tộc Trần Quốc Tuấn. Toàn bộ lực lượng quân sự trên đây đều đặt dưới sự chỉ huy trực tiếp của Quốc công Tiết chế Hưng Đạo Vương Trần Quốc Tuấn. Dưới quyền ông là những danh tướng “sức dư trăm trận" như: Nguyễn Khoái, Phạm Ngũ Lão, Nội minh tự Đỗ Hành - người đã từng tham gia “bẻ gãy giáo giặc ở bến Chương Dương, bắt sống giặc Hồ ở cửa Hàm Tử”. Có những tướng soái thuộc dòng tôm thất như Trần Quốc Hiến, Trần Quốc Bảo; có người chỉ huy giỏi xuất thân từ gia nô hay bình dân như Yết Kiêu, Dã Tượng; có những quan văn giỏi mưu kế như Nguyễn Xuân, có nhiều võ tướng anh dũng người địa phương như Vũ Đại, Hoàng Thản, Hoa Duy Thành, và còn biết bao nhiêu người chỉ huy dân binh dũng cảm, mưu trí khác.

Từ dự đoán đường rút của quân Nguyên và dự kiến kế hoạch tác chiến của mình, Trần Quốc Tuấn đã dùng đại bộ phận thủy quân cùng một lực lượng lớn bộ binh bố trí thành một trận địa mai phục ở thượng lưu sông Bạch Đằng. Một trận địa bãi cọc ngầm được chuẩn bị, bày sẵn. Đó là bãi cọc gỗ nằm ở cửa sông Chanh sát liền với sông Bạch Đằng, ngày nay ta quen gọi là bãi cọc Yên Giang và các bãi cọc kết hợp khác ở sông Kênh, sông Rút... Tất cả kết hợp với nhau kéo dài như một phòng tuyến ngầm dàn ra ở các cửa sông, sẵn sàng chặn đánh quân địch tháo chạy. Bộ binh của ta một phần mai phục ở núi Tràng Kênh để phối hợp với thủy binh chiếm giữ các điểm cao và sẵn sàng đánh bật địch xuống sông nếu chúng dám liều lĩnh đổ bộ lên bờ. Lực lượng mai phục trong những cánh rừng và bãi sú vẹt kín đáo ven sông bên tả ngạn, nhiều nhất là ở vùng cửa sông Chanh, sông Kênh... Đây là nơi mà hàng trăm thuyền chiến địch sẽ dồn lại và lực lượng thủy bộ của ta phối hợp với nhau đánh giặc cả trên sông, trên bờ, tiêu diệt toàn bộ quân giặc. Nhiều thuyền nan, thuyền nứa chứa đầy củi khô tẩm các thứ nhựa, dầu cháy đã được chuẩn bị sẵn sàng ở chân núi Tràng Kênh để thực hiện kế hoạch hỏa công. Một đội thuyền nhẹ của ta sẵn sàng khiêu chiến như địch.

Về phía quân Nguyên, thực hiện kế hoạch đã định, từ căn cứ Vạn Kiếp, Thoát Hoan cho đạo quân thủy của Ô Mã Nhi, Phân Tiếp rút lui trước. Trên bờ có đội kỵ binh hộ tống do Hữu thừa Trình Bằng Phi và Thiêm tỉnh Đạt Truật chỉ huy. Đạo quân bộ của Thoát Hoan vẫn đóng ở Vạn Kiếp để hỗ trợ cho quân thủy rút lui an toàn rồi mới rút theo đường bộ qua Lạng Sơn. Về số lượng quân Nguyên rút lui bằng đường thủy là bao nhiêu? Khi tiến sang xâm lược nước ta cuối năm 1287, đoàn thuyền chiến của địch gồm 620 chiếc (theo Nguyên sử q.209 và An Nam chỉ lược q.4, lúc đầu nhà Nguyên huy động 500 thuyền chiến sang đánh Đại Việt. Sau đó lại bổ sung thêm 120 chiếc lấy ở Quỳnh Lôi, Hải Nam và Nam Ninh, Quảng Tây, đưa tổng số thuyền chiến lên 620 chiếc). Sau mấy trận đánh ở chiến trường vùng ven biển Đông Bắc, số thuyền của địch có bị hao hụt, nhưng chúng lại cướp và đóng thêm để bù vào. Số chiến thuyền quân Nguyên sử dụng trong cuộc rút lui này khoảng 600 chiếc. Theo những tài liệu đương thời thì mỗi thuyền chiến của quân Nguyên có thể chở được trên dưới 100 người. Như vậy số quân địch rút quân bằng đường thủy có khoảng trên 6 vạn binh sĩ.

Ngày 30 tháng 3 năm 1288, đạo thủy quân do Ô Mã Nhi và Phản Tiếp chỉ huy bắt đầu rút. Đoàn kỵ binh hộ tống của Trình Bằng Phi gặp nhiều khó khăn, tiến chậm chạp do bị quân ta triệt phá cầu đường và liên tục đánh chặn. Khi đến chợ Đông Triều (Quảng Ninh), không thể vượt qua sông được, đoàn kỵ binh này quay trở lại. Vì cầu đường đã bị phá và biết tin quân ta đang chờ chặn đánh nên Trình Bằng Phi không dám trở về theo đường cũ, đang đêm chúng cưỡng bức các hương lão đã bị chúng bắt, đưa đường khác trở về Vạn Kiếp để còn kịp theo Thoát Hoan rút chạy về nước. Ta không tốn nhiều sức mà đội kỵ binh của địch mới đi được mươi dặm đã phải quay trở lại, bỏ mặc đạo binh thuyền Ô Mã Nhi đang hành trình trên sông, Việc tách được đoàn thuyền chiến khỏi đội kỵ binh hộ tống, đã tạo điều kiện thuận lợi cho trận chiến sau đó. Do đánh nhau liên tục với quân ta trong mấy tháng trời, vừa trở về Vạn Kiếp nay lại phải ra đi, đoàn thuyền chiến của Mã Nhi gặp rất nhiều khó khăn. Quân sĩ mỏi mệt, bọn tướng chỉ huy thì run sợ, hoang mang lo lắng. Chúng miễn cưỡng tiến hành cuộc hành quân bằng đường thủy, điều mà chúng hoàn toàn không muốn, nhất là trong trường hợp này. Trước đây, chúng đã bao phen bị đại bại khi đụng đầu với thủy binh Đại Việt ở An Quảng, Đại Bàng, Tháp Sơn và giờ đây quân ta đang đợi chúng trên đường về. Dọc đường từ Vạn Kiếp qua sông Kinh Thầy, quân ta đã tổ chức nhiều trận đánh tiêu hao địch. Nhiều trận tập kích đã xảy ra kìm hãm bước tiến của chúng. Nguyên sử chép: “Giao chiến ngày này qua ngày khác”. Vì không có quân hộ tống nên đoàn thuyền của Ô Mã Nhi di chuyển vô cùng chậm chạp.

Ngày 8 tháng 4, tiền vệ của địch do do tướng Lưu Khuê chỉ huy tiến đến đầu sông Giá (dẫn theo Lê Trác trong An Nam chỉ lược, có ý kiến cho rằng Lưu Khuê rút theo đường bộ). Chúng vừa thăm dò lực lượng quân ta vừa tìm đường gần nhất để theo sông này ra sông Bạch Đằng. Đến vùng Trúc Động, Lưu Khuê bị quân ta đón đánh (Trúc Động nay thuộc xã Lưu Kiếm, huyện Thủy Nguyên, thành phố Hải Phòng). Trận Trúc Động là trận phục kích nghi binh diễn ra cả ngày lẫn đêm. Theo truyền thuyết, trước đó mỗi gia đình người dân ở đây nộp cho quân đội nhiều mo cau có trát sơn và các bè chuối. Khi được tin quân giặc sắp kéo đến, quân ta từ trên núi thay đổi quần áo và cờ lệnh năm lần với năm màu sắc khác nhau, lại thả rất nhiều mo cau và thân chuối trôi đầy sông. Đêm tối, đuốc sáng trưng, chiêng trống vang trời. Đồng thời quân ta từ phía trước và hai bên cùng đánh, tên bắn xuống như mưa gây cho địch nhiều thiệt hại. Giặc Nguyên tưởng quân ta đông, rất hoang mang lo sợ. Qua một ngày đêm chiến đấu, mưu trí và linh hoạt, quân dân ta đã đánh cho đội quân Lưu Khuê thất bại hoàn toàn, phần lớn bị tiêu diệt, số còn lại quay ra dòng Đá Bạc xuôi cùng đoàn thuyền Ô Mã Nhi. Trúc Động là trận đánh chặn bảo vệ, chuẩn bị cho trận Bạch Đằng. Trần Quốc Tuấn không để địch xuôi theo sông Giá; vì nếu địch hành quân theo đường này thì lực lượng bố trí của ta bị lộ, thế chủ động bất ngờ của trận Bạch Đằng không còn nữa. Mặt khác, quân ta cần phải kiềm chế để từng bước dẫn dắt quân địch vào trận địa mai phục đúng địa điểm và thời gian đã định. Thắng lợi Trúc Động đã bảo vệ an toàn cho lực lượng ta bố trí trên sông Giá, sông Thải và các dãy núi hai bên bờ. Thắng lợi đó bảo đảm bị mật cho trận địa Bạch Đằng và buộc địch phải đi theo đường dự kiến của ta.

Sáng sớm ngày 9 tháng 4 năm 1288, đoàn thuyền của Ô Mã Nhi theo sông Đá Bạc tiến xuống. Đội tiền quân do Tham chính Phàn Tiếp chỉ huy. Lúc đó nước triều vẫn còn mênh mông, thuyền địch đi chậm chạp. Ngày hôm đó, đúng vào độ nước cường, thủy triều dâng cao và lên xuống mạnh, dự tỉnh về con nước lúc cao nhất vào nửa đêm hôm trước là 3,20m và thấp nhất là 0,90m vào buổi trưa ngày hôm sau, như vậy độ chênh lệch là 2,30m. Khi triều xuống thấp thì nước chảy rất mạnh. Quân Đại Việt trên các môm đá đã sẵn sàng cung tên, giáo dài, chờ vào lúc nước triều xuống mạnh và đạo binh thuyền Ô Mã Nhi qua sông Đá Bạc, lọt vào sông Bạch Đằng mới đổ ra quyết chiến. Khoảng 6 đến 7 giờ sáng (giờ mão) nước triều từ từ xuống, tức là gần đến khi các bãi cọc phát huy tác dụng, cũng là lúc cuộc chiến đấu bắt đầu. Hưng Đạo Vương Trần Quốc Tuấn ra lệnh “cho quân khiêu chiến, rồi già cách thua, quân giặc đuổi theo, quân ta cố sức đánh lại (Sđd, tr.67). Đội quân của Phàn Tiếp đuổi theo và tiến lên phía trước. Thủy triều xuống mạnh càng đưa thuyền địch lao nhanh. Phản Tiếp vội đưa thuyền áp sát về phía Tràng Kênh rồi thúc quân “chiếm lấy đình cao (Lê Trắc, An Nam chỉ lược, q.5) hòng ngăn chặn quân ta phía núi, hỗ trợ cho trung và hậu quân tiến lên. Địch lọt vào trận địa mai phục của ta. Trống hiệu nổi lên, cờ hiệu tung bay phấp phới thôi thúc đoàn quân chiến đấu. Thủy binh ta trên các truyền nhẹ từ các ngả sông, nhánh sông, từ trong các lùm cây, bãi sĩ bất ngờ xông ra. Bộ phận quân ta gồm cả quân chủ lực và dân binh dưới quyền chỉ huy của tướng Trần Quốc Bảo đóng ở các áng núi lạch công mại nhục sẵn ở núi Tràng Kênh lao ra quyết chiến. Từ trên núi cao quân ta đánh hất địch xuống hết đợt này đến đợt khác để giữ vững vị trí. Thủy quân Hải Đông - Vân Trà từ các phía Điền Công, Gia Đước, sông Thải, sông Giá nhanh chóng tiến ra sông Bạch Đằng. Quân Thánh dực nghĩa dũng lộ Hồng Khoái (Hải Dương, Hưng Yên) do tướng quân Nguyễn Khoái chỉ huy với hàng trăm chiến thuyền cùng quân các lộ căng tay chèo lao nhanh ra sông, dựa vào Ghềnh Cốc lập thành một dải chiến thuyền hùng vĩ chặn đầu quân địch, “chẳn chiến hạm ở ngang sông . Đại quân địch do Ô Mã Nhi thống lĩnh lúc đó cũng vừa đổ vào sông Bạch Đằng. Thuyền chiến của giặc san sát, phần nhiều là loại thuyền Quảng Đông to lớn đóng bằng thứ gỗ tốt nặng nề trôi về hướng Ghềnh Cốc. Bộ phận đi đầu cố tránh quãng ghềnh cạn, dồn đội hình lại, định vượt qua quãng ghềnh sâu nhưng bị ngay thủy quân ta tiến công vào giữa đội hình. Một số thuyền giặc luống cuống va vào quãng ghềnh cạn, chiếc bị đắm, chiếc lật nghiêng. Những chiếc khác hốt hoảng giạt sang một bên, bị thủy quân ta xông vào tiêu diệt. Các thuyền chiến của tướng quân Nguyễn Khoái tả xung hữu độ trên quãng sông Ghềnh Cốc khiến quân Nguyên không thể nào vượt qua được. Tiếng chiêng trống, tiếng hò reo của quân ta khiến quân Nguyên càng hoảng loạn. Quân ta “bắn tên như mưa" dồn thuyền địch về phía tả ngạn sông. Ô Mã Nhi phải ra lệnh thúc thuyền hướng theo các cửa sông Chanh, sông Kênh, sông Rút để tìm đường tháo chạy ra biển.

Bấy giờ là quãng giữa trưa. Thủy triều rút nhanh, nước xuống đến mức thấp nhất. Các trận địa cọc im lìm bấy lâu ẩn dưới làn nước triều mênh mông bỗng nhiên xuất hiện, như vùng lên cùng người đánh giặc. Bị nước đẩy xuôi, lại bị đánh gấp phía sau lưng, thuyền giặc hết lớp trước đến lớp sau bị dồn vào bãi cọc. Nhiều thuyền chiến của giặc bị nghẽn trước cửa sông Chanh, một số thuyền bị cọc đâm thủng nhiều chiếc va vào Ghềnh Các một số dần lai trước cửa sông Kênh, sông Rút. Số thuyền giặc bị đắm hoặc bị mắc cạn không thể tiến lên được nhiều vô kể.

Cuộc chiến đấu diễn ra hết sức ác liệt. Từng trận mưa tên tẩm thuốc độc trùm lên đầu giặc. Thuyền chiến của quân ta cơ động nhanh áp sát vào thuyền địch đánh gần; quân ta dùng gươm, câu liêm hai lười, lưỡi quắm, giáo dài, ngạch lớn, dùi bốn cạnh đâm chém giết chết vô số quân giặc. Quân ta càng đánh khí thế càng hăng. Đúng lúc đó, các bè nửa, thuyền nan chứa đầy chất dễ cháy giấu sẵn ở vùng Tràng Kênh, từ các làng Do Lễ, Phục Lễ, Phả Lễ được các đội dân bình nổi lửa đốt lên, thả xuôi dòng nước lao thẳng vào giữa đội hình thuyền chiến của giặc đang hỗn loạn, bị nghẽn tắc trước hàng cọc gỗ. Thuyền giặc bắt lửa, bốc cháy ngùn ngụt, thiêu sống bọn giặc trên thuyền. Trận hòa công dữ dội đã gây ấn tượng mạnh mẽ, đến tận ngày nay nhân dân địa phương vẫn còn lưu truyền câu ca:

> “Bạch Đằng nhất trận hóa công
> Tặc binh đại phả, huyết hồng mãn giang".
> (Bạch Đằng một trận hỏa công
> Phá tan quân giặc, máu hồng đầy sông).

Trên đà thắng lợi, quân ta càng hăng hái đánh địch. Phía núi Tràng Kênh, quân ta vừa dùng cung tên bắn, vừa đánh giáp lá cà, khiến cho toàn đội binh thuyền Phàn Tiếp phải nhảy xuống sông. Địch bị chết, bị thương không kể xiết. Tướng giặc là Phàn Tiếp bị trúng tên, nhảy xuống nước, bị quân ta dùng câu liêm móc lên, bắt sống.

Giữa lúc trận thủy chiến và hòa công đang diễn ra quyết liệt thì đoàn thuyền chiến của hai vua Trần theo kế hoạch đã kịp xông tới hợp sức tiến công địch. Trước đó, đạo quân của hai vua đóng ở vùng Hiệp Môn bên bờ sông Giáp (sông Kinh Thầy, vùng Kinh Môn) làm nhiệm vụ đánh tiêu hao và kiềm bước địch. Khi biết giặc đã lọt vào sông Bạch Đằng, hai vua Trần sẵn sàng đội ngũ, cờ hiệu rợp sông, theo đà nước, tiến gấp để kịp thời đánh địch. Đại Việt sử ký toàn thư chép: “Hai vua đem quân tiếp đến, tung quân đánh hăng, quân Nguyên chết đuối không xiết kể, nước sông đến nỗi đỏ ngàu (Đại Việt sử ký toàn thư, Sđd, tr.67). Đòn của hai vua Trần đánh vào sau lưng địch đã khiến cho chúng càng bị động, lúng túng và thiệt hại nặng. Sau đó mấy chục năm, đầu thế kỷ XIV, danh sĩ Phạm Sư Mạnh viết bài thơ ca ngợi chiến công Bạch Đằng trong đó có nhắc tới hai vua rằng:

> “Ức tích Trùng Hưng để
> Khắc chuyển khôn oát kiền
> Hải phổ thiên mông đồng
> Hiệp Môn vạn tỉnh chiên".
> (Nhớ xưa vua Trùng Hưng
> Khéo xoay trời chuyển đất
> Bãi biển nghìn chiến thuyền
> Hiệp Môn vạn cờ xí).

Ô Mã Nhi bạt đô, viên tướng Nguyên mang danh hiệu “dũng sĩ” ấy không thể nào chống đỡ nổi đòn tiến công mãnh liệt của quân và dân nhà Trần. Tình thế không thể xoay chuyển được. Thủy triều xuống thấp, chiến thuyền quân Nguyên vướng cọc bị đốt, đắm và phá hủy ngày càng nhiều. Đến chiều hầu như toàn bộ chủ sự của quân Nguyên bị tiêu diệt. Chủ tướng chỉ huy thủy quân giặc là Ô Mã Nhi bị quân ta bắt sống. Viên Vạn hộ thủy quân Trương Ngọc tử trận. Rất nhiều tướng giặc bị bắt, trong đó có viên đại quý tộc Mông Cổ tước vương Tích Lệ Cơ (Si rê ghi) và quan giữ văn thư theo Ô Mã Nhi là Lý Thiên Hựu cùng bọn thuộc hạ bị bắt sống. Hơn 400 thuyền giặc lọt vào tay quân dân Đại Việt.

Một bộ phận quân Nguyên hốt hoảng bỏ thuyền chạy lên bờ tả ngạn Yên Hưng hòng tìm đường trốn thoát. Nhưng khi chúng vừa lên bờ đã vấp phải bộ bình quân ta dưới quyền chỉ huy của Trần Quốc Tuấn, phục sẵn từ trước. Cuộc chiến đấu trên bộ cũng diễn ra hết sức quyết liệt. Nếu như trận thủy chiến trên sông đã tiêu diệt phần lớn sinh lực địch thì trận đánh trên bộ lại bồi thêm cho chúng những đòn chí tử, tướng giặc Phạm Nhan bị bắt, toàn bộ quân địch bị tiêu diệt. Trương Hán Siêu, nhà văn, nhà chính trị nổi tiếng thời Trần đã mô tả rằng: “Chiết kịch trầm giang, khô cốt doanh khâu", nghĩa là: giao mác chìm sông, xương khô đầy gò. Cho đến nay, nhân dân các xã vùng Hà Nam còn lưu truyền câu ca dao nói về cuộc chiến đấu gay go trên bộ ấy:

> “Bạch Đằng giang là sông cửa ải
> Tổng Hà Nam là bãi chiến trường .

Đến chiều, trận đánh vô cùng ác liệt và oai hùng trên sông Bạch Đằng kết thúc. Cả đạo thủy binh hùng mạnh của Ô Mã Nhi bị tiêu diệt hoàn toàn, đúng như Trương Hán Siêu đã mô tả:

> "... Bấy giờ:
> Muôn dặm thuyền bè, tinh kỳ phấp phới
> Sảu quân oai hùng, gươm giáo sáng chói
> Sống mải chưa phân, Bắc - Nam lũy đổi
> Trời đất rung rinh (chừ) sắp tan
> Nhật nguyệt u ảm (chừ) mờ tối...".
> (Phú sông Bạch Đằng)

Bài phú đã nói lên hùng khí của quân dân ta trong giờ phút lịch sử, lòng dũng cảm tuyệt vời của các chiến sĩ quyết xả thân vì nước. Trong khi toàn bộ đoàn thuyền binh của quân Nguyên tan tác trên sông Bạch Đằng thì cánh quân bộ của Thoát Hoan cũng đang khốn đốn trên đường tháo chạy khỏi biên giới Đại Việt. Trên tất cả các đường rút của bộ binh và kỵ binh giặc đều bị quân đội nhà Trần phục kích chờ đánh. Thoát Hoan dẫn quân chạy đến cửa quan Nội Bàng thì lại lọt vào trận địa phục kích đã được bố trí sẵn. Bọn chúng phải ra sức chống lại mới mở đường máu rút được. Nhưng quân Trần vẫn tiếp tục truy kích, Thoát Hoan phải cho Vạn hộ Trương Quân chỉ huy ba nghìn quân tình nhuê đi sau hộ vệ. Quân Nguyên vừa ra khỏi cửa Nội Bàng, chưa kịp hoàn hồn thì được tin quân Trần đã đóng ở cửa quan Nữ Nhi và núi Khưu Cấp. Quân ta đã rải quân suốt hơn một trăm dặm để chặn đường về của giặc.

Tin đại thắng trên sông Bạch Đằng nhanh chóng truyền lan khắp nước, càng làm nức lòng quân dân Đại Việt, trở thành nguồn động viên mạnh mẽ đối với tất cả các chiến sĩ miền biên giới hăng hái xông lên tiêu diệt đạo quân Thoát Hoan. Những chiến thắng to lớn ở cửa quan Hãm Sa, các ải Nội Bàng, Nữ Nhi, Khưu Cấp (đều thuộc Bắc Giang, Lạng Sơn) đã liên tiếp giáng cho đạo quân này những đòn thất bại nặng nề. Hàng vạn quân Nguyên phải rải xác trên đường tháo chạy. Những hố sâu được đào và ngụy trang rất khéo léo để làm bẫy diệt kỵ binh giặc. Quân ta từ trên núi cao bắn tên độc xuống. Tướng giặc là Abatri trúng ba mũi tên độc, đầu cổ đùi đều sưng lên rồi chết. Cuối cùng, quân Nguyên cũng về được đến phủ Tư Minh (Quảng Tây, Trung Quốc) vào ngày 19 tháng 4 năm 1288, Thoát Hoan cho rải tán đám tàn quân. A Ruc đem quân trở về Vân Nam, Agurutri dẫn quân về Bắc. Trần Ích Tắc lại lẽo đẽo theo bọn tướng tá Nguyên trở về Ngạc Châu.

Chín ngày sau trận đại thắng Bạch Đằng, ngày 18 tháng 4 năm 1288 Thượng hoàng Trần Thánh Tông và vua Trần Nhân Tông về phủ Long Hưng, đem bọn tù binh Ô Mã Nhi, Tích Lệ Cơ, Phàn Tiếp và nhiều tên Vạn hộ, Thiên hộ khác của giặc làm lễ mừng thắng trận trước lăng Trần Thái Tông, vị vua anh hùng đã lãnh đạo cuộc kháng chiến chống quân xâm lược Mông Cổ lần thứ nhất năm 1258. Trong buổi lễ trang nghiêm, vua Trần Nhân Tông nhớ lại những ngày gian khổ, cảm khái đọc:

> “Xã tắc lưỡng hồi lao thạch mã
> Sơn hà thiên cổ điện kim âu".
> (Đất nước hai phen chồn ngựa đá
> Non sông nghìn thuở vững âu vàng).

Để ca ngợi công lao đó, Trương Hán Siêu đã làm bài thơ:
> Vua Trần hai vị Thánh quân
> Sông kia còn dầu tẩy trần giáp binh
> Ngàn xưa ngẫm cuộc thăng bình
> Tại đâu đất hiểm, bởi mình đức cao!

Ngày 28 tháng 4 năm 1288 xa giá hai vua Trần và triều đình trở về Kinh đô Thăng Long. Giữa cung điện bị thiêu hủy, kinh thành bị tàn phá nặng nề, vua Trần ban lệnh đại xá thiên hạ, miễn tô dịch toàn phần cho những nơi bị giặc cướp phá. Trận Bạch Đằng năm 1288 hoàn thành vẻ vang nhiệm vụ tiêu diệt đạo quân rút lui đường thủy do Ô Mã Nhi và Phàn Tiếp chỉ huy, là trận quyết chiến lớn nhất, kết thúc cuộc kháng chiến chống Nguyên lần thứ ba. Một đạo quân lớn trên 6 vạn người, giàu kinh nghiệm viễn chinh xâm lược, những tên tướng quý tộc, cao cấp thân cận của Hốt Tất Liệt, sừng sỏ và độc ác như Ô Mã Nhi, Phàn Tiếp, Tích Lệ Cơ, Lưu Khuê... sau mấy lần giày xéo đất nước ta, đã phải đền tội. Chiến thắng Bạch Đằng cùng với những chiến công khác trong cuộc chiến tranh đã đánh tan mấy chục vạn quân Nguyên xâm lược, bảo vệ nền độc lập của Tổ quốc, khẳng định sự tồn tại vững vàng không thể lay chuyển được của cả nước Đại Việt, một đất nước ở sát cạnh một đế chế cường thịnh nhất thế giới đương thời đầy âm mưu xảo quyệt và tham vọng bành trướng. Chiến thắng của quân dân nhà Trần đã đập tan âm mưu chiếm nước ta làm căn cứ, làm bàn đạp để tiến hành xâm lược các nước phương Nam, ngăn chặn sự bành trướng của đế quốc Mông - Nguyên xuống Đông Nam Á. Chiến thắng Bạch Đằng cùng với những chiến thắng khác đã gây chấn động ở nhiều nước và nó đã có tác dụng góp phần bảo vệ nền độc lập dân tộc cho các nước láng giềng.

Chiến thắng Bạch Đằng năm 1288 là hình ảnh tập trung tiêu biểu nhất của sức mạnh tổng hợp về tinh thần và vật chất của quân và dân ta, là biểu tượng của khí phách anh hùng, ý chí quật cường bất khuất và tinh thần đoàn kết dân tộc thời bấy giờ. Đặc biệt, chiến công này đã thể hiện trí tuệ và tài thao lược của ông cha ta thế kỷ XIII mà tiêu biểu là nhà quân sự kiệt xuất - anh hùng dân tộc Hưng Đạo Vương Trần Quốc Tuấn. Trước hết, đó là tư tưởng chủ động về chiến lược cũng như chiến thuật của Trần Quốc Tuấn và các nhà lãnh đạo kháng chiến. Cũng như trong cuộc kháng chiến chống quân Nguyên lần thứ hai (1285), trong cuộc kháng chiến lần này Trần Quốc Tuấn lại được cử làm Quốc công Tiết chế, lĩnh sứ mệnh tổng chỉ huy các lực lượng vũ trang. Qua kinh nghiệm dày dặn phong phú của hai cuộc kháng chiến trước, Trần Quốc Tuấn đã đề ra kế hoạch đánh giặc rất chủ động, tài giỏi. Buổi đầu, trước thế mạnh của giặc, quân ta rút về vùng ven biển để bảo toàn lực lượng. Nhưng ở khắp nơi, nhân dân các địa phương trên đường giặc đi qua và trong vùng bị tạm chiếm đóng đều được lệnh cất giấu lương thực, kiên quyết triệt nguồn lương thảo của chúng; đồng thời dân binh đẩy mạnh hoạt động đánh địch làm cho chúng tiêu hao sức lực, ăn không ngon, ngủ không yên, đẩy quân địch vào thế bị động, mệt mỏi, hao kiệt cả về tinh thần lẫn vật chất, cuối cùng mở cuộc phản công chiến lược đánh bại hoàn toàn quân địch. Khi được tin giặc sắp tràn vào biên giới nước ta, vua Trần Nhân Tông đã hỏi Hưng Đạo Vương: “Giặc đến làm thế nào?”. Hưng Đạo Vương trả lời: “Năm nay giặc đến dễ đánh (Đại Việt sử ký toàn thư, Sđd, tr.65). Câu nói đầy tin tưởng đó thể hiện tư tưởng chủ động của ông. Trương Hán Siêu viết:

> Duy thử giang chi đại tiệp
> Do Đại vương chi tặc nhàn
> (Kìa sông này mà đại thắng
> Bởi Đại vương coi thế giặc nhàn).

Trong cuộc kháng chiến chống Nguyên - Mông lần thứ ba, Hưng Đạo Vương Trần Quốc Tuấn và triều đình rất chú trọng đến chiến trường ven biển Đông Bắc. Đây là đường tiến quân của thủy bình và đoàn thuyền tải lương của giặc. Phó tướng Trần Khánh Dư được Trần Quốc Tuấn tin tưởng giao cho mọi công việc biên thùy ven biển, có nhiệm vụ chặn thủy quân giặc, tiêu diệt đoàn thuyền lương, làm thất bại ngay từ đầu kế hoạch hậu cần của chúng. Đây là một đòn hiểm, đánh thẳng vào “dạ dày của giặc. Vừa mới ra quân, địch đã mất sạch lương dự trữ. Đoàn quân viễn chinh bị lâm ngay vào cảnh thiếu đói. Tiền để cho thắng lợi của ta và thất bại của địch đã được tạo ra. Chính vì vậy, khi được tin Trương Văn Hổ cùng đoàn thuyền lương bị tiêu diệt thì quân giặc rất hoang mang, hoảng sợ, lúng túng và buộc phải bàn kế lui quân. Và như vậy đã trúng vào kế sách của Trần Quốc Tuấn. Tuy nhiên trên thực tế, từ hai cuộc kháng chiến lần trước chứng minh: bị thua thảm bại, tướng chết quân tàn, phải chạy về nước, nhưng quân Mông - Nguyên vẫn chưa từ bỏ âm mưu xâm lược nước ta, vẫn ngoan cố quay trở lại. Vì giặc Mông - Nguyên là một đế chế lớn, có tiềm lực kinh tế và quân sự rất mạnh, ý đồ mở rộng phạm vi thống trị rất xảo quyệt. Chưa nếm đòn thật đau, thật hiểm thì chúng chưa chịu từ bỏ tham vọng quay trở lại xâm lược nước ta. Bởi vậy, Trần Quốc Tuấn và Bộ tham mưu kháng chiến đã nhằm đúng thời cơ, lúc địch mệt mỏi, suy yếu, buộc địch phải tháo chạy, để tập trung sức lực đánh đòn quyết định tiêu diệt toàn bộ đạo quân thủy của Ô Mã Nhi và Phàn Tiếp. Chiến thắng Bạch Đằng năm 1288 cũng như tác động của nó đối với chính sách sau này của nhà Nguyên quả là một thành công tiêu biểu của tư tưởng tiến công, tư tưởng chủ động chiến lược của Trần Quốc Tuấn. Quân Nguyên tuy phải rút lui, nhưng lực lượng của chúng còn đông tới hàng chục vạn và lại rút bằng hai đường thủy và bộ. Trong so sánh lực lượng lúc bấy giờ, ta chưa đủ sức để đồng thời tiêu diệt cả hai cảnh quân. Trần Quốc Tuấn đã từng tổng kết và nêu thành một phương châm chỉ đạo chiến lược: “Tóm lại, giặc cậy trường trận, ta cậy đoản binh, lấy đoản chế trường là việc thường của binh pháp. Nếu thấy quân giặc đến ồ ạt như lửa cháy gió thổi thì thể dễ chế ngự. Nếu nó đi chậm như cách tằm ăn, không cần của dân, không cần được chóng, thì phải chọn dùng tướng giỏi, xem xét quyền biến, như đánh cờ vậy, tùy thì mà làm, có thu được quân lính một lòng như cha con thì mới dùng được” (Đại Việt sử ký toàn thư, Sđd, tr.88 - 89). Ở đây, vấn đề đặt ra là phải chọn đối tượng quyết chiến chính xác để có thể đạt được hiệu quả tiêu diệt chiến lược cao nhất, buộc nhà Nguyên phải từ bỏ ý đồ tiếp tục xâm lược nước ta. Trên cơ sở phán đoán đúng mưu đồ, ý định của Thoát Hoan và đánh giá đúng tương quan lực lượng, Trần Quốc Tuấn và Bộ tham mưu đã có chủ trương trước hết tập trung lực lượng tiêu diệt cánh quân rút lui theo đường thủy, rồi sau đó thừa thắng tiêu diệt một bộ phận cánh quân đi bộ. Đây là sự lựa chọn đúng đắn và là quyết tâm chiến lược sáng suốt, chính xác của một nhà chiến lược lớn có tầm nhìn bao quát rộng, có trí tuệ phân tích và phán đoán sắc sảo minh mẫn. Chọn cánh quân rút lui theo đường thủy làm đối tượng tiêu diệt trước hết và chủ yếu là chính xác, vì cánh quân này rút trước và chiến đấu trên sông nước vốn là chỗ mạnh truyền thống của quân đội nhà Trần, là chỗ yếu của quân giặc. Cánh quân thủy khi đã bị tiêu diệt gọn thì cánh quân bộ sẽ phải rút lui trong cảnh hoảng loạn, sợ hãi và sẽ là đối tượng chặn đánh, truy kích dễ dàng của quân dân ta để giáng thêm những đòn tổn thất nặng nề cho quân địch. Như vậy, Trần Quốc Tuấn đã biết nhằm đúng chỗ yếu nhất của địch để tập trung sức tiến công, phát huy cái sở trường của ta để đánh vào cái sở đoản của địch. Với chủ trương và quyết tâm chiến lược như trên, khúc sông Bạch Đằng, ở vùng thượng lưu đã được Trần Quốc Tuấn chọn làm điểm quyết chiến chiến lược. Việc xác định không gian và thời gian quyết chiến đều nhằm triệt để lợi dụng địa hình thiên nhiên, phát huy cao độ ưu thế thùy chiến trong điều kiện thiên thời, địa lợi, nhân hòa thuộc về ta.

Trong chiến tranh chống ngoại xâm, dân tộc ta đánh địch và thắng địch ngay trên đất nước, quê hương của mình. Do vậy, điều kiện địa lý như núi sông, thời tiết, khí hậu... nếu biết tận dụng sẽ trở thành một điều kiện rất có lợi cho ta, một nhân tố thắng lợi của chiến tranh yêu nước. Trần Quốc Tuấn đã nghiên cứu rất tường tận địa hình, sông nước, chế độ thủy triều của sông Bạch Đằng và sử dụng thành công trong việc xây dựng trận địa quyết chiến và bài bình bố trận. Quãng sông Bạch Đằng, nơi được chọn làm điểm quyết chiến là một khu vực hiểm yếu, có đủ những điều kiện cần thiết đáp ứng được yêu cầu bố trí một trận địa mai phục trên sông với quy mô lớn. Địa hình sông Bạch Đằng vốn có thể thiên hiểm với sông sâu và rộng, rừng núi sát ven bờ, nhiều lạch thoát triều và bãi triều, nhiều nhánh sông đổ vào, nước triều lên xuống rất mạnh. Để tăng thêm thế lợi hại của trận địa mai phục, Trần Quốc Tuấn đã kế thừa truyền thống của Ngô Quyền và Lê Hoàn trong kháng chiến chống quân Nam Hán (năm 938) và chống Tổng (năm 981), đã cho đóng cọc gỗ nhằm cản phá đội hình, chặn đường tháo chạy của thuyền chiến địch, bao vây và tiêu diệt triệt để quân xâm lược. Trận địa quyết chiến với bãi cọc ngầm chi phát huy được tác dụng khi nước triều xuống, nên nó đòi hỏi người chỉ huy điều hành trận chiến đấu phải biết lợi dụng chế độ thủy triều với cả một nghệ thuật dẫn dắt thuyền giặc vào trận địa đúng lúc, đúng chỗ. Ở đây, yếu tố không gian và thời gian kết hợp chặt chẽ với nhau, trận đánh phải bắt đầu và kết thúc một cách chính xác vào thời điểm có lợi nhất để tận dụng chế độ thủy triều và phát huy được hết tác dụng của bãi cọc ngầm. Tài năng xuất chúng của Trần Quốc Tuấn và Bộ tham mưu kháng chiến là đã hoàn toàn cô lập đạo quân thủy của Ô Mã Nhi với đạo quân bộ, rồi dần dần điều động nó từng bước vào đúng điểm quyết chiến đã định và đúng thời gian đã xác định (từ mờ sáng đến trưa ngày 9 tháng 4 lúc nước triều rút mạnh). Do vậy mà hiệu suất chiến đấu càng cao.

Trận Bạch Đằng năm 1288 là trận đánh mai phục kết hợp với vận động tiến công quy mô lớn nhằm bao vây, tiêu diệt gọn đoàn binh thuyền đông đến hàng mấy trăm chiếc với hàng vạn quân địch. Trong trận chiến đấu này, dĩ nhiên thủy bình giữ vai trò chủ yếu. Là một dân tộc có lịch sử dựng nước và giữ nước lâu đời trên một lãnh thổ có nhiều sông biển, ao hồ, nên nhân dân ta quen thuộc với nghề sông nước. Quân đội Đại Việt có truyền thống giỏi thủy chiến. Thuyền chiến của ta có thể không lớn và chắc như thuyền địch, nhưng thủy binh của ta lại quen thuộc với sông nước quê hương, có tinh thần chiến đấu quả cảm và lối đánh cơ động, lợi hại theo phương châm “đĩ đoản chế trường . Trần Quốc Tuấn đã nêu rõ: Lấy đoàn binh thắng trường trận là việc thường của binh pháp. Đoản binh là chỉ bộ binh của ta, một đội quân với số lượng không nhiều nhưng được huấn luyện tinh nhuệ, biên chế gọn nhẹ là cái mạnh của ta. Kỵ binh và quân đông, sức cơ động nhanh là cái mạnh của địch. Nhưng khi trường trận bị dàn mỏng ra, bị phân tán, đứt quãng, không được tiếp tế đầy đủ, không ứng cứu được nhau và lâm vào tử địa, do địa hình không phát huy được thì trở thành yếu, dễ bị công kích và tan vỡ. Như trong trận Đông Bộ Đầu (năm 1258), trận chiến đấu diễn ra ban đêm, quân địch dày đặc nhưng không kịp lên ngựa, bị những đoàn binh nhẹ nhàng mang vũ khí ngắn của ta xông vào chém giết, đã hỗn loạn và tan tác. Hoặc trong trận thủy chiến trên sông Bạch Đằng này, một đoàn dài thuyền lớn, nặng nề chậm chạp của địch bị những thuyền nhẹ của ta từ những ngách sông xông ra đón đánh, đã không xoay sở chạy kịp, đâm vào cọc nhọn bị chìm và bị tiêu diệt. Rõ ràng dĩ đoản chế trường là một sáng tạo sâu sắc của ta dùng để chống lại một kẻ địch đông đảo và trang bị mạnh hơn mình. Sáng tạo này cho tới nay vẫn giữ nguyên giá trị. Điểm nổi bật là trận thủy chiến trên sông Bạch Đằng có sự phối hợp chặt chẽ giữa quân thùy và quân bộ, giữa quân chủ lực với quân địa phương và dân binh, giữa đánh thủy và đánh bộ. Trần Quốc Tuấn đã vận dụng cách đánh tiến công kiên quyết, kết hợp nhiều lối đánh phong phú, đa dạng nhằm phát huy tổng hợp tất cả thế mạnh của chiến tranh nhân dân yêu nước, của truyền thống thủy chiến, của điều kiện thiên nhiên để giành thắng lợi trọn vẹn và triệt để nhất. Các lực lượng tham chiến đã hiệp đồng chặt chẽ với nhau cả về không gian và thời gian, đã sử dụng những lối đánh truyền thống một cách sáng tạo, đó là chiến thuật tiến công địch trên sông và trên bộ, nghi binh kiềm chế, giữ vững điểm cao, từng bước dẫn dắt quân địch, kết hợp đánh chặn phía trước, phía sau và các mũi bên sườn, đánh dồn địch vào cửa sông nhỏ bên tả ngạn, đúng chỗ bố trí các trận địa bãi cọc, hiểm hóc, dùng đòn hỏa công thiêu cháy đoàn thuyền giặc khi chúng vướng cọc... Tất cả các hình thức chiến thuật, các lối đánh đó đều phát huy được tác dụng lợi hại của nó. Chiến thắng Bạch Đằng năm 1288 là sự thể hiện tập trung những sáng tạo về nghệ thuật quân sự của Hưng Đạo Vương Trần Quốc Tuấn và quân dân ta thời Trần, biết phát huy cao độ nội lực, tận dụng mọi điều kiện khách quan thuận lợi, biết tạo ra và lợi dụng chỗ yếu và sai lầm của địch, sáng tạo ra cách đánh hay, có sự chỉ đạo chiến lược sắc bén, chọn mục tiêu và thời cơ thuận lợi đánh những đòn hiểm, đòn đau, đưa cuộc chiến đấu đến toàn thắng. Tài thao lược của Hưng Đạo Vương Trần Quốc Tuấn, vị anh hùng kiệt xuất, nhà chiến lược lỗi lạc của dân tộc ta và các tướng lĩnh tài ba, kết hợp với sức mạnh chiến đấu của toàn quân, toàn dân ta thời Trần đã tạo nên chiến thẳng Bạch Đằng lịch sử. Hòa trong võ công hiển hách ba lần đánh bại quân Nguyên - Mông của dân tộc ta, trận Bạch Đằng nổi lên như một kiểu mẫu của nghệ thuật “dùng đoản binh đánh trường trận và là đỉnh cao chói lọi của sức mạnh và nghệ thuật quân sự Việt Nam thời đó. Trận đánh tiêu diệt trên sông Bạch Đằng năm 1288 là một mẫu mực về mọi phương diện: chuẩn bị chu đáo, tỉ mỉ, giữ bí mật cao độ, tính toán thời gian chuẩn xác mưu kế tài tình tiến công mãnh liệt. Trận đánh trên bộ cũng là kết quả tất yếu của thế bố trí chủ động, không kẽ hở. Trên đường rút chạy, địch liên tục bị đánh chặn phía trước, truy kích phía sau. Cả một đoàn quân lớn tan tác, không ứng cứu được nhau, lần lượt bị tiêu diệt và bắt sống, chỉ còn một nhóm nhỏ chạy thoát về bên kia biên giới. Cuộc kháng chiến lần thứ ba chống quân Nguyên - Mông thắng lợi oanh liệt. Ý chí xâm lược của địch hoàn toàn bị bẻ gãy. Hốt Tất Liệt, hoàng đế nhà Nguyên kiêu ngạo, hiếu chiến buộc phải thừa nhận sự tồn tại của nước Đại Việt. Nền độc lập dân tộc và bờ cõi của nước ta được giữ vững.', 'TEXT', '2026-06-05 05:22:27.18451', '2026-06-05 05:22:27.18449', null, 'DRAFT') ON CONFLICT ("doc_id") DO NOTHING;

